    /** Identifies Craftics' own max-HP modifier so it can be replaced without touching
     *  any other mod's health bonuses. */
    private static final net.minecraft.util.Identifier HP_BONUS_MODIFIER_ID =
        net.minecraft.util.Identifier.of(CrafticsMod.MOD_ID, "hp_bonus");

    private static GridPos adaptSpawnToArena(GridPos originalPos, LevelDefinition levelDef, GridArena arena) {
        int mappedX = scaleGridCoordinate(originalPos.x(), levelDef.getWidth(), arena.getWidth());
        int mappedZ = scaleGridCoordinate(originalPos.z(), levelDef.getHeight(), arena.getHeight());
        return new GridPos(mappedX, mappedZ);
    }

    private static int scaleGridCoordinate(int value, int sourceSize, int targetSize) {
        if (targetSize <= 1) return 0;
        if (sourceSize <= 1) return Math.min(targetSize - 1, targetSize / 2);

        double ratio = (double) value / (double) (sourceSize - 1);
        int mapped = (int) Math.round(ratio * (targetSize - 1));
        return Math.max(0, Math.min(targetSize - 1, mapped));
    }

    private static GridPos findNearestValidSpawn(GridArena arena, GridPos desiredPos, int entitySize) {
        return findNearestValidSpawn(arena, desiredPos, entitySize, entitySize, false);
    }

    private static boolean canPlaceSpawnAt(GridArena arena, GridPos origin, int entitySize) {
        return canPlaceSpawnAt(arena, origin, entitySize, entitySize, false);
    }

    private static boolean canPlaceSpawnAt(GridArena arena, GridPos origin, int sizeX, int sizeZ, boolean aquatic) {
        for (GridPos tilePos : GridArena.getOccupiedTiles(origin, sizeX, sizeZ)) {
            if (!arena.isInBounds(tilePos)) return false;

            GridTile tile = arena.getTile(tilePos);
            if (tile == null) return false;
            if (aquatic) {
                // Only spawn aquatic mobs on shallow water -deep water is a hazard
                if (tile.getType() != com.crackedgames.craftics.core.TileType.WATER) return false;
            } else {
                if (!tile.isSafeForSpawn()) return false;
            }
            if (arena.isOccupied(tilePos)) return false;
        }

        return true;
    }

    private static GridPos findNearestValidSpawn(GridArena arena, GridPos desiredPos, int sizeX, int sizeZ, boolean aquatic) {
        GridPos bestPos = null;
        int bestDistance = Integer.MAX_VALUE;

        for (int x = 0; x <= arena.getWidth() - sizeX; x++) {
            for (int z = 0; z <= arena.getHeight() - sizeZ; z++) {
                GridPos candidate = new GridPos(x, z);
                if (!canPlaceSpawnAt(arena, candidate, sizeX, sizeZ, aquatic)) continue;

                int distance = candidate.manhattanDistance(desiredPos);
                if (distance < bestDistance) {
                    bestDistance = distance;
                    bestPos = candidate;
                }
            }
        }

        return bestPos;
    }

    /**
     * Find the nearest valid spawn tile that is also reachable by the player.
     * Prevents enemies from spawning on islands the player can't reach.
     */
    private static GridPos findNearestReachableSpawn(GridArena arena, GridPos desiredPos,
                                                      int sizeX, int sizeZ, java.util.Set<GridPos> reachable) {
        GridPos bestPos = null;
        int bestDistance = Integer.MAX_VALUE;

        for (int x = 0; x <= arena.getWidth() - sizeX; x++) {
            for (int z = 0; z <= arena.getHeight() - sizeZ; z++) {
                GridPos candidate = new GridPos(x, z);
                if (!canPlaceSpawnAt(arena, candidate, sizeX, sizeZ, false)) continue;
                if (!reachable.contains(candidate)) continue;

                int distance = candidate.manhattanDistance(desiredPos);
                if (distance < bestDistance) {
                    bestDistance = distance;
                    bestPos = candidate;
                }
            }
        }

        return bestPos;
    }

    public static GridPos findNearestWalkableUnreserved(GridArena arena, GridPos desiredPos, java.util.Set<GridPos> reserved) {
        GridPos bestFree = null;
        int bestFreeDistance = Integer.MAX_VALUE;
        GridPos bestOccupied = null;
        int bestOccupiedDistance = Integer.MAX_VALUE;

        for (int x = 0; x < arena.getWidth(); x++) {
            for (int z = 0; z < arena.getHeight(); z++) {
                GridPos candidate = new GridPos(x, z);
                if (reserved.contains(candidate)) continue;
                GridTile tile = arena.getTile(candidate);
                if (tile == null || !tile.isWalkable()) continue;

                int distance = candidate.manhattanDistance(desiredPos);
                // Whoever already stands here counts. The party is positioned AFTER
                // startCombat has spawned the level's enemies, so a search that only asked
                // whether a tile was walkable handed non-leader members a tile a mob was
                // already standing on - the reported "enemies spawn inside me", which only
                // ever happened to the members, never to the leader whose start tile the
                // enemy placement had reserved.
                if (arena.isOccupied(candidate)) {
                    if (distance < bestOccupiedDistance) {
                        bestOccupiedDistance = distance;
                        bestOccupied = candidate;
                    }
                    continue;
                }
                if (distance < bestFreeDistance) {
                    bestFreeDistance = distance;
                    bestFree = candidate;
                }
            }
        }

        // An occupied tile only when the arena has no free one at all: standing on a mob
        // beats being left off the grid entirely.
        return bestFree != null ? bestFree : bestOccupied;
    }

    /** True if there's a non-air block within 3 blocks below {@code standPos} -- i.e. the
     *  player will land on something instead of dropping into a void/pit. Used to keep
     *  party members off floorless tiles in schematic arenas (trial chambers), where the
     *  grid can mark a real gap "walkable" even though the world has no floor under it. */
    private static boolean hasSolidFloorBelow(ServerWorld world, BlockPos standPos) {
        // Starts at down(1), NOT down(0). standPos is the block the player stands IN, so a
        // block there is something in the way - a torch, a slab, a cobweb, one of the
        // block-backed objects like a hive or a grave - and never floor. Counting it meant
        // any prop sitting over an open pit reported the tile as floored, which is one of
        // the ways a member could be placed on a hole and drop straight through it.
        for (int dy = 1; dy <= FLOOR_PROBE_DEPTH; dy++) {
            if (!world.getBlockState(standPos.down(dy)).isAir()) return true;
        }
        return false;
    }

    /**
     * How far below a tile to look for something to land on.
     *
     * <p>Was 3, which is shallower than a trial chamber's pits: a gap deeper than three
     * blocks read as "no floor here" only by accident, and a gap with a ledge at four read
     * as floored when the player would still fall past it. Six covers the authored drops
     * without being so deep that a genuine void reads as solid.
     */
    private static final int FLOOR_PROBE_DEPTH = 6;

    /** Like {@link #findNearestWalkableUnreserved} but ALSO requires a real floor under the
     *  tile, so a player is never dropped into a trial-chamber pit. Falls back to plain
     *  walkability only if no floored tile exists at all (degenerate arena).
     *
     *  <p>Public because raid arenas need it just as much: RaidBossInstance builds its
     *  arena inside a VoidChunkGenerator dimension, where a floorless "walkable" tile is
     *  not a pit with a bottom but open void. */
    public static GridPos findNearestSafeSpawn(ServerWorld world, GridArena arena,
                                               GridPos desired, java.util.Set<GridPos> reserved) {
        GridPos bestFloored = null; int bestFlDist = Integer.MAX_VALUE;
        GridPos bestWalkable = null; int bestWkDist = Integer.MAX_VALUE;
        // Same tiles, but a mob is standing on them. Kept only as a last resort, for the
        // degenerate arena where every free tile is a pit or does not exist.
        GridPos takenFloored = null; int takenFlDist = Integer.MAX_VALUE;
        GridPos takenWalkable = null; int takenWkDist = Integer.MAX_VALUE;
        for (int x = 0; x < arena.getWidth(); x++) {
            for (int z = 0; z < arena.getHeight(); z++) {
                GridPos c = new GridPos(x, z);
                if (reserved.contains(c)) continue;
                GridTile tile = arena.getTile(c);
                if (tile == null || !tile.isWalkable()) continue;
                int dist = c.manhattanDistance(desired);
                boolean floored = hasSolidFloorBelow(world, arena.gridToBlockPos(c));
                // Enemies are already on the grid by the time the party is positioned, so
                // an occupied tile must lose to any free one - otherwise a member is dropped
                // inside a mob.
                if (arena.isOccupied(c)) {
                    if (dist < takenWkDist) { takenWkDist = dist; takenWalkable = c; }
                    if (floored && dist < takenFlDist) { takenFlDist = dist; takenFloored = c; }
                    continue;
                }
                if (dist < bestWkDist) { bestWkDist = dist; bestWalkable = c; }
                if (floored && dist < bestFlDist) { bestFlDist = dist; bestFloored = c; }
            }
        }
        if (bestFloored != null) return bestFloored;
        // Floor outranks everything below it, including being free. Sharing a tile with a
        // mob is survivable and self-corrects the moment either of them moves; a floorless
        // tile is a death pit, and this method exists precisely to keep players out of one.
        // The old order preferred a FREE floorless tile over an OCCUPIED floored one, so a
        // busy arena could hand a party member a hole to stand on.
        if (takenFloored != null) return takenFloored;
        // Nothing floored anywhere. Deliberately NOT falling back to a floorless tile: that
        // fallback is what "I immediately fell in the void pit" looks like from the player's
        // side. Null sends the caller to the leader's own tile, which is the one tile that
        // was already vetted, and a warning here makes the situation diagnosable instead of
        // silently lethal - it usually means the arena's blocks are not where we think.
        CrafticsMod.LOGGER.warn(
            "findNearestSafeSpawn: no floored tile anywhere in the {}x{} arena at {} - refusing"
                + " to place a player over a pit; caller falls back to the leader's tile",
            arena.getWidth(), arena.getHeight(), arena.getOrigin());
        return null;
    }

    // ─────────────────────────────────────────────────────────────────────
    // Party spawn layouts
    //
    // Two shapes are supported, alternating by level number to keep coop
    // encounters varied:
    //   • LINE    -members fan out around the leader's start tile along the
    //               X axis (1 step, -1, 2, -2, ...). Compact and predictable,
    //               good for formation-style play.
    //   • CORNERS -members are placed at distinct grid corners far from each
    //               other. Forces the party to split up and approach enemies
    //               from different angles.
    //
    // The LINE layout is used on odd level numbers, CORNERS on even numbers,
    // so a given biome run alternates every level. Solo play reduces to
    // "leader at start grid" under either layout.
    //
    // For CORNERS with party size > 4 we fall back to LINE because there are
    // only four distinct corners -piling multiple members onto each corner
    // defeats the point of the layout.
    // ─────────────────────────────────────────────────────────────────────

    private enum SpawnLayout { LINE, CORNERS }

    /** Decide which spawn layout to use for this level's party transition. */
    private static SpawnLayout pickSpawnLayout(GridArena arena, int memberCount, LevelDefinition def) {
        if (memberCount <= 1) return SpawnLayout.LINE;     // solo: layout is moot
        if (memberCount > 4) return SpawnLayout.LINE;      // not enough corners for 5+
        // Guard against arenas that are too small to meaningfully split: if
        // the grid is narrower than 4 tiles on either axis, corners collapse
        // onto each other and LINE looks better.
        if (arena.getWidth() < 4 || arena.getHeight() < 4) return SpawnLayout.LINE;
        int levelNum = def != null ? def.getLevelNumber() : 0;
        return (levelNum % 2 == 0) ? SpawnLayout.CORNERS : SpawnLayout.LINE;
    }

    /**
     * Produce desired grid positions for each member, in order. Index 0 is
     * always the leader. Returned positions may be out of walkable tiles -
     * the caller runs {@link #findNearestWalkableUnreserved} to snap each
     * desired pos to the nearest valid tile.
     */
    private static List<GridPos> computeDesiredSpawns(SpawnLayout layout,
                                                       GridArena arena,
                                                       GridPos leaderGrid,
                                                       int count) {
        List<GridPos> out = new ArrayList<>(count);
        if (count <= 0) return out;

        // Leader always gets the anchor tile regardless of layout -the arena's
        // player-start tile is the authoritative "combat origin" and shifting
        // it would drag camera framing, enemy spawns, etc. off-center.
        out.add(leaderGrid);
        if (count == 1) return out;

        int w = arena.getWidth();
        int h = arena.getHeight();

        if (layout == SpawnLayout.CORNERS) {
            // The four grid corners (1 tile inset so we don't collide with
            // boundary walls). Rank them by manhattan distance from the
            // leader, descending -farthest first -so member 1 lands at the
            // opposite corner, member 2 at the next farthest, etc.
            GridPos[] corners = new GridPos[] {
                new GridPos(1, 1),
                new GridPos(w - 2, 1),
                new GridPos(1, h - 2),
                new GridPos(w - 2, h - 2),
            };
            // Simple sort: descending by distance from leader.
            java.util.Arrays.sort(corners, (a, b) ->
                Integer.compare(b.manhattanDistance(leaderGrid),
                                a.manhattanDistance(leaderGrid)));
            for (int i = 1; i < count; i++) {
                // Clamp index into corners[] -count is guaranteed ≤ 4 by
                // pickSpawnLayout, but be defensive.
                GridPos c = corners[Math.min(i - 1, corners.length - 1)];
                out.add(c);
            }
            return out;
        }

        // LINE: fan out along X, alternating right/left of the leader.
        // i=1 → +1, i=2 → -1, i=3 → +2, i=4 → -2, ...
        for (int i = 1; i < count; i++) {
            int dx = (i % 2 == 1) ? ((i + 1) / 2) : -((i + 1) / 2);
            int cx = Math.max(0, Math.min(w - 1, leaderGrid.x() + dx));
            int cz = Math.max(0, Math.min(h - 1, leaderGrid.z()));
            out.add(new GridPos(cx, cz));
        }
        return out;
    }

    // Finds a safe block pos for respawn: tries current pos, then start, then any walkable tile
    /**
     * Whether the arena's floor has actually been placed in the world yet.
     *
     * <p>Second line of defence behind {@link #FALL_DEATH_GRACE_TICKS}: a fall-death is only
     * real if there is a floor to have fallen off. On a slow machine the grace window can
     * expire while the arena is still being built (or its chunks are still loading), and
     * without this the player would be killed - or have their totem consumed - for the crime
     * of loading in slowly. Samples the player-start tile, which every arena places.
     */
    private boolean arenaFloorExists() {
        if (arena == null || player == null) return false;
        if (!(player.getEntityWorld() instanceof ServerWorld sw)) return false;
        BlockPos start = arena.getPlayerStartBlockPos();
        if (start == null) return false;
        BlockPos floor = start.down();
        return !sw.getBlockState(floor).getCollisionShape(sw, floor).isEmpty();
    }

    private static BlockPos getSafeArenaBlockPos(GridArena arena) {
        GridPos safe = getSafeArenaGridPos(arena);
        return safe != null ? arena.gridToBlockPos(safe) : arena.getPlayerStartBlockPos();
    }

    /**
     * A walkable tile to put the player on: their current tile if it is still valid, else the
     * arena start, else the first walkable tile anywhere. {@code null} when the arena has no
     * walkable tile at all (the caller falls back to the raw start block).
     *
     * <p>Callers that TELEPORT the player must also
     * {@code arena.setPlayerGridPos(...)} to this position. The block position alone moves the
     * entity while the grid still believes the player occupies the tile they left - which, for
     * a void rescue, meant the arena thought they were standing in the pit they just fell into,
     * so move highlights, attack range, and enemy pathing all read from the wrong tile.
     */
    private static GridPos getSafeArenaGridPos(GridArena arena) {
        GridPos current = arena.getPlayerGridPos();
        GridTile currentTile = arena.getTile(current);
        if (currentTile != null && currentTile.isWalkable()) {
            return current;
        }
        GridPos start = arena.getPlayerStart();
        GridTile startTile = arena.getTile(start);
        if (startTile != null && startTile.isWalkable()) {
            return start;
        }
        for (int x = 0; x < arena.getWidth(); x++) {
            for (int z = 0; z < arena.getHeight(); z++) {
                GridTile tile = arena.getTile(x, z);
                if (tile != null && tile.isWalkable()) {
                    return new GridPos(x, z);
                }
            }
        }
        return null;
    }

