    /**
     * Every tick, enforce the Ender Dragon's world position based on its AI state.
     * The vanilla EnderDragonEntity PhaseManager continuously overrides position,
     * so we must re-apply every tick to win the tug-of-war.
     *
     * Also handles state transitions: adds/removes occupancy tiles and sends
     * messages when the dragon perches or takes off.
     *
     * ATTACKING → parked 100 blocks above arena, not targetable.
     * PERCHING  → forced to arena centre at ground level, visible + targetable.
     */
    private void tickDragonPositionEnforcer() {
        if (player == null || arena == null) return;
        for (CombatEntity e : enemies) {
            if (!e.isAlive() || !e.isBoss()) continue;
            EnemyAI ai = resolveAi(e);
            if (!(ai instanceof com.crackedgames.craftics.combat.ai.DragonAI dragonAi)) continue;
            MobEntity mob = e.getMobEntity();
            if (mob == null) continue;

            BlockPos origin = arena.getOrigin();
            int arenaW = arena.getWidth();
            int arenaH = arena.getHeight();
            double cx = origin.getX() + arenaW / 2.0;
            double cz = origin.getZ() + arenaH / 2.0;

            // Handle state transitions: toggle occupancy tiles + messages
            if (dragonAi.hasStateChanged()) {
                dragonAi.acknowledgeStateChange();
                int bw = 3, bh = 7;
                int ox = (arenaW - bw) / 2;
                int oz = (arenaH - bh) / 2;

                if (dragonAi.getState() == com.crackedgames.craftics.combat.ai.DragonAI.State.PERCHING) {
                    // Re-add occupancy tiles so the dragon is targetable
                    for (int dx = 0; dx < bw; dx++) {
                        for (int dz = 0; dz < bh; dz++) {
                            arena.getOccupants().put(new GridPos(ox + dx, oz + dz), e);
                        }
                    }
                    sendMessage("§5§l\u2726 The Ender Dragon perches! Strike now!");
                    ServerWorld world = (ServerWorld) player.getEntityWorld();
                    world.playSound(null, player.getBlockPos(),
                        net.minecraft.sound.SoundEvents.ENTITY_ENDER_DRAGON_GROWL,
                        net.minecraft.sound.SoundCategory.HOSTILE, 2.0f, 0.7f);
                } else {
                    // Remove occupancy tiles so the dragon is NOT targetable
                    for (int dx = 0; dx < bw; dx++) {
                        for (int dz = 0; dz < bh; dz++) {
                            GridPos slot = new GridPos(ox + dx, oz + dz);
                            if (arena.getOccupant(slot) == e) {
                                arena.getOccupants().remove(slot);
                            }
                        }
                    }
                    sendMessage("§8§l\u2726 The Ender Dragon takes flight!");
                    ServerWorld world = (ServerWorld) player.getEntityWorld();
                    world.playSound(null, player.getBlockPos(),
                        net.minecraft.sound.SoundEvents.ENTITY_ENDER_DRAGON_FLAP,
                        net.minecraft.sound.SoundCategory.HOSTILE, 2.0f, 0.8f);
                }
                sendSync();
            }

            // Position enforcement every tick.
            // Server-only mixin suppresses tickMovement() so vanilla PhaseManager
            // can't fight our position. Client tickMovement() still runs to populate
            // the segment buffer the renderer needs. A client-side renderer mixin
            // checks isInvisible() + isAiDisabled() to skip drawing during ATTACKING.
            if (dragonAi.getState() == com.crackedgames.craftics.combat.ai.DragonAI.State.PERCHING) {
                double bobY = Math.sin(mob.age * 0.05) * 0.3;
                double groundY = origin.getY() + 5.0 + bobY;
                forceDragonPosition(mob, cx, groundY, cz);
                float idleYaw = (mob.age * 0.5f) % 360f;
                mob.setYaw(idleYaw);
                mob.setHeadYaw(idleYaw);
                mob.setSilent(false);
                mob.setInvisible(false);
            } else {
                double hideY = origin.getY() + 100;
                forceDragonPosition(mob, cx, hideY, cz);
                mob.setSilent(true);
                mob.setInvisible(true);
            }
            // Keep PhaseManager in HOVER so vanilla AI never overrides position
            if (mob instanceof net.minecraft.entity.boss.dragon.EnderDragonEntity enforceDragon) {
                enforceDragon.getPhaseManager().setPhase(
                    net.minecraft.entity.boss.dragon.phase.PhaseType.HOVER);
            }
        }
    }

    /**
     * Force the ender dragon AND all its body-part sub-entities to a position.
     * The vanilla EnderDragonEntity has ~8 EnderDragonPart sub-entities (head,
     * neck segments, body, tail, wings) that each have independent positions.
     * If we only set the main entity position, the parts stay at their old
     * coords and the renderer draws the dragon at the wrong place. This method
     * forces everything to the same point.
     */
    private static void forceDragonPosition(MobEntity mob, double x, double y, double z) {
        // requestTeleport flags the entity for a forced position sync to all
        // tracking clients -setPosition alone only updates the server and the
        // client never learns the dragon moved.
        mob.requestTeleport(x, y, z);
        mob.setVelocity(0, 0, 0);
        // Sync body parts -EnderDragonEntity stores them as getBodyParts()
        if (mob instanceof net.minecraft.entity.boss.dragon.EnderDragonEntity dragon) {
            for (net.minecraft.entity.boss.dragon.EnderDragonPart part : dragon.getBodyParts()) {
                part.refreshPositionAndAngles(x, y, z, 0, 0);
                part.setPosition(x, y, z);
            }
        }
    }

    /** Scale baby variant mobs smaller using vanilla SCALE attribute. */
    private static void scaleBabyMob(MobEntity mob) {
        var scaleAttr = mob.getAttributeInstance(SCALE_ATTR);
        if (scaleAttr != null) {
            scaleAttr.setBaseValue(0.7);
        }
    }

    /** Start a dying mob's gradual shrink + death particles. Returns original scale. */
    private float startDeathShrink(MobEntity mob) {
        var scaleAttr = mob.getAttributeInstance(SCALE_ATTR);
        float startScale = scaleAttr != null ? (float) scaleAttr.getBaseValue() : 1.0f;

        // Hurt flash + death sound
        mob.setHealth(0);

        // Initial death poof particles
        if (mob.getWorld() instanceof ServerWorld sw) {
            sw.spawnParticles(net.minecraft.particle.ParticleTypes.POOF,
                mob.getX(), mob.getY() + mob.getHeight() / 2, mob.getZ(),
                10, 0.3, 0.3, 0.3, 0.02);
        }
        return startScale;
    }

    private void tickReacting() {
        // Reuses enemy movement lerp logic, returns to PLAYER_TURN when done
        if (enemyMovePathIndex >= enemyMovePath.size()) {
            enemyLerpInitialized = false;
            currentEnemy = null;
            phase = CombatPhase.PLAYER_TURN;
            return;
        }

        MobEntity mob = currentEnemy.getMobEntity();
        if (mob == null || !mob.isAlive() || mob.isRemoved()) {
            enemyLerpInitialized = false;
            currentEnemy = null;
            phase = CombatPhase.PLAYER_TURN;
            return;
        }

        if (!enemyLerpInitialized) {
            enemyLerpInitialized = true;
            enemyMoveTickCounter = 0;
            enemyLerpStartX = mob.getX();
            enemyLerpStartY = mob.getY();
            enemyLerpStartZ = mob.getZ();

            GridPos next = enemyMovePath.get(enemyMovePathIndex);
            GridPos prev = enemyMovePathIndex == 0 ? currentEnemy.getGridPos() : enemyMovePath.get(enemyMovePathIndex - 1);
            int dx = next.x() - prev.x();
            int dz = next.z() - prev.z();
            float yaw = (float) Math.toDegrees(Math.atan2(-dx, dz));
            if ("minecraft:ghast".equals(currentEnemy.getEntityTypeId())) {
                yaw = snapToCardinalYaw(yaw);
            }
            mob.setYaw(yaw);
            mob.setHeadYaw(yaw);
        }

        enemyMoveTickCounter++;
        GridPos next = enemyMovePath.get(enemyMovePathIndex);
        BlockPos endBlock = arena.gridToBlockPos(next);
        double endX = endBlock.getX() + (currentEnemy != null ? currentEnemy.getSizeX() / 2.0 : 0.5);
        double endY = arena.getEntityY(next, currentEnemy != null && currentEnemy.isFlying());
        double endZ = endBlock.getZ() + (currentEnemy != null ? currentEnemy.getSizeZ() / 2.0 : 0.5);

        int emTicks = getMoveTicks();
        float progress = Math.min(1.0f, (float) enemyMoveTickCounter / emTicks);
        double x = enemyLerpStartX + (endX - enemyLerpStartX) * progress;
        double y = enemyLerpStartY + (endY - enemyLerpStartY) * progress;
        double z = enemyLerpStartZ + (endZ - enemyLerpStartZ) * progress;
        mob.requestTeleport(x, y, z);

        if (enemyMoveTickCounter >= emTicks) {
            arena.moveEntity(currentEnemy, next);
            // Void Walker rift: teleport the enemy if they landed on a portal, then
            // end the reaction so the path doesn't continue from the stale route.
            if (handleEnemyVoidRiftEntry(currentEnemy, next)) {
                enemyLerpInitialized = false;
                currentEnemy = null;
                phase = CombatPhase.PLAYER_TURN;
                return;
            }
            enemyLerpInitialized = false;
            enemyMovePathIndex++;
        }
    }

    /** Apply a combat effect to a specific player's effect set by UUID (party-wide buffs). */
    private void applyEffectToPlayerUuid(java.util.UUID playerUuid, CombatEffects.EffectType type, int turns, int amplifier) {
        CombatEffects fx = playerCombatEffects.computeIfAbsent(playerUuid, k -> new CombatEffects());
        applyPlayerEffectLive(fx, playerUuid, type, turns, amplifier);
    }

    /**
     * Apply an effect to a player's effect set and, if it is that player's turn
     * right now, fold a freshly-granted SPEED/HASTE bonus into the LIVE budget
     * immediately instead of waiting for the next turn-start recompute.
     *
     * <p>{@code apRemaining} and {@code movePointsRemaining} are snapshotted at
     * turn start, so a buff applied mid-turn (an instrument, a quaffed potion,
     * etc.) otherwise wouldn't help until next turn. We top up by the DELTA the
     * effect adds ({@code bonus after - bonus before}), so re-applying the same
     * level adds nothing and a level-up adds only the difference. Only the
     * current acting player on their PLAYER_TURN is topped up; other players'
     * buffs correctly fold in at their own next turn.
     */
    private void applyPlayerEffectLive(CombatEffects fx, java.util.UUID playerUuid,
                                       CombatEffects.EffectType type, int turns, int amplifier) {
        boolean liveActor = phase == CombatPhase.PLAYER_TURN
            && player != null && player.getUuid().equals(playerUuid);

        int hasteBefore = liveActor ? fx.getHasteBonus() : 0;
        int speedBefore = liveActor ? fx.getSpeedBonus() : 0;

        fx.addEffect(type, turns, amplifier);

        if (liveActor) {
            if (type == CombatEffects.EffectType.HASTE) {
                apRemaining += Math.max(0, fx.getHasteBonus() - hasteBefore);
            } else if (type == CombatEffects.EffectType.SPEED) {
                movePointsRemaining += Math.max(0, fx.getSpeedBonus() - speedBefore);
            }
        }
    }

    /**
     * Public entry for non-CombatManager code (potions, goat horns, pottery sherd
     * spells, addon item handlers) to apply a buff/effect to the CURRENT player
     * with the same live AP/movement top-up the internal paths use. Prefer this
     * over {@code getCombatEffects().addEffect(...)} for player-side SPEED/HASTE
     * so the buff takes effect this turn, not next. No-op-safe if combat has no
     * active player.
     */
    public void applyPlayerEffectLive(CombatEffects.EffectType type, int turns, int amplifier) {
        applyPlayerEffectLive(combatEffects, player != null ? player.getUuid() : null, type, turns, amplifier);
    }

    /**
     * Elytra launch: rise straight up out of view from the current tile, then fall onto
     * {@code target}. The grid position changes once, at the apex, so nothing observes the
     * player mid-flight in a stale tile. Input is blocked for the flight.
     *
     * <p>Public because {@code ItemUseHandler} drives the Elytra ability but cannot reach
     * {@code activeWalkers} / {@code spellAnimCooldown} / the position broadcast, which are all
     * private here - the same reason {@link #applyPlayerEffectLive} exists. The caller is
     * responsible for validating that {@code target} is a legal landing tile.
     */
    public void flyPlayerTo(GridPos target) {
        if (player == null || arena == null || target == null) return;

        final ServerPlayerEntity fp = player;
        EntityWalker.Mover mover = (x, y, z, yaw) -> {
            //? if <=1.21.4 {
            fp.prevX = fp.getX();
            fp.prevY = fp.getY();
            fp.prevZ = fp.getZ();
            //?} else {
            /*fp.lastX = fp.getX();
            fp.lastY = fp.getY();
            fp.lastZ = fp.getZ();
            *///?}
            fp.setPosition(x, y, z);
            fp.networkHandler.requestTeleport(x, y, z, fp.getYaw(), fp.getPitch());
            broadcastPlayerPositionToOthers(fp);
        };

        double startX = fp.getX(), startY = fp.getY(), startZ = fp.getZ();
        double apexY = startY + ELYTRA_FLIGHT_HEIGHT;

        BlockPos destBlock = arena.gridToBlockPos(target);
        double destX = destBlock.getX() + 0.5;
        double destZ = destBlock.getZ() + 0.5;
        double destY = arena.getEntityY(target, false);

        // Fall leg: starts above the destination, lands on it. Queued by the rise's completion.
        Runnable startFall = () -> {
            // The grid tile changes exactly once, at the apex, while the player is out of view.
            arena.setPlayerGridPos(target);
            activeWalkers.add(new EntityWalker(mover,
                destX, apexY, destZ, destX, destY, destZ, ELYTRA_FALL_TICKS,
                () -> {
                    fp.setOnGround(true);
                    fp.fallDistance = 0;
                    sendSync();
                    refreshHighlights();
                }));
        };

        activeWalkers.add(new EntityWalker(mover,
            startX, startY, startZ, startX, apexY, startZ, ELYTRA_RISE_TICKS, startFall));

        // Hold input until both legs finish (+2 ticks of slack, matching the sherd-animation gate).
        spellAnimCooldown = ELYTRA_RISE_TICKS + ELYTRA_FALL_TICKS + 2;
    }

    /**
     * Run {@code buffApplication} (which may apply SPEED/HASTE to the current
     * player's {@code combatEffects}) and top up the live AP/movement budget by
     * whatever bonus it newly granted. For external buff helpers (goat horns,
     * pottery sherd spells) that apply to {@code combatEffects} directly and
     * don't return the effect type/level, so we measure the delta around the call.
     * Only tops up on the player's own turn.
     */
    private void rebudgetAroundBuff(Runnable buffApplication) {
        boolean liveActor = phase == CombatPhase.PLAYER_TURN && player != null;
        int hasteBefore = liveActor ? combatEffects.getHasteBonus() : 0;
        int speedBefore = liveActor ? combatEffects.getSpeedBonus() : 0;
        buffApplication.run();
        if (liveActor) {
            apRemaining += Math.max(0, combatEffects.getHasteBonus() - hasteBefore);
            movePointsRemaining += Math.max(0, combatEffects.getSpeedBonus() - speedBefore);
        }
    }

    /** Remove all debuffs from an ally entity (Keyboard cleanse). */
    private void cleanseAlly(CombatEntity target) {
        if (target == null) return;
        target.clearDebuffs();
    }

    /** True if the held item is an instrument and the performance was resolved (consumes the click). */
    private boolean tryHandleInstrument(GridPos clicked) {
        if (player == null) return false;
        net.minecraft.item.Item held = player.getMainHandStack().getItem();
        com.crackedgames.craftics.compat.instruments.InstrumentDef def =
            com.crackedgames.craftics.compat.instruments.InstrumentsCompat.defFor(held);
        if (def == null) return false;
        int cost = def.apCost();
        if (apRemaining < cost) {
            sendMessage("§cNot enough AP to play the " + def.itemPath() + ".");
            return true; // consume the click; not enough AP
        }
        apRemaining -= cost;

        GridPos center = gridPosOf(player);
        GridPos aim = clicked != null ? clicked : center;
        java.util.List<GridPos> tiles =
            (def.shape() == com.crackedgames.craftics.compat.instruments.InstrumentDef.Shape.FULL_ARENA)
                ? com.crackedgames.craftics.combat.AoeShapes.allTiles(arena)
                : com.crackedgames.craftics.compat.instruments.InstrumentPerformance.shapeTiles(def, center, aim, combatRng.nextLong());

        if (def.role() == com.crackedgames.craftics.compat.instruments.InstrumentDef.Role.ATTACK) {
            resolveInstrumentAttack(def, center, tiles);
        } else {
            resolveInstrumentSupport(def, center, tiles);
        }

        // VFX: spawn the instrument's note particles on the actual affected tiles.
        playInstrumentVfx(def, center, tiles);

        // Re-check the win condition the same way every other damage path does.
        // resolveInstrumentAttack credits and despawns the killed enemy via
        // checkAndHandleDeath, but that helper deliberately never ends the fight,
        // so without this an instrument landing the final blow soft-locks the level.
        if (!anyEnemyBlockingVictory()) {
            handleVictory();
            return true;
        }

        sendSync();
        return true;
    }

    private static final int INSTRUMENT_FLAT_HEAL = 6;   // FLAT_HEAL signature (Vintage Lyre)
    private static final int INSTRUMENT_ARENA_HEAL = 4;  // ARENA_HEAL signature (Violin)

    /**
     * A mob performs a held instrument. ATTACK: aim the shape at the player, apply the
     * def's debuff effects + baseDamage if the player is in the shape. SUPPORT: aim at
     * the performer's own tile, buff the living enemy-side entities caught in the shape
     * (the mob's "allies"). Returns false when there's no valid target so the caller
     * falls back to the normal action. Mirrors resolveInstrumentAttack/Support with the
     * target side flipped (the mob is the caster, the player is the enemy).
     */
    private boolean resolveMobInstrument(CombatEntity performer,
            com.crackedgames.craftics.compat.instruments.InstrumentDef def) {
        if (def == null || arena == null || player == null) return false;
        GridPos center = performer.getGridPos();
        if (center == null) return false;
        boolean fullArena = def.shape()
            == com.crackedgames.craftics.compat.instruments.InstrumentDef.Shape.FULL_ARENA;

        if (def.role() == com.crackedgames.craftics.compat.instruments.InstrumentDef.Role.ATTACK) {
            GridPos aim = arena.getPlayerGridPos();
            java.util.List<GridPos> tiles = fullArena
                ? com.crackedgames.craftics.combat.AoeShapes.allTiles(arena)
                : com.crackedgames.craftics.compat.instruments.InstrumentPerformance
                    .shapeTiles(def, center, aim, combatRng.nextLong());
            if (!tiles.contains(aim)) return false; // player not caught in the shape
            int dealt = def.baseDamage() > 0 ? damagePlayer(def.baseDamage(), performer) : 0;
            for (var fx : def.effects()) {
                if (fx.type() != null) addEffectHooked(fx.type(), fx.turns(), fx.amplifier());
            }
            playInstrumentVfx(def, center, tiles);
            sendMessage("§5  " + performer.getDisplayName() + " plays a haunting tune"
                + (dealt > 0 ? " for " + dealt + " damage!" : "!"));
            return true;
        } else {
            java.util.List<GridPos> tiles = fullArena
                ? com.crackedgames.craftics.combat.AoeShapes.allTiles(arena)
                : com.crackedgames.craftics.compat.instruments.InstrumentPerformance
                    .shapeTiles(def, center, center, combatRng.nextLong());
            java.util.List<CombatEntity> allies =
                com.crackedgames.craftics.combat.AoeShapes.enemiesOn(arena, tiles, null);
            allies.removeIf(e -> e == performer || !e.isAlive());
            if (allies.isEmpty()) return false; // nothing to buff -> fall back to melee
            for (CombatEntity ally : allies) {
                for (var fx : def.effects()) {
                    if (fx.type() != null) applyInstrumentEffect(ally, fx.type(), fx.turns(), fx.amplifier());
                }
            }
            playInstrumentVfx(def, center, tiles);
            sendMessage("§5  " + performer.getDisplayName() + " rallies its allies with a song!");
            return true;
        }
    }

    private void resolveInstrumentAttack(com.crackedgames.craftics.compat.instruments.InstrumentDef def,
                                         GridPos center, java.util.List<GridPos> tiles) {
        java.util.List<CombatEntity> hit =
            com.crackedgames.craftics.combat.AoeShapes.enemiesOn(arena, tiles, null);
        for (CombatEntity e : hit) {
            applySpecialUtilityDamage(e, def.baseDamage());
            for (var fx : def.effects()) {
                if (fx.type() != null) applyInstrumentEffect(e, fx.type(), fx.turns(), fx.amplifier());
            }
        }
        if (def.signature() == com.crackedgames.craftics.compat.instruments.InstrumentDef.Signature.KNOCKBACK) {
            for (CombatEntity e : hit) {
                if (!e.isAlive()) continue;
                if (e.hasSlowFalling()) continue;
                int dx = Integer.signum(e.getGridPos().x() - center.x());
                int dz = Integer.signum(e.getGridPos().z() - center.z());
                if (dx == 0 && dz == 0) dx = 1;
                knockEnemyBack(e, dx, dz, 1);
            }
        }
        for (CombatEntity e : hit) checkAndHandleDeath(e);
        sendTileFlash(tiles, FLASH_DAMAGE_COLOR, 20);
    }

    private void resolveInstrumentSupport(com.crackedgames.craftics.compat.instruments.InstrumentDef def,
                                          GridPos center, java.util.List<GridPos> tiles) {
        // AI allies on the tiles
        for (CombatEntity ally : com.crackedgames.craftics.combat.AoeShapes.alliesOn(arena, tiles)) {
            applyInstrumentBuffsToAlly(def, ally);
        }
        // The casting player (always in a self-centered shape)
        applyInstrumentBuffsToPlayerUuid(def, player.getUuid());
        if (def.signature() == com.crackedgames.craftics.compat.instruments.InstrumentDef.Signature.FLAT_HEAL
            || def.signature() == com.crackedgames.craftics.compat.instruments.InstrumentDef.Signature.ARENA_HEAL) {
            int healAmt = def.signature() == com.crackedgames.craftics.compat.instruments.InstrumentDef.Signature.FLAT_HEAL ? INSTRUMENT_FLAT_HEAL : INSTRUMENT_ARENA_HEAL;
            player.setHealth(Math.min(player.getMaxHealth(), player.getHealth() + healAmt));
        }
        if (def.signature() == com.crackedgames.craftics.compat.instruments.InstrumentDef.Signature.CLEANSE) {
            combatEffects.clearDebuffs();
        }
        // Teammate players standing in the shape
        java.util.Set<GridPos> tileSet = new java.util.HashSet<>(tiles);
        for (net.minecraft.server.network.ServerPlayerEntity p : partyPlayers) {
            if (p == player) continue;
            GridPos pg = gridPosOf(p);
            if (pg != null && tileSet.contains(pg)) applyInstrumentBuffsToPlayerUuid(def, p.getUuid());
        }
        sendTileFlash(tiles, FLASH_EFFECT_COLOR, 20);
    }

    private void applyInstrumentBuffsToAlly(com.crackedgames.craftics.compat.instruments.InstrumentDef def, CombatEntity ally) {
        for (var fx : def.effects()) {
            if (fx.type() != null) applyInstrumentEffect(ally, fx.type(), fx.turns(), fx.amplifier());
        }
        switch (def.signature()) {
            case FLAT_HEAL -> ally.heal(INSTRUMENT_FLAT_HEAL);
            case ARENA_HEAL -> ally.heal(INSTRUMENT_ARENA_HEAL);
            case CLEANSE -> cleanseAlly(ally);
            default -> {}
        }
    }

    private void applyInstrumentBuffsToPlayerUuid(com.crackedgames.craftics.compat.instruments.InstrumentDef def, java.util.UUID uuid) {
        for (var fx : def.effects()) {
            if (fx.type() != null) applyEffectToPlayerUuid(uuid, fx.type(), fx.turns(), fx.amplifier());
        }
        // The player-side flat heal is applied to the caster in resolveInstrumentSupport; teammate heals:
        if (!uuid.equals(player.getUuid())) {
            switch (def.signature()) {
                case FLAT_HEAL -> healPlayerByUuid(uuid, INSTRUMENT_FLAT_HEAL);
                case ARENA_HEAL -> healPlayerByUuid(uuid, INSTRUMENT_ARENA_HEAL);
                case CLEANSE -> {
                    com.crackedgames.craftics.combat.CombatEffects fx = playerCombatEffects.get(uuid);
                    if (fx != null) fx.clearDebuffs();
                }
                default -> {}
            }
        }
    }

    /** Heal a party player by UUID (no-op if not online in this combat). */
    private void healPlayerByUuid(java.util.UUID uuid, int amount) {
        for (net.minecraft.server.network.ServerPlayerEntity p : partyPlayers) {
            if (p.getUuid().equals(uuid)) {
                p.setHealth(Math.min(p.getMaxHealth(), p.getHealth() + amount));
                return;
            }
        }
    }

    /**
     * Apply a debuff/buff to a CombatEntity. Mirrors {@code UsableItemContextImpl.applyEffect}
     * (CombatEffectContext does not expose a CombatEntity overload, so the switch is duplicated
     * here so handleInstrument can route effects without going through the inner class).
     */
    private void applyInstrumentEffect(CombatEntity target, CombatEffects.EffectType type, int turns, int amplifier) {
        switch (type) {
            case POISON -> target.stackPoison(turns, amplifier);
            case WITHER -> target.stackWither(turns, amplifier);
            case BURNING -> target.stackBurning(turns, amplifier);
            case SOAKED -> target.stackSoaked(turns, amplifier);
            case SLOWNESS -> target.stackSlowness(turns, amplifier);
            case CONFUSION -> {
                // Nerf: confusion is never guaranteed - roll confusionApplyChance.
                if (com.crackedgames.craftics.combat.ConfusionLogic.rollHits(
                        Math.random(), CrafticsMod.CONFIG.confusionApplyChance())) {
                    target.stackConfusion(turns, amplifier);
                }
            }
            case WEAKNESS -> {
                target.setAttackPenalty(2 * (amplifier + 1));
                target.setAttackPenaltyTurns(turns);
            }
            case BLEEDING -> target.stackBleed(amplifier + 1);
            case REGENERATION -> target.applyRegeneration(turns, amplifier);
            case ABSORPTION -> target.applyAbsorption(4 * (amplifier + 1), turns);
            case SLOW_FALLING -> target.applySlowFalling(turns);
            case STRENGTH -> target.applyAttackBuff(3 * (amplifier + 1), turns);
            case SPEED -> target.applySpeedBuff(2 * (amplifier + 1), turns);
            case RESISTANCE -> target.applyResistance(amplifier + 1, turns);
            default -> { /* effect type not applicable to combat entities */ }
        }
    }

    private void playInstrumentVfx(com.crackedgames.craftics.compat.instruments.InstrumentDef def,
                                   GridPos center, java.util.List<GridPos> tiles) {
        if (player == null) return;
        try {
            com.crackedgames.craftics.vfx.VfxDescriptor desc =
                com.crackedgames.craftics.vfx.instruments.InstrumentVfx.describe(def, tiles);
            net.minecraft.util.math.BlockPos origin = player.getBlockPos();
            com.crackedgames.craftics.vfx.VfxContext ctx =
                com.crackedgames.craftics.vfx.VfxContext.ofEntities(
                    player.getId(), -1, origin, origin, 0f, false, arena);
            com.crackedgames.craftics.vfx.Vfx.play(
                (net.minecraft.server.world.ServerWorld) player.getEntityWorld(), desc, ctx);
        } catch (Exception e) {
            CrafticsMod.LOGGER.debug("[Instruments] VFX failed for {}: {}", def.itemPath(), e.toString());
        }
    }

    /**
     * Open a crafting station's UI for the acting player, spending {@link
     * CraftingStations#AP_COST} AP. The screen is bound to the player's own tile,
     * so any items left in the station's working slots on close drop at their feet
     * and are re-collected -nothing is lost. No block is placed; the held station
     * item stays in the player's hand.
     */
    private void handleStationOpen(CraftingStations.Station station) {
        if (player == null || arena == null) return;
        if (apRemaining < CraftingStations.AP_COST) {
            sendMessage("§cNeed " + CraftingStations.AP_COST + " AP to use the "
                + station.label() + "! (have " + apRemaining + ")");
            return;
        }
        if (!(player.getEntityWorld() instanceof ServerWorld world)) return;
        // Virtual context (not create(...) and not EMPTY): the station is opened from
        // a held item on an empty combat tile, so there is no real station block.
        //  - create(world, pos) would make canUse() fail every tick (no block at pos)
        //    and the game snaps the screen shut ("opens then instantly closes").
        //  - EMPTY is the client stub whose run() is a no-op, so recipe/enchant/grind
        //    world logic never fires and crafting does nothing (a log made no planks).
        // CraftingStations.virtualContext runs world callbacks against the player's
        // real position (recipes + on-close drops work) but fakes canUse to always
        // pass, so the screen stays open AND crafting works.
        net.minecraft.screen.ScreenHandlerContext ctx =
            CraftingStations.virtualContext(world, player.getBlockPos());
        // Charge only if the screen actually opened (openHandledScreen is empty
        // when the player already has a screen up).
        if (player.openHandledScreen(station.factory(ctx, world, player.getBlockPos())).isEmpty()) return;
        apRemaining -= CraftingStations.AP_COST;
        String extra = "";
        if (station == CraftingStations.Station.ENCHANTING) {
            int power = CombatEnchantmentScreenHandler.carriedBookshelfPower(player.getInventory());
            extra = power > 0
                ? " §7(" + power + " carried bookshelves powering it)"
                : " §7(carry bookshelves to raise the enchant levels)";
            // Vanilla refuses to enchant an item that already carries an enchantment, and
            // it says so only by greying the rows out. Spell it out, or a player who just
            // enchanted their sword thinks the table broke.
            sendMessage("§8The table offers nothing for an already-enchanted item, "
                + "and each offer costs XP levels and lapis.");
        }
        sendMessage("§b✦ " + station.label() + " opened. §7(-" + CraftingStations.AP_COST + " AP)" + extra);
        sendSync();
        refreshHighlights();
    }

    /** True if a campfire has been placed on {@code tile} (see {@code useCampfire}). */
    private boolean isCampfireTile(GridPos tile) {
        return tile != null && "campfire".equals(tileEffects.get(tile));
    }

    /**
     * Cook raw food on a placed campfire for 1 AP. A single action cooks up to
     * {@link ItemUseHandler#CAMPFIRE_COOK_BATCH} items off the held stack - not the
     * whole stack - so a full stack still takes several turns to work through.
     * The player must be standing on the fire or next to it.
     */
    private void handleCampfireCook(ItemStack heldStack, GridPos targetTile) {
        if (player == null || arena == null) return;
        GridPos pPos = arena.getPlayerGridPos();
        int cheby = Math.max(Math.abs(pPos.x() - targetTile.x()), Math.abs(pPos.z() - targetTile.z()));
        if (cheby > 1) {
            sendMessage("§cStand next to the campfire to cook.");
            return;
        }
        if (apRemaining < 1) {
            sendMessage("§cNeed 1 AP to cook! (have " + apRemaining + ")");
            return;
        }
        Item cooked = ItemUseHandler.campfireResult(heldStack.getItem());
        if (cooked == null) return;

        int amount = Math.min(ItemUseHandler.CAMPFIRE_COOK_BATCH, heldStack.getCount());
        String rawName = heldStack.getName().getString();
        heldStack.decrement(amount);
        ItemStack result = new ItemStack(cooked, amount);
        if (!player.getInventory().insertStack(result)) {
            player.dropItem(result, false);
        }
        apRemaining -= 1;

        if (player.getEntityWorld() instanceof ServerWorld world) {
            BlockPos bp = arena.gridToBlockPos(targetTile);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE,
                bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5, 12, 0.2, 0.2, 0.2, 0.01);
            world.playSound(null, bp, net.minecraft.sound.SoundEvents.BLOCK_CAMPFIRE_CRACKLE,
                net.minecraft.sound.SoundCategory.BLOCKS, 1.0f, 1.0f);
        }
        sendMessage("§6✦ Cooked " + amount + "x " + rawName + " §7(-1 AP)");
        sendSync();
        refreshHighlights();
    }

    /**
     * The acting player's Luck progression points, or 0 outside a live world. The single
     * place armor and item procs read Luck from, so they all scale off the same number the
     * weapon abilities do.
     */
    private int luckPointsOf(ServerPlayerEntity member) {
        if (member == null || !(member.getEntityWorld() instanceof ServerWorld world)) return 0;
        return PlayerProgression.get(world).getStats(member).getPoints(PlayerProgression.Stat.LUCK);
    }

    /** The three anvil condition variants, all of which double as a portable bench. */
    private static boolean isAnvilItem(Item item) {
        return item == Items.ANVIL || item == Items.CHIPPED_ANVIL || item == Items.DAMAGED_ANVIL;
    }

    /**
     * Open the vanilla anvil UI for the acting player. Costs the same AP as a crafting
     * station and, like one, neither consumes the anvil nor places a block. Aimed at an
     * enemy the anvil is still a weapon; this is only the empty-tile / own-tile path.
     */
    private void handleAnvilOpen() {
        if (player == null || arena == null) return;
        if (apRemaining < CraftingStations.AP_COST) {
            sendMessage("§cNeed " + CraftingStations.AP_COST + " AP to use the anvil! (have "
                + apRemaining + ")");
            return;
        }
        if (!(player.getEntityWorld() instanceof ServerWorld world)) return;
        net.minecraft.screen.ScreenHandlerContext ctx =
            CraftingStations.virtualContext(world, player.getBlockPos());
        var factory = new net.minecraft.screen.SimpleNamedScreenHandlerFactory(
            (syncId, inv, viewer) -> new net.minecraft.screen.AnvilScreenHandler(syncId, inv, ctx),
            net.minecraft.text.Text.translatable("container.repair"));
        if (player.openHandledScreen(factory).isEmpty()) return;
        apRemaining -= CraftingStations.AP_COST;
        sendMessage("§b✦ Anvil opened. §7(-" + CraftingStations.AP_COST
            + " AP) §8Aim at an enemy to drop it instead.");
        sendSync();
        refreshHighlights();
    }

    private void handleUseItem(GridPos targetTile) {
        // Variable AP cost based on item type (stack-aware for goat horns)
        ItemStack heldStack = player.getMainHandStack();
        Item heldItem = heldStack.getItem();

        // Crafting stations (crafting table, smithing table, loom, stonecutter,
        // grindstone, cartography table, enchanting table): spend 1 AP to open the
        // station's UI for the acting player. The item is not consumed and no block
        // is placed. Furnaces/smelters are intentionally not stations.
        CraftingStations.Station station = CraftingStations.of(heldItem);
        if (station != null) {
            handleStationOpen(station);
            return;
        }

        // Campfire cooking: holding raw food and clicking a placed campfire tile cooks
        // it rather than eating it raw. Checked before the feed/eat paths below so a
        // raw steak aimed at the fire never gets swallowed instead.
        if (ItemUseHandler.isCampfireCookable(heldItem) && isCampfireTile(targetTile)) {
            handleCampfireCook(heldStack, targetTile);
            return;
        }

        // Co-op feed: holding food + clicking an adjacent ally tile feeds them
        // instead of self-healing. Lets parties share consumables to keep a
        // low-HP member alive when the food belongs to another player.
        if (ItemUseHandler.isFood(heldItem) && partyPlayers.size() > 1 && arena != null) {
            GridPos myPos = arena.getPlayerGridPos();
            if (myPos != null && myPos.manhattanDistance(targetTile) <= 1
                    && !myPos.equals(targetTile)) {
                net.minecraft.util.math.BlockPos origin = arena.getOrigin();
                for (ServerPlayerEntity ally : partyPlayers) {
                    if (ally == null || ally == player || !ally.isAlive()) continue;
                    if (ally.isRemoved() || ally.isDisconnected()) continue;
                    net.minecraft.util.math.BlockPos abp = ally.getBlockPos();
                    GridPos allyPos = new GridPos(
                        abp.getX() - origin.getX(), abp.getZ() - origin.getZ());
                    if (allyPos.equals(targetTile)) {
                        handleFeedAlly(ally, heldStack);
                        return;
                    }
                }
            }
        }

        // Co-op milk: holding a milk bucket + clicking an adjacent ally tile clears
        // THEIR status effects instead of the drinker's own. Mirrors the food-feed
        // branch above.
        if (heldItem == Items.MILK_BUCKET && partyPlayers.size() > 1 && arena != null) {
            GridPos myPos = arena.getPlayerGridPos();
            if (myPos != null && myPos.manhattanDistance(targetTile) <= 1
                    && !myPos.equals(targetTile)) {
                net.minecraft.util.math.BlockPos origin = arena.getOrigin();
                for (ServerPlayerEntity ally : partyPlayers) {
                    if (ally == null || ally == player || !ally.isAlive()) continue;
                    if (ally.isRemoved() || ally.isDisconnected()) continue;
                    net.minecraft.util.math.BlockPos abp = ally.getBlockPos();
                    GridPos allyPos = new GridPos(
                        abp.getX() - origin.getX(), abp.getZ() - origin.getZ());
                    if (allyPos.equals(targetTile)) {
                        handleFeedMilkToAlly(ally, heldStack);
                        return;
                    }
                }
            }
        }

        // Registered usable items (addon mods / JSON datapacks) take priority over
        // Craftics' built-in item handling. Unregistered items fall through unchanged.
        com.crackedgames.craftics.api.registry.UsableItemEntry customEntry =
            com.crackedgames.craftics.api.registry.UsableItemRegistry.getOrNull(heldItem);
        if (customEntry != null) {
            handleCustomUsableItem(targetTile, customEntry);
            return;
        }

        // Spawn eggs summon a temporary in-combat ally on the target tile.
        if (heldItem instanceof net.minecraft.item.SpawnEggItem) {
            handleSpawnEggSummon(heldStack, targetTile);
            return;
        }

        // Bucket of Axolotl behaves exactly like an axolotl spawn egg in combat:
        // it summons an axolotl ally on the target tile. On success the bucket
        // is consumed and an empty bucket is returned to the player (mirrors
        // vanilla's bucket-of-fish dump behavior).
        if (heldItem == Items.AXOLOTL_BUCKET) {
            ItemStack synthetic = new ItemStack(Items.AXOLOTL_SPAWN_EGG);
            if (handleSpawnEggSummon(synthetic, targetTile)) {
                heldStack.decrement(1);
                ItemStack emptyBucket = new ItemStack(Items.BUCKET);
                if (!player.getInventory().insertStack(emptyBucket)) {
                    player.dropItem(emptyBucket, false);
                }
            }
            return;
        }

        // Anvil: dropping it on an enemy is a weapon (handled in ItemUseHandler), but
        // clicking empty ground or your own tile opens the anvil UI instead, so a
        // spare anvil doubles as a portable repair/rename bench mid-fight.
        if (isAnvilItem(heldItem) && arena != null) {
            CombatEntity occupant = arena.getOccupant(targetTile);
            boolean ownTile = targetTile.equals(arena.getPlayerGridPos());
            if (ownTile || occupant == null || !occupant.isAlive()) {
                handleAnvilOpen();
                return;
            }
        }

        // Eligible blocks place a temporary wall obstacle on the target tile.
        if (WallBlocks.isEligible(heldStack)) {
            handleWallBlockPlacement(heldStack, targetTile);
            return;
        }

        int apCost = ItemUseHandler.getApCost(heldStack);

        // Robe armor makes sherd spells cheaper. Applied before the affordability
        // check so the discount can be the thing that lets the cast happen at all.
        if (PotterySherdSpells.isPotterySherd(heldItem)) {
            int discount = ArmorSetEffects.sherdApDiscount(PlayerCombatStats.getArmorSet(player));
            if (discount > 0) apCost = Math.max(1, apCost - discount);
        }

        if (apRemaining < apCost) {
            sendMessage("§cNeed " + apCost + " AP to use that! (have " + apRemaining + ")");
            return;
        }

        // Pottery Sherd spells -handled directly for access to enemies/combatEffects
        if (PotterySherdSpells.isPotterySherd(heldItem)) {
            handleSherdSpell(targetTile, heldItem, apCost);
            return;
        }

        // Trapper (hoe): a splash potion cast onto an empty tile with no enemy in splash
        // range arms a hidden trap there instead of splashing nothing - strictly an upgrade
        // over the wasted throw it replaces. Springs on the first enemy to stand on the tile.
        if (ItemUseHandler.isSplashPotion(heldItem) && targetTile != null
                && CrafticsEnchantments.level(player, CrafticsEnchantments.TRAPPER) > 0
                && arena.isInBounds(targetTile)
                && arena.getOccupant(targetTile) == null
                && !targetTile.equals(gridPosOf(player))
                && !trapperTraps.containsKey(targetTile)) {
            boolean enemyInSplash = false;
            for (CombatEntity ce : enemies) {
                if (ce.isAlive() && !ce.isAlly()
                        && ce.getGridPos().manhattanDistance(targetTile) <= 1) {
                    enemyInSplash = true;
                    break;
                }
            }
            GridTile trapTile = arena.getTile(targetTile);
            var trapContents = heldStack.get(DataComponentTypes.POTION_CONTENTS);
            if (!enemyInSplash && trapTile != null && trapTile.isWalkable() && trapContents != null) {
                ItemStack buried = heldStack.copyWithCount(1);
                heldStack.decrement(1);
                trapperTraps.put(targetTile, new TrapperTrap(buried, player.getUuid()));
                apRemaining -= apCost;
                ServerWorld trapWorld = (ServerWorld) player.getEntityWorld();
                BlockPos trapBp = arena.gridToBlockPos(targetTile);
                trapWorld.playSound(null, trapBp, net.minecraft.sound.SoundEvents.BLOCK_SAND_PLACE,
                    net.minecraft.sound.SoundCategory.PLAYERS, 0.7f, 0.8f);
                sendMessage("§2Trapper: potion buried. The first enemy to step there springs it.");
                sendSync();
                refreshHighlights();
                return;
            }
        }

        // Terraform (hoe): remember the target tile's PRE-cast terrain, so a successful cast
        // can normalize what was already there without undoing terrain the cast itself made.
        TileType terraformPriorType = null;
        if (targetTile != null && arena != null) {
            GridTile tt = arena.getTile(targetTile);
            if (tt != null) terraformPriorType = tt.getType();
        }

        // Remember what was thrown BEFORE the handler decrements the stack, so the flight
        // below can show the right item.
        ItemStack thrownStack = player.getMainHandStack().copyWithCount(1);

        // A thrown item leaves the hand BEFORE it does anything.
        //
        // This is the last of the four bugs that all came from effects resolving at use time
        // rather than at land time. The snowball's damage, the fire charge's burst and the
        // splash potion's cloud all used to happen the instant the item was used, and the item
        // was then shown crossing the arena afterwards - chasing a result the player had
        // already watched. So the throw goes first and the whole of the resolution waits for it
        // to arrive.
        //
        // canThrowAt is what makes that safe: item use validates and resolves in one call, so
        // without asking first there would be no way to know the throw was legal until after
        // committing to the visual. It applies exactly the reach and line-of-sight rule the
        // throw itself will, and touches nothing.
        if (targetTile != null && isThrownItem(thrownStack.getItem())
                && ItemUseHandler.canThrowAt(player, arena, targetTile)) {
            int flightTicks = flyThrownItem(thrownStack, targetTile);
            if (flightTicks > 0) {
                final int fApCost = apCost;
                final TileType fPriorType = terraformPriorType;
                final ItemStack fHeld = heldStack;
                final Item fItem = heldItem;
                pendingItemDelay = flightTicks;
                // Guarded the same way pendingAttackAction's body is: the fight can end while
                // the item is in the air (another party member finishing it, a disconnect), and
                // resolving into a torn-down arena is an NPE. Dropping it costs the player
                // nothing - useItem has not run, so the item is still in their hand and the AP
                // is still unspent.
                pendingItemAction = () -> {
                    if (!active || player == null || arena == null) return;
                    resolveItemUse(targetTile, fHeld, fItem, fApCost, fPriorType);
                };
                sendSync();
                return;
            }
        }

        resolveItemUse(targetTile, heldStack, heldItem, apCost, terraformPriorType);
    }

    /**
     * Everything a used item does, once it is where it is going.
     *
     * <p>Split out of {@link #handleUseItem} so a thrown item can have its flight happen first.
     * For everything else - eating, a bucket, a pickaxe, a horn - this still runs immediately
     * and nothing about it changed.
     *
     * <p>The parameters are the state the decision was made with, captured at use time rather
     * than re-read here. That matters for the deferred path: {@code apCost} was already
     * discounted by robe armour, and {@code terraformPriorType} is the target's terrain from
     * BEFORE the cast, which cannot be recovered afterwards by definition.
     */
    private void resolveItemUse(GridPos targetTile, ItemStack heldStack, Item heldItem,
                                int apCost, TileType terraformPriorType) {
        String result = ItemUseHandler.useItem(player, arena, targetTile);

        if (result == null) {
            sendMessage("§cCan't use that item!");
            return;
        }

        // Don't deduct AP if the item use failed (range check, invalid target, etc.)
        if (result.startsWith("§c")) {
            sendMessage(result);
            sendSync();
            refreshHighlights();
            return;
        }

        applyTerraform(targetTile, terraformPriorType, result);

        // Performative (hoe): the cast echoes for free. useItem() consumes the held item itself,
        // so hand one back BEFORE the encore - otherwise the second cast eats a second item and
        // the enchantment would be a downgrade rather than a bonus.
        if (isSpecialClassItem(heldItem) && HoeEnchantEffects.rollDoubleCast(player)) {
            HoeEnchantEffects.performativeVfx(player, (ServerWorld) player.getEntityWorld());
            sendMessage("§dPerformative! The cast echoes.");
            ItemStack encoreStack = player.getMainHandStack();
            boolean refunded = false;
            if (encoreStack.isEmpty()) {
                // The first cast used the last one - put a fresh one in hand to spend.
                player.setStackInHand(net.minecraft.util.Hand.MAIN_HAND, new ItemStack(heldItem));
                refunded = true;
            } else if (encoreStack.getItem() == heldItem) {
                encoreStack.increment(1);
                refunded = true;
            }
            if (refunded) {
                String encore = ItemUseHandler.useItem(player, arena, targetTile);
                if (encore != null && !encore.startsWith("§c")) {
                    sendMessage(encore);
                }
            }
        }

        // Reserving (hoe): chance the cast costs no AP at all.
        if (isSpecialClassItem(heldItem) && HoeEnchantEffects.rollFreeAp(player)) {
            HoeEnchantEffects.reservingVfx(player, (ServerWorld) player.getEntityWorld());
            sendMessage("§dReserving! That cost you no AP.");
        } else {
            apRemaining -= apCost;
        }

        // Sound: item use
        player.getWorld().playSound(null, player.getBlockPos(),
            net.minecraft.sound.SoundEvents.ENTITY_ITEM_PICKUP,
            net.minecraft.sound.SoundCategory.PLAYERS, 0.5f, 1.2f);

        // Handle mounting -player mounts a saddled horse/donkey/camel for bonus speed
        if (result.startsWith(ItemUseHandler.MOUNT_PREFIX)) {
            int entityId = Integer.parseInt(result.substring(ItemUseHandler.MOUNT_PREFIX.length()));
            for (CombatEntity e : enemies) {
                if (e.getEntityId() == entityId) {
                    e.setAlly(true);
                    mountPlayerOn(e);
                    break;
                }
            }
        }
        // Handle taming -combat-capable mobs become allies
        else if (result.startsWith(ItemUseHandler.TAME_PREFIX)) {
            int entityId = Integer.parseInt(result.substring(ItemUseHandler.TAME_PREFIX.length()));
            for (CombatEntity e : enemies) {
                if (e.getEntityId() == entityId) {
                    // Snapshot the mob's full NBT so variant/collar/name persist when it
                    // returns to the hub after combat. Only needed for mobs that weren't
                    // loaded from a hub snapshot already.
                    if (e.getOriginalHubNbt() == null && e.getMobEntity() != null) {
                        net.minecraft.nbt.NbtCompound tameSnap = new net.minecraft.nbt.NbtCompound();
                        try {
                            e.getMobEntity().writeNbt(tameSnap);
                            e.setOriginalHubNbt(tameSnap);
                        } catch (Throwable t) {
                            CrafticsMod.LOGGER.warn("Failed to snapshot tamed mob NBT: {}", t.getMessage());
                        }
                    }
                    e.setAlly(true);
                    e.setOwnerUuid(player.getUuid());
                    // Tamed here, not brought here: it fights out this level and then goes
                    // home, rather than being carried through the rest of the run.
                    e.setTamedInCombat(true);
                    // Apply per-species minimum stats for combat pets
                    AllyEntry petMin = AllyRegistry.getOrNull(e.getEntityTypeId());
                    if (petMin != null) {
                        if (e.getAttackPower() < petMin.attack()) {
                            e.setAttackBoost(petMin.attack() - e.getAttackPower());
                        }
                        if (e.getDefense() < petMin.defense()) {
                            e.setDefenseBoost(petMin.defense() - e.getDefense());
                        }
                        if (e.getRange() < petMin.range()) {
                            e.setRangeOverride(petMin.range());
                        }
                    }
                    if (e.getMobEntity() != null) {
                        e.getMobEntity().setGlowing(false);
                        // Check for horse/wolf armor on the tamed mob
                        ItemStack petArmor = e.getMobEntity().getEquippedStack(net.minecraft.entity.EquipmentSlot.BODY);
                        if (!petArmor.isEmpty()) {
                            Item armorItem = petArmor.getItem();
                            int defBonus = 0;
                            int atkBonus = 0;
                            if (armorItem == Items.IRON_HORSE_ARMOR) { defBonus = 2; }
                            else if (armorItem == Items.GOLDEN_HORSE_ARMOR) { defBonus = 1; atkBonus = 1; }
                            else if (armorItem == Items.DIAMOND_HORSE_ARMOR) { defBonus = 3; atkBonus = 1; }
                            else if (armorItem == Items.WOLF_ARMOR) { defBonus = 2; atkBonus = 1; }
                            else if (armorItem == Items.LEATHER_HORSE_ARMOR) { defBonus = 1; }
                            if (defBonus > 0 || atkBonus > 0) {
                                sendMessage("\u00a77" + e.getDisplayName() + "'s armor: +" + defBonus + " DEF" + (atkBonus > 0 ? ", +" + atkBonus + " ATK" : ""));
                            }
                        }
                    }
                    // Pet affinity HP. A tamed mob already exists as a CombatEntity, so its
                    // constructor-set max HP is raised with a negative reduction rather than
                    // folded in at spawn like the other ally paths. The damage bonus is applied
                    // per-attack via DamageType.getTotalBonus on the PET damage type, so there
                    // is deliberately no ATK boost here -that would double-count it.
                    int hpBoost = computeAllyPetHpBonus(e.getEntityTypeId(), player.getUuid());
                    if (hpBoost > 0) {
                        e.addMaxHpReduction(-hpBoost);
                        e.heal(hpBoost);
                        sendMessage("\u00a7aPet Affinity: +" + hpBoost + " HP");
                    }
                    sendMessage("§a§l" + e.getDisplayName() + " has been tamed! They fight for you now!");
                    break;
                }
            }
            // Check if taming the last enemy triggers victory
            if (!anyEnemyBlockingVictory()) {
                handleVictory();
                return;
            }
        }
        // Handle befriending -passive mobs vanish (sent to hub) with hearts
        else if (result.startsWith(ItemUseHandler.BEFRIEND_PREFIX)) {
            String data = result.substring(ItemUseHandler.BEFRIEND_PREFIX.length());
            String[] parts = data.split(":", 2);
            int entityId = Integer.parseInt(parts[0]);
            String entityType = parts.length > 1 ? parts[1] : "unknown";
            for (CombatEntity e : enemies) {
                if (e.getEntityId() == entityId) {
                    // Show hearts particle burst, then remove
                    if (e.getMobEntity() != null) {
                        net.minecraft.server.world.ServerWorld sw = (net.minecraft.server.world.ServerWorld) player.getEntityWorld();
                        sw.spawnParticles(net.minecraft.particle.ParticleTypes.HEART,
                            e.getMobEntity().getX(), e.getMobEntity().getY() + 1.5, e.getMobEntity().getZ(),
                            8, 0.5, 0.3, 0.5, 0.1);
                    }
                    killEnemy(e);
                    String mobName = entityType.contains(":") ? entityType.substring(entityType.indexOf(':') + 1) : entityType;
                    sendMessage("§a§l" + mobName.substring(0,1).toUpperCase() + mobName.substring(1) + " befriended! Sent to your hub.");
                    break;
                }
            }
        }
        // Handle TNT placement -track for detonation next round
        else if (result.startsWith(ItemUseHandler.TNT_PREFIX)) {
            String coords = result.substring(ItemUseHandler.TNT_PREFIX.length());
            String[] parts = coords.split(",");
            int tx = Integer.parseInt(parts[0]);
            int tz = Integer.parseInt(parts[1]);
            GridPos tntPos = new GridPos(tx, tz);
            primePendingTnt(tntPos, "§e§lTNT placed! §r§7It will explode at the start of next round!");
        }
        else if (result.startsWith(ItemUseHandler.CHORUS_PREFIX)) {
            int healed = 0;
            try {
                healed = Integer.parseInt(result.substring(ItemUseHandler.CHORUS_PREFIX.length()));
            } catch (NumberFormatException ignored) {}
            chorusHop(healed);
        }
        // Bed: anchor in the overworld, bomb in the nether/end.
        else if (result.startsWith(ItemUseHandler.BED_PREFIX)) {
            String data = result.substring(ItemUseHandler.BED_PREFIX.length());
            String[] parts = data.split(",");
            GridPos bedPos = new GridPos(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
            net.minecraft.block.Block bedBlock = net.minecraft.block.Blocks.RED_BED;
            if (parts.length > 2) {
                net.minecraft.item.Item bedItem = net.minecraft.registry.Registries.ITEM
                    .get(net.minecraft.util.Identifier.of(parts[2]));
                if (bedItem instanceof net.minecraft.item.BlockItem bi) bedBlock = bi.getBlock();
            }
            boolean isAnchor = bedBlock == net.minecraft.block.Blocks.RESPAWN_ANCHOR;
            if (isExplosiveSleepItem(isAnchor)) {
                detonateBed(bedPos, bedBlock);
            } else {
                placeBedAnchor(bedPos, bedBlock);
            }
        }
        else if (!hasDeferredHandler(result)) {
            sendMessage(result);
        }
        // Tile effects (lava, campfire, honey, banner, scaffold)
        if (result.startsWith(ItemUseHandler.TILE_EFFECT_PREFIX)) {
            String data = result.substring(ItemUseHandler.TILE_EFFECT_PREFIX.length());
            String[] parts = data.split("\\|", 2);
            String tileData = parts[0]; // e.g. "lava:3:5"
            String[] tileInfo = tileData.split(":");
            String effectType = tileInfo[0];
            int tx = Integer.parseInt(tileInfo[1]);
            int tz = Integer.parseInt(tileInfo[2]);
            if ("clear".equals(effectType)) {
                // Empty bucket: revert tile to NORMAL and remove any existing effect
                resetTileToFloor(new GridPos(tx, tz));
            } else if ("beehive".equals(effectType) || "armor_stand".equals(effectType)) {
                // Both are block-backed objects with HP that sit on the field.
                // The hive keeps releasing allied bees; the stand just soaks
                // aggro. Flagged ally + taunting so resolveTauntTarget pulls
                // enemies onto them instead of the player.
                boolean isHive = "beehive".equals(effectType);
                GridPos objPos = new GridPos(tx, tz);
                ServerWorld objWorld = (ServerWorld) player.getEntityWorld();
                CombatEntity placed = placeBlockObject(
                    isHive ? HIVE_ALLY_ID : DECOY_ID, objPos,
                    isHive ? HIVE_HP : DECOY_HP,
                    -(minibossBlockIdCounter++),
                    isHive ? net.minecraft.block.Blocks.BEEHIVE : net.minecraft.block.Blocks.STONE,
                    objWorld);
                if (placed != null) {
                    placed.setAlly(true);
                    placed.setTaunting(true);
                    if (!isHive) {
                        // A real armor stand entity reads far better than a stone
                        // block; the block object is only the grid/HP anchor.
                        objWorld.setBlockState(arena.gridToBlockPos(objPos),
                            net.minecraft.block.Blocks.AIR.getDefaultState());
                        spawnDecoyVisual(placed, objPos, objWorld);
                    }
                }
            } else if ("end_crystal".equals(effectType)) {
                // 1 HP: any hit pops it. The crystal is not a wall you chew through,
                // it is a trigger you choose the moment for. Left non-ally so enemies
                // ignore it entirely - placeBlockObject marks it scenery, so it can
                // never keep a room from clearing either.
                GridPos xPos = new GridPos(tx, tz);
                ServerWorld xWorld = (ServerWorld) player.getEntityWorld();
                CombatEntity crystal = placeBlockObject(END_CRYSTAL_ID, xPos, 1,
                    -(minibossBlockIdCounter++), net.minecraft.block.Blocks.AIR, xWorld);
                if (crystal != null) spawnEndCrystalVisual(crystal, xPos, xWorld);
            } else if (effectType.startsWith("ice_")) {
                placeIceTile(new GridPos(tx, tz), effectType.substring("ice_".length()));
            } else if ("grow_cover".equals(effectType)
                    || effectType.startsWith("place_cover_")) {
                GridPos coverPos = new GridPos(tx, tz);
                boolean fern = effectType.endsWith("_fern");
                GridTile coverTile = arena.getTile(coverPos);
                ServerWorld coverWorld = (ServerWorld) player.getEntityWorld();
                if (coverTile != null) {
                    coverTile.setType(fern ? TileType.TALL_FERN : TileType.TALL_GRASS);
                    net.minecraft.block.Block plant = fern
                        ? net.minecraft.block.Blocks.LARGE_FERN
                        : net.minecraft.block.Blocks.TALL_GRASS;
                    coverTile.setBlockType(plant);
                    // Cover is a two-block plant sitting in the Y+1 overlay, matching
                    // what the shear path clears.
                    BlockPos lower = arena.gridToBlockPos(coverPos);
                    coverWorld.setBlockState(lower, plant.getDefaultState()
                        .with(net.minecraft.block.TallPlantBlock.HALF,
                            net.minecraft.block.enums.DoubleBlockHalf.LOWER),
                        net.minecraft.block.Block.NOTIFY_LISTENERS);
                    coverWorld.setBlockState(lower.up(), plant.getDefaultState()
                        .with(net.minecraft.block.TallPlantBlock.HALF,
                            net.minecraft.block.enums.DoubleBlockHalf.UPPER),
                        net.minecraft.block.Block.NOTIFY_LISTENERS);
                    coverWorld.spawnParticles(net.minecraft.particle.ParticleTypes.HAPPY_VILLAGER,
                        lower.getX() + 0.5, lower.getY() + 0.6, lower.getZ() + 0.5,
                        12, 0.3, 0.4, 0.3, 0.02);
                    coverWorld.playSound(null, lower,
                        net.minecraft.sound.SoundEvents.BLOCK_GRASS_PLACE,
                        net.minecraft.sound.SoundCategory.BLOCKS, 0.9f, 1.1f);
                }
            } else if ("shear_grass".equals(effectType) || "shear_web".equals(effectType)) {
                GridPos shearPos = new GridPos(tx, tz);
                ServerWorld shearWorld = (ServerWorld) player.getEntityWorld();
                net.minecraft.item.Item cut;
                if ("shear_web".equals(effectType)) {
                    arena.clearWebOverlay(shearPos);
                    shearWorld.setBlockState(arena.gridToBlockPos(shearPos).up(1),
                        net.minecraft.block.Blocks.AIR.getDefaultState());
                    cut = Items.COBWEB;
                } else {
                    GridTile shorn = arena.getTile(shearPos);
                    cut = shorn != null && shorn.getType() == TileType.TALL_FERN
                        ? Items.LARGE_FERN : Items.TALL_GRASS;
                    if (shorn != null) {
                        shorn.setType(TileType.NORMAL);
                        shorn.setBlockType(getBiomeFloorBlock());
                    }
                    shearWorld.setBlockState(arena.gridToBlockPos(shearPos),
                        net.minecraft.block.Blocks.AIR.getDefaultState());
                }
                // Hand the player what they cut so cover can be re-placed elsewhere.
                giveOrDropItem(new ItemStack(cut));
                shearWorld.playSound(null, arena.gridToBlockPos(shearPos),
                    net.minecraft.sound.SoundEvents.ENTITY_SHEEP_SHEAR,
                    net.minecraft.sound.SoundCategory.PLAYERS, 0.8f, 1.1f);
            } else if ("break".equals(effectType)) {
                // Pickaxe: convert obstacle to walkable NORMAL tile
                GridPos breakPos = new GridPos(tx, tz);
                // A support pillar comes out whole. It is three blocks tall and the ordinary
                // break below clears exactly one of them, which would leave a floating stump at
                // head height - and a block up there is read back as a permanent obstacle the
                // next time this arena is scanned. Taking one out also strips the boss of the
                // armour it was giving him, which is the entire reason to spend a turn on it.
                if (isBossPillar(breakPos)) {
                    clearBossPillar(breakPos);
                    sendMessage("§6⛏ You knock out a support pillar! §7The Hollow King's guard drops.");
                } else {
                    GridTile breakTile = arena.getTile(breakPos);
                    if (breakTile != null) {
                        breakTile.setType(TileType.NORMAL);
                        breakTile.setBlockType(getBiomeFloorBlock());
                    }
                    // gridToBlockPos returns oy+1 (where the obstacle block sits)
                    BlockPos aboveBp = arena.gridToBlockPos(breakPos);
                    // Floor is one Y below
                    BlockPos floorBp = aboveBp.down();
                    ServerWorld sw = (ServerWorld) player.getEntityWorld();
                    // Clear the obstacle block at oy+1
                    sw.setBlockState(aboveBp, net.minecraft.block.Blocks.AIR.getDefaultState());
                    // Restore floor block at oy
                    sw.setBlockState(floorBp, breakTile != null ? breakTile.getBlockType().getDefaultState()
                        : getBiomeFloorBlock().getDefaultState());
                    // Break particles
                    sw.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                        aboveBp.getX() + 0.5, aboveBp.getY() + 0.5, aboveBp.getZ() + 0.5,
                        8, 0.3, 0.3, 0.3, 0.05);
                    player.getWorld().playSound(null, aboveBp,
                        net.minecraft.sound.SoundEvents.BLOCK_STONE_BREAK,
                        net.minecraft.sound.SoundCategory.BLOCKS, 1.0f, 1.0f);
                }
            } else if ("pit".equals(effectType)) {
                // Pickaxe on a normal floor tile: dig a 1-deep sunken pit
                // (LOW_GROUND). Wall the hole with cobblestone so the player
                // doesn't break through into a large air gap underneath.
                digSunkenPit(new GridPos(tx, tz));
            } else if ("void".equals(effectType)) {
                // Pickaxe on a sunken pit: deepen it into a VOID hole. Keep
                // cobblestone interior walls and lay a black-concrete bottom.
                digVoidPit(new GridPos(tx, tz));
            } else if ("soul_fire".equals(effectType)) {
                // Dragon's breath. SOUL_SPREAD, not STRUCK: dragon-origin soul fire
                // needs no fuel and carries through obstacles, and igniteTile's
                // ensureSoulBase lays the soul soil the flame has to stand on.
                GridPos soulPos = new GridPos(tx, tz);
                if (!igniteTile(soulPos, Ignition.SOUL_SPREAD)) {
                    sendMessage("§7The breath won't take hold there.");
                }
            } else if ("fire".equals(effectType)) {
                // Flint & steel / fire charge on open ground: start a real burn that
                // spreads and scorches, rather than pasting a permanent hazard tile.
                GridPos firePos = new GridPos(tx, tz);
                if (!igniteTile(firePos, Ignition.STRUCK)) {
                    sendMessage("§7There's nothing there to catch.");
                }
            } else {
                GridPos effectPos = new GridPos(tx, tz);

                // Bridging: ItemUseHandler#requireFlatGround now allows placing these
                // blocks onto WATER, DEEP_WATER and LAVA tiles, so the tile itself has to
                // flip to NORMAL here before anything below sets its own type/block -
                // walkability is driven by TileType, not the visible block, so leaving the
                // tile typed as a hazard would still block movement even with a block sat
                // on top of it. This MUST run before the per-effect code further down:
                // GridTile#setType resets the tile's block to a generic default, and the
                // obstacle/utility placement below (cactus, jukebox, honey, sponge, ...)
                // relies on setting its own type (e.g. OBSTACLE) and block AFTER this, so
                // it still wins for the effects that aren't a plain walkable floor.
                GridTile bridgeTile = arena.getTile(effectPos);
                if (bridgeTile != null) {
                    TileType bridgedFrom = bridgeTile.getType();
                    if (bridgedFrom == TileType.WATER || bridgedFrom == TileType.DEEP_WATER
                            || bridgedFrom == TileType.LAVA) {
                        bridgeTile.setType(TileType.NORMAL);
                    }
                }

                // Banner: store color- and bonus-tagged form so the aura is visually
                // distinct per color and the Special-scaled DEF bonus is frozen at
                // placement time (later affinity gains don't retroactively buff old banners).
                if ("banner".equals(effectType) && tileInfo.length >= 5) {
                    tileEffects.put(effectPos, "banner:" + tileInfo[3] + ":" + tileInfo[4]);
                } else if ("banner".equals(effectType) && tileInfo.length >= 4) {
                    tileEffects.put(effectPos, "banner:" + tileInfo[3]);
                } else {
                    tileEffects.put(effectPos, effectType);
                }

                // Register light zones for torches and lanterns (negate darkness)
                if ("torch".equals(effectType) || "lantern".equals(effectType) || "campfire".equals(effectType)) {
                    int lightRadius = "torch".equals(effectType) ? 2 : 3; // Torches: 2 tiles, Lanterns/Campfire: 3 tiles
                    registerLightZone(effectPos, lightRadius);
                }

                // Player-placed cactus: place an actual cactus block and mark the tile as an obstacle
                if ("cactus".equals(effectType)) {
                    GridTile cactusTile = arena.getTile(effectPos);
                    if (cactusTile != null) {
                        cactusTile.setType(TileType.OBSTACLE);
                        cactusTile.setBlockType(Blocks.CACTUS);
                    }
                    BlockPos cactusBp = arena.gridToBlockPos(effectPos);
                    ServerWorld cactusWorld = (ServerWorld) player.getEntityWorld();
                    recordPlacedBlock(cactusBp);
                    cactusWorld.setBlockState(cactusBp, Blocks.CACTUS.getDefaultState(),
                        net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);
                }

                // Sponge: soak the four tiles around it. Its own tile is already handled by
                // the bridging flip above, and must NOT go through resetTileToFloor - that
                // clears tileEffects, which by this point holds the sponge's own entry.
                if ("sponge".equals(effectType)) {
                    int drained = 0;
                    for (int[] off : new int[][]{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
                        GridPos near = new GridPos(effectPos.x() + off[0], effectPos.z() + off[1]);
                        GridTile wet = arena.getTile(near);
                        if (wet != null && wet.isWater()) {
                            resetTileToFloor(near);
                            drained++;
                        }
                    }
                    if (drained > 0) {
                        sendMessage("§eThe sponge soaks up " + drained + " water tile"
                            + (drained == 1 ? "" : "s") + ".");
                    }
                }

                // Player-placed utility blocks: physically drop the right block
                // in the world. Full-cube blocks (honey, slime, jukebox, sponge,
                // powder snow) also turn their tile into an OBSTACLE so the
                // grid pathing respects the wall. Non-full-cube blocks
                // (campfire, scaffolding, spore blossom, bell) only place the
                // block -the tile stays walkable.
                placeUtilityBlock(effectType, effectPos);

                // Player-placed banner: place a real, color-correct banner block.
                // Tile stays NORMAL -banners have no collision; player can stand on/walk through.
                if ("banner".equals(effectType) && tileInfo.length >= 4) {
                    String colorId = tileInfo[3];
                    net.minecraft.block.Block bannerBlock = BannerEffects.blockForColorId(colorId);
                    if (bannerBlock != null) {
                        BlockPos bannerBp = arena.gridToBlockPos(effectPos);
                        ServerWorld bannerWorld = (ServerWorld) player.getEntityWorld();
                        recordPlacedBlock(bannerBp);
                        bannerWorld.setBlockState(bannerBp, bannerBlock.getDefaultState(),
                            net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);
                    }
                }

                // Update the GridTile type so fishing/boat checks work
                GridTile effectTile = arena.getTile(effectPos);
                if (effectTile != null) {
                    if ("water".equals(effectType)) effectTile.setType(TileType.WATER);
                    else if ("lava".equals(effectType)) effectTile.setType(TileType.LAVA);
                    else if ("powder_snow".equals(effectType)) effectTile.setType(TileType.POWDER_SNOW);
                }

                // Water/lava bucket: actually place the fluid block so the tile is
                // visible. Without this the tile type flips to WATER/LAVA but the
                // floor block never changes, so the player sees no fluid yet still
                // "sinks" into the tile (and could fish an invisible pool).
                // gridToBlockPos is Y+1 overlay space; the floor sits one block below.
                net.minecraft.block.Block fluidBlock =
                    "water".equals(effectType) ? Blocks.WATER
                    : "lava".equals(effectType) ? Blocks.LAVA
                    : null;
                if (fluidBlock != null && effectTile != null) {
                    BlockPos fluidBp = arena.gridToBlockPos(effectPos);
                    BlockPos fluidFloorBp = fluidBp.down();
                    ServerWorld fluidWorld = (ServerWorld) player.getEntityWorld();
                    recordPlacedBlock(fluidFloorBp);
                    recordPlacedBlock(fluidBp);
                    fluidWorld.setBlockState(fluidFloorBp, fluidBlock.getDefaultState(),
                        net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);
                    fluidWorld.setBlockState(fluidBp, net.minecraft.block.Blocks.AIR.getDefaultState());
                    effectTile.setBlockType(fluidBlock);
                }
            }
            // Process message part - handle GIVE: prefix for item rewards
            if (parts.length > 1) {
                String msg = parts[1];
                // Check for chained GIVE:item|message format
                if (msg.startsWith("GIVE:")) {
                    String[] giveParts = msg.split("\\|", 2);
                    String itemId = giveParts[0].substring(5); // after "GIVE:"
                    net.minecraft.item.Item giveItem = switch (itemId) {
                        case "water_bucket" -> Items.WATER_BUCKET;
                        case "lava_bucket" -> Items.LAVA_BUCKET;
                        case "powder_snow_bucket" -> Items.POWDER_SNOW_BUCKET;
                        case "bucket" -> Items.BUCKET;
                        default -> null;
                    };
                    if (giveItem != null) {
                        LootDelivery.deliver(player, new ItemStack(giveItem));
                    }
                    if (giveParts.length > 1) sendMessage(giveParts[1]);
                } else {
                    sendMessage(msg);
                }
            }
        }
        // Ally buff (jukebox music, hay bale heal, echo shard)
        else if (result.startsWith(ItemUseHandler.ALLY_BUFF_PREFIX)) {
            String data = result.substring(ItemUseHandler.ALLY_BUFF_PREFIX.length());
            String[] parts = data.split("\\|", 2);
            // Parse buff type: "heal:entityId:amount" or "music" or "echo"
            String buffData = parts[0];
            if (buffData.startsWith("heal:")) {
                String[] healParts = buffData.split(":");
                if (healParts.length >= 3) {
                    try {
                        int entityId = Integer.parseInt(healParts[1]);
                        int healAmount = Integer.parseInt(healParts[2]);
                        for (CombatEntity e : enemies) {
                            if (e.getEntityId() == entityId && e.isAlive() && e.isAlly()) {
                                e.heal(healAmount);
                                break;
                            }
                        }
                    } catch (NumberFormatException ignored) {}
                }
            }
            if (buffData.startsWith("wolfarmor:")) {
                String[] p = buffData.split(":");
                if (p.length >= 3) {
                    try {
                        int entityId = Integer.parseInt(p[1]);
                        int def = Integer.parseInt(p[2]);
                        for (CombatEntity e : enemies) {
                            if (e.getEntityId() == entityId && e.isAlive() && e.isAlly()) {
                                e.setDefenseBoost(def);
                                break;
                            }
                        }
                    } catch (NumberFormatException ignored) {}
                }
            }
            if (buffData.startsWith("blind:")) {
                String[] p = buffData.split(":");
                if (p.length >= 3) {
                    try {
                        int entityId = Integer.parseInt(p[1]);
                        int turns = Integer.parseInt(p[2]);
                        for (CombatEntity e : enemies) {
                            if (e.getEntityId() == entityId && e.isAlive() && !e.isAlly()) {
                                e.stackBlinded(turns);
                                break;
                            }
                        }
                    } catch (NumberFormatException ignored) {}
                }
            }
            if (buffData.startsWith("litcoal:")) {
                try {
                    int entityId = Integer.parseInt(buffData.substring("litcoal:".length()));
                    for (CombatEntity e : enemies) {
                        if (e.getEntityId() == entityId && e.isAlive() && e.isAlly()) {
                            igniteAlly(e);
                            break;
                        }
                    }
                } catch (NumberFormatException ignored) {}
            }
            if (buffData.equals("echo")) {
                echoReturnArmed.add(player.getUuid());
            }
            if (parts.length > 1) sendMessage(parts[1]);
        }
        // Fishing result -strip prefix, display the catch message
        if (result.startsWith(ItemUseHandler.FISHING_PREFIX)) {
            sendMessage(result.substring(ItemUseHandler.FISHING_PREFIX.length()));
        }
        // Anvil drop -spawn a falling anvil entity above the target and defer
        // the actual damage until the block lands. Vanilla anvil gravity damage
        // is disabled; only the queued base damage applies.
        if (result.startsWith(ItemUseHandler.ANVIL_DROP_PREFIX)) {
            String data = result.substring(ItemUseHandler.ANVIL_DROP_PREFIX.length());
            String[] parts = data.split("\\|", 2);
            String[] body = parts[0].split(":");
            if (body.length >= 2) {
                try {
                    int targetEntityId = Integer.parseInt(body[0]);
                    int damage = Integer.parseInt(body[1]);
                    spawnAnvilDrop(targetEntityId, damage);
                } catch (NumberFormatException ignored) {}
            }
            if (parts.length > 1) sendMessage(parts[1]);
        }
        // Goat horn effect -apply buff/debuff
        if (result.startsWith(ItemUseHandler.HORN_EFFECT_PREFIX)) {
            String data = result.substring(ItemUseHandler.HORN_EFFECT_PREFIX.length());
            String[] parts = data.split("\\|", 2);
            String hornId = parts[0];
            if (parts.length > 1) sendMessage(parts[1]);

            // Play the horn's own instrument sound (per-variant, not random)
            HornVariants.soundForVariant(hornId).ifPresent(sound ->
                player.getWorld().playSound(null, player.getBlockPos(),
                    sound, net.minecraft.sound.SoundCategory.PLAYERS, 1.5f, 1.0f));

            // Apply the actual effect, scaled by the player's Special-class affinity
            int hornDurationBonus = SpecialAffinity.durationBonus(player);
            int hornPotencyBonus  = SpecialAffinity.potencyBonus(player);
            String[] hornMsg = new String[1];
            // Top up live AP/movement so the Feel horn's SPEED applies this turn.
            rebudgetAroundBuff(() -> hornMsg[0] = GoatHornEffects.useHorn(hornId, combatEffects, enemies,
                hornDurationBonus, hornPotencyBonus));
            if (hornMsg[0] != null && !hornMsg[0].isEmpty()) {
                sendMessage(hornMsg[0]);
            }
            // Horn Collector counts distinct variants. Sounding one is the proof you have it -
            // the tracker's recordHornUsed had existed for this and was never called by anything.
            achievementTracker.recordHornUsed(hornId);
            AchievementManager.recordCollected(player, AchievementManager.COL_HORNS, hornId);
        }

        // Check if any enemy died from the item use (egg damage, etc.)
        // Collect dead enemies first to avoid concurrent modification
        List<CombatEntity> deadEnemies = enemies.stream()
            .filter(e -> !e.isAlive() && e.getMobEntity() != null && e.getMobEntity().isAlive())
            .toList();
        for (CombatEntity dead : deadEnemies) {
            sendMessage("§a" + dead.getDisplayName() + " defeated!");
            sendToAllParty(new CombatEventPayload(
                CombatEventPayload.EVENT_DIED, dead.getEntityId(), 0, 0,
                dead.getGridPos().x(), dead.getGridPos().z()
            ));
            killEnemy(dead);
        }

        // A consumable/item landing the final blow (egg, harming splash, befriend,
        // water-drowning, etc.) must end the level too. checkAndHandleDeath/killEnemy
        // never end the fight on their own, so without this an item kill soft-locks.
        // Same win check as handleAttack / tryHandleInstrument.
        if (phase != CombatPhase.GAME_OVER && phase != CombatPhase.LEVEL_COMPLETE
                && !anyEnemyBlockingVictory()) {
            handleVictory();
            return;
        }

        sendSync();
        refreshHighlights();
    }

    /**
     * True when an item-use result carries a prefix that a LATER block in handleUseItem parses
     * and messages itself. Those results are machine-readable payloads, not chat lines: the
     * catch-all else used to print them verbatim, so every one of these items dumped its raw
     * "§eTILE:lava:3:5|GIVE:bucket|..." payload into chat and then printed the real message
     * again right under it. Most obvious on the echo shard, whose only visible effect WAS the
     * message - so it read as "does nothing but say it activated, twice".
     */
    private static boolean hasDeferredHandler(String result) {
        return result.startsWith(ItemUseHandler.TILE_EFFECT_PREFIX)
            || result.startsWith(ItemUseHandler.ALLY_BUFF_PREFIX)
            || result.startsWith(ItemUseHandler.FISHING_PREFIX)
            || result.startsWith(ItemUseHandler.ANVIL_DROP_PREFIX)
            || result.startsWith(ItemUseHandler.HORN_EFFECT_PREFIX);
    }

    /**
     * Whether {@code item} is a Special-class cast - the things the hoe enchantments key off.
     * Sherds are spells outright; everything else is the caster's consumable toolkit, defined
     * once in {@link ItemUseHandler#isSpecialConsumable}.
     */
    private static boolean isSpecialClassItem(Item item) {
        if (item == null) return false;
        return PotterySherdSpells.isPotterySherd(item) || ItemUseHandler.isSpecialConsumable(item);
    }

    /** True while a Performative encore is replaying a sherd, so the encore can't itself echo. */
    private boolean sherdEncoreInProgress = false;

    /** Handle pottery sherd spell usage -called from handleUseItem when held item is a sherd. */
    private void handleSherdSpell(GridPos targetTile, Item sherdItem, int apCost) {
        // Self-cast spells don't need a target tile
        GridPos effectiveTarget = PotterySherdSpells.isSelfCast(sherdItem) ? null : targetTile;

        // Validate range and target
        String error = PotterySherdSpells.validateSherd(sherdItem, arena, effectiveTarget, enemies);
        if (error != null) {
            sendMessage(error);
            sendSync();
            refreshHighlights();
            return;
        }

        // Reserving (hoe): chance a sherd cast costs no AP. The encore is already free, so it
        // neither rolls nor pays.
        if (sherdEncoreInProgress) {
            // free replay - charge nothing
        } else if (HoeEnchantEffects.rollFreeAp(player)) {
            HoeEnchantEffects.reservingVfx(player, (ServerWorld) player.getEntityWorld());
            sendMessage("§dReserving! That cost you no AP.");
        } else {
            apRemaining -= apCost;
        }

        // Cast the spell (applies damage/effects/particles; sherd may shatter on cast).
        // Wrapped so a self-buff sherd (e.g. War Cry's SPEED) tops up live AP/movement this turn.
        String[] resultBox = new String[1];
        rebudgetAroundBuff(() -> resultBox[0] =
            PotterySherdSpells.useSherd(player, arena, effectiveTarget, enemies, combatEffects));
        String result = resultBox[0];
        if (result == null) {
            sendMessage("§cFailed to cast spell!");
            sendSync();
            refreshHighlights();
            return;
        }

        // Block input while staged spell particles play out
        int animDelay = PotterySherdSpells.getMaxPendingDelay();
        if (animDelay > 0) spellAnimCooldown = animDelay + 2;

        // Process prefix-based results from spells

        // Tile effects (hex_trap from Danger sherd). Matched with startsWith, like the other
        // tile-effect parser: the sherd puts the prefix at the head of its result, so contains
        // only added the chance of firing on the prefix appearing inside a message body.
        if (result.startsWith(PotterySherdSpells.HEX_TRAP_PREFIX)) {
            String afterPrefix = result.substring(PotterySherdSpells.HEX_TRAP_PREFIX.length());
            String[] parts = afterPrefix.split("\\|", 2);
            String tileData = parts[0];
            String[] tileInfo = tileData.split(":");
            String effectType = tileInfo[0];
            int tx = Integer.parseInt(tileInfo[1]);
            int tz = Integer.parseInt(tileInfo[2]);
            tileEffects.put(new GridPos(tx, tz), effectType);
            hexTrapTurnsRemaining = 5;
            if (parts.length > 1) sendMessage(parts[1]);
        }
        // Seeker volley (Archer sherd). Spawning grid entities is the manager's job, so
        // the sherd hands back a "count:damage" instruction instead of doing it itself.
        else if (result.contains(PotterySherdSpells.SEEKERS_PREFIX)) {
            String afterPrefix = result.substring(result.indexOf(PotterySherdSpells.SEEKERS_PREFIX)
                + PotterySherdSpells.SEEKERS_PREFIX.length());
            // Split the payload off the trailing text first: useSherd appends the
            // "(The sherd shattered.)" suffix to whatever the spell returned, and it
            // would otherwise land inside the number we're about to parse.
            String[] parts = afterPrefix.split("\\|", 2);
            String[] seekerInfo = parts[0].split(":");
            int seekerCount = Integer.parseInt(seekerInfo[0]);
            int seekerDamage = Integer.parseInt(seekerInfo[1]);
            String volley = castSpectralSeekers(player, seekerCount, seekerDamage);
            sendMessage(parts.length > 1 ? volley + parts[1] : volley);
        }
        // Double damage next attack (Prize sherd)
        else if (result.contains(PotterySherdSpells.DOUBLE_NEXT_PREFIX)) {
            String afterPrefix = result.substring(result.indexOf(PotterySherdSpells.DOUBLE_NEXT_PREFIX) + PotterySherdSpells.DOUBLE_NEXT_PREFIX.length());
            String[] parts = afterPrefix.split("\\|", 2);
            doubleDamageNextAttack = true;
            if (parts.length > 1) sendMessage(parts[1]);
        }
        else {
            sendMessage(result);
        }

        List<CombatEntity> deadEnemies = enemies.stream()
            .filter(e -> !e.isAlive() && e.getMobEntity() != null && e.getMobEntity().isAlive())
            .toList();
        for (CombatEntity dead : deadEnemies) {
            sendMessage("§a" + dead.getDisplayName() + " defeated!");
            sendToAllParty(new CombatEventPayload(
                CombatEventPayload.EVENT_DIED, dead.getEntityId(), 0, 0,
                dead.getGridPos().x(), dead.getGridPos().z()
            ));
            killEnemy(dead);
        }

        if (!anyEnemyBlockingVictory()) {
            handleVictory();
            return;
        }

        // Performative (hoe): replay the whole cast once, for free. Re-entering the method (rather
        // than just re-running useSherd) means the encore's own damage, deaths and prefix results
        // all resolve exactly like the first cast. The guard stops an encore from echoing itself.
        if (!sherdEncoreInProgress && HoeEnchantEffects.rollDoubleCast(player)) {
            HoeEnchantEffects.performativeVfx(player, (ServerWorld) player.getEntityWorld());
            sendMessage("§dPerformative! The cast echoes.");
            sherdEncoreInProgress = true;
            try {
                handleSherdSpell(targetTile, sherdItem, 0);
            } finally {
                sherdEncoreInProgress = false;
            }
            return; // the encore ran its own sync/highlight pass
        }

        sendSync();
        refreshHighlights();
    }

    // ===== Addon SDK -registered usable items ===============================

    /**
     * Handle use of an item registered in {@code UsableItemRegistry} (addon or JSON
     * datapack content). Validates AP and target, runs the item's handler through a
     * {@link UsableItemContextImpl}, then spends AP, consumes the item, and runs the
     * death/victory check. Built-in items never reach here -see {@link #handleUseItem}.
     */
    private void handleCustomUsableItem(GridPos targetTile,
            com.crackedgames.craftics.api.registry.UsableItemEntry entry) {
        int apCost = entry.apCost();
        if (apRemaining < apCost) {
            sendMessage("§cNeed " + apCost + " AP to use that! (have " + apRemaining + ")");
            return;
        }

        String targetError = validateCustomItemTarget(entry, targetTile);
        if (targetError != null) {
            sendMessage(targetError);
            sendSync();
            refreshHighlights();
            return;
        }

        UsableItemContextImpl ctx = new UsableItemContextImpl(targetTile, player.getMainHandStack());
        com.crackedgames.craftics.api.ItemUseResult result;
        try {
            result = entry.handler().use(ctx);
        } catch (Throwable t) {
            CrafticsMod.LOGGER.error("Usable item handler failed for {}", entry.item(), t);
            sendMessage("§cThat item fizzled.");
            return;
        }

        if (result == null || !result.success()) {
            if (result != null && result.failureMessage() != null) {
                sendMessage(result.failureMessage());
            }
            sendSync();
            refreshHighlights();
            return;
        }

        // Success -spend AP, consume the item, play the use sound.
        apRemaining -= apCost;
        if (entry.consumedOnUse() && !player.isCreative()) {
            player.getMainHandStack().decrement(1);
        }
        player.getWorld().playSound(null, player.getBlockPos(),
            net.minecraft.sound.SoundEvents.ENTITY_ITEM_PICKUP,
            net.minecraft.sound.SoundCategory.PLAYERS, 0.5f, 1.2f);

        // Death / victory check (mirrors handleSherdSpell).
        List<CombatEntity> deadEnemies = enemies.stream()
            .filter(e -> !e.isAlive() && e.getMobEntity() != null && e.getMobEntity().isAlive())
            .toList();
        for (CombatEntity dead : deadEnemies) {
            sendMessage("§a" + dead.getDisplayName() + " defeated!");
            sendToAllParty(new CombatEventPayload(
                CombatEventPayload.EVENT_DIED, dead.getEntityId(), 0, 0,
                dead.getGridPos().x(), dead.getGridPos().z()
            ));
            killEnemy(dead);
        }
        if (!anyEnemyBlockingVictory()) {
            handleVictory();
            return;
        }

        sendSync();
        refreshHighlights();
    }

    /** Validate a registered item's target against its TargetType and range. */
    private String validateCustomItemTarget(
            com.crackedgames.craftics.api.registry.UsableItemEntry entry, GridPos targetTile) {
        com.crackedgames.craftics.api.TargetType targetType = entry.targetType();
        if (targetType == com.crackedgames.craftics.api.TargetType.SELF) {
            return null;
        }
        if (targetTile == null || !arena.isInBounds(targetTile)) {
            return "§cInvalid target.";
        }
        if (entry.range() > 0) {
            int dist = arena.getPlayerGridPos().manhattanDistance(targetTile);
            if (dist > entry.range()) {
                return "§cToo far -that item reaches " + entry.range() + " tile(s).";
            }
        }
        CombatEntity occupant = arena.getOccupant(targetTile);
        switch (targetType) {
            case SINGLE_ENEMY -> {
                if (occupant == null || !occupant.isAlive() || occupant.isAlly()) {
                    return "§cThat item needs an enemy target.";
                }
            }
            case SINGLE_ALLY -> {
                // isMountWall excluded: the netherite mount's wall sentinel is flagged
                // isAlly() to block enemies but is not a real ally target.
                if (occupant == null || !occupant.isAlive() || !occupant.isAlly() || occupant.isMountWall()) {
                    return "§cThat item needs an allied target.";
                }
            }
            default -> { /* ANY_TILE, AOE -any in-range tile is valid */ }
        }
        return null;
    }

    /**
     * Tick every custom (addon-registered) status effect on {@code e}: apply its
     * per-turn HP change (scaled by amplifier), run its scripted handler, decrement,
     * and expire at zero turns. Called from the per-round DOT processing.
     */
    private void tickCustomEffects(CombatEntity e) {
        java.util.Iterator<java.util.Map.Entry<String, int[]>> it =
            e.getCustomEffects().entrySet().iterator();
        while (it.hasNext()) {
            java.util.Map.Entry<String, int[]> entry = it.next();
            com.crackedgames.craftics.api.CustomEffectDef def =
                com.crackedgames.craftics.api.registry.CombatEffectRegistry.get(entry.getKey());
            if (def == null) {
                it.remove(); // effect no longer registered (datapack removed on /reload)
                continue;
            }
            int[] state = entry.getValue(); // [turnsRemaining, amplifier]
            int amplifier = state[1];
            int hpChange = def.hpChangePerTurn() * (amplifier + 1);
            if (hpChange < 0) {
                int dealt = applyStatusDot(e, -hpChange);
                sendMessage(def.colorCode() + e.getDisplayName() + " suffers " + dealt
                    + " from " + def.displayName() + ".");
            } else if (hpChange > 0) {
                e.heal(hpChange);
            }
            if (def.tickHandler() != null) {
                try {
                    def.tickHandler().onTick(e, amplifier, state[0]);
                } catch (Throwable t) {
                    CrafticsMod.LOGGER.error("Custom effect tick handler failed for {}", def.id(), t);
                }
            }
            state[0]--;
            if (state[0] <= 0 || !e.isAlive()) {
                it.remove();
            }
        }
    }

    /** {@code UsableItemContext} implementation backed by this combat session. */
    private final class UsableItemContextImpl implements com.crackedgames.craftics.api.UsableItemContext {
        private final GridPos targetPos;
        private final ItemStack stack;

        UsableItemContextImpl(GridPos targetPos, ItemStack stack) {
            this.targetPos = targetPos;
            this.stack = stack;
        }

        @Override public ServerPlayerEntity player() { return player; }
        @Override public GridArena arena() { return arena; }
        @Override public GridPos targetPos() {
            return targetPos != null ? targetPos : arena.getPlayerGridPos();
        }
        @Override public CombatEntity targetEntity() {
            return targetPos != null ? arena.getOccupant(targetPos) : null;
        }
        @Override public ItemStack stack() { return stack; }
        @Override public List<CombatEntity> combatants() { return enemies; }

        @Override public int damage(CombatEntity target, int amount) {
            return target.takeDamage(amount);
        }
        @Override public void healPlayer(int amount) {
            player.setHealth(Math.min(player.getMaxHealth(), player.getHealth() + amount));
        }
        @Override public void healEntity(CombatEntity entity, int amount) {
            entity.heal(amount);
        }

        @Override public boolean captureEntity(CombatEntity target) {
            // Refused for allies and for anything already off the field. Capturing your own
            // ally would delete it from the fight with no way to get it back, and a double
            // call on the same target would otherwise report success twice for one creature.
            if (target == null || target.isAlly() || !enemies.contains(target)) return false;
            String name = target.getDisplayName();
            discardRestoredEntity(target);
            sendMessage("§a" + name + " was captured!");
            sendSync();
            return true;
        }

        @Override public void applyPlayerEffect(CombatEffects.EffectType type, int turns, int amplifier) {
            applyPlayerEffectLive(combatEffects, player != null ? player.getUuid() : null, type, turns, amplifier);
        }
        @Override public void applyEffect(CombatEntity target, CombatEffects.EffectType type,
                                          int turns, int amplifier) {
            applyEffectTo(target, type, turns, amplifier);
        }
        @Override public void applyCustomEffect(CombatEntity target, String effectId,
                                                int turns, int amplifier) {
            if (com.crackedgames.craftics.api.registry.CombatEffectRegistry.get(effectId) == null) {
                CrafticsMod.LOGGER.warn("applyCustomEffect: no effect registered with id '{}'", effectId);
                return;
            }
            target.applyCustomEffect(effectId, turns, amplifier);
        }

        @Override public void stun(CombatEntity target) {
            target.setStunned(true);
        }
        @Override public void knockback(CombatEntity target, int distance) {
            GridPos playerPos = arena.getPlayerGridPos();
            int dx = Integer.signum(target.getGridPos().x() - playerPos.x());
            int dz = Integer.signum(target.getGridPos().z() - playerPos.z());
            if (dx == 0 && dz == 0) dx = 1;
            GridPos kbPos = target.getGridPos();
            boolean intoVoid = false;
            for (int step = 0; step < distance; step++) {
                GridPos next = new GridPos(kbPos.x() + dx, kbPos.z() + dz);
                if (!arena.isInBounds(next) || arena.isOccupied(next)) break;
                GridTile tile = arena.getTile(next);
                if (tile == null) break;
                // A pit (VOID) is a valid landing spot: push the target onto it and let it
                // fall in, rather than treating it as an impassable wall. Hazard-immune
                // (flying) mobs are stopped at the rim like any other non-walkable tile.
                if (tile.getType() == TileType.VOID && !target.isHazardImmune()) {
                    kbPos = next;
                    intoVoid = true;
                    break;
                }
                if (!tile.isWalkable()) break;
                kbPos = next;
            }
            if (!kbPos.equals(target.getGridPos())) {
                arena.moveEntity(target, kbPos);
                if (target.getMobEntity() != null) {
                    BlockPos bp = arena.gridToBlockPos(kbPos);
                    target.getMobEntity().requestTeleport(bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5);
                }
                if (intoVoid) checkEnemyFallDeath(target);
            }
        }
        @Override public void teleportPlayer(GridPos pos) {
            // Enforce the documented contract: never drop the player onto an
            // occupied or non-walkable tile. isOccupied covers every footprint tile
            // of a sized mob, so this also stops a teleport from landing the player
            // inside a 2x2 magma cube / spider. Silently no-op on an invalid target
            // rather than clipping the player into a mob or a wall.
            if (!arena.isInBounds(pos) || arena.isOccupied(pos)) return;
            var destTile = arena.getTile(pos);
            if (destTile == null || !destTile.isWalkable()) return;
            arena.setPlayerGridPos(pos);
            BlockPos bp = arena.gridToBlockPos(pos);
            player.requestTeleport(bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5);
            broadcastPlayerPositionToOthers(player);
        }

        @Override public void placeTileEffect(GridPos pos, String effectType) {
            tileEffects.put(pos, effectType);
        }

        @Override public void message(String text) {
            sendMessage(text);
        }
    }

    /** Where each party member stood when their current turn began - the echo shard's anchor. */
    private final java.util.Map<java.util.UUID, GridPos> turnStartGridPos = new java.util.HashMap<>();

    /** Members who spent an echo shard this turn and snap back to their anchor when it ends. */
    private final java.util.Set<java.util.UUID> echoReturnArmed = new java.util.HashSet<>();

    /**
     * Echo shard payoff: snap the acting player back to the tile they started the turn on.
     * Charge in, swing, and rewind out of reach - the shard buys a free disengage rather than
     * a second move budget. Silently no-ops if the anchor is gone, blocked, or already home.
     */
    private void resolveEchoReturn() {
        if (player == null || arena == null) return;
        if (!echoReturnArmed.remove(player.getUuid())) return;

        GridPos anchor = turnStartGridPos.get(player.getUuid());
        if (anchor == null || !arena.isInBounds(anchor)) {
            sendMessage("§5The echo fades - there's nothing to return to.");
            return;
        }
        if (anchor.equals(arena.getPlayerGridPos())) {
            sendMessage("§5The echo settles - you never left.");
            return;
        }
        GridTile dest = arena.getTile(anchor);
        if (dest == null || !dest.isWalkable() || arena.isOccupied(anchor)) {
            sendMessage("§5The echo can't reach - something holds the ground you started on.");
            return;
        }

        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos from = player.getBlockPos();
        arena.setPlayerGridPos(anchor);
        BlockPos to = arena.gridToBlockPos(anchor);
        player.requestTeleport(to.getX() + 0.5, arena.getEntityY(anchor), to.getZ() + 0.5);
        player.setVelocity(0, 0, 0);
        player.velocityModified = true;
        player.fallDistance = 0;
        broadcastPlayerPositionToOthers(player);

        world.spawnParticles(net.minecraft.particle.ParticleTypes.SCULK_SOUL,
            from.getX() + 0.5, from.getY() + 1.0, from.getZ() + 0.5, 18, 0.3, 0.5, 0.3, 0.02);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.SCULK_SOUL,
            to.getX() + 0.5, to.getY() + 1.0, to.getZ() + 0.5, 18, 0.3, 0.5, 0.3, 0.02);
        world.playSound(null, to, net.minecraft.sound.SoundEvents.BLOCK_SCULK_CATALYST_BLOOM,
            net.minecraft.sound.SoundCategory.PLAYERS, 0.9f, 1.1f);
        sendMessage("§5Echo! You snap back to (" + anchor.x() + "," + anchor.z() + ").");
        sendSync();
        refreshHighlights();
    }

    private void handleEndTurn() {
        resolveEchoReturn();
        turnIdleTicks = 0; // the turn is ending; the next holder starts fresh
        if (!killedThisTurn && killStreak > 0) {
            killStreak = 0;
            sendSync();
        }
        killedThisTurn = false;


        // Lazy init: party members register AFTER startCombat, so the queue may be empty on first use
        if (partyPlayers.size() > 1 && turnQueue.size() <= 1) {
            rebuildTurnQueue();
        }
        if (turnQueue.size() > 1) {
            currentTurnIndex++;
            if (currentTurnIndex < turnQueue.size()) {
                switchToTurnPlayer();
                return;
            }
            // All players acted -fall through to enemy turn
            currentTurnIndex = 0;
        }

        tickBossWarnings();
        startEnemyTurn();
    }

    /**
     * The current player's jump behavior, from their movement enchantments: Pole Vault (held
     * blunt weapon) makes jumps cost the plain walk and lets them clear enemy-occupied tiles;
     * Longstride (worn leggings) widens the clearable gap to 3. The client builds the same
     * profile from the same stacks in ClientGridHelper - keep the two in step.
     */
    private Pathfinding.JumpProfile playerJumpProfile() {
        if (player == null) return Pathfinding.JumpProfile.DEFAULT;
        boolean poleVault = CrafticsEnchantments.heldLevel(player, CrafticsEnchantments.POLE_VAULT) > 0;
        boolean longstride = CrafticsEnchantments.wornLevel(player, CrafticsEnchantments.LONGSTRIDE) > 0;
        if (!poleVault && !longstride) return Pathfinding.JumpProfile.DEFAULT;
        return new Pathfinding.JumpProfile(
            longstride ? SwordAxeEnchantEffects.LONGSTRIDE_MAX_GAP : Pathfinding.MAX_JUMP_GAP,
            poleVault, poleVault);
    }

    /** Display name for a Momentum recipient, falling back to "a party member" if offline. */
    private String momentumNameOf(java.util.UUID uuid) {
        for (ServerPlayerEntity member : partyPlayers) {
            if (member != null && member.getUuid().equals(uuid)) {
                return member.getName().getString();
            }
        }
        return "a party member";
    }

    /**
     * Pay out any Momentum AP banked for the player whose turn is starting, and re-arm the
     * once-per-turn proc. Called from every turn-start AP reset, right after the AP formula.
     */
    private int consumePendingMomentumAp() {
        // Per-turn enchant state rides the same turn-start call: Momentum re-arms, Phantom
        // Edge gets its stealth-preserved attacks back, Tag Team's free swap resets.
        // The echo shard's anchor is stamped here too - this is the one place every
        // turn-start path (round start, co-op turn switch) reliably passes through.
        if (player != null && arena != null) {
            turnStartGridPos.put(player.getUuid(), arena.getPlayerGridPos());
        }
        momentumProcThisTurn = false;
        phantomEdgeUsesThisTurn = 0;
        tagTeamUsedThisTurn = false;
        // Trailblazer: the wearer's OWN old trail expires as their new turn begins - it lives
        // exactly one rotation, so everyone after them in the order could follow it.
        playerTrails.remove(player.getUuid());
        Integer banked = pendingMomentumAp.remove(player.getUuid());
        if (banked != null && banked > 0) {
            sendMessage("§eMomentum! +" + banked + " AP this turn.");
            return banked;
        }
        return 0;
    }

    /**
     * Return one tile to plain biome floor: grid type, floor block, any registered tile
     * effect or light zone, and the burn cycle. THE reset every "this tile is no longer
     * water / fire / a pit" path runs.
     *
     * <p>Split out because the grid half and the world half have to happen together. A
     * caller that only reached the grid model (the sponge's drain lived in ItemUseHandler)
     * flipped the TYPE and left the fluid block standing, so the arena showed water on a
     * tile the rules treated as dry ground.
     */
    private void resetTileToFloor(GridPos pos) {
        if (pos == null || arena == null || player == null) return;
        GridTile tile = arena.getTile(pos);
        if (tile != null) {
            tile.setType(TileType.NORMAL);
            tile.setBlockType(getBiomeFloorBlock());
        }
        tileEffects.remove(pos);
        unregisterLightZone(pos);
        burningTiles.remove(pos);
        // gridToBlockPos is Y+1 overlay space; restore floor on Y and clear overlay
        BlockPos bp = arena.gridToBlockPos(pos);
        ServerWorld sw = (ServerWorld) player.getEntityWorld();
        sw.setBlockState(bp, net.minecraft.block.Blocks.AIR.getDefaultState());
        sw.setBlockState(bp.down(), tile != null
            ? tile.getBlockType().getDefaultState()
            : getBiomeFloorBlock().getDefaultState());
    }

    /**
     * Terraform (hoe): a successful tile-targeted Special cast also normalizes hostile terrain
     * at the target - douses FIRE, drains WATER, fills LOW_GROUND. Works from the tile's
     * PRE-cast type, and skips casts that explicitly reshape the tile themselves (a TILE:
     * result), so a lava or water bucket's fresh terrain is never erased by its own cast.
     * Mirrors the empty-bucket "clear" dispatch: overlay space is gridToBlockPos (Y+1), the
     * real floor is one below.
     */
    private void applyTerraform(GridPos targetTile, TileType priorType, String castResult) {
        if (targetTile == null || arena == null || priorType == null || player == null) return;
        if (castResult != null && castResult.startsWith(ItemUseHandler.TILE_EFFECT_PREFIX)) return;
        if (!priorType.isFlames() && priorType != TileType.WATER
                && priorType != TileType.LOW_GROUND) return;
        if (CrafticsEnchantments.level(player, CrafticsEnchantments.TERRAFORM) <= 0) return;
        GridTile tile = arena.getTile(targetTile);
        if (tile == null || tile.getType() != priorType) return; // the cast already changed it

        tile.setType(TileType.NORMAL);
        tile.setBlockType(getBiomeFloorBlock());
        tileEffects.remove(targetTile);
        unregisterLightZone(targetTile);
        BlockPos bp = arena.gridToBlockPos(targetTile);
        ServerWorld sw = (ServerWorld) player.getEntityWorld();
        sw.setBlockState(bp, net.minecraft.block.Blocks.AIR.getDefaultState());
        sw.setBlockState(bp.down(), tile.getBlockType().getDefaultState());

        String what = switch (priorType) {
            case FIRE, SOUL_FIRE -> "The flames are doused";
            case WATER -> "The water drains away";
            default -> "The sunken ground fills in";
        };
        // Terraform douses a burn outright, so the tile must leave the burn cycle too -
        // otherwise the state machine would repaint magma over the ground it just cleared.
        burningTiles.remove(targetTile);
        sw.spawnParticles(net.minecraft.particle.ParticleTypes.COMPOSTER,
            bp.getX() + 0.5, bp.getY() + 0.5, bp.getZ() + 0.5, 14, 0.35, 0.3, 0.35, 0.05);
        sw.playSound(null, bp, net.minecraft.sound.SoundEvents.ITEM_HOE_TILL,
            net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 1.0f);
        sendMessage("§aTerraform! " + what + ".");
    }

    /**
     * Spring any Trapper trap an enemy is standing on: apply the buried potion to it with
     * the exact splash-potion ruleset. Scanned each enemy-turn tick and after knockback, so
     * both walking onto a trap and being SHOVED onto one springs it.
     */
    private void springTrapperTraps() {
        if (trapperTraps.isEmpty() || arena == null || player == null) return;
        var it = trapperTraps.entrySet().iterator();
        while (it.hasNext()) {
            var entry = it.next();
            CombatEntity victim = arena.getOccupant(entry.getKey());
            if (victim == null || !victim.isAlive() || victim.isAlly()) continue;
            it.remove();
            TrapperTrap trap = entry.getValue();
            var contents = trap.potion().get(DataComponentTypes.POTION_CONTENTS);
            ServerPlayerEntity owner = resolveAllyOwner(trap.owner());
            StringBuilder msg = new StringBuilder();
            if (contents != null && owner != null) {
                ItemUseHandler.applyPotionEffectsToEnemies(owner, java.util.List.of(victim), contents, msg);
            }
            ServerWorld sw = (ServerWorld) player.getEntityWorld();
            BlockPos bp = arena.gridToBlockPos(entry.getKey());
            ProjectileSpawner.spawnPotionSplash(sw, bp, false);
            sw.playSound(null, bp, net.minecraft.sound.SoundEvents.ENTITY_SPLASH_POTION_BREAK,
                net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 1.0f);
            sendMessage("§2Trap sprung! " + msg.toString().trim());
            checkAndHandleDeath(victim);
        }
    }

    /**
     * Hand a new round to the first player in the turn queue.
     *
     * <p>Every path that opens a player round has to do this, and the two that skip the
     * enemy phase entirely - the Phantom set bonus and the raid prep turn - used to go
     * straight to {@code PLAYER_TURN} without it. That left the fight in a state no input
     * could get out of: {@code currentTurnIndex} had already been wound back to 0 by
     * {@link #handleEndTurn}, so the clients were told it was the first player's turn,
     * while {@code this.player} was still whoever ended the round. The action guard only
     * accepts {@code this.player}, so the first player's input was rejected and the last
     * player's client never offered the button - nobody could act and nobody could pass.
     * The AFK watchdog could not rescue it either, because it only runs during a turn it
     * believes somebody holds.
     *
     * <p>The raid hit this every single time: its prep turn fires on turn 1, immediately
     * after the first full round of a party fight.
     *
     * <p>Solo fights are unaffected - with no queue there is nobody to hand off to.
     */
    private void handOffRoundToFirstPartyPlayer() {
        if (partyPlayers.size() <= 1) return;
        rebuildTurnQueue();
        if (turnQueue.isEmpty()) return;
        currentTurnIndex = 0;
        java.util.UUID firstUuid = turnQueue.get(0);
        for (ServerPlayerEntity member : partyPlayers) {
            if (member.getUuid().equals(firstUuid)) { this.player = member; break; }
        }
        retargetEffectsToCurrentPlayer();
        if (arena != null) {
            net.minecraft.util.math.BlockPos qOrigin = arena.getOrigin();
            net.minecraft.util.math.BlockPos qBlock = player.getBlockPos();
            arena.setPlayerGridPos(new GridPos(
                qBlock.getX() - qOrigin.getX(),
                qBlock.getZ() - qOrigin.getZ()
            ));
        }
    }

    private void rebuildTurnQueue() {
        turnQueue.clear();
        pendingMomentumAp.clear();
        midasPaidEnemies.clear();
        trapperTraps.clear();
        ledgegripUsed.clear();
        grudgeTargets.clear();
        playerTrails.clear();
        for (ServerPlayerEntity member : partyPlayers) {
            if (member != null && !member.isRemoved() && !member.isDisconnected()
                    && !deadPartyMembers.contains(member.getUuid())) {
                turnQueue.add(member.getUuid());
            }
        }
        currentTurnIndex = 0;
    }

    private void switchToTurnPlayer() {
        if (turnQueue.isEmpty()) return;
        java.util.UUID nextUuid = turnQueue.get(currentTurnIndex);
        ServerPlayerEntity nextPlayer = null;
        for (ServerPlayerEntity member : partyPlayers) {
            if (member.getUuid().equals(nextUuid)) { nextPlayer = member; break; }
        }
        if (nextPlayer == null || nextPlayer.isRemoved() || nextPlayer.isDisconnected()) {
            turnQueue.remove(currentTurnIndex);
            if (currentTurnIndex >= turnQueue.size()) {
                currentTurnIndex = 0;
                tickBossWarnings();
                startEnemyTurn();
                return;
            }
            switchToTurnPlayer();
            return;
        }

        this.player = nextPlayer;
        turnIdleTicks = 0; // fresh turn for the next player
        retargetEffectsToCurrentPlayer();

        if (arena != null) {
            net.minecraft.util.math.BlockPos origin = arena.getOrigin();
            net.minecraft.util.math.BlockPos pBlock = player.getBlockPos();
            arena.setPlayerGridPos(new GridPos(
                pBlock.getX() - origin.getX(),
                pBlock.getZ() - origin.getZ()
            ));
        }

        // Scan the incoming player's equipment BEFORE the AP/speed block so trim and
        // addon (e.g. Artifacts) bonuses actually feed it. The scan used to run after
        // the stats were already computed - and the trim AP/SPEED bonuses were never
        // added at all - so every party member after the first silently lost their
        // trim/artifact bonuses on turn switch.
        this.activeTrimScan = TrimEffects.scan(player);
        this.activeCombatEffects = activeTrimScan.getCombatEffects();
        if (effectContext != null) effectContext.update(player, arena, combatEffects, activeTrimScan);

        PlayerProgression turnProg = PlayerProgression.get((ServerWorld) player.getEntityWorld());
        PlayerProgression.PlayerStats turnStats = turnProg.getStats(player);
        apRemaining = Math.max(0, turnStats.getEffective(PlayerProgression.Stat.AP)
            + PlayerCombatStats.getSetApBonus(player)
            + activeTrimScan.get(TrimEffects.Bonus.AP)
            + combatEffects.getHasteBonus()            // Haste: +1 AP per level
            - combatEffects.getMiningFatiguePenalty()); // Mining Fatigue: -1 AP per level
        apRemaining += consumePendingMomentumAp();
        movePointsRemaining = baseSpeedStat(turnStats)
            + combatEffects.getSpeedBonus() - combatEffects.getSpeedPenalty()
            + PlayerCombatStats.getSetSpeedBonus(player)
            + activeTrimScan.get(TrimEffects.Bonus.SPEED)
            - combatEffects.getLevitationPenalty();    // Levitation: -1 movement per level
        if (combatEffects.hasEffect(CombatEffects.EffectType.SOAKED)) {
            movePointsRemaining = Math.max(1, movePointsRemaining - 1);
        }
        movePointsRemaining = Math.max(0, movePointsRemaining);

        // Fresh acting player -reset the per-turn trackers spear momentum and the
        // shield rule depend on, so one party member's turn never bleeds into the next.
        tilesMovedThisTurn = 0;
        attackedWithoutShieldThisTurn = false;

        player.getWorld().playSound(null, player.getBlockPos(),
            net.minecraft.sound.SoundEvents.BLOCK_NOTE_BLOCK_CHIME.value(),
            net.minecraft.sound.SoundCategory.PLAYERS, 0.8f, 1.2f);
        sendMessage("§e" + player.getName().getString() + "'s turn! §aAP: " + apRemaining + " | SPD: " + movePointsRemaining);
        fireEffectHook(h -> h.onTurnStart(effectContext));

        // Rebuild the netherite mount's 1×3 wall for the new player turn so it stays
        // visible and keeps following the rider. It no longer blocks the rider's own
        // movement (Pathfinding treats the mount-wall sentinel as passable for self==null),
        // so it can persist through the player's turn instead of being cleared.
        refreshMountWall();

        // Hazard tile damage at turn start. While mounted the player rides above the
        // tile, so lava and powder snow can't reach them (see mount immunity).
        GridTile turnTile = arena.getTile(arena.getPlayerGridPos());
        if (turnTile != null) {
            if (turnTile.getType() == com.crackedgames.craftics.core.TileType.LAVA && !playerMounted
                    && !combatEffects.hasFireResistance()
                    && !PlayerCombatStats.wearsHead(player, Items.PIGLIN_HEAD)) {
                int lavaDmg = damagePlayerFromTile(10, null);
                sendMessage("§6  Standing in lava! " + lavaDmg + " damage! (HP: " + getPlayerHp() + ")");
                if (getPlayerHp() <= 0) { sendSync(); handlePlayerDeathOrGameOver(); return; }
            } else if (turnTile.getType().isFlames()
                    && !combatEffects.hasFireResistance()
                    && !PlayerCombatStats.wearsHead(player, Items.PIGLIN_HEAD)) {
                // Standing in the flames sets you alight instead of dealing flat damage -
                // the burn is the threat, and staying put extends it turn after turn.
                applyFireTileBurnToPlayer(turnTile.getType());
            }

            if (turnTile.getType() == com.crackedgames.craftics.core.TileType.POWDER_SNOW
                    && !hasLeatherBoots() && !playerMounted) {
                powderSnowTurns++;
                int freezeDmg = (int) Math.pow(2, powderSnowTurns - 1); // 1, 2, 4, 8, 16...
                int actual = damagePlayerFromTile(freezeDmg, null);
                sendMessage("§b  Freezing! " + actual + " damage! (Turn " + powderSnowTurns + " in snow)");
                if (getPlayerHp() <= 0) { sendSync(); handlePlayerDeathOrGameOver(); return; }
            } else {
                powderSnowTurns = 0; // reset off snow, with boots, or while mounted
            }
        }

        sendSync();
        refreshHighlights();
    }

    /**
     * The ONE room-clear test. Every victory check routes through this, so a new attackable object
     * only has to set {@link CombatEntity#setScenery} once instead of being special-cased at every
     * call site.
     *
     * <p>Allies never block. Scenery never blocks: graves and war banners are optional counterplay,
     * not chores. Egg sacs are NOT scenery and still block, which is deliberate.
     */
    private boolean anyEnemyBlockingVictory() {
        return anyEnemyBlockingVictory(null);
    }

    /**
     * As {@link #anyEnemyBlockingVictory()}, but ignores {@code excluded}. Used on the death path,
     * where the dying entity is still in {@code enemies} and still reads as alive but must not count
     * itself as the reason the room has not cleared.
     */
    private boolean anyEnemyBlockingVictory(CombatEntity excluded) {
        if (enemies == null) return false;
        for (CombatEntity e : enemies) {
            if (e == excluded) continue;
            if (e.blocksRoomClear()) return true;
        }
        return false;
    }

    /**
     * Anti-farming guard, evaluated once per round at the player→enemy boundary.
     * <p>
     * If the arena still has living enemies but every one of them is currently
     * non-threatening (passive animals, or neutral mobs the player hasn't
     * provoked) AND the player scored no kill this round, count an "idle" round.
     * After {@link #ANTI_FARM_IDLE_LIMIT} consecutive idle rounds the fight ends
     * automatically so the player can't sit in a room full of harmless mobs
     * farming fish, taming, or other free resources forever.
     * <p>
     * Any kill, any provoked/hostile mob, or an empty arena resets the counter.
     *
     * @return true if this method ended combat (caller must stop processing).
     */
    private boolean checkAntiFarmAutoEnd() {
        boolean killedLastRound = killedThisRound;
        killedThisRound = false;

        if (enemies == null) return false;

        // Grace period: don't even start counting idle rounds until enough rounds
        // have passed, so the player has time to fight before the auto-end can
        // trigger. killedThisRound is still consumed above each round.
        if (turnNumber <= ANTI_FARM_GRACE_ROUNDS) {
            antiFarmIdleRounds = 0;
            return false;
        }

        boolean anyEnemyAlive = false;
        boolean anyThreat = false;
        GridPos playerPos = arena != null ? arena.getPlayerGridPos() : null;
        for (CombatEntity e : enemies) {
            // Same room-clear rule as the victory checks. Scenery (graves, hives, banners) is not
            // a "living enemy" for this purpose, and it must not read as a threat either: a grave
            // resolves an AI whose isHostileThreat defaults to true, which would hold the idle
            // counter at zero forever and strand the player in a room of harmless mobs.
            if (!e.blocksRoomClear()) continue;
            anyEnemyAlive = true;
            EnemyAI ai = resolveAi(e);
            // No AI resolved → treat as a threat (fail safe; never auto-end on it).
            if (ai == null || playerPos == null || ai.isHostileThreat(e, arena, playerPos)) {
                anyThreat = true;
                break;
            }
        }

        // Made progress, faced a real threat, or the room is already empty: not idle.
        if (killedLastRound || anyThreat || !anyEnemyAlive) {
            antiFarmIdleRounds = 0;
            return false;
        }

        antiFarmIdleRounds++;
        int remaining = ANTI_FARM_IDLE_LIMIT - antiFarmIdleRounds;
        if (remaining > 0) {
            sendMessage("§7The remaining creatures are harmless. Move on or this fight ends in "
                + remaining + " turn" + (remaining == 1 ? "" : "s") + ".");
            return false;
        }

        // Idle limit reached -finish the room. The harmless stragglers are simply
        // left behind (they vanish with the arena on level transition); we don't
        // force-kill them, which would hand out kill XP / loot for not fighting.
        antiFarmIdleRounds = 0;
        sendMessage("§e§lNothing left to fight -moving on!");
        handleVictory();
        return true;
    }

    // ── Mid-fight save points (leave and rejoin) ─────────────────────────────

    /**
     * The record a snapshot is filed under and keyed by: the fight leader's. Their run cursor
     * ({@code activeBiomeId} + {@code activeBiomeLevelIndex}) is the pair the level was built
     * from, and the same pair a re-entry resolves before it asks for a snapshot back.
     */
    private CrafticsSavedData.PlayerData resumeCursorOwner(CrafticsSavedData data) {
        java.util.UUID key = leaderUuid != null
            ? leaderUuid
            : (player != null ? player.getUuid() : null);
        return key == null ? null : data.getPlayerData(key);
    }

    /**
     * Write a save point for this level: the roster, everyone's health and effects, and where
     * everything stood. Called once per player turn (see the edge trigger in {@link #tick}).
     *
     * <p>This is what stops a level from being healed out of. Leaving a fight used to discard it
     * entirely, so a player could go home, top up, and get the level rebuilt at full health; now
     * whichever way they leave, the last completed turn is already on disk.
     *
     * <p>Skipped for raid bosses and dev arenas: neither has a run cursor to file under, and
     * neither is a level anyone can re-enter.
     */
    private void captureResumeSnapshot() {
        if (!active || arena == null || player == null) return;
        if (raidBossContext != null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        CrafticsSavedData data = CrafticsSavedData.get(world);
        CrafticsSavedData.PlayerData lead = resumeCursorOwner(data);
        if (lead == null || !lead.isInBiomeRun()) return;

        List<ResumeSnapshot.PlayerState> playerStates = new ArrayList<>();
        for (ServerPlayerEntity p : getAllParticipants()) {
            if (p == null || p.isRemoved()) continue;
            // A fallen member is revived at the next level regardless, so recording them at 0 HP
            // would only produce a record the restore has to throw away.
            if (deadPartyMembers.contains(p.getUuid())) continue;
            GridPos g = gridPosOf(p);
            List<ResumeSnapshot.EffectState> fx = new ArrayList<>();
            CombatEffects pfx = playerCombatEffects.get(p.getUuid());
            if (pfx != null) {
                for (var entry : pfx.getAll().entrySet()) {
                    CombatEffects.ActiveEffect eff = entry.getValue();
                    // Frozen effects are hub-applied ones whose clock has not started. The next
                    // combat start re-freezes those from the player's own buffs, so carrying them
                    // through a resume would double them up.
                    if (eff == null || eff.isFrozen()) continue;
                    fx.add(new ResumeSnapshot.EffectState(
                        entry.getKey().name(), eff.turnsRemaining, eff.amplifier));
                }
            }
            playerStates.add(new ResumeSnapshot.PlayerState(p.getUuid(), p.getHealth(),
                p.getHungerManager().getFoodLevel(), p.getHungerManager().getSaturationLevel(),
                g.x(), g.z(), fx));
        }

        List<ResumeSnapshot.EnemyState> roster = new ArrayList<>();
        if (enemies != null) {
            for (CombatEntity e : enemies) {
                if (e == null || !e.isAlive()) continue;
                roster.add(ResumeSnapshot.capture(e));
            }
        }

        ResumeSnapshot.Snapshot snap = new ResumeSnapshot.Snapshot(System.currentTimeMillis(),
            lead.activeBiomeId, lead.activeBiomeLevelIndex, turnNumber, playerStates, roster);
        // Filed on every participant's OWN record, not just the leader's: a member who rejoins
        // alone still has the state, and nothing has to resolve a host who may be offline.
        for (ServerPlayerEntity p : getAllParticipants()) {
            if (p == null) continue;
            CrafticsSavedData.PlayerData pd = data.getPlayerData(p.getUuid());
            pd.resumeSnapshots = ResumeSnapshot.push(pd.resumeSnapshots, snap);
        }
        data.markDirty();
    }

    /**
     * Resume this level from its newest save point, if one is still good for it. Call right after
     * the party is in the arena and {@link #startCombat} has run; a no-op when there is nothing to
     * resume, which is every first entry into a level.
     *
     * <p>A save point older than {@link ResumeSnapshot#MAX_AGE_MILLIS} is not used: the player gets
     * the level they were on, rebuilt fresh, exactly as before this existed.
     */
    public void tryRestoreResumeSnapshot() {
        if (!active || arena == null || player == null) return;
        if (raidBossContext != null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        CrafticsSavedData data = CrafticsSavedData.get(world);
        CrafticsSavedData.PlayerData lead = resumeCursorOwner(data);
        if (lead == null || !lead.isInBiomeRun()) return;
        ResumeSnapshot.Snapshot snap = ResumeSnapshot.newestFor(lead.resumeSnapshots,
            lead.activeBiomeId, lead.activeBiomeLevelIndex, System.currentTimeMillis());
        if (snap == null) return;
        applyResumeSnapshot(snap);
    }

    /**
     * Put a save point back on the field.
     *
     * <p>The roster is reconciled rather than rebuilt wholesale, because what spawned an entity
     * decides how much of it a record can recreate:
     * <ul>
     *   <li><b>Bosses and allies</b> are matched to a record and have their state written onto the
     *       entity the fresh build already made. Their wiring is not in the record and cannot be: a
     *       boss carries its AI key, phase setup and display name, and a pet carries the owner link
     *       that decides whether the player still has it after the level.</li>
     *   <li><b>Plain hostiles</b> are cleared out and respawned from records, which is what carries
     *       mid-fight arrivals (raised zombies, split slimes, hive bees) back onto the field.</li>
     *   <li><b>Block-backed props</b> (graves, hives, banners, egg sacs) are left exactly as the
     *       fresh build placed them. They have no mob to respawn, and their world block and tile
     *       registration belong to the mechanic that placed them.</li>
     * </ul>
     *
     * <p>Not restored, by design: boss phase state, AI cooldowns, tile state (fire, ice, webs,
     * rubble) and mid-level event gates. {@code turnNumber} does come back, so everything keyed off
     * the turn counter (sudden death, the every-Nth-round hooks) resumes rather than restarts.
     */
    private void applyResumeSnapshot(ResumeSnapshot.Snapshot snap) {
        List<ResumeSnapshot.EnemyState> pending = new ArrayList<>();
        for (ResumeSnapshot.EnemyState rec : snap.enemies()) {
            if (rec.hasMob()) pending.add(rec);
        }

        for (CombatEntity e : new ArrayList<>(enemies)) {
            if (e == null || !e.isAlive()) continue;
            if (e.getMobEntity() == null) continue; // prop: the fresh build owns it
            // A linked entity counts as identity too: a Creaking only dies when its heart does,
            // and the link is minted by the level build. Respawning one from a record would put an
            // unkillable mob on the field and soft-lock the room.
            boolean identityMatters = e.isBoss() || e.isAlly()
                || e.getLinkedHeartId() >= 0 || e.getLinkedCreakingId() >= 0;
            ResumeSnapshot.EnemyState match = identityMatters ? takeResumeMatch(pending, e) : null;
            if (match != null) {
                restoreStateOnto(e, match);
            } else {
                // Either it was already dead when the player left, or it is a plain hostile that
                // the record loop below puts back with the HP and position it actually had.
                discardRestoredEntity(e);
            }
        }

        int respawned = 0;
        for (ResumeSnapshot.EnemyState rec : pending) {
            // A record left over here found no counterpart in the fresh build. For most mobs that
            // is exactly the case worth rebuilding (a mid-fight arrival), but not for these two:
            //  - a boss WITHOUT a recorded identity is more than its stats. Its AI key, phase
            //    setup, footprint and display name were established by the spawn path, and a bare
            //    mob wearing a boss's HP would stand there doing nothing. A boss whose aiKey WAS
            //    recorded is a different matter: that key is the whole of what the spawn path
            //    would have looked it up by, so rebuilding from it produces the same boss.
            //  - a Creaking dies only with its heart, and that link is minted by the level build.
            //    Spawning one from a record puts an unkillable mob in the room.
            // Dropping the record leaves the fight slightly easier, which beats either failure.
            if ((rec.boss() && !rec.hasIdentity()) || !isRestoreRespawnable(rec.typeId())) {
                CrafticsMod.LOGGER.info(
                    "Resume: not rebuilding '{}' from a save point (boss or level-wired entity)",
                    rec.typeId());
                continue;
            }
            // Footprint is deliberately left as the spawn path resolves it: placeEntity has
            // already registered tiles for that shape, and widening it afterwards would leave the
            // grid and the entity disagreeing about which tiles are occupied.
            CombatEntity ce = spawnRaidReinforcement(rec.typeId(), rec.gridPos(),
                Math.max(1, rec.maxHp()), rec.atk(), rec.def(), rec.range(),
                rec.hasIdentity() ? rec.aiKey() : null,
                rec.displayName().isEmpty() ? null : rec.displayName(),
                null);   // spawn NBT is not recorded; the customizer keyed on aiKey is
            if (ce == null) continue; // nowhere it fits any more; the room is that much easier
            if (rec.ally()) {
                ce.setAlly(true);
                if (rec.has('t')) ce.setTemporaryAlly(true);
                if (!rec.ownerUuid().isEmpty()) {
                    try {
                        ce.setOwnerUuid(java.util.UUID.fromString(rec.ownerUuid()));
                    } catch (IllegalArgumentException ignored) {
                        // The owner link is a nicety here; the ally still fights for the party.
                    }
                }
            }
            if (rec.has('g')) ce.setBackgroundBoss(true);
            ce.restoreHp(rec.curHp());
            ResumeSnapshot.applyStatus(ce, rec.status());
            respawned++;
        }

        for (ServerPlayerEntity p : getAllParticipants()) {
            if (p == null || p.isRemoved()) continue;
            ResumeSnapshot.PlayerState st = snap.playerState(p.getUuid());
            if (st == null) continue;
            if (st.health() > 0) {
                p.setHealth(Math.min(st.health(), p.getMaxHealth()));
            }
            p.getHungerManager().setFoodLevel(st.food());
            p.getHungerManager().setSaturationLevel(st.saturation());
            CombatEffects fx = playerCombatEffects.computeIfAbsent(
                p.getUuid(), k -> new CombatEffects());
            fx.clear();
            for (ResumeSnapshot.EffectState eff : st.effects()) {
                try {
                    fx.addEffect(CombatEffects.EffectType.valueOf(eff.type()),
                        eff.turns(), eff.amp());
                } catch (IllegalArgumentException ignored) {
                    // An effect this build no longer has. Dropping it beats refusing the resume.
                }
            }
            GridPos tile = st.gridPos();
            if (arena.isInBounds(tile) && arena.getOccupant(tile) == null) {
                GridTile gt = arena.getTile(tile);
                if (gt != null && gt.isWalkable()) {
                    BlockPos bp = arena.gridToBlockPos(tile);
                    p.requestTeleport(bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5);
                }
            }
        }
        arena.setPlayerGridPos(gridPosOf(player));

        // Resuming mid-fight means resuming the turn clock with it.
        this.turnNumber = Math.max(1, snap.turnNumber());
        // And this turn is already saved: without it the tick loop would immediately write the
        // state it just restored back over the older of the two save points.
        this.lastSnapshotTurn = this.turnNumber;

        sendMessage("§e↺ Picking up where you left off: §fturn " + turnNumber
            + "§e, " + countLivingHostiles() + " enemies still standing.");
        CrafticsMod.LOGGER.info(
            "Resumed {} level {} for {} at turn {} ({} recorded combatants, {} respawned)",
            snap.biomeId(), snap.levelIndex() + 1, player.getName().getString(),
            snap.turnNumber(), snap.enemies().size(), respawned);
        sendSync();
        refreshHighlights();
    }

    /**
     * Whether a save point may respawn this entity type at all. False for anything whose lethality
     * or behaviour is wired by the level build rather than carried in its stats: a Creaking is
     * killable only through its heart, so one spawned without that link never dies.
     */
    private static boolean isRestoreRespawnable(String typeId) {
        return !"minecraft:creaking".equals(typeId);
    }

    /** Living combatants that still have to be dealt with. Message text only. */
    private int countLivingHostiles() {
        int n = 0;
        if (enemies != null) {
            for (CombatEntity e : enemies) {
                if (e != null && e.blocksRoomClear()) n++;
            }
        }
        return n;
    }

    /**
     * Pull the record that describes {@code e} out of {@code pending}, or null if none does.
     * Matched on entity type plus side, because a stable per-entity id across a rebuild does not
     * exist (ids are minted by the spawn) and two zombies of the same type are interchangeable for
     * this purpose anyway.
     */
    private ResumeSnapshot.EnemyState takeResumeMatch(List<ResumeSnapshot.EnemyState> pending,
                                                      CombatEntity e) {
        // Identity first. Type plus side is enough to tell two zombies apart because two zombies
        // ARE interchangeable, but it is not enough for a mod that fields a whole roster under a
        // single entity type: every one of its creatures reads as the same typeId, so a gym
        // leader's Onix record would land on their Geodude and quietly restore the wrong HP and
        // the wrong status onto it. Where both sides name an aiKey, that key decides.
        ResumeSnapshot.EnemyState strict = takeResumeMatch(pending, e, true);
        return strict != null ? strict : takeResumeMatch(pending, e, false);
    }

    /**
     * @param requireIdentity when true, only a record whose {@code aiKey} equals the entity's own
     *                        matches - so an exact identity match is always preferred over a
     *                        record that merely shares an entity type
     */
    private ResumeSnapshot.EnemyState takeResumeMatch(List<ResumeSnapshot.EnemyState> pending,
                                                      CombatEntity e, boolean requireIdentity) {
        String liveKey = e.getAiOverrideKey();
        boolean liveHasKey = liveKey != null && !liveKey.isEmpty();
        for (int i = 0; i < pending.size(); i++) {
            ResumeSnapshot.EnemyState rec = pending.get(i);
            if (!rec.typeId().equals(e.getEntityTypeId())) continue;
            if (rec.ally() != e.isAlly()) continue;
            if (rec.boss() != e.isBoss()) continue;
            if (requireIdentity) {
                if (!liveHasKey || !rec.hasIdentity()) continue;
                if (!rec.aiKey().equals(liveKey)) continue;
            } else if (liveHasKey && rec.hasIdentity() && !rec.aiKey().equals(liveKey)) {
                // Both sides know who they are and they disagree. Falling back to a type match
                // here is exactly the collision this guards against.
                continue;
            }
            return pending.remove(i);
        }
        return null;
    }

    /** Write a record's health, status and tile onto an entity the fresh build already made. */
    private void restoreStateOnto(CombatEntity e, ResumeSnapshot.EnemyState rec) {
        // Max first, then current: a boss whose max HP moved mid-fight (stack layers, phase
        // changes) would otherwise clamp the restored current HP to the stale maximum.
        if (rec.maxHp() > 0) e.setMaxHp(rec.maxHp());
        e.restoreHp(rec.curHp());
        ResumeSnapshot.applyStatus(e, rec.status());
        GridPos tile = rec.gridPos();
        if (arena.isInBounds(tile) && !tile.equals(e.getGridPos())) {
            // A refused move leaves it where it spawned, which is a valid tile by construction.
            // Forcing it is how an entity ends up occupying no tiles at all.
            arena.moveEntity(e, tile);
        }
    }

    /** Take an entity off the field silently: no death, no loot, no XP, no kill credit. */
    private void discardRestoredEntity(CombatEntity e) {
        MobEntity mob = e.getMobEntity();
        if (mob != null) {
            clearStackPassengers(mob);
            if (!mob.isRemoved()) mob.discard();
        }
        arena.removeEntity(e);
        enemies.remove(e);
    }

    /**
     * Drop this level's save points. Called when the level stops being resumable: it was won, or
     * the run it belonged to ended in defeat. Without this a player who lost could walk back into
     * a level they had already left behind and resume a fight that is over.
     */
    private void clearResumeSnapshots() {
        if (player == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        List<java.util.UUID> ids = new ArrayList<>();
        for (ServerPlayerEntity p : getAllParticipants()) {
            if (p != null) ids.add(p.getUuid());
        }
        CrafticsSavedData.get(world).clearResumeSnapshots(ids);
    }

    private void startEnemyTurn() {
        fireEffectHook(h -> h.onTurnEnd(effectContext));
        // Age timed summons exactly once per round, BEFORE any early-return guard,
        // so a summon's lifespan stays accurate even when the enemy turn is skipped
        // (e.g. the PHANTOM set bonus below). Round-effect hooks (bee summon, hay
        // heal) still run only on the normal path, via runAllyRoundHooks() later.
        ageTimedSummons();
        // Raid waves march on the same once-per-round clock.
        tickRaidWaves();
        if (activeMiniboss != null) {
            minibossRound++;
            activeMiniboss.onRoundStart(buildMinibossCtx());
        }
        // Bee hives (player-placed and wild forest ones) release a bee each round.
        tickBeeHives();
        // Mid-biome weather (sandstorm, ...) pulses on the same round boundary, with its
        // own counter so it can't drift when a miniboss shares the level.
        if (activeBiomeEffect != null) {
            biomeEffectRound++;
            int saved = minibossRound;
            minibossRound = biomeEffectRound;   // ctx.round() reads this field
            activeBiomeEffect.onRoundStart(buildMinibossCtx());
            minibossRound = saved;
        }

        // Anti-farming: end the fight if the room holds only harmless mobs and the
        // player has made no progress for several rounds. Returns true when it took
        // over and ended combat, so we stop here.
        if (checkAntiFarmAutoEnd()) return;
        // PHANTOM set bonus: enemies don't act for the first 2 turns
        if (turnNumber <= 2 && activeTrimScan != null
                && activeTrimScan.setBonus() == TrimEffects.SetBonus.PHANTOM) {
            sendMessage("§5§l✦ Phantom! §r§7You are invisible -enemies skip their turn.");
            // Skip directly to new player turn
            turnNumber++;
            // The round still changes hands even though the enemies never acted.
            handOffRoundToFirstPartyPlayer();
            movedThisTurn = false;
            tilesMovedThisTurn = 0;
            attackedWithoutShieldThisTurn = false;
            PlayerProgression turnProg2 = PlayerProgression.get((ServerWorld) player.getEntityWorld());
            PlayerProgression.PlayerStats turnStats2 = turnProg2.getStats(player);
            apRemaining = Math.max(0, turnStats2.getEffective(PlayerProgression.Stat.AP)
                + PlayerCombatStats.getSetApBonus(player)
                + combatEffects.getHasteBonus()
                - combatEffects.getMiningFatiguePenalty());
            apRemaining += consumePendingMomentumAp();
            movePointsRemaining = turnStats2.getEffective(PlayerProgression.Stat.SPEED)
                + combatEffects.getSpeedBonus() - combatEffects.getSpeedPenalty()
                + PlayerCombatStats.getSetSpeedBonus(player)
                - combatEffects.getLevitationPenalty();
            if (combatEffects.hasEffect(CombatEffects.EffectType.SOAKED)) {
                movePointsRemaining = Math.max(1, movePointsRemaining - 1);
            }
            movePointsRemaining = Math.max(0, movePointsRemaining);
            phase = CombatPhase.PLAYER_TURN;
            sendSync();
            refreshHighlights();
            return;
        }

        // Raid prep turn: the opening pillager wave is placed on the field within crossbow
        // range in a cramped arena and - unlike every later wave, which telegraphs one round
        // ahead (see tickRaidWaves) - gets no warning. Skip the very first enemy phase so the
        // party gets a full turn to reposition before any pillager fires. Mirrors the PHANTOM
        // skip above; runs after the once-per-round bookkeeping so summon aging / the wave
        // clock stay consistent with a normal skipped round.
        if (raidActive && turnNumber <= 1) {
            sendMessage("§c§l✦ The pillagers close in! §r§7Take a turn to get into position.");
            turnNumber++;
            // The round still changes hands even though the enemies never acted.
            handOffRoundToFirstPartyPlayer();
            movedThisTurn = false;
            tilesMovedThisTurn = 0;
            attackedWithoutShieldThisTurn = false;
            PlayerProgression raidProg = PlayerProgression.get((ServerWorld) player.getEntityWorld());
            PlayerProgression.PlayerStats raidStats = raidProg.getStats(player);
            apRemaining = Math.max(0, raidStats.getEffective(PlayerProgression.Stat.AP)
                + PlayerCombatStats.getSetApBonus(player)
                + combatEffects.getHasteBonus()
                - combatEffects.getMiningFatiguePenalty());
            apRemaining += consumePendingMomentumAp();
            movePointsRemaining = raidStats.getEffective(PlayerProgression.Stat.SPEED)
                + combatEffects.getSpeedBonus() - combatEffects.getSpeedPenalty()
                + PlayerCombatStats.getSetSpeedBonus(player)
                - combatEffects.getLevitationPenalty();
            if (combatEffects.hasEffect(CombatEffects.EffectType.SOAKED)) {
                movePointsRemaining = Math.max(1, movePointsRemaining - 1);
            }
            movePointsRemaining = Math.max(0, movePointsRemaining);
            phase = CombatPhase.PLAYER_TURN;
            sendSync();
            refreshHighlights();
            return;
        }

        if (player != null) {
            player.getWorld().playSound(null, player.getBlockPos(),
                net.minecraft.sound.SoundEvents.BLOCK_NOTE_BLOCK_BASS.value(),
                net.minecraft.sound.SoundCategory.PLAYERS, 0.6f, 0.5f);
        }
        clearHighlights();
        // Keep live boss telegraphs painted while the enemies act.
        syncWarningTiles();
        phase = CombatPhase.ENEMY_TURN;
        enemyTurnIndex = 0;
        enemyTurnDelay = 10;
        enemyTurnDelayScaled = false;
        enemyTurnState = EnemyTurnState.DECIDING;
        pendingAction = null;
        currentEnemy = null;
        // Reset infinite-boss multi-action counters at the top of every enemy
        // phase, so an interrupted turn can never leak a stale partial budget.
        for (CombatEntity e : enemies) {
            if (e.isBoss() && e.hasAiMemory("inf_actions_used")) {
                e.setAiMemory("inf_actions_used", 0);
            }
        }

        // Netherite golem mount: raise the 1×3 wall now so enemies path around it this
        // turn. It's cleared again at the start of the player's turn so it never blocks
        // the rider's own movement.
        refreshMountWall();

        // SANDSTORM set bonus: enemies within 2 tiles of player lose 1 Speed this turn
        if (activeTrimScan != null && activeTrimScan.setBonus() == TrimEffects.SetBonus.SANDSTORM) {
            GridPos pPos = arena.getPlayerGridPos();
            for (CombatEntity e : enemies) {
                if (!e.isAlive() || e.isAlly()) continue;
                if (e.minDistanceTo(pPos) <= 2) {
                    e.stackSlowness(1, 1);
                }
            }
            sendMessage("§e§l✦ Sandstorm! §r§eNearby enemies are slowed.");
        }

        // Per-round ally effects (honey golem bee summon, hay golem heal, ...).
        // Hooks-only -timed-summon aging already ran above via ageTimedSummons().
        // Runs once per round here -startEnemyTurn fires after all party players
        // have acted, which is exactly one round.
        runAllyRoundHooks();

        sendSync();
    }

    /**
     * Showcase fights only: the first level of a biome, biome bosses, and raid bosses.
     * A mid-biome level replays the arena the party has been grinding through -
     * an unskippable camera pass there would wear out its welcome by level three.
     */
    private boolean shouldPlayIntro(LevelDefinition levelDef) {
        if (levelDef instanceof com.crackedgames.craftics.raid.RaidBossLevelDefinition) return true;
        if (levelDef instanceof com.crackedgames.craftics.level.GeneratedLevelDefinition gld) {
            com.crackedgames.craftics.level.BiomeTemplate bt = gld.getBiomeTemplate();
            if (bt == null) return false;
            int lvl = gld.getLevelNumber();
            return bt.getBiomeLevelIndex(lvl) == 0 || bt.isBossLevel(lvl);
        }
        return false;
    }

    /** Drives the intro fuse, the input lock, and the per-fighter particle bursts. */
    private void tickIntro() {
        if (introPendingTicks > 0) {
            introPendingTicks--;
            if (introPendingTicks == 0) fireIntro();
            return;
        }
        if (introLockTicks <= 0) return;
        introLockTicks--;
        introElapsedTicks++;
        int sinceLead = introElapsedTicks - INTRO_LEAD_TICKS;
        if (sinceLead >= 0 && sinceLead % INTRO_STEP_TICKS == 0) {
            int step = sinceLead / INTRO_STEP_TICKS;
            if (step < introCastIds.size()) spawnIntroParticles(step);
        }
        if (introLockTicks == 0) {
            introCastIds.clear();
            introCastAffinities.clear();
            sendSync();
        }
    }

    /**
     * The fuse fired: assemble the cast (the roster is complete by now - see
     * {@code introPendingTicks}), hand each fighter their affinity weapon, and tell
     * every client to run the camera pass. The lock length mirrors the client
     * sequence plus a lead for its loading transition; the client is authoritative
     * over its own camera, the server only over when play resumes.
     */
    private void fireIntro() {
        if (!active) return;
        java.util.List<ServerPlayerEntity> cast = getAllParticipants();
        if (cast.isEmpty()) return;
        introCastIds.clear();
        introCastAffinities.clear();
        StringBuilder wire = new StringBuilder();
        for (ServerPlayerEntity p : cast) {
            if (p == null || p.isDisconnected()) continue;
            PlayerProgression.Affinity aff = LoadingCast.strongestAffinity(p);
            introCastIds.add(p.getUuid());
            introCastAffinities.add(aff);
            if (wire.length() > 0) wire.append(',');
            wire.append(p.getId()).append(':').append(aff.name());
            try {
                introHoldAffinityWeapon(p, aff);
            } catch (Exception e) {
                CrafticsMod.LOGGER.warn("Intro weapon hold failed for {}", p.getName().getString(), e);
            }
        }
        if (introCastIds.isEmpty()) return;
        introElapsedTicks = 0;
        introLockTicks = INTRO_LEAD_TICKS + INTRO_STEP_TICKS * introCastIds.size() + INTRO_TAIL_TICKS;
        com.crackedgames.craftics.network.CombatIntroPayload payload =
            new com.crackedgames.craftics.network.CombatIntroPayload(wire.toString(), INTRO_STEP_TICKS);
        for (ServerPlayerEntity p : cast) {
            if (p != null && !p.isDisconnected()) ServerPlayNetworking.send(p, payload);
        }
    }

    /**
     * Put the weapon matching this player's leading affinity in their hand for the
     * intro pose. PHYSICAL and PET intros pose bare-handed by design. The Move item's
     * pinned slot is never touched (MoveSlotManager would immediately fight over it).
     */
    private void introHoldAffinityWeapon(ServerPlayerEntity p, PlayerProgression.Affinity aff) {
        DamageType want;
        try {
            want = DamageType.valueOf(aff.name());
        } catch (IllegalArgumentException e) {
            return;
        }
        if (want == DamageType.PHYSICAL || want == DamageType.PET) return;

        net.minecraft.entity.player.PlayerInventory inv = p.getInventory();
        //? if <=1.21.4 {
        int selected = inv.selectedSlot;
        //?} else {
        /*int selected = inv.getSelectedSlot();
        *///?}

        int moveSlot = 8;
        if (p.getEntityWorld() instanceof ServerWorld sw) {
            moveSlot = Math.max(0, Math.min(8,
                com.crackedgames.craftics.world.CrafticsSavedData.get(sw)
                    .getPlayerData(p.getUuid()).lockedMoveSlot));
        }

        // Best source: the held stack itself, then any hotbar slot, then main inventory.
        int src = -1;
        for (int i = 0; i < 36; i++) {
            net.minecraft.item.ItemStack s = inv.getStack(i);
            if (s.isEmpty() || com.crackedgames.craftics.item.MoveSlotManager.isMoveStack(s)) continue;
            if (DamageType.fromWeapon(s.getItem()) != want) continue;
            if (i == selected) { src = i; break; }
            if (src < 0 || (i < 9 && src >= 9)) src = i;
        }
        if (src < 0) return;

        int dest = selected;
        if (dest == moveSlot) {
            dest = -1;
            for (int i = 0; i < 9; i++) {
                if (i != moveSlot) { dest = i; break; }
            }
            if (dest < 0) return;
        }

        if (src != dest) {
            net.minecraft.item.ItemStack tmp = inv.getStack(dest);
            inv.setStack(dest, inv.getStack(src));
            inv.setStack(src, tmp);
        }
        if (dest != selected) {
            //? if <=1.21.4 {
            inv.selectedSlot = dest;
            //?} else {
            /*inv.setSelectedSlot(dest);
            *///?}
            p.networkHandler.sendPacket(
                new net.minecraft.network.packet.s2c.play.UpdateSelectedSlotS2CPacket(dest));
        }
    }

    /** A themed burst on the fighter the camera just reached. */
    private void spawnIntroParticles(int step) {
        PlayerProgression.Affinity aff = introCastAffinities.get(step);
        java.util.UUID id = introCastIds.get(step);
        ServerPlayerEntity target = null;
        for (ServerPlayerEntity p : getAllParticipants()) {
            if (p != null && p.getUuid().equals(id)) { target = p; break; }
        }
        if (target == null || !(target.getEntityWorld() instanceof ServerWorld world)) return;
        double x = target.getX(), y = target.getY() + 1.0, z = target.getZ();
        switch (aff) {
            case SLASHING -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SWEEP_ATTACK, x, y, z, 4, 0.5, 0.4, 0.5, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, x, y, z, 20, 0.6, 0.6, 0.6, 0.2);
            }
            case CLEAVING -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, x, y, z, 25, 0.7, 0.5, 0.7, 0.3);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, x, y - 0.8, z, 8, 0.5, 0.1, 0.5, 0.05);
            }
            case BLUNT -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, x, y - 0.8, z, 14, 0.6, 0.1, 0.6, 0.08);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, x, y, z, 12, 0.5, 0.5, 0.5, 0.25);
            }
            case RANGED -> world.spawnParticles(net.minecraft.particle.ParticleTypes.ELECTRIC_SPARK, x, y, z, 22, 0.5, 0.7, 0.5, 0.15);
            case WATER -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SPLASH, x, y, z, 30, 0.6, 0.5, 0.6, 0.1);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.DOLPHIN, x, y, z, 20, 0.6, 0.6, 0.6, 0.05);
            }
            case SPECIAL -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.WITCH, x, y, z, 22, 0.5, 0.7, 0.5, 0.1);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL, x, y, z, 15, 0.5, 0.6, 0.5, 0.3);
            }
            case PET -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.HEART, x, y + 0.5, z, 6, 0.5, 0.4, 0.5, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.HAPPY_VILLAGER, x, y, z, 15, 0.6, 0.6, 0.6, 0.0);
            }
            case PHYSICAL -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, x, y, z, 10, 0.5, 0.4, 0.5, 0.06);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, x, y, z, 15, 0.5, 0.5, 0.5, 0.2);
            }
        }
    }

    public void tick() {
        // Drive the event cinematic walk-up. This must run even when combat isn't
        // active: tickAll() ticks every CombatManager instance unconditionally, and
        // the trader event lives outside active combat. Runs before the !active guard.
        if (!activeWalkers.isEmpty()) {
            // Snapshot: a walker's onComplete may ADD another walker (the Elytra launch chains
            // its rise leg into a fall leg). Iterating the live list would then throw
            // ConcurrentModificationException mid-flight and strand the player in the air.
            // The snapshot also gives a newly added walker its first tick on the NEXT server
            // tick, keeping a chained animation's tick budget honest.
            for (EntityWalker w : new java.util.ArrayList<>(activeWalkers)) w.tick();
            activeWalkers.removeIf(EntityWalker::isComplete);
        }

        // Projectiles in the air, ticked HERE for the same reason the walkers are: this runs
        // before every guard and early return below. Ticking it further down meant a flight
        // simply stopped moving whenever any of those fired, and the projectile hung in the
        // air at the thrower's feet until its ceiling forced it down.
        tickProjectileFlight();

        // Deferred event-return: hold the loading screen, then enter battle. Runs
        // outside active combat (events live between levels), so it's before the guard.
        if (eventReturnTicks > 0) {
            eventReturnTicks--;
            if (eventReturnTicks == 0) {
                fireEventReturnTransition();
                // The transition just started the next combat (active=true) and spawned the
                // carried-over pets. Return so the rest of the combat body doesn't run on
                // this same tick -matching the normal level transition, which starts combat
                // from the payload handler and only processes it on the NEXT tick. Running it
                // here on the freshly-started arena was an event-only divergence.
                return;
            }
        }

        // Keep the soundtrack in sync with combat/event/trader state. Runs before the
        // !active guard so trader and between-level events (which live outside active
        // combat) still get music. Only emits a packet when the chosen track changes.
        //
        // Idle guard: an instance with no combat, no event room, no trader, and no track
        // playing has nothing to score - and tickAll ticks one instance per player who has
        // EVER fought, forever. Without this, music selection was the one per-tick cost
        // that scaled with lifetime player count instead of active fights.
        if (active || eventRoomType != null || activeTraderOffer != null
                || !lastSentMusicKey.isEmpty()) {
            refreshMusic();
        }

        if (!active) return;

        // Keep the player's body where the grid says they are.
        //
        // The grid is what the game plays on: attacks, reach, enemy pathing and the move
        // highlights all read from it, and a commanded move writes it. The entity is only the
        // picture. They are allowed to disagree briefly - a dash commits the grid immediately
        // and lerps the body over several ticks, which is the whole point of the animation -
        // but once nothing is animating, a disagreement is drift, and the player is left
        // standing visibly on one tile while the game plays them on another.
        //
        // Nothing was correcting that in a solo fight. The turn switch re-derives the grid FROM
        // the body, which would paper over it, but it returns early when there is only one
        // player in the queue - so a single player could drift and stay drifted for the rest of
        // the level.
        //
        // The body follows the grid rather than the other way round because the grid is the
        // half the rules use. Snapping the picture is a cosmetic correction; moving the grid to
        // meet a drifted body would silently relocate the player in the fight.
        reconcilePlayerToGrid();

        if (player == null || player.isRemoved() || player.isDisconnected()) {
            endCombat();
            return;
        }

        tickCounter++;

        tickIntro();

        // Mid-fight save point, once per player turn. Edge-triggered on the turn counter rather
        // than hooked into the ~10 places that set phase = PLAYER_TURN: every one of them would
        // have to remember to call this, and the one that forgot would be the level that could
        // still be healed out of. See ResumeSnapshot.
        if (phase == CombatPhase.PLAYER_TURN && turnNumber != lastSnapshotTurn) {
            lastSnapshotTurn = turnNumber;
            captureResumeSnapshot();
        }

        // AFK turn watchdog (CrafticsConfig.turnTimerEnabled, off by default): if the current
        // player does nothing for turnTimerSeconds, auto-end their turn so an AFK player can't
        // stall a multiplayer fight. The idle counter is reset on every action (handleAction)
        // and turn change (handleEndTurn / switchToTurnPlayer / startCombat).
        if (phase == CombatPhase.PLAYER_TURN) {
            boolean timerOn = false;
            int limitSec = 90;
            try {
                timerOn = com.crackedgames.craftics.CrafticsMod.CONFIG.turnTimerEnabled();
                limitSec = com.crackedgames.craftics.CrafticsMod.CONFIG.turnTimerSeconds();
                // A raid always runs a timer, at its own (shorter) limit: eight players
                // means one AFK player can freeze seven others for a whole fight.
                if (raidBossContext != null) {
                    timerOn = true;
                    limitSec = com.crackedgames.craftics.CrafticsMod.CONFIG.raidBossTurnSeconds();
                }
            } catch (Exception ignored) { /* config not loaded yet - leave the timer off */ }
            if (timerOn) {
                int limitTicks = Math.max(1, limitSec) * 20;
                turnIdleTicks++;
                if (limitTicks - turnIdleTicks == 200 && player != null) {
                    // ~10s warning to the active player (action bar).
                    player.sendMessage(net.minecraft.text.Text.literal(
                        "§eYour turn ends automatically in 10 seconds..."), true);
                } else if (turnIdleTicks >= limitTicks) {
                    ServerPlayerEntity timedOut = player;
                    if (timedOut != null) {
                        sendMessage("§e" + timedOut.getName().getString()
                            + "'s turn timed out - ending automatically.");
                    }
                    turnIdleTicks = 0;
                    if (raidBossContext != null && timedOut != null
                            && applyRaidBossStrike(timedOut)) {
                        return; // removed from the raid; the queue was already repaired
                    }
                    handleEndTurn();
                    return; // turn handed off this tick; skip the rest of the combat body
                }
            }
        }

        // Netherite mount furnace glow: while charged, re-assert the "charged" state each
        // tick (the mod's AI may try to reset it) and decay the timer; turn it off on the
        // final tick. Cheap -setCharged only re-sends when the value actually changes.
        if (mountFurnaceTicks > 0) {
            mountFurnaceTicks--;
            if (isNetheriteMount() && mountMob != null) {
                com.crackedgames.craftics.compat.golemoverhaul.NetheriteMountState
                    .setCharged(mountMob, mountFurnaceTicks > 0);
            } else {
                mountFurnaceTicks = 0;
            }
        }

        // Keep the hidden fire-resistance baseline alive. Other effect sources
        // (potions, sherds, totem revival) can override the icon-hidden ambient
        // version we apply on combat start with a visible-icon one. Force ours
        // back whenever the active FIRE_RESISTANCE instance is showing an icon
        // or particles, so the inventory UI doesn't misleadingly tell players
        // they're lava-immune. Players ARE protected from ambient fire damage,
        // but the lava/fire tile damage runs through Craftics' tile system.
        enforceHiddenFireResistance();

        // Keep anyone standing on a water tile breathing.
        enforceWaterTileBreathing();

        // Advance any lead-commanded walk animation.
        tickLeadWalk();

        // Advance any in-flight anvil drops.
        tickPendingAnvils();

        // Decay per-mob animation state so a forgotten setter can't freeze a pose.
        if (enemies != null) {
            for (CombatEntity e : enemies) {
                if (e != null && e.getMobEntity() != null) {
                    com.crackedgames.craftics.combat.animation.MobAnimations.tick(e.getMobEntity());
                }
            }
        }

        // Stealth tiles: re-apply vanilla invisibility to any player/mob standing
        // on a TALL_GRASS or TALL_FERN tile. AI targeting gate reads the tile
        // directly elsewhere, so this is purely for the visual hide. EVERY party
        // member is ticked, not just the turn-holder -the hide is a rolling
        // 30-tick buff, so ticking only the active player made a teammate's bush
        // invisibility lapse about one turn after the turn rotated off them.
        {
            List<net.minecraft.entity.LivingEntity> stealthPlayers = new ArrayList<>();
            List<GridPos> stealthPositions = new ArrayList<>();
            for (ServerPlayerEntity member : allCombatPlayers()) {
                if (member == null || member.isRemoved()
                    || deadPartyMembers.contains(member.getUuid())) continue;
                stealthPlayers.add(member);
                stealthPositions.add(player != null && member.getUuid().equals(player.getUuid())
                    ? arena.getPlayerGridPos() : gridPosOf(member));
            }
            com.crackedgames.craftics.combat.StealthTiles.applyEach(
                arena, stealthPlayers, stealthPositions, enemies,
                player != null ? player.getEntityWorld() : null);
        }

        // Keep boated players mounted -vanilla dismounts on interact/damage/
        // position changes. Per player, so a teammate parked on water keeps
        // THEIR boat between turns instead of the current turn-holder being
        // pulled into it.
        if (!activeBoats.isEmpty()) {
            var boatIt = activeBoats.entrySet().iterator();
            while (boatIt.hasNext()) {
                var boatEntry = boatIt.next();
                var boat = boatEntry.getValue();
                if (boat == null || boat.isRemoved()) {
                    boatIt.remove();
                    continue;
                }
                ServerPlayerEntity owner = null;
                for (ServerPlayerEntity m : allCombatPlayers()) {
                    if (m != null && m.getUuid().equals(boatEntry.getKey())) {
                        owner = m;
                        break;
                    }
                }
                if (owner == null || owner.isRemoved() || owner.isDisconnected()) {
                    boat.discard();
                    boatIt.remove();
                    continue;
                }
                if (!owner.hasVehicle()) {
                    owner.startRiding(boat, true);
                }
            }
        }
        // Mount cleanup + re-attach safety net.
        if (playerMounted && mountMob != null) {
            if (mountMob.isRemoved() || !mountMob.isAlive()) {
                mountFurnaceTicks = 0; // mount gone -stop the furnace glow timer
                clearMountWall(); // mount died mid-combat -drop its wall
                // Everyone riding it needs their own tile back. Clearing the fields without
                // this left passengers attached to a corpse with no legal square to act from.
                dismountAllRiders();
                sendMessage("§7The mount falls - everyone hits the ground.");
            } else if (player != null && !player.hasVehicle()) {
                player.startRiding(mountMob, true);
            }
        }

        // Fall death: rescue the player, then let a totem save them (see below).
        // Teleport back first to stop vanilla lava/void damage loops.
        // Skip if already dying / game over so we don't loop the message and
        // restart the death animation every tick while gravity drags the
        // corpse below the threshold.
        //
        // The grace countdown is what stops a SLOW-LOADING arena from reading as a void fall:
        // the floor is placed over several ticks (much longer while chunks load on a weak
        // machine), and until it exists the player is falling through empty air. Without this
        // they were killed - or, once totems covered void deaths, had their totem eaten - just
        // for entering an arena that took too long to build.
        if (fallDeathGraceTicks > 0) {
            // Hold the grace open while the floor genuinely isn't there yet: on a slow machine
            // the fixed window can expire with the arena still building. Only ever EXTENDS the
            // initial window - it can't re-open once the floor has appeared, so a terrain-
            // destroying boss can't hand the party permanent invulnerability later in the fight.
            if (!arenaFloorExists()) {
                fallDeathGraceTicks = Math.max(fallDeathGraceTicks, 20);
            }
            fallDeathGraceTicks--;

            // While the floor is still arriving, keep anyone who has started to drop pinned at
            // the arena instead of letting them sink out of the world. No death, no totem - just
            // put them back and cancel the fall.
            if (arena != null && player != null && player.getY() < arena.getOrigin().getY() - 1) {
                BlockPos hold = getSafeArenaBlockPos(arena);
                if (hold != null) {
                    player.requestTeleport(hold.getX() + 0.5, hold.getY(), hold.getZ() + 0.5);
                    player.setVelocity(0, 0, 0);
                    player.velocityModified = true;
                    player.fallDistance = 0;
                }
            }
        }
        if (arena != null && fallDeathGraceTicks <= 0
                && phase != CombatPhase.PLAYER_DYING && phase != CombatPhase.GAME_OVER) {
            int arenaFloorY = arena.getOrigin().getY();
            // The lowest LEGITIMATE standing height in an arena is arenaFloorY itself - that's
            // where a LOW_GROUND dip, water, lava and powder snow all put you. Anything below
            // that is a hole.
            //
            // This used to require arenaFloorY - 2, which a pickaxe-dug void pit never reaches:
            // digVoidPit caps the shaft with black concrete at floorY-2, so its floor is at
            // floorY-1 and whoever fell in just STOOD there - alive, two blocks down, their grid
            // position somewhere else entirely. Enemies kept attacking the desynced position
            // until something finally killed them.
            if (player.getY() < arenaFloorY - 0.5) {
                // Move the player's GRID position too, not just their entity: the tile they fell
                // through is a void obstacle and is not somewhere they can be standing. Leaving
                // the grid on it desyncs move highlights, attack range, and enemy pathing from
                // where the player actually is. (Harmless while this path always ended in death;
                // a live bug now that a totem can bring them back.)
                GridPos safeGrid = getSafeArenaGridPos(arena);
                BlockPos safePos = safeGrid != null
                    ? arena.gridToBlockPos(safeGrid) : arena.getPlayerStartBlockPos();
                if (safeGrid != null) {
                    arena.setPlayerGridPos(safeGrid);
                }
                if (safePos != null) {
                    player.requestTeleport(safePos.getX() + 0.5, safePos.getY(), safePos.getZ() + 0.5);
                }
                // Reset velocity and fall distance so the player doesn't immediately
                // re-fall through the safe block from accumulated downward velocity.
                player.setVelocity(0, 0, 0);
                player.velocityModified = true;
                player.fallDistance = 0;
                player.setFireTicks(0);
                player.setFrozenTicks(0);
                player.setHealth(1);
                // A totem saves you from the void too. This path called the death animation
                // directly instead of going through handlePlayerDeathOrGameOver, so falling
                // into a void obstacle killed you with a totem still in your hand.
                if (tryConsumeTotemAndResurrect()) {
                    sendMessage("§6You were snatched back from the void!");
                    refreshHighlights();
                    sendSync();
                    return;
                }
                sendMessage("§c§l☠ You fell to your death!");
                if (partyPlayers.size() <= 1) {
                    startPlayerDeathAnimation();
                } else {
                    deadPartyMembers.add(player.getUuid());
                    player.changeGameMode(net.minecraft.world.GameMode.SPECTATOR);
                    sendMessage("§c§l☠ " + player.getName().getString() + " has fallen!");
                    ServerPlayerEntity nextAlive = null;
                    for (ServerPlayerEntity member : partyPlayers) {
                        if (!deadPartyMembers.contains(member.getUuid())
                                && member != null && !member.isRemoved() && !member.isDisconnected()) {
                            nextAlive = member;
                            break;
                        }
                    }
                    if (nextAlive == null) {
                        startPlayerDeathAnimation();
                    } else {
                        sendMessage("§e" + nextAlive.getName().getString() + " takes over the fight!");
                        // Same grid sync as the rescue above: the grid is still sitting on the
                        // void tile the fallen player dropped through, so the survivor would take
                        // over "standing" in a pit they aren't actually in.
                        GridPos takeoverGrid = getSafeArenaGridPos(arena);
                        BlockPos takeoverPos = takeoverGrid != null
                            ? arena.gridToBlockPos(takeoverGrid) : arena.getPlayerStartBlockPos();
                        if (takeoverGrid != null) {
                            arena.setPlayerGridPos(takeoverGrid);
                        }
                        if (takeoverPos != null) {
                            nextAlive.requestTeleport(
                                takeoverPos.getX() + 0.5,
                                takeoverPos.getY(),
                                takeoverPos.getZ() + 0.5);
                            broadcastPlayerPositionToOthers(nextAlive);
                        }
                        // Drop the fallen player from the turn queue so survivors
                        // don't get a free double-turn this round.
                        pruneDeadFromTurnQueue(player.getUuid());
                        this.player = nextAlive;
                        retargetEffectsToCurrentPlayer();
                    }
                }
                return;
            }

            // Same rescue for NON-acting party members. Knockback or a shove can
            // drop a teammate below the arena outside their own turn, where the
            // turn-holder check above never sees them -they kept falling into
            // the void and died through vanilla damage, outside the combat flow.
            //
            // Two things here used to differ from the turn-holder branch above, and both
            // were bugs rather than decisions. The `member == player` guard means this loop
            // can ONLY ever kill a non-leader, so both landed exclusively on party members:
            //
            //   • The threshold was arenaFloorY - 2, while the turn holder is caught at
            //     arenaFloorY - 0.5. A dug void pit is capped at floorY-2 so its floor sits
            //     at floorY-1 - between the two. A member who fell in was therefore never
            //     rescued AND never killed: they stood in the hole, grid position somewhere
            //     else, while enemies attacked the tile they used to be on. That is the
            //     exact desync the comment on the branch above says was fixed; it was only
            //     ever fixed for the turn holder.
            //
            //   • It killed unconditionally. The turn holder gets tryConsumeTotemAndResurrect
            //     before any death, and so does the ordinary death path; this one went
            //     straight to SPECTATOR with the totem still in the member's hand. Combined
            //     with the entry grace - during which all damage to a routed player is
            //     swallowed, so they fall harmlessly behind the loading screen - a member
            //     misplaced over a pit on arrival was killed the tick the grace expired,
            //     with no counterplay of any kind.
            if (partyPlayers.size() > 1) {
                boolean anyMemberFell = false;
                for (ServerPlayerEntity member : partyPlayers) {
                    if (member == null || member == player || member.isRemoved()
                        || member.isDisconnected()
                        || deadPartyMembers.contains(member.getUuid())) continue;
                    if (member.getY() >= arenaFloorY - 0.5) continue;

                    BlockPos safePos = getSafeArenaBlockPos(arena);
                    if (safePos != null) {
                        member.requestTeleport(safePos.getX() + 0.5, safePos.getY(), safePos.getZ() + 0.5);
                        broadcastPlayerPositionToOthers(member);
                    }
                    member.setVelocity(0, 0, 0);
                    member.velocityModified = true;
                    member.fallDistance = 0;
                    member.setFireTicks(0);
                    member.setFrozenTicks(0);
                    // Their grid position followed them into the hole, and the tile they
                    // fell through is not somewhere anyone can stand. Resync it to where
                    // the rescue actually put them, or the survivor fights on with a
                    // teammate whose highlights and attack range point into the floor.
                    refreshAllPlayerGridPositions();
                    if (tryConsumeTotemForMember(member)) {
                        sendMessageTo(member, "§6You were snatched back from the void!");
                        sendMessage("§6" + member.getName().getString()
                            + " was snatched back from the void!");
                        anyMemberFell = true;
                        continue;
                    }
                    member.setHealth(1);
                    deadPartyMembers.add(member.getUuid());
                    member.changeGameMode(net.minecraft.world.GameMode.SPECTATOR);
                    sendMessage("§c§l☠ " + member.getName().getString() + " has fallen!");
                    pruneDeadFromTurnQueue(member.getUuid());
                    anyMemberFell = true;
                }
                if (anyMemberFell) {
                    sendSync();
                }
            }
        }
        // Void safety
        if (player.getY() < 0) {
            BlockPos safePos = arena != null ? getSafeArenaBlockPos(arena) : null;
            if (safePos != null) {
                player.requestTeleport(safePos.getX() + 0.5, safePos.getY(), safePos.getZ() + 0.5);
            } else {
                player.requestTeleport(player.getX(), 100, player.getZ());
            }
            player.setVelocity(0, 0, 0);
            player.velocityModified = true;
            player.setFireTicks(0);
            player.fallDistance = 0;
        }

        // Suppress vanilla fire visuals -our tile system handles lava damage
        if (player.isOnFire()) player.setFireTicks(0);

        tickBossAmbientParticles();
        tickDragonPositionEnforcer();
        tickVoidRiftParticles();
        tickSandMineParticles();

        if (activeMiniboss != null || activeBiomeEffect != null) {
            if (activeMiniboss != null) activeMiniboss.onCombatTick(buildMinibossCtx(), tickCounter);
            if (activeBiomeEffect != null) activeBiomeEffect.onCombatTick(buildMinibossCtx(), tickCounter);
        }

        // Damage synced to animation impact frame
        if (pendingAttackDelay > 0) {
            pendingAttackDelay--;
            if (pendingAttackDelay == 0 && pendingAttackAction != null) {
                pendingAttackAction.run();
                pendingAttackAction = null;
            }
        }

        // The thrown item has arrived; now it does what it came to do.
        if (pendingItemDelay > 0) {
            pendingItemDelay--;
            if (pendingItemDelay == 0 && pendingItemAction != null) {
                Runnable landed = pendingItemAction;
                pendingItemAction = null;   // cleared FIRST: the effect can end the fight
                landed.run();
            }
        }

        if (spellAnimCooldown > 0) spellAnimCooldown--;

        if (!PotterySherdSpells.PENDING_EFFECTS.isEmpty()) {
            var iter = PotterySherdSpells.PENDING_EFFECTS.iterator();
            while (iter.hasNext()) {
                var effect = iter.next();
                if (--effect.ticksRemaining <= 0) {
                    effect.effect.run();
                    iter.remove();
                }
            }
        }

        // Re-spawn mobs killed by vanilla mechanics and suppress stray fire
        if (enemies != null) {
            for (CombatEntity e : enemies) {
                if (!e.isAlive()) continue;
                MobEntity mob = e.getMobEntity();
                if (mob == null) continue;

                // CombatEntity stats are still valid -just need a new visual mob
                if (!mob.isAlive() || mob.isRemoved()) {
                    CrafticsMod.LOGGER.warn("Enemy '{}' (id={}) removed externally -- reason={}, health={}, pos=({},{},{})",
                        e.getDisplayName(), e.getEntityId(),
                        mob.getRemovalReason(), mob.getHealth(),
                        mob.getX(), mob.getY(), mob.getZ());
                    BlockPos respawnPos = arena.gridToBlockPos(e.getGridPos());
                    ServerWorld tickWorld = (ServerWorld) player.getEntityWorld();
                    EntityType<?> reType = Registries.ENTITY_TYPE.get(Identifier.of(e.getEntityTypeId()));
                    var newMob = reType.create(tickWorld, null, respawnPos, SpawnReason.COMMAND, false, false);
                    if (newMob instanceof MobEntity replacementMob) {
                        // Background bosses (Wailing Revenant, parked Ender
                        // Dragon) have a sentinel gridPos like (0, 0) used
                        // only for targeting -their real world position is
                        // outside the arena. Respawning at gridBlockPos
                        // dropped them onto an actual tile mid-fight. Reuse
                        // the original placement formula so they stay parked.
                        double spawnX, spawnY, spawnZ;
                        if (e.isBackgroundBoss()) {
                            spawnX = arena.getOrigin().getX() + (arena.getWidth() - 1) / 2.0 + 0.5;
                            spawnZ = arena.getOrigin().getZ() - 10.0;
                            spawnY = arena.getOrigin().getY() + 2.0;
                        } else {
                            // Center over the live footprint (the entity's dims, not the
                            // type default - orientation/boss overrides may differ).
                            spawnX = respawnPos.getX() + e.getSizeX() / 2.0;
                            spawnY = respawnPos.getY();
                            spawnZ = respawnPos.getZ() + e.getSizeZ() / 2.0;
                        }
                        replacementMob.refreshPositionAndAngles(spawnX, spawnY, spawnZ, 0, 0);
                        replacementMob.setInvulnerable(true);
                        replacementMob.setAiDisabled(true);
                        replacementMob.setNoGravity(true);
                        replacementMob.noClip = true;
                        replacementMob.setPersistent();
                        replacementMob.setHealth(replacementMob.getMaxHealth());
                        replacementMob.addCommandTag("craftics_arena");
                        tickWorld.spawnEntity(replacementMob);
                        e.setMobEntity(replacementMob);
                        // Re-apply boss scale lost when the original mob was
                        // removed -without this a respawned Wailing Revenant
                        // would lose its 2x size and look like a normal ghast.
                        if (e.isBackgroundBoss() && replacementMob instanceof net.minecraft.entity.mob.GhastEntity) {
                            scaleBoss(replacementMob, 2.0);
                        }
                        CrafticsMod.LOGGER.info("Re-spawned '{}' successfully", e.getDisplayName());
                    } else {
                        CrafticsMod.LOGGER.error("Failed to re-spawn '{}' -removing from combat", e.getDisplayName());
                        e.takeDamage(9999);
                        arena.removeEntity(e);
                        sendToAllParty(new CombatEventPayload(
                            CombatEventPayload.EVENT_DIED, e.getEntityId(), 0, 0, 0, 0
                        ));
                        if (!anyEnemyBlockingVictory()) {
                            handleVictory();
                            return;
                        }
                    }
                    continue;
                }

                if (e.isLitOneShot()) {
                    // A lit coal golem is literally on fire -keep the burning overlay
                    // visible by refreshing its fire ticks each tick (otherwise the
                    // stray-fire suppression below would extinguish it instantly).
                    mob.setFireTicks(Math.max(mob.getFireTicks(), 40));
                } else if (e.getBurningTurns() > 0) {
                    // Turn-based Burning DoT active (Blaze Rod / Fire Aspect): keep the fire
                    // overlay lit instead of extinguishing it, so the burn reads visually for
                    // its whole duration. The DoT damage is driven by burningTurns, not fireTicks.
                    mob.setFireTicks(Math.max(mob.getFireTicks(), 40));
                } else if (mob.isOnFire()) {
                    mob.setFireTicks(0);
                }

                // Creeper fuse visual -NO ignite, that causes a real explosion
                if (e.getFuseTimer() > 0 && e.getEntityTypeId().equals("minecraft:creeper")) {
                    mob.setGlowing(e.getFuseTimer() % 8 < 4);
                    ServerWorld creeperWorld = (ServerWorld) player.getEntityWorld();
                    creeperWorld.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE,
                        mob.getX(), mob.getY() + 1.0, mob.getZ(),
                        2, 0.2, 0.3, 0.2, 0.01);
                }

                // Snap idle mobs to grid -skip currently animating + background
                // bosses + the active mount. The mount's CombatEntity gridPos
                // tracks the player's tile, but the player's tile isn't updated
                // until the move lerp completes; snapping the mount every tick
                // would drag it back to the lerp's starting tile (the rubberband).
                // Its world position is driven by the lerp tick directly.
                if (!e.isBackgroundBoss()
                        && !e.isMounted()
                        && (e != currentEnemy || enemyTurnState == EnemyTurnState.DONE
                        || enemyTurnState == EnemyTurnState.DECIDING)) {
                    BlockPos gridBlock = arena.gridToBlockPos(e.getGridPos());
                    double targetX = gridBlock.getX() + e.getSizeX() / 2.0;
                    double targetZ = gridBlock.getZ() + e.getSizeZ() / 2.0;
                    double targetY = arena.getEntityY(e.getGridPos(), e.isFlying());
                    double driftX = Math.abs(mob.getX() - targetX);
                    double driftZ = Math.abs(mob.getZ() - targetZ);
                    if (driftX > 0.1 || driftZ > 0.1) {
                        mob.requestTeleport(targetX, targetY, targetZ);
                    }
                    if (e.isProjectile() && e.getVisualProjectileEntityId() != -1) {
                        syncVisualProjectile(e, targetX, targetY + 0.5, targetZ);
                    }
                }
            }
        }

        // Detect a held-item swap in any phase: refresh the move/attack highlights
        // (range changed) on the player's turn, and always re-sync so the hover
        // panel's attack/range readout tracks the weapon currently in hand.
        if (player != null) {
            var currentItem = player.getMainHandStack().getItem();
            if (currentItem != lastHeldItem) {
                lastHeldItem = currentItem;
                if (phase == CombatPhase.PLAYER_TURN) refreshHighlights();
                sendSync();
            }
        }

        for (int i = dyingMobs.size() - 1; i >= 0; i--) {
            DyingMob dm = dyingMobs.get(i);
            int remaining = dm.timer() - 1;
            if (remaining <= 0) {
                // Defense in depth: every entry point that adds to dyingMobs
                // should already have cleared stack passengers, but cover the
                // case where one didn't so the cosmetic rider can't outlive
                // its mount and become a ghost mob.
                clearStackPassengers(dm.mob());
                dm.mob().discard();
                dyingMobs.remove(i);
            } else {
                dyingMobs.set(i, dm.withTimer(remaining));
                int totalShrinkTicks = 15;
                int elapsed = 20 - remaining;
                float progress = Math.min(1.0f, (float) elapsed / totalShrinkTicks);
                float eased = progress * progress;
                float currentScale = dm.startScale() * (1.0f - eased) + 0.01f * eased;
                var scaleAttr = dm.mob().getAttributeInstance(SCALE_ATTR);
                if (scaleAttr != null) scaleAttr.setBaseValue(currentScale);

                if (elapsed % 3 == 0 && dm.mob().getWorld() instanceof ServerWorld sw) {
                    sw.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE,
                        dm.mob().getX(), dm.mob().getY() + 0.3, dm.mob().getZ(),
                        3, 0.2, 0.2, 0.2, 0.01);
                }
            }
        }

        switch (phase) {
            case ANIMATING -> tickAnimation();
            case REACTING -> tickReacting();
            case ENEMY_TURN -> tickEnemyTurn();
            case PLAYER_DYING -> tickPlayerDying();
            case GAME_OVER_FLIP -> tickGameOverFlip();
            default -> {}
        }
    }

    private void tickAnimation() {
        // Riptide dash uses its own continuous-lerp animator (ease-out + particle whirl).
        if (riptideAnimActive) { tickRiptideAnimation(); return; }
        if (movePathIndex >= movePath.size()) {
            int tilesMoved = movePath.size();
            // Captured before movePath is nulled below: every tile actually stood on this
            // move (ordinary steps AND jump landings), in order. Tiles JUMPED OVER are never
            // in here - Pathfinding.Path.steps() only ever holds tiles the player stood on -
            // so vaulting a lava channel still correctly skips all of the hazard loop below.
            List<GridPos> traversedTiles = new ArrayList<>(movePath);
            GridPos walkedPos = arena.getPlayerGridPos();
            movePath = null;
            lerpInitialized = false;

            notifyBossesPlayerMoved(walkedPos, tilesMoved);

            // Void Walker: if the player stepped onto a rift, teleport them and possibly buff.
            // The teleport updates the grid pos, so re-read before any downstream logic.
            if (handleVoidRiftEntry(walkedPos)) {
                walkedPos = arena.getPlayerGridPos();
            }
            // Sandstorm Pharaoh: detonate a buried sand mine if we stepped on one.
            // A lethal mine is resolved here (mirrors the lava/fire step-damage guards
            // below) so the move-finish block doesn't run on a dying player.
            triggerSandMine(walkedPos);
            if (getPlayerHp() <= 0) {
                sendSync();
                handlePlayerDeathOrGameOver();
                return;
            }
            final GridPos finalPos = walkedPos;

            // Addon combat effects: player moved
            {
                final GridPos fromPos = moveOriginPos != null ? moveOriginPos : finalPos;
                final int dist = tilesMoved;
                fireEffectHook(h -> h.onMove(effectContext, fromPos, finalPos, dist));
                // Curse of the Sands: the tile the player just left erupts into a
                // buried mine. Counterplay is to stay put (or clear ground you'll
                // need later) until the curse burns off.
                if (curseOfSandsTurns > 0 && tilesMoved > 0 && !fromPos.equals(finalPos)) {
                    sendMessage("§6  The curse stirs the sand behind you...");
                    registerSandMine(fromPos);
                }
                moveOriginPos = null;
            }

            // TERRAFORMER (Earthshatter) set bonus: moving 3+ tiles deals 2 damage to adjacent enemies
            if (tilesMoved >= 3 && activeTrimScan != null
                    && activeTrimScan.setBonus() == TrimEffects.SetBonus.TERRAFORMER) {
                int shatterCount = 0;
                for (int sdx = -1; sdx <= 1; sdx++) {
                    for (int sdz = -1; sdz <= 1; sdz++) {
                        if (sdx == 0 && sdz == 0) continue;
                        GridPos adj = new GridPos(finalPos.x() + sdx, finalPos.z() + sdz);
                        CombatEntity adjTarget = arena.getOccupant(adj);
                        if (adjTarget != null && adjTarget.isAlive() && !adjTarget.isAlly()) {
                            adjTarget.takeDamage(2);
                            shatterCount++;
                            if (!adjTarget.isAlive()) {
                                checkAndHandleDeath(adjTarget);
                            }
                        }
                    }
                }
                if (shatterCount > 0) {
                    sendMessage("§6§l⚡ Earthshatter! §r§6" + shatterCount + " enemies hit for 2 damage!");
                    if (player != null) {
                        player.getWorld().playSound(null, player.getBlockPos(),
                            net.minecraft.sound.SoundEvents.ENTITY_GENERIC_EXPLODE.value(),
                            net.minecraft.sound.SoundCategory.PLAYERS, 0.6f, 0.7f);
                    }
                }
            }

            if (arena.hasWebOverlay(finalPos) || tileHasWebBlock(finalPos)) {
                arena.clearWebOverlay(finalPos);
                // Break the cobweb block(s) in the world at body (Y+1) and head (Y+2) -
                // schematics hang webs at either height. gridToBlockPos resolves the real
                // world tile in schematic/offset arenas (the old origin+grid math could miss).
                BlockPos base = arena.gridToBlockPos(finalPos);
                if (player.getWorld() instanceof ServerWorld sw) {
                    for (int dy = 1; dy <= 2; dy++) {
                        BlockPos wp = base.up(dy);
                        if (sw.getBlockState(wp).isOf(Blocks.COBWEB)) {
                            sw.setBlockState(wp, Blocks.AIR.getDefaultState(),
                                net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);
                            sw.spawnParticles(net.minecraft.particle.ParticleTypes.ITEM_COBWEB,
                                wp.getX() + 0.5, wp.getY() + 0.5, wp.getZ() + 0.5,
                                8, 0.3, 0.3, 0.3, 0.01);
                        }
                    }
                }
                sendMessage("§7  Caught in cobwebs! Movement stopped.");
            }

            // Water tile handling: boat visual + Soaked effect
            GridTile landingTile = arena.getTile(finalPos);
            boolean onWaterNow = landingTile != null
                && landingTile.getType() == com.crackedgames.craftics.core.TileType.WATER;
            if (onWaterNow && !playerMounted) {
                if (moveBoatProtected) {
                    net.minecraft.entity.vehicle.BoatEntity boat = boatOf(player);
                    // Spawn a visual boat if we don't have one
                    if (boat == null && player.getWorld() instanceof ServerWorld sw) {
                        BlockPos boatBlock = arena.gridToBlockPos(finalPos);
                        double boatY = boatBlock.getY(); // surface level, not lowered
                        //? if <=1.21.1 {
                        boat = new net.minecraft.entity.vehicle.BoatEntity(
                            net.minecraft.entity.EntityType.BOAT, sw);
                        //?} else {
                        /*boat = new net.minecraft.entity.vehicle.BoatEntity(
                            net.minecraft.entity.EntityType.OAK_BOAT, sw,
                            () -> net.minecraft.item.Items.OAK_BOAT);
                        *///?}
                        boat.setPosition(boatBlock.getX() + 0.5, boatY, boatBlock.getZ() + 0.5);
                        boat.setYaw(player.getYaw() - 90f);
                        boat.setInvulnerable(true);
                        boat.setNoGravity(true);
                        sw.spawnEntity(boat);
                        activeBoats.put(player.getUuid(), boat);
                        // Teleport player to boat position THEN mount
                        player.requestTeleport(boatBlock.getX() + 0.5, boatY, boatBlock.getZ() + 0.5);
                        player.startRiding(boat, true);
                    } else if (boat != null) {
                        // Move existing boat with the player
                        BlockPos boatBlock = arena.gridToBlockPos(finalPos);
                        double boatY = boatBlock.getY();
                        boat.setPosition(boatBlock.getX() + 0.5, boatY, boatBlock.getZ() + 0.5);
                        boat.setYaw(player.getYaw() - 90f);
                    }
                } else if (player.getEquippedStack(net.minecraft.entity.EquipmentSlot.HEAD).getItem() != Items.TURTLE_HELMET) {
                    addEffectHooked(CombatEffects.EffectType.SOAKED, 2, 0);
                    sendMessage("§b  Wading through water! Soaked for 2 turns.");
                }
            } else {
                // Left water -remove the mover's boat (despawn snaps their position)
                despawnActiveBoat(player);
            }

            // Lava damage + flame burning for EVERY tile actually walked across this move,
            // not just the tile the player stops on. This used to only check landingTile
            // (the very last tile), so wading three lava tiles in one move was free right
            // up until the player stopped standing in one - walking straight across a lava
            // channel cost nothing at all unless you ended your move inside it. Reuses the
            // exact same lava-damage amount/message and applyFireTileBurnToPlayer that the
            // "standing in lava/fire" turn-start checks use, so landing and mid-path tiles
            // can never drift apart from each other.
            for (GridPos crossed : traversedTiles) {
                GridTile crossedTile = arena.getTile(crossed);
                if (crossedTile == null) continue;
                if (crossedTile.getType() == com.crackedgames.craftics.core.TileType.LAVA
                        && !playerMounted && !combatEffects.hasFireResistance()) {
                    int lavaDmg = damagePlayerFromTile(10, null);
                    sendMessage("§6  Stepped in lava for " + lavaDmg + " damage!");
                    if (getPlayerHp() <= 0) {
                        sendSync();
                        handlePlayerDeathOrGameOver();
                        return;
                    }
                }

                // Walking into a flame tile sets you alight (Burning II, extending any burn
                // already running). The magma a burnt-out tile leaves behind is a separate
                // EMBER tile and bites through the MAGMA_BLOCK check in the per-turn pass.
                if (crossedTile.getType().isFlames() && !combatEffects.hasFireResistance()) {
                    applyFireTileBurnToPlayer(crossedTile.getType());
                }
            }

            // Frost: the blizzard's rime. Leather boots keep it off you, exactly like powder
            // snow, so the cold-weather counter-gear works consistently across both hazards.
            // TileType has always described FROST as "Blizzard applies Frozen risk on step" -
            // until now nothing applied anything and the tile was pure decoration.
            if (landingTile != null
                    && landingTile.getType() == com.crackedgames.craftics.core.TileType.FROST
                    && !hasLeatherBoots() && !playerMounted) {
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 1, 0);
                player.setFrozenTicks(Math.max(player.getFrozenTicks(), 80));
                sendMessage("§b  Rime underfoot - you slip and slow down.");
            }

            // Withered ground: the rot the Wither leaves behind. Bites on ENTRY rather than per
            // turn, so crossing the boss's trail costs you and camping on it does not stack -
            // this is meant to shrink the board, not to punish a player who has run out of
            // clean tiles to stand on. Wither bypasses Fire Resistance by design.
            if (landingTile != null
                    && landingTile.getType() == com.crackedgames.craftics.core.TileType.DECAY) {
                int decayDmg = damagePlayerFromTile(landingTile.getType().damageOnStep, null);
                addEffectHooked(CombatEffects.EffectType.WITHER, 2, 0);
                sendMessage("§8  The withered ground saps you for " + decayDmg + "!");
                if (getPlayerHp() <= 0) {
                    sendSync();
                    handlePlayerDeathOrGameOver();
                    return;
                }
            }

            // Prevent vanilla cobweb physics desync
            player.setVelocity(0, 0, 0);
            player.velocityModified = true;

            phase = CombatPhase.PLAYER_TURN;
            sendSync();
            refreshHighlights();
            return;
        }

        if (!lerpInitialized) {
            lerpInitialized = true;
            moveTickCounter = 0;
            lerpStartX = player.getX();
            lerpStartY = player.getY();
            lerpStartZ = player.getZ();

            GridPos next = movePath.get(movePathIndex);
            GridPos prev = movePathIndex == 0 ? arena.getPlayerGridPos() : movePath.get(movePathIndex - 1);
            int dx = next.x() - prev.x();
            int dz = next.z() - prev.z();
            playerMoveYaw = (float) Math.toDegrees(Math.atan2(-dx, dz));
            updateMountFacing(dx, dz); // netherite mount: wall reorients to travel direction

            // Budget this step's ticks by how far it spans. A jump covers 2-3 tiles in a single
            // path step; giving it one walk's ticks (MOVE_TICKS) crossed all of that plus a tall
            // arc in ~4 position updates, which read as a choppy pop. Scaling by span keeps the
            // per-tick distance - and so the arc's smoothness - the same as an ordinary walk.
            // getMoveTicks() already collapses to 1 when animations are skipped; keep that.
            int baseTicks = getMoveTicks();
            int span = Math.abs(dx) + Math.abs(dz);
            currentStepTicks = baseTicks > 1 && span > 1 ? baseTicks * span : baseTicks;

            // Fire up the golem's furnace while it walks (refreshed each step, so it stays
            // lit through a multi-tile move and fades shortly after stopping).
            chargeMountFurnace(currentStepTicks + 8);
        }

        moveTickCounter++;
        GridPos next = movePath.get(movePathIndex);
        BlockPos endBlock = arena.gridToBlockPos(next);
        double endX = endBlock.getX() + 0.5;
        // Boat on water = surface Y; leather boots on powder snow = surface Y; otherwise use tile Y
        GridTile nextTile = arena.getTile(next);
        boolean stayOnSurface = (boatOf(player) != null || moveBoatProtected)
            || (nextTile != null && nextTile.getType() == com.crackedgames.craftics.core.TileType.POWDER_SNOW && hasLeatherBoots());
        double endY = stayOnSurface ? endBlock.getY() : arena.getEntityY(next);
        double endZ = endBlock.getZ() + 0.5;

        float progress = Math.min(1.0f, (float) moveTickCounter / currentStepTicks);

        double x = lerpStartX + (endX - lerpStartX) * progress;
        double y = lerpStartY + (endY - lerpStartY) * progress;

        // --- Airborne cases: the body has to get OVER a tile it cannot stand on ---
        // Both of these arc the player up and back down, interpolating start->end Y underneath
        // so a jump onto a STAIR (+0.5) or ELEVATED (+1) tile lands at the right height.
        GridPos prevTile = movePathIndex == 0 ? moveOriginPos : movePath.get(movePathIndex - 1);
        int spanTiles = prevTile == null ? 1
            : Math.abs(next.x() - prevTile.x()) + Math.abs(next.z() - prevTile.z());
        boolean isJumpStep = spanTiles > 1;

        // Pathfinder trim: the bonus lets you WALK THROUGH obstacle tiles, but nothing ever
        // lifted the body - getEntityY only raises an entity over an obstacle when flying=true,
        // so a Pathfinder player was routed straight through the middle of the block. Hop them
        // over its top instead. (Pre-existing bug; obstacles are not jumpable, so this is the
        // only way a walking player is ever inside one.)
        GridTile crossingTile = arena.getTile(next);
        boolean walkingOverObstacle = !isJumpStep && crossingTile != null
            && crossingTile.getType() == com.crackedgames.craftics.core.TileType.OBSTACLE;
        if (walkingOverObstacle) {
            endY = arena.getEntityY(next, true); // obstacle top, as a flyer would sit
            y = lerpStartY + (endY - lerpStartY) * progress;
        }

        if (isJumpStep || walkingOverObstacle) {
            // Parabolic hop on top of the straight Y interpolation. Peaks mid-step, zero at both
            // ends, so it never disturbs the landing height.
            double arcHeight = isJumpStep ? 0.55 + 0.25 * (spanTiles - 1) : 0.35;
            y += Math.sin(progress * Math.PI) * arcHeight;
        }
        double z = lerpStartZ + (endZ - lerpStartZ) * progress;

        if (playerMounted && mountMob != null) {
            // Mounted ride: drive the mount via requestTeleport so the
            // server broadcasts the new position immediately. The rider
            // (player) renders at the mount's tracked position.
            mountMob.setYaw(playerMoveYaw);
            mountMob.setHeadYaw(playerMoveYaw);
            mountMob.setBodyYaw(playerMoveYaw);
            mountMob.setOnGround(true);
            mountMob.requestTeleport(x, y, z);
            // Re-attach the rider if vanilla silently dropped the link.
            if (!player.hasVehicle() && !mountMob.isRemoved()) {
                player.startRiding(mountMob, true);
            }
        } else {
            player.setYaw(playerMoveYaw);
            player.setHeadYaw(playerMoveYaw);
            // Also align the BODY yaw, otherwise the body keeps its old angle while the
            // head snaps to the move direction -the player renders walking "crooked"
            // (diagonal body, forward head). Matches the mounted path above.
            player.setBodyYaw(playerMoveYaw);
            player.setOnGround(true);

            // prevXYZ needed so client limb animator sees the movement delta
            //? if <=1.21.4 {
            player.prevX = player.getX();
            player.prevY = player.getY();
            player.prevZ = player.getZ();
            //?} else {
            /*player.lastX = player.getX();
            player.lastY = player.getY();
            player.lastZ = player.getZ();
            *///?}
            player.setPosition(x, y, z);

            // Velocity drives vanilla limb animation on client
            double dx = endX - lerpStartX;
            double dz = endZ - lerpStartZ;
            double len = Math.sqrt(dx * dx + dz * dz);
            if (len > 0) {
                double speed = 0.12;
                player.setVelocity(dx / len * speed, 0, dz / len * speed);
                player.velocityDirty = true;
            }

            player.networkHandler.requestTeleport(x, y, z, playerMoveYaw, 0f);
            // Vanilla entity tracker won't broadcast server-driven position
            // changes for player entities -clients see only the velocity
            // (limb anim) and the pawn walks in place. Push the position
            // explicitly to every OTHER observer.
            broadcastPlayerPositionToOthers(player);
        }

        // Keep boat in sync with player during movement -boats face 90° offset from entity yaw
        net.minecraft.entity.vehicle.BoatEntity moveBoat = boatOf(player);
        if (moveBoat != null) {
            moveBoat.setPosition(x, y, z);
            moveBoat.setYaw(playerMoveYaw - 90f);
        }

        if (moveTickCounter >= currentStepTicks) {
            arena.setPlayerGridPos(next);
            // Netherite mount: the 1×3 wall follows the rider, so rebuild it on the new
            // tile (facing was already updated for this step at lerp init).
            refreshMountWall();

            // Trailblazer leggings: every tile the wearer crosses joins their trail, which
            // teammates can follow at a discount until the wearer's next turn.
            if (CrafticsEnchantments.wornLevel(player, CrafticsEnchantments.TRAILBLAZER) > 0) {
                playerTrails.computeIfAbsent(player.getUuid(),
                    k -> new java.util.HashSet<>()).add(next);
            }

            // Shockstep boots: landing a gap-jump stomps every enemy beside the landing
            // tile - damage plus a short Slow from the shockwave.
            if (spanTiles > 1
                    && CrafticsEnchantments.wornLevel(player, CrafticsEnchantments.SHOCKSTEP) > 0) {
                for (int sdx = -1; sdx <= 1; sdx++) {
                    for (int sdz = -1; sdz <= 1; sdz++) {
                        if (sdx == 0 && sdz == 0) continue;
                        CombatEntity stomped = arena.getOccupant(
                            new GridPos(next.x() + sdx, next.z() + sdz));
                        if (stomped == null || !stomped.isAlive() || stomped.isAlly()) continue;
                        int dealt = stomped.takeDamage(SwordAxeEnchantEffects.SHOCKSTEP_DAMAGE);
                        stomped.stackSlowness(SwordAxeEnchantEffects.SHOCKSTEP_SLOW_TURNS, 1);
                        sendMessage("§bShockstep! " + stomped.getDisplayName()
                            + " takes " + dealt + " from the landing and is Slowed!");
                        checkAndHandleDeath(stomped);
                    }
                }
                ServerWorld stompWorld = (ServerWorld) player.getEntityWorld();
                BlockPos stompBp = arena.gridToBlockPos(next);
                ProjectileSpawner.spawnExpandingRing(stompWorld, stompBp, 1.2,
                    net.minecraft.particle.ParticleTypes.CLOUD, 12);
                stompWorld.playSound(null, stompBp,
                    net.minecraft.sound.SoundEvents.ENTITY_GENERIC_BIG_FALL,
                    net.minecraft.sound.SoundCategory.PLAYERS, 0.8f, 1.1f);
            }
            if (player != null) {
                player.getWorld().playSound(null, player.getBlockPos(),
                    net.minecraft.sound.SoundEvents.BLOCK_STONE_STEP,
                    net.minecraft.sound.SoundCategory.PLAYERS, 0.3f, 1.0f);
            }

            // Walk-over pickup: retrieve exactly the trident(s) lying on THIS tile,
            // leaving any others where they landed.
            for (java.util.Iterator<DroppedTrident> it = droppedTridents.iterator(); it.hasNext();) {
                DroppedTrident dropped = it.next();
                if (!next.equals(dropped.pos())) continue;
                returnOneTrident(dropped);
                it.remove();
                sendMessage("§3You retrieve your " + dropped.stack().getName().getString() + "!");
            }

            if (tileEffects.containsKey(next) && tileEffects.get(next).startsWith("cake")) {
                String cakeData = tileEffects.get(next);
                int uses = 3;
                if (cakeData.contains(":")) {
                    try { uses = Integer.parseInt(cakeData.split(":")[1]); } catch (Exception ignored) {}
                }
                if (player.getHealth() < player.getMaxHealth()) {
                    player.setHealth(Math.min(player.getMaxHealth(), player.getHealth() + 2));
                    sendMessage("§dYou eat cake! +2 HP");
                }
                uses--;
                if (uses <= 0) {
                    tileEffects.remove(next);
                    sendMessage("§7The cake is all gone!");
                } else {
                    tileEffects.put(next, "cake:" + uses);
                }
            }

            lerpInitialized = false;
            movePathIndex++;
        }
    }

    /**
     * Build the arena for the level after this one, if it doesn't exist yet. Called from
     * the victory flow so the build cost is buried under the victory screen instead of
     * hitching the transition into the next fight. Global level numbering carries across
     * biome boundaries, and ensureArena's biome-stamp check self-corrects any New Game+
     * branch re-roll, so blindly prefetching level+1 is always safe - worst case the
     * stamp mismatches later and that entry rebuilds, exactly as it would have anyway.
     */
    private void prefetchNextArena() {
        try {
            if (player == null
                || !(levelDef instanceof com.crackedgames.craftics.level.GeneratedLevelDefinition gld)) {
                return;
            }
            if (!(player.getEntityWorld() instanceof ServerWorld sw)) return;
            CrafticsSavedData data = CrafticsSavedData.get(sw);
            java.util.UUID owner = data.getEffectiveWorldOwner(player.getUuid());
            if (owner == null || data.getPlayerData(owner).worldSlot < 0) return;
            int next = gld.getLevelNumber() + 1;
            long start = System.currentTimeMillis();
            int[] meta = com.crackedgames.craftics.level.ArenaPreGenerator.ensureArena(sw, owner, next);
            if (meta != null) {
                CrafticsMod.LOGGER.debug("Prefetched arena for level {} in {}ms",
                    next, System.currentTimeMillis() - start);
            }
        } catch (Exception e) {
            // Never let a prefetch failure disturb the victory flow - the level entry
            // path builds lazily exactly as before.
            CrafticsMod.LOGGER.warn("Next-arena prefetch failed (will build on entry): {}", e.toString());
        }
    }

    private void tickEnemyTurn() {
        // Trapper: spring any trap an enemy has stepped onto since the last tick.
        springTrapperTraps();

        // The room can empty DURING the enemy phase - a mob burns to death on its own turn,
        // walks into lava, or is killed by another mob - and every victory check in the file
        // is bolted onto a player action, so none of them see it. What is left is a fight with
        // nothing in it that the player can only end by taking another turn, and if anything
        // stalls the rotation they cannot even do that. Ending it here closes both.
        if (phase == CombatPhase.ENEMY_TURN && !anyEnemyBlockingVictory()) {
            handleVictory();
            return;
        }

        // Stall watchdog. The enemy phase is a state machine spread over ~60 arming sites, and
        // any one of them that returns without arming a delay or advancing the state leaves the
        // phase spinning on the same tick forever. The player is locked out entirely while that
        // happens: handleAction drops every input that is not PLAYER_TURN, so the reported
        // symptom is "end turn does nothing". Rather than trusting every site to be correct,
        // notice that nothing has changed for ENEMY_STALL_TICKS and force the rotation on.
        long stallKey = (long) enemyTurnIndex << 8 | enemyTurnState.ordinal();
        if (stallKey == lastEnemyStallKey) {
            if (++enemyStallTicks >= ENEMY_STALL_TICKS) {
                CrafticsMod.LOGGER.warn(
                    "Enemy turn stalled at index {} state {} ({}); forcing it forward",
                    enemyTurnIndex, enemyTurnState,
                    currentEnemy != null ? currentEnemy.getEntityTypeId() : "no entity");
                enemyStallTicks = 0;
                enemyLerpInitialized = false;
                pendingAction = null;
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = 0;
                tickEnemyDone();
                return;
            }
        } else {
            lastEnemyStallKey = stallKey;
            enemyStallTicks = 0;
        }
        // Cinematic pacing: stretch each freshly-armed action delay (~1.8x, clamped)
        // so the camera has time to pan onto the acting unit and linger before
        // returning. enemyTurnDelay is written in ~60 places but read only here, so
        // this single site scales them all once per arming. Respects the toggle and
        // skipEnemyAnimations; leaves deliberate instant chains (delay 0) untouched.
        if (!enemyTurnDelayScaled && enemyTurnDelay > 0
                && CrafticsMod.CONFIG.cinematicEnemyTurns()
                && !CrafticsMod.CONFIG.skipEnemyAnimations()) {
            enemyTurnDelay = Math.min(60, Math.round(enemyTurnDelay * 1.8f));
            enemyTurnDelayScaled = true;
        }
        if (enemyTurnDelay > 0) { enemyTurnDelay--; return; }
        enemyTurnDelayScaled = false; // consumed -the next arming re-scales

        switch (enemyTurnState) {
            case DECIDING -> tickEnemyDeciding();
            case MOVING -> tickEnemyMoving();
            case ANIMATING -> tickEnemyAnimating();
            case ATTACKING -> tickEnemyAttacking();
            case TANTRUM_HOPPING -> tickTantrumHopping();
            case DONE -> tickEnemyDone();
        }
    }

    /**
     * Ticks one mimic tantrum hop at a time. Called from {@link #tickEnemyTurn}
     * while {@link EnemyTurnState#TANTRUM_HOPPING}. Each invocation advances
     * {@link #tantrumIndex} by one and drives the visible mob to that tile so the
     * player sees each discrete bounce. Bails out early when the path is exhausted
     * or the mimic lands on the player.
     */
    private void tickTantrumHopping() {
        // Guard: finished, lost state, or already scored a hit -settle and advance.
        if (tantrumPath == null || tantrumHitPlayer || tantrumIndex >= tantrumPath.size()) {
            finalizeTantrum();
            return;
        }

        GridPos hop = tantrumPath.get(tantrumIndex++);

        // Defensive validation -arena shouldn't mutate mid-turn, but don't crash if it does.
        if (!arena.isInBounds(hop)) { finalizeTantrum(); return; }
        GridTile hopTile = arena.getTile(hop);
        if (hopTile == null) { finalizeTantrum(); return; }
        if (hopTile.getType() == com.crackedgames.craftics.core.TileType.OBSTACLE) { finalizeTantrum(); return; }

        ServerWorld tantrumWorld = (ServerWorld) player.getEntityWorld();
        MobEntity tantrumMob = currentEnemy.getMobEntity();

        // Did this hop land on the player's tile? Deal damage, stop the tantrum
        // on the last safe tile, don't occupy the player's spot.
        if (hop.equals(arena.getPlayerGridPos())) {
            int actual = damagePlayer(tantrumDamage, currentEnemy);
            sendMessage("§c  Slammed down on you for " + actual + " damage! (HP: " + getPlayerHp() + ")");
            tantrumWorld.playSound(null, arena.gridToBlockPos(hop),
                net.minecraft.sound.SoundEvents.ENTITY_GENERIC_EXPLODE.value(),
                net.minecraft.sound.SoundCategory.HOSTILE, 1.0f, 1.4f);
            tantrumWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                player.getX(), player.getY() + 0.5, player.getZ(),
                20, 0.5, 0.3, 0.5, 0.1);
            tantrumHitPlayer = true;
            if (getPlayerHp() <= 0) { handlePlayerDeathOrGameOver(); return; }
            finalizeTantrum();
            return;
        }

        // Another entity is in the way -skip this hop and try the next one
        // on the following tick (without a long pause).
        if (arena.isOccupied(hop)) {
            enemyTurnDelay = 1;
            return;
        }

        // Commit the hop: update the grid, teleport the visible mob, play VFX/SFX.
        arena.moveEntity(currentEnemy, hop);
        tantrumLandingTile = hop;
        if (tantrumMob != null) {
            double wx = arena.getOrigin().getX() + hop.x() + 0.5;
            double wz = arena.getOrigin().getZ() + hop.z() + 0.5;
            tantrumMob.requestTeleport(wx,
                arena.getEntityY(hop, currentEnemy.isFlying()), wz);
        }

        BlockPos hopBlock = arena.gridToBlockPos(hop);
        tantrumWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
            hopBlock.getX() + 0.5, hopBlock.getY() + 0.2, hopBlock.getZ() + 0.5,
            5, 0.3, 0.05, 0.3, 0.02);
        tantrumWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
            hopBlock.getX() + 0.5, hopBlock.getY() + 0.4, hopBlock.getZ() + 0.5,
            3, 0.2, 0.1, 0.2, 0.03);
        tantrumWorld.playSound(null, hopBlock,
            net.minecraft.sound.SoundEvents.ENTITY_SLIME_JUMP,
            net.minecraft.sound.SoundCategory.HOSTILE, 0.9f, 1.4f);

        // Push the grid-pos update to the client so the HUD mob marker follows along.
        sendSync();

        // Pace between hops -slime-jump-ish cadence.
        enemyTurnDelay = 4;
    }

    /**
     * Finalize a tantrum sequence: settle the visible mob on the last safe tile
     * (no-op if the loop already placed it), emit the "lands harmlessly" message
     * when the mimic missed, and transition back to the standard DONE state.
     */
    private void finalizeTantrum() {
        if (!tantrumHitPlayer) {
            sendMessage("§7  The mimic lands harmlessly.");
        }
        tantrumPath = null;
        tantrumIndex = 0;
        tantrumHitPlayer = false;
        sendSync();
        enemyTurnState = EnemyTurnState.DONE;
        enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
    }

    /**
     * Transform a confused enemy's REAL AI action so it strikes {@code victim} (another
     * enemy) instead of the player. Melee single-target actions become a MoveAndAttackMob
     * at the victim (real damage preserved). Ranged actions are returned UNCHANGED but the
     * victim is stored in {@code confusedRangedVictim} so the ranged resolver fires at it
     * (a confused skeleton shoots its ally). AoE / swoop / boss / summon / terrain return
     * null - the caller then lets the enemy act normally vs the player. Explode is left
     * as-is: it already damages nearby enemies, so a confused creeper adjacent to allies
     * catches them in the blast.
     */
    private EnemyAction redirectActionAtEnemy(EnemyAction real, CombatEntity victim,
                                              java.util.List<GridPos> path) {
        // Ranged: keep the action, aim the resolver at the victim entity.
        if (real instanceof EnemyAction.RangedAttack) {
            confusedRangedVictim = victim;
            return real;
        }
        if (real instanceof EnemyAction.MoveAndAttack
                && getRangedProjectileType(currentEnemy.getEntityTypeId()) != null) {
            // A MoveAndAttack that resolves as ranged (e.g. a repositioning shooter).
            confusedRangedVictim = victim;
            return real;
        }
        // Melee single-target: strike the victim with the action's real damage.
        int dmg = switch (real) {
            case EnemyAction.Attack a -> a.damage();
            case EnemyAction.MoveAndAttack m -> m.damage();
            case EnemyAction.AttackWithKnockback k -> k.damage();
            case EnemyAction.MoveAndAttackWithKnockback k -> k.damage();
            case EnemyAction.Pounce p -> p.damage();
            case EnemyAction.TeleportAndAttack t -> t.damage();
            default -> -1;
        };
        if (dmg < 0) return null; // unsupported: caller falls back to a normal player turn
        return new EnemyAction.MoveAndAttackMob(
            path != null ? path : java.util.List.of(), victim.getEntityId(), Math.max(1, dmg));
    }

    private void tickEnemyDeciding() {
        while (enemyTurnIndex < enemies.size() && !enemies.get(enemyTurnIndex).isAlive()) {
            enemyTurnIndex++;
        }

        if (enemyTurnIndex >= enemies.size()) {
            // All enemies done -start new player turn
            for (CombatEntity e : enemies) e.setDamagedSinceLastTurn(false);

            // --- Enemy DoT ticks (all status damage is Special type) ---
            for (CombatEntity e : enemies) {
                if (!e.isAlive() || e.getPoisonTurns() <= 0) continue;
                boolean wasAlive = e.isAlive();
                int poisonDmg = applyStatusDot(e, e.getPoisonTickDamage());
                e.setPoisonTurns(e.getPoisonTurns() - 1);
                sendMessage("§2" + e.getDisplayName() + " took " + poisonDmg + " poison damage.");
                if (e.getMobEntity() != null) {
                    ((ServerWorld) player.getEntityWorld()).spawnParticles(
                        net.minecraft.particle.ParticleTypes.ITEM_SLIME,
                        e.getMobEntity().getX(), e.getMobEntity().getY() + 1.0, e.getMobEntity().getZ(),
                        8, 0.3, 0.3, 0.3, 0.05);
                }
                if (wasAlive && !e.isAlive()) achievementTracker.recordPoisonKill();
                checkAndHandleDeath(e);
            }

            // --- Enemy Wither ticks: damage = remainingTurns + 1 + amp + maxHpBonus ---
            for (CombatEntity e : enemies) {
                if (!e.isAlive() || e.getWitherTurns() <= 0) continue;
                boolean wasAlive = e.isAlive();
                int witherDmg = applyStatusDot(e, e.getWitherTickDamage());
                e.setWitherTurns(e.getWitherTurns() - 1);
                sendMessage("§8" + e.getDisplayName() + " withers for " + witherDmg + " damage.");
                if (e.getMobEntity() != null) {
                    ((ServerWorld) player.getEntityWorld()).spawnParticles(
                        net.minecraft.particle.ParticleTypes.SOUL,
                        e.getMobEntity().getX(), e.getMobEntity().getY() + 1.0, e.getMobEntity().getZ(),
                        6, 0.3, 0.4, 0.3, 0.02);
                }
                if (e.getWitherTurns() <= 0) {
                    e.setWitherAmplifier(0);
                }
                if (wasAlive && !e.isAlive()) achievementTracker.recordWitherKill();
                checkAndHandleDeath(e);
            }

            if (!anyEnemyBlockingVictory()) {
                handleVictory();
                return;
            }

            for (CombatEntity e : enemies) {
                if (!e.isAlive() || e.getBurningTurns() <= 0) continue;
                boolean wasAlive = e.isAlive();
                int burnDmg = applyStatusDot(e, e.getBurningTickDamage());
                e.setBurningTurns(e.getBurningTurns() - 1);
                sendMessage("§6" + e.getDisplayName() + " burned for " + burnDmg + ".");
                if (e.getMobEntity() != null) {
                    ((ServerWorld) player.getEntityWorld()).spawnParticles(
                        net.minecraft.particle.ParticleTypes.FLAME,
                        e.getMobEntity().getX(), e.getMobEntity().getY() + 1.0, e.getMobEntity().getZ(),
                        10, 0.3, 0.5, 0.3, 0.02);
                }
                if (e.getBurningTurns() <= 0) {
                    e.setBurningAmplifier(0);
                }
                if (wasAlive && !e.isAlive()) achievementTracker.recordBurnKill();
                checkAndHandleDeath(e);
            }

            // --- Soul burn DOT: the same cycle as burning, on its own timer so a mob can
            // carry both at once (walking a soul fire into an ordinary one). Fire-immune
            // mobs tick too, just for less - the reduction lives in getSoulBurningTickDamage.
            for (CombatEntity e : enemies) {
                if (!e.isAlive() || e.getSoulBurningTurns() <= 0) continue;
                boolean wasAlive = e.isAlive();
                int soulDmg = applyStatusDot(e, e.getSoulBurningTickDamage());
                e.setSoulBurningTurns(e.getSoulBurningTurns() - 1);
                sendMessage("§3" + e.getDisplayName() + " is scorched by soul fire for " + soulDmg + ".");
                if (e.getMobEntity() != null) {
                    ((ServerWorld) player.getEntityWorld()).spawnParticles(
                        net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME,
                        e.getMobEntity().getX(), e.getMobEntity().getY() + 1.0, e.getMobEntity().getZ(),
                        10, 0.3, 0.5, 0.3, 0.02);
                }
                if (e.getSoulBurningTurns() <= 0) {
                    e.setSoulBurningAmplifier(0);
                }
                if (wasAlive && !e.isAlive()) achievementTracker.recordBurnKill();
                checkAndHandleDeath(e);
            }

            // --- Bleed DOT: damage grows with stack count, then 1 stack drops off ---
            for (CombatEntity e : enemies) {
                if (!e.isAlive() || e.getBleedStacks() <= 0) continue;
                // The big-target bonus is added OUTSIDE computeBleedTickDamage (unlike poison,
                // wither and burn, which fold it in), so the ceiling has to be re-applied to the
                // sum here or a high-max-HP enemy would bleed for more than MAX_BLEED_TICK.
                int bleedDmg = applyStatusDot(e, Math.min(EffectFormulas.MAX_BLEED_TICK,
                    CombatEntity.computeBleedTickDamage(e.getBleedStacks()) + e.getMaxHpDotBonus()));
                sendMessage("§4" + e.getDisplayName() + " bleeds for " + bleedDmg + " (" + e.getBleedStacks() + " stacks).");
                if (e.getMobEntity() != null) {
                    ((ServerWorld) player.getEntityWorld()).spawnParticles(
                        net.minecraft.particle.ParticleTypes.DAMAGE_INDICATOR,
                        e.getMobEntity().getX(), e.getMobEntity().getY() + 1.0, e.getMobEntity().getZ(),
                        6, 0.3, 0.5, 0.3, 0.02);
                }
                e.setBleedStacks(Math.max(0, e.getBleedStacks() - 1));
                checkAndHandleDeath(e);
            }

            // --- Custom (addon-registered) effect ticks ---
            for (CombatEntity e : enemies) {
                if (!e.isAlive() || e.getCustomEffects().isEmpty()) continue;
                tickCustomEffects(e);
                checkAndHandleDeath(e);
            }

            // Enemy Airtime/Levitation (visual + movement only). Levitation wearing off drops
            // the enemy into Airtime for 1 turn, mirroring the player rule.
            for (CombatEntity e : enemies) {
                if (!e.isAlive()) continue;
                // Tick any PRE-EXISTING Airtime first, so a fresh grant below survives this round.
                // (Ticking after the grant would decrement the just-granted stack straight back to 0,
                // making enemy Levitation->Airtime a no-op: no icon, no float, no fly-over next round.)
                e.tickAirtimeState();
                boolean levWasActive = e.getLevitationStateTurns() > 0;
                e.tickLevitationState();
                if (levWasActive && e.getLevitationStateTurns() == 0) {
                    e.applyAirtimeState(1);
                }
            }

            // --- Positive buff ticks on allies (instrument support performances) ---
            for (CombatEntity e : enemies) {
                if (e.isAlive() && e.isAlly()) e.tickBuffs();
            }

            if (!anyEnemyBlockingVictory()) {
                handleVictory();
                return;
            }

            for (CombatEntity e : enemies) {
                if (!e.isAlive() || e.getDefensePenaltyTurns() <= 0) continue;
                e.setDefensePenaltyTurns(e.getDefensePenaltyTurns() - 1);
                if (e.getDefensePenaltyTurns() <= 0) {
                    e.setDefensePenalty(0);
                }
            }

            for (CombatEntity e : enemies) {
                if (!e.isAlive() || e.getAttackPenaltyTurns() <= 0) continue;
                e.setAttackPenaltyTurns(e.getAttackPenaltyTurns() - 1);
                if (e.getAttackPenaltyTurns() <= 0) {
                    e.setAttackPenalty(0);
                    sendMessage("§7" + e.getDisplayName() + " is no longer weakened.");
                }
            }

            // Marked countdown -clear the glow + status when it expires.
            for (CombatEntity e : enemies) {
                if (e.getMarkedTurns() <= 0) continue;
                e.setMarkedTurns(e.getMarkedTurns() - 1);
                if (e.getMarkedTurns() <= 0) {
                    if (e.getMobEntity() != null) e.getMobEntity().setGlowing(false);
                    if (e.isAlive()) sendMessage("§7" + e.getDisplayName() + " is no longer marked.");
                }
            }

            for (CombatEntity e : enemies) {
                if (!e.isAlive() || e.getSoakedTurns() <= 0) continue;
                e.setSoakedTurns(e.getSoakedTurns() - 1);
                if (e.getSoakedTurns() <= 0) {
                    e.setSoakedAmplifier(0);
                    sendMessage("§3" + e.getDisplayName() + " dried off.");
                }
            }

            for (CombatEntity e : enemies) {
                if (!e.isAlive() || e.getSlownessTurns() <= 0) continue;
                e.setSlownessTurns(e.getSlownessTurns() - 1);
                if (e.getSlownessTurns() <= 0) {
                    e.setSlownessPenalty(0);
                    sendMessage("§7" + e.getDisplayName() + " is no longer slowed.");
                }
            }

            if (hexTrapTurnsRemaining > 0) {
                hexTrapTurnsRemaining--;
                if (hexTrapTurnsRemaining <= 0) {
                    tileEffects.entrySet().removeIf(e -> "hex_trap".equals(e.getValue()));
                }
            }

            List<GridPos> expiredWebs = arena.tickWebOverlays();
            if (!expiredWebs.isEmpty()) {
                ServerWorld world = (ServerWorld) player.getEntityWorld();
                for (GridPos pos : expiredWebs) {
                    BlockPos bp = arena.gridToBlockPos(pos);
                    world.setBlockState(bp.up(1), net.minecraft.block.Blocks.AIR.getDefaultState(),
                        net.minecraft.block.Block.NOTIFY_ALL);
                }
            }

            tickPlacedWalls();

            // Player-side per-turn effects (trim regen, DoT, tile hazards, campfire
            // heal, poison-cloud breath) run once PER PARTY MEMBER, not just for the
            // single host/last-actor. Previously this block ran against this.player
            // and arena.getPlayerGridPos() only, so in co-op every member except the
            // last to act never had their poison/burn/wither tick (DoTs were
            // cosmetic), and tile hazards/heals were evaluated against the wrong
            // tile. Each member is swapped in via the this.player pattern so their
            // own effects map, trim scan, and HP are used. mirrors the creeper
            // blast loop. tickPlayerPerTurnEffects returns true if the whole game
            // ended (party wiped), in which case we abort the tick.
            {
                ServerPlayerEntity savedTurnPlayer = this.player;
                GridPos savedGrid = arena.getPlayerGridPos();
                boolean gameOver = false;
                java.util.List<ServerPlayerEntity> ptMembers = partyPlayers.size() > 1
                    ? new java.util.ArrayList<>(partyPlayers)
                    : java.util.List.of(player);
                for (ServerPlayerEntity member : ptMembers) {
                    if (member == null || member.isRemoved() || member.isDisconnected()) continue;
                    if (deadPartyMembers.contains(member.getUuid())) continue;
                    boolean swapped = member != savedTurnPlayer;
                    if (swapped) {
                        this.player = member;
                        retargetEffectsToCurrentPlayer();
                        arena.setPlayerGridPos(gridPosOf(member));
                    }
                    // ORDER MATTERS: an effect must PAY OUT before it expires.
                    //
                    // tickTurn() decrements durations and REMOVES anything that hits 0, and
                    // applyPerTurnEffects (inside tickPlayerPerTurnEffects) only reads effects
                    // that are still present. Running the tick first therefore deleted an
                    // effect on its final turn before that turn's heal/damage ever ran, so an
                    // N-turn effect only paid out N-1 times: 3-turn Regeneration healed twice,
                    // and poison / wither / burning / bleeding all silently lost their last
                    // tick. Poison and wither read turnsRemaining in their damage formulas too,
                    // so the ordering skewed their numbers as well, not just the count.
                    if (tickPlayerPerTurnEffects()) { gameOver = true; break; }

                    // Now tick down THIS member's durations. combatEffects is retargeted to
                    // them above, so Slowness/Poison/Strength/shields expire per member.
                    String memberExpired = combatEffects.tickTurn();

                    // Iron Will helmet: mental debuffs (Confusion/Blindness/Darkness) lose a
                    // second turn, halving how long they cloud the wearer.
                    if (CrafticsEnchantments.wornLevel(player, CrafticsEnchantments.IRON_WILL) > 0) {
                        String mentalExpired = combatEffects.tickMentalEffectsExtra();
                        if (mentalExpired != null) {
                            sendMessage("§bIron Will shakes off: " + mentalExpired);
                        }
                    }

                    // Riding out a Levitation drops you into Airtime: grant Airtime I (1 turn) the turn
                    // Levitation wears off. combatEffects is already retargeted to this member here.
                    if (combatEffects.getLastExpired().contains(CombatEffects.EffectType.AIRTIME) == false
                            && combatEffects.getLastExpired().contains(CombatEffects.EffectType.LEVITATION)) {
                        combatEffects.addEffect(CombatEffects.EffectType.AIRTIME, 1, 0);
                    }

                    if (memberExpired != null) {
                        for (CombatEffects.EffectType expType : combatEffects.getLastExpired()) {
                            var mcEffect = mapCombatToVanillaEffect(expType);
                            if (mcEffect != null) member.removeStatusEffect(mcEffect);
                        }
                    }
                    for (CombatEffects.EffectType expiredType : combatEffects.getLastExpired()) {
                        final CombatEffects.EffectType expType = expiredType;
                        fireEffectHook(h -> h.onEffectExpired(effectContext, expType));
                    }
                }
                // Restore the original turn-holder ONLY if they survived. If the
                // turn-holder died mid-pass, handlePlayerDeathOrGameOver already
                // reassigned this.player to a survivor -leave it there rather than
                // re-activating the dead player.
                if (!gameOver && this.player != savedTurnPlayer
                        && !deadPartyMembers.contains(savedTurnPlayer.getUuid())) {
                    this.player = savedTurnPlayer;
                    retargetEffectsToCurrentPlayer();
                }
                arena.setPlayerGridPos(savedGrid);
                if (gameOver) return;
            }

            for (var entry : tileEffects.entrySet()) {
                GridPos tPos = entry.getKey();
                String effect = entry.getValue();
                if ("lava".equals(effect)) {
                    CombatEntity occupant = arena.getOccupant(tPos);
                    if (occupant != null && occupant.isAlive() && !occupant.isAlly()) {
                        occupant.takeDamage(3);
                        if (occupant.getMobEntity() != null) occupant.getMobEntity().setFireTicks(60);
                        sendMessage("§6" + occupant.getDisplayName() + " burns in lava for 3 damage!");
                    }
                }
                if ("poison_cloud".equals(effect)) {
                    // Enemy-side only: spawn the cloud and damage enemy occupants once.
                    // The player-breath self-damage is handled per-member above in
                    // tickPlayerPerTurnEffects so each member in the cloud takes it.
                    ProjectileSpawner.spawnLingeringCloud(
                        (ServerWorld) player.getEntityWorld(), arena.gridToBlockPos(tPos));
                    // 3x3 AoE around cloud center
                    java.util.Set<CombatEntity> cloudHits = new java.util.HashSet<>();
                    for (int dx = -1; dx <= 1; dx++) {
                        for (int dz = -1; dz <= 1; dz++) {
                            GridPos checkPos = new GridPos(tPos.x() + dx, tPos.z() + dz);
                            CombatEntity occ = arena.getOccupant(checkPos);
                            if (occ != null && occ.isAlive() && !occ.isAlly()) cloudHits.add(occ);
                        }
                    }
                    for (CombatEntity hit : cloudHits) {
                        int dealt = applySpecialUtilityDamage(hit, 2);
                        sendMessage("§5" + hit.getDisplayName() + " chokes in poison cloud for " + dealt + " damage!");
                        checkAndHandleDeath(hit);
                    }
                }
                if ("cactus".equals(effect)) {
                    for (CombatEntity e : enemies) {
                        if (!e.isAlive() || e.isAlly()) continue;
                        int d = Math.abs(e.getGridPos().x() - tPos.x()) + Math.abs(e.getGridPos().z() - tPos.z());
                        if (d <= 1) {
                            e.takeDamage(1);
                            sendMessage("§2" + e.getDisplayName() + " is pricked by cactus for 1 damage!");
                        }
                    }
                }
                if (BannerEffects.isBannerEffect(effect)) {
                    ServerWorld bannerWorld = (ServerWorld) player.getEntityWorld();
                    for (int dx = -BannerEffects.AURA_RADIUS; dx <= BannerEffects.AURA_RADIUS; dx++) {
                        for (int dz = -BannerEffects.AURA_RADIUS; dz <= BannerEffects.AURA_RADIUS; dz++) {
                            if (Math.abs(dx) + Math.abs(dz) > BannerEffects.AURA_RADIUS) continue;
                            GridPos auraPos = new GridPos(tPos.x() + dx, tPos.z() + dz);
                            if (!arena.isInBounds(auraPos)) continue;
                            BlockPos auraBp = arena.gridToBlockPos(auraPos);
                            bannerWorld.spawnParticles(net.minecraft.particle.ParticleTypes.HAPPY_VILLAGER,
                                auraBp.getX() + 0.5, auraBp.getY() + 0.1, auraBp.getZ() + 0.5,
                                3, 0.3, 0.05, 0.3, 0.0);
                        }
                    }
                }
            }
            // Timed traps: mend/harm whoever stands in them, age them, drop the spent ones.
            tickTileTraps();

            // Lightning rod -single-use, strikes then self-removes
            tileEffects.entrySet().removeIf(entry -> {
                if ("lightning".equals(entry.getValue())) {
                    GridPos tPos = entry.getKey();
                    int hit = 0;
                    for (CombatEntity e : enemies) {
                        if (!e.isAlive() || e.isAlly()) continue;
                        int d = Math.abs(e.getGridPos().x() - tPos.x()) + Math.abs(e.getGridPos().z() - tPos.z());
                        if (d <= 1) {
                            // Soaked doubles lightning -mirrors CombatEntity.takeLightningDamage
                            // (canonical rule). The rod keeps the SPECIAL-resistance utility path,
                            // so it applies the same 2x factor here rather than routing through it.
                            int lightningDmg = e.isSoaked() ? 4 * 2 : 4;
                            applySpecialUtilityDamage(e, lightningDmg);
                            hit++;
                        }
                    }
                    if (hit > 0) sendMessage("§e⚡ Lightning strikes! " + hit + " enemies hit!");
                    else sendMessage("§eLightning rod fizzles -no enemies nearby.");
                    return true;
                }
                return false;
            });

            turnNumber++;
            achievementTracker.recordTurnCompleted();
            tickSuddenDeath();

            for (CombatEntity e : enemies) {
                if (e.isAlive() && e.isBackgroundBoss()) {
                    triggerGhastScream(e, false);
                }
            }

            long allyCount = enemies.stream().filter(e -> e.isAlive() && e.isAlly()).count();
            achievementTracker.recordLivingAllies((int) allyCount);

            // Same room-clear rule as every other victory path: scenery left standing is not a
            // reason to keep the fight open, or this auto-end would never tick with a grave up.
            //
            // Ends the level on the spot rather than counting off "auto-ending in N turns". The
            // countdown was already a lie: tickEnemyTurn runs the identical check one tick later
            // and wins the fight there, so the only thing the counter produced was a promise of
            // three more turns immediately followed by VICTORY. Nothing the player can still do
            // in a room holding only graves, hives and other scenery is worth waiting for.
            if (!anyEnemyBlockingVictory()) {
                sendMessage("§a§lNo enemies remain! Combat complete.");
                handleVictory();
                return;
            }

            endTurnHintSent = false;
            movedThisTurn = false;
            tilesMovedThisTurn = 0;
            attackedWithoutShieldThisTurn = false;

            tickTemporaryTerrain();
            // Advance fire AFTER existing temporary tiles decay, so a tile lit
            // this tick keeps its full burn duration instead of losing a turn.
            tickFire();
            tickFissureDebris();
            tickCollapseRubble();
            tickWardenMarkHunt();
            tickTidecallerWave();
            detonatePendingTnts();

            handOffRoundToFirstPartyPlayer();

            // Re-scan the acting player's equipment EVERY round start - solo included.
            // This scan used to live only inside the party branch above, so a solo
            // player who equipped an artifact (e.g. Running Shoes) mid-fight kept the
            // stale combat-start scan and never received the new bonuses.
            this.activeTrimScan = TrimEffects.scan(player);
            this.activeCombatEffects = activeTrimScan.getCombatEffects();
            if (effectContext != null) effectContext.update(player, arena, combatEffects, activeTrimScan);

            // `player` may have been switched by the turn queue above
            PlayerProgression turnProg = PlayerProgression.get((ServerWorld) player.getEntityWorld());
            PlayerProgression.PlayerStats turnStats = turnProg.getStats(player);
            apRemaining = turnStats.getEffective(PlayerProgression.Stat.AP);
            apRemaining += PlayerCombatStats.getSetApBonus(player);
            if (activeTrimScan != null) apRemaining += activeTrimScan.get(TrimEffects.Bonus.AP);
            apRemaining += combatEffects.getHasteBonus();              // Haste: +1 AP per level
            apRemaining = Math.max(0, apRemaining - combatEffects.getMiningFatiguePenalty());
            apRemaining += consumePendingMomentumAp();
            movePointsRemaining = baseSpeedStat(turnStats)
                + combatEffects.getSpeedBonus() - combatEffects.getSpeedPenalty();
            movePointsRemaining += PlayerCombatStats.getSetSpeedBonus(player);
            if (activeTrimScan != null) movePointsRemaining += activeTrimScan.get(TrimEffects.Bonus.SPEED);
            movePointsRemaining -= combatEffects.getLevitationPenalty(); // Levitation: -1 movement per level
            if (combatEffects.hasEffect(CombatEffects.EffectType.SOAKED)) {
                movePointsRemaining = Math.max(1, movePointsRemaining - 1);
            }
            movePointsRemaining = Math.max(0, movePointsRemaining);
            phase = CombatPhase.PLAYER_TURN;
            player.getWorld().playSound(null, player.getBlockPos(),
                net.minecraft.sound.SoundEvents.BLOCK_NOTE_BLOCK_CHIME.value(),
                net.minecraft.sound.SoundCategory.PLAYERS, 0.8f, 1.2f);
            if (turnQueue.size() > 1) {
                sendMessage("§e" + player.getName().getString() + "'s turn! §aAP: " + apRemaining + " | SPD: " + movePointsRemaining);
            } else {
                sendMessage("§aAP: " + apRemaining + " | SPD: " + movePointsRemaining);
            }
            fireEffectHook(h -> h.onTurnStart(effectContext));

            // Rebuild the netherite mount's 1×3 wall for the rider's turn so it persists
            // and follows the rider (it no longer blocks the rider's own movement).
            refreshMountWall();

            // Warden set "Echo": the wearer is permanently shrouded. Refreshed every
            // turn (for longer than a turn) so the fog-of-war never blinks off during
            // the enemy phase. Goes through addEffectHooked so addon immunities can
            // still intercept it like any other Darkness source.
            if (com.crackedgames.craftics.compat.deeperanddarker.WardenSetEffects.isFullSet(player)) {
                addEffectHooked(CombatEffects.EffectType.DARKNESS,
                    com.crackedgames.craftics.compat.deeperanddarker.WardenSetEffects.DARKNESS_TURNS, 0);
            }

            // Hazard tile damage at turn start (must match startPlayerTurn logic)
            GridTile qTurnTile = arena.getTile(arena.getPlayerGridPos());
            if (qTurnTile != null) {
                if (qTurnTile.getType() == com.crackedgames.craftics.core.TileType.LAVA && !playerMounted
                        && !combatEffects.hasFireResistance()
                        && !PlayerCombatStats.wearsHead(player, Items.PIGLIN_HEAD)) {
                    int lavaDmg = damagePlayerFromTile(10, null);
                    sendMessage("§6  Standing in lava! " + lavaDmg + " damage! (HP: " + getPlayerHp() + ")");
                    if (getPlayerHp() <= 0) { sendSync(); handlePlayerDeathOrGameOver(); return; }
                } else if (qTurnTile.getType().isFlames()
                        && !combatEffects.hasFireResistance()
                        && !PlayerCombatStats.wearsHead(player, Items.PIGLIN_HEAD)) {
                    applyFireTileBurnToPlayer(qTurnTile.getType());
                }
                if (qTurnTile.getType() == com.crackedgames.craftics.core.TileType.POWDER_SNOW
                        && !hasLeatherBoots() && !playerMounted) {
                    powderSnowTurns++;
                    int freezeDmg = (int) Math.pow(2, powderSnowTurns - 1);
                    int actual = damagePlayerFromTile(freezeDmg, null);
                    sendMessage("§b  Freezing! " + actual + " damage! (Turn " + powderSnowTurns + " in snow)");
                    if (getPlayerHp() <= 0) { sendSync(); handlePlayerDeathOrGameOver(); return; }
                } else {
                    powderSnowTurns = 0;
                }
            }

            sendSync();
            refreshHighlights();
            sendToAllParty(new CombatEventPayload(
                CombatEventPayload.EVENT_PHASE_CHANGED, 0,
                CombatPhase.PLAYER_TURN.ordinal(), apRemaining, 0, 0
            ));
            return;
        }

        currentEnemy = enemies.get(enemyTurnIndex);
        currentEnemyPetAggroTarget = null;
        // Deadeye hybrid: record that this enemy has begun a turn -once it has,
        // it no longer counts as "hasn't acted" for the ranged damage bonus.
        hybridEnemiesActed.add(currentEnemy.getEntityId());

        if (currentEnemy.isStunned()) {
            sendMessage("§7" + currentEnemy.getDisplayName() + " is stunned!");
            // Visible daze: head down, arms slack, wobble (auto-expires).
            if (currentEnemy.getMobEntity() != null) {
                com.crackedgames.craftics.combat.animation.MobAnimations.set(
                    currentEnemy.getMobEntity(),
                    com.crackedgames.craftics.combat.animation.AnimState.STUNNED);
            }
            currentEnemy.setStunned(false);
            enemyTurnState = EnemyTurnState.DONE;
            enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            return;
        }

        confusedRangedVictim = null; // reset per enemy turn; set only on a confused-ranged redirect
        if (currentEnemy.getConfusionTurns() > 0 && !currentEnemy.isAlly()) {
            // Confusion ticks down every confused turn regardless of what happens.
            currentEnemy.setConfusionTurns(currentEnemy.getConfusionTurns() - 1);

            // 50/50: this turn the enemy is either disoriented (redirects its REAL attack
            // at a random enemy) or acts completely normally against the player.
            boolean disoriented = com.crackedgames.craftics.combat.ConfusionLogic.rollHits(
                Math.random(), CrafticsMod.CONFIG.confusedRetargetChance());
            if (disoriented) {
                java.util.List<CombatEntity> teammates = new java.util.ArrayList<>();
                for (CombatEntity e : enemies) {
                    if (e != currentEnemy && e.isAlive() && !e.isAlly()) teammates.add(e);
                }
                if (!teammates.isEmpty()) {
                    // Pick a random reachable teammate (size-aware path so a 2x2 mob's
                    // footprint routes correctly).
                    java.util.Collections.shuffle(teammates);
                    CombatEntity victim = null;
                    java.util.List<GridPos> path = null;
                    for (CombatEntity candidate : teammates) {
                        java.util.List<GridPos> p = Pathfinding.findPathSized(arena,
                            currentEnemy.getGridPos(), candidate.getGridPos(),
                            currentEnemy.getMoveSpeed(), currentEnemy,
                            currentEnemy.getSizeX(), currentEnemy.getSizeZ(),
                            currentEnemy.hasAirtimeState() || currentEnemy.hasLevitationState());
                        GridPos end = (p == null || p.isEmpty())
                            ? currentEnemy.getGridPos() : p.get(p.size() - 1);
                        if (candidate.minChebyshevDistanceTo(end) <= 1) {
                            victim = candidate;
                            path = p;
                            break;
                        }
                    }
                    if (victim != null) {
                        // Run the REAL AI aimed at the victim, then redirect its action.
                        EnemyAI confusedAi = resolveAi(currentEnemy);
                        EnemyAction realAction = confusedAi.decideAction(
                            currentEnemy, arena, victim.getGridPos());
                        EnemyAction redirected = redirectActionAtEnemy(realAction, victim, path);
                        if (redirected != null) {
                            sendMessage("§d" + currentEnemy.getDisplayName()
                                + " is confused and turns on " + victim.getDisplayName() + "!");
                            pendingAction = redirected;
                            boolean isRanged = confusedRangedVictim != null;
                            if (!isRanged && redirected instanceof
                                    com.crackedgames.craftics.combat.ai.EnemyAction.MoveAndAttackMob mam
                                    && mam.path() != null && !mam.path().isEmpty()) {
                                startEnemyMove(mam.path());
                            } else {
                                startAttackAnimation(CrafticsMod.CONFIG.enemyTurnDelay());
                            }
                            return;
                        }
                        // Unsupported action (AoE/swoop/boss/etc): fall through to a normal
                        // player-targeted turn below.
                    } else {
                        // Nobody reachable: stagger toward the nearest teammate, hit nothing.
                        teammates.sort(java.util.Comparator.comparingInt(
                            e -> e.minDistanceTo(currentEnemy.getGridPos())));
                        java.util.List<GridPos> stagger = Pathfinding.findPathSized(arena,
                            currentEnemy.getGridPos(), teammates.get(0).getGridPos(),
                            currentEnemy.getMoveSpeed(), currentEnemy,
                            currentEnemy.getSizeX(), currentEnemy.getSizeZ(),
                            currentEnemy.hasAirtimeState() || currentEnemy.hasLevitationState());
                        sendMessage("§d" + currentEnemy.getDisplayName()
                            + " staggers about in confusion!");
                        if (stagger != null && !stagger.isEmpty()) {
                            pendingAction = new com.crackedgames.craftics.combat.ai.EnemyAction.Move(stagger);
                            startEnemyMove(stagger);
                        } else {
                            enemyTurnState = EnemyTurnState.DONE;
                            enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                        }
                        return;
                    }
                }
                // No teammates OR unsupported redirect: fall through to a normal turn.
            }
            // Not disoriented (50%) OR redirect fell through: take a normal turn. Do NOT
            // return - control continues to the normal ai.decideAction path below. But if
            // ALSO blinded, fumble now so both debuffs don't double-tick this round.
            if (currentEnemy.getBlindedTurns() > 0) {
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                return;
            }
        }

        if (currentEnemy.getBlindedTurns() > 0 && !currentEnemy.isAlly()) {
            // Fumble the turn outright (no swing animation), like the stun path -
            // a blinded enemy can't see to attack, so it just loses its turn.
            currentEnemy.setBlindedTurns(currentEnemy.getBlindedTurns() - 1);
            sendMessage("§9" + currentEnemy.getDisplayName() + " is blinded and can't see to attack!");
            enemyTurnState = EnemyTurnState.DONE;
            enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            return;
        }

        if (currentEnemy.isAlly()) {
            handleAllyTurn(currentEnemy);
            return;
        }

        // Some AIs react to player's held item (e.g. cat)
        arena.setPlayerHeldItemId(net.minecraft.registry.Registries.ITEM
            .getId(player.getMainHandStack().getItem()).toString());

        EnemyAI ai = resolveAi(currentEnemy);
        // Resolve pending telegraphs for anything running on a BossAI -real bosses
        // AND mirror-image clones that run VoidWalkerAI with their own state.
        // Skip on an infinite boss's 2nd+ action of the SAME enemy phase
        // (inf_actions_used > 0): a telegraph stored by action 1 must survive
        // until the player has had a turn to react, not resolve seconds later.
        if ((currentEnemy.isBoss() || ai instanceof BossAI)
                && currentEnemy.getAiMemory("inf_actions_used", 0) == 0) {
            resolvePendingBossWarnings(currentEnemy);
        }
        if (currentEnemy.isBoss()) {
            CrafticsMod.LOGGER.info("[BOSS DEBUG] Boss '{}' aiKey='{}' resolved AI class={}",
                currentEnemy.getDisplayName(), currentEnemy.getAiKey(), ai.getClass().getSimpleName());
        }
        refreshAllPlayerGridPositions();
        CombatEntity tauntTarget = resolveTauntTarget(currentEnemy);
        currentEnemyPetAggroTarget = tauntTarget != null ? tauntTarget : resolveAggroPetTarget(currentEnemy);
        GridPos aiTargetPos;
        if (currentEnemyPetAggroTarget != null) {
            aiTargetPos = currentEnemyPetAggroTarget.getGridPos();
        } else {
            java.util.List<GridPos> allPlayers = arena.getAllPlayerGridPositions();
            if (allPlayers.size() > 1) {
                final CombatEntity enemy = currentEnemy;
                aiTargetPos = allPlayers.stream()
                    .min(java.util.Comparator.comparingInt(p -> enemy.minDistanceTo(p)))
                    .orElse(arena.getPlayerGridPos());
            } else {
                aiTargetPos = arena.getPlayerGridPos();
            }
        }
        // Creaking freeze: can't move when the player is looking at it (90° cone).
        // Uses dot-product to check if the creaking falls anywhere inside the
        // player's forward-facing cone. When not observed, the creaking has 6 speed.
        if (com.crackedgames.craftics.compat.palegardenbackport
                .PaleGardenBackportCompat.isCreakingEntity(currentEnemy.getEntityTypeId())) {
            BlockPos creakingBlock = arena.gridToBlockPos(currentEnemy.getGridPos());
            // Player's look direction on the XZ plane from their yaw
            double yawRad = Math.toRadians(player.getYaw());
            double lookX = -Math.sin(yawRad);
            double lookZ = Math.cos(yawRad);
            // Vector from player to creaking
            double toX = creakingBlock.getX() + 0.5 - player.getX();
            double toZ = creakingBlock.getZ() + 0.5 - player.getZ();
            double dist = Math.sqrt(toX * toX + toZ * toZ);
            boolean playerLooking = false;
            if (dist > 0.1) {
                // Dot product gives cos(angle) between look direction and direction to creaking
                double cosAngle = (lookX * toX + lookZ * toZ) / dist;
                // 90° cone = 45° each side → cos(45°) ≈ 0.707
                playerLooking = cosAngle > 0.707;
            }
            if (playerLooking) {
                // Hard freeze -flag bypasses the Math.max(1, ...) speed clamp AND
                // CreakingAI returns Idle so it can't attack either.
                currentEnemy.setFrozen(true);
                sendMessage("\u00a77The Creaking freezes under your gaze...");
            } else {
                currentEnemy.setFrozen(false);
                currentEnemy.setSpeedBonus(6 - currentEnemy.getMoveSpeed()); // 6 effective speed when unobserved
            }
        }

        // Invisibility target gate: while the player is invisible, enemies that would
        // target the player can't see them and skip their action. Enemies aggroed onto
        // a pet (currentEnemyPetAggroTarget) still act against the pet.
        boolean invisibleToThisEnemy = combatEffects.isInvisible() && currentEnemyPetAggroTarget == null;

        // Stealth-tile target gate: if the player is on a tall-grass/fern tile
        // and we're not adjacent, we can't see them -skip the turn entirely.
        // Bosses included (per design: bosses do not ignore tall grass).
        // A burning mob breaks off and runs for water. This sits AHEAD of the mob's own AI so
        // all of them inherit it without touching 50-odd AI classes, and it yields (returns
        // null) whenever the mob isn't alight or there's no water it can reach, in which case
        // the normal AI runs untouched. Bosses are exempt: a boss abandoning its fight to go
        // paddle would gut the encounter.
        // Water-immune mobs (drowned, guardians, ...) don't get Soaked by wading, so running
        // for water would never put them out - they'd just jog back and forth on fire forever.
        // They keep fighting and let the burn tick out.
        EnemyAction waterSeek = (currentEnemy.isBoss()
                || isWaterImmune(currentEnemy.getEntityTypeId()))
            ? null
            : com.crackedgames.craftics.combat.ai.AIUtils.seekWaterIfBurning(currentEnemy, arena);

        // Cleared before every decision, not after every hit. A per-action override is only
        // meaningful for the action the AI is about to name, and leaving a stale one set would
        // silently retype - or silently re-roll - every later attack that never asked for it.
        //
        // Above the branch rather than inside it: the water-seek and stealth-search branches
        // below return an action WITHOUT consulting the AI, so a clear that lived in the else
        // let an override outlive the action it was set for whenever a burning mob went for
        // water or lost sight of its target.
        currentEnemy.setPendingAttackType(null);
        currentEnemy.setPendingAccuracy(AccuracyRoll.NO_OVERRIDE);

        if (waterSeek != null) {
            pendingAction = waterSeek;
        } else if (invisibleToThisEnemy
                || StealthTiles.isConcealedFrom(arena, currentEnemy.getGridPos(), aiTargetPos, player.getEntityWorld())) {
            // Target is hidden. Hunt for it instead of standing still: close on the
            // nearest cover and thrash it open. Losing the grass is the cost of
            // hiding in it, so stealth buys time rather than permanent safety.
            pendingAction = searchForHiddenTarget(currentEnemy);
        } else {
            pendingAction = ai.decideAction(currentEnemy, arena, aiTargetPos);
            // Mob-vs-mob predators: downgrade to Idle if the prey is on a stealth
            // tile and we're not adjacent to it. Uses the returned action's target.
            pendingAction = gateMobTargetingThroughStealth(currentEnemy, pendingAction);
        }

        // Boss phase change: addon notification + the on-screen moment
        if (ai instanceof BossAI bai && bai.consumePhaseTransition()) {
            final CombatEntity fBoss = currentEnemy;
            fireEffectHook(h -> h.onBossPhaseChange(effectContext, fBoss, 2));
            announceBossPhaseTwo(fBoss);
        }

        // Trim STEALTH_RANGE bonus: enemies beyond detection range skip their turn
        int stealthRange = activeTrimScan != null ? activeTrimScan.get(TrimEffects.Bonus.STEALTH_RANGE) : 0;
        if (stealthRange > 0 && !currentEnemy.isBoss()) {
            int detectionRange = 3 + stealthRange; // base 3 + bonus
            int distToPlayer = currentEnemy.minDistanceTo(arena.getPlayerGridPos());
            if (distToPlayer > detectionRange) {
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = Math.max(1, CrafticsMod.CONFIG.enemyTurnDelay() / 2);
                return;
            }
        }

        // Modded instrument: a non-boss mob holding one PERFORMS it this turn instead
        // of its normal action - an ATTACK instrument aimed at the player, or a SUPPORT
        // one buffing its allies. Falls through to the normal action if it can't perform
        // (player out of shape / no allies to buff).
        if (!currentEnemy.isBoss() && currentEnemy.getMobEntity() != null) {
            ItemStack heldInstrument = currentEnemy.getMobEntity().getMainHandStack();
            if (com.crackedgames.craftics.compat.instruments.InstrumentsCompat
                    .isInstrument(heldInstrument.getItem())
                    && resolveMobInstrument(currentEnemy,
                        com.crackedgames.craftics.compat.instruments.InstrumentsCompat
                            .defFor(heldInstrument.getItem()))) {
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                pendingAction = null;
                return;
            }
        }

        switch (pendingAction) {
            case EnemyAction.Move move -> startEnemyMove(move.path());
            case EnemyAction.Flee flee -> startEnemyMove(flee.path());
            case EnemyAction.MoveAndAttack maa -> startEnemyMove(maa.path());
            case EnemyAction.MoveAttackMove mam -> startEnemyMove(mam.approachPath());
            case EnemyAction.Attack atk -> {
                startAttackAnimation(CrafticsMod.CONFIG.enemyTurnDelay());
            }
            case EnemyAction.Teleport tp -> {
                sendMessage("§5" + currentEnemy.getDisplayName() + " teleports!");
                MobEntity mob = currentEnemy.getMobEntity();
                if (mob != null) {
                    double wx = arena.getOrigin().getX() + tp.target().x() + 0.5;
                    double wz = arena.getOrigin().getZ() + tp.target().z() + 0.5;
                    mob.requestTeleport(wx,
                        arena.getEntityY(tp.target(), currentEnemy.isFlying()), wz);
                }
                arena.moveEntity(currentEnemy, tp.target());
                // Rift chain: if the teleport landed on a portal, slingshot through it.
                handleEnemyVoidRiftEntry(currentEnemy, tp.target());
                // Movement-only turn -announce the actor for the act-order strip.
                sendToAllParty(new CombatEventPayload(
                    CombatEventPayload.EVENT_MOVED, currentEnemy.getEntityId(), 0, 0,
                    tp.target().x(), tp.target().z()));
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.TeleportAndAttack tpa -> {
                sendMessage("§5" + currentEnemy.getDisplayName() + " teleports behind you!");
                MobEntity mob = currentEnemy.getMobEntity();
                if (mob != null) {
                    double wx = arena.getOrigin().getX() + tpa.target().x() + 0.5;
                    double wz = arena.getOrigin().getZ() + tpa.target().z() + 0.5;
                    mob.requestTeleport(wx,
                        arena.getEntityY(tpa.target(), currentEnemy.isFlying()), wz);
                }
                arena.moveEntity(currentEnemy, tpa.target());
                handleEnemyVoidRiftEntry(currentEnemy, tpa.target());
                pendingAction = new EnemyAction.Attack(tpa.damage());
                startAttackAnimation(CrafticsMod.CONFIG.enemyTurnDelay());
            }
            case EnemyAction.Pounce pounce -> {
                sendMessage("§6" + currentEnemy.getDisplayName() + " pounces!");
                // Footprint-vs-player safety net: a sized mob must not pounce onto a
                // landing whose footprint covers the player tile (clipping into it).
                // If the planned landing would overlap the player, stay put and just
                // attack from here instead of teleporting on top of them.
                boolean landingClipsPlayer = currentEnemy.isMultiTile()
                    && CombatEntity.minDistanceFromSizedEntity(
                        pounce.landingPos(), currentEnemy.getSizeX(), currentEnemy.getSizeZ(),
                        arena.getPlayerGridPos()) == 0;
                if (!landingClipsPlayer) {
                    MobEntity mob = currentEnemy.getMobEntity();
                    if (mob != null) {
                        double wx = arena.getOrigin().getX() + pounce.landingPos().x() + currentEnemy.getSizeX() / 2.0;
                        double wz = arena.getOrigin().getZ() + pounce.landingPos().z() + currentEnemy.getSizeZ() / 2.0;
                        mob.requestTeleport(wx,
                            arena.getEntityY(pounce.landingPos(), currentEnemy.isFlying()), wz);
                    }
                    arena.moveEntity(currentEnemy, pounce.landingPos());
                    handleEnemyVoidRiftEntry(currentEnemy, pounce.landingPos());
                }
                pendingAction = new EnemyAction.Attack(pounce.damage());
                startAttackAnimation(2);
            }
            case EnemyAction.MimicDash dash -> {
                sendMessage("§6§l" + currentEnemy.getDisplayName() + " DASHES!");
                ServerWorld dashWorld = (ServerWorld) player.getEntityWorld();
                GridPos start = currentEnemy.getGridPos();
                GridPos current = start;
                int steps = 0;
                int maxSteps = Math.max(arena.getWidth(), arena.getHeight()) + 1;
                // Walk tile by tile in the dash direction. Stop only when the next
                // tile is out of bounds or an obstacle. Players/allies in the way
                // get shoved sideways and damaged.
                while (steps < maxSteps) {
                    GridPos next = new GridPos(current.x() + dash.dirX(), current.z() + dash.dirZ());
                    if (!arena.isInBounds(next)) break;
                    GridTile nextTile = arena.getTile(next);
                    if (nextTile == null) break;
                    if (nextTile.getType() == com.crackedgames.craftics.core.TileType.OBSTACLE) break;

                    // Check what's on the next tile and shove it aside.
                    if (next.equals(arena.getPlayerGridPos())) {
                        shovePlayerAside(next, dash.dirX(), dash.dirZ(), dash.damage(), currentEnemy);
                        if (getPlayerHp() <= 0) { handlePlayerDeathOrGameOver(); return; }
                    } else {
                        CombatEntity occupant = arena.getOccupant(next);
                        if (occupant != null && occupant != currentEnemy) {
                            shoveEntityAside(occupant, next, dash.dirX(), dash.dirZ(), dash.damage());
                        }
                    }

                    arena.moveEntity(currentEnemy, next);
                    current = next;
                    steps++;

                    // Particle trail along the dash path
                    BlockPos trailBlock = arena.gridToBlockPos(next);
                    dashWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                        trailBlock.getX() + 0.5, trailBlock.getY() + 0.5, trailBlock.getZ() + 0.5,
                        6, 0.3, 0.2, 0.3, 0.05);
                    dashWorld.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                        trailBlock.getX() + 0.5, trailBlock.getY() + 0.3, trailBlock.getZ() + 0.5,
                        3, 0.2, 0.1, 0.2, 0.02);
                }

                // Move the actual MobEntity to the final tile so the visual catches up
                MobEntity dashMob = currentEnemy.getMobEntity();
                if (dashMob != null) {
                    double wx = arena.getOrigin().getX() + current.x() + 0.5;
                    double wz = arena.getOrigin().getZ() + current.z() + 0.5;
                    dashMob.requestTeleport(wx,
                        arena.getEntityY(current, currentEnemy.isFlying()), wz);
                }

                BlockPos endBlock = arena.gridToBlockPos(current);
                dashWorld.playSound(null, endBlock,
                    net.minecraft.sound.SoundEvents.ENTITY_RAVAGER_HURT,
                    net.minecraft.sound.SoundCategory.HOSTILE, 1.2f, 1.4f);

                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.MimicTantrum tantrum -> {
                // Queue the hop sequence and transition to TANTRUM_HOPPING so each
                // bounce plays out over its own tick. Previously this ran the whole
                // path in a single tick and teleported the visible mob only once at
                // the end -the player saw only the final landing spot.
                sendMessage("§6§l" + currentEnemy.getDisplayName() + " throws a TANTRUM!");
                tantrumPath = new java.util.ArrayList<>(tantrum.path());
                tantrumIndex = 0;
                tantrumDamage = tantrum.damage();
                tantrumLandingTile = currentEnemy.getGridPos();
                tantrumHitPlayer = false;
                enemyTurnState = EnemyTurnState.TANTRUM_HOPPING;
                enemyTurnDelay = 6; // brief wind-up before the first hop
            }
            case EnemyAction.Explode explode -> {
                sendMessage("§c§l" + currentEnemy.getDisplayName() + " EXPLODES!");
                ServerWorld explodeWorld = (ServerWorld) player.getEntityWorld();
                BlockPos explodeBlock = arena.gridToBlockPos(currentEnemy.getGridPos());
                explodeWorld.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION,
                    explodeBlock.getX() + 0.5, explodeBlock.getY() + 1.0, explodeBlock.getZ() + 0.5,
                    3, 1.0, 0.5, 1.0, 0.0);
                explodeWorld.spawnParticles(net.minecraft.particle.ParticleTypes.FLAME,
                    explodeBlock.getX() + 0.5, explodeBlock.getY() + 0.5, explodeBlock.getZ() + 0.5,
                    20, 1.5, 0.8, 1.5, 0.05);
                explodeWorld.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                    explodeBlock.getX() + 0.5, explodeBlock.getY() + 1.0, explodeBlock.getZ() + 0.5,
                    15, 1.0, 1.0, 1.0, 0.03);
                GridPos selfPos = currentEnemy.getGridPos();
                int kbTiles = currentEnemy.isEnraged() ? 3 : 2;
                // MP: hit EVERY party member inside the blast radius, not just
                // the host. Previous code measured to arena.getPlayerGridPos()
                // (the host's tile) so a creeper exploding next to player 2
                // with the host out of range dealt zero damage to anyone. Each
                // hit is routed via the this.player swap pattern so dodge /
                // armor / effects / death handling apply to the actual victim.
                java.util.List<ServerPlayerEntity> blastVictims = new java.util.ArrayList<>();
                if (partyPlayers.size() > 1) {
                    for (ServerPlayerEntity member : partyPlayers) {
                        if (member == null || member.isRemoved() || member.isDisconnected()) continue;
                        if (deadPartyMembers.contains(member.getUuid())) continue;
                        GridPos mPos = gridPosOf(member);
                        if (selfPos.manhattanDistance(mPos) <= explode.radius()) {
                            blastVictims.add(member);
                        }
                    }
                } else if (selfPos.manhattanDistance(arena.getPlayerGridPos()) <= explode.radius()) {
                    blastVictims.add(player);
                }
                boolean gameOverFromBlast = false;
                for (ServerPlayerEntity victim : blastVictims) {
                    ServerPlayerEntity savedExpPlayer = this.player;
                    boolean expSwapped = victim != savedExpPlayer;
                    if (expSwapped) {
                        this.player = victim;
                        retargetEffectsToCurrentPlayer();
                    }
                    boolean victimDied = false;
                    try {
                        int actual = damagePlayer(explode.damage(), currentEnemy, DamageType.BLUNT);
                        sendMessage("§c  Explosion hits "
                            + (expSwapped ? victim.getName().getString() : "you")
                            + " for " + actual + " damage! (HP: " + getPlayerHp() + ")");
                        if (getPlayerHp() <= 0) {
                            victimDied = true;
                            handlePlayerDeathOrGameOver();
                            gameOverFromBlast = (partyPlayers.size() <= 1 || !active);
                            continue;
                        }
                        applyPlayerKnockback(selfPos, kbTiles, currentEnemy);
                        if (getPlayerHp() <= 0) {
                            victimDied = true;
                            handlePlayerDeathOrGameOver();
                            gameOverFromBlast = (partyPlayers.size() <= 1 || !active);
                            continue;
                        }
                        // Variant creepers can attach status effects to their blast
                        // (e.g. cave_creeper → BLINDNESS, snowy_creeper → SLOWNESS).
                        if (explode.blastEffects() != null && !explode.blastEffects().isEmpty()) {
                            for (var be : explode.blastEffects()) {
                                if (be == null || be.effect() == null || be.turns() <= 0) continue;
                                addEffectHooked(be.effect(), be.turns(), be.amplifier());
                            }
                        }
                    } finally {
                        if (!victimDied) {
                            this.player = savedExpPlayer;
                            retargetEffectsToCurrentPlayer();
                        }
                    }
                }
                if (gameOverFromBlast) return;
                List<CombatEntity> blastTargets = new ArrayList<>();
                for (CombatEntity other : enemies) {
                    if (other == currentEnemy || !other.isAlive()) continue;
                    if (selfPos.manhattanDistance(other.getGridPos()) <= explode.radius()) {
                        blastTargets.add(other);
                    }
                }
                for (CombatEntity target : blastTargets) {
                    int dealt = target.takeDamage(explode.damage());
                    sendMessage("§6  Blast hits " + target.getDisplayName() + " for " + dealt + "!");
                    if (target.isAlive()) {
                        int edx = Integer.signum(target.getGridPos().x() - selfPos.x());
                        int edz = Integer.signum(target.getGridPos().z() - selfPos.z());
                        if (edx == 0 && edz == 0) edx = 1;
                        knockEnemyBack(target, edx, edz, kbTiles);
                    }
                    checkAndHandleDeath(target);
                }
                // Self-exploded = no drops
                currentEnemy.setSelfExploded(true);
                currentEnemy.takeDamage(9999);
                killEnemy(currentEnemy);
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = 8;
            }
            case EnemyAction.RangedAttack ra -> {
                startAttackAnimation(CrafticsMod.CONFIG.enemyTurnDelay());
            }
            case EnemyAction.Swoop swoop -> {
                // Lerped swoop -dragon/phantom physically flies along path tile-by-tile
                // via startEnemyMove. Damage is applied up-front to anyone in the path
                // (size-aware so the dragon's 3x3 footprint crushes the player) and the
                // per-tile trail particles are spawned by tickEnemyMoving while lerping.
                sendMessage("§5§l⌇ " + currentEnemy.getDisplayName() + " swoops!");
                ServerWorld swoopWorld = (ServerWorld) player.getEntityWorld();

                // Truncate the swoop path at the first obstacle that appeared
                // after the boss planned its charge (player placed a barrier
                // on the line). FIRE is walkable for swoops by design.
                // Copied, not aliased: the trim below mutates this list, and the action's own
                // path belongs to the AI that planned it.
                List<GridPos> swoopPath = new ArrayList<>(swoop.path());
                int swoopBlockedAt = -1;
                for (int i = 0; i < swoopPath.size(); i++) {
                    var stile = arena.getTile(swoopPath.get(i));
                    if (stile != null && !stile.isWalkable()
                            && !stile.getType().isFlames()) {
                        swoopBlockedAt = i;
                        break;
                    }
                }
                if (swoopBlockedAt >= 0) {
                    swoopPath = new ArrayList<>(swoopPath.subList(0, swoopBlockedAt));
                }

                // Force the mob visible for the lerp -cinematic swoops from off-stage
                // bosses (like the Ender Dragon) rely on this so the lerp actually shows.
                MobEntity swoopMob = currentEnemy.getMobEntity();
                if (swoopMob != null) {
                    swoopMob.setInvisible(false);
                    swoopMob.setSilent(false);
                    // Snap to the first tile of the path so the lerp starts at the correct
                    // edge position for cross-arena swoops -prevents a diagonal snap from
                    // the dragon's previous tile.
                    //
                    // Skipped when that tile belongs to somebody. This snap is why a phantom
                    // kept ending its swoop inside the player: a phantom standing NEXT to its
                    // target builds a path whose first tile IS the target's tile, and this
                    // moved it there outright - before the flight, before any landing check.
                    // Every later guard then read the mob as already standing there and left
                    // it alone, because a mob's own square is the one place it is always
                    // allowed to be. The illegal position was created and then protected.
                    //
                    // Nothing is lost by skipping it. The snap only exists so a boss diving
                    // in from off-stage starts its lerp at the arena edge instead of sliding
                    // diagonally out of its old tile, and such a path begins nowhere near a
                    // player. A phantom simply starts its dive from where it actually is.
                    if (!swoopPath.isEmpty()) {
                        GridPos swoopStart = swoopPath.get(0);
                        if (!currentEnemy.getGridPos().equals(swoopStart)
                                && !tileTakenByOther(swoopStart)) {
                            BlockPos snapBlock = arena.gridToBlockPos(swoopStart);
                            swoopMob.requestTeleport(
                                snapBlock.getX() + currentEnemy.getSizeX() / 2.0,
                                arena.getEntityY(swoopStart),
                                snapBlock.getZ() + currentEnemy.getSizeZ() / 2.0);
                            arena.moveEntity(currentEnemy, swoopStart);
                        }
                    }
                }

                // Dragon roar on swoop start -adds presence to the invisible entity
                if (currentEnemy.getAiKey() != null && currentEnemy.getAiKey().contains("dragons_nest")
                        && currentEnemy.getMobEntity() != null) {
                    swoopWorld.playSound(null, currentEnemy.getMobEntity().getBlockPos(),
                        net.minecraft.sound.SoundEvents.ENTITY_ENDER_DRAGON_GROWL,
                        net.minecraft.sound.SoundCategory.HOSTILE, 2.0f, 0.85f);
                }

                // Damage the player if any path tile intersects their footprint
                GridPos playerGridPos = arena.getPlayerGridPos();
                boolean hitPlayer = false;
                for (GridPos pos : swoopPath) {
                    if (CombatEntity.minDistanceFromSizedEntity(
                            pos, currentEnemy.getSizeX(), currentEnemy.getSizeZ(), playerGridPos) <= 0) {
                        hitPlayer = true;
                        break;
                    }
                }
                if (hitPlayer) {
                    int actual = damagePlayer(swoop.damage());
                    sendMessage("§c  Swoops through you for " + actual + " damage! (HP: " + getPlayerHp() + ")");
                    swoopWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                        player.getX(), player.getY() + 1.0, player.getZ(), 10, 0.3, 0.5, 0.3, 0.03);
                    swoopWorld.spawnParticles(net.minecraft.particle.ParticleTypes.DAMAGE_INDICATOR,
                        player.getX(), player.getY() + 0.8, player.getZ(), 5, 0.2, 0.3, 0.2, 0.01);
                    sendSync();
                    if (getPlayerHp() <= 0) { handlePlayerDeathOrGameOver(); return; }
                }

                // Chain damage: non-active party members standing on the swoop path
                if (partyPlayers.size() > 1) {
                    net.minecraft.util.math.BlockPos swoopOrigin = arena.getOrigin();
                    for (ServerPlayerEntity member : partyPlayers) {
                        if (member == player) continue;
                        if (deadPartyMembers.contains(member.getUuid())) continue;
                        if (member.isRemoved() || member.isDisconnected()) continue;
                        net.minecraft.util.math.BlockPos mbp = member.getBlockPos();
                        GridPos memberGrid = new GridPos(
                            mbp.getX() - swoopOrigin.getX(), mbp.getZ() - swoopOrigin.getZ());
                        boolean memberHit = false;
                        for (GridPos pos : swoopPath) {
                            if (CombatEntity.minDistanceFromSizedEntity(pos,
                                    currentEnemy.getSizeX(), currentEnemy.getSizeZ(), memberGrid) <= 0) {
                                memberHit = true;
                                break;
                            }
                        }
                        if (memberHit) {
                            // Party member's AC dodge roll. Member-specific
                            // combat effects / trims aren't tracked here, so
                            // pass their armor + Defense stat only.
                            int memberAc = PlayerCombatStats.getArmorClass(member, null, null,
                                PlayerProgression.get((ServerWorld) member.getEntityWorld())
                                    .getStats(member).getPoints(PlayerProgression.Stat.DEFENSE) * PROG_DEFENSE_PER_POINT, 0);
                            if (DodgeRoll.roll(memberAc, swoop.damage(), combatRng).dodged()) {
                                sendMessage("§b  " + member.getName().getString() + " deflected the swoop!");
                            } else {
                                int actual = Math.max(1, swoop.damage());
                                member.setHealth(Math.max(1, member.getHealth() - actual));
                                sendMessage("§c  Chains through " + member.getName().getString()
                                    + " for " + actual + " damage!");
                                swoopWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                                    member.getX(), member.getY() + 1.0, member.getZ(),
                                    10, 0.3, 0.5, 0.3, 0.03);
                                if ((int) member.getHealth() <= 1) {
                                    ServerPlayerEntity savedPlayer = this.player;
                                    this.player = member;
                                    retargetEffectsToCurrentPlayer();
                                    handlePlayerDeathOrGameOver();
                                    this.player = savedPlayer;
                                    retargetEffectsToCurrentPlayer();
                                }
                            }
                        }
                    }
                    sendSync();
                }

                // Damage is worked out from the FULL path above; where the mob comes to rest
                // is settled by startEnemyMove, which refuses to end a move on an occupied
                // tile whatever the action was.

                // Start the actual per-tile lerp through the swoop path.
                // tickEnemyMoving handles the visual interpolation and spawns trail
                // particles when pendingAction is a Swoop (see tickEnemyMoving hook).
                if (swoopPath.isEmpty()) {
                    enemyTurnState = EnemyTurnState.DONE;
                    enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                } else {
                    startEnemyMove(swoopPath);
                }
            }
            case EnemyAction.StartFuse fuse -> {
                sendMessage("§e" + currentEnemy.getDisplayName() + " is hissing... §c§lRUN!");
                // Creeper glows white while priming
                if (currentEnemy.getMobEntity() != null) {
                    currentEnemy.getMobEntity().setGlowing(true);
                }
                // Smoke particles around the creeper
                ServerWorld fuseWorld = (ServerWorld) player.getEntityWorld();
                BlockPos fuseBlock = arena.gridToBlockPos(currentEnemy.getGridPos());
                fuseWorld.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                    fuseBlock.getX() + 0.5, fuseBlock.getY() + 1.0, fuseBlock.getZ() + 0.5,
                    10, 0.3, 0.5, 0.3, 0.02);
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.AttackMob am -> {
                // Mob attacks another mob (predator hunting prey)
                CombatEntity target = findEnemyById(am.targetEntityId());
                if (target != null && target.isAlive()) {
                    // Falls through to the shared turn-advance tail below rather than
                    // returning, so a miss ends the turn exactly the way a hit does.
                    if (!attackMisses(currentEnemy, target)) {
                        int typed = applyTypeEffectiveness(am.damage(), currentEnemy, target);
                        int dealt = target.takeDamage(typed);
                        sendMessage("§6" + currentEnemy.getDisplayName() + " attacks " + target.getDisplayName() + " for " + dealt + "!");
                        checkAndHandleDeath(target);
                    }
                } else {
                    sendMessage("§7" + currentEnemy.getDisplayName() + " looks around...");
                }
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.MoveAndAttackMob maam -> startEnemyMove(maam.path());
            case EnemyAction.AttackWithKnockback akb -> {
                startAttackAnimation(CrafticsMod.CONFIG.enemyTurnDelay());
            }
            case EnemyAction.MoveAndAttackWithKnockback maakb -> startEnemyMove(maakb.path());
            case EnemyAction.Idle idle -> {
                // Render the pending telegraph first -this is the red-cell /
                // gathering-particle display the player reads to dodge. It MUST
                // happen before any short-circuit so late-game bosses still show
                // their warnings.
                EnemyAI bossAiForWarning = null;
                com.crackedgames.craftics.combat.ai.boss.BossAI pendingWarningBoss = null;
                if (currentEnemy.isBoss()) {
                    bossAiForWarning = resolveAi(currentEnemy);
                    if (bossAiForWarning instanceof com.crackedgames.craftics.combat.ai.boss.BossAI ba
                            && ba.getPendingWarning() != null) {
                        pendingWarningBoss = ba;
                        renderBossWarning(ba.getPendingWarning());
                    }
                    triggerGhastScream(currentEnemy, true);
                }

                // Late-game bosses (4th biome / ordinal >= 3) don't waste their
                // telegraph turn just idling: they also pick a movement/attack
                // action via BossAI.getChargingAdvanceAction() and dispatch it
                // this turn. The pendingWarning stays alive and resolves next
                // turn like normal. Bosses that want to stay put while charging
                // (e.g. DragonAI off-map) override getChargingAdvanceAction to
                // return Idle.
                if (currentEnemy.isBoss() && currentBiomeOrdinal >= 3
                        && pendingWarningBoss != null) {
                    EnemyAction chargeAction = pendingWarningBoss.getChargingAdvanceAction(
                        currentEnemy, arena, arena.getPlayerGridPos());
                    if (chargeAction != null && !(chargeAction instanceof EnemyAction.Idle)) {
                        sendMessage("§e" + currentEnemy.getDisplayName() + " advances while charging...");
                        pendingAction = chargeAction;
                        // Re-enter the main dispatcher with the advance action.
                        // Only common movement/attack cases are handled here; anything
                        // else falls through to the idle wait below.
                        if (chargeAction instanceof EnemyAction.Move mv) {
                            startEnemyMove(mv.path());
                            break;
                        } else if (chargeAction instanceof EnemyAction.MoveAndAttack maa) {
                            startEnemyMove(maa.path());
                            break;
                        } else if (chargeAction instanceof EnemyAction.Attack) {
                            startAttackAnimation(CrafticsMod.CONFIG.enemyTurnDelay());
                            break;
                        }
                        // Otherwise fall through to idle wait.
                    }
                }

                // Inert objects (graves, war banners, egg sacs) idle every single turn by design, so
                // announcing it would bury the real combat log. They still TAKE the turn: the
                // rotation is where per-entity bookkeeping happens, so skipping is not equivalent.
                if (!currentEnemy.isInertObject()) {
                    sendMessage("§7" + currentEnemy.getDisplayName() + " waits...");
                }
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }

            // === Spider ceiling mechanic ===

            case EnemyAction.CeilingAscend ascend -> {
                sendMessage("§7" + currentEnemy.getDisplayName() + " shoots a web and ascends to the ceiling!");
                // Hide the mob entity (move it way up so it's invisible)
                MobEntity ascendMob = currentEnemy.getMobEntity();
                if (ascendMob != null) {
                    ascendMob.requestTeleport(ascendMob.getX(), ascendMob.getY() + 100, ascendMob.getZ());
                    ascendMob.setInvisible(true);
                }
                // Remove from grid so it doesn't block tiles, but keep in enemies list
                arena.removeEntity(currentEnemy);
                // Mark as "on ceiling" via a tag the AI can check
                currentEnemy.setOnCeiling(true);
                // Movement-only turn -announce the actor (no camera focus, it left the grid).
                sendToAllParty(new CombatEventPayload(
                    CombatEventPayload.EVENT_MOVED, currentEnemy.getEntityId(), 0, 0, -1, -1));
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }

            case EnemyAction.CeilingDrop drop -> {
                sendMessage("§c" + currentEnemy.getDisplayName() + " drops from the ceiling!");
                // Place the mob back on the grid at the landing position
                currentEnemy.setOnCeiling(false);
                currentEnemy.setGridPos(drop.landingPos());
                arena.placeEntity(currentEnemy);
                // Show the mob entity again at the landing position
                MobEntity dropMob = currentEnemy.getMobEntity();
                if (dropMob != null) {
                    dropMob.setInvisible(false);
                    BlockPos dropBlock = arena.gridToBlockPos(drop.landingPos());
                    dropMob.requestTeleport(dropBlock.getX() + 0.5,
                        arena.getEntityY(drop.landingPos()),
                        dropBlock.getZ() + 0.5);
                }
                // Landing only -no attack this turn (drop is the action)
                sendToAllParty(new CombatEventPayload(
                    CombatEventPayload.EVENT_MOVED, currentEnemy.getEntityId(), 0, 0,
                    drop.landingPos().x(), drop.landingPos().z()));
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }

            // === Revenant burrow ===

            case EnemyAction.Burrow ignored -> {
                sendMessage("§8§l✦ " + currentEnemy.getDisplayName()
                    + " digs into the earth! §7You cannot reach it.");
                burrowEnemy(currentEnemy);
                // Movement-only turn -announce the actor (no camera focus, it left the grid).
                sendToAllParty(new CombatEventPayload(
                    CombatEventPayload.EVENT_MOVED, currentEnemy.getEntityId(), 0, 0, -1, -1));
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }

            case EnemyAction.Surface surface -> {
                surfaceEnemy(currentEnemy, surface.anchor(),
                    "§c§l✦ " + currentEnemy.getDisplayName() + " erupts from the grave!");
                GridPos surfacedAt = currentEnemy.getGridPos();
                sendToAllParty(new CombatEventPayload(
                    CombatEventPayload.EVENT_MOVED, currentEnemy.getEntityId(), 0, 0,
                    surfacedAt.x(), surfacedAt.z()));
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }

            // === Boss action types ===

            case EnemyAction.SummonMinions sm -> {
                sendMessage("§5" + currentEnemy.getDisplayName() + " summons reinforcements!");
                spawnBossMinions(sm);
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay() + 4;
            }
            case EnemyAction.AreaAttack aa -> {
                // A tag can carry a payload after a colon ("conduction:<markId>");
                // only the ability name before it is meant for humans.
                String abilityName = aa.effectName() != null ? aa.effectName() : "a powerful attack";
                int payloadStart = abilityName.indexOf(':');
                if (payloadStart > 0) abilityName = abilityName.substring(0, payloadStart);
                sendMessage("§c" + currentEnemy.getDisplayName() + " unleashes " +
                    abilityName.replace('_', ' ') + "!");
                resolveAreaAttack(aa);
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.TileAreaAttack ta -> {
                String abilityName = ta.effectName() != null ? ta.effectName() : "a powerful attack";
                int payloadStart = abilityName.indexOf(':');
                if (payloadStart > 0) abilityName = abilityName.substring(0, payloadStart);
                sendMessage("§c" + currentEnemy.getDisplayName() + " unleashes "
                    + abilityName.replace('_', ' ') + "!");
                resolveTileAreaAttack(ta);
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.RaisePillars rp -> {
                resolveRaisePillars(rp);
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.CreateTerrain ct -> {
                resolveCreateTerrain(ct);
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.IgniteTiles ignite -> {
                resolveIgniteTiles(ignite);
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.LineAttack la -> {
                sendMessage("§c" + currentEnemy.getDisplayName() + " attacks in a line!");
                resolveLineAttack(la);
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.ModifySelf ms -> {
                resolveModifySelf(currentEnemy, ms);
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.ForcedMovement fm -> {
                resolveForcedMovement(fm);
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.BreakStealthTile bst -> {
                sendMessage("§7" + currentEnemy.getDisplayName() + " thrashes the undergrowth!");
                breakStealthTileAt(bst.tile());
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.PlaceWeb pw -> {
                // Infinite-pool web_spray/entangle return this directly (campaign
                // bosses only ever emit it as a BossAbility sub-action) - without
                // this case it fell to the default and silently did nothing.
                sendMessage("§c" + currentEnemy.getDisplayName() + " sprays webbing!");
                resolvePlaceWeb(pw);
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.BossAbility ba -> {
                // A special attack that marks tiles ALWAYS shows those tiles first, in every
                // biome, for every boss. The warning turn is the counterplay: it is the only
                // thing that separates a boss ability from unavoidable damage, and an attack
                // you cannot see coming is not harder, it is just a die roll.
                //
                // This used to be dropped from the fourth biome onward (ordinal >= 3), and
                // that rule was carved back four separate times - Void Walker's rifts, then
                // infinite bosses, then raid bosses, then the Warden's fissure - each time
                // because the un-telegraphed version turned out to be indefensible. It has
                // no defenders left, so it is gone.
                //
                // Late-game pressure still escalates, just not by hiding information: the
                // charging-advance path above lets a deep-biome boss move or strike during
                // its telegraph turn instead of standing still, and infinite/raid bosses add
                // actions per turn on top of that.
                if (ba.warningTiles() != null && !ba.warningTiles().isEmpty()) {
                    sendMessage("§e" + currentEnemy.getDisplayName() + " prepares " +
                        ba.abilityName().replace('_', ' ') + "! §7("
                        + com.crackedgames.craftics.vfx.boss.BossAttackVfx.hintFor(ba.abilityName())
                        + ")");
                    // Store pending warning for resolution next turn
                    pendingBossWarnings.add(new PendingBossWarning(currentEnemy, ba));
                    // Paint it NOW - the telegraph fires mid-enemy-phase, where
                    // refreshHighlights() is turn-gated and would drop it.
                    syncWarningTiles();
                    // The boss visibly channels while the telegraph charges -
                    // arms raised, head up, converging enchant particles.
                    if (currentEnemy.getMobEntity() != null) {
                        com.crackedgames.craftics.combat.animation.MobAnimations.set(
                            currentEnemy.getMobEntity(),
                            com.crackedgames.craftics.combat.animation.AnimState.CAST);
                    }
                    // Render warning particles on the telegraphed tiles
                    spawnBossAbilityTelegraphParticles(ba);
                    // Dread pass: resonant toll, boss aura flare, and particles
                    // converging on the doomed tiles in pulses across the turn.
                    com.crackedgames.craftics.vfx.boss.BossAttackVfx.telegraph(
                        (ServerWorld) player.getEntityWorld(), arena, currentEnemy, ba);
                    // Paint the red tile overlay on each warning tile so the player can
                    // actually see where the attack will land.
                    for (GridPos tile : ba.warningTiles()) {
                        highlightWarningTile(tile);
                    }
                    // Clear BossAI's internal warning to prevent double-fire
                    EnemyAI bossAi = resolveAi(currentEnemy);
                    if (bossAi instanceof com.crackedgames.craftics.combat.ai.boss.BossAI bai) {
                        bai.clearPendingWarning();
                    }
                } else {
                    // No warning tiles to show: an ability that targets nothing on the grid
                    // (a self-buff, a summon, an arena-wide state change) resolves the turn
                    // it is used. Anything that DOES mark tiles took the branch above.
                    sendMessage("§c" + currentEnemy.getDisplayName() + " uses " +
                        ba.abilityName().replace('_', ' ') + "!");
                    // Even without a telegraph the hit must LAND: themed,
                    // category-shaped impact instead of an unheralded damage tick.
                    com.crackedgames.craftics.vfx.boss.BossAttackVfx.impact(
                        (ServerWorld) player.getEntityWorld(), arena, currentEnemy, ba,
                        findAnyPlayerInside(ba.warningTiles()));
                    dispatchBossSubAction(ba.resolvedAction());
                }
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            }
            case EnemyAction.CompositeAction ca -> {
                // Move/Pounce sub-actions drive the turn state machine themselves
                // (movement lerp / attack animation), so they're dispatched through
                // the main handlers and the DONE override below is skipped.
                // dispatchBossSubAction ignores them -which used to mean a magma
                // cube's fire-trail bounce burned the floor while the cube itself
                // silently never moved.
                boolean tookOverTurn = false;
                for (EnemyAction subAction : ca.actions()) {
                    // Only ONE movement-driven sub-action may own the turn state
                    // machine; a second would reset enemyMovePath mid-flight and
                    // silently discard the first. No current AI builds such a
                    // composite -this guards the day one does.
                    boolean isMovementSub = subAction instanceof EnemyAction.Move
                        || subAction instanceof EnemyAction.MoveAndAttack
                        || subAction instanceof EnemyAction.Pounce;
                    if (tookOverTurn && isMovementSub) {
                        CrafticsMod.LOGGER.warn(
                            "CompositeAction with multiple movement sub-actions -dropping extra {}",
                            subAction.getClass().getSimpleName());
                        continue;
                    }
                    if (subAction instanceof EnemyAction.Move mv) {
                        if (!mv.path().isEmpty()) {
                            pendingAction = mv;
                            startEnemyMove(mv.path());
                            tookOverTurn = true;
                        }
                    } else if (subAction instanceof EnemyAction.MoveAndAttack maa) {
                        if (!maa.path().isEmpty()) {
                            // pendingAction must be the sub-action so the arrival
                            // attack fires when the movement lerp completes.
                            pendingAction = maa;
                            startEnemyMove(maa.path());
                            tookOverTurn = true;
                        } else {
                            dispatchBossSubAction(new EnemyAction.Attack(maa.damage()));
                        }
                    } else if (subAction instanceof EnemyAction.Pounce pounce) {
                        boolean clipsPlayer = currentEnemy.isMultiTile()
                            && CombatEntity.minDistanceFromSizedEntity(
                                pounce.landingPos(), currentEnemy.getSizeX(), currentEnemy.getSizeZ(),
                                arena.getPlayerGridPos()) == 0;
                        if (!clipsPlayer) {
                            MobEntity pMob = currentEnemy.getMobEntity();
                            if (pMob != null) {
                                double wx = arena.getOrigin().getX() + pounce.landingPos().x() + currentEnemy.getSizeX() / 2.0;
                                double wz = arena.getOrigin().getZ() + pounce.landingPos().z() + currentEnemy.getSizeZ() / 2.0;
                                pMob.requestTeleport(wx,
                                    arena.getEntityY(pounce.landingPos(), currentEnemy.isFlying()), wz);
                            }
                            arena.moveEntity(currentEnemy, pounce.landingPos());
                            handleEnemyVoidRiftEntry(currentEnemy, pounce.landingPos());
                        }
                        pendingAction = new EnemyAction.Attack(pounce.damage());
                        startAttackAnimation(2);
                        tookOverTurn = true;
                    } else {
                        dispatchBossSubAction(subAction);
                    }
                }
                sendSync();
                if (!tookOverTurn) {
                    enemyTurnState = EnemyTurnState.DONE;
                    enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay() + 2;
                }
            }

            // === Projectile action types ===

            case EnemyAction.SpawnProjectile sp -> {
                sendMessage("§5" + currentEnemy.getDisplayName() + " launches projectiles!");
                spawnProjectiles(sp);
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay() + 4;
            }
            case EnemyAction.ProjectileMove pmRaw -> {
                // ProjectileAI collision-tests only the single AI-target tile (the
                // closest member), so in co-op its flight path can pass straight
                // through everyone else. Clip at the first member on the path.
                EnemyAction.ProjectileMove pm = clipProjectileAtAnyMember(pmRaw);
                if (pm != pmRaw) pendingAction = pm;
                if (pm.path().isEmpty()) {
                    if (pm.impacts()) {
                        resolveProjectileImpact(currentEnemy, pm.impactPos());
                    }
                    enemyTurnState = EnemyTurnState.DONE;
                    enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                } else {
                    startEnemyMove(pm.path());
                }
            }

            case EnemyAction.CustomAction ca -> {
                // Addon-defined action: hand resolution straight back to whoever
                // registered the id. See CustomActionHandler for why this is one member of
                // the sealed set rather than an unsealed interface.
                //
                // Resolved synchronously and the turn ends immediately after, the same as
                // Attack. A handler that wants a wind-up wraps itself in a BossAbility
                // instead, which gets the warning tiles and the telegraph for free and
                // arrives here a turn later.
                resolveCustomAction(ca, currentEnemy);
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = Math.max(1, CrafticsMod.CONFIG.enemyTurnDelay());
            }

            default -> {
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = Math.max(1, CrafticsMod.CONFIG.enemyTurnDelay() / 2);
            }
        }
    }


    /**
     * Run an addon-registered custom action, giving its handler a context wired into the
     * real combat pipeline rather than a set of raw fields.
     *
     * <p>The context routes damage through {@code damageEnemy}-equivalent handling and
     * movement through the same grid rules built-in knockback uses, so an addon action
     * cannot accidentally skip resistances, attack typings, shields, death processing or
     * the pit-fall check. That is the whole point of handing over a context instead of the
     * arena: an addon that pokes HP directly would silently bypass half the combat rules,
     * and the bug would look like a balance problem rather than a missing call.
     */
    private void resolveCustomAction(EnemyAction.CustomAction ca, CombatEntity actorIn) {
        final CombatEntity actor = actorIn;
        if (actor == null) return;
        final GridArena arenaRef = arena;
        final ServerWorld worldRef = (player != null && player.getEntityWorld() instanceof ServerWorld sw)
            ? sw : null;
        if (arenaRef == null || worldRef == null) return;

        com.crackedgames.craftics.api.CustomActionHandler.Context ctx =
            new com.crackedgames.craftics.api.CustomActionHandler.Context() {
                @Override public CombatEntity self() { return actor; }
                @Override public GridArena arena() { return arenaRef; }
                @Override public ServerWorld world() { return worldRef; }
                @Override public GridPos playerPos() { return arenaRef.getPlayerGridPos(); }
                @Override public java.util.List<GridPos> tiles() {
                    return ca.tiles() == null ? java.util.List.of() : ca.tiles();
                }
                @Override public net.minecraft.nbt.NbtCompound params() {
                    return ca.params() == null ? new net.minecraft.nbt.NbtCompound() : ca.params();
                }
                @Override public int damage() { return ca.damage(); }

                @Override public void damage(CombatEntity target, int amount) {
                    if (target == null || amount <= 0) return;
                    // Routing follows the ACTOR's side. An ally using the same move as an
                    // enemy must hit enemies with it, and the old form assumed the actor was
                    // always an enemy - so anything an ally targeted that was not itself read
                    // as "the player" and the move hit its own owner.
                    if (actor.isAlly()) {
                        // An ally's action hits creatures on the field - enemies it is aimed
                        // at, and itself or its own side for recoil and moves that cost the
                        // user. It never falls through to the player: an ally with no valid
                        // creature target does nothing rather than turning on its own owner.
                        hurtCombatant(target, amount, actor);
                        return;
                    }
                    if (target.isAlly() || target.getEntityId() == actor.getEntityId()) {
                        // Enemy-on-ally and enemy-on-self both already have a path that
                        // handles death, ownership and the ally roster.
                        hurtCombatant(target, amount, actor);
                        return;
                    }
                    // Anything else an ENEMY action can hit is the player. An ally never
                    // reaches here; it must say damagePlayer() to mean the player.
                    CombatManager.this.damagePlayer(amount, actor);
                }

                @Override public boolean moveSelfTo(GridPos dest) {
                    if (dest == null || !arenaRef.isInBounds(dest)) return false;
                    if (arenaRef.isOccupied(dest)) return false;
                    com.crackedgames.craftics.core.GridTile t = arenaRef.getTile(dest);
                    if (t == null) return false;
                    boolean voidDest = t.getType() == TileType.VOID && !actor.isHazardImmune();
                    if (!voidDest && !t.isWalkable()) return false;
                    if (!arenaRef.moveEntity(actor, dest)) return false;
                    if (actor.getMobEntity() != null) {
                        BlockPos bp = arenaRef.gridToBlockPos(dest);
                        actor.getMobEntity().requestTeleport(bp.getX() + 0.5,
                            arenaRef.getEntityY(dest, actor.isFlying()), bp.getZ() + 0.5);
                    }
                    if (voidDest) checkEnemyFallDeath(actor);
                    return true;
                }

                @Override public void heal(CombatEntity target, int amount) {
                    if (target == null || amount <= 0) return;
                    target.heal(amount);
                }

                @Override public void applyEffect(CombatEntity target,
                                                  CombatEffects.EffectType type,
                                                  int turns, int amplifier) {
                    // Shared with the item path, so confusion still rolls its chance and
                    // weakness still sets its own penalty timer.
                    applyEffectTo(target, type, turns, amplifier);
                }

                @Override public void applyCustomEffect(CombatEntity target, String effectId,
                                                        int turns, int amplifier) {
                    if (target == null) return;
                    if (com.crackedgames.craftics.api.registry.CombatEffectRegistry
                            .get(effectId) == null) {
                        CrafticsMod.LOGGER.warn(
                            "Custom action applyCustomEffect: no effect registered with id '{}'",
                            effectId);
                        return;
                    }
                    target.applyCustomEffect(effectId, turns, amplifier);
                }

                @Override public void damagePlayer(int amount) {
                    if (amount <= 0) return;
                    CombatManager.this.damagePlayer(amount, actor);
                }

                @Override public void message(String text) {
                    if (text != null && !text.isEmpty()) sendMessage(text);
                }
            };

        com.crackedgames.craftics.api.registry.CustomActionRegistry.resolve(ca.id(), ctx);
    }

    /**
     * Handle an ally's turn: resolve the ally's {@link com.crackedgames.craftics.combat.ai.ally.AllyAI}
     * from the {@code AllyRegistry}, ask it for an action, and execute that action -
     * applying owner-gear damage bonuses for gear-scaling allies.
     */
    private void handleAllyTurn(CombatEntity ally) {
        // A mounted ally is the player's vehicle, not a combatant -it has no
        // grid tile and moves with the player, so it never takes a turn.
        if (ally.isMounted()) {
            enemyTurnState = EnemyTurnState.DONE;
            enemyTurnDelay = Math.max(1, CrafticsMod.CONFIG.enemyTurnDelay() / 2);
            return;
        }
        // Use the archetype AI resolved when the ally was spawned; if it wasn't
        // resolved, fall back to the registry entry and finally the melee default.
        AllyEntry entry = AllyRegistry.getOrNull(ally.getEntityTypeId());
        AllyAI ai = ally.getAllyAi();
        if (ai == null) {
            ai = entry != null ? entry.ai() : AllyEntry.DEFAULT_AI;
        }
        // null (unregistered ally) defaults to true: the pre-framework handleAllyTurn
        // applied the owner-gear bonus to every ally, so this preserves that behavior.
        // A seeker is a spell's payload, not a pet, so Pet affinity must not scale it -
        // its damage is the sherd's own number.
        boolean scalesWithGear = !ally.isSeekerProjectile()
            && (entry == null || entry.scalesWithOwnerGear());

        // What a standing order carried, snapshotted before the reset below wipes it.
        // An addon sets the type and accuracy of a commanded move at the moment it issues
        // the order, and the order is obeyed a turn later - so clearing unconditionally here
        // meant a commanded move always arrived untyped and at default accuracy, and the
        // only way to give an ally a typed move was to route it through the ally AI.
        String orderedAttackType = ally.getPendingAttackType();
        double orderedAccuracy = ally.getPendingAccuracy();

        ally.setPendingAttackType(null);   // see the note at the enemy decision point
        ally.setPendingAccuracy(AccuracyRoll.NO_OVERRIDE);

        // A player-issued order wins over the ally's own judgement, and is consumed as it is
        // read so it is obeyed exactly once. Everything downstream is the ordinary ally path,
        // so a commanded attack goes through the same damage, typing and accuracy handling an
        // AI-chosen one does - the order decides WHAT, never how it resolves.
        EnemyAction commanded = ally.consumeCommandedAction();
        if (commanded != null) {
            // Hand the order back its own typing and accuracy. Only on the commanded path:
            // the AI sets its own as it decides, and needs the clean slate above.
            ally.setPendingAttackType(orderedAttackType);
            ally.setPendingAccuracy(orderedAccuracy);
        }

        // A blinded ally swings wide instead of losing its turn. Enemies fumble their whole
        // turn to blindness at a check allies never reach, which is why an enemy blinding a
        // player's pet has done precisely nothing since blindness was added - the debuff was
        // applied, displayed on the HUD, and then read by no ally code path at all.
        //
        // Halving accuracy rather than copying the fumble is the treatment that fits: a pet
        // that silently forfeits turns reads as the game being broken, while one that visibly
        // swings and misses reads as blinded. The countdown ticks here, on the ally's own
        // turn, because that is the only point an ally reliably passes once per round.

        if (ally.getBlindedTurns() > 0) {
            ally.setBlindedTurns(ally.getBlindedTurns() - 1);
            // Scaled, not assigned - see AccuracyRoll.blinded. A commanded move brings its
            // own accuracy, and overwriting it would make an inaccurate move land MORE often
            // while blinded.
            ally.setPendingAccuracy(AccuracyRoll.blinded(ally.getPendingAccuracy()));
        }

        EnemyAction action = commanded != null ? commanded : ai.decideAction(ally, arena, enemies);

        int doneDelay = Math.max(1, CrafticsMod.CONFIG.enemyTurnDelay() / 2);

        if (action instanceof EnemyAction.Flee flee) {
            sendMessage("§e" + ally.getDisplayName() + " retreats!");
            startEnemyMove(flee.path());
            return;
        }
        if (action instanceof EnemyAction.Move move) {
            sendMessage("§a" + ally.getDisplayName() + " advances!");
            startEnemyMove(move.path());
            return;
        }

        if (action instanceof EnemyAction.MoveAndAttackMob attack) {
            CombatEntity target = null;
            for (CombatEntity e : enemies) {
                if (e.getEntityId() == attack.targetEntityId()) { target = e; break; }
            }
            if (target == null || !target.isAlive()) {
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = doneDelay;
                return;
            }

            int totalDamage = attack.damage();
            int petBonus = 0;
            if (scalesWithGear) {
                // Apply the owner's armor-set / trim / mob-head bonuses to this ally's damage.
                ServerPlayerEntity allyOwner = resolveAllyOwner(ally.getOwnerUuid());
                PlayerProgression.PlayerStats allyOwnerStats = PlayerProgression.get(
                    (ServerWorld) allyOwner.getEntityWorld()).getStats(allyOwner);
                TrimEffects.TrimScan ownerTrimScan = activeTrimScan;
                if (ally.getOwnerUuid() != null && allyOwner != player) {
                    ownerTrimScan = TrimEffects.scan(allyOwner);
                }
                petBonus = DamageType.getTotalBonus(
                        allyOwner, ownerTrimScan, combatEffects,
                        DamageType.PET, allyOwnerStats)
                    + DamageType.getMobHeadBonus(
                        allyOwner.getEquippedStack(net.minecraft.entity.EquipmentSlot.HEAD), DamageType.PET);
                if (ownerTrimScan != null && ownerTrimScan.setBonus() == TrimEffects.SetBonus.RALLY) {
                    petBonus += 1;
                }
                totalDamage += petBonus;
            }
            // Type effectiveness for the ally's own attack, applied once here where the
            // figure is finalised rather than where it lands, because the hit resolves a
            // tick or more later via the queued action.
            totalDamage = applyTypeEffectiveness(totalDamage, ally, target);
            pendingAllyAttackTarget = target;
            pendingAction = new EnemyAction.MoveAndAttackMob(
                attack.path(), target.getEntityId(), totalDamage);
            // Walk the approach path first when there is one -tickEnemyMoving
            // chains into the attack, so the ally moves and strikes in one turn.
            if (attack.path().isEmpty()) {
                startAttackAnimation(CrafticsMod.CONFIG.enemyTurnDelay());
            } else {
                startEnemyMove(attack.path());
            }
            return;
        }

        if (action instanceof EnemyAction.CustomAction ca) {
            // The same handler the enemy path uses, with the ally as the actor - so an addon
            // move behaves identically whoever throws it. Without this an ally handed a
            // CustomAction fell through to Idle below and silently burned its turn, which
            // meant an addon's moves worked fully in enemy hands and landed as a single
            // plain hit in the player's.
            resolveCustomAction(ca, ally);
            enemyTurnState = EnemyTurnState.DONE;
            enemyTurnDelay = Math.max(1, CrafticsMod.CONFIG.enemyTurnDelay());
            return;
        }

        // EnemyAction.Idle (or anything else): the ally holds position / has no move.
        enemyTurnState = EnemyTurnState.DONE;
        enemyTurnDelay = doneDelay;
    }

    // ==================== Boss Action Resolution ====================

    /**
     * Resolve pending boss warnings at the start of a boss's turn.
     * Called before the boss chooses its new action.
     */
    /**
     * The grid position of ANY party member standing inside {@code tiles}, or
     * null when nobody is. Drives the "you are standing in the blast" screen
     * treatment - checking every member (not just the tracked player) so a
     * co-op teammate in the AoE triggers it too.
     */
    private GridPos findAnyPlayerInside(java.util.List<GridPos> tiles) {
        if (tiles == null || tiles.isEmpty() || arena == null) return null;
        for (GridPos p : arena.getAllPlayerGridPositions()) {
            if (p != null && tiles.contains(p)) return p;
        }
        GridPos tracked = arena.getPlayerGridPos();
        return tracked != null && tiles.contains(tracked) ? tracked : null;
    }

    private void resolvePendingBossWarnings(CombatEntity boss) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        boolean resolvedAny = false;
        var iterator = pendingBossWarnings.iterator();
        while (iterator.hasNext()) {
            PendingBossWarning pw = iterator.next();
            if (pw.boss() == boss && boss.isAlive()) {
                sendMessage("§c" + boss.getDisplayName() + "'s " +
                    pw.ability().abilityName().replace('_', ' ') + " resolves!");
                // The payoff: themed, category-shaped impact - slams ripple a
                // shockwave, lines sweep their tiles in order, magic converges
                // then bursts - instead of the old flat FLASH+CRIT sprinkle.
                java.util.List<GridPos> warnTiles = pw.ability().warningTiles();
                com.crackedgames.craftics.vfx.boss.BossAttackVfx.impact(
                    world, arena, boss, pw.ability(), findAnyPlayerInside(warnTiles));
                // Ghast scream on attack resolution
                triggerGhastScream(boss, true);
                // Void Walker: register a live rift pair once the telegraph finishes.
                if ("void_rift".equals(pw.ability().abilityName()) && warnTiles != null && warnTiles.size() >= 2) {
                    registerVoidRift(boss, warnTiles.get(0), warnTiles.get(1));
                }
                dispatchBossSubAction(pw.ability().resolvedAction());
                iterator.remove();
                resolvedAny = true;
            }
        }
        if (resolvedAny) {
            // Un-paint the resolved telegraph immediately; the next player-turn
            // refreshHighlights() is a whole enemy phase away.
            syncWarningTiles();
        }
    }

    // === Void Walker rifts ===============================================

    /**
     * Register a new rift pair after the Void Walker's void_rift telegraph resolves.
     * In Phase 1 rifts last 4 turns; in Phase 2 they are permanent (Reality Shatter).
     */
    private void registerVoidRift(CombatEntity boss, GridPos a, GridPos b) {
        if (a == null || b == null || a.equals(b)) return;
        if (!arena.isInBounds(a) || !arena.isInBounds(b)) return;

        boolean permanent = false;
        EnemyAI ai = resolveAi(boss);
        if (ai instanceof com.crackedgames.craftics.combat.ai.boss.BossAI bossAi) {
            // Phase 2 (<=50% HP): rifts are permanent until boss dies.
            if (boss.getMaxHp() > 0 && boss.getCurrentHp() * 2 <= boss.getMaxHp()) {
                permanent = true;
            }
        }
        int life = permanent ? -1 : 4;
        activeVoidRifts.add(new VoidRift(a, b, life));

        sendMessage("§5A void rift pair tears open! §7Step into one to teleport to the other"
            + (permanent ? " §8(permanent)" : " §8(" + life + " turns)") + ".");

        // Big placement burst on both endpoints so the player immediately sees them.
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        for (GridPos p : new GridPos[]{a, b}) {
            BlockPos bp = arena.gridToBlockPos(p);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL,
                bp.getX() + 0.5, bp.getY() + 0.2, bp.getZ() + 0.5, 40, 0.35, 0.1, 0.35, 0.6);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
                bp.getX() + 0.5, bp.getY() + 1.2, bp.getZ() + 0.5, 30, 0.3, 0.6, 0.3, 0.4);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD,
                bp.getX() + 0.5, bp.getY() + 1.6, bp.getZ() + 0.5, 12, 0.15, 0.2, 0.15, 0.05);
        }
        if (player != null) {
            player.getWorld().playSound(null, arena.gridToBlockPos(a),
                net.minecraft.sound.SoundEvents.BLOCK_PORTAL_TRIGGER,
                net.minecraft.sound.SoundCategory.HOSTILE, 0.6f, 1.4f);
        }
    }

    // === Sandstorm Pharaoh sand mines =====================================

    /** Register a persistent sand mine on the given tile when "plant_mine" resolves. */
    private void registerSandMine(GridPos pos) {
        if (pos == null || !arena.isInBounds(pos)) return;
        GridTile gt = arena.getTile(pos);
        if (gt == null || !gt.isWalkable()) return;
        // Don't stack two mines on the same tile.
        for (SandMine m : activeSandMines) {
            if (m.pos.equals(pos)) return;
        }
        activeSandMines.add(new SandMine(pos, SAND_MINE_LIFETIME));
        if (player != null) {
            ServerWorld world = (ServerWorld) player.getEntityWorld();
            BlockPos bp = arena.gridToBlockPos(pos);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.ASH,
                bp.getX() + 0.5, bp.getY() + 0.2, bp.getZ() + 0.5, 12, 0.25, 0.1, 0.25, 0.02);
            world.playSound(null, bp,
                net.minecraft.sound.SoundEvents.BLOCK_SAND_PLACE,
                net.minecraft.sound.SoundCategory.HOSTILE, 0.7f, 0.8f);
        }
        sendMessage("§6A sand mine settles into the ground! §7Watch your step §8("
            + SAND_MINE_LIFETIME + " turns)");
    }

    /** Per-tick subtle marker so an observant player can spot a buried mine. */
    private void tickSandMineParticles() {
        if (activeSandMines.isEmpty() || player == null) return;
        if (tickCounter % 4 != 0) return;
        ServerWorld sw = (ServerWorld) player.getEntityWorld();
        for (SandMine m : activeSandMines) {
            if (!arena.isInBounds(m.pos)) continue;
            BlockPos bp = arena.gridToBlockPos(m.pos);
            double cx = bp.getX() + 0.5, cy = bp.getY() + 0.05, cz = bp.getZ() + 0.5;
            sw.spawnParticles(net.minecraft.particle.ParticleTypes.ASH,
                cx, cy, cz, 2, 0.25, 0.05, 0.25, 0.0);
            sw.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                cx, cy + 0.15, cz, 1, 0.2, 0.05, 0.2, 0.0);
        }
    }

    /**
     * Detonate any armed sand mine on the tile the player just stepped onto: deals
     * {@link #SAND_MINE_DAMAGE} and a 1-turn stun, removes the mine, and notifies the
     * SandstormPharaoh AI so its active-mine count decrements. Returns true if a mine
     * detonated. Mirrors handleVoidRiftEntry's step-trigger model.
     */
    private boolean triggerSandMine(GridPos destination) {
        if (activeSandMines.isEmpty() || player == null || destination == null) return false;
        SandMine hit = null;
        for (SandMine m : activeSandMines) {
            if (m.armedThisTurn) continue; // freshly planted -not live yet
            if (m.pos.equals(destination)) { hit = m; break; }
        }
        if (hit == null) return false;
        activeSandMines.remove(hit);
        notifySandMineRemoved();

        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos bp = arena.gridToBlockPos(destination);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION,
            bp.getX() + 0.5, bp.getY() + 0.5, bp.getZ() + 0.5, 1, 0.0, 0.0, 0.0, 0.0);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.ASH,
            bp.getX() + 0.5, bp.getY() + 0.3, bp.getZ() + 0.5, 30, 0.5, 0.6, 0.5, 0.05);
        world.playSound(null, bp,
            net.minecraft.sound.SoundEvents.ENTITY_GENERIC_EXPLODE.value(),
            net.minecraft.sound.SoundCategory.HOSTILE, 0.8f, 1.3f);

        int dealt = damagePlayerFromTile(SAND_MINE_DAMAGE, null);
        sendMessage("§6A buried sand mine erupts beneath you for " + dealt
            + " damage! §7(HP: " + getPlayerHp() + ")");
        if (getPlayerHp() <= 0) {
            // Lethal -leave death resolution to the caller, exactly like the lava/fire
            // step-damage paths. Handling it here AND returning to the move-finish block
            // would clobber the dying phase and revive the player at 1 HP.
            return true;
        }
        // Brief stun (same MINING_FATIGUE amp-9 pattern as the web/burial stuns).
        addEffectHooked(CombatEffects.EffectType.MINING_FATIGUE, 1, 9);
        sendMessage("§7  The blast staggers you! §8(stunned 1 turn)");
        return true;
    }

    /**
     * Deeper-and-Darker geyser trap (Blooming Caverns): stepping onto a
     * {@link TileType#GEYSER} tile erupts - Burning II plus a launch of up to 3
     * tiles in a random cardinal direction. The launch reuses
     * {@link #resolveForcedMovement} so all the void-fall / teleport / particle
     * handling is shared. Called from the move-finish path scan in handleMove.
     */
    private void triggerGeyser(GridPos tile) {
        if (player == null || tile == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos bp = arena.gridToBlockPos(tile);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.LAVA,
            bp.getX() + 0.5, bp.getY() + 0.3, bp.getZ() + 0.5, 20, 0.3, 0.6, 0.3, 0.05);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.SCULK_SOUL,
            bp.getX() + 0.5, bp.getY() + 0.6, bp.getZ() + 0.5, 12, 0.2, 0.8, 0.2, 0.04);
        world.playSound(null, bp,
            net.minecraft.sound.SoundEvents.BLOCK_LAVA_POP,
            net.minecraft.sound.SoundCategory.HOSTILE, 0.9f, 0.7f);

        if (!combatEffects.hasFireResistance()) {
            addEffectHooked(CombatEffects.EffectType.BURNING, 2, 1); // Burning II
            sendMessage("§cA sculk geyser erupts beneath you! §6(Burning II)");
        } else {
            sendMessage("§cA sculk geyser erupts beneath you!");
        }

        // Random cardinal launch, up to 3 tiles. resolveForcedMovement stops at
        // walls/edges and applies void-fall damage if it flings you off a ledge.
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int[] dir = dirs[(int) (Math.random() * dirs.length)];
        resolveForcedMovement(new EnemyAction.ForcedMovement(-1, dir[0], dir[1], 3));
    }

    /** Damage a sculk jaw deals when it bites, before defense. */
    private static final int SCULK_JAW_DAMAGE = 6;
    /** XP levels a sculk jaw swallows per bite. It keeps them until it is destroyed. */
    private static final int SCULK_JAW_XP_STEAL = 1;
    /** Grid tile -> XP levels that jaw is currently holding, refunded when it's broken. */
    private final java.util.Map<GridPos, Integer> sculkJawHoard = new java.util.HashMap<>();

    /**
     * Deeper-and-Darker sculk jaw: a step-trap that bites for
     * {@value #SCULK_JAW_DAMAGE} and swallows {@value #SCULK_JAW_XP_STEAL} XP level.
     *
     * <p>The XP is not destroyed, it is <em>held</em> - the jaw hoards what it takes
     * and coughs the whole pile back up when the tile is destroyed (see
     * {@link #breakSculkJaw}). That is what makes it a puzzle rather than a pure tax:
     * XP is real currency here (enchanting and death both spend levels), so you can
     * eat the loss or spend a turn getting it back.
     *
     * <p>Sculk creatures are immune in the source mod, and they are here too, by
     * omission rather than by check: no enemy movement path reads this tile type, so
     * only players ever trigger it. Every enemy in an overhauled Deep Dark is sculk,
     * so that lines up exactly.
     */
    private void triggerSculkJaw(GridPos tile) {
        if (player == null || tile == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos bp = arena.gridToBlockPos(tile);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.SCULK_SOUL,
            bp.getX() + 0.5, bp.getY() + 0.5, bp.getZ() + 0.5, 14, 0.25, 0.3, 0.25, 0.02);
        world.playSound(null, bp,
            net.minecraft.sound.SoundEvents.BLOCK_SCULK_SHRIEKER_SHRIEK,
            net.minecraft.sound.SoundCategory.HOSTILE, 0.7f, 1.4f);

        int dealt = damagePlayerFromTile(SCULK_JAW_DAMAGE, null);
        int levels = Math.min(SCULK_JAW_XP_STEAL, player.experienceLevel);
        if (levels > 0) {
            player.addExperienceLevels(-levels);
            sculkJawHoard.merge(tile, levels, Integer::sum);
            sendMessage("§3A sculk jaw clamps down! §f" + dealt
                + " damage and it swallows " + levels + " XP level. §7(Break it to get them back)");
        } else {
            sendMessage("§3A sculk jaw clamps down! §f" + dealt + " damage.");
        }
    }

    /**
     * Destroy a sculk jaw tile and return whatever XP it was holding. Called from the
     * attack path when a player strikes a jaw tile.
     */
    private void breakSculkJaw(GridPos tile) {
        GridTile t = arena.getTile(tile);
        if (t == null || t.getType() != com.crackedgames.craftics.core.TileType.SCULK_JAW) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos bp = arena.gridToBlockPos(tile);
        world.setBlockState(bp, net.minecraft.block.Blocks.AIR.getDefaultState(), 3);
        world.syncWorldEvent(2001, bp, net.minecraft.block.Block.getRawIdFromState(
            net.minecraft.block.Blocks.SCULK_SHRIEKER.getDefaultState()));
        world.playSound(null, bp,
            net.minecraft.sound.SoundEvents.BLOCK_SCULK_BREAK,
            net.minecraft.sound.SoundCategory.BLOCKS, 0.8f, 0.9f);
        t.setType(com.crackedgames.craftics.core.TileType.NORMAL);

        Integer held = sculkJawHoard.remove(tile);
        if (held != null && held > 0) {
            player.addExperienceLevels(held);
            sendMessage("§aThe jaw splits open - you recover " + held + " XP level"
                + (held == 1 ? "" : "s") + ".");
        } else {
            sendMessage("§7The sculk jaw is destroyed.");
        }
    }

    /** Put a stack in the player's inventory, dropping it at their feet if full. */
    private void giveOrDropItem(ItemStack stack) {
        if (player == null || stack == null || stack.isEmpty()) return;
        if (!player.getInventory().insertStack(stack)) {
            player.dropItem(stack, false);
        }
    }

    /**
     * Spawn the visible armor stand for a decoy. The {@link CombatEntity} itself
     * is a block object (that's what carries HP and the grid slot); this is only
     * what the player sees, so it is invulnerable and gravity-free.
     */
    private void spawnDecoyVisual(CombatEntity decoy, GridPos pos, ServerWorld world) {
        BlockPos bp = arena.gridToBlockPos(pos);
        net.minecraft.entity.decoration.ArmorStandEntity stand =
            new net.minecraft.entity.decoration.ArmorStandEntity(
                world, bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5);
        stand.setNoGravity(true);
        stand.setInvulnerable(true);
        stand.addCommandTag("craftics_arena");
        stand.setCustomName(net.minecraft.text.Text.literal("§7Decoy"));
        world.spawnEntity(stand);
        decoyVisuals.put(decoy.getEntityId(), stand);
    }

    /** Discard a destroyed decoy's armor stand, if it had one. */
    private void clearDecoyVisual(CombatEntity entity) {
        net.minecraft.entity.Entity visual = decoyVisuals.remove(entity.getEntityId());
        if (visual != null) visual.discard();
    }

    /**
     * Once-per-round hive tick: every living hive on the field releases one bee.
     * A player-placed hive ({@link #HIVE_ALLY_ID}) releases an ally that fights
     * for the party; a wild forest hive ({@link #HIVE_WILD_ID}) releases a hostile
     * one. Each hive keeps at most {@link #HIVE_BEE_CAP} of its bees alive, so a
     * long fight doesn't drown in them and the hive stays worth breaking.
     */
    private void tickBeeHives() {
        if (arena == null || player == null) return;
        List<CombatEntity> hives = new ArrayList<>();
        for (CombatEntity e : enemies) {
            if (!e.isAlive()) continue;
            String id = e.getEntityTypeId();
            if (HIVE_ALLY_ID.equals(id) || HIVE_WILD_ID.equals(id)) hives.add(e);
        }
        if (hives.isEmpty()) return;

        for (CombatEntity hive : hives) {
            boolean allied = HIVE_ALLY_ID.equals(hive.getEntityTypeId());
            // Count this hive's own live bees against the cap.
            int liveBees = 0;
            for (CombatEntity e : enemies) {
                if (e.isAlive() && "minecraft:bee".equals(e.getEntityTypeId())
                        && e.isAlly() == allied) {
                    liveBees++;
                }
            }
            if (liveBees >= HIVE_BEE_CAP) continue;

            GridPos spot = findOpenTileNear(hive.getGridPos());
            if (spot == null) continue;
            CombatEntity bee = spawnRaidReinforcement("minecraft:bee", spot, 4, 2, 0, 1);
            if (bee == null) continue;
            if (allied) bee.setAlly(true);
            ServerWorld hw = (ServerWorld) player.getEntityWorld();
            BlockPos bp = arena.gridToBlockPos(spot);
            hw.spawnParticles(net.minecraft.particle.ParticleTypes.HAPPY_VILLAGER,
                bp.getX() + 0.5, bp.getY() + 0.5, bp.getZ() + 0.5, 8, 0.3, 0.3, 0.3, 0.02);
            hw.playSound(null, bp, net.minecraft.sound.SoundEvents.ENTITY_BEE_LOOP,
                net.minecraft.sound.SoundCategory.NEUTRAL, 0.6f, 1.0f);
            sendMessage(allied
                ? "§eA bee buzzes out of your hive to help!"
                : "§cA bee swarms out of the hive!");
        }
    }

    /** Entity id for the Deeper-and-Darker infested sculk prop. */
    public static final String INFESTED_SCULK_ID = "craftics:infested_sculk";
    /** Entity id for the Deeper-and-Darker ancient vase prop. */
    public static final String ANCIENT_VASE_ID = "craftics:ancient_vase";
    /** HP of the infested sculk block - soft, so it dies to a single careless swing. */
    public static final int INFESTED_SCULK_HP = 10;
    /** HP of the ancient vase - deliberately brittle, it is pottery. */
    public static final int ANCIENT_VASE_HP = 6;

    /**
     * Resolve a destroyed Deeper-and-Darker prop. No-op for anything else, so this is
     * safe to call for every kill.
     *
     * <p>Both props are gambles resolved at the moment of breaking:
     * <ul>
     *   <li><b>Infested sculk</b> erupts with Sculk Leeches and a Shriek Worm and
     *       shoves the breaker back, unless they used Silk Touch - which is exactly
     *       the source mod's {@code PREVENTS_INFESTED_SCULK_SPAWNS} contract, and
     *       makes a Silk Touch tool worth carrying into the Deep Dark.</li>
     *   <li><b>Ancient vase</b> pays out treasure, or bursts open with a Stalker.
     *       Silk Touch does not help here: the mod lets you take the vase itself
     *       intact instead, so that is what we hand over.</li>
     * </ul>
     */
    private void breakDeepDarkProp(CombatEntity entity) {
        if (entity == null) return;
        String id = entity.getEntityTypeId();
        boolean infested = INFESTED_SCULK_ID.equals(id);
        boolean vase = ANCIENT_VASE_ID.equals(id);
        if (!infested && !vase) return;

        GridPos pos = entity.getGridPos();
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos bp = arena.gridToBlockPos(pos);
        // spawnBlockObject painted a block here; nothing else clears it on death.
        world.setBlockState(bp, net.minecraft.block.Blocks.AIR.getDefaultState(), 3);

        boolean silk = PlayerCombatStats.getEnchantLevel(
            player.getMainHandStack(), "minecraft:silk_touch") > 0;

        if (infested) {
            if (silk) {
                giveOrDropItem(new ItemStack(Items.SCULK));
                sendMessage("§aSilk Touch: the sculk comes away clean - nothing wakes up.");
                return;
            }
            com.crackedgames.craftics.compat.deeperanddarker.DeeperAndDarkerCompat
                .eruptInfestedSculk(this, pos);
            return;
        }

        com.crackedgames.craftics.compat.deeperanddarker.DeeperAndDarkerCompat
            .openAncientVase(this, pos, silk);
    }

    /**
     * Spawn a hostile at or near {@code around} for a compat prop's ambush. Public so
     * compat modules can drive their own break effects without reaching into combat
     * internals. Returns null when there is nowhere to put it.
     */
    public CombatEntity spawnPropAmbusher(String entityTypeId, GridPos around,
                                          int hp, int atk, int def, int range) {
        GridPos spot = arena.isOccupied(around) ? findOpenTileNear(around) : around;
        if (spot == null) return null;
        return spawnRaidReinforcement(entityTypeId, spot, hp, atk, def, range);
    }

    /** Hand a stack to the player (or drop it at their feet). Public for compat props. */
    public void givePropLoot(ItemStack stack) {
        giveOrDropItem(stack);
    }

    /** Send a combat message. Public for compat props. */
    public void propMessage(String message) {
        sendMessage(message);
    }

    /** Shove the player away from {@code from} by {@code tiles}. Public for compat props. */
    public void shovePlayerFrom(GridPos from, int tiles) {
        GridPos p = arena.getPlayerGridPos();
        if (p == null || from == null) return;
        int dx = Integer.signum(p.x() - from.x());
        int dz = Integer.signum(p.z() - from.z());
        if (dx == 0 && dz == 0) dx = 1;
        resolveForcedMovement(new EnemyAction.ForcedMovement(-1, dx, dz, tiles));
    }

    /** The world this fight is running in. Public for compat props. */
    public ServerWorld propWorld() {
        return (ServerWorld) player.getEntityWorld();
    }

    /** Block position of a grid tile. Public for compat props. */
    public BlockPos propBlockPos(GridPos pos) {
        return arena.gridToBlockPos(pos);
    }

    /**
     * Heart of the Deep's pulse: drag every hidden enemy back into view and lift the
     * Darkness from the whole party.
     *
     * <p>Reveal works by tripping each AI's own hidden-state latch rather than by
     * forcing {@code setInvisible(false)} alone - otherwise the AI would simply
     * re-hide itself on its next turn and the pulse would look broken. The two latches
     * behave differently on purpose: a shriek worm's is a one-way trigger so it stays
     * revealed for good, while a stalker's only clears its current vanish, so it can
     * still slip away again on its next stalk turn.
     *
     * @return the number of enemies dragged into view
     */
    public int pulseReveal() {
        int revealed = 0;
        for (CombatEntity e : enemies) {
            if (e == null || !e.isAlive() || e.isAlly()) continue;
            boolean wasHidden = false;
            if (com.crackedgames.craftics.compat.deeperanddarker.DeeperAndDarkerCompat
                    .SHRIEK_WORM.equals(e.getEntityTypeId())
                    && e.getAiMemory(com.crackedgames.craftics.combat.ai.deeperanddarker
                        .ShriekWormAI.REVEALED_KEY, 0) == 0) {
                e.setAiMemory(com.crackedgames.craftics.combat.ai.deeperanddarker
                    .ShriekWormAI.REVEALED_KEY, 1);
                wasHidden = true;
            }
            if (e.getAiMemory(com.crackedgames.craftics.combat.ai.deeperanddarker
                    .StalkerAI.HIDDEN_KEY, 0) == 1) {
                e.setAiMemory(com.crackedgames.craftics.combat.ai.deeperanddarker
                    .StalkerAI.HIDDEN_KEY, 0);
                wasHidden = true;
            }
            if (e.getMobEntity() != null && e.getMobEntity().isInvisible()) {
                e.getMobEntity().setInvisible(false);
                wasHidden = true;
            }
            if (wasHidden) revealed++;
        }
        // Clearing Darkness is the other half: the pulse is the answer to a Deep Dark
        // that hides things from you, whether by mob or by effect.
        combatEffects.removeEffect(CombatEffects.EffectType.DARKNESS);
        sendSync();
        refreshHighlights();
        return revealed;
    }

    /**
     * Soul Elytra glide: launch the player to {@code target}, passing OVER everything
     * between. Unlike a normal move this ignores obstacles, hazards and void along the
     * way - only the landing tile has to be sound - which is what makes it worth an
     * artifact slot in arenas built around pits and jaws.
     *
     * @return null on success, or a player-facing reason it couldn't launch
     */
    public String glideTo(GridPos target, int maxTiles) {
        if (target == null) return "§cNeed to target a tile!";
        GridPos from = arena.getPlayerGridPos();
        if (from == null) return "§cCan't launch from here.";
        int dist = Math.max(Math.abs(target.x() - from.x()), Math.abs(target.z() - from.z()));
        if (dist == 0) return "§cPick a tile to glide to.";
        if (dist > maxTiles) return "§cToo far! The elytra carries you " + maxTiles + " tiles.";
        if (!arena.isInBounds(target)) return "§cThat's outside the arena.";
        if (arena.isOccupied(target)) return "§cSomething is already standing there.";
        GridTile landing = arena.getTile(target);
        if (landing == null || !landing.isWalkable()) return "§cNothing to land on there.";

        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos fromBp = arena.gridToBlockPos(from);
        BlockPos toBp = arena.gridToBlockPos(target);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL,
            fromBp.getX() + 0.5, fromBp.getY() + 0.8, fromBp.getZ() + 0.5, 20, 0.3, 0.4, 0.3, 0.05);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME,
            toBp.getX() + 0.5, toBp.getY() + 0.6, toBp.getZ() + 0.5, 18, 0.3, 0.3, 0.3, 0.03);
        world.playSound(null, toBp, net.minecraft.sound.SoundEvents.ITEM_ELYTRA_FLYING,
            net.minecraft.sound.SoundCategory.PLAYERS, 0.8f, 1.3f);

        arena.setPlayerGridPos(target);
        player.requestTeleport(toBp.getX() + 0.5, toBp.getY(), toBp.getZ() + 0.5);
        sendSync();
        refreshHighlights();
        return null;
    }

    /**
     * Breaking a wild forest hive with a Silk Touch tool yields the hive itself,
     * turning a hazard you had to clear into a beehive you can place on your own
     * side. Without Silk Touch the hive is simply destroyed, so the tool choice
     * is the whole decision.
     */
    private void dropHiveOnSilkTouch(CombatEntity entity) {
        if (player == null || entity == null) return;
        if (!HIVE_WILD_ID.equals(entity.getEntityTypeId())) return;
        if (PlayerCombatStats.getEnchantLevel(
                player.getMainHandStack(), "minecraft:silk_touch") <= 0) {
            return;
        }
        giveOrDropItem(new ItemStack(Items.BEEHIVE));
        sendMessage("§a✦ Silk Touch! §7You harvest the hive intact.");
    }

    /**
     * What a mob does when its target is hidden (in tall grass, or invisible) and
     * it has nothing it can actually see. Instead of standing still it hunts:
     *
     * <ol>
     *   <li>Adjacent to a stealth tile? Thrash it - that breaks the cover and
     *       flushes out anyone inside.</li>
     *   <li>Otherwise walk toward the nearest stealth tile on the field, since
     *       that's the only place the target could be hiding.</li>
     *   <li>No cover left anywhere? Wander, so it's still searching rather than
     *       frozen.</li>
     * </ol>
     */
    private EnemyAction searchForHiddenTarget(CombatEntity hunter) {
        GridPos from = hunter.getGridPos();
        net.minecraft.world.World world = player != null ? player.getEntityWorld() : null;

        GridPos nearest = null;
        int bestDist = Integer.MAX_VALUE;
        for (int x = 0; x < arena.getWidth(); x++) {
            for (int z = 0; z < arena.getHeight(); z++) {
                GridPos p = new GridPos(x, z);
                if (!StealthTiles.isStealthTile(arena, p, world)) continue;
                int d = Math.max(Math.abs(p.x() - from.x()), Math.abs(p.z() - from.z()));
                if (d < bestDist) { bestDist = d; nearest = p; }
            }
        }

        // Nothing left to search - keep moving so the mob still reads as hunting.
        if (nearest == null) {
            return com.crackedgames.craftics.combat.ai.AIUtils.wander(hunter, arena);
        }
        // Already next to cover: tear it open.
        if (bestDist <= 1) {
            return new EnemyAction.BreakStealthTile(nearest);
        }
        // Close in on the nearest patch of cover.
        List<GridPos> path = Pathfinding.findPathSized(
            arena, from, nearest, hunter.getMoveSpeed(), hunter);
        if (path.isEmpty()) {
            return com.crackedgames.craftics.combat.ai.AIUtils.wander(hunter, arena);
        }
        return new EnemyAction.Move(path);
    }

    /**
     * Destroy the stealth cover on a tile: clears both grass/fern block halves,
     * resets the tile so its occupant stops being hidden, and plays the break
     * feedback. Shared by the player's 1-AP grass break and the enemy search.
     */
    private void breakStealthTileAt(GridPos pos) {
        if (arena == null || player == null || pos == null) return;
        ServerWorld sw = (ServerWorld) player.getEntityWorld();
        BlockPos floorBlock = arena.gridToBlockPos(pos);
        BlockPos lowerPos = floorBlock.up(1);
        BlockPos upperPos = floorBlock.up(2);
        net.minecraft.block.BlockState broken = sw.getBlockState(lowerPos);
        sw.setBlockState(lowerPos, net.minecraft.block.Blocks.AIR.getDefaultState(), 3);
        sw.setBlockState(upperPos, net.minecraft.block.Blocks.AIR.getDefaultState(), 3);
        GridTile tile = arena.getTile(pos);
        if (tile != null) tile.setType(TileType.NORMAL);
        sw.spawnParticles(new net.minecraft.particle.BlockStateParticleEffect(
                net.minecraft.particle.ParticleTypes.BLOCK, broken),
            lowerPos.getX() + 0.5, lowerPos.getY() + 0.5, lowerPos.getZ() + 0.5,
            10, 0.3, 0.3, 0.3, 0.1);
        sw.playSound(null, lowerPos, net.minecraft.sound.SoundEvents.BLOCK_GRASS_BREAK,
            net.minecraft.sound.SoundCategory.BLOCKS, 1.0f, 1.0f);
    }

    /** A free, walkable tile adjacent to {@code around} (8-dir), or null. */
    private GridPos findOpenTileNear(GridPos around) {
        for (int dx = -1; dx <= 1; dx++) {
            for (int dz = -1; dz <= 1; dz++) {
                if (dx == 0 && dz == 0) continue;
                GridPos p = new GridPos(around.x() + dx, around.z() + dz);
                if (!arena.isInBounds(p) || arena.isOccupied(p)) continue;
                GridTile t = arena.getTile(p);
                if (t == null || !t.isWalkable()) continue;
                if (p.equals(arena.getPlayerGridPos())) continue;
                return p;
            }
        }
        return null;
    }

    /** Tick sand-mine lifetimes at end of player turn; arm fresh mines and expire old ones. */
    private void tickSandMines() {
        if (activeSandMines.isEmpty()) return;
        ServerWorld world = player != null ? (ServerWorld) player.getEntityWorld() : null;
        var it = activeSandMines.iterator();
        while (it.hasNext()) {
            SandMine m = it.next();
            m.armedThisTurn = false; // becomes live after the turn it was planted
            m.turnsRemaining--;
            if (m.turnsRemaining <= 0) {
                it.remove();
                notifySandMineRemoved();
                if (world != null && arena.isInBounds(m.pos)) {
                    BlockPos bp = arena.gridToBlockPos(m.pos);
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE,
                        bp.getX() + 0.5, bp.getY() + 0.3, bp.getZ() + 0.5, 8, 0.25, 0.2, 0.25, 0.01);
                }
            }
        }
    }

    /** Tell the SandstormPharaoh AI a mine is gone so its active-mine count heals. */
    private void notifySandMineRemoved() {
        for (CombatEntity e : enemies) {
            if (!e.isAlive() || !e.isBoss()) continue;
            EnemyAI ai = resolveAi(e);
            if (ai instanceof com.crackedgames.craftics.combat.ai.boss.SandstormPharaohAI pharaoh) {
                pharaoh.notifyMineDestroyed();
            }
        }
    }

    /**
     * Called every combat tick -emit persistent column particles for each active rift
     * so the player always sees exactly where they are.
     */
    private void tickVoidRiftParticles() {
        if (activeVoidRifts.isEmpty() || player == null) return;
        ServerWorld sw = (ServerWorld) player.getEntityWorld();
        boolean slow = tickCounter % 4 == 0;
        boolean fast = tickCounter % 2 == 0;
        for (VoidRift rift : activeVoidRifts) {
            emitRiftPillar(sw, rift.a, slow, fast);
            emitRiftPillar(sw, rift.b, slow, fast);
        }
    }

    private void emitRiftPillar(ServerWorld sw, GridPos pos, boolean slow, boolean fast) {
        if (!arena.isInBounds(pos)) return;
        BlockPos bp = arena.gridToBlockPos(pos);
        double cx = bp.getX() + 0.5;
        double cy = bp.getY();
        double cz = bp.getZ() + 0.5;

        // Swirling portal column -highly visible from any angle.
        if (fast) {
            for (int i = 0; i < 3; i++) {
                double angle = (tickCounter * 0.35) + i * (Math.PI * 2.0 / 3.0);
                double r = 0.45;
                double px = cx + Math.cos(angle) * r;
                double pz = cz + Math.sin(angle) * r;
                sw.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
                    px, cy + 0.1 + (i * 0.4), pz, 1, 0.0, 0.15, 0.0, 0.02);
            }
            sw.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL,
                cx, cy + 0.05, cz, 2, 0.25, 0.05, 0.25, 0.0);
        }
        // Bright top marker so the pair is obvious from across the arena.
        if (slow) {
            sw.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD,
                cx, cy + 1.8, cz, 1, 0.05, 0.05, 0.05, 0.0);
            sw.spawnParticles(net.minecraft.particle.ParticleTypes.ENCHANTED_HIT,
                cx, cy + 0.9, cz, 1, 0.2, 0.3, 0.2, 0.01);
        }
    }

    /**
     * Check whether the given enemy landed on a rift tile. If so, teleport them to the
     * paired endpoint (including the Void Walker itself -the boss is not immune to its
     * own portals). Returns true if a teleport happened, in which case the caller should
     * cancel any remaining movement path so the lerp doesn't continue from the old route.
     */
    private boolean handleEnemyVoidRiftEntry(CombatEntity enemy, GridPos destination) {
        if (activeVoidRifts.isEmpty() || enemy == null || !enemy.isAlive()) return false;
        VoidRift matched = null;
        GridPos target = null;
        for (VoidRift rift : activeVoidRifts) {
            if (rift.usedThisTurn) continue;
            if (rift.a.equals(destination)) { matched = rift; target = rift.b; break; }
            if (rift.b.equals(destination)) { matched = rift; target = rift.a; break; }
        }
        if (matched == null || target == null) return false;
        if (!arena.isInBounds(target) || arena.isOccupied(target)) return false;
        GridTile gt = arena.getTile(target);
        if (gt == null || !gt.isWalkable()) return false;

        ServerWorld world = (ServerWorld) player.getEntityWorld();

        // Departure burst
        BlockPos depBp = arena.gridToBlockPos(destination);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
            depBp.getX() + 0.5, depBp.getY() + 1.0, depBp.getZ() + 0.5, 25, 0.3, 0.8, 0.3, 0.5);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL,
            depBp.getX() + 0.5, depBp.getY() + 0.5, depBp.getZ() + 0.5, 12, 0.3, 0.4, 0.3, 0.3);

        // Move the entity on the grid and teleport its mob visual counterpart.
        arena.moveEntity(enemy, target);
        MobEntity mob = enemy.getMobEntity();
        if (mob != null) {
            BlockPos arrBp = arena.gridToBlockPos(target);
            double offsetX = enemy.getSizeX() / 2.0;
            double offsetZ = enemy.getSizeZ() / 2.0;
            mob.requestTeleport(
                arrBp.getX() + offsetX,
                arena.getEntityY(target, enemy.isFlying()),
                arrBp.getZ() + offsetZ);
            // Arrival burst
            world.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL,
                arrBp.getX() + offsetX, arrBp.getY() + 1.0, arrBp.getZ() + offsetZ, 25, 0.3, 0.8, 0.3, 0.5);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD,
                arrBp.getX() + offsetX, arrBp.getY() + 1.0, arrBp.getZ() + offsetZ, 10, 0.2, 0.3, 0.2, 0.05);
            world.playSound(null, arrBp,
                net.minecraft.sound.SoundEvents.ENTITY_ENDERMAN_TELEPORT,
                net.minecraft.sound.SoundCategory.HOSTILE, 0.9f, 1.1f);
        }

        matched.usedThisTurn = true;
        sendMessage("§5" + enemy.getDisplayName() + " is dragged through the void rift!");
        return true;
    }

    /**
     * Check whether the player just stepped onto a rift. If so, teleport them
     * to the paired tile and grant a reward for engaging with the mechanic.
     * Returns true if a teleport occurred.
     */
    private boolean handleVoidRiftEntry(GridPos destination) {
        if (activeVoidRifts.isEmpty() || player == null) return false;
        VoidRift matched = null;
        GridPos target = null;
        for (VoidRift rift : activeVoidRifts) {
            if (rift.usedThisTurn) continue;
            if (rift.a.equals(destination)) { matched = rift; target = rift.b; break; }
            if (rift.b.equals(destination)) { matched = rift; target = rift.a; break; }
        }
        if (matched == null || target == null) return false;
        if (!arena.isInBounds(target) || arena.isOccupied(target)) {
            // Paired tile blocked -no teleport, but don't consume the rift.
            return false;
        }
        GridTile gt = arena.getTile(target);
        if (gt == null || !gt.isWalkable()) return false;

        ServerWorld world = (ServerWorld) player.getEntityWorld();

        // Departure burst at current position
        BlockPos depBp = arena.gridToBlockPos(destination);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
            depBp.getX() + 0.5, depBp.getY() + 1.0, depBp.getZ() + 0.5, 30, 0.3, 0.8, 0.3, 0.6);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL,
            depBp.getX() + 0.5, depBp.getY() + 0.5, depBp.getZ() + 0.5, 15, 0.3, 0.4, 0.3, 0.3);

        // Move the player
        arena.setPlayerGridPos(target);
        BlockPos arrBp = arena.gridToBlockPos(target);
        player.requestTeleport(arrBp.getX() + 0.5, arrBp.getY(), arrBp.getZ() + 0.5);
        broadcastPlayerPositionToOthers(player);

        // Arrival burst
        world.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL,
            arrBp.getX() + 0.5, arrBp.getY() + 1.0, arrBp.getZ() + 0.5, 30, 0.3, 0.8, 0.3, 0.6);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD,
            arrBp.getX() + 0.5, arrBp.getY() + 1.0, arrBp.getZ() + 0.5, 12, 0.2, 0.3, 0.2, 0.05);
        world.playSound(null, arrBp,
            net.minecraft.sound.SoundEvents.ENTITY_ENDERMAN_TELEPORT,
            net.minecraft.sound.SoundCategory.PLAYERS, 0.9f, 1.1f);

        matched.usedThisTurn = true;

        // Reward the player for using the rift. First traversal grants a buff bundle;
        // subsequent traversals of the same pair still teleport (tactical repositioning)
        // but don't re-grant the buff to prevent farming.
        if (!matched.hasGrantedBuff) {
            matched.hasGrantedBuff = true;
            addEffectHooked(CombatEffects.EffectType.STRENGTH, 2, 0);
            addEffectHooked(CombatEffects.EffectType.SPEED, 2, 0);
            sendMessage("§d§lVoid-Touched! §r§7You slipped through the boss's own rift -"
                + "§a+Strength §7and §b+Speed §7for 2 turns.");
        } else {
            sendMessage("§5  The rift flickers -you step through.");
        }
        return true;
    }

    /**
     * Tick rift lifetimes at end of player turn. Permanent rifts (Phase 2) are untouched.
     */
    private void tickVoidRifts() {
        if (activeVoidRifts.isEmpty()) return;
        var it = activeVoidRifts.iterator();
        ServerWorld world = player != null ? (ServerWorld) player.getEntityWorld() : null;
        while (it.hasNext()) {
            VoidRift rift = it.next();
            rift.usedThisTurn = false;
            if (rift.turnsRemaining < 0) continue; // permanent
            rift.turnsRemaining--;
            if (rift.turnsRemaining <= 0) {
                if (world != null) {
                    for (GridPos p : new GridPos[]{rift.a, rift.b}) {
                        if (!arena.isInBounds(p)) continue;
                        BlockPos bp = arena.gridToBlockPos(p);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE,
                            bp.getX() + 0.5, bp.getY() + 0.5, bp.getZ() + 0.5, 15, 0.3, 0.3, 0.3, 0.02);
                    }
                }
                it.remove();
            }
        }
    }

    private void clearVoidRifts() {
        activeVoidRifts.clear();
        // Sand mines share the same combat-teardown lifecycle as rifts.
        activeSandMines.clear();
        curseOfSandsTurns = 0;
        // Drop unresolved boss telegraphs on teardown too, so a warning whose boss
        // died before it resolved can't keep broadcasting its tiles into later levels.
        pendingBossWarnings.clear();
        pendingWeatherArrows.clear();
        // Anything still in the air is brought down and its damage settled. A flight that
        // outlived its fight would hold the input lock into the next one.
        if (activeFlight != null) {
            activeFlight.abort();
            activeFlight = null;
        }
        flightCeiling = 0;
        spellAnimCooldown = 0;
    }

    /**
     * Destroy every Void Walker mirror image bound to the given boss. Called when the
     * player successfully targets the real boss -all illusions shatter at once.
     */
    private void dispelVoidWalkerClones(int bossEntityId) {
        if (player == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        int shattered = 0;
        for (CombatEntity e : new ArrayList<>(enemies)) {
            if (!e.isAlive()) continue;
            if (!e.isMirrorClone() || e.getCloneOfBossId() != bossEntityId) continue;
            // Particle burst on each clone's position before we kill it.
            BlockPos bp = arena.gridToBlockPos(e.getGridPos());
            world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
                bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5, 25, 0.3, 0.6, 0.3, 0.5);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL,
                bp.getX() + 0.5, bp.getY() + 0.6, bp.getZ() + 0.5, 15, 0.3, 0.4, 0.3, 0.3);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE,
                bp.getX() + 0.5, bp.getY() + 0.5, bp.getZ() + 0.5, 10, 0.3, 0.3, 0.3, 0.02);
            // Striking the real boss instantly shatters every clone regardless of
            // their remaining HP (clones no longer vanish on a single hit).
            e.applyDirectDamage(e.getCurrentHp());
            checkAndHandleDeath(e);
            shattered++;
        }
        if (shattered > 0) {
            sendMessage("§5§l  You struck the real Void Walker! §r§5The mirror images shatter.");
            world.playSound(null, arena.gridToBlockPos(arena.getPlayerGridPos()),
                net.minecraft.sound.SoundEvents.BLOCK_GLASS_BREAK,
                net.minecraft.sound.SoundCategory.HOSTILE, 0.9f, 1.3f);
        }
    }

    /**
     * Dispatch a single boss sub-action (used by BossAbility resolution and CompositeAction).
     */
    private void dispatchBossSubAction(EnemyAction action) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        switch (action) {
            case EnemyAction.Attack atk -> {
                // Swap this.player to the player the boss actually targeted (closest
                // live member), not the last turn-holder. Without this, boss melee
                // sub-actions landed on the wrong player in co-op.
                ServerPlayerEntity savedBossPlayer = this.player;
                ServerPlayerEntity bossTarget = currentEnemy != null
                    ? findClosestPartyTarget(currentEnemy.getGridPos()) : this.player;
                boolean bossSwapped = bossTarget != null && bossTarget != savedBossPlayer;
                if (bossSwapped) { this.player = bossTarget; retargetEffectsToCurrentPlayer(); }
                boolean targetDied = false;
                try {
                    int actual = damagePlayer(atk.damage());
                    if (!lastHitAvoided && isFrostboundBossAttacker()) {
                        applyFrostboundSlownessOnHit();
                    }
                    // Impact particles at the targeted player
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.DAMAGE_INDICATOR,
                        player.getX(), player.getY() + 1.0, player.getZ(), 5, 0.3, 0.3, 0.3, 0.01);
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                        player.getX(), player.getY() + 0.8, player.getZ(), 8, 0.4, 0.5, 0.4, 0.02);
                    sendMessage("§c  Hit " + (bossSwapped ? bossTarget.getName().getString() : "you")
                        + " for " + actual + " damage! (HP: " + getPlayerHp() + ")");
                    if (getPlayerHp() <= 0) { targetDied = true; handlePlayerDeathOrGameOver(); }
                } finally {
                    if (bossSwapped && !targetDied) { this.player = savedBossPlayer; retargetEffectsToCurrentPlayer(); }
                }
            }
            case EnemyAction.SummonMinions sm -> spawnBossMinions(sm);
            case EnemyAction.SpawnProjectile sp -> spawnProjectiles(sp);
            case EnemyAction.AreaAttack aa -> resolveAreaAttack(aa);
            case EnemyAction.TileAreaAttack ta -> resolveTileAreaAttack(ta);
            case EnemyAction.CreateTerrain ct -> resolveCreateTerrain(ct);
            case EnemyAction.RaisePillars rp -> resolveRaisePillars(rp);
            case EnemyAction.IgniteTiles ignite -> resolveIgniteTiles(ignite);
            case EnemyAction.PlaceWeb pw -> resolvePlaceWeb(pw);
            case EnemyAction.LineAttack la -> resolveLineAttack(la);
            case EnemyAction.ModifySelf ms -> resolveModifySelf(currentEnemy, ms);
            case EnemyAction.ForcedMovement fm -> resolveForcedMovement(fm);
            case EnemyAction.Teleport tp -> {
                if (currentEnemy != null) {
                    // Departure particles at old position
                    MobEntity mob = currentEnemy.getMobEntity();
                    if (mob != null) {
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
                            mob.getX(), mob.getY() + 1.0, mob.getZ(), 20, 0.3, 0.8, 0.3, 0.5);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL,
                            mob.getX(), mob.getY() + 0.5, mob.getZ(), 10, 0.2, 0.5, 0.2, 0.3);
                        double wx = arena.getOrigin().getX() + tp.target().x() + 0.5;
                        double wz = arena.getOrigin().getZ() + tp.target().z() + 0.5;
                        mob.requestTeleport(wx,
                            arena.getEntityY(tp.target(), currentEnemy.isFlying()), wz);
                        // Arrival particles at new position
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
                            wx, arena.getOrigin().getY() + 2.0, wz, 20, 0.3, 0.8, 0.3, 0.5);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL,
                            wx, arena.getOrigin().getY() + 1.5, wz, 10, 0.2, 0.5, 0.2, 0.3);
                    }
                    arena.moveEntity(currentEnemy, tp.target());
                }
            }
            case EnemyAction.TeleportAndAttack tpa -> {
                if (currentEnemy != null) {
                    MobEntity mob = currentEnemy.getMobEntity();
                    if (mob != null) {
                        // Departure burst
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
                            mob.getX(), mob.getY() + 1.0, mob.getZ(), 15, 0.3, 0.8, 0.3, 0.5);
                        double wx = arena.getOrigin().getX() + tpa.target().x() + 0.5;
                        double wy = arena.getEntityY(tpa.target(), currentEnemy.isFlying());
                        double wz = arena.getOrigin().getZ() + tpa.target().z() + 0.5;
                        mob.requestTeleport(wx, wy, wz);
                        // Arrival + strike burst
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL,
                            wx, wy + 1.0, wz, 15, 0.3, 0.5, 0.3, 0.3);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                            wx, wy + 0.5, wz, 10, 0.4, 0.6, 0.4, 0.03);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.DAMAGE_INDICATOR,
                            player.getX(), player.getY() + 1.0, player.getZ(), 5, 0.3, 0.3, 0.3, 0.01);
                    }
                    arena.moveEntity(currentEnemy, tpa.target());
                    // Strike the player the boss teleported to (closest member), not
                    // the last turn-holder.
                    ServerPlayerEntity savedTpaPlayer = this.player;
                    ServerPlayerEntity tpaTarget = findClosestPartyTarget(currentEnemy.getGridPos());
                    boolean tpaSwapped = tpaTarget != null && tpaTarget != savedTpaPlayer;
                    if (tpaSwapped) { this.player = tpaTarget; retargetEffectsToCurrentPlayer(); }
                    boolean targetDied = false;
                    try {
                        int actual = damagePlayer(tpa.damage(), currentEnemy);
                        if (!lastHitAvoided && isFrostboundBossAttacker()) {
                            applyFrostboundSlownessOnHit();
                        }
                        sendMessage("§c  Teleport strike on " + (tpaSwapped ? tpaTarget.getName().getString() : "you")
                            + " for " + actual + " damage! (HP: " + getPlayerHp() + ")");
                        if (getPlayerHp() <= 0) { targetDied = true; handlePlayerDeathOrGameOver(); }
                    } finally {
                        if (tpaSwapped && !targetDied) { this.player = savedTpaPlayer; retargetEffectsToCurrentPlayer(); }
                    }
                }
            }
            case EnemyAction.RangedAttack ra -> {
                // Swap this.player to the boss's actual ranged target (closest live
                // member) so the hit, status effects, knockback, overwatch and death
                // handling all land on the right player in co-op.
                ServerPlayerEntity savedRaPlayer = this.player;
                ServerPlayerEntity raTarget = currentEnemy != null
                    ? findClosestPartyTarget(currentEnemy.getGridPos()) : this.player;
                boolean raSwapped = raTarget != null && raTarget != savedRaPlayer;
                if (raSwapped) { this.player = raTarget; retargetEffectsToCurrentPlayer(); }
                boolean raTargetDied = false;
                try {
                // Aegis hybrid: a chance to dodge incoming ranged attacks outright.
                if (activeHybridEffect() == HybridEffect.AEGIS
                        && Math.random() < HybridSetEffects.AEGIS_DODGE_CHANCE) {
                    playDodgeFeedback("§b§l✦ AEGIS!",
                        "§b§l✦ Aegis!§r §7You sidestep the " + currentEnemy.getDisplayName()
                            + "'s ranged attack.");
                    fireEffectHook(h -> h.onDodge(effectContext, currentEnemy));
                    sendSync();
                    break;
                }
                int actual = damagePlayer(ra.damage(), currentEnemy, DamageType.RANGED);
                // A fully avoided ranged hit (dodge / Ethereal / shield block / Gilded
                // Guard) applies no impact effects, knockback, or hit message -only the
                // avoid feedback already shown inside damagePlayer.
                if (!lastHitAvoided) {
                if (isFrostboundBossAttacker()) {
                    applyFrostboundSlownessOnHit();
                }
                // Ranged impact particles based on attack type
                String rangedType = ra.effectName() != null ? ra.effectName() : "";
                switch (rangedType) {
                    case "frost_arrow" -> {
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.SNOWFLAKE,
                            player.getX(), player.getY() + 1.0, player.getZ(), 10, 0.3, 0.5, 0.3, 0.02);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.ENCHANTED_HIT,
                            player.getX(), player.getY() + 0.8, player.getZ(), 5, 0.2, 0.3, 0.2, 0.01);
                    }
                    case "venomous_bite" -> {
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.ITEM_SLIME,
                            player.getX(), player.getY() + 0.8, player.getZ(), 8, 0.3, 0.4, 0.3, 0.02);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.HAPPY_VILLAGER,
                            player.getX(), player.getY() + 1.0, player.getZ(), 5, 0.2, 0.3, 0.2, 0.01);
                        addEffectHooked(CombatEffects.EffectType.POISON, 3, 1);
                        sendMessage("§2  Poisoned for 3 turns!");
                    }
                    case "hex_bolt" -> {
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.WITCH,
                            player.getX(), player.getY() + 1.0, player.getZ(), 10, 0.3, 0.5, 0.3, 0.02);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL,
                            player.getX(), player.getY() + 0.8, player.getZ(), 5, 0.2, 0.3, 0.2, 0.01);
                    }
                    case "shulker_bullet" -> {
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD,
                            player.getX(), player.getY() + 1.0, player.getZ(), 8, 0.3, 0.5, 0.3, 0.02);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.ELECTRIC_SPARK,
                            player.getX(), player.getY() + 0.8, player.getZ(), 5, 0.2, 0.3, 0.2, 0.01);
                    }
                    case "sonic_boom" -> {
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.SONIC_BOOM,
                            player.getX(), player.getY() + 1.0, player.getZ(), 1, 0.0, 0.0, 0.0, 0.0);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.SCULK_SOUL,
                            player.getX(), player.getY() + 1.0, player.getZ(), 10, 0.4, 0.5, 0.4, 0.02);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                            player.getX(), player.getY() + 0.6, player.getZ(), 6, 0.3, 0.3, 0.3, 0.01);
                        // Same payload as the Warden's beam version (see applyBossAreaEffect):
                        // a sonic boom means one thing wherever it comes from. Infinite and raid
                        // bosses draw this from the ability pool as a single-target shot rather
                        // than a lane, but what it does to whoever it catches is identical.
                        addEffectHooked(CombatEffects.EffectType.MARKED, SONIC_MARK_TURNS, 0);
                        addEffectHooked(CombatEffects.EffectType.DARKNESS, SONIC_MARK_TURNS, 0);
                        addEffectHooked(CombatEffects.EffectType.BLINDNESS, SONIC_MARK_TURNS, 0);
                        sendMessage("§3  The sonic boom rips through you! §8Marked, blinded and lost in the dark ("
                            + SONIC_MARK_TURNS + " turns)");
                    }
                    case "poison_arrow" -> {
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.ITEM_SLIME,
                            player.getX(), player.getY() + 0.8, player.getZ(), 8, 0.3, 0.4, 0.3, 0.02);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.HAPPY_VILLAGER,
                            player.getX(), player.getY() + 1.0, player.getZ(), 5, 0.2, 0.3, 0.2, 0.01);
                        addEffectHooked(CombatEffects.EffectType.POISON, 3, 1);
                        sendMessage("§2  Poisoned for 3 turns!");
                    }
                    case "wind_charge" -> {
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.GUST,
                            player.getX(), player.getY() + 1.0, player.getZ(), 8, 0.4, 0.4, 0.4, 0.02);
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.SWEEP_ATTACK,
                            player.getX(), player.getY() + 1.0, player.getZ(), 2, 0.2, 0.2, 0.2, 0.0);
                        world.playSound(null, player.getBlockPos(),
                            net.minecraft.sound.SoundEvents.ENTITY_WIND_CHARGE_WIND_BURST.value(),
                            net.minecraft.sound.SoundCategory.HOSTILE, 1.2f, 0.9f);
                        applyWindChargeKnockback(currentEnemy);
                    }
                    default -> {
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                            player.getX(), player.getY() + 1.0, player.getZ(), 8, 0.3, 0.5, 0.3, 0.02);
                    }
                }
                sendMessage("§c  Ranged hit " + (raSwapped ? raTarget.getName().getString() : "you")
                    + " for " + actual + " damage! (HP: " + getPlayerHp() + ")");
                } // end ranged on-hit effects (skipped on a fully avoided attack)
                checkOverwatchCounter(currentEnemy);
                if (getPlayerHp() <= 0) { raTargetDied = true; handlePlayerDeathOrGameOver(); }
                } finally {
                    if (raSwapped && !raTargetDied) { this.player = savedRaPlayer; retargetEffectsToCurrentPlayer(); }
                }
            }
            case EnemyAction.CeilingDrop drop -> {
                if (currentEnemy != null) {
                    currentEnemy.setOnCeiling(false);
                    currentEnemy.setGridPos(drop.landingPos());
                    arena.placeEntity(currentEnemy);
                    MobEntity dropMob = currentEnemy.getMobEntity();
                    if (dropMob != null) {
                        dropMob.setInvisible(false);
                        BlockPos landBlock = arena.gridToBlockPos(drop.landingPos());
                        dropMob.requestTeleport(landBlock.getX() + 0.5,
                            arena.getEntityY(drop.landingPos()),
                            landBlock.getZ() + 0.5);
                    }
                    sendMessage("§c  " + currentEnemy.getDisplayName() + " slams down from the ceiling!");
                }
            }
            case EnemyAction.CompositeAction ca -> {
                for (EnemyAction sub : ca.actions()) {
                    dispatchBossSubAction(sub);
                }
            }
            case EnemyAction.Burrow ignored -> {
                // Defense in depth: Burrow is meant to be a top-level, turn-owning action (BossAI
                // never composes it), but if one ever reaches here it MUST bury the boss, or the
                // untargetable flag never gets set and the "digs under" beat silently vanishes.
                if (currentEnemy != null) {
                    sendMessage("§8§l✦ " + currentEnemy.getDisplayName()
                        + " digs into the earth! §7You cannot reach it.");
                    burrowEnemy(currentEnemy);
                }
            }
            case EnemyAction.Surface surface -> {
                // Defense in depth: same reasoning as Burrow. A dropped Surface would strand the
                // boss underground and permanently untargetable, so route it to the real handler.
                if (currentEnemy != null) {
                    surfaceEnemy(currentEnemy, surface.anchor(),
                        "§c§l✦ " + currentEnemy.getDisplayName() + " erupts from the grave!");
                }
            }
            case EnemyAction.Swoop swoop -> {
                // Dispatch the same way the top-level case does: snap the mob to
                // the first path tile, make it visible, and kick off the lerp via
                // startEnemyMove. The Idle-bypass code path that called us will
                // then let tickEnemyMoving take over instead of forcing DONE.
                MobEntity subMob = currentEnemy != null ? currentEnemy.getMobEntity() : null;
                if (subMob != null && !swoop.path().isEmpty()) {
                    subMob.setInvisible(false);
                    subMob.setSilent(false);
                    GridPos swoopStart = swoop.path().get(0);
                    // Same occupancy guard as the top-level case: never snap the mob onto a
                    // tile somebody is standing on. See there for why this one line was the
                    // whole phantom-lands-inside-you bug.
                    if (!currentEnemy.getGridPos().equals(swoopStart)
                            && !tileTakenByOther(swoopStart)) {
                        BlockPos snapBlock = arena.gridToBlockPos(swoopStart);
                        subMob.requestTeleport(
                            snapBlock.getX() + currentEnemy.getSizeX() / 2.0,
                            arena.getEntityY(swoopStart),
                            snapBlock.getZ() + currentEnemy.getSizeZ() / 2.0);
                        arena.moveEntity(currentEnemy, swoopStart);
                    }
                }
                startEnemyMove(swoop.path());
            }
            default -> {} // Ignore unsupported sub-actions
        }
    }

    /**
     * Spawn minions for a boss SummonMinions action.
     */
    private void spawnBossMinions(EnemyAction.SummonMinions sm) {
        // Special handling: Broodmother egg sac placement (not a real mob spawn)
        if ("craftics:egg_sac".equals(sm.entityTypeId())) {
            EnemyAI bossAi = resolveAi(currentEnemy);
            if (bossAi instanceof BroodmotherAI broodmother) {
                ServerWorld world = (ServerWorld) player.getEntityWorld();
                for (GridPos pos : sm.positions()) {
                    placeEggSacEntity(broodmother, pos, world);
                    broodmother.registerEggSac(pos);
                }
                sendMessage("§e  The Broodmother lays new eggs!");
            }
            return;
        }

        // Special handling: Revenant phase-2 graves (not a real mob spawn). Only graves the grid
        // accepted are registered, so a refused tile does not inflate the zombie cap.
        if ("craftics:grave".equals(sm.entityTypeId())) {
            EnemyAI graveAi = resolveAi(currentEnemy);
            if (graveAi instanceof RevenantAI revenant) {
                ServerWorld world = (ServerWorld) player.getEntityWorld();
                int placed = 0;
                for (GridPos pos : sm.positions()) {
                    CombatEntity grave = placeBlockObject("craftics:grave", pos,
                        GRAVE_HP, -(graveIdCounter++), Blocks.COBBLESTONE_WALL, world);
                    if (grave != null) {
                        revenant.registerGrave(pos);
                        placed++;
                    }
                }
                if (placed > 0) sendMessage("§4  The Revenant tears open fresh graves!");
            }
            return;
        }

        ServerWorld world = (ServerWorld) player.getEntityWorld();
        EntityType<?> type = Registries.ENTITY_TYPE.get(Identifier.of(sm.entityTypeId()));
        int spawned = 0;
        java.util.List<GridPos> spawnPositions = sm.positions();
        if (isRevenantZombieSummon(sm)) {
            boolean hasAnyMarkers = spawnPositions.stream().anyMatch(this::isRevenantSummonMarker);
            if (hasAnyMarkers) {
                spawnPositions = spawnPositions.stream()
                    .filter(this::isRevenantSummonMarker)
                    .toList();
            }
            clearRevenantSummonMarkers(sm.positions());
            if (spawnPositions.isEmpty()) {
                sendMessage("§a  You shattered the grave markers before anything could emerge!");
                return;
            }
        }

        // Determine the grid size this batch of minions should occupy. Most
        // summoned minions are 1×1; Molten King splits come in at whatever size
        // the pending split mechanic requested (currently 2×2 gen-1 copies).
        int minionGridSize = pendingMoltenSplitKey != null && pendingMoltenSplitSize > 0
            ? pendingMoltenSplitSize : 1;

        for (GridPos pos : spawnPositions) {
            if (spawned >= sm.count()) break;
            // Check every tile in the minion's footprint, not just the origin.
            boolean areaClear = true;
            for (int dx = 0; dx < minionGridSize && areaClear; dx++) {
                for (int dz = 0; dz < minionGridSize && areaClear; dz++) {
                    GridPos t = new GridPos(pos.x() + dx, pos.z() + dz);
                    if (!arena.isInBounds(t) || arena.isOccupied(t)) { areaClear = false; break; }
                    GridTile gt = arena.getTile(t);
                    if (gt == null || !gt.isWalkable()) { areaClear = false; break; }
                }
            }
            if (!areaClear) continue;

            BlockPos spawnPos = arena.gridToBlockPos(pos);
            double centerOffset = minionGridSize / 2.0;
            var rawEntity = type.create(world, null, spawnPos, SpawnReason.MOB_SUMMONED, false, false);
            if (rawEntity == null) continue;
            rawEntity.refreshPositionAndAngles(
                spawnPos.getX() + centerOffset, spawnPos.getY(), spawnPos.getZ() + centerOffset, 0, 0);
            if (rawEntity instanceof MobEntity mob) {
                mob.setAiDisabled(true);
                mob.setInvulnerable(true);
                mob.setNoGravity(true);
                mob.noClip = true;
                mob.setPersistent();
                mob.addCommandTag("craftics_arena");
                // For Molten King splits: force vanilla slime size to match the 2×2
                // grid footprint (vanilla size 4 ≈ 2 blocks wide).
                if (pendingMoltenSplitKey != null
                        && mob instanceof net.minecraft.entity.mob.SlimeEntity) {
                    ((com.crackedgames.craftics.mixin.SlimeEntityAccessor) mob)
                        .craftics$setSize(4, true);
                }
            }
            world.spawnEntity(rawEntity);
            if (rawEntity instanceof MobEntity mob) {
                CombatEntity ce = new CombatEntity(
                    mob.getId(), sm.entityTypeId(), pos,
                    sm.hp(), sm.atk(), sm.def(), 1, minionGridSize
                );
                ce.setMobEntity(mob);
                // Void Walker Mirror Image: any enderman summon from the Void Walker
                // is a weak decoy (low HP/ATK from sm.hp()/sm.atk()) that TAKES DOUBLE
                // DAMAGE, wears the boss's name, and runs its own VoidWalkerAI (flagged as
                // clone) so it can use most of the boss's attack kit. Rifts and further
                // cloning are gated off.
                if (currentEnemy != null
                        && "boss:warped_forest".equals(currentEnemy.getAiKey())
                        && "minecraft:enderman".equals(sm.entityTypeId())) {
                    ce.setMirrorClone(true);
                    ce.setDamageTakenMultiplier(2.0);
                    ce.setCloneOfBossId(currentEnemy.getEntityId());
                    ce.setBossDisplayName(currentEnemy.getDisplayName());
                    ce.setAiOverrideKey("boss:warped_forest");
                    ce.setAiInstance(
                        new com.crackedgames.craftics.combat.ai.boss.VoidWalkerAI(true));
                    mob.setCustomName(Text.literal("§5§l" + currentEnemy.getDisplayName()));
                    mob.setCustomNameVisible(true);
                    // Match the real boss's 1.7x scale so clones visually match.
                    // (The real Void Walker is scaled in the boss-decoration switch above.)
                    scaleBoss(mob, 1.7);
                    if (com.crackedgames.craftics.CrafticsMod.CONFIG.bossGlowEffect()) {
                        mob.setGlowing(true);
                    }
                }
                // Molten King split: override AI so copies use the correct generation
                // and give each copy its own AI instance with independent state.
                if (pendingMoltenSplitKey != null) {
                    ce.setAiOverrideKey(pendingMoltenSplitKey);
                    ce.setBoss(true);
                    ce.setHazardImmune(true);
                    ce.setBossDisplayName(getBossName("nether_wastes"));
                    ce.setAiInstance(new MoltenKingAI(1));
                    if (com.crackedgames.craftics.CrafticsMod.CONFIG.bossGlowEffect()) {
                        mob.setGlowing(true);
                    }
                    mob.setCustomName(Text.literal("§c§lThe Molten King"));
                    mob.setCustomNameVisible(true);
                }
                enemies.add(ce);
                arena.placeEntity(ce);
                spawned++;
                // Add to no-collision team
                net.minecraft.scoreboard.Scoreboard sb = world.getScoreboard();
                net.minecraft.scoreboard.Team noCollideTeam = sb.getTeam(ARENA_TEAM_NAME);
                if (noCollideTeam != null) {
                    sb.addScoreHolderToTeam(mob.getUuidAsString(), noCollideTeam);
                }
                // Register with boss AI for tracking
                if (currentEnemy != null && currentEnemy.isBoss()) {
                    EnemyAI bAi = resolveAi(currentEnemy);
                    if (bAi instanceof com.crackedgames.craftics.combat.ai.boss.BossAI bossAi) {
                        bossAi.registerSpawnedMinion(ce.getEntityId());
                    }
                }
                // Boss-themed spawn particles based on minion type
                net.minecraft.particle.ParticleEffect spawnPrimary;
                net.minecraft.particle.ParticleEffect spawnSecondary;
                String minionType = sm.entityTypeId();
                if (minionType.contains("zombie") || minionType.contains("husk")) {
                    spawnPrimary = net.minecraft.particle.ParticleTypes.SMOKE;
                    spawnSecondary = net.minecraft.particle.ParticleTypes.SOUL;
                } else if (minionType.contains("spider") || minionType.contains("cave_spider")) {
                    spawnPrimary = net.minecraft.particle.ParticleTypes.ITEM_SLIME;
                    spawnSecondary = net.minecraft.particle.ParticleTypes.SMOKE;
                } else if (minionType.contains("blaze")) {
                    spawnPrimary = net.minecraft.particle.ParticleTypes.FLAME;
                    spawnSecondary = net.minecraft.particle.ParticleTypes.LAVA;
                } else if (minionType.contains("vex")) {
                    spawnPrimary = net.minecraft.particle.ParticleTypes.WITCH;
                    spawnSecondary = net.minecraft.particle.ParticleTypes.ENCHANT;
                } else if (minionType.contains("silverfish")) {
                    spawnPrimary = net.minecraft.particle.ParticleTypes.ASH;
                    spawnSecondary = net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE;
                } else if (minionType.contains("wither_skeleton")) {
                    spawnPrimary = net.minecraft.particle.ParticleTypes.SOUL;
                    spawnSecondary = net.minecraft.particle.ParticleTypes.LARGE_SMOKE;
                } else if (minionType.contains("enderman") || minionType.contains("endermite")) {
                    spawnPrimary = net.minecraft.particle.ParticleTypes.PORTAL;
                    spawnSecondary = net.minecraft.particle.ParticleTypes.REVERSE_PORTAL;
                } else if (minionType.contains("drowned")) {
                    spawnPrimary = net.minecraft.particle.ParticleTypes.SPLASH;
                    spawnSecondary = net.minecraft.particle.ParticleTypes.BUBBLE;
                } else if (minionType.contains("piglin")) {
                    spawnPrimary = net.minecraft.particle.ParticleTypes.CRIMSON_SPORE;
                    spawnSecondary = net.minecraft.particle.ParticleTypes.FLAME;
                } else if (minionType.contains("shulker")) {
                    spawnPrimary = net.minecraft.particle.ParticleTypes.END_ROD;
                    spawnSecondary = net.minecraft.particle.ParticleTypes.ENCHANTED_HIT;
                } else if (minionType.contains("magma_cube")) {
                    spawnPrimary = net.minecraft.particle.ParticleTypes.LAVA;
                    spawnSecondary = net.minecraft.particle.ParticleTypes.FLAME;
                } else {
                    spawnPrimary = net.minecraft.particle.ParticleTypes.POOF;
                    spawnSecondary = net.minecraft.particle.ParticleTypes.CLOUD;
                }
                world.spawnParticles(spawnPrimary,
                    spawnPos.getX() + 0.5, spawnPos.getY() + 0.8, spawnPos.getZ() + 0.5,
                    6, 0.3, 0.5, 0.3, 0.02);
                world.spawnParticles(spawnSecondary,
                    spawnPos.getX() + 0.5, spawnPos.getY() + 0.3, spawnPos.getZ() + 0.5,
                    4, 0.2, 0.3, 0.2, 0.01);
            }
        }
        if (spawned > 0) {
            if (pendingMoltenSplitKey != null) {
                sendMessage("§6§l  The Molten King splits into " + spawned + " fragments!");
                pendingMoltenSplitKey = null;
                pendingMoltenSplitSize = 0;
            } else {
                sendMessage("§5  " + spawned + " " + sm.entityTypeId().substring(sm.entityTypeId().indexOf(':') + 1)
                    + "(s) appeared!");
            }
        }
    }

    /**
     * A free, walkable tile adjacent (8-dir) to {@code want} for a displaced
     * projectile spawn, never a tile a party member is standing on. Null when
     * the whole neighborhood is blocked.
     */
    private GridPos findFreeProjectileTileNear(GridPos want) {
        if (arena == null || want == null) return null;
        for (int dx = -1; dx <= 1; dx++) {
            for (int dz = -1; dz <= 1; dz++) {
                if (dx == 0 && dz == 0) continue;
                GridPos cand = new GridPos(want.x() + dx, want.z() + dz);
                if (!arena.isInBounds(cand) || arena.isOccupied(cand)) continue;
                GridTile t = arena.getTile(cand);
                if (t == null || !t.isWalkable()) continue;
                boolean onPlayer = false;
                for (GridPos pp : arena.getAllPlayerGridPositions()) {
                    if (cand.equals(pp)) { onPlayer = true; break; }
                }
                if (!onPlayer) return cand;
            }
        }
        return null;
    }

    /**
     * Spawn projectile entities for a boss SpawnProjectile action.
     */
    private void spawnProjectiles(EnemyAction.SpawnProjectile sp) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        EntityType<?> type = Registries.ENTITY_TYPE.get(Identifier.of(sp.entityTypeId()));
        int spawned = 0;

        // Determine which visual entity to spawn alongside the invisible tracking mob
        String visualEntityId = switch (sp.projectileType()) {
            case "ghast_fireball" -> "minecraft:fireball";
            case "wither_skull", "grave_skull" -> "minecraft:wither_skull";
            case "shulker_bullet" -> "minecraft:shulker_bullet";
            case "scarab" -> "minecraft:silverfish";
            default -> null;
        };

        for (int i = 0; i < sp.positions().size(); i++) {
            GridPos pos = sp.positions().get(i);
            int[] dir = sp.directions().get(i);

            // Positions were picked when the ability was CAST - for telegraphed
            // barrages that's a full boss action earlier, and by resolve time the
            // player/boss/a minion can be standing there. Shift to a free
            // neighbor instead of silently dropping the projectile (which made
            // whole barrages fizzle against a mobile 1x1 infinite boss).
            if (!arena.isInBounds(pos) || arena.isOccupied(pos)
                    || arena.getTile(pos) == null || !arena.getTile(pos).isWalkable()) {
                pos = findFreeProjectileTileNear(pos);
                if (pos == null) continue;
            }
            // Re-aim from the actual spawn tile at the player's current position;
            // the cast-time direction goes stale the moment the player moves.
            GridPos aim = arena.getPlayerGridPos();
            if (aim != null && !aim.equals(pos)) {
                int adx = aim.x() - pos.x();
                int adz = aim.z() - pos.z();
                dir = Math.abs(adx) >= Math.abs(adz)
                    ? new int[]{Integer.signum(adx), 0}
                    : new int[]{0, Integer.signum(adz)};
            }

            GridTile tile = arena.getTile(pos);
            if (tile == null || !tile.isWalkable()) continue;

            BlockPos spawnPos = arena.gridToBlockPos(pos);

            // Spawn the visual projectile entity (fireball / wither skull)
            int spawnedVisualId = -1;
            if (visualEntityId != null) {
                EntityType<?> visualType = Registries.ENTITY_TYPE.get(Identifier.of(visualEntityId));
                //? if <=1.21.1 {
                var visualEntity = visualType.create(world);
                //?} else {
                /*var visualEntity = visualType.create(world, net.minecraft.entity.SpawnReason.LOAD);
                *///?}
                if (visualEntity != null) {
                    visualEntity.refreshPositionAndAngles(
                        spawnPos.getX() + 0.5, spawnPos.getY() + 0.5, spawnPos.getZ() + 0.5, 0, 0);
                    visualEntity.setNoGravity(true);
                    visualEntity.addCommandTag("craftics_arena");
                    visualEntity.addCommandTag("craftics_visual_projectile");
                    // Mob-typed visuals (the scarab's silverfish) must not think
                    // for themselves - they're puppets synced to the grid mob.
                    if (visualEntity instanceof MobEntity visualMob) {
                        visualMob.setAiDisabled(true);
                        visualMob.setSilent(true);
                        visualMob.setInvulnerable(true);
                    }
                    world.spawnEntity(visualEntity);
                    spawnedVisualId = visualEntity.getId();
                }
            }

            // Spawn the invisible tracking mob for grid logic. Some projectile
            // types (e.g. minecraft:wither_skull) are NOT MobEntity, so when
            // that happens we use a hidden blaze tracker instead.
            var rawEntity = type.create(world, null, spawnPos, SpawnReason.MOB_SUMMONED, false, false);
            MobEntity mob;
            if (rawEntity instanceof MobEntity asMob) {
                mob = asMob;
            } else {
                //? if <=1.21.1 {
                var fallback = net.minecraft.entity.EntityType.BLAZE.create(world);
                //?} else {
                /*var fallback = net.minecraft.entity.EntityType.BLAZE
                    .create(world, net.minecraft.entity.SpawnReason.LOAD);
                *///?}
                if (!(fallback instanceof MobEntity fallbackMob)) continue;
                mob = fallbackMob;
            }

            mob.refreshPositionAndAngles(
                spawnPos.getX() + 0.5, spawnPos.getY(), spawnPos.getZ() + 0.5, 0, 0);
            mob.setAiDisabled(true);
            mob.setInvulnerable(true);
            mob.setNoGravity(true);
            mob.noClip = true;
            mob.setPersistent();
            mob.addCommandTag("craftics_arena");
            world.spawnEntity(mob);

            {
                // Hide the tracking mob when a visual projectile entity exists
                if (visualEntityId != null) {
                    mob.setInvisible(true);
                    mob.setSilent(true);
                    // Scale to near-zero so fire/particle effects don't render
                    var scaleAttr = mob.getAttributeInstance(
                        SCALE_ATTR);
                    if (scaleAttr != null) scaleAttr.setBaseValue(0.01);
                }
                CombatEntity ce = new CombatEntity(
                    mob.getId(), sp.entityTypeId(), pos,
                    sp.hp(), sp.atk(), sp.def(), 1
                );
                ce.setMobEntity(mob);
                // Seeker types home in on the player; everything else flies straight.
                boolean seeking = switch (sp.projectileType()) {
                    case "shulker_bullet", "grave_skull", "scarab" -> true;
                    default -> false;
                };
                ce.setAiOverrideKey(seeking ? "seeking_projectile" : "projectile");
                ce.setProjectile(true);
                ce.setProjectileDirX(dir[0]);
                ce.setProjectileDirZ(dir[1]);
                ce.setProjectileType(sp.projectileType());
                ce.setProjectileOwnerId(currentEnemy != null ? currentEnemy.getEntityId() : -1);
                ce.setVisualProjectileEntityId(spawnedVisualId);
                // Display name based on projectile type
                if ("ghast_fireball".equals(sp.projectileType())) {
                    ce.setBossDisplayName("Fireball");
                } else if ("wither_skull".equals(sp.projectileType())) {
                    ce.setBossDisplayName("Wither Skull");
                } else if ("shulker_bullet".equals(sp.projectileType())) {
                    ce.setBossDisplayName("Shulker Bullet");
                } else if ("grave_skull".equals(sp.projectileType())) {
                    ce.setBossDisplayName("Grave Skull");
                } else if ("scarab".equals(sp.projectileType())) {
                    ce.setBossDisplayName("Scarab");
                }
                enemies.add(ce);
                arena.placeEntity(ce);
                spawned++;

                // Register with boss AI for tracking
                if (currentEnemy != null && currentEnemy.isBoss()) {
                    EnemyAI bAi = resolveAi(currentEnemy);
                    if (bAi instanceof com.crackedgames.craftics.combat.ai.boss.BossAI bossAi) {
                        bossAi.registerSpawnedProjectile(ce.getEntityId());
                    }
                }

                // Themed projectile spawn particles
                if ("ghast_fireball".equals(sp.projectileType())) {
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.FLAME,
                        spawnPos.getX() + 0.5, spawnPos.getY() + 0.8, spawnPos.getZ() + 0.5,
                        10, 0.3, 0.5, 0.3, 0.03);
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.LAVA,
                        spawnPos.getX() + 0.5, spawnPos.getY() + 0.5, spawnPos.getZ() + 0.5,
                        5, 0.2, 0.3, 0.2, 0.0);
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE,
                        spawnPos.getX() + 0.5, spawnPos.getY() + 1.0, spawnPos.getZ() + 0.5,
                        4, 0.15, 0.3, 0.15, 0.01);
                } else if ("wither_skull".equals(sp.projectileType())
                        || "grave_skull".equals(sp.projectileType())) {
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL,
                        spawnPos.getX() + 0.5, spawnPos.getY() + 0.8, spawnPos.getZ() + 0.5,
                        8, 0.3, 0.5, 0.3, 0.03);
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME,
                        spawnPos.getX() + 0.5, spawnPos.getY() + 0.5, spawnPos.getZ() + 0.5,
                        5, 0.2, 0.3, 0.2, 0.02);
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                        spawnPos.getX() + 0.5, spawnPos.getY() + 1.0, spawnPos.getZ() + 0.5,
                        4, 0.15, 0.3, 0.15, 0.01);
                } else if ("shulker_bullet".equals(sp.projectileType())) {
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD,
                        spawnPos.getX() + 0.5, spawnPos.getY() + 0.8, spawnPos.getZ() + 0.5,
                        10, 0.25, 0.4, 0.25, 0.03);
                    world.playSound(null, spawnPos,
                        net.minecraft.sound.SoundEvents.ENTITY_SHULKER_SHOOT,
                        net.minecraft.sound.SoundCategory.HOSTILE, 1.0f, 1.0f);
                } else {
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.POOF,
                        spawnPos.getX() + 0.5, spawnPos.getY() + 0.5, spawnPos.getZ() + 0.5,
                        6, 0.3, 0.3, 0.3, 0.02);
                }
            }
        }
        if (spawned > 0) {
            String name = switch (sp.projectileType()) {
                case "ghast_fireball" -> "fireball";
                case "shulker_bullet" -> "shulker bullet";
                case "grave_skull" -> "grave skull";
                case "scarab" -> "scarab";
                default -> "wither skull";
            };
            sendMessage("§5  " + spawned + " " + name + "(s) launched!");
        }
    }

    /**
     * Sync the visual projectile entity to follow the invisible tracking mob.
     * Uses the stored entity ID for direct lookup -no bounding box search.
     */
    private void syncVisualProjectile(CombatEntity ce, double x, double y, double z) {
        int visualId = ce.getVisualProjectileEntityId();
        if (visualId == -1) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        net.minecraft.entity.Entity visual = world.getEntityById(visualId);
        if (visual != null) {
            visual.refreshPositionAndAngles(x, y, z, visual.getYaw(), visual.getPitch());
        }
    }

    /**
     * Kill the visual projectile entity when the combat projectile is destroyed.
     */
    private void killVisualProjectileNear(CombatEntity ce) {
        int visualId = ce.getVisualProjectileEntityId();
        if (visualId == -1 || player == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        net.minecraft.entity.Entity visual = world.getEntityById(visualId);
        if (visual != null) {
            visual.discard();
        }
    }

    /** Party members standing within {@code radius} tiles (Chebyshev box) of
     *  {@code center}; falls back to the tracked player solo. Offline and dead
     *  members are skipped. radius 0 = exact tile only. */
    private java.util.List<ServerPlayerEntity> partyVictimsNear(GridPos center, int radius) {
        java.util.List<ServerPlayerEntity> victims = new java.util.ArrayList<>();
        if (partyPlayers.size() > 1) {
            for (ServerPlayerEntity member : partyPlayers) {
                if (member == null || member.isRemoved() || member.isDisconnected()) continue;
                if (deadPartyMembers.contains(member.getUuid())) continue;
                GridPos mPos = gridPosOf(member);
                if (Math.abs(mPos.x() - center.x()) <= radius
                    && Math.abs(mPos.z() - center.z()) <= radius) {
                    victims.add(member);
                }
            }
        } else {
            GridPos playerGridPos = arena.getPlayerGridPos();
            if (Math.abs(playerGridPos.x() - center.x()) <= radius
                && Math.abs(playerGridPos.z() - center.z()) <= radius) {
                victims.add(player);
            }
        }
        return victims;
    }

    /** Per-victim messaging/effects hook for {@link #damagePartyVictims}. Runs inside
     *  the this.player swap, so addEffectHooked/getPlayerHp target the victim. */
    private interface PartyHitCallback {
        void accept(ServerPlayerEntity victim, int actualDamage, boolean swapped);
    }

    /**
     * Damage every listed party member, routing each through the this.player swap so
     * their own dodge/armor/effects/death handling apply (mirrors resolveAreaAttack's
     * loop, shared by the projectile impact types).
     *
     * @return true when a death ended combat (game over) -the caller must stop
     *         touching combat state immediately.
     */
    private boolean damagePartyVictims(java.util.List<ServerPlayerEntity> victims, int damage,
                                       PartyHitCallback afterDamage) {
        return damagePartyVictims(victims, damage, null, afterDamage);
    }

    /**
     * Variant of {@link #damagePartyVictims(java.util.List, int, PartyHitCallback)} that
     * preserves attacker context for damage routing (boss caps, dodge math, and type hooks).
     */
    private boolean damagePartyVictims(java.util.List<ServerPlayerEntity> victims, int damage,
                                       CombatEntity attacker,
                                       PartyHitCallback afterDamage) {
        // Everything routed through here is an AREA effect, and riders wear those personally
        // rather than hiding behind the mount. The mount is caught too - see the block after
        // the loop.
        boolean wasResolvingArea = resolvingAreaDamage;
        resolvingAreaDamage = true;
        try {
        for (ServerPlayerEntity victim : victims) {
            ServerPlayerEntity savedPlayer = this.player;
            boolean swapped = victim != savedPlayer;
            if (swapped) { this.player = victim; retargetEffectsToCurrentPlayer(); }
            boolean victimDied = false;
            try {
                int actual = damagePlayer(damage, attacker);
                afterDamage.accept(victim, actual, swapped);
                if (getPlayerHp() <= 0) {
                    victimDied = true;
                    handlePlayerDeathOrGameOver();
                    if (partyPlayers.size() <= 1 || !active) return true;
                }
            } finally {
                if (!victimDied) { this.player = savedPlayer; retargetEffectsToCurrentPlayer(); }
            }
        }
        // The mount is standing in the blast too. Caught once for the whole area effect, not
        // once per rider, so a camel carrying four people is not hit four times by one bomb.
        if (playerMounted && mountMob != null && damage > 0) {
            CombatEntity mount = findMountEntity();
            if (mount != null && mount.isAlive()) {
                int dealt = mount.takeDamage(damage);
                sendMessage("§6" + mount.getDisplayName() + " is caught in the blast for " + dealt + "!");
                checkAndHandleDeath(mount);
            }
        }
        return false;
        } finally {
            resolvingAreaDamage = wasResolvingArea;
        }
    }

    /** The mount's grid entity, matched by the ridden mob's id. Null if it is gone. */
    private CombatEntity findMountEntity() {
        if (mountMob == null) return null;
        for (CombatEntity e : enemies) {
            if (e.getEntityId() == mountMob.getId()) return e;
        }
        return null;
    }

    /** ProjectileAI is handed one target tile (the closest member), so in co-op its
     *  flight path can sail through other party members. Clip the returned move at the
     *  first path tile any living member is standing on and impact there instead. */
    private EnemyAction.ProjectileMove clipProjectileAtAnyMember(EnemyAction.ProjectileMove pm) {
        if (pm.path().isEmpty() || partyPlayers.size() <= 1 || arena == null) return pm;
        refreshAllPlayerGridPositions();
        java.util.List<GridPos> allPlayers = arena.getAllPlayerGridPositions();
        for (int i = 0; i < pm.path().size(); i++) {
            GridPos step = pm.path().get(i);
            if (allPlayers.contains(step)) {
                if (pm.impacts() && step.equals(pm.impactPos())) return pm; // already ends here
                return new EnemyAction.ProjectileMove(
                    new java.util.ArrayList<>(pm.path().subList(0, i + 1)), true, step);
            }
        }
        return pm;
    }

    /**
     * Damage a reflected fireball deals to a boss. Flat, not a share of max HP: this is the
     * counterplay against a boss that cannot be reached on foot, and it has to stay worth the
     * setup no matter how far the biome scaling and the HP multiplier have pushed the boss.
     */
    private static final int REFLECTED_FIREBALL_BOSS_DAMAGE = 50;

    /**
     * Resolve a projectile impact -AOE explosion for fireballs, wither effect for skulls.
     */
    private void resolveProjectileImpact(CombatEntity projectile, GridPos impactPos) {
        if (!projectile.isProjectile() || !projectile.isAlive()) return;

        String type = projectile.getProjectileType();
        int damage = projectile.getAttackPower();
        boolean redirected = projectile.isProjectileRedirected();
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        GridPos effectCenter = impactPos != null ? impactPos : projectile.getGridPos();
        BlockPos bp = arena.gridToBlockPos(effectCenter);

        if ("ghast_fireball".equals(type)) {
            sendMessage("§c\uD83D\uDD25 Fireball explodes!");
            world.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION,
                bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5, 3, 0.3, 0.3, 0.3, 0.0);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.FLAME,
                bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5, 15, 0.8, 0.8, 0.8, 0.04);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.LAVA,
                bp.getX() + 0.5, bp.getY() + 0.5, bp.getZ() + 0.5, 8, 0.5, 0.3, 0.5, 0.0);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                bp.getX() + 0.5, bp.getY() + 1.5, bp.getZ() + 0.5, 8, 0.6, 0.8, 0.6, 0.02);
            player.getWorld().playSound(null, bp,
                net.minecraft.sound.SoundEvents.ENTITY_GENERIC_EXPLODE.value(),
                net.minecraft.sound.SoundCategory.HOSTILE, 1.0f, 1.0f);

            int aoeRadius = 1;

            // Damage EVERY party member in the AOE, not just the leader-tracked player
            // (skip for redirected fireballs -they're heading away)
            if (!redirected) {
                boolean gameOver = damagePartyVictims(partyVictimsNear(effectCenter, aoeRadius),
                    damage, (victim, actual, swapped) -> {
                        sendMessage("§c  Explosion hit " + (swapped ? victim.getName().getString() : "you")
                            + " for " + actual + " damage! (HP: " + getPlayerHp() + ")");
                        if (!combatEffects.hasFireResistance()) {
                            addEffectHooked(CombatEffects.EffectType.BURNING, 2, 0);
                            sendMessage("§6  " + (swapped ? victim.getName().getString() + " is" : "You're")
                                + " burning for 2 turns!");
                        }
                    });
                if (gameOver) return;
            }

            // Damage all enemies in AOE (always -this is how redirected fireballs damage the boss)
            for (CombatEntity e : new ArrayList<>(enemies)) {
                if (e == projectile || !e.isAlive()) continue;

                // Background bosses (Wailing Revenant) occupy many arena tiles via
                // the occupant map, but their gridPos/size only cover one -so
                // minDistanceTo misreports distance and reflected fireballs can
                // miss them entirely. For background bosses, check the occupant
                // map across the AoE footprint instead.
                boolean inAoe;
                if (e.isBackgroundBoss()) {
                    inAoe = false;
                    outer:
                    for (int dx = -aoeRadius; dx <= aoeRadius; dx++) {
                        for (int dz = -aoeRadius; dz <= aoeRadius; dz++) {
                            GridPos check = new GridPos(effectCenter.x() + dx, effectCenter.z() + dz);
                            if (arena.getOccupant(check) == e) { inAoe = true; break outer; }
                        }
                    }
                } else {
                    inAoe = e.minDistanceTo(effectCenter) <= aoeRadius;
                }

                if (inAoe) {
                    // A reflected fireball that strikes a regular ghast enemy
                    // detonates it outright -its own ammunition turned back on it.
                    // Bosses (Wailing Revenant included) are explicitly excluded:
                    // they only ever take the scaled chip damage below.
                    if (redirected && !e.isBoss()
                            && "minecraft:ghast".equals(e.getEntityTypeId())) {
                        int dealt = e.takeDamage(e.getMaxHp());
                        sendMessage("§6§l  Reflected fireball detonates " + e.getDisplayName() + "!");
                        checkAndHandleDeath(e);
                        continue;
                    }
                    // A reflected fireball is the intended answer to a boss you cannot walk up
                    // to, so it hits like one. A flat number rather than a fraction of max HP:
                    // boss health scales with biome progress and the HP multiplier, so 1/20 of
                    // max meant the counterplay got weaker in exactly the fights where it was
                    // the only counterplay, and the reflect never felt worth the setup.
                    int fireDmg = (redirected && e.isBoss()) ? REFLECTED_FIREBALL_BOSS_DAMAGE : damage;
                    int dealt = e.takeDamage(fireDmg);
                    if (redirected && e.isBoss()) {
                        sendMessage("§6§l  Reflected fireball slams into " + e.getDisplayName() + " for " + dealt + "!");
                    } else {
                        sendMessage("§6  Explosion hits " + e.getDisplayName() + " for " + dealt + "!");
                    }
                    checkAndHandleDeath(e);
                }
            }
        } else if ("wither_skull".equals(type)) {
            sendMessage("§8\u2620 Wither Skull impacts!");
            world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL,
                bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5, 12, 0.4, 0.6, 0.4, 0.03);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME,
                bp.getX() + 0.5, bp.getY() + 0.8, bp.getZ() + 0.5, 8, 0.3, 0.4, 0.3, 0.02);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                bp.getX() + 0.5, bp.getY() + 1.3, bp.getZ() + 0.5, 6, 0.4, 0.5, 0.4, 0.01);

            // Damage + wither to whichever party member is on the impact tile
            if (damagePartyVictims(partyVictimsNear(effectCenter, 0), damage,
                    (victim, actual, swapped) -> {
                        sendMessage("§8  Wither Skull hits " + (swapped ? victim.getName().getString() : "you")
                            + " for " + actual + " damage!");
                        addEffectHooked(CombatEffects.EffectType.WITHER, 3, 0);
                        sendMessage("§8  " + (swapped ? victim.getName().getString() + " is withered" : "Withered")
                            + " for 3 turns! (damage ramps up)");
                    })) {
                return;
            }
        } else if ("shulker_bullet".equals(type)) {
            world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD,
                bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5, 12, 0.35, 0.5, 0.35, 0.04);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.ELECTRIC_SPARK,
                bp.getX() + 0.5, bp.getY() + 0.8, bp.getZ() + 0.5, 6, 0.25, 0.35, 0.25, 0.02);
            player.getWorld().playSound(null, bp,
                net.minecraft.sound.SoundEvents.ENTITY_SHULKER_BULLET_HIT,
                net.minecraft.sound.SoundCategory.HOSTILE, 1.0f, 1.0f);

            if (damagePartyVictims(partyVictimsNear(effectCenter, 0), damage,
                    (victim, actual, swapped) -> {
                        sendMessage("§d✦ Shulker bullet hits " + (swapped ? victim.getName().getString() : "you")
                            + " for " + actual + " damage!");
                        addEffectHooked(CombatEffects.EffectType.LEVITATION, 2, 0);
                        sendMessage("§d  " + (swapped ? victim.getName().getString() + " floats" : "You float")
                            + " helplessly - Levitation for 2 turns!");
                    })) {
                return;
            }
        } else if ("grave_skull".equals(type)) {
            world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL,
                bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5, 10, 0.35, 0.5, 0.35, 0.03);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                bp.getX() + 0.5, bp.getY() + 0.8, bp.getZ() + 0.5, 5, 0.25, 0.35, 0.25, 0.01);
            player.getWorld().playSound(null, bp,
                net.minecraft.sound.SoundEvents.ENTITY_WITHER_SKELETON_HURT,
                net.minecraft.sound.SoundCategory.HOSTILE, 0.8f, 0.7f);

            if (damagePartyVictims(partyVictimsNear(effectCenter, 0), damage,
                    (victim, actual, swapped) -> {
                        sendMessage("§8☠ Grave Skull bites " + (swapped ? victim.getName().getString() : "you")
                            + " for " + actual + " damage!");
                        addEffectHooked(CombatEffects.EffectType.WITHER, 2, 0);
                        sendMessage("§8  " + (swapped ? victim.getName().getString() + " is withered" : "Withered")
                            + " for 2 turns!");
                    })) {
                return;
            }
        } else if ("scarab".equals(type)) {
            world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                bp.getX() + 0.5, bp.getY() + 0.8, bp.getZ() + 0.5, 8, 0.3, 0.3, 0.3, 0.05);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.ITEM_SLIME,
                bp.getX() + 0.5, bp.getY() + 0.6, bp.getZ() + 0.5, 6, 0.25, 0.25, 0.25, 0.02);
            player.getWorld().playSound(null, bp,
                net.minecraft.sound.SoundEvents.ENTITY_SILVERFISH_DEATH,
                net.minecraft.sound.SoundCategory.HOSTILE, 0.9f, 0.8f);

            if (damagePartyVictims(partyVictimsNear(effectCenter, 0), damage,
                    (victim, actual, swapped) -> {
                        sendMessage("§2⚘ Scarab burrows into " + (swapped ? victim.getName().getString() : "you")
                            + " for " + actual + " damage!");
                        addEffectHooked(CombatEffects.EffectType.POISON, 2, 0);
                        sendMessage("§2  " + (swapped ? victim.getName().getString() + " is poisoned" : "Poisoned")
                            + " for 2 turns!");
                    })) {
                return;
            }
        }

        // Kill the projectile entity
        killEnemy(projectile);
    }

    /**
     * Resolve an AoE attack centered on a tile.
     */
    private void resolveAreaAttack(EnemyAction.AreaAttack aa) {
        // Conduction carries NO center - by design. The strike resolves on the marked
        // combatant's LIVE position at this moment (the mark id rides in the tag), never
        // on the tile the mark was cast from. This branch must run before anything below
        // touches aa.center(), which is null here.
        if (aa.effectName() != null && aa.effectName().startsWith("conduction:")) {
            resolveConductionChain(
                Integer.parseInt(aa.effectName().substring("conduction:".length())),
                aa.damage());
            return;
        }

        GridPos center = aa.center();
        int radius = aa.radius();
        int damage = aa.damage();
        ServerWorld world = (ServerWorld) player.getEntityWorld();

        // Boss-specific particles based on the attack effect
        BlockPos centerBlock = arena.gridToBlockPos(center);
        double cx = centerBlock.getX() + 0.5, cy = centerBlock.getY() + 1.0, cz = centerBlock.getZ() + 0.5;
        double spread = Math.max(0.5, radius * 0.5);
        spawnAreaAttackParticles(world, aa.effectName(), cx, cy, cz, spread, radius);

        // Sandstorm Pharaoh: "plant_mine" is not an instant AoE -it drops a
        // persistent, lightly-telegraphed step-trigger trap on the tile. Register it
        // and return before the (radius-0, damage-0) victim loop runs.
        if ("plant_mine".equals(aa.effectName())) {
            registerSandMine(center);
            return;
        }

        // Hit EVERY party member inside the AoE box, not just the host. The boss
        // AI centers the blast on the closest member, so in co-op the targeted
        // teammate (if not the leader-tracked player) previously took zero damage
        // while the wrong player got hit. damagePartyVictims routes each member via
        // the this.player swap so their dodge/armor/effects/death handling apply.
        boolean gameOverFromArea = damagePartyVictims(partyVictimsNear(center, radius),
            damage, currentEnemy, (victim, actual, swapped) -> {
                sendMessage("§c  Area hit " + (swapped ? victim.getName().getString() : "you")
                    + " for " + actual + " damage! (HP: " + getPlayerHp() + ")");
                // Apply named effects to this victim
                if (aa.effectName() != null) {
                    applyBossAreaEffect(aa.effectName());
                }
            });
        if (gameOverFromArea) return;

        // Damage enemy mobs in the area (friendly fire for bosses)
        if (CrafticsMod.CONFIG.friendlyFireEnabled()) {
            for (CombatEntity e : new ArrayList<>(enemies)) {
                if (e == currentEnemy || !e.isAlive()) continue;
                if (Math.abs(e.getGridPos().x() - center.x()) <= radius
                    && Math.abs(e.getGridPos().z() - center.z()) <= radius) {
                    int dealt = e.takeDamage(damage);
                    sendMessage("§6  Blast hits " + e.getDisplayName() + " for " + dealt + "!");
                    checkAndHandleDeath(e);
                }
            }
        }

        // Special scripted effect: prime a TNT charge on this tile.
        if ("hollow_tnt_prime".equals(aa.effectName())) {
            // "2-round fuse" was counting the fuse's own decrements, not the window the player
            // gets. The charge is primed during the enemy phase, the round transition
            // immediately after takes it to 1, and it blows on the NEXT one - so what the
            // player actually has is one turn. Say that.
            primePendingTnt(center,
                "§6  The Hollow King primes a TNT cache! §c§lGet off it before your turn ends!", 2);
        }
    }

    /**
     * Resolve an AoE attack over an explicit tile list (a multi-zone volley whose splash
     * footprints overlap, e.g. Trident Storm).
     *
     * <p>The contract that makes this different from {@link #resolveAreaAttack}: every victim
     * is damaged AT MOST ONCE, no matter how many of the volley's zones cover them. The old
     * shape (one AreaAttack per zone inside a CompositeAction) resolved each zone
     * independently, so standing on a seam took the hit once per overlapping zone while the
     * telegraph painted every covered tile the same. Membership in the tile set is the whole
     * test here, so overlap cannot stack by construction.
     */
    private void resolveTileAreaAttack(EnemyAction.TileAreaAttack ta) {
        if (ta.tiles() == null || ta.tiles().isEmpty()) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();

        // Distinct tile set: the damage test. A caller that passed duplicates still cannot
        // make a tile hit twice.
        java.util.Set<GridPos> impact = new java.util.LinkedHashSet<>(ta.tiles());

        // Particles are centred for looks only; the centre never selects victims.
        GridPos vfxCenter = ta.center() != null ? ta.center() : ta.tiles().get(0);
        BlockPos centerBlock = arena.gridToBlockPos(vfxCenter);
        spawnAreaAttackParticles(world, ta.effectName(),
            centerBlock.getX() + 0.5, centerBlock.getY() + 1.0, centerBlock.getZ() + 0.5, 1.5, 1);

        // Each party member standing anywhere in the union is hit exactly once.
        java.util.List<ServerPlayerEntity> victims = new java.util.ArrayList<>();
        if (partyPlayers.size() > 1) {
            for (ServerPlayerEntity member : partyPlayers) {
                if (member == null || member.isRemoved() || member.isDisconnected()) continue;
                if (deadPartyMembers.contains(member.getUuid())) continue;
                if (impact.contains(gridPosOf(member))) victims.add(member);
            }
        } else if (impact.contains(arena.getPlayerGridPos())) {
            victims.add(player);
        }

        boolean gameOver = damagePartyVictims(victims, ta.damage(), currentEnemy, (victim, actual, swapped) -> {
            sendMessage("§c  Area hit " + (swapped ? victim.getName().getString() : "you")
                + " for " + actual + " damage! (HP: " + getPlayerHp() + ")");
            if (ta.effectName() != null) {
                applyBossAreaEffect(ta.effectName());
            }
        });
        if (gameOver) return;

        // Friendly fire, same once-per-entity rule: a multi-tile mob standing across two
        // zones is one victim, not one per covered tile.
        if (CrafticsMod.CONFIG.friendlyFireEnabled()) {
            for (CombatEntity e : new ArrayList<>(enemies)) {
                if (e == currentEnemy || !e.isAlive()) continue;
                if (!entityTouchesAnyTile(e, impact)) continue;
                int dealt = e.takeDamage(ta.damage());
                sendMessage("§6  Blast hits " + e.getDisplayName() + " for " + dealt + "!");
                checkAndHandleDeath(e);
            }
        }

        // The Warden's fissure: the damage above is incidental, the HOLE is the attack. Carve
        // the struck tiles into a permanent void so the arena is genuinely smaller from here on.
        if ("fissure".equals(ta.effectName())) {
            carveFissure(impact);
        }

        // The Hollow King's collapse is SEEN coming down, on every single tile it covers.
        // A ceiling failing is the one attack in the game where the tile list IS the spectacle,
        // and painting it red and dealing damage was never going to carry that.
        if ("hollow_collapse".equals(ta.effectName())) {
            rainCollapseDebris(world, impact);
        }
    }

    /**
     * Tear the listed tiles out of the arena floor for good.
     *
     * <p>Built out of the same shape a pickaxe-dug void has - floor and sub-floor cleared, black
     * concrete capping the bottom - so everything that already understands a pit understands
     * this one: the tile scan, the fall-death check, enemy pathing, and the client's own
     * walkability read all agree without special cases.
     *
     * <p>Anything standing on a tile as it opens is dropped by the normal fall handling rather
     * than being killed here, so ledgegrip, totems and the survivor rescue all still get their
     * say. Bosses vault gaps (see {@code Pathfinding#canVaultGaps}), so a fissure narrows the
     * player's options without walling the boss off from the fight.
     */
    private void carveFissure(java.util.Set<GridPos> tiles) {
        if (arena == null || tiles.isEmpty()) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        for (GridPos pos : tiles) {
            if (!arena.isInBounds(pos)) continue;
            GridTile tile = arena.getTile(pos);
            if (tile == null || tile.getType() == TileType.VOID) continue;

            BlockPos overlay = arena.gridToBlockPos(pos);   // floorY+1
            BlockPos floor = overlay.down();                // floorY
            BlockPos pitFloor = floor.down();               // floorY-1
            BlockPos bottom = pitFloor.down();              // floorY-2, capped like every pit
            setArenaBlock(world, overlay, net.minecraft.block.Blocks.AIR, false);
            setArenaBlock(world, floor, net.minecraft.block.Blocks.AIR, false);
            setArenaBlock(world, pitFloor, net.minecraft.block.Blocks.AIR, false);
            setArenaBlock(world, bottom, net.minecraft.block.Blocks.BLACK_CONCRETE, false);

            tile.setType(TileType.VOID);
            tile.setBlockType(net.minecraft.block.Blocks.AIR);

            // Noted for the collapse: the ceiling starts filling this tile back in from the
            // next round on (see tickFissureDebris).
            fissureDebris.put(pos, 0);

            world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                floor.getX() + 0.5, floor.getY(), floor.getZ() + 0.5, 8, 0.3, 0.4, 0.3, 0.02);
        }
        world.playSound(null, arena.gridToBlockPos(tiles.iterator().next()),
            net.minecraft.sound.SoundEvents.BLOCK_DEEPSLATE_BREAK,
            net.minecraft.sound.SoundCategory.BLOCKS, 1.4f, 0.4f);
        sendMessage("§8§lThe ground tears open!");
        sendSync();
        refreshHighlights();
    }

    // ── Sonic boom mark hunt ─────────────────────────────────────────────────

    /** Turns of Marked / Darkness / Blindness a sonic boom leaves on whoever it catches. */
    private static final int SONIC_MARK_TURNS = 4;
    /** Speed the Warden gains while it has someone marked to run down. */
    private static final int WARDEN_HUNT_SPEED = 5;

    /** Players a sonic boom has marked. Emptied as the marks lapse. */
    private final Set<java.util.UUID> sonicMarkedPlayers = new HashSet<>();
    /** Whether the hunt speed bonus is currently on the Warden, so it is added once and removed once. */
    private boolean wardenHuntSpeedApplied = false;

    /**
     * Keep the Warden pointed at whoever its boom marked.
     *
     * <p>A mark is a lead, not a debuff it can forget: while one is live the Warden abandons
     * whatever vibration it was chasing, runs at the marked player specifically, and moves
     * faster doing it. When the last mark lapses the lead goes cold - the bonus comes off and
     * it drops back to hunting by sound like normal.
     */
    private void tickWardenMarkHunt() {
        if (arena == null) return;

        // Retire marks that have run out (or players who have left the fight).
        sonicMarkedPlayers.removeIf(uuid -> {
            CombatEffects fx = playerCombatEffects.get(uuid);
            return fx == null || !fx.hasEffect(CombatEffects.EffectType.MARKED)
                || deadPartyMembers.contains(uuid);
        });

        CombatEntity warden = null;
        com.crackedgames.craftics.combat.ai.WardenAI wardenAi = null;
        for (CombatEntity e : enemies) {
            if (!e.isAlive()) continue;
            if (resolveAi(e) instanceof com.crackedgames.craftics.combat.ai.WardenAI w) {
                warden = e;
                wardenAi = w;
                break;
            }
        }
        if (warden == null) { wardenHuntSpeedApplied = false; return; }

        // The marked player's LIVE tile, refreshed every round - the lead follows them as
        // they run, which is the whole point of being marked.
        GridPos hunted = null;
        for (ServerPlayerEntity member : allCombatPlayers()) {
            if (member == null || !sonicMarkedPlayers.contains(member.getUuid())) continue;
            hunted = gridPosOf(member);
            if (hunted != null) break;
        }

        wardenAi.setHuntedTile(hunted);
        boolean shouldBoost = hunted != null;
        if (shouldBoost && !wardenHuntSpeedApplied) {
            warden.setSpeedBonus(warden.getSpeedBonus() + WARDEN_HUNT_SPEED);
            wardenHuntSpeedApplied = true;
            sendMessage("§3The Warden has your scent - it moves faster!");
        } else if (!shouldBoost && wardenHuntSpeedApplied) {
            warden.setSpeedBonus(warden.getSpeedBonus() - WARDEN_HUNT_SPEED);
            wardenHuntSpeedApplied = false;
            sendMessage("§7The Warden loses the scent.");
        }
    }

    // ── Fissure debris ───────────────────────────────────────────────────────
    // The hole the Warden tears is not permanent. The ceiling of the Deep Dark keeps
    // shedding into it: every round, a few blocks of cobble crash down on random tiles of
    // the crack until the whole thing is filled back in. Two loads fill a tile - the first
    // piles up enough rubble to stand on, the second brings it level with the floor - so the
    // arena repairs itself over several rounds instead of being one turn poorer forever.
    //
    // Standing in a half-filled crack is a gamble, not a shortcut: a load that lands on
    // anything, player or mob, hits it for DEBRIS_DAMAGE.

    /** Cobble loads already dropped per fissure tile. Two fills the hole and retires it. */
    private final java.util.Map<GridPos, Integer> fissureDebris = new java.util.HashMap<>();

    /** Loads that fill one tile: rubble to stand on, then floor. */
    private static final int DEBRIS_TO_FILL = 2;
    /** Damage a falling load deals to whatever is standing where it lands. */
    private static final int DEBRIS_DAMAGE = 10;
    /** Loads that come down per round, inclusive range. */
    private static final int DEBRIS_MIN_PER_TURN = 1;
    private static final int DEBRIS_MAX_PER_TURN = 5;

    /** What a solid drop does to whoever is standing where it lands. */
    private static final int CRUSH_DAMAGE = 6;

    // ── Support pillars ──────────────────────────────────────────────────────

    /**
     * The difficulty this fight is being played at.
     *
     * <p>Resolved live rather than snapshotted at the start of combat, so changing it takes
     * effect straight away. That is safe because of WHERE the two levers land: the HP
     * multiplier is read once per mob as it spawns, so nothing already on the field changes
     * size underneath the player, and the damage bonus is read per hit, which is the only part
     * that could sensibly change mid-fight anyway. The command that sets it refuses while a
     * fight is running regardless.
     *
     * <p>Read from the ISLAND OWNER, using the same owner id the per-level HP scaling already
     * uses - in a party the island being played is the leader's, so the leader's setting is the
     * one that counts, and the two settings cannot disagree about whose island it is.
     */
    private CrafticsDifficulty activeDifficulty() {
        if (player == null || !(player.getEntityWorld() instanceof ServerWorld sw)) {
            return CrafticsDifficulty.EASY;
        }
        java.util.UUID owner = worldOwnerUuid != null ? worldOwnerUuid
            : (leaderUuid != null ? leaderUuid : player.getUuid());
        return CrafticsDifficulty.of(sw, owner);
    }

    /** Tiles carrying a standing support pillar. The Hollow King's armour, and the shape of
     *  the collapse he is loading. */
    private final java.util.Set<GridPos> bossPillars = new java.util.LinkedHashSet<>();

    /** Blocks above the floor. Tall enough to read as a pit prop from across the arena rather
     *  than as a kerb, which is what a one-block obstacle looks like from the fight camera. */
    private static final int PILLAR_HEIGHT = 3;

    /** A mine timber. Wood in a stone room reads instantly as something someone PUT there,
     *  which is the whole point: these are the boss's work, not the arena's. */
    private static final net.minecraft.block.Block PILLAR_BLOCK = Blocks.STRIPPED_OAK_LOG;

    /**
     * Cosmetic falling blocks must never touch down, and these two numbers are what guarantee
     * it.
     *
     * <p>A {@code FallingBlockEntity} that lands turns into a REAL block, and this arena is
     * read back from its blocks when the level is revisited - so one that gets through does not
     * just look wrong, it is welded in. The tracker discards them mid-air on a tick boundary,
     * which means the drop has to be short enough that the discard always wins the race. At
     * -0.4 initial velocity plus vanilla gravity, five ticks covers roughly 2.6 blocks, so
     * starting seven up leaves better than four blocks of clearance over anything in the arena
     * - pillars included.
     */
    private static final double DEBRIS_DROP_HEIGHT = 5.0;
    /** Long enough to reach the floor from that height; the tracker adopts what lands. */
    private static final int DEBRIS_LIFETIME = 40;

    /** Turns a landed lump of collapse rubble stays on the floor before it is cleared. */
    private static final int RUBBLE_TURNS = 3;

    /** Tiles rained on by a collapse, and how many turns their rubble has left. */
    private final java.util.Map<GridPos, Integer> collapseRubble = new java.util.LinkedHashMap<>();

    /**
     * Age out landed collapse rubble.
     *
     * <p>The blocks are real - they are meant to be, a collapse that leaves nothing behind reads
     * as a light show - but real and permanent are different things. Left alone they would
     * silt the arena up over a long fight and, worse, still be sitting there when the level is
     * scanned back on a revisit. Clearing goes through the arena's own VFX-obstacle removal, so
     * the tile type it was covering comes back with it.
     */
    private void tickCollapseRubble() {
        if (arena == null || player == null || collapseRubble.isEmpty()) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        var it = collapseRubble.entrySet().iterator();
        while (it.hasNext()) {
            var entry = it.next();
            int left = entry.getValue() - 1;
            if (left > 0) {
                entry.setValue(left);
                continue;
            }
            arena.clearVfxObstacle(world, entry.getKey());
            it.remove();
        }
    }

    /**
     * Drop real, tumbling blocks onto every tile of a collapse.
     *
     * <p>Through {@link com.crackedgames.craftics.vfx.VfxBlockTracker}, which is the machinery
     * that already knows how to have a falling block be PURELY cosmetic. That distinction is the
     * whole reason not to hand-roll this: a vanilla {@code FallingBlockEntity} turns into a real
     * block wherever it lands, so raining sixty of them over an arena floor would repave it in
     * stone and, because arenas are rescanned from their blocks on revisit, bake that in. The
     * tracker discards each one mid-air with a burst before it can touch down, and purges
     * anything outstanding at {@code endCombat}.
     *
     * <p>Launched from a low ceiling with a stagger, so they arrive across a few ticks rather
     * than as one synchronised sheet - a roof gives way, it does not deploy.
     */
    private void rainCollapseDebris(ServerWorld world, java.util.Collection<GridPos> tiles) {
        var tracker = com.crackedgames.craftics.vfx.VfxBlockTracker.of(world);
        var state = getBiomeFloorBlock().getDefaultState();
        for (GridPos pos : tiles) {
            if (!arena.isInBounds(pos)) continue;
            // Rubble only falls where there is floor to land ON. A rock dropped over a pillar
            // or a wall touches down three or four blocks up, and the tracker only ever adopts
            // a block that settles at the arena's own surface height - so anything landing
            // higher becomes a real block nobody owns, perched on top of the beams and left
            // there when the fight ends. Dropping only over open ground removes the case.
            if (bossPillars.contains(pos)) continue;
            GridTile floorTile = arena.getTile(pos);
            if (floorTile == null || !floorTile.isWalkable()) continue;

            BlockPos floor = tileFloorPos(pos);
            double jitterX = (combatRng.nextDouble() - 0.5) * 0.4;
            double jitterZ = (combatRng.nextDouble() - 0.5) * 0.4;
            double height = DEBRIS_DROP_HEIGHT + combatRng.nextDouble() * 1.5;
            // The arena is passed so the tracker ADOPTS whatever lands: it marks the tile as a
            // VFX obstacle, which is the arena's existing "a block is sitting here" bookkeeping
            // and is torn down with everything else at the end of the fight.
            tracker.launchInto(world,
                new net.minecraft.util.math.Vec3d(
                    floor.getX() + 0.5 + jitterX, floor.getY() + height, floor.getZ() + 0.5 + jitterZ),
                new net.minecraft.util.math.Vec3d(0, -0.4, 0),
                state, DEBRIS_LIFETIME, arena);
            collapseRubble.put(pos, RUBBLE_TURNS);
        }
        if (!tiles.isEmpty()) {
            world.playSound(null, arena.gridToBlockPos(tiles.iterator().next()),
                net.minecraft.sound.SoundEvents.ENTITY_GENERIC_EXPLODE.value(),
                net.minecraft.sound.SoundCategory.BLOCKS, 1.4f, 0.5f);
        }
    }

    /** Is there a boss pillar on this tile? Public so the pickaxe path can ask. */
    public boolean isBossPillar(GridPos pos) {
        return bossPillars.contains(pos);
    }

    /**
     * Stand pillars up on the given tiles.
     *
     * <p>Every block goes through {@link #setArenaBlock}, which snapshots what it replaced into
     * {@code placedBlockRestores}. That is the only restore path in this class that does not
     * assume a single Y level, and it is what guarantees a three-tall pillar cannot outlive the
     * fight - see {@link EnemyAction.RaisePillars} for why a survivor would be so much worse
     * than an eyesore.
     */
    private void resolveRaisePillars(EnemyAction.RaisePillars rp) {
        if (arena == null || player == null || rp.tiles() == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        int raised = 0;
        for (GridPos pos : rp.tiles()) {
            if (!arena.isInBounds(pos) || bossPillars.contains(pos)) continue;
            GridTile tile = arena.getTile(pos);
            if (tile == null) continue;
            // Same rule as every other solid placement: never inside anybody. See
            // isTileOccupiedByCombatant.
            if (isTileOccupiedByCombatant(pos)) continue;

            tile.setType(TileType.OBSTACLE);
            tile.setBlockType(PILLAR_BLOCK);   // AFTER setType, which resets the block
            BlockPos floor = tileFloorPos(pos);
            for (int dy = 1; dy <= PILLAR_HEIGHT; dy++) {
                setArenaBlock(world, floor.up(dy), PILLAR_BLOCK, false);
            }
            // Driven in, shown with particles up the length of the timber rather than with
            // falling blocks. A falling block dropped down a column that ALREADY has a pillar
            // in it has three blocks less room to fall, lands, and becomes a real log standing
            // proud of the beam - a stump that outlives the pillar it was decorating, because
            // nothing clears blocks above the pillar's own height. The pillar appears in one
            // piece; the dust is what sells the impact.
            for (int dy = 1; dy <= PILLAR_HEIGHT; dy++) {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                    floor.getX() + 0.5, floor.getY() + dy + 0.5, floor.getZ() + 0.5,
                    6, 0.45, 0.15, 0.45, 0.02);
            }
            world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                floor.getX() + 0.5, floor.getY() + 0.6, floor.getZ() + 0.5, 10, 0.5, 0.1, 0.5, 0.03);
            bossPillars.add(pos);
            raised++;
        }
        if (raised > 0) {
            world.playSound(null, arena.gridToBlockPos(rp.tiles().get(0)),
                net.minecraft.sound.SoundEvents.BLOCK_WOOD_PLACE,
                net.minecraft.sound.SoundCategory.BLOCKS, 1.0f, 0.7f);
            sendSync();
            refreshHighlights();
        }
    }

    /**
     * Take a pillar down, all of it.
     *
     * <p>The single funnel for every way one can go: the boss spending it, a player mining it,
     * the collapse consuming it. One method because three near-identical removals that each
     * clear a different number of Y levels is precisely how a block gets orphaned at head
     * height.
     */
    private void clearBossPillar(GridPos pos) {
        if (!bossPillars.remove(pos) || arena == null || player == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos floor = tileFloorPos(pos);
        for (int dy = 1; dy <= PILLAR_HEIGHT; dy++) {
            setArenaBlock(world, floor.up(dy), Blocks.AIR, false);
        }
        GridTile tile = arena.getTile(pos);
        if (tile != null) {
            tile.setType(TileType.NORMAL);
            tile.setBlockType(getBiomeFloorBlock());
            world.setBlockState(floor, tile.getBlockType().getDefaultState());
        }
        // It topples rather than vanishing: the timbers are thrown outward in a scatter, one
        // per block of the pillar that just gave way.
        var tracker = com.crackedgames.craftics.vfx.VfxBlockTracker.of(world);
        for (int dy = 1; dy <= PILLAR_HEIGHT; dy++) {
            tracker.launchInto(world,
                new net.minecraft.util.math.Vec3d(
                    floor.getX() + 0.5, floor.getY() + dy, floor.getZ() + 0.5),
                new net.minecraft.util.math.Vec3d(
                    (combatRng.nextDouble() - 0.5) * 0.35, 0.25 + dy * 0.05,
                    (combatRng.nextDouble() - 0.5) * 0.35),
                // Thrown UPWARD and binned near the top of the arc, before gravity brings it
                // back down onto whatever it was flung over. Unlike the collapse rubble this
                // one has no fixed landing tile to adopt - it could come down on a wall, on
                // another pillar, anywhere - so it is never allowed to land at all.
                PILLAR_BLOCK.getDefaultState(), 8);
        }
        world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
            floor.getX() + 0.5, floor.getY() + 1.5, floor.getZ() + 0.5, 14, 0.3, 1.0, 0.3, 0.06);
        world.playSound(null, floor, net.minecraft.sound.SoundEvents.BLOCK_WOOD_BREAK,
            net.minecraft.sound.SoundCategory.BLOCKS, 1.0f, 0.6f);
    }

    /**
     * Is a live combatant standing here?
     *
     * <p>The question a boss must ask before it puts a solid block down. A block written into
     * an occupied tile does not politely fail - vanilla's push-out ejects whatever it overlaps,
     * so the victim is shoved to a tile they did not choose, and the arenas here are full of
     * fissures, ledges and void pits for them to be shoved into. Being killed by a shove is
     * not a mechanic anyone can play around, because nothing about the telegraph says which way
     * you will be pushed.
     */
    private boolean isTileOccupiedByCombatant(GridPos pos) {
        if (arena == null || pos == null) return false;
        if (arena.isOccupied(pos)) return true;
        java.util.Set<GridPos> one = java.util.Set.of(pos);
        for (CombatEntity e : enemies) {
            if (e.isAlive() && entityTouchesAnyTile(e, one)) return true;
        }
        for (ServerPlayerEntity member : allCombatPlayers()) {
            if (member == null || member.isRemoved() || member.isDisconnected()) continue;
            if (deadPartyMembers.contains(member.getUuid())) continue;
            if (pos.equals(gridPosOf(member))) return true;
        }
        return false;
    }

    /**
     * Land a collapse on whoever is standing on {@code pos} instead of building on top of them.
     *
     * <p>The counterpart to the guard above: the stone still comes down and it still hurts,
     * it just resolves as damage on the grid rather than as a block that displaces a hitbox.
     * Same shape as the Warden's fissure debris, which is the rule this arena already teaches.
     *
     * @return true if the fight ended here
     */
    private boolean crushOccupantsOn(GridPos pos, int damage, String what) {
        java.util.Set<GridPos> hitTile = java.util.Set.of(pos);
        List<ServerPlayerEntity> victims = new ArrayList<>();
        for (ServerPlayerEntity member : allCombatPlayers()) {
            if (member == null || member.isRemoved() || member.isDisconnected()) continue;
            if (deadPartyMembers.contains(member.getUuid())) continue;
            if (pos.equals(gridPosOf(member))) victims.add(member);
        }
        if (!victims.isEmpty()) {
            boolean gameOver = damagePartyVictims(victims, damage, null,
                (victim, actual, swapped) -> sendMessage("§8" + what + " crushes "
                    + (swapped ? victim.getName().getString() : "you")
                    + " for " + actual + " damage!"));
            if (gameOver) return true;
        }
        for (CombatEntity e : new ArrayList<>(enemies)) {
            if (!e.isAlive() || !entityTouchesAnyTile(e, hitTile)) continue;
            int dealt = e.takeDamage(damage);
            sendMessage("§8" + what + " crushes " + e.getDisplayName() + " for " + dealt + "!");
            checkAndHandleDeath(e);
        }
        return !active;
    }

    /**
     * Drop this round's ceiling collapse into the open fissures.
     *
     * <p>Runs at the top of the player's turn beside the other terrain ticks, so the state of
     * the floor the player is about to plan around is already settled.
     */
    private void tickFissureDebris() {
        if (arena == null || player == null || fissureDebris.isEmpty()) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();

        // Only tiles still short of a full fill can take a load.
        List<GridPos> open = new ArrayList<>();
        for (var entry : fissureDebris.entrySet()) {
            if (entry.getValue() < DEBRIS_TO_FILL) open.add(entry.getKey());
        }
        if (open.isEmpty()) { fissureDebris.clear(); return; }

        int loads = DEBRIS_MIN_PER_TURN
            + combatRng.nextInt(DEBRIS_MAX_PER_TURN - DEBRIS_MIN_PER_TURN + 1);
        sendMessage("§8The ceiling gives way over the crack...");

        for (int i = 0; i < loads && !open.isEmpty(); i++) {
            GridPos target = open.remove(combatRng.nextInt(open.size()));
            int filled = fissureDebris.merge(target, 1, Integer::sum);
            dropDebrisOn(world, target, filled);
            // A tile that is only part-filled can still take this round's later loads.
            if (filled < DEBRIS_TO_FILL) open.add(target);
            if (!active) return;   // a debris kill ended the fight
        }
        sendSync();
        refreshHighlights();
    }

    /**
     * One load of cobble landing on {@code pos}, with {@code filled} counting this load.
     *
     * <p>First load: rubble piles up from the bottom of the pit into a sunken ledge that can
     * be walked on. Second: the tile is whole again, ordinary cobblestone floor. Anything
     * caught underneath takes the hit either way.
     */
    private void dropDebrisOn(ServerWorld world, GridPos pos, int filled) {
        GridTile tile = arena.getTile(pos);
        if (tile == null) return;

        BlockPos overlay = arena.gridToBlockPos(pos);   // floorY+1
        BlockPos floor = overlay.down();                // floorY
        BlockPos pitFloor = floor.down();               // floorY-1

        // Deepslate, not cobble: this is the deep dark's own ceiling coming down, and the
        // patch should read as part of that floor rather than as something built into it.
        var debris = net.minecraft.block.Blocks.DEEPSLATE;
        if (filled >= DEBRIS_TO_FILL) {
            setArenaBlock(world, pitFloor, debris, false);
            setArenaBlock(world, floor, debris, false);
            setArenaBlock(world, overlay, net.minecraft.block.Blocks.AIR, false);
            tile.setType(TileType.NORMAL);
            tile.setBlockType(debris);
        } else {
            // Half-filled: rubble in the bottom of the pit. LOW_GROUND is the arena's
            // existing "walkable, but you are standing a block down" tile, which is exactly
            // what a partly-filled hole is - and it means the client, the pathfinder and the
            // fall checks all already understand it.
            setArenaBlock(world, pitFloor, debris, false);
            setArenaBlock(world, floor, net.minecraft.block.Blocks.AIR, false);
            setArenaBlock(world, overlay, net.minecraft.block.Blocks.AIR, false);
            tile.setType(TileType.LOW_GROUND);
            tile.setBlockType(debris);
        }

        // The rock is SEEN coming down. The block placement above is authoritative and
        // immediate - the grid must agree with itself the moment the fill happens - so this
        // entity is pure theatre: DropItem false so it never becomes an item if it lands
        // somewhere odd, HurtEntities false because the 10 damage is applied below by the
        // grid rather than by vanilla's falling-block physics.
        spawnDebrisVisual(world, floor, debris);

        world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
            floor.getX() + 0.5, floor.getY() + 0.5, floor.getZ() + 0.5, 12, 0.35, 0.4, 0.35, 0.03);
        world.playSound(null, floor, net.minecraft.sound.SoundEvents.BLOCK_STONE_BREAK,
            net.minecraft.sound.SoundCategory.BLOCKS, 1.1f, 0.6f);

        // Anyone caught under it. Players first: damagePartyVictims handles the co-op
        // player swap, death and game-over path.
        java.util.Set<GridPos> hitTile = java.util.Set.of(pos);
        List<ServerPlayerEntity> victims = new ArrayList<>();
        for (ServerPlayerEntity member : allCombatPlayers()) {
            if (member == null || member.isRemoved() || member.isDisconnected()) continue;
            if (deadPartyMembers.contains(member.getUuid())) continue;
            if (pos.equals(gridPosOf(member))) victims.add(member);
        }
        if (!victims.isEmpty()) {
            boolean gameOver = damagePartyVictims(victims, DEBRIS_DAMAGE, null,
                (victim, actual, swapped) -> sendMessage("§8Falling rock crushes "
                    + (swapped ? victim.getName().getString() : "you")
                    + " for " + actual + " damage!"));
            if (gameOver) return;
        }

        for (CombatEntity e : new ArrayList<>(enemies)) {
            if (!e.isAlive() || !entityTouchesAnyTile(e, hitTile)) continue;
            int dealt = e.takeDamage(DEBRIS_DAMAGE);
            sendMessage("§8Falling rock crushes " + e.getDisplayName() + " for " + dealt + "!");
            checkAndHandleDeath(e);
        }
    }

    /**
     * A block of ceiling visibly falling into {@code floor}.
     *
     * <p>Cosmetic only, and deliberately so: it is spawned ABOVE a tile that has already been
     * filled, so it lands on solid ground and vanishes rather than placing anything. The
     * authoritative block is set by the caller in the same tick, which keeps the grid model
     * and the world in agreement even if the entity is culled, the chunk unloads, or the
     * fight ends mid-fall.
     */
    private void spawnDebrisVisual(ServerWorld world, BlockPos floor, net.minecraft.block.Block block) {
        //? if <=1.21.1 {
        net.minecraft.entity.FallingBlockEntity fbe =
            net.minecraft.entity.EntityType.FALLING_BLOCK.create(world);
        //?} else {
        /*net.minecraft.entity.FallingBlockEntity fbe =
            net.minecraft.entity.EntityType.FALLING_BLOCK.create(world, net.minecraft.entity.SpawnReason.TRIGGERED);
        *///?}
        if (fbe == null) return;
        net.minecraft.nbt.NbtCompound nbt = new net.minecraft.nbt.NbtCompound();
        fbe.writeNbt(nbt);
        nbt.put("BlockState", net.minecraft.nbt.NbtHelper.fromBlockState(block.getDefaultState()));
        nbt.putBoolean("DropItem", false);
        nbt.putBoolean("HurtEntities", false);
        nbt.putInt("Time", 1);
        fbe.readNbt(nbt);
        // High enough to read as coming out of the dark overhead, close enough to land fast.
        fbe.setPosition(floor.getX() + 0.5, floor.getY() + 14.0, floor.getZ() + 0.5);
        fbe.setVelocity(0, -0.6, 0);
        fbe.timeFalling = 1;
        fbe.addCommandTag("craftics_arena");
        world.spawnEntity(fbe);
    }

    /**
     * Fly the held item along {@code waypoints} and optionally back to the thrower.
     *
     * <p>The visible half of a thrown-weapon ability. It holds the player's turn for the
     * duration, so the next action waits for the disc to come home rather than firing while it
     * is mid-air.
     *
     * @param waypoints grid tiles to visit in order, first hop leaving the thrower
     * @param returnHome fly back to the thrower at the end (a chakram does; an arrow does not)
     */
    public void flyHeldItemChain(java.util.List<GridPos> waypoints, boolean returnHome) {
        flyHeldItemChain(waypoints, returnHome, h -> false);
    }

    /**
     * As above, but each waypoint does something when the disc reaches it.
     *
     * @param impact run when a hop lands; returns true if that landing killed its target, which
     *               ends the chain there rather than bouncing off a corpse
     * @return ticks the disc takes to reach its FIRST waypoint, for the caller to time the
     *         primary hit to, or 0 if nothing was launched
     */
    public int flyHeldItemChain(java.util.List<GridPos> waypoints, boolean returnHome,
                                ProjectileFlight.ImpactHandler impact) {
        if (!active || player == null || arena == null || waypoints == null || waypoints.isEmpty()) return 0;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        ItemStack held = player.getMainHandStack();
        if (held.isEmpty()) return 0;

        BlockPos originBp = arena.gridToBlockPos(arena.getPlayerGridPos());
        double ox = originBp.getX() + 0.5, oy = originBp.getY() + 1.1, oz = originBp.getZ() + 0.5;

        // An ITEM DISPLAY, not a dropped item. A dropped ItemEntity always renders upright and
        // its pitch cannot be set, so a chakram thrown that way stands on edge like a coin. A
        // display entity carries a full transform, which is what lets the disc lie flat and
        // spin about its own axis on the way out - a frisbee rather than a tossed sword.
        net.minecraft.entity.decoration.DisplayEntity.ItemDisplayEntity disc =
            new net.minecraft.entity.decoration.DisplayEntity.ItemDisplayEntity(
                net.minecraft.entity.EntityType.ITEM_DISPLAY, world);
        disc.refreshPositionAndAngles(ox, oy, oz, 0f, 0f);
        ((com.crackedgames.craftics.mixin.ItemDisplayInvoker) disc)
            .craftics$setItemStack(held.copyWithCount(1));
        var discInv = (com.crackedgames.craftics.mixin.DisplayEntityInvoker) disc;
        discInv.craftics$setBillboardMode(
            net.minecraft.entity.decoration.DisplayEntity.BillboardMode.FIXED);
        // Interpolate between the positions the walker sets, or the disc stutters one tile at
        // a time instead of gliding.
        discInv.craftics$setTeleportDuration(2);
        discInv.craftics$setInterpolationDuration(2);
        discInv.craftics$setBrightness(new net.minecraft.entity.decoration.Brightness(15, 15));
        disc.addCommandTag("craftics_arena");
        world.spawnEntity(disc);
        // Spin counter, advanced by the mover below.
        final int[] spin = {0};

        java.util.List<ProjectileFlight.Hop> hops = new java.util.ArrayList<>();
        for (GridPos wp : waypoints) hops.add(new ProjectileFlight.Hop(wp, -1, 0));

        // Speed off distance, not a fixed count. A flat six ticks a leg made a disc thrown at
        // the tile next door drift across it, and one thrown to the edge of its range look no
        // faster - the same "needs to be faster" the arrows had before they were timed this way.
        int legTiles = 1;
        GridPos prev = arena.getPlayerGridPos();
        for (GridPos wp : waypoints) {
            legTiles = Math.max(legTiles,
                Math.max(Math.abs(wp.x() - prev.x()), Math.abs(wp.z() - prev.z())));
            prev = wp;
        }
        final int discTicks = Math.max(3, Math.round(legTiles * DISC_TICKS_PER_TILE));

        final double[] home = {ox, oy, oz};
        ProjectileFlight flight = new ProjectileFlight(
            disc, hops,
            impact,
            new ProjectileFlight.Flightpath() {
                @Override public double[] originOf(ProjectileFlight.Hop h) { return home; }
                @Override public double[] arrivalOf(ProjectileFlight.Hop h) {
                    BlockPos bp = arena.gridToBlockPos(h.target());
                    return new double[]{bp.getX() + 0.5, bp.getY() + 1.1, bp.getZ() + 0.5};
                }
                @Override public EntityWalker.Mover moverFor(net.minecraft.entity.Entity e) {
                    EntityWalker.Mover base = ProjectileFlight.holdingMover(e);
                    return (x, y, z, yaw) -> {
                        base.apply(x, y, z, yaw);
                        // Lay it flat (90 degrees about X) and spin it about the vertical.
                        // Composed in that order so the spin turns the disc in its own plane
                        // rather than tumbling it end over end.
                        spin[0]++;
                        float angle = (float) (spin[0] * Math.PI / 4);
                        var flat = new org.joml.Quaternionf(
                            new org.joml.AxisAngle4f((float) Math.toRadians(90f), 1f, 0f, 0f));
                        var turn = new org.joml.Quaternionf(
                            new org.joml.AxisAngle4f(angle, 0f, 0f, 1f));
                        discInv.craftics$setTransformation(
                            new net.minecraft.util.math.AffineTransformation(
                                new org.joml.Vector3f(0f, 0f, 0f),
                                flat.mul(turn),
                                new org.joml.Vector3f(0.8f, 0.8f, 0.8f),
                                new org.joml.Quaternionf()));
                    };
                }
            },
            returnHome ? home : null, discTicks, activeWalkers::add, this::onFlightFinished);
        launchFlight(flight);
        return discTicks;
    }

    /** Ticks a thrown weapon spends crossing one tile. Heavier than an arrow, lighter than a
     *  lobbed item. */
    private static final float DISC_TICKS_PER_TILE = 1.5f;

    /**
     * Throw the weapon along an ability's plan, resolving each hop as it arrives.
     *
     * <p>The order this exists to fix: the disc leaves the hand FIRST, and the damage follows it
     * to each target. Every hop past the primary is a ricochet, and it lands through
     * {@link #resolveAbilityHop} rather than a bare {@code takeDamage} - which is what puts
     * knockback, Fire Aspect and the weapon's own proc back on the enemies a bounce touches.
     *
     * <p>Hop 0 is deliberately NOT applied here. The engine deals the primary hit itself from
     * its own damage chain (crits, resistances, the whole ladder), timed by the caller to this
     * flight's first arrival; applying it again here would hit the same enemy twice for one
     * throw.
     *
     * @return ticks until the disc reaches the primary target, or 0 if it never left
     */
    private int flyAbilityPlan(com.crackedgames.craftics.api.AbilityPlan plan, Item weapon,
                               PlayerProgression.PlayerStats stats, int luckPoints) {
        if (plan == null || plan.hops().isEmpty() || arena == null) return 0;
        java.util.List<GridPos> waypoints = new java.util.ArrayList<>();
        java.util.List<com.crackedgames.craftics.api.AbilityPlan.Hop> hops = plan.hops();
        for (var h : hops) {
            if (h.target() == null || h.target().getGridPos() == null) return 0;
            waypoints.add(h.target().getGridPos());
        }
        final int[] landed = {0};
        return flyHeldItemChain(waypoints, plan.returnsToThrower(), h -> {
            int i = landed[0]++;
            if (i == 0 || i >= hops.size()) return false;   // primary belongs to the damage chain
            return resolveAbilityHop(hops.get(i), weapon, stats, luckPoints, "Ricochet!");
        });
    }

    /** Guards {@link #resolveAbilityHop} against a weapon whose ability bounces into itself. */
    private boolean resolvingAbilityHop = false;

    /**
     * Land one ricochet, with everything a normal strike would carry.
     *
     * <p>This is the whole point of the plan. The bounce used to be
     * {@code bounce.takeDamage(n)} inside the ability handler, which is around the outside of
     * every on-hit effect the game has: a Punch chakram knocked back the enemy it was aimed at
     * and nothing it bounced to, and a Chomp'olotl rolled its axolotl only on the first target.
     * Routing through the universal enchant pass and the weapon's own handler means a ricochet
     * gets whatever the swing would have.
     *
     * @return true if this hop killed its target, which ends the chain
     */
    private boolean resolveAbilityHop(com.crackedgames.craftics.api.AbilityPlan.Hop hop,
                                      Item weapon, PlayerProgression.PlayerStats stats,
                                      int luckPoints, String label) {
        CombatEntity t = hop.target();
        if (t == null || !t.isAlive() || player == null || arena == null) return false;
        int dealt = t.takeDamage(hop.damage());
        sendMessage("§b✦ " + label + " " + t.getDisplayName() + " takes " + dealt + "!");
        sendToAllParty(new CombatEventPayload(
            CombatEventPayload.EVENT_DAMAGED, t.getEntityId(), dealt, t.getCurrentHp(),
            t.getGridPos().x(), t.getGridPos().z()));
        if (hop.appliesOnHitEffects() && t.isAlive() && !resolvingAbilityHop) {
            resolvingAbilityHop = true;
            try {
                // ORDER MATTERS, and it is the same order the main attack path uses: the
                // weapon's own ability first, then the universal enchant pass told whether that
                // ability already hit extra targets. Sweeping Edge and the weapon abilities that
                // bake in their own AoE (claymore, glaive, scythe, coral fan, Soulrender) share
                // one geometry, so the flag is what stops the same neighbours being hit twice
                // for one landing. Running the pass first with the flag hardcoded - which is
                // what this did - suppressed Sweeping Edge on every hop unconditionally, so a
                // sweeping weapon's ricochet quietly hit one enemy where the swing hits three.
                boolean abilityHitExtras = false;
                if (WeaponAbility.hasAbility(weapon)) {
                    var extra = WeaponAbility.applyAbility(player, weapon, t, arena, hop.damage(),
                        stats, luckPoints);
                    abilityHitExtras = !extra.extraTargets().isEmpty();
                    for (String msg : extra.messages()) {
                        if (msg.startsWith("[WB_SELF:")) {
                            applyWindBurstRecoil(Integer.parseInt(msg.substring(9, msg.length() - 1)));
                            continue;
                        }
                        sendMessage(msg);
                    }
                    for (CombatEntity swept : extra.extraTargets()) {
                        checkAndHandleDeath(swept);
                    }
                }

                // A bow and a sword do not carry the same enchantments, so they do not get the
                // same pass. universalEnchantEffects is the six MELEE enchants and a bow can
                // never legally hold any of them; the bow's equivalents are Flame and Punch,
                // which the main attack path applies to the primary target only. Applied here
                // per hop, they reach every body in the line - which is the point.
                boolean ranged = PlayerCombatStats.isBowItem(weapon) || weapon == Items.CROSSBOW;
                if (!t.isAlive()) {
                    // Killed by its own ability. Nothing below can land on a corpse.
                } else if (ranged) {
                    int flame = PlayerCombatStats.getBowFlame(player);
                    if (flame > 0) {
                        int amp = flame == 1 ? 0 : 1;
                        int turns = flame == 1 ? 2 : 4;
                        t.stackBurning(turns, amp);
                        if (t.getMobEntity() != null) t.getMobEntity().setFireTicks(turns * 80);
                        sendMessage("§6  Flame! " + t.getDisplayName() + " catches light.");
                    }
                    int punch = PlayerCombatStats.getBowPunch(player);
                    if (punch > 0 && t.isAlive()) {
                        GridPos from = arena.getPlayerGridPos();
                        int kdx = Integer.signum(t.getGridPos().x() - from.x());
                        int kdz = Integer.signum(t.getGridPos().z() - from.z());
                        if (kdx != 0 || kdz != 0) knockEnemyBack(t, kdx, kdz, punch);
                    }
                } else {
                    // Sharpness, Smite, Bane, Knockback, Serrated and - when the ability did not
                    // already claim the swing - Sweeping Edge, so a hop lands the same whirlwind
                    // a direct strike does.
                    var uni = com.crackedgames.craftics.api.VanillaWeapons.universalEnchantEffects(
                        player, t, arena, hop.damage(), stats, luckPoints, abilityHitExtras);
                    for (String msg : uni.messages()) {
                        if (msg.startsWith("[WB_SELF:")) {
                            applyWindBurstRecoil(Integer.parseInt(msg.substring(9, msg.length() - 1)));
                            continue;
                        }
                        sendMessage(msg);
                    }
                    for (CombatEntity swept : uni.extraTargets()) {
                        checkAndHandleDeath(swept);
                    }
                    int fireAspect = PlayerCombatStats.getFireAspect(player);
                    if (fireAspect > 0 && t.isAlive()) {
                        t.stackBurning(fireAspect * 2, Math.max(0, fireAspect - 1));
                        if (t.getMobEntity() != null) t.getMobEntity().setFireTicks(fireAspect * 160);
                    }
                }
            } finally {
                resolvingAbilityHop = false;
            }
        }
        checkAndHandleDeath(t);
        return !t.isAlive();
    }

    /**
     * The projectile body every flight uses: an item display showing {@code stack}.
     *
     * <p>Not a real arrow or a dropped item. Those are client-predicted - the client
     * extrapolates their position from velocity, and this system pins velocity to zero so the
     * walker owns the movement. The result was a projectile the server flew across the arena
     * while every client rendered it sitting by the thrower's head. A display entity has no
     * physics and no prediction: it goes exactly where the server puts it, and its
     * interpolation makes the per-tick steps read as a glide instead of a stutter.
     */
    private net.minecraft.entity.decoration.DisplayEntity.ItemDisplayEntity spawnFlightBody(
            ServerWorld world, ItemStack stack, double x, double y, double z) {
        var body = new net.minecraft.entity.decoration.DisplayEntity.ItemDisplayEntity(
            net.minecraft.entity.EntityType.ITEM_DISPLAY, world);
        body.refreshPositionAndAngles(x, y, z, 0f, 0f);
        ((com.crackedgames.craftics.mixin.ItemDisplayInvoker) body)
            .craftics$setItemStack(stack.copyWithCount(1));
        var inv = (com.crackedgames.craftics.mixin.DisplayEntityInvoker) body;
        inv.craftics$setBillboardMode(
            net.minecraft.entity.decoration.DisplayEntity.BillboardMode.FIXED);
        inv.craftics$setTeleportDuration(2);
        inv.craftics$setInterpolationDuration(2);
        inv.craftics$setBrightness(new net.minecraft.entity.decoration.Brightness(15, 15));
        body.addCommandTag("craftics_arena");
        world.spawnEntity(body);
        return body;
    }

    /**
     * An item sprite runs corner to corner, not edge to edge.
     *
     * <p>Every long item in the game - arrow, trident, sword - is drawn on its texture as a
     * diagonal from the bottom-left to the top-right. So a sprite yawed to the raw heading has
     * its shaft 45 degrees off the direction it is travelling: aim due north and the arrow
     * points north-east. Correcting by this is what makes the tip actually lead.
     */
    private static final float SPRITE_DIAGONAL = (float) (-Math.PI / 4);

    /** Arc height as a fraction of the shot's length, and the bounds either side of it. */
    private static final double FLIGHT_ARC_PER_TILE = 0.14;
    private static final double FLIGHT_ARC_MIN = 0.15;
    private static final double FLIGHT_ARC_MAX = 1.1;

    /**
     * A mover that flies a display's item on a real ballistic path, nose first the whole way.
     *
     * <p>Replaces a mover that did neither. That one took the straight line
     * {@link EntityWalker} hands it - constant speed, dead flat, no rise and no fall - and
     * pinned the sprite to a single pose computed once at launch, so the shot read as a decal
     * sliding across the floor rather than something thrown. Three things were wrong and all
     * three are fixed here:
     *
     * <ul>
     *   <li><b>It never arced.</b> The walker lerps Y along with X and Z, so a shot between two
     *       tiles at the same height stayed at exactly that height for the whole flight. Y is
     *       now driven by a parabola over the top of the straight line, scaled to the range, so
     *       a long shot lofts and a point-blank one barely lifts.</li>
     *   <li><b>It never turned.</b> The pose was fixed at launch, so even once a rise and fall
     *       existed the arrow would have flown through it at a constant angle. The pose is now
     *       rebuilt every tick from the path's own tangent, which is what makes it climb out
     *       nose-up and come down nose-down into the target.</li>
     *   <li><b>It pointed 45 degrees wrong.</b> See {@link #SPRITE_DIAGONAL}.</li>
     * </ul>
     *
     * <p><b>The aiming is not done here.</b> A display in {@code BillboardMode.FIXED} renders in
     * its own entity rotation, and {@code holdingMover} already sets that rotation from the
     * direction of travel every tick via {@code ProjectileFlight.faceAlong}. The old mover
     * applied the heading a SECOND time in the transformation on top of it, so the sprite came
     * out at twice the intended yaw - pointing at the target only when the target happened to
     * lie due north, and further off the more the shot deviated from it. That is the bug behind
     * "it's not pointing towards the enemy". The transformation below now carries only what is
     * true of the sprite itself regardless of where it is going: lay it into the horizontal
     * plane, and undo its diagonal. Direction is left entirely to the entity rotation, which
     * gets it right including pitch.
     *
     * <p>Flat rather than upright is deliberate: the horizontal plane is the one the fight is
     * read on from the isometric camera, and an upright sprite would vanish edge-on every time
     * it flew toward or away from the viewer.
     */
    private EntityWalker.Mover ballisticPointingMover(
            net.minecraft.entity.Entity e,
            com.crackedgames.craftics.mixin.DisplayEntityInvoker inv,
            double sx, double sy, double sz, double ex, double ey, double ez) {
        EntityWalker.Mover base = ProjectileFlight.holdingMover(e);

        final double dx = ex - sx, dy = ey - sy, dz = ez - sz;
        final double flat = Math.sqrt(dx * dx + dz * dz);
        final double arc = Math.max(FLIGHT_ARC_MIN,
            Math.min(FLIGHT_ARC_MAX, flat * FLIGHT_ARC_PER_TILE));

        // Constant for the whole flight: nothing here depends on where the shot is going.
        var lay = new org.joml.Quaternionf(
            new org.joml.AxisAngle4f((float) Math.toRadians(90f), 1f, 0f, 0f));
        var undoDiagonal = new org.joml.Quaternionf(
            new org.joml.AxisAngle4f(SPRITE_DIAGONAL, 0f, 0f, 1f));
        final var pose = lay.mul(undoDiagonal);

        return (x, y, z, yaw) -> {
            // Recover progress from the walker's straight-line step rather than counting ticks
            // here, so this stays in step with the walker even if its timing changes.
            double travelled = Math.sqrt((x - sx) * (x - sx) + (z - sz) * (z - sz));
            double t = flat < 1.0e-4 ? 1.0 : Math.min(1.0, travelled / flat);

            // Y comes off the parabola instead of the walker's flat lerp. base.apply then aims
            // the entity along the step it actually took, so the arc is what makes it nose up
            // out of the bow and drop onto the target rather than sliding across at one angle.
            double arcedY = sy + dy * t + Math.sin(t * Math.PI) * arc;
            base.apply(x, arcedY, z, yaw);

            inv.craftics$setTransformation(new net.minecraft.util.math.AffineTransformation(
                new org.joml.Vector3f(0f, 0f, 0f),
                pose,
                new org.joml.Vector3f(0.9f, 0.9f, 0.9f),
                new org.joml.Quaternionf()));
        };
    }

    /** Items that visibly cross the arena when used on a tile. */
    private static boolean isThrownItem(net.minecraft.item.Item item) {
        return item == Items.SNOWBALL || item == Items.EGG || item == Items.FIRE_CHARGE
            || item == Items.WIND_CHARGE || item == Items.BRICK || item == Items.INK_SAC
            || item == Items.SPLASH_POTION || item == Items.LINGERING_POTION
            || item == Items.ENDER_PEARL;
    }

    /**
     * Show {@code stack} flying to {@code target}, and say how long it will take.
     *
     * <p>The caller now waits on that number: the item's effect is resolved when the throw
     * ARRIVES rather than at the moment it left the hand. That is also why the flight is no
     * longer pinned to a fixed four ticks. It used to be short on purpose - every tick the item
     * spent in the air was a tick its explosion had already happened without it, so the throw
     * had to sprint to catch up with its own consequences. With the consequences waiting for it,
     * it can travel at a speed that looks like a throw.
     *
     * @return ticks until it lands, or 0 if nothing was launched
     */
    private int flyThrownItem(ItemStack stack, GridPos target) {
        if (!active || player == null || arena == null || stack.isEmpty()) return 0;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos fromBp = arena.gridToBlockPos(arena.getPlayerGridPos());
        BlockPos toBp = arena.gridToBlockPos(target);
        double sx = fromBp.getX() + 0.5, sy = fromBp.getY() + 1.2, sz = fromBp.getZ() + 0.5;
        double ex = toBp.getX() + 0.5, ey = toBp.getY() + 1.0, ez = toBp.getZ() + 0.5;

        var thrown = spawnFlightBody(world, stack, sx, sy, sz);
        var thrownInv = (com.crackedgames.craftics.mixin.DisplayEntityInvoker) thrown;

        int tiles = Math.max(1, Math.max(
            Math.abs(target.x() - arena.getPlayerGridPos().x()),
            Math.abs(target.z() - arena.getPlayerGridPos().z())));
        final int throwTicks = Math.max(THROWN_ITEM_TICKS,
            Math.round(tiles * THROWN_ITEM_TICKS_PER_TILE));

        ProjectileFlight flight = new ProjectileFlight(
            thrown, java.util.List.of(new ProjectileFlight.Hop(target, -1, 0)),
            h -> false,
            new ProjectileFlight.Flightpath() {
                @Override public double[] originOf(ProjectileFlight.Hop h) { return new double[]{sx, sy, sz}; }
                @Override public double[] arrivalOf(ProjectileFlight.Hop h) { return new double[]{ex, ey, ez}; }
                @Override public EntityWalker.Mover moverFor(net.minecraft.entity.Entity e) {
                    return ballisticPointingMover(e, thrownInv, sx, sy, sz, ex, ey, ez);
                }
            },
            null, throwTicks, activeWalkers::add, this::onFlightFinished);
        launchFlight(flight);
        return throwTicks;
    }

    /** Flight length of the shot just launched, folded into pendingAttackDelay. */
    private int rangedFlightTicks = 0;

    /** Ticks a projectile spends crossing one tile. Slow enough to read, fast enough to
     *  not stall the turn. */
    private static final int FLIGHT_TICKS_PER_TILE = 2;
    /**
     * Floor on a thrown item's flight, so a throw at the tile next door is still seen leaving
     * the hand.
     *
     * <p>This used to be the WHOLE flight time, fixed regardless of distance, and short on
     * purpose: the item's damage and burst were applied the moment it was used, so every tick
     * it spent in the air was a tick its explosion had already happened without it. The throw
     * had to keep up with its own consequences. Item use now waits for the landing, so the
     * flight is free to take the time the distance deserves - see {@link #flyThrownItem}.
     */
    private static final int THROWN_ITEM_TICKS = 4;
    /** Ticks per tile for a lobbed item. Heavier and slower than an arrow or a disc. */
    private static final float THROWN_ITEM_TICKS_PER_TILE = 2.0f;
    /**
     * Ticks between arming a flight and it actually arriving, beyond its own travel time.
     *
     * <p>activeWalkers hands a newly added walker its first tick on the NEXT server tick, and
     * the final step needs a tick to be seen. Anything timed to coincide with a landing has to
     * account for both or it fires while the projectile is still visibly in the air.
     */
    private static final int FLIGHT_SCHEDULING_LAG = 2;
    /** Ticks per tile for an arrow. Deliberately quick - an arrow is not a thrown rock. */
    private static final float ARROW_TICKS_PER_TILE = 1.0f;

    /**
     * Send a visible projectile from {@code from} to {@code to} and return how many ticks it
     * will take.
     *
     * <p>The entity is the spectacle only: the damage stays where it already was, in
     * {@code pendingAttackAction}, whose delay the caller stretches to match this. Keeping the
     * two apart means a culled or lost arrow cannot swallow a hit the player paid AP for.
     */
    private int launchPlayerProjectile(BlockPos from, BlockPos to, boolean trident, int impactTicks) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        double sx = from.getX() + 0.5, sy = from.getY() + 1.2, sz = from.getZ() + 0.5;
        double ex = to.getX() + 0.5, ey = to.getY() + 1.0, ez = to.getZ() + 0.5;
        ItemStack body = new ItemStack(trident ? Items.TRIDENT : Items.ARROW);
        var shot = spawnFlightBody(world, body, sx, sy, sz);
        var shotInv = (com.crackedgames.craftics.mixin.DisplayEntityInvoker) shot;

        // Arrows are FAST. Timing the flight off the weapon's impact delay made a bow shot
        // take half a second to cross two tiles, which is nothing like an arrow. Distance
        // drives it instead, at roughly a tile per tick, floored so a point-blank shot is
        // still seen leaving the bow.
        int tiles = Math.max(1, Math.max(Math.abs(to.getX() - from.getX()),
                                         Math.abs(to.getZ() - from.getZ())));
        int ticks = Math.max(3, Math.round(tiles * ARROW_TICKS_PER_TILE));

        ProjectileFlight.Hop hop = new ProjectileFlight.Hop(null, -1, 0);
        ProjectileFlight flight = new ProjectileFlight(
            shot, java.util.List.of(hop),
            h -> false,                                  // damage lives in pendingAttackAction
            new ProjectileFlight.Flightpath() {
                @Override public double[] originOf(ProjectileFlight.Hop h) { return new double[]{sx, sy, sz}; }
                @Override public double[] arrivalOf(ProjectileFlight.Hop h) { return new double[]{ex, ey, ez}; }
                @Override public EntityWalker.Mover moverFor(net.minecraft.entity.Entity e) {
                    return ballisticPointingMover(e, shotInv, sx, sy, sz, ex, ey, ez);
                }
            },
            null, ticks, activeWalkers::add, this::onFlightFinished);
        launchFlight(flight);
        return ticks;
    }

    // ── Projectiles in flight ────────────────────────────────────────────────

    /** The flight currently in the air, or null. One at a time: a turn cannot throw twice. */
    private ProjectileFlight activeFlight = null;
    /**
     * Ticks left before the flight is forced to end no matter what.
     *
     * <p>The input lock is what makes the next action wait, and a lock that is never released
     * is a fight nobody can act in. Every ordinary exit releases it, and this catches the ones
     * that are not ordinary - an entity culled by a chunk unload, a world change, a bug.
     */
    private int flightCeiling = 0;

    /** Drive the live flight and enforce its ceiling. */
    private void tickProjectileFlight() {
        if (activeFlight == null) return;
        if (flightCeiling > 0 && --flightCeiling <= 0 && !activeFlight.isFinished()) {
            CrafticsMod.LOGGER.warn("Projectile flight overran its ceiling; forcing it down");
            activeFlight.abort();
        }
        activeFlight.tick();
        if (activeFlight.isFinished()) activeFlight = null;
    }

    /**
     * Put a flight in the air and hold the player's turn until it lands.
     *
     * <p>{@code spellAnimCooldown} is the existing input gate - handleAction refuses every
     * player action while it is above zero - so the lock costs no new machinery. It is set
     * generously and cleared by the flight's own finish callback, which is the only place
     * that releases it.
     */
    private void launchFlight(ProjectileFlight flight) {
        if (flight == null) return;
        if (activeFlight != null) activeFlight.abort();   // never two at once
        activeFlight = flight;
        int planned = flight.plannedTicks();
        spellAnimCooldown = Math.max(spellAnimCooldown, planned);
        flightCeiling = planned + 20;
        flight.start();
        if (flight.isFinished()) activeFlight = null;     // nothing to fly; do not hold the turn
    }

    /** Called by a flight when it ends: give the turn back and resync. */
    private void onFlightFinished() {
        // Hold the turn until the DAMAGE has resolved too, not merely until the arrow has
        // landed. pendingAttackDelay is what actually applies the hit, and it can still have
        // a tick or two left; releasing here would let the player act before their own shot
        // had connected.
        spellAnimCooldown = Math.max(0, Math.max(pendingAttackDelay, pendingItemDelay));
        flightCeiling = 0;
        sendSync();
        refreshHighlights();
        // A projectile can land the killing blow, and the room must be re-checked THEN rather
        // than when it was thrown - otherwise the fight ends while the arrow is still moving.
        if (phase != CombatPhase.GAME_OVER && phase != CombatPhase.LEVEL_COMPLETE
                && !anyEnemyBlockingVictory()) {
            handleVictory();
        }
    }

    /** True while something is in the air. Callers must not start a second flight. */
    public boolean hasFlightInAir() {
        return activeFlight != null && !activeFlight.isFinished();
    }

    /** True when any tile of {@code e}'s footprint is in {@code tiles}. */
    private static boolean entityTouchesAnyTile(CombatEntity e, java.util.Set<GridPos> tiles) {
        GridPos base = e.getGridPos();
        if (base == null) return false;
        for (int dx = 0; dx < e.getSizeX(); dx++) {
            for (int dz = 0; dz < e.getSizeZ(); dz++) {
                if (tiles.contains(new GridPos(base.x() + dx, base.z() + dz))) return true;
            }
        }
        return false;
    }

    /**
     * The Tidecaller's Conduction strike. Lightning lands on the marked combatant's LIVE
     * tile - never the tile the mark was cast on - then arcs between every combatant
     * (party members, allies, and the boss's own minions alike) within 2 tiles of the
     * last one struck, walked by {@link ConductionChain}. Damage decays 1 per jump, and
     * each Soaked link doubles independently: enemies through
     * {@link CombatEntity#takeLightningDamage}, players doubled here because they have no
     * lightning entry point of their own. The Tidecaller itself never conducts - a boss
     * electrocuting itself reads as a bug, not a mechanic.
     */
    private void resolveConductionChain(int markId, int baseDamage) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();

        // Combatant roster: living party members first, then every living combat entity
        // except the strike's owner and non-combatants (projectiles, background bosses).
        java.util.List<ServerPlayerEntity> members = new java.util.ArrayList<>();
        java.util.List<CombatEntity> mobs = new java.util.ArrayList<>();
        java.util.List<GridPos> positions = new java.util.ArrayList<>();
        if (partyPlayers.size() > 1) {
            for (ServerPlayerEntity member : partyPlayers) {
                if (member == null || member.isRemoved() || member.isDisconnected()) continue;
                if (deadPartyMembers.contains(member.getUuid())) continue;
                members.add(member);
                positions.add(gridPosOf(member));
            }
        } else {
            members.add(player);
            positions.add(arena.getPlayerGridPos());
        }
        int mobOffset = members.size();
        int startIndex = markId == com.crackedgames.craftics.combat.ai.boss.BossWarning.MARK_PLAYER_ID
            ? members.indexOf(player) : -1;
        for (CombatEntity e : enemies) {
            if (!e.isAlive() || e == currentEnemy || e.isProjectile() || e.isBackgroundBoss()) continue;
            if (e.getEntityId() == markId) startIndex = mobOffset + mobs.size();
            mobs.add(e);
            positions.add(e.getGridPos());
        }

        // A dead or absent mark fizzles: no damage, no chain, no fallback to the cast tile.
        if (startIndex < 0) {
            sendMessage("§e⚡ The conduction bolt earths itself harmlessly - its mark is gone.");
            return;
        }

        java.util.List<ConductionChain.Link> chain = ConductionChain.walk(positions, startIndex,
            com.crackedgames.craftics.combat.ai.boss.TidecallerAI.CONDUCTION_CHAIN_RANGE);
        sendMessage("§e§l⚡ Conduction! §eThe bolt strikes the mark and arcs through everything near it!");

        BlockPos prevBlock = null;
        int chainIndex = 0;
        for (ConductionChain.Link link : chain) {
            int dmg = ConductionChain.damageAt(baseDamage, link.depth());
            BlockPos linkBlock = arena.gridToBlockPos(positions.get(link.index()));
            boolean soaked;
            if (link.index() < mobOffset) {
                ServerPlayerEntity victim = members.get(link.index());
                soaked = isPartyMemberSoaked(victim);
                // Soaked doubles lightning. CombatEntity applies this centrally in
                // takeLightningDamage; the player side has no lightning entry point,
                // so the 2x is applied here before the shared damage path.
                final boolean soakedTag = soaked;
                boolean gameOver = damagePartyVictims(java.util.List.of(victim),
                    soaked ? dmg * 2 : dmg, (v, actual, swapped) ->
                        sendMessage("§e  ⚡ The chain hits " + (swapped ? v.getName().getString() : "you")
                            + " for " + actual + (soakedTag ? " §3(2x Soaked!)" : "") + "§e!"));
                if (gameOver) return; // a death ended combat - stop touching state
            } else {
                CombatEntity e = mobs.get(link.index() - mobOffset);
                soaked = e.isSoaked();
                int dealt = e.takeLightningDamage(dmg);
                sendMessage("§e  ⚡ The chain hits " + e.getDisplayName() + " for " + dealt
                    + (soaked ? " §3(2x Soaked!)" : "") + "§e!");
                checkAndHandleDeath(e);
            }

            // One staggered arc per jump so the bolt visibly travels outward link by
            // link - same delayed-effect queue and cadence as the Guster sherd's chain.
            // The first link's arc drops from the sky: it is the strike itself.
            final BlockPos fromBlock = prevBlock != null ? prevBlock : linkBlock.up(10);
            final BlockPos toBlock = linkBlock;
            final int depth = link.depth();
            final boolean arcSoaked = soaked;
            PotterySherdSpells.PENDING_EFFECTS.add(new PotterySherdSpells.DelayedSpellEffect(
                3 + chainIndex * 4, () -> {
                    ProjectileSpawner.spawnSpellTrail(world, fromBlock, toBlock,
                        net.minecraft.particle.ParticleTypes.ELECTRIC_SPARK,
                        net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME, 10, 1.5);
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.ELECTRIC_SPARK,
                        toBlock.getX() + 0.5, toBlock.getY() + 1.0, toBlock.getZ() + 0.5,
                        20, 0.3, 0.5, 0.3, 0.15);
                    if (arcSoaked) {
                        world.spawnParticles(net.minecraft.particle.ParticleTypes.SPLASH,
                            toBlock.getX() + 0.5, toBlock.getY() + 1.0, toBlock.getZ() + 0.5,
                            10, 0.3, 0.3, 0.3, 0.1);
                    }
                    world.playSound(null, toBlock,
                        net.minecraft.sound.SoundEvents.ENTITY_LIGHTNING_BOLT_IMPACT,
                        net.minecraft.sound.SoundCategory.HOSTILE, 0.7f, 1.2f + depth * 0.1f);
                }));
            // A mace-slam shockwave ripples out at each struck tile, staggered on
            // the SAME cadence as the arc above (3 + chainIndex * 4 ticks) so the
            // impacts ripple outward in step with the bolt. The shockwave stages
            // itself via its own phase delay; it layers on top of the arc + thunder
            // rather than replacing them.
            com.crackedgames.craftics.vfx.boss.BossAttackVfx.shockwaveImpact(
                world, arena, currentEnemy, positions.get(link.index()), 3 + chainIndex * 4);
            prevBlock = linkBlock;
            chainIndex++;
        }
        if (chain.size() > 1) {
            sendMessage("§7  (" + chain.size() + " combatants conducted the bolt)");
        }
    }

    /** A member's Soaked state read from their OWN effects: the live field for the player
     *  this manager currently tracks, the per-UUID map for everyone else. */
    private boolean isPartyMemberSoaked(ServerPlayerEntity member) {
        if (member == this.player) {
            return combatEffects.hasEffect(CombatEffects.EffectType.SOAKED);
        }
        CombatEffects fx = playerCombatEffects.get(member.getUuid());
        return fx != null && fx.hasEffect(CombatEffects.EffectType.SOAKED);
    }

    /**
     * Apply status effects from boss area attacks.
     */
    private void applyBossAreaEffect(String effectName) {
        switch (effectName) {
            case "frost_wave", "glacial_trap" -> {
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 2, 1);
                sendMessage("§b  Frostbite! Slowness II for 2 turns.");
            }
            case "slowness", "blizzard", "frost", "frost_harpoon", "whiteout_ring" -> {
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 2, 0);
                sendMessage("§b  Slowness applied! (-1 movement for 2 turns)");
            }
            case "blizzard_stun" -> {
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 2, 0);
                addEffectHooked(CombatEffects.EffectType.MINING_FATIGUE, 1, 9);
                sendMessage("§b  Frozen solid! Stunned + slowed!");
            }
            case "ground_pound" -> {
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 1, 0);
                sendMessage("§7  The shockwave staggers you! (-1 movement for 1 turn)");
            }
            case "weakness", "cursed_fog", "wail", "hex_snare" -> {
                addEffectHooked(CombatEffects.EffectType.WEAKNESS, 2, 0);
                sendMessage("§7  Weakness applied! (-2 attack for 2 turns)");
            }
            case "ender_roar" -> {
                addEffectHooked(CombatEffects.EffectType.BLINDNESS, 2, 0);
                sendMessage("§5  The Void Walker's roar blinds you! (-2 range for 2 turns)");
            }
            case "darkness_pulse" -> {
                // Darkness, not blindness: the pulse is the arena going dark around you, which
                // is what hides the things in it, rather than a range penalty on your own
                // attacks. Both are applied - it blinds AND it hides - for the same 4 turns.
                addEffectHooked(CombatEffects.EffectType.DARKNESS, 4, 0);
                addEffectHooked(CombatEffects.EffectType.BLINDNESS, 4, 0);
                sendMessage("§8  The Warden's darkness pulse swallows the light! (4 turns)");
            }
            case "sonic_boom" -> {
                // The boom does not just hurt: it finds you. Marked doubles what everything
                // does to you from here, and the Warden hunts whoever is wearing it (see
                // tickWardenMarkHunt) until it lapses.
                addEffectHooked(CombatEffects.EffectType.MARKED, SONIC_MARK_TURNS, 0);
                addEffectHooked(CombatEffects.EffectType.DARKNESS, SONIC_MARK_TURNS, 0);
                addEffectHooked(CombatEffects.EffectType.BLINDNESS, SONIC_MARK_TURNS, 0);
                sonicMarkedPlayers.add(player.getUuid());
                sendMessage("§3  The sonic boom rips through you! §8Marked, blinded and lost in the dark ("
                    + SONIC_MARK_TURNS + " turns)");
            }
            case "tremor_stomp" -> {
                // Tremor pushes dust into your eyes -short blindness
                addEffectHooked(CombatEffects.EffectType.BLINDNESS, 2, 0);
                sendMessage("§8  The tremor kicks up blinding dust! (2 turns)");
            }
            case "null_burst" -> {
                addEffectHooked(CombatEffects.EffectType.MINING_FATIGUE, 1, 0);
                sendMessage("§5  Null energy disrupts your footing! (-1 AP next turn)");
            }
            case "burning", "fire", "magma", "raining_fireball", "magma_eruption" -> {
                if (!combatEffects.hasFireResistance()) {
                    addEffectHooked(CombatEffects.EffectType.BURNING, 2, 0);
                    sendMessage("§6  You're burning for 2 turns!");
                }
            }
            case "sand_burial" -> {
                // Buried alive: the same amp-9 MINING_FATIGUE stun the webs use.
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 1, 0);
                addEffectHooked(CombatEffects.EffectType.MINING_FATIGUE, 1, 9);
                sendMessage("§6  The sand swallows you! Stunned + slowed!");
            }
            case "sandstorm" -> {
                addEffectHooked(CombatEffects.EffectType.WEAKNESS, 2, 0);
                sendMessage("§6  Sand scours your eyes! Weakness for 2 turns.");
            }
            case "curse_of_sands" -> {
                curseOfSandsTurns = Math.max(curseOfSandsTurns, CURSE_OF_SANDS_DURATION);
                sendMessage("§6  §lCURSED!§r §6Every tile you leave sprouts a sand mine! §8("
                    + curseOfSandsTurns + " turns)");
            }
            case "entangle" -> {
                addEffectHooked(CombatEffects.EffectType.MINING_FATIGUE, 1, 9);
                sendMessage("§2  Roots grip your legs! Rooted for 1 turn!");
            }
            case "trident_storm" -> {
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 1, 0);
                sendMessage("§9  Drenched! Slowness for 1 turn.");
            }
            case "poison", "venom", "web_poison" -> {
                addEffectHooked(CombatEffects.EffectType.POISON, 3, 0);
                sendMessage("§2  Poisoned for 3 turns!");
            }
            case "wither", "wither_slash" -> {
                addEffectHooked(CombatEffects.EffectType.WITHER, 3, 0);
                sendMessage("§8  Withered for 3 turns! (damage ramps up)");
            }
            case "wither_decay" -> {
                // Decay aura tick -short refresh of Wither so standing in
                // the aura every turn keeps the player at peak Wither stacks.
                addEffectHooked(CombatEffects.EffectType.WITHER, 3, 0);
                sendMessage("§8  Decay aura corrupts you! (Withered 3 turns)");
            }
            case "wither_explosion" -> {
                // Phase 2 transition burst -heavier and longer-lasting.
                addEffectHooked(CombatEffects.EffectType.WITHER, 4, 1);
                sendMessage("§4  The Wither's roar withers you to the bone! (Wither II, 4 turns)");
            }
            case "darkness", "lights_out" -> {
                // Check if the player is standing in a lit zone (torch/lantern)
                if (!isPositionLit(arena.getPlayerGridPos())) {
                    addEffectHooked(CombatEffects.EffectType.DARKNESS, 2, 0);
                    sendMessage("§8  Darkness falls! Vision reduced (-1 range for 2 turns).");
                } else {
                    sendMessage("§8  Darkness tries to encroach... §eYour light holds it back!");
                }
            }
            // === The Hollow King ===
            case "hollow_shore_up" -> sendMessage(
                "§8§l⛏ §7The Hollow King drives in fresh props. §fThe stone holds him now.");
            case "hollow_collapse" -> {
                // The dust is the point: a collapse that only did damage read as another
                // orange square. This blinds briefly, which is what being under a ceiling
                // that just came down should feel like.
                addEffectHooked(CombatEffects.EffectType.BLINDNESS, 1, 0);
                sendMessage("§8§l☠ TOTAL COLLAPSE! §r§7The props gave way and the roof came in.");
            }
            case "hollow_shrapnel" -> sendMessage(
                "§6§l✦ Shrapnel! §r§7A shattered prop tears down the lane.");
            case "hollow_mine" -> sendMessage(
                "§7⛏ The Hollow King cuts straight through the rock to reach you.");
            case "web_spray" -> {
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 1, 0);
                // Stun: use MINING_FATIGUE with high amplifier to zero out AP next turn
                addEffectHooked(CombatEffects.EffectType.MINING_FATIGUE, 1, 9);
                sendMessage("§7  Webbed! Stunned + slowed!");
            }
            case "web_spray_poison" -> {
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 1, 0);
                addEffectHooked(CombatEffects.EffectType.POISON, 2, 0);
                // Stun: use MINING_FATIGUE with high amplifier to zero out AP next turn
                addEffectHooked(CombatEffects.EffectType.MINING_FATIGUE, 1, 9);
                sendMessage("§7  Webbed! Stunned + slowed + poisoned!");
            }
            default -> {} // No special effect
        }
    }

    /**
     * Spawn thematic particles for boss area attacks based on the attack's effect name.
     * Each boss gets unique particles that match their identity.
     */
    private void spawnAreaAttackParticles(ServerWorld world, String effectName,
                                          double cx, double cy, double cz, double spread, int radius) {
        if (effectName == null) {
            // Generic fallback
            world.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION,
                cx, cy, cz, 3, spread, 0.5, spread, 0.0);
            return;
        }
        switch (effectName) {
            // === The Hollow King ===
            case "hollow_collapse" -> {
                // Falling stone, then the dust rolling out along the floor after it.
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                    cx, cy + 2.0, cz, 18, spread, 1.2, spread, 0.04);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ASH,
                    cx, cy + 1.0, cz, 30, spread, 1.0, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                    cx, cy + 0.3, cz, 10, spread, 0.2, spread, 0.05);
            }
            case "hollow_shrapnel" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                    cx, cy + 0.8, cz, 14, spread, 0.4, spread, 0.12);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE,
                    cx, cy + 0.6, cz, 8, spread, 0.3, spread, 0.02);
            }
            case "hollow_shore_up" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                    cx, cy + 0.5, cz, 10, spread, 0.6, spread, 0.01);
            }
            // === Molten King ===
            case "magma_eruption" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LAVA, cx, cy, cz, 15, spread, 0.8, spread, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.FLAME, cx, cy + 0.5, cz, 20, spread, 1.0, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE, cx, cy, cz, 8, spread, 0.5, spread, 0.01);
            }
            // === Ender Dragon ===
            // The breath's own colours. These used to be spawned by the marching-wave tick;
            // the wave is gone and the breath resolves as a normal tile-area hit now, so the
            // look lives here instead of vanishing into the generic explosion fallback.
            case "dragon_breath", "dragon_swoop" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.DRAGON_BREATH,
                    cx, cy - 0.2, cz, 18, spread, 0.4, spread, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
                    cx, cy, cz, 12, spread, 0.5, spread, 0.05);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME,
                    cx, cy + 0.2, cz, 10, spread, 0.5, spread, 0.02);
            }
            // === Frostbound Huntsman ===
            case "blizzard" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SNOWFLAKE, cx, cy + 1.0, cz, 25, spread, 1.2, spread, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy + 0.5, cz, 10, spread, 0.6, spread, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ENCHANTED_HIT, cx, cy, cz, 6, spread, 0.3, spread, 0.0);
            }
            case "blizzard_stun" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SNOWFLAKE, cx, cy + 0.5, cz, 30, 0.3, 0.8, 0.3, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ENCHANTED_HIT, cx, cy + 0.3, cz, 12, 0.2, 0.4, 0.2, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy, cz, 8, 0.3, 0.2, 0.3, 0.0);
            }
            case "glacial_trap" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SNOWFLAKE, cx, cy, cz, 12, spread, 0.3, spread, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ENCHANTED_HIT, cx, cy + 0.2, cz, 8, spread, 0.2, spread, 0.0);
            }
            case "frost_harpoon" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SNOWFLAKE, cx, cy + 0.7, cz, 16, spread, 0.6, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SWEEP_ATTACK, cx, cy + 0.4, cz, 3, spread, 0.3, spread, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy, cz, 10, spread, 0.4, spread, 0.01);
            }
            case "whiteout_ring" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SNOWFLAKE, cx, cy + 0.8, cz, 20, spread, 0.9, spread, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy + 0.5, cz, 12, spread, 0.5, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ENCHANTED_HIT, cx, cy, cz, 6, spread, 0.3, spread, 0.0);
            }
            case "frost_wave" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SNOWFLAKE, cx, cy + 0.9, cz, 18, spread, 0.7, spread, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy + 0.4, cz, 10, spread, 0.4, spread, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ENCHANTED_HIT, cx, cy + 0.2, cz, 6, spread, 0.2, spread, 0.0);
            }
            // === Hollow King ===
            case "cave_in" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE, cx, cy + 0.5, cz, 12, spread, 0.8, spread, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ASH, cx, cy, cz, 20, spread + 0.5, 1.0, spread + 0.5, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy, cz, 8, spread, 0.4, spread, 0.0);
            }
            case "hollow_tnt_prime" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE, cx, cy + 0.6, cz, 12, 0.3, 0.4, 0.3, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.FLAME, cx, cy + 0.5, cz, 8, 0.2, 0.3, 0.2, 0.01);
            }
            case "rubble_toss" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE, cx, cy + 0.5, cz, 10, spread, 0.6, spread, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, cx, cy + 0.3, cz, 8, spread, 0.4, spread, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy, cz, 8, spread, 0.3, spread, 0.0);
            }
            case "lights_out" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE, cx, cy, cz, 15, spread + 1, 1.0, spread + 1, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE, cx, cy + 0.5, cz, 25, spread + 2, 1.5, spread + 2, 0.01);
            }
            // === Rockbreaker ===
            case "seismic_slam" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE, cx, cy, cz, 15, spread, 0.3, spread, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy + 0.2, cz, 10, spread, 0.4, spread, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, cx, cy + 0.3, cz, 12, spread, 0.5, spread, 0.02);
            }
            case "boulder_toss" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy + 0.5, cz, 8, 0.3, 0.5, 0.3, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE, cx, cy, cz, 6, 0.4, 0.3, 0.4, 0.0);
            }
            case "avalanche" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ASH, cx, cy + 1.5, cz, 30, spread + 1, 1.5, spread + 1, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy + 0.8, cz, 15, spread, 1.0, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE, cx, cy, cz, 10, spread, 0.5, spread, 0.01);
            }
            case "ground_pound" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION, cx, cy + 0.3, cz, 3, spread, 0.3, spread, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE, cx, cy, cz, 20, spread + 1, 0.2, spread + 1, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, cx, cy + 0.5, cz, 15, spread + 1, 0.6, spread + 1, 0.03);
            }
            // === Sandstorm Pharaoh ===
            case "sandstorm" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ASH, cx, cy + 1.0, cz, 30, spread + 0.5, 1.5, spread + 0.5, 0.04);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE, cx, cy, cz, 12, spread, 0.8, spread, 0.02);
            }
            case "sand_burial" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ASH, cx, cy, cz, 15, spread, 0.3, spread, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy + 0.1, cz, 6, spread, 0.2, spread, 0.0);
            }
            case "plant_mine" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ASH, cx, cy, cz, 3, 0.2, 0.1, 0.2, 0.0);
            }
            case "curse_of_sands" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ASH, cx, cy + 0.5, cz, 12, 0.3, 0.5, 0.3, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.WITCH, cx, cy + 1.0, cz, 5, 0.2, 0.3, 0.2, 0.0);
            }
            // === Chorus Mind ===
            case "resonance_cascade" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD, cx, cy + 0.5, cz, 20, spread + 1, 1.0, spread + 1, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL, cx, cy, cz, 30, spread, 1.5, spread, 0.5);
            }
            case "entangle" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.HAPPY_VILLAGER, cx, cy, cz, 15, spread, 0.4, spread, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.COMPOSTER, cx, cy + 0.3, cz, 10, spread, 0.3, spread, 0.0);
            }
            case "chorus_bomb", "chorus_bomb_pull" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL, cx, cy, cz, 25, spread, 1.0, spread, 0.5);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL, cx, cy + 0.5, cz, 15, spread, 0.8, spread, 0.3);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD, cx, cy + 0.3, cz, 5, spread, 0.5, spread, 0.01);
            }
            // === Ashen Warlord ===
            case "ash_storm" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ASH, cx, cy + 1.0, cz, 30, spread + 0.5, 1.5, spread + 0.5, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME, cx, cy + 0.5, cz, 10, spread, 0.8, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE, cx, cy, cz, 8, spread, 0.5, spread, 0.01);
            }
            case "wither_slash" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL, cx, cy + 0.5, cz, 12, spread, 0.6, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE, cx, cy, cz, 8, spread, 0.3, spread, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, cx, cy + 0.3, cz, 6, spread, 0.4, spread, 0.0);
            }
            case "fire_pillar_x" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.FLAME, cx, cy + 1.0, cz, 20, spread, 1.5, spread, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME, cx, cy + 0.5, cz, 10, spread, 1.0, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE, cx, cy, cz, 8, spread, 0.5, spread, 0.01);
            }
            // === Bastion Brute ===
            case "rampage" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, cx, cy + 0.5, cz, 20, spread, 0.8, spread, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.DAMAGE_INDICATOR, cx, cy + 0.3, cz, 10, spread, 0.5, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIMSON_SPORE, cx, cy, cz, 15, spread + 0.5, 0.6, spread + 0.5, 0.01);
            }
            // === Broodmother ===
            case "web_spray" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ITEM_SLIME, cx, cy + 0.5, cz, 15, spread, 0.8, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy, cz, 8, spread, 0.3, spread, 0.0);
            }
            case "web_spray_poison" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ITEM_SLIME, cx, cy + 0.5, cz, 15, spread, 0.8, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.HAPPY_VILLAGER, cx, cy + 0.3, cz, 8, spread, 0.4, spread, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy, cz, 5, spread, 0.3, spread, 0.0);
            }
            // === Broodmother ceiling attacks ===
            case "ceiling_slam" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy, cz, 20, spread + 0.5, 0.3, spread + 0.5, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, cx, cy + 0.5, cz, 15, spread, 0.8, spread, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ITEM_SLIME, cx, cy, cz, 10, spread, 0.5, spread, 0.01);
            }
            case "hunting_dive_slam" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy, cz, 25, spread + 0.5, 0.3, spread + 0.5, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, cx, cy + 0.5, cz, 20, spread, 1.0, spread, 0.04);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ITEM_SLIME, cx, cy, cz, 15, spread + 0.3, 0.6, spread + 0.3, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ENCHANTED_HIT, cx, cy + 0.3, cz, 8, spread, 0.4, spread, 0.01);
            }
            case "pounce" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, cx, cy + 0.3, cz, 12, spread, 0.5, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy, cz, 8, spread, 0.3, spread, 0.01);
            }
            // === Hexweaver ===
            case "cursed_fog" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.WITCH, cx, cy + 0.8, cz, 20, spread, 1.0, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE, cx, cy, cz, 15, spread + 0.5, 0.5, spread + 0.5, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL, cx, cy + 0.5, cz, 6, spread, 0.6, spread, 0.01);
            }
            case "hex_snare" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.WITCH, cx, cy + 0.8, cz, 18, spread, 0.8, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ENCHANT, cx, cy + 0.5, cz, 16, spread, 0.5, spread, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL, cx, cy, cz, 10, spread, 0.4, spread, 0.01);
            }
            // === Shulker Architect ===
            case "bullet_storm" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD, cx, cy + 0.5, cz, 15, spread, 0.8, spread, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ENCHANTED_HIT, cx, cy + 0.3, cz, 10, spread, 0.5, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ELECTRIC_SPARK, cx, cy, cz, 8, spread, 0.3, spread, 0.01);
            }
            // === Tidecaller ===
            case "trident_storm" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SPLASH, cx, cy + 0.5, cz, 20, spread, 0.8, spread, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.BUBBLE, cx, cy, cz, 15, spread, 0.5, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.DRIPPING_WATER, cx, cy + 1.0, cz, 8, spread, 0.3, spread, 0.0);
            }
            // === Void Herald ===
            case "lightning_strike" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.ELECTRIC_SPARK, cx, cy + 1.5, cz, 25, spread, 2.0, spread, 0.05);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.FLASH, cx, cy + 1.0, cz, 3, 0.1, 0.1, 0.1, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD, cx, cy, cz, 8, spread, 0.5, spread, 0.01);
            }
            case "blink_assault" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL, cx, cy, cz, 20, spread, 1.0, spread, 0.5);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL, cx, cy + 0.5, cz, 12, spread, 0.8, spread, 0.3);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, cx, cy + 0.3, cz, 8, spread, 0.4, spread, 0.02);
            }
            // === Warden ===
            case "darkness_pulse" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SCULK_SOUL, cx, cy + 0.8, cz, 25, spread + 0.5, 1.0, spread + 0.5, 0.04);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE, cx, cy + 0.3, cz, 20, spread, 0.6, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE, cx, cy, cz, 15, spread + 0.3, 0.4, spread + 0.3, 0.01);
            }
            case "tremor_stomp" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD, cx, cy, cz, 20, spread + 0.5, 0.3, spread + 0.5, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE, cx, cy + 0.2, cz, 12, spread, 0.4, spread, 0.01);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SCULK_SOUL, cx, cy + 0.5, cz, 8, spread, 0.5, spread, 0.02);
            }
            case "sonic_boom" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SONIC_BOOM, cx, cy + 1.0, cz, 1, 0.0, 0.0, 0.0, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SCULK_SOUL, cx, cy + 0.8, cz, 12, spread, 0.6, spread, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE, cx, cy + 0.4, cz, 8, spread, 0.4, spread, 0.02);
            }
            // === Void Walker ===
            case "null_burst" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.REVERSE_PORTAL, cx, cy + 0.6, cz, 25, spread, 0.8, spread, 0.25);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL, cx, cy + 1.0, cz, 18, spread + 0.3, 1.0, spread + 0.3, 0.3);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD, cx, cy + 0.3, cz, 10, spread, 0.4, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.FLASH, cx, cy + 0.5, cz, 2, 0.0, 0.0, 0.0, 0.0);
            }
            case "ender_roar" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE, cx, cy + 0.8, cz, 20, spread + 0.5, 0.6, spread + 0.5, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL, cx, cy + 0.5, cz, 20, spread + 0.3, 0.8, spread + 0.3, 0.35);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SCULK_SOUL, cx, cy + 0.9, cz, 6, spread, 0.5, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SONIC_BOOM, cx, cy + 1.0, cz, 1, 0.0, 0.0, 0.0, 0.0);
            }
            // === Wither Boss ===
            case "wither_explosion" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL, cx, cy + 1.0, cz, 25, spread + 1, 1.5, spread + 1, 0.04);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE, cx, cy + 0.5, cz, 15, spread, 1.0, spread, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE, cx, cy, cz, 20, spread + 0.5, 0.8, spread + 0.5, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION, cx, cy, cz, 5, spread, 0.5, spread, 0.0);
            }
            // === Wailing Revenant ===
            case "soul_chain" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL, cx, cy + 0.5, cz, 12, 0.3, 0.6, 0.3, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME, cx, cy + 0.3, cz, 8, 0.2, 0.4, 0.2, 0.01);
            }
            case "wail_despair", "wail_despair_slow" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SCULK_SOUL, cx, cy + 1.0, cz, 15, spread + 1, 1.5, spread + 1, 0.03);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL, cx, cy + 0.5, cz, 20, spread + 2, 1.0, spread + 2, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE, cx, cy, cz, 10, spread, 0.5, spread, 0.01);
            }
            case "raining_fireball" -> {
                // Individual fireball impact from the sky
                world.spawnParticles(net.minecraft.particle.ParticleTypes.FLAME, cx, cy + 2.0, cz, 12, 0.2, 1.5, 0.2, 0.04);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LAVA, cx, cy + 0.5, cz, 6, 0.3, 0.3, 0.3, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE, cx, cy + 1.0, cz, 5, 0.2, 0.8, 0.2, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION, cx, cy + 0.5, cz, 1, 0.1, 0.1, 0.1, 0.0);
            }
            // === Revenant ===
            case "death_charge" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE, cx, cy + 0.5, cz, 12, spread, 0.8, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT, cx, cy + 0.3, cz, 8, spread, 0.5, spread, 0.01);
            }
            // === Ground Slam (Bastion Brute cross fire) ===
            case "ground_slam" -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LAVA, cx, cy + 0.5, cz, 15, spread, 0.8, spread, 0.02);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.FLAME, cx, cy + 0.3, cz, 10, spread, 0.4, spread, 0.01);
            }
            // === Generic fallback for unknown effects ===
            default -> {
                world.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION,
                    cx, cy, cz, 3, spread, 0.5, spread, 0.0);
            }
        }
    }

    private boolean isFrostboundBossAttacker() {
        return currentEnemy != null && currentEnemy.isBoss()
            && "boss:snowy".equals(currentEnemy.getAiKey());
    }

    private void applyFrostboundSlownessOnHit() {
        addEffectHooked(CombatEffects.EffectType.SLOWNESS, 2, 1);
        sendMessage("§b  Frostbound chill! Slowness II for 2 turns.");
    }

    /**
     * Resolve terrain creation/transformation.
     */
    // === Fire =================================================================
    // A lit tile is a real flame block at Y+1 sitting on an intact floor, and it runs a
    // three-stage burn: flames -> magma -> burned out. The stage countdown lives HERE, in
    // burningTiles, not in GridTile.turnsRemaining: tickTemporaryTerrain runs before the
    // fire tick and would expire a one-turn FIRE tile back to its original block before we
    // ever got to advance it. Instead each stage is pinned with a long temporary duration
    // (BURN_HOLD_TURNS) so the tile stays put until this system moves it on, while still
    // counting as temporary terrain that endCombat restores. The ORIGINAL type/block is
    // captured by the first setTemporaryType and survives every later stage, because
    // setTemporaryType only re-captures when the tile isn't already temporary.

    /** Where a burning tile is in its lifecycle. */
    private enum BurnStage { FLAMES, MAGMA }

    /**
     * What is lighting a tile. Only the fuel requirement differs, and only one of the three
     * has one: fuel decides whether a fire SPREADS, not whether it can burn at all.
     */
    private enum Ignition {
        /** Ordinary fire reaching the next tile. The fuel chain - stops where fuel runs out. */
        SPREAD,
        /** Soul fire reaching the next tile. Needs no fuel and carries the blue flame with it. */
        SOUL_SPREAD,
        /** A player striking a light by hand. Needs no fuel; the ground picks the flame. */
        STRUCK
    }

    /**
     * @param restores  tile comes back as itself (netherrack) rather than burning to dirt.
     * @param intensity how much further this flame can travel: each tile it spreads to is
     *                  born one weaker, and a fire at 0 has run out of reach and only burns
     *                  where it stands. {@link #INFINITE_INTENSITY} never decays.
     */
    private record BurnState(BurnStage stage, int turnsLeft, boolean restores, int intensity,
                             net.minecraft.block.Block fuel) {}

    /**
     * Spread budget by source.
     *
     * <p>A fire is not just "lit" or "not lit" - it carries how far it can still travel.
     * A hand-struck light gets {@link #STRUCK_INTENSITY} tiles of reach and dies out at the
     * edge of it, so flint and steel is a tool with a radius rather than something that
     * eventually eats the arena. Soul fire is the exception: it burns without fuel and it
     * does not tire, so it never loses reach.
     */
    private static final int STRUCK_INTENSITY = 3;
    /** Soul fire, and anything it lights. Never decays. */
    private static final int INFINITE_INTENSITY = Integer.MAX_VALUE;

    /** Long enough that tickTemporaryTerrain never expires a stage out from under us,
     *  short of permanent so endCombat's temporary-terrain restore still claims the tile. */
    private static final int BURN_HOLD_TURNS = 9999;

    /** Tiles mid-burn, in ignition order. */
    private final java.util.LinkedHashMap<GridPos, BurnState> burningTiles = new java.util.LinkedHashMap<>();

    /**
     * Tiles that finished burning and refuse to catch light again yet, by turns remaining.
     * Ground that comes back as itself gets a short cooldown; ground that burnt to ash is
     * entered at {@link #SPENT_FOREVER} and never leaves - its fuel is gone for this fight.
     */
    private final java.util.HashMap<GridPos, Integer> fireproofTiles = new java.util.HashMap<>();

    /** Cooldown value meaning "this tile has nothing left to burn". Never decremented. */
    private static final int SPENT_FOREVER = Integer.MAX_VALUE;

    /** Floor-level BlockPos for a grid tile. The flame overlay is this {@code .up(1)},
     *  which is also what {@code arena.gridToBlockPos} returns. */
    private BlockPos tileFloorPos(GridPos pos) {
        return new BlockPos(
            arena.getOrigin().getX() + pos.x(),
            arena.getOrigin().getY(),
            arena.getOrigin().getZ() + pos.z());
    }

    /** Remove the flame block above a tile, leaving anything else at Y+1 alone. */
    private void clearFlameOverlay(ServerWorld world, BlockPos floor) {
        var above = world.getBlockState(floor.up(1));
        if (above.isOf(Blocks.FIRE) || above.isOf(Blocks.SOUL_FIRE)) {
            world.setBlockState(floor.up(1), Blocks.AIR.getDefaultState(),
                net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);
        }
    }

    /**
     * Paint a tile's current block into the world. FIRE goes into the Y+1 overlay slot with
     * the floor left intact (it is a placed flame, not a floor material); every other type
     * paints at floor Y and clears any flame that was standing there.
     */
    private void paintTileBlock(ServerWorld world, GridPos pos, GridTile tile) {
        BlockPos floor = tileFloorPos(pos);
        if (tile.getType().isFlames()) {
            ensureSoulBase(world, floor, tile.getType());
            world.setBlockState(floor.up(1), tile.getBlockType().getDefaultState(),
                net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);
            return;
        }
        clearFlameOverlay(world, floor);
        // RUBBLE rides with OBSTACLE: it is a blocking tile, and painting it at floor level
        // left a boulder that read as a paving slab while the grid refused to let anything
        // cross it - a wall you can neither see nor walk through.
        if (tile.getType() == TileType.OBSTACLE || tile.getType() == TileType.RUBBLE) {
            // Walls stand in the obstacle layer (Y+1), same slot placeObstacleTile uses, with
            // the floor left alone underneath. Matters when soul fire has eaten a stone wall
            // and the tile restores: painted at floor Y the wall would come back as a paving
            // slab and the tile would read as blocked with nothing visibly there.
            world.setBlockState(floor.up(1), tile.getBlockType().getDefaultState(),
                net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);
            return;
        }
        world.setBlockState(floor, tile.getBlockType().getDefaultState());
    }

    /**
     * Scorch a tile's floor into soul soil when soul fire is about to stand on it, unless the
     * ground is already soul sand or soul soil.
     *
     * <p>Vanilla will not let soul fire exist anywhere else. {@code SoulFireBlock.canPlaceAt}
     * is exactly {@code isSoulBase(state below)} - the {@code SOUL_FIRE_BASE_BLOCKS} tag, i.e.
     * soul sand and soul soil - and {@code SoulFireBlock.getStateForNeighborUpdate} returns
     * AIR the moment that check fails. {@code FORCE_STATE} gets the flame in, but it does not
     * keep it: the first neighbour update to reach the tile deletes it, and every floor repaint
     * on an adjacent tile sends one (the non-flame branch below writes with the default
     * NOTIFY_NEIGHBORS flags). The flame would land, vanish within a tick or two, and leave
     * nothing but its particles - soul fire that looks like a particle effect because that is
     * all that survived.
     *
     * <p>So give it legal footing. Every route out of a burn repaints the floor from the tile's
     * own record - flames collapse to an EMBER magma block, {@link #finishBurn} lays ash or
     * restores the original block, {@link #tickTemporaryTerrain} repaints on expiry - so the
     * soul soil is only ever the substrate under a live flame and reverts without extra
     * bookkeeping. It reads right, too: soul fire scorches ground into soul soil.
     */
    private void ensureSoulBase(ServerWorld world, BlockPos floor, TileType flames) {
        if (flames != TileType.SOUL_FIRE) return;
        if (net.minecraft.block.SoulFireBlock.isSoulBase(world.getBlockState(floor))) return;
        world.setBlockState(floor, Blocks.SOUL_SOIL.getDefaultState());
    }

    /**
     * Set one tile alight, if it has anything left to burn. Clears whatever was standing on
     * it (tall grass, a log obstacle) so the fuel is visibly consumed, drops a flame block
     * at Y+1, and enters the tile into the burn cycle.
     *
     * @param kind where the flame came from, which decides whether fuel is required
     * @return true if the tile was ignited
     */
    private boolean igniteTile(GridPos pos, Ignition kind) {
        return igniteTile(pos, kind, defaultIntensity(kind));
    }

    /** The reach a flame from {@code kind} starts with when no parent hands one down. */
    private static int defaultIntensity(Ignition kind) {
        return kind == Ignition.SOUL_SPREAD ? INFINITE_INTENSITY : STRUCK_INTENSITY;
    }

    /**
     * As {@link #igniteTile(GridPos, Ignition)}, but with an explicit spread budget - what a
     * spreading fire hands its children, one less than its own.
     *
     * <p>Also where fires MERGE. A tile already alight is not simply refused: if the arriving
     * flame is the stronger one it overwrites what is there, so a soul fire washing over an
     * ordinary burn turns it blue and endless rather than bouncing off it, and a fresh strike
     * re-arms ground whose fire had nearly run out. The weaker flame never downgrades the
     * stronger, so two fires meeting always resolve to the fiercer of the two.
     */
    private boolean igniteTile(GridPos pos, Ignition kind, int intensity) {
        if (arena == null || player == null || pos == null) return false;
        if (!arena.isInBounds(pos)) return false;
        BurnState existing = burningTiles.get(pos);
        if (existing != null) {
            if (intensity > existing.intensity()) {
                boolean toSoul = kind == Ignition.SOUL_SPREAD;
                burningTiles.put(pos, new BurnState(existing.stage(), existing.turnsLeft(),
                    existing.restores(), intensity, existing.fuel()));
                GridTile merging = arena.getTile(pos);
                if (toSoul && merging != null && merging.getType() == TileType.FIRE) {
                    merging.setTemporaryType(TileType.SOUL_FIRE, BURN_HOLD_TURNS);
                    paintTileBlock((ServerWorld) player.getEntityWorld(), pos, merging);
                }
            }
            return false;   // no NEW tile caught; the count of spread tiles is unchanged
        }
        // The cooldown is the ONE thing soul fire respects: a tile that has already burned
        // gets its turn off, or a soul fire would sit on the same ground relighting it
        // forever and the front would never actually go out.
        if (fireproofTiles.containsKey(pos)) return false;   // still cooling down
        GridTile tile = arena.getTile(pos);
        if (tile == null) return false;

        boolean fuel = FlammableTiles.isFlammable(tile);
        if (!fuel) {
            // Fuel decides whether a fire SPREADS, not whether it can exist. Ordinary fire
            // spreading is a fuel chain and stops here; a struck light or soul fire does not
            // need any. What all three still refuse is ground that can't hold a flame at all
            // (void, water, lava) and permanent walls - the same blocks a pickaxe refuses.
            if (kind == Ignition.SPREAD) return false;
            if (tile.isPermanent() || !FlammableTiles.canHoldFlame(tile)) return false;
            // A hand-struck light goes on the GROUND. Soul fire is the only thing that eats
            // through a standing wall, so a non-fuel obstacle turns a strike away - otherwise
            // flint and steel would quietly become a wall-removal tool.
            if (kind == Ignition.STRUCK && !tile.isWalkable()) return false;
        }

        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos floor = tileFloorPos(pos);
        // Read from the floor block BEFORE the tile is overwritten - once the burn starts,
        // getBlockType() is the fire/magma of whatever stage the tile is in. Soul ground
        // burns blue, and so does anything soul fire spread to. Ground that was never fuel
        // rebuilds itself rather than being scorched to dirt: soul fire eating a stone
        // arena should leave stone behind, not a field of soil.
        boolean restores = !fuel || FlammableTiles.restoresAfterBurning(tile.getBlockType());
        // What was actually burning, kept for the burnt-out block to be chosen from. By the
        // time the fire goes out the tile's own block is the fire or the magma it collapsed
        // into, so the fuel cannot be recovered then - it has to be remembered now.
        net.minecraft.block.Block fuelBlock = tile.getBlockType();
        boolean soul = kind == Ignition.SOUL_SPREAD
            || FlammableTiles.burnsSoulFire(tile.getBlockType());
        // Burn away the fuel standing on the tile (grass halves, a log, a fence) before
        // the flame takes its place at Y+1.
        world.setBlockState(floor.up(1), Blocks.AIR.getDefaultState(),
            net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);
        world.setBlockState(floor.up(2), Blocks.AIR.getDefaultState(),
            net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);

        tile.setTemporaryType(soul ? TileType.SOUL_FIRE : TileType.FIRE, BURN_HOLD_TURNS);
        paintTileBlock(world, pos, tile);
        // Soul fire is endless whatever lit it - ground that burns blue makes a blue fire,
        // and a blue fire never runs out of reach.
        burningTiles.put(pos, new BurnState(BurnStage.FLAMES,
            soul ? FlammableTiles.SOUL_FIRE_BURN_TURNS : FlammableTiles.FIRE_BURN_TURNS,
            restores, soul ? INFINITE_INTENSITY : Math.max(0, intensity), fuelBlock));

        world.spawnParticles(soul ? net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME
                : net.minecraft.particle.ParticleTypes.FLAME,
            floor.getX() + 0.5, floor.getY() + 1.2, floor.getZ() + 0.5,
            10, 0.3, 0.3, 0.3, 0.02);
        // Anything already standing in the new flames catches immediately rather than
        // waiting a full round for the next fire tick.
        applyFireTileBurn(pos);
        return true;
    }

    /**
     * Ignite any flammable tiles among {@code tiles}. Called by fire-based attacks - Fire
     * Aspect cone, bow Flame, fire knockback, flint &amp; steel, fire charges - so any
     * flammable ground or obstacle caught in the attack is set alight. Returns the count.
     */
    private int igniteFlammableTiles(Iterable<GridPos> tiles) {
        int ignited = 0;
        for (GridPos pos : tiles) {
            if (igniteTile(pos, Ignition.SPREAD)) ignited++;
        }
        return ignited;
    }

    /**
     * Resolve an {@link EnemyAction.IgniteTiles} - an enemy lighting an impact site and
     * leaving the rest to the arena. The listed tiles enter the burn cycle exactly as a
     * struck light does, so they spread a ring per turn, collapse to magma, and burn out on
     * their own schedule instead of holding a painted shape for a fixed count of turns.
     *
     * <p>Soul ignition goes in as {@link Ignition#SOUL_SPREAD} rather than STRUCK: the flame
     * came off a dragon, not a flint, so it carries the blue fire onto ground that has no
     * fuel and through standing walls. Tiles that are already burning, still cooling down, or
     * burnt to ash refuse quietly - {@link #igniteTile} owns those rules and nothing here
     * should second-guess them.
     */
    private void resolveIgniteTiles(EnemyAction.IgniteTiles ignite) {
        if (ignite.tiles() == null || ignite.tiles().isEmpty()) return;
        Ignition kind = ignite.soulFire() ? Ignition.SOUL_SPREAD : Ignition.STRUCK;
        int lit = 0;
        int dropped = 0;
        for (GridPos pos : ignite.tiles()) {
            if (!igniteTile(pos, kind)) continue;
            lit++;
            // Show HOW the fire arrived, for the attacks that care. Staggered per tile so a
            // multi-ember volley scatters down the sky instead of falling in lockstep. Only
            // tiles that actually caught get an ember - a mote falling onto ground that
            // refused to light would be a lie about where the burn is.
            if ("soul_ember".equals(ignite.effectName())) {
                com.crackedgames.craftics.vfx.boss.BossAttackVfx.fallingEmber(
                    (ServerWorld) player.getEntityWorld(), arena, currentEnemy, pos, dropped * 3);
                dropped++;
            }
        }
        if (lit > 0 && currentEnemy != null) {
            sendMessage((ignite.soulFire() ? "§b  " : "§6  ") + currentEnemy.getDisplayName()
                + " sets " + lit + " tile" + (lit == 1 ? "" : "s") + " alight!");
        }
    }

    /**
     * Advance every burning tile one turn, then spread from the tiles that were still
     * showing flames. Order matters and is the whole feel of the mechanic:
     *
     * <ol>
     *   <li>flames spread outward to adjacent flammable tiles,</li>
     *   <li>those flames collapse into a magma block for one more turn,</li>
     *   <li>the magma finishes burning - to dirt, or back to netherrack with a
     *       short cooldown before it can catch again.</li>
     * </ol>
     *
     * <p>Spread is computed from a snapshot taken before any stage advances, so a tile lit
     * this turn doesn't chain across the whole arena in a single round. Boss-placed FIRE
     * terrain seeds the spread too, but keeps its own duration instead of joining the
     * cycle - a telegraphed hazard is meant to clear itself, not scar the floor.
     */
    private void tickFire() {
        if (arena == null || player == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();

        var cooling = fireproofTiles.entrySet().iterator();
        while (cooling.hasNext()) {
            var entry = cooling.next();
            if (entry.getValue() == SPENT_FOREVER) continue;  // burnt to ash; never relights
            int left = entry.getValue() - 1;
            if (left <= 0) cooling.remove(); else entry.setValue(left);
        }

        // Snapshot the flame front before anything moves, tagging each source with whether it
        // is soul fire. The tag has to be taken NOW: by the time the spread runs, these tiles
        // have already collapsed to EMBER and their type no longer says which flame they were.
        java.util.LinkedHashMap<GridPos, Boolean> flameFront = new java.util.LinkedHashMap<>();
        for (int x = 0; x < arena.getWidth(); x++) {
            for (int z = 0; z < arena.getHeight(); z++) {
                GridTile t = arena.getTile(x, z);
                if (t != null && t.getType().isFlames()) {
                    flameFront.put(new GridPos(x, z), t.getType() == TileType.SOUL_FIRE);
                }
            }
        }

        // Advance the tiles that were already burning.
        int burnedOut = 0;
        for (GridPos pos : new java.util.ArrayList<>(burningTiles.keySet())) {
            BurnState state = burningTiles.get(pos);
            GridTile tile = arena.getTile(pos);
            if (tile == null) { burningTiles.remove(pos); continue; }
            int left = state.turnsLeft() - 1;
            if (left > 0) {
                burningTiles.put(pos, new BurnState(state.stage(), left, state.restores(),
                    state.intensity(), state.fuel()));
                continue;
            }
            if (state.stage() == BurnStage.FLAMES) {
                // Flames collapse into the magma block they leave behind.
                tile.setTemporaryType(TileType.EMBER, BURN_HOLD_TURNS);
                paintTileBlock(world, pos, tile);
                burningTiles.put(pos, new BurnState(BurnStage.MAGMA,
                    FlammableTiles.MAGMA_TURNS, state.restores(), state.intensity(), state.fuel()));
                BlockPos floor = tileFloorPos(pos);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                    floor.getX() + 0.5, floor.getY() + 1.1, floor.getZ() + 0.5,
                    6, 0.3, 0.2, 0.3, 0.01);
            } else {
                burningTiles.remove(pos);
                finishBurn(world, pos, tile, state.restores(), state.fuel());
                burnedOut++;
            }
        }

        // Spread from the snapshot. Each candidate remembers whether ANY adjacent source was
        // soul fire - soul wins the tie, because a tile touched by both should take the flame
        // that doesn't care whether there's fuel there.
        // Each candidate carries the soul flag AND the reach it would inherit: one less than
        // the strongest neighbour feeding it. A source with no reach left (intensity 0) is
        // still burning, it just cannot hand anything on, so it is skipped as a parent - that
        // is what makes a struck fire stop after STRUCK_INTENSITY tiles instead of walking
        // the whole arena. Soul fire is infinite and stays infinite in its children.
        java.util.LinkedHashMap<GridPos, Boolean> toIgnite = new java.util.LinkedHashMap<>();
        java.util.HashMap<GridPos, Integer> inherited = new java.util.HashMap<>();
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (var src : flameFront.entrySet()) {
            BurnState parent = burningTiles.get(src.getKey());
            // A flame tile with no burn state is painted terrain (a boss's fire, an arena
            // hazard) rather than something this cycle lit; give it the standard reach.
            int parentIntensity = parent != null ? parent.intensity() : STRUCK_INTENSITY;
            if (parentIntensity <= 0) continue;                       // burning, but spent
            int childIntensity = parentIntensity == INFINITE_INTENSITY
                ? INFINITE_INTENSITY : parentIntensity - 1;
            for (int[] d : dirs) {
                GridPos n = new GridPos(src.getKey().x() + d[0], src.getKey().z() + d[1]);
                if (!arena.isInBounds(n)) continue;
                toIgnite.merge(n, src.getValue(), (a, b) -> a || b);
                inherited.merge(n, childIntensity, Math::max);
            }
        }
        int spread = 0;
        int soulSpread = 0;
        for (var candidate : toIgnite.entrySet()) {
            if (!igniteTile(candidate.getKey(),
                    candidate.getValue() ? Ignition.SOUL_SPREAD : Ignition.SPREAD,
                    inherited.getOrDefault(candidate.getKey(), 0))) continue;
            spread++;
            if (candidate.getValue()) soulSpread++;
        }
        if (spread > 0) {
            sendMessage((soulSpread == spread ? "§bThe soul fire spreads to " : "§6The fire spreads to ")
                + spread + " more tile" + (spread == 1 ? "" : "s") + "!");
        }
        if (burnedOut > 0) {
            sendMessage("§8" + burnedOut + " tile" + (burnedOut == 1 ? "" : "s")
                + " burned out to ash.");
        }

        // Mobs standing in the flames catch once per round. Players are handled on their own
        // turn instead (turn-start hazard check + stepping into a tile), so a party member
        // never eats two applications for one round spent in the same fire.
        for (GridPos pos : flameFront.keySet()) {
            GridTile t = arena.getTile(pos);
            if (t == null || !t.getType().isFlames()) continue;
            CombatEntity occupant = arena.getOccupant(pos);
            if (occupant != null) applyFireTileBurn(occupant, t.getType());
        }
    }

    /**
     * Settle a tile that has finished burning - whether it ran its course or was put out
     * early. Ground that comes back as itself is restored and gets a short cooldown; anything
     * else is left as scorched dirt and retired for the fight.
     *
     * @param restores the burn's own record of whether this ground rebuilds itself, captured
     *                 at ignition while the original floor block was still readable
     */
    private void finishBurn(ServerWorld world, GridPos pos, GridTile tile, boolean restores,
                            net.minecraft.block.Block fuel) {
        if (restores) {
            // Nether ground comes back as itself, then shrugs off fire for a turn so
            // neighbouring flames can't relight the same tile forever.
            tile.setTurnsRemaining(1);
            tile.tickTurn();
            fireproofTiles.put(pos, FlammableTiles.NETHERRACK_COOLDOWN_TURNS + 1);
        } else {
            // Burned out for the rest of the fight, held as temporary terrain so endCombat
            // hands the arena back unscarred. WHAT it burns down to depends on what was
            // burning: soil under grass, charcoal where there was timber. Everything used to
            // become dirt, which turned a burnt plank floor into a field of soil suspended
            // where the boards had been.
            tile.setTemporaryType(TileType.NORMAL, BURN_HOLD_TURNS);
            tile.setBlockType(FlammableTiles.residueFor(fuel));
            // Retired for the rest of the fight. Bare dirt isn't fuel, so ordinary fire
            // would leave it alone anyway - this is what stops SOUL fire, which needs no
            // fuel, from re-consuming ground it has already burnt to ash.
            fireproofTiles.put(pos, SPENT_FOREVER);
        }
        paintTileBlock(world, pos, tile);
    }

    /**
     * Beat out the flames on a tile. The fuel is already gone - it was consumed the moment
     * the tile caught - so dousing lands the tile straight on its burnt-out state instead of
     * rewinding it: scorched ground that will not catch again, skipping the magma stage the
     * fire would otherwise have left behind. That is the point of putting it out early.
     *
     * <p>Boss-placed fire is not part of the burn cycle and has no fuel record, so it is
     * simply expired back to the terrain it was painted over.
     *
     * @return true if there were flames here to put out
     */
    private boolean douseFire(GridPos pos) {
        if (arena == null || player == null || pos == null) return false;
        GridTile tile = arena.getTile(pos);
        if (tile == null || !tile.getType().isFlames()) return false;

        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos floor = tileFloorPos(pos);
        BurnState state = burningTiles.remove(pos);
        if (state != null) {
            finishBurn(world, pos, tile, state.restores(), state.fuel());
        } else {
            tile.setTurnsRemaining(1);
            tile.tickTurn();
            paintTileBlock(world, pos, tile);
        }

        world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
            floor.getX() + 0.5, floor.getY() + 1.1, floor.getZ() + 0.5,
            18, 0.35, 0.3, 0.35, 0.01);
        world.playSound(null, floor, net.minecraft.sound.SoundEvents.BLOCK_FIRE_EXTINGUISH,
            net.minecraft.sound.SoundCategory.BLOCKS, 1.0f, 1.0f);
        return true;
    }

    /**
     * Set alight everything standing on a flame tile. Used where the fire arrives at the
     * victim rather than the victim walking into it (a thrown fire charge, a spreading front
     * reaching an occupied tile), so both the mob and any party member on the tile catch.
     */
    private void applyFireTileBurn(GridPos pos) {
        if (arena == null || pos == null) return;
        GridTile tile = arena.getTile(pos);
        TileType flames = tile != null ? tile.getType() : TileType.FIRE;
        CombatEntity occupant = arena.getOccupant(pos);
        if (occupant != null) applyFireTileBurn(occupant, flames);

        for (ServerPlayerEntity member : allCombatPlayers()) {
            if (member == null || member.isRemoved() || member.isDisconnected()) continue;
            if (deadPartyMembers.contains(member.getUuid())) continue;
            if (!pos.equals(gridPosOf(member))) continue;

            ServerPlayerEntity saved = this.player;
            boolean swapped = member != saved;
            if (swapped) { this.player = member; retargetEffectsToCurrentPlayer(); }
            try {
                applyFireTileBurnToPlayer(flames);
            } finally {
                if (swapped) { this.player = saved; retargetEffectsToCurrentPlayer(); }
            }
        }
    }

    /** Burning level a flame tile inflicts: soul fire runs one level hotter than fire. */
    private static int burnLevelFor(TileType flames) {
        return flames == TileType.SOUL_FIRE
            ? FlammableTiles.SOUL_BURN_LEVEL : FlammableTiles.BURN_LEVEL;
    }

    /**
     * Burn the acting player for standing in flames: Burning II (III in soul fire) for two
     * turns, EXTENDING any burn already running rather than refreshing it, so staying in the
     * fire goes 2 turns -&gt; 4 turns -&gt; 6 turns instead of being pinned at two.
     */
    private void applyFireTileBurnToPlayer(TileType flames) {
        if (player == null) return;
        // Soul fire is its own burn, and fire resistance does NOT keep it off you - it only
        // takes the edge off each tick (see CombatEffects). Ordinary fire still bounces off
        // a fireproof player entirely, which is the whole point of being fireproof.
        if (flames == TileType.SOUL_FIRE) {
            int soulLevel = Math.max(burnLevelFor(flames),
                combatEffects.getAmplifier(CombatEffects.EffectType.SOUL_BURNING) + 1);
            int soulTurns = CombatEffects.SOUL_BURN_TURNS
                + combatEffects.getTurnsRemaining(CombatEffects.EffectType.SOUL_BURNING);
            if (addEffectHooked(CombatEffects.EffectType.SOUL_BURNING, soulTurns, soulLevel - 1)) {
                sendMessage("§b  You're standing in soul fire! §3Soul Burning "
                    + "I".repeat(Math.max(1, soulLevel)) + " for "
                    + combatEffects.getTurnsRemaining(CombatEffects.EffectType.SOUL_BURNING)
                    + " turns."
                    + (combatEffects.hasFireResistance() ? " §7Your fire resistance barely helps." : ""));
            }
            return;
        }
        if (combatEffects.hasFireResistance()) return;
        int level = burnLevelFor(flames);
        // addEffect REPLACES the timer, so the extension has to be summed in here. The
        // LEVEL takes the max rather than the new value: stepping from soul fire into
        // ordinary fire must not cool a Burning III back down to II.
        int turns = FlammableTiles.BURN_TURNS
            + combatEffects.getTurnsRemaining(CombatEffects.EffectType.BURNING);
        level = Math.max(level,
            combatEffects.getAmplifier(CombatEffects.EffectType.BURNING) + 1);
        if (addEffectHooked(CombatEffects.EffectType.BURNING, turns, level - 1)) {
            sendMessage((flames == TileType.SOUL_FIRE
                    ? "§b  You're standing in soul fire! §cBurning "
                    : "§6  You're standing in the fire! §cBurning ")
                + "I".repeat(Math.max(1, level)) + " for "
                + combatEffects.getTurnsRemaining(CombatEffects.EffectType.BURNING) + " turns.");
        }
    }

    /** Mob/ally half of the fire-tile burn: same rule, same extend-don't-refresh behaviour
     *  ({@link CombatEntity#stackBurning} already adds turns, so only the level is pinned). */
    private void applyFireTileBurn(CombatEntity victim, TileType flames) {
        if (victim == null || !victim.isAlive()) return;
        // Soul fire burns the fire-immune too - a blaze standing in it is not safe, it just
        // takes a slightly smaller bite. Same rule as the player side.
        if (flames == TileType.SOUL_FIRE) {
            int soulLevel = burnLevelFor(flames);
            int before = victim.getSoulBurningTurns();
            victim.stackSoulBurning(CombatEffects.SOUL_BURN_TURNS, 0);
            if (victim.getSoulBurningTurns() == before) return;   // soaked - nothing caught
            victim.setSoulBurningAmplifier(
                Math.max(victim.getSoulBurningAmplifier(), soulLevel - 1));
            sendMessage("§b" + victim.getDisplayName() + " is standing in soul fire! §3Soul Burning "
                + "I".repeat(Math.max(1, soulLevel)) + ".");
            return;
        }
        if (victim.isFireImmune()) return;
        int level = burnLevelFor(flames);
        int before = victim.getBurningTurns();
        victim.stackBurning(FlammableTiles.BURN_TURNS, 0);
        if (victim.getBurningTurns() == before) return; // soaked / immune - nothing caught
        victim.setBurningAmplifier(Math.max(victim.getBurningAmplifier(), level - 1));
        sendMessage((flames == TileType.SOUL_FIRE
                ? "§b" + victim.getDisplayName() + " is standing in soul fire! §cBurning "
                : "§6" + victim.getDisplayName() + " is standing in the fire! §cBurning ")
            + "I".repeat(Math.max(1, level)) + ".");
    }

    /**
     * Maximum lifetime (in turns) for blocking / floor-destroying terrain a boss
     * tries to create permanently. Long enough to stay tactically threatening,
     * short enough that the arena always recovers and can never be permanently
     * flooded or partitioned into an unreachable layout.
     */
    private static final int BOSS_BLOCKING_TERRAIN_DURATION = 6;

    private void resolveCreateTerrain(EnemyAction.CreateTerrain ct) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        int duration = ct.duration();
        if (currentEnemy != null && currentEnemy.isBoss() && duration <= 0) {
            TileType tt = ct.terrainType();
            if (tt.isFlames() || tt == TileType.LAVA) {
                // Prevent permanent trap patterns from boss lava/magma; always decay.
                duration = 3;
            } else if (tt == TileType.OBSTACLE || tt == TileType.VOID
                    || tt == TileType.DEEP_WATER) {
                // Same safeguard for blocking / floor-destroying terrain: a boss must
                // never PERMANENTLY wall off the arena or delete the floor. Left
                // permanent, Chorus plants, Rockbreaker boulders, and Void Herald
                // collapses accumulate every turn and can isolate the player on an
                // island or seal the boss out of melee reach -an unrecoverable
                // softlock. Force a finite lifetime so the arena always heals back to
                // a navigable state while the terrain stays threatening while active.
                duration = BOSS_BLOCKING_TERRAIN_DURATION;
            }
        }
        // Get biome-appropriate floor block for NORMAL terrain
        net.minecraft.block.Block biomeFloorBlock = null;
        if (ct.terrainType() == TileType.NORMAL) {
            biomeFloorBlock = getBiomeFloorBlock();
        }
        // Terrain that occupies the space a body stands in, rather than the ground under it.
        boolean blocking = ct.terrainType() == TileType.OBSTACLE
            || ct.terrainType() == TileType.RUBBLE;

        int changed = 0;
        int crushed = 0;
        for (GridPos pos : ct.tiles()) {
            if (!arena.isInBounds(pos)) continue;
            GridTile tile = arena.getTile(pos);
            if (tile == null) continue;

            // A wall is never built on top of somebody. See isTileOccupiedByCombatant: the
            // block would shove them off the tile, and a cave-in that kills by pushing its
            // victim into a pit is not something the telegraph gave them any way to read. The
            // stone lands on them instead, which is what a cave-in should have been doing.
            if (blocking && isTileOccupiedByCombatant(pos)) {
                if (crushOccupantsOn(pos, CRUSH_DAMAGE, "Falling stone")) return;
                crushed++;
                continue;
            }

            // Clearing a tile that carries a pillar goes through the pillar's own removal, or
            // only the bottom block of it would come out and the rest would be left hanging.
            // This is how the boss spends its own supports.
            if (bossPillars.contains(pos)) {
                clearBossPillar(pos);
                changed++;
                continue;
            }

            if (duration > 0) {
                tile.setTemporaryType(ct.terrainType(), duration);
            } else {
                tile.setType(ct.terrainType());
            }
            // Frostbound ice walls: use literal above-floor ice obstacle blocks
            // (same layer as player-placed walls), while leaving the floor tile
            // itself intact so they "break down" cleanly when duration expires.
            boolean snowyIceWall = ct.terrainType() == TileType.OBSTACLE
                && currentEnemy != null
                && "boss:snowy".equals(currentEnemy.getAiKey());
            if (snowyIceWall) {
                tile.setBlockType(Blocks.PACKED_ICE);
            }
            // Override the block type for NORMAL tiles to match the arena biome
            if (biomeFloorBlock != null) {
                tile.setBlockType(biomeFloorBlock);
            }
            // Update the visual block in the world (floor level, not above)
            BlockPos bp = new BlockPos(
                arena.getOrigin().getX() + pos.x(),
                arena.getOrigin().getY(),
                arena.getOrigin().getZ() + pos.z());
            if (ct.terrainType() == TileType.POWDER_SNOW) {
                world.setBlockState(bp.down(), Blocks.STONE.getDefaultState());
            }
            if (snowyIceWall) {
                world.setBlockState(bp.up(), Blocks.PACKED_ICE.getDefaultState());
            } else if (ct.terrainType().isFlames() || blocking) {
                // Flames and walls both belong ABOVE an intact floor, not painted onto it.
                // Written at floor level, a cave-in boulder replaced the paving and came out
                // looking like a slightly different colour of ground that the grid then
                // refused to let anything walk across - a wall nobody could see. Y+1 is the
                // obstacle layer every other wall in the game already uses, and it is what
                // paintTileBlock restores to when the temporary terrain expires.
                paintTileBlock(world, pos, tile);
            } else {
                world.setBlockState(bp, tile.getBlockType().getDefaultState());
            }
            // The snow-overlay clear that used to sit here is gone with the reason for it: the
            // overlay lives in the obstacle layer, which is now exactly where the wall is
            // written, so paintTileBlock replaces it rather than being buried under it.

            // Particles for the transformation
            world.spawnParticles(net.minecraft.particle.ParticleTypes.POOF,
                bp.getX() + 0.5, bp.getY() + 0.5, bp.getZ() + 0.5,
                3, 0.3, 0.3, 0.3, 0.01);
            changed++;
        }
        // Only the enemy path announces the reshape. Player-initiated terrain (e.g. the
        // netherite mount's lava line) runs with currentEnemy null and sends its own
        // message, so skip here to avoid an NPE and a duplicate line.
        if (changed > 0 && currentEnemy != null) {
            String terrainName = ct.terrainType().name().toLowerCase();
            sendMessage("§e  " + currentEnemy.getDisplayName() + " reshapes " + changed
                + " tiles to " + terrainName + "!");
        }
        if (crushed > 0 && currentEnemy != null) {
            sendMessage("§8  " + crushed + " tile" + (crushed == 1 ? "" : "s")
                + " came down on whoever was standing there instead of walling it off.");
        }
    }

    /** Resolve a Spider-style web placement: drop cobwebs at floor+1 on each
     *  target tile via the arena web-overlay system so the floor stays intact
     *  underneath and pathfinding treats the tile as slowing (not blocked).
     *  Delegates to {@link #placeWebOverlays}. */
    private void resolvePlaceWeb(EnemyAction.PlaceWeb pw) {
        java.util.List<GridPos> inBounds = new java.util.ArrayList<>();
        for (GridPos pos : pw.tiles()) {
            if (arena.isInBounds(pos)) inBounds.add(pos);
        }
        if (inBounds.isEmpty()) return;
        placeWebOverlays(inBounds, pw.duration());
        if (currentEnemy != null) {
            sendMessage("§e  " + currentEnemy.getDisplayName() + " lays "
                + inBounds.size() + " cobweb" + (inBounds.size() == 1 ? "" : "s") + "!");
        }
    }

    /**
     * Resolve a line attack -damage all entities along a line.
     */
    private void resolveLineAttack(EnemyAction.LineAttack la) {
        GridPos playerGridPos = arena.getPlayerGridPos();
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        boolean hitPlayer = false;

        // Determine line particle type based on the current boss
        net.minecraft.particle.ParticleEffect lineParticle = net.minecraft.particle.ParticleTypes.CRIT;
        net.minecraft.particle.ParticleEffect trailParticle = net.minecraft.particle.ParticleTypes.SMOKE;
        if (currentEnemy != null) {
            String aiKey = currentEnemy.getAiKey();
            if (aiKey != null) {
                if (aiKey.contains("ashen_warlord") || aiKey.contains("AshenWarlord")) {
                    lineParticle = net.minecraft.particle.ParticleTypes.FLAME;
                    trailParticle = net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME;
                } else if (aiKey.contains("hexweaver") || aiKey.contains("Hexweaver")) {
                    lineParticle = net.minecraft.particle.ParticleTypes.WITCH;
                    trailParticle = net.minecraft.particle.ParticleTypes.SOUL;
                } else if (aiKey.contains("hollow_king") || aiKey.contains("HollowKing")) {
                    lineParticle = net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE;
                    trailParticle = net.minecraft.particle.ParticleTypes.ASH;
                } else if (aiKey.contains("revenant") || aiKey.contains("Revenant")) {
                    lineParticle = net.minecraft.particle.ParticleTypes.SMOKE;
                    trailParticle = net.minecraft.particle.ParticleTypes.SOUL;
                } else if (aiKey.contains("crimson") || aiKey.contains("Crimson")) {
                    lineParticle = net.minecraft.particle.ParticleTypes.CRIMSON_SPORE;
                    trailParticle = net.minecraft.particle.ParticleTypes.FLAME;
                } else if (aiKey.contains("wither") || aiKey.contains("Wither")) {
                    lineParticle = net.minecraft.particle.ParticleTypes.SOUL;
                    trailParticle = net.minecraft.particle.ParticleTypes.LARGE_SMOKE;
                } else if (aiKey.contains("tidecaller") || aiKey.contains("Tidecaller")) {
                    lineParticle = net.minecraft.particle.ParticleTypes.SPLASH;
                    trailParticle = net.minecraft.particle.ParticleTypes.BUBBLE;
                } else if (aiKey.contains("warped_forest")) {
                    // Void Walker -void beam
                    lineParticle = net.minecraft.particle.ParticleTypes.PORTAL;
                    trailParticle = net.minecraft.particle.ParticleTypes.REVERSE_PORTAL;
                } else if (aiKey.contains("dragons_nest")) {
                    // Ender Dragon breath -magenta dragon breath + portal shimmer
                    lineParticle = net.minecraft.particle.ParticleTypes.DRAGON_BREATH;
                    trailParticle = net.minecraft.particle.ParticleTypes.PORTAL;
                }
            }
        }

        java.util.Set<GridPos> lineTiles = new java.util.HashSet<>();
        for (int i = 0; i < la.length(); i++) {
            GridPos tile = new GridPos(la.start().x() + la.dx() * i, la.start().z() + la.dz() * i);
            if (!arena.isInBounds(tile)) continue;
            lineTiles.add(tile);
            if (tile.equals(playerGridPos)) hitPlayer = true;

            // Spawn line particles along each tile
            BlockPos bp = arena.gridToBlockPos(tile);
            world.spawnParticles(lineParticle,
                bp.getX() + 0.5, bp.getY() + 0.8, bp.getZ() + 0.5,
                5, 0.2, 0.4, 0.2, 0.02);
            world.spawnParticles(trailParticle,
                bp.getX() + 0.5, bp.getY() + 0.3, bp.getZ() + 0.5,
                3, 0.15, 0.2, 0.15, 0.01);

            // Damage enemies in the line (friendly fire)
            if (CrafticsMod.CONFIG.friendlyFireEnabled()) {
                CombatEntity occupant = arena.getOccupant(tile);
                if (occupant != null && occupant != currentEnemy && occupant.isAlive()) {
                    int dealt = occupant.takeDamage(la.damage());
                    sendMessage("§6  Line hits " + occupant.getDisplayName() + " for " + dealt + "!");
                    checkAndHandleDeath(occupant);
                }
            }
        }
        // Damage EVERY party member standing on a line tile, not just the host.
        // A non-leader teammate standing in the beam previously took no damage
        // because the line was only tested against arena.getPlayerGridPos().
        // Each hit routes through the this.player swap for correct per-victim
        // dodge/armor/effects/death handling.
        java.util.List<ServerPlayerEntity> lineVictims = new java.util.ArrayList<>();
        if (partyPlayers.size() > 1) {
            for (ServerPlayerEntity member : partyPlayers) {
                if (member == null || member.isRemoved() || member.isDisconnected()) continue;
                if (deadPartyMembers.contains(member.getUuid())) continue;
                if (lineTiles.contains(gridPosOf(member))) lineVictims.add(member);
            }
        } else if (hitPlayer) {
            lineVictims.add(player);
        }
        boolean gameOverFromLine = false;
        for (ServerPlayerEntity victim : lineVictims) {
            ServerPlayerEntity savedLinePlayer = this.player;
            boolean lineSwapped = victim != savedLinePlayer;
            if (lineSwapped) { this.player = victim; retargetEffectsToCurrentPlayer(); }
            boolean victimDied = false;
            try {
                int actual = damagePlayer(la.damage(), currentEnemy);
                sendMessage("§c  Line attack hits " + (lineSwapped ? victim.getName().getString() : "you")
                    + " for " + actual + " damage! (HP: " + getPlayerHp() + ")");
                if (getPlayerHp() <= 0) {
                    victimDied = true;
                    handlePlayerDeathOrGameOver();
                    gameOverFromLine = (partyPlayers.size() <= 1 || !active);
                }
            } finally {
                if (!victimDied) { this.player = savedLinePlayer; retargetEffectsToCurrentPlayer(); }
            }
            if (gameOverFromLine) return;
        }
    }

    private boolean tryDestroyRevenantSummonMarker(GridPos clickedTile) {
        GridPos playerPos = arena.getPlayerGridPos();
        Item weapon = player.getMainHandStack().getItem();
        int range = getEffectiveWeaponRange();
        if (range > 1) range += getScaffoldRangeBonus(playerPos);

        int dist = PlayerCombatStats.isBow(player)
            ? playerPos.manhattanDistance(clickedTile)
            : Math.max(Math.abs(playerPos.x() - clickedTile.x()), Math.abs(playerPos.z() - clickedTile.z()));
        if (dist > range) {
            sendMessage("§cThat grave marker is out of range!");
            return false;
        }

        int attackCost = WeaponAbility.getAttackCost(weapon);
        if (weapon == Items.CROSSBOW) {
            attackCost = Math.max(1, attackCost - PlayerCombatStats.getQuickCharge(player));
        }
        int rogueReduction = PlayerCombatStats.getSetApCostReduction(player);
        if (rogueReduction > 0) {
            attackCost = Math.max(1, attackCost - rogueReduction);
        }
        if (apRemaining < attackCost) {
            sendMessage("§cNeed " + attackCost + " AP to attack! (have " + apRemaining + ")");
            return false;
        }

        apRemaining -= hookedAttackApCost(attackCost);
        ItemStack weaponStack = player.getMainHandStack();
        if (weaponStack.isDamageable()) {
            weaponStack.damage(7, player, net.minecraft.entity.EquipmentSlot.MAINHAND);
            if (weaponStack.isEmpty() || weaponStack.getDamage() >= weaponStack.getMaxDamage()) {
                sendMessage("§c§lYour weapon broke!");
            }
        }

        removeRevenantSummonMarker(clickedTile);
        player.getWorld().playSound(null, arena.gridToBlockPos(clickedTile),
            net.minecraft.sound.SoundEvents.BLOCK_BONE_BLOCK_BREAK,
            net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 0.9f);
        sendMessage("§aYou smash the zombie head before the corpse can rise!");
        return true;
    }

    private boolean isRevenantZombieSummon(EnemyAction.SummonMinions sm) {
        return currentEnemy != null
            && currentEnemy.getAiKey() != null
            && currentEnemy.getAiKey().contains("revenant")
            && "minecraft:zombie".equals(sm.entityTypeId());
    }

    private boolean isRevenantSummonMarker(GridPos pos) {
        return TILE_EFFECT_REVENANT_HEAD.equals(tileEffects.get(pos));
    }

    private void syncSpecialBossWarningMarkers(com.crackedgames.craftics.combat.ai.boss.BossWarning warning) {
        EnemyAction resolveAction = warning.getResolveAction();
        if (resolveAction instanceof EnemyAction.SummonMinions sm
                && "minecraft:zombie".equals(sm.entityTypeId())
                && currentEnemy != null
                && currentEnemy.getAiKey() != null
                && currentEnemy.getAiKey().contains("revenant")) {
            syncRevenantSummonMarkers(warning.getAffectedTiles());
        }
    }

    private void syncRevenantSummonMarkers(java.util.List<GridPos> desiredTiles) {
        java.util.Set<GridPos> desired = new java.util.HashSet<>(desiredTiles);
        java.util.List<GridPos> existing = new java.util.ArrayList<>();
        for (var entry : tileEffects.entrySet()) {
            if (TILE_EFFECT_REVENANT_HEAD.equals(entry.getValue())) {
                existing.add(entry.getKey());
            }
        }
        for (GridPos pos : existing) {
            if (!desired.contains(pos)) {
                removeRevenantSummonMarker(pos);
            }
        }
        for (GridPos pos : desired) {
            placeRevenantSummonMarker(pos);
        }
    }

    private void clearRevenantSummonMarkers(java.util.List<GridPos> positions) {
        for (GridPos pos : positions) {
            removeRevenantSummonMarker(pos);
        }
    }

    private void clearAllRevenantSummonMarkers() {
        java.util.List<GridPos> markers = new java.util.ArrayList<>();
        for (var entry : tileEffects.entrySet()) {
            if (TILE_EFFECT_REVENANT_HEAD.equals(entry.getValue())) {
                markers.add(entry.getKey());
            }
        }
        clearRevenantSummonMarkers(markers);
    }

    private void placeRevenantSummonMarker(GridPos pos) {
        tileEffects.put(pos, TILE_EFFECT_REVENANT_HEAD);
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos headPos = arena.gridToBlockPos(pos).up();
        if (!world.getBlockState(headPos).isAir() && !world.getBlockState(headPos).isOf(Blocks.ZOMBIE_HEAD)) {
            return;
        }
        world.setBlockState(headPos,
            Blocks.ZOMBIE_HEAD.getDefaultState().with(net.minecraft.block.SkullBlock.ROTATION, 0));
        world.spawnParticles(net.minecraft.particle.ParticleTypes.ASH,
            headPos.getX() + 0.5, headPos.getY() + 0.2, headPos.getZ() + 0.5,
            5, 0.2, 0.1, 0.2, 0.01);
    }

    private void removeRevenantSummonMarker(GridPos pos) {
        tileEffects.remove(pos, TILE_EFFECT_REVENANT_HEAD);
        if (player == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos headPos = arena.gridToBlockPos(pos).up();
        if (world.getBlockState(headPos).isOf(Blocks.ZOMBIE_HEAD)) {
            world.setBlockState(headPos, Blocks.AIR.getDefaultState());
            world.spawnParticles(net.minecraft.particle.ParticleTypes.POOF,
                headPos.getX() + 0.5, headPos.getY() + 0.2, headPos.getZ() + 0.5,
                4, 0.15, 0.1, 0.15, 0.01);
        }
    }

    /**
     * Resolve a boss self-modification (buff/debuff).
     */
    private void resolveModifySelf(CombatEntity boss, EnemyAction.ModifySelf ms) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        MobEntity bMob = boss.getMobEntity();
        double bx = bMob != null ? bMob.getX() : 0;
        double by = bMob != null ? bMob.getY() + 1.0 : 0;
        double bz = bMob != null ? bMob.getZ() : 0;

        switch (ms.stat()) {
            case "speed" -> {
                boss.setSpeedBonus(boss.getSpeedBonus() + ms.amount());
                // Speed boost -wind swirl
                if (bMob != null) {
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                        bx, by, bz, 8, 0.4, 0.6, 0.4, 0.03);
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.SWEEP_ATTACK,
                        bx, by - 0.3, bz, 2, 0.2, 0.1, 0.2, 0.0);
                }
                sendMessage("§d  " + boss.getDisplayName() + " gains +" + ms.amount() + " speed!");
            }
            case "defense" -> {
                boss.setDefensePenalty(boss.getDefensePenalty() - ms.amount());
                if (ms.duration() > 0) {
                    boss.setDefensePenaltyTurns(ms.duration());
                }
                // Defense boost -armored shimmer
                if (bMob != null) {
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.ENCHANTED_HIT,
                        bx, by, bz, 12, 0.4, 0.6, 0.4, 0.02);
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD,
                        bx, by + 0.3, bz, 5, 0.3, 0.5, 0.3, 0.01);
                }
                sendMessage("§d  " + boss.getDisplayName() + " gains +" + ms.amount() + " defense!");
            }
            case "attack" -> {
                boss.setAttackPenalty(boss.getAttackPenalty() - ms.amount());
                // Attack boost -aggressive red sparks
                if (bMob != null) {
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                        bx, by, bz, 10, 0.3, 0.5, 0.3, 0.03);
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.DAMAGE_INDICATOR,
                        bx, by + 0.3, bz, 5, 0.2, 0.3, 0.2, 0.01);
                }
                sendMessage("§d  " + boss.getDisplayName() + " gains +" + ms.amount() + " attack!");
            }
            case "hp", "heal" -> {
                boss.heal(ms.amount());
                // Heal -green sparkles + hearts
                if (bMob != null) {
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.HAPPY_VILLAGER,
                        bx, by, bz, 10, 0.4, 0.6, 0.4, 0.02);
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.HEART,
                        bx, by + 0.5, bz, 3, 0.3, 0.3, 0.3, 0.0);
                }
                sendMessage("§a  " + boss.getDisplayName() + " heals for " + ms.amount() + " HP!");
            }
            default -> {
                if (bMob != null) {
                    world.spawnParticles(net.minecraft.particle.ParticleTypes.ENCHANT,
                        bx, by, bz, 8, 0.3, 0.5, 0.3, 0.02);
                }
                sendMessage("§d  " + boss.getDisplayName() + " modifies " + ms.stat() + "!");
            }
        }
    }

    /**
     * Resolve forced movement -push/pull a target entity.
     */
    private void resolveForcedMovement(EnemyAction.ForcedMovement fm) {
        ServerWorld fmWorld = (ServerWorld) player.getEntityWorld();
        if (fm.targetEntityId() == -1) {
            // Move the player the boss actually targeted (closest live member), not
            // the last-acting member that arena.getPlayerGridPos()/this.player point
            // at. The push direction was computed against that member, so the origin
            // must be their tile or the wrong player gets displaced from the wrong
            // spot (and void-fall damage hits the wrong player). Routed via the
            // this.player swap so the void-fall + rift handling apply to them.
            ServerPlayerEntity savedFmPlayer = this.player;
            GridPos savedFmGrid = arena.getPlayerGridPos();
            ServerPlayerEntity fmTarget = currentEnemy != null
                ? findClosestPartyTarget(currentEnemy.getGridPos()) : this.player;
            boolean fmSwapped = fmTarget != null && fmTarget != savedFmPlayer;
            if (fmSwapped) {
                this.player = fmTarget;
                retargetEffectsToCurrentPlayer();
                arena.setPlayerGridPos(gridPosOf(fmTarget));
            }
            boolean fmTargetDied = false;
            try {
            // Move the player -spawn wind particles along push/pull path
            GridPos playerGridPos = arena.getPlayerGridPos();
            GridPos landingPos = playerGridPos;
            for (int i = 1; i <= fm.tiles(); i++) {
                GridPos candidate = new GridPos(playerGridPos.x() + fm.dx() * i, playerGridPos.z() + fm.dz() * i);
                if (!arena.isInBounds(candidate) || arena.isEnemyOccupied(candidate)) break;
                GridTile tile = arena.getTile(candidate);
                if (tile != null && tile.getType() == TileType.VOID) {
                    // Player pushed into void -take fall damage
                    int fallDmg = damagePlayer(5);
                    sendMessage("§c  Pushed into the void for " + fallDmg + " damage! (HP: " + getPlayerHp() + ")");
                    if (getPlayerHp() <= 0) { fmTargetDied = true; handlePlayerDeathOrGameOver(); return; }
                    break;
                }
                if (tile == null || !tile.isWalkable()) break;
                // Wind trail along movement path
                BlockPos pathBp = arena.gridToBlockPos(candidate);
                fmWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                    pathBp.getX() + 0.5, pathBp.getY() + 0.8, pathBp.getZ() + 0.5,
                    3, 0.2, 0.3, 0.2, 0.02);
                fmWorld.spawnParticles(net.minecraft.particle.ParticleTypes.SWEEP_ATTACK,
                    pathBp.getX() + 0.5, pathBp.getY() + 0.5, pathBp.getZ() + 0.5,
                    1, 0.1, 0.1, 0.1, 0.0);
                landingPos = candidate;
            }
            if (!landingPos.equals(playerGridPos)) {
                arena.setPlayerGridPos(landingPos);
                BlockPos bp = arena.gridToBlockPos(landingPos);
                player.requestTeleport(bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5);
                broadcastPlayerPositionToOthers(player);
                // Landing impact
                fmWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                    bp.getX() + 0.5, bp.getY() + 0.5, bp.getZ() + 0.5,
                    5, 0.3, 0.3, 0.3, 0.01);
                sendMessage("§e  Pushed " + playerGridPos.manhattanDistance(landingPos) + " tiles!");
                // Void Walker: Void Pull may have dragged the player onto one of the boss's own rifts.
                handleVoidRiftEntry(landingPos);
            }
            } finally {
                if (fmSwapped && !fmTargetDied) {
                    this.player = savedFmPlayer;
                    retargetEffectsToCurrentPlayer();
                    arena.setPlayerGridPos(savedFmGrid);
                }
            }
        } else {
            // Move an enemy entity
            CombatEntity target = findEnemyById(fm.targetEntityId());
            if (target != null && target.isAlive()) {
                knockEnemyBack(target, fm.dx(), fm.dz(), fm.tiles());
            }
        }
    }

    /**
     * Arena-wide wind gust for miniboss mechanics that have no boss {@link CombatEntity} to
     * channel a {@link EnemyAction.BossAbility} (the Snowy Blizzard's storm, e.g.) - mirrors
     * {@link com.crackedgames.craftics.combat.ai.boss.FrostboundAI#castHarpoonPull}: sweeping
     * arrow glyphs across the WHOLE arena in {@code (dirX,dirZ)}, then every unit on the grid -
     * every live party member and every live enemy - is dragged {@code tiles} tiles that
     * direction.
     *
     * <p>The normal {@link EnemyAction.BossAbility} telegraph path (pendingBossWarnings /
     * {@link #resolvePendingBossWarnings}) requires a live {@code CombatEntity boss} to key the
     * pending warning and theme the VFX, which a miniboss mechanic doesn't have. This method
     * bypasses that system entirely and talks straight to the same client contract
     * ({@link TileSetPayload}'s {@code warningTiles}/{@code arrowTiles}) that
     * {@link #syncWarningTiles()} uses, so the arrows rendered are the real client-side arrow
     * glyphs, not a particles-only approximation. Because there's no boss to hold the warning
     * across a turn boundary, the arrow paint and the drag happen in the same call - callers
     * that want a one-round lead time (chat warning, then a later round calling this) get that
     * by simply not calling this every round.
     */
    /** Telegraph-only wind gust: paint the sweeping arrows + wind particles this round, WITHOUT
     *  dragging. The mechanic calls this a round before {@link #triggerWindGust} so the player
     *  sees the floor arrows and has a turn to brace/reposition, matching the Frostbound gust's
     *  telegraph-then-resolve cadence. */
    private void triggerWindTelegraph(int dirX, int dirZ) {
        paintWindArrows(dirX, dirZ); // warning arrows on every tile, no particles
    }

    private void triggerWindGust(int dirX, int dirZ) {
        if (arena == null || player == null) return;
        if (dirX == 0 && dirZ == 0) return;
        paintWindArrows(dirX, dirZ);  // keep the arrows this round
        spawnWindSnow(dirX, dirZ);    // + the snow of the actual blow

        // Drag every live party player (each via the same swap-and-move routine ForcedMovement
        // uses for the player target) - loop the full party, not just the closest member, since
        // this is an arena-wide gust rather than a single-target harpoon pull.
        for (ServerPlayerEntity member : new ArrayList<>(partyPlayers.isEmpty()
                ? java.util.List.of(player) : partyPlayers)) {
            if (member == null || member.isRemoved() || member.isDisconnected()) continue;
            if (deadPartyMembers.contains(member.getUuid())) continue;
            dragPartyMember(member, dirX, dirZ, 2);
        }

        // Drag every live enemy the same direction.
        for (CombatEntity enemy : new ArrayList<>(enemies)) {
            if (enemy == null || !enemy.isAlive()) continue;
            knockEnemyBack(enemy, dirX, dirZ, 2);
        }

        // The gust has resolved - drop the arrows so they don't linger into the next turn.
        pendingWeatherArrows.clear();
        sendSync();
    }

    // How many tiles the river current sweeps a unit standing in the water.
    private static final int RIVER_CURRENT_TILES = 2;
    // If at least this fraction of water tiles share one nearest-edge direction, the whole
    // current flows that one way (water "clearly on one side"); otherwise each unit is pulled
    // toward its own nearest edge (arenas with water on several sides, e.g. the boss ring).
    private static final double RIVER_UNIFORM_THRESHOLD = 0.6;

    /**
     * The river biome's current. On the telegraph round ({@code telegraphOnly}) it paints
     * directional arrows on every water tile pointing the way that tile's current flows; on the
     * resolve round it also sweeps every player and enemy STANDING on a water tile
     * {@link #RIVER_CURRENT_TILES} tiles toward the nearest outside edge, reusing the same
     * drag/knockback primitives as the wind gust (which already stop at the arena edge, so a unit
     * is never swept out of bounds).
     *
     * <p>Direction is resolved once from the water layout: if the water is concentrated on one
     * side (>= {@link #RIVER_UNIFORM_THRESHOLD} of water tiles share a nearest edge) the whole
     * current flows that one way; otherwise it flows per-tile toward each tile's nearest edge, so
     * a water-ringed arena pushes outward in all directions at once.
     */
    private void triggerRiverCurrent(boolean telegraphOnly) {
        if (arena == null || player == null) return;

        // Collect every water tile and its nearest-edge push direction.
        java.util.List<GridPos> waterTiles = new java.util.ArrayList<>();
        java.util.Map<GridPos, int[]> tileDir = new java.util.HashMap<>();
        int[] dirVotes = new int[4]; // [-x, +x, -z, +z] tallies for the uniform check
        for (int x = 0; x < arena.getWidth(); x++) {
            for (int z = 0; z < arena.getHeight(); z++) {
                GridPos p = new GridPos(x, z);
                GridTile t = arena.getTile(p);
                if (t == null) continue;
                if (t.getType() != TileType.WATER && t.getType() != TileType.DEEP_WATER) continue;
                int[] dir = nearestEdgeDir(x, z);
                waterTiles.add(p);
                tileDir.put(p, dir);
                if (dir[0] < 0) dirVotes[0]++; else if (dir[0] > 0) dirVotes[1]++;
                else if (dir[1] < 0) dirVotes[2]++; else if (dir[1] > 0) dirVotes[3]++;
            }
        }
        if (waterTiles.isEmpty()) return;

        // Uniform if one edge direction dominates; else keep the per-tile directions.
        int[] uniform = null;
        int best = -1, bestIdx = -1;
        for (int i = 0; i < 4; i++) if (dirVotes[i] > best) { best = dirVotes[i]; bestIdx = i; }
        if (best >= waterTiles.size() * RIVER_UNIFORM_THRESHOLD) {
            uniform = switch (bestIdx) {
                case 0 -> new int[]{-1, 0};
                case 1 -> new int[]{ 1, 0};
                case 2 -> new int[]{ 0,-1};
                default -> new int[]{ 0, 1};
            };
            for (GridPos p : waterTiles) tileDir.put(p, uniform);
        }

        // Paint per-tile flow arrows on the water into the persistent weather-arrow channel (each
        // tile points its own flow way). Goes through the same list as the blizzard gust so it
        // survives the enemy-phase rebroadcasts instead of being wiped the moment it's sent.
        pendingWeatherArrows.clear();
        for (GridPos p : waterTiles) {
            int[] d = tileDir.get(p);
            pendingWeatherArrows.add(new int[]{p.x(), p.z(), d[0], d[1]});
        }

        if (telegraphOnly) {
            syncWarningTiles();
            return;
        }

        // Resolve: sweep every unit standing on a water tile toward its tile's flow direction.
        ServerWorld cw = (ServerWorld) player.getEntityWorld();
        for (int x = 0; x < arena.getWidth(); x++) {
            for (int z = 0; z < arena.getHeight(); z++) {
                GridPos p = new GridPos(x, z);
                BlockPos bp = arena.gridToBlockPos(p);
                if (tileDir.containsKey(p)) {
                    cw.spawnParticles(net.minecraft.particle.ParticleTypes.SPLASH,
                        bp.getX() + 0.5, bp.getY() + 0.4, bp.getZ() + 0.5, 4, 0.3, 0.05, 0.3, 0.1);
                }
            }
        }
        playPartySound(net.minecraft.sound.SoundEvents.WEATHER_RAIN, 0.7f, 0.8f);

        // Players first: a member is swept only if the tile they're on is water.
        for (ServerPlayerEntity member : new ArrayList<>(partyPlayers.isEmpty()
                ? java.util.List.of(player) : partyPlayers)) {
            if (member == null || member.isRemoved() || member.isDisconnected()) continue;
            if (deadPartyMembers.contains(member.getUuid())) continue;
            int[] d = tileDir.get(gridPosOf(member));
            if (d == null) continue;
            dragPartyMember(member, d[0], d[1], RIVER_CURRENT_TILES);
        }
        // Enemies: same rule, keyed off the enemy's own tile.
        for (CombatEntity enemy : new ArrayList<>(enemies)) {
            if (enemy == null || !enemy.isAlive()) continue;
            int[] d = tileDir.get(enemy.getGridPos());
            if (d == null) continue;
            knockEnemyBack(enemy, d[0], d[1], RIVER_CURRENT_TILES);
        }

        // The current has resolved - drop the flow arrows so they don't linger into the next turn.
        pendingWeatherArrows.clear();
        sendSync();
    }

    /** The push direction toward the nearest arena edge from tile (x,z). Compares the four edge
     *  distances (left=x, right=W-1-x, top=z, bottom=H-1-z) and returns the unit vector toward the
     *  closest; ties break toward the X axis, then negative, so the choice is deterministic. */
    private int[] nearestEdgeDir(int x, int z) {
        int w = arena.getWidth(), h = arena.getHeight();
        int left = x, right = w - 1 - x, top = z, bottom = h - 1 - z;
        int min = Math.min(Math.min(left, right), Math.min(top, bottom));
        if (left == min) return new int[]{-1, 0};
        if (right == min) return new int[]{1, 0};
        if (top == min) return new int[]{0, -1};
        return new int[]{0, 1};
    }

    /** Paint the arena-wide directional arrow glyphs + wind particles for a gust in (dirX,dirZ).
     *  Shared by the telegraph round and the resolve round so both show the same sweep. */
    /** Paint the directional warning arrows on EVERY arena tile (all pointing the drag way).
     *  This is the telegraph - no particles, so the arrows read cleanly as the warning. */
    private void paintWindArrows(int dirX, int dirZ) {
        if (arena == null || player == null) return;
        if (dirX == 0 && dirZ == 0) return;
        // Store the arrows in the persistent weather-arrow list (uniform dir on every tile), then
        // let the normal broadcast fold them in. A one-off payload here would be wiped by the very
        // next broadcastTileSets/syncWarningTiles, which is exactly why weather arrows never showed.
        pendingWeatherArrows.clear();
        for (int x = 0; x < arena.getWidth(); x++) {
            for (int z = 0; z < arena.getHeight(); z++) {
                pendingWeatherArrows.add(new int[]{x, z, dirX, dirZ});
            }
        }
        syncWarningTiles();
    }

    /** Spawn the drifting snow/cloud that streams in the drag direction - the visual of the
     *  ACTUAL blow, shown only when the gust resolves (not on the telegraph). */
    private void spawnWindSnow(int dirX, int dirZ) {
        if (arena == null || player == null) return;
        ServerWorld gustWorld = (ServerWorld) player.getEntityWorld();
        for (int x = 0; x < arena.getWidth(); x++) {
            for (int z = 0; z < arena.getHeight(); z++) {
                BlockPos bp = arena.gridToBlockPos(new GridPos(x, z));
                gustWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                    bp.getX() + 0.5, bp.getY() + 1.2, bp.getZ() + 0.5,
                    0, dirX, 0.02, dirZ, 0.18);
                gustWorld.spawnParticles(net.minecraft.particle.ParticleTypes.SNOWFLAKE,
                    bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5,
                    0, dirX, 0.0, dirZ, 0.3);
            }
        }
    }

    /**
     * Drag a single party member {@code tiles} in {@code (dx,dz)} - the multi-player equivalent
     * of {@link #resolveForcedMovement}'s {@code targetEntityId == -1} branch, which only ever
     * moves the closest party member. Swaps {@code this.player}/{@code arena.playerGridPos} to
     * {@code member} for the duration of the move so the existing void-fall/rift/teleport logic
     * (keyed off {@code this.player}) applies to the correct person, then swaps back.
     */
    private void dragPartyMember(ServerPlayerEntity member, int dx, int dz, int tiles) {
        ServerWorld fmWorld = (ServerWorld) member.getEntityWorld();
        ServerPlayerEntity savedFmPlayer = this.player;
        GridPos savedFmGrid = arena.getPlayerGridPos();
        boolean fmSwapped = member != savedFmPlayer;
        if (fmSwapped) {
            this.player = member;
            retargetEffectsToCurrentPlayer();
            arena.setPlayerGridPos(gridPosOf(member));
        }
        boolean fmTargetDied = false;
        try {
            GridPos memberGridPos = arena.getPlayerGridPos();
            GridPos landingPos = memberGridPos;
            for (int i = 1; i <= tiles; i++) {
                GridPos candidate = new GridPos(memberGridPos.x() + dx * i, memberGridPos.z() + dz * i);
                if (!arena.isInBounds(candidate) || arena.isEnemyOccupied(candidate)) break;
                GridTile tile = arena.getTile(candidate);
                if (tile != null && tile.getType() == TileType.VOID) {
                    int fallDmg = damagePlayer(5);
                    sendMessage("§c  " + member.getName().getString() + " is pushed into the void for "
                        + fallDmg + " damage! (HP: " + getPlayerHp() + ")");
                    if (getPlayerHp() <= 0) { fmTargetDied = true; handlePlayerDeathOrGameOver(); return; }
                    break;
                }
                if (tile == null || !tile.isWalkable()) break;
                BlockPos pathBp = arena.gridToBlockPos(candidate);
                fmWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                    pathBp.getX() + 0.5, pathBp.getY() + 0.8, pathBp.getZ() + 0.5,
                    3, 0.2, 0.3, 0.2, 0.02);
                fmWorld.spawnParticles(net.minecraft.particle.ParticleTypes.SWEEP_ATTACK,
                    pathBp.getX() + 0.5, pathBp.getY() + 0.5, pathBp.getZ() + 0.5,
                    1, 0.1, 0.1, 0.1, 0.0);
                landingPos = candidate;
            }
            if (!landingPos.equals(memberGridPos)) {
                arena.setPlayerGridPos(landingPos);
                BlockPos bp = arena.gridToBlockPos(landingPos);
                member.requestTeleport(bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5);
                broadcastPlayerPositionToOthers(member);
                BlockPos impactBp = arena.gridToBlockPos(landingPos);
                fmWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                    impactBp.getX() + 0.5, impactBp.getY() + 0.5, impactBp.getZ() + 0.5,
                    5, 0.3, 0.3, 0.3, 0.01);
                handleVoidRiftEntry(landingPos);
            }
        } finally {
            if (fmSwapped && !fmTargetDied) {
                this.player = savedFmPlayer;
                retargetEffectsToCurrentPlayer();
                arena.setPlayerGridPos(savedFmGrid);
            }
        }
    }

    /**
     * Apply a status effect to EVERY live party member (solo: just {@code player}) - the
     * party-wide analogue of a single {@link #addEffectHooked} call, backing
     * {@link com.crackedgames.craftics.combat.miniboss.MinibossContext#applyPartyEffect}
     * for weather-style mechanics (e.g. a sandstorm blinding everyone).
     *
     * <p>Follows the same swap-and-restore discipline as {@link #dragPartyMember}: for each
     * member, swap {@code this.player} to them and retarget effects, apply the effect, then
     * restore {@code this.player} and retarget again in a {@code finally}. Unlike
     * {@code dragPartyMember} there's no void-fall/teleport path that can end the fight
     * mid-loop, so the restore is unconditional.
     */
    private void applyEffectToParty(CombatEffects.EffectType type, int turns) {
        for (ServerPlayerEntity member : new ArrayList<>(partyPlayers.isEmpty()
                ? java.util.List.of(player) : partyPlayers)) {
            if (member == null || member.isRemoved() || member.isDisconnected()) continue;
            if (deadPartyMembers.contains(member.getUuid())) continue;

            ServerPlayerEntity savedPePlayer = this.player;
            boolean peSwapped = member != savedPePlayer;
            if (peSwapped) {
                this.player = member;
                retargetEffectsToCurrentPlayer();
            }
            try {
                addEffectHooked(type, turns, 0);
            } finally {
                if (peSwapped) {
                    this.player = savedPePlayer;
                    retargetEffectsToCurrentPlayer();
                }
            }
        }
        sendSync();
    }

    /**
     * Highlight a warning tile for the player (red glow effect).
     */
    private void highlightWarningTile(GridPos tile) {
        // Send warning tile highlight to client for rendering
        if (player != null) {
            sendToAllParty(new CombatEventPayload(
                CombatEventPayload.EVENT_TILE_WARNING, 0, 0, 0, tile.x(), tile.z()
            ));
        }
    }

    /**
     * Render a boss warning. Some warnings only use particles/client overlays,
     * while line-style telegraphs also place a temporary floor marker.
     */
    private void renderBossWarning(com.crackedgames.craftics.combat.ai.boss.BossWarning warning) {
        if (warning == null) return;
        syncSpecialBossWarningMarkers(warning);
        // Always highlight affected tiles via the client-side red overlay
        for (GridPos tile : warning.getAffectedTiles()) {
            highlightWarningTile(tile);
        }

        // Spawn thematic particles based on warning type and color
        switch (warning.getType()) {
            case GROUND_CRACK -> {
                // Pick thematic crack particles based on boss color
                net.minecraft.particle.ParticleEffect crackParticle = getWarningParticleForColor(warning.getColor());
                spawnWarningParticles(warning.getAffectedTiles(), crackParticle, 3);
                // Additional rumble particles for all ground cracks
                spawnWarningParticles(warning.getAffectedTiles(), net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE, 1);
            }
            case GATHERING_PARTICLES -> {
                // Converging particles -boss is charging up
                net.minecraft.particle.ParticleEffect gatherParticle = getWarningParticleForColor(warning.getColor());
                spawnWarningParticles(warning.getAffectedTiles(), gatherParticle, 2);
                spawnWarningParticles(warning.getAffectedTiles(), net.minecraft.particle.ParticleTypes.ENCHANT, 3);
            }
            case TILE_HIGHLIGHT -> {
                // Danger zone -subtle shimmer particles on top of the red overlay
                net.minecraft.particle.ParticleEffect shimmerParticle = getWarningParticleForColor(warning.getColor());
                spawnWarningParticles(warning.getAffectedTiles(), shimmerParticle, 2);
            }
            case DIRECTIONAL -> {
                // Directional wind/spark particles. When the warning carries a real
                // direction, particles DRIFT along it (velocity mode) so even the
                // server-side layer reads "that way", matching the client arrows.
                if (warning.hasDirection() && player != null && arena != null) {
                    ServerWorld dirWorld = (ServerWorld) player.getEntityWorld();
                    for (GridPos tile : warning.getAffectedTiles()) {
                        if (!arena.isInBounds(tile)) continue;
                        BlockPos bp = arena.gridToBlockPos(tile);
                        // count=0 -> offsets become velocity; speed scales the vector
                        dirWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                            bp.getX() + 0.5, bp.getY() + 1.2, bp.getZ() + 0.5,
                            0, warning.getDirX(), 0.02, warning.getDirZ(), 0.18);
                        dirWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CRIT,
                            bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5,
                            0, warning.getDirX(), 0.0, warning.getDirZ(), 0.3);
                    }
                } else {
                    spawnWarningParticles(warning.getAffectedTiles(), net.minecraft.particle.ParticleTypes.CLOUD, 2);
                    spawnWarningParticles(warning.getAffectedTiles(), net.minecraft.particle.ParticleTypes.CRIT, 1);
                }
            }
            case ENTITY_GLOW -> {
                // Boss is powering up -bright sparks
                spawnWarningParticles(warning.getAffectedTiles(), net.minecraft.particle.ParticleTypes.END_ROD, 2);
                spawnWarningParticles(warning.getAffectedTiles(), net.minecraft.particle.ParticleTypes.ENCHANTED_HIT, 1);
            }
            case SOUND_ONLY -> {} // No particles for sound-only warnings
        }
    }

    /**
     * Pick a thematic warning particle based on the boss warning ARGB color.
     * Uses the dominant color channel to determine the boss theme.
     */
    private net.minecraft.particle.ParticleEffect getWarningParticleForColor(int argb) {
        int r = (argb >> 16) & 0xFF;
        int g = (argb >> 8) & 0xFF;
        int b = argb & 0xFF;

        // Fire/lava bosses: heavy red, low blue
        if (r > 180 && b < 100 && g < 150) return net.minecraft.particle.ParticleTypes.FLAME;
        // Ice/water bosses: heavy blue
        if (b > 150 && r < 100) return net.minecraft.particle.ParticleTypes.SNOWFLAKE;
        // Water/tidal: moderate blue with some green
        if (b > 130 && g > 80 && r < 100) return net.minecraft.particle.ParticleTypes.SPLASH;
        // Nature/chorus: heavy green
        if (g > 150 && r < 150 && b < 150) return net.minecraft.particle.ParticleTypes.HAPPY_VILLAGER;
        // Void/ender: purple tones (r and b both high, g low)
        if (r > 60 && b > 100 && g < 100) return net.minecraft.particle.ParticleTypes.PORTAL;
        // Wither/dark: very dark colors
        if (r < 80 && g < 80 && b < 80) return net.minecraft.particle.ParticleTypes.SOUL;
        // Sand/earth: tan/brown
        if (r > 150 && g > 100 && b < 100) return net.minecraft.particle.ParticleTypes.ASH;
        // White/bright: phase transitions
        if (r > 200 && g > 200 && b > 200) return net.minecraft.particle.ParticleTypes.FLASH;
        // Default
        return net.minecraft.particle.ParticleTypes.CRIT;
    }

    private void spawnWarningParticles(java.util.List<GridPos> tiles,
                                       net.minecraft.particle.ParticleEffect particle,
                                       int countPerTile) {
        if (player == null || arena == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        for (GridPos tile : tiles) {
            if (!arena.isInBounds(tile)) continue;
            BlockPos bp = arena.gridToBlockPos(tile);
            world.spawnParticles(
                particle,
                bp.getX() + 0.5,
                bp.getY() + 0.15,
                bp.getZ() + 0.5,
                countPerTile,
                0.18,
                0.02,
                0.18,
                0.01
            );
        }
    }

    /**
     * Spawn telegraph particles when a BossAbility warning is first placed.
     * These give the player an immediate visual cue that danger is incoming.
     */
    private void spawnBossAbilityTelegraphParticles(EnemyAction.BossAbility ba) {
        if (player == null || arena == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        String name = ba.abilityName();
        java.util.List<GridPos> tiles = ba.warningTiles();
        if (tiles == null || tiles.isEmpty()) return;

        // Pick telegraph particles based on ability name
        net.minecraft.particle.ParticleEffect primary;
        net.minecraft.particle.ParticleEffect secondary;
        switch (name) {
            case "ash_storm" -> { primary = net.minecraft.particle.ParticleTypes.ASH; secondary = net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME; }
            case "wither_slash", "wither_applied" -> { primary = net.minecraft.particle.ParticleTypes.SOUL; secondary = net.minecraft.particle.ParticleTypes.SMOKE; }
            case "ground_slam" -> { primary = net.minecraft.particle.ParticleTypes.LAVA; secondary = net.minecraft.particle.ParticleTypes.FLAME; }
            case "absorb" -> { primary = net.minecraft.particle.ParticleTypes.LAVA; secondary = net.minecraft.particle.ParticleTypes.FLAME; }
            case "fortify_shell", "fortify_shell_reflect" -> { primary = net.minecraft.particle.ParticleTypes.END_ROD; secondary = net.minecraft.particle.ParticleTypes.ENCHANTED_HIT; }
            case "soul_chain" -> { primary = net.minecraft.particle.ParticleTypes.SOUL_FIRE_FLAME; secondary = net.minecraft.particle.ParticleTypes.SOUL; }
            case "void_rift", "void_beam", "null_burst", "ender_roar" -> { primary = net.minecraft.particle.ParticleTypes.PORTAL; secondary = net.minecraft.particle.ParticleTypes.REVERSE_PORTAL; }
            case "darkness_pulse", "tremor_stomp", "sonic_boom" -> { primary = net.minecraft.particle.ParticleTypes.SCULK_SOUL; secondary = net.minecraft.particle.ParticleTypes.LARGE_SMOKE; }
            case "lights_out" -> { primary = net.minecraft.particle.ParticleTypes.LARGE_SMOKE; secondary = net.minecraft.particle.ParticleTypes.SMOKE; }
            default -> { primary = net.minecraft.particle.ParticleTypes.ENCHANT; secondary = net.minecraft.particle.ParticleTypes.CRIT; }
        }

        // Spawn a modest burst on each warned tile (not too many -these persist visually)
        for (GridPos tile : tiles) {
            if (!arena.isInBounds(tile)) continue;
            BlockPos bp = arena.gridToBlockPos(tile);
            world.spawnParticles(primary,
                bp.getX() + 0.5, bp.getY() + 0.5, bp.getZ() + 0.5,
                3, 0.2, 0.3, 0.2, 0.01);
            world.spawnParticles(secondary,
                bp.getX() + 0.5, bp.getY() + 0.2, bp.getZ() + 0.5,
                2, 0.15, 0.15, 0.15, 0.005);
        }
    }


    /**
     * Tick all temporary terrain tiles (fire, lava, etc.) -called at the start of each turn.
     */
    private void tickTemporaryTerrain() {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        for (int x = 0; x < arena.getWidth(); x++) {
            for (int z = 0; z < arena.getHeight(); z++) {
                GridTile tile = arena.getTile(x, z);
                if (tile != null && tile.getTurnsRemaining() > 0) {
                    TileType before = tile.getType();
                    tile.tickTurn();
                    if (tile.getType() != before) {
                        BlockPos bp = new BlockPos(
                            arena.getOrigin().getX() + x,
                            arena.getOrigin().getY(),
                            arena.getOrigin().getZ() + z);
                        // Fungus plants live in the Y+1 overlay and never touched the floor block,
                        // so on revert just clear the plant above - repainting floor-Y would stomp
                        // the intact biome floor with a redundant block.
                        if (before == TileType.CRIMSON_FUNGUS || before == TileType.WARPED_FUNGUS) {
                            world.setBlockState(bp.up(), Blocks.AIR.getDefaultState());
                            continue;
                        }
                        // Temporary wall-style obstacle terrain is rendered in the
                        // obstacle layer (Y+1); clear it when the tile restores. Flames
                        // live in that same slot, so an expiring boss fire clears too.
                        if (before == TileType.OBSTACLE) {
                            world.setBlockState(bp.up(), Blocks.AIR.getDefaultState());
                        } else if (before.isFlames()) {
                            clearFlameOverlay(world, bp);
                        }
                        world.setBlockState(bp, tile.getBlockType().getDefaultState());
                    }
                }
            }
        }
    }

    /**
     * Advance the Tidecaller's tidal wave. The wave is a full-width, 3-thick band of water
     * that marches 3 tiles per turn from one end of the arena to the other and then is gone.
     * It runs autonomously so the Tidecaller keeps acting while it sweeps. (The dragon used
     * to march its breath the same way; its fire now seeds the arena's own burn cycle and
     * spreads from there, so this is the last of the hand-marched waves.)
     *
     * <p>It deals NO damage. Anyone the band catches is CARRIED the same 3 tiles the wave
     * moved, via the shared forced-movement resolver, so a blocked destination fails safe
     * exactly like every other push in the game (carried as far as it can, never overlapping
     * an entity). The water it leaves behind Soaks whoever wades it, which is what sets up
     * Conduction.
     */
    private void tickTidecallerWave() {
        if (player == null || arena == null) return;
        for (CombatEntity e : enemies) {
            if (!e.isAlive() || !e.isBoss()) continue;
            EnemyAI ai = resolveAi(e);
            if (!(ai instanceof com.crackedgames.craftics.combat.ai.boss.TidecallerAI tideAi)) continue;
            if (tideAi.getActiveWave() == null) continue;

            // Snapshot who the band holds BEFORE it moves: they ride from where they stand,
            // not from wherever the advanced band happens to reach.
            int[] carry = tideAi.getWaveCarry();
            java.util.List<ServerPlayerEntity> riders = new java.util.ArrayList<>();
            if (partyPlayers.size() > 1) {
                for (ServerPlayerEntity member : partyPlayers) {
                    if (member == null || member.isRemoved() || member.isDisconnected()) continue;
                    if (deadPartyMembers.contains(member.getUuid())) continue;
                    if (tideAi.waveCovers(gridPosOf(member))) riders.add(member);
                }
            } else if (tideAi.waveCovers(arena.getPlayerGridPos())) {
                riders.add(player);
            }

            List<GridPos> flooded = tideAi.tickWave();
            ServerWorld world = (ServerWorld) player.getEntityWorld();

            // Carry each rider exactly once, one tile at a time so the existing resolver
            // stops them at the first wall/occupied tile instead of overlapping anything.
            if (carry != null && (carry[0] != 0 || carry[1] != 0)) {
                int dirX = Integer.signum(carry[0]);
                int dirZ = Integer.signum(carry[1]);
                int carryTiles = Math.abs(carry[0]) + Math.abs(carry[1]);
                for (ServerPlayerEntity rider : riders) {
                    ServerPlayerEntity savedTidePlayer = this.player;
                    GridPos savedTideGrid = arena.getPlayerGridPos();
                    boolean tideSwapped = rider != savedTidePlayer;
                    if (tideSwapped) {
                        this.player = rider;
                        retargetEffectsToCurrentPlayer();
                        arena.setPlayerGridPos(gridPosOf(rider));
                    }
                    try {
                        GridPos before = arena.getPlayerGridPos();
                        resolveForcedMovement(new EnemyAction.ForcedMovement(-1, dirX, dirZ, carryTiles));
                        if (!active) return; // the carry killed them (void) and ended the fight
                        GridPos after = arena.getPlayerGridPos();
                        if (!after.equals(before)) {
                            sendMessage("§3§l≈ The tide sweeps "
                                + (tideSwapped ? rider.getName().getString() : "you")
                                + " along " + before.manhattanDistance(after) + " tiles!");
                        } else {
                            sendMessage("§3≈ The tide breaks against your back - nowhere to be carried.");
                        }
                    } finally {
                        if (tideSwapped && active) {
                            this.player = savedTidePlayer;
                            retargetEffectsToCurrentPlayer();
                            arena.setPlayerGridPos(savedTideGrid);
                        }
                    }
                }
            }

            if (flooded.isEmpty()) {
                if (!riders.isEmpty()) sendSync();
                continue;
            }

            // Flood the band. Temporary water so the arena drains behind the wave and the
            // fight does not silently turn into the phase-2 deluge.
            for (GridPos pos : flooded) {
                GridTile tile = arena.getTile(pos);
                if (tile == null) continue;
                if (tile.getType() == TileType.NORMAL) {
                    tile.setTemporaryType(TileType.WATER, 2);
                    // gridToBlockPos returns the standing block (origin.getY() + 1).
                    // The flood must be PART of the floor, so place the water at
                    // origin.getY() with .down() - matching resolveCreateTerrain,
                    // which builds terrain at origin.getY() ("floor level, not
                    // above"). The GridTile stays on the same logical tile; only
                    // the world block Y drops to the floor.
                    BlockPos floorBp = arena.gridToBlockPos(pos).down();
                    world.setBlockState(floorBp, tile.getBlockType().getDefaultState());
                }
                BlockPos bp = arena.gridToBlockPos(pos);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SPLASH,
                    bp.getX() + 0.5, bp.getY() + 0.9, bp.getZ() + 0.5,
                    6, 0.35, 0.3, 0.35, 0.05);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.BUBBLE,
                    bp.getX() + 0.5, bp.getY() + 0.6, bp.getZ() + 0.5,
                    3, 0.25, 0.2, 0.25, 0.02);
            }
            sendTileFlash(flooded, 0xFF3388CC, 14);

            // Soak whoever the wave leaves standing in it. The move-into-water path only
            // fires on a player's own movement, so without this the wave could wash over
            // someone and leave them dry - and Conduction's payoff depends on Soaked.
            java.util.Set<GridPos> floodedSet = new java.util.HashSet<>(flooded);
            if (partyPlayers.size() > 1) {
                for (ServerPlayerEntity member : partyPlayers) {
                    if (member == null || member.isRemoved() || member.isDisconnected()) continue;
                    if (deadPartyMembers.contains(member.getUuid())) continue;
                    if (!floodedSet.contains(gridPosOf(member))) continue;
                    if (boatOf(member) != null || member.hasVehicle()) continue;
                    ServerPlayerEntity savedSoakPlayer = this.player;
                    boolean soakSwapped = member != savedSoakPlayer;
                    if (soakSwapped) { this.player = member; retargetEffectsToCurrentPlayer(); }
                    try {
                        addEffectHooked(CombatEffects.EffectType.SOAKED, 2, 0);
                        sendMessage("§b  The tidal wave leaves "
                            + (soakSwapped ? member.getName().getString() : "you") + " Soaked for 2 turns.");
                    } finally {
                        if (soakSwapped) { this.player = savedSoakPlayer; retargetEffectsToCurrentPlayer(); }
                    }
                }
            } else if (floodedSet.contains(arena.getPlayerGridPos())
                    && boatOf(player) == null && !player.hasVehicle()) {
                addEffectHooked(CombatEffects.EffectType.SOAKED, 2, 0);
                sendMessage("§b  The tidal wave leaves you Soaked for 2 turns.");
            }

            // Soak the drowned too: the chain arcs through them, and a wave that soaked only
            // the player would quietly make Conduction weaker than the water it swims in.
            java.util.Set<Integer> soakedEnemies = new java.util.HashSet<>();
            for (GridPos pos : flooded) {
                CombatEntity occ = arena.getOccupant(pos);
                if (occ == null || !occ.isAlive() || occ.isProjectile()) continue;
                if (occ == e) continue; // the Tidecaller rides its own tide
                if (!soakedEnemies.add(occ.getEntityId())) continue; // multi-tile: once only
                occ.stackSoaked(2, 1);
            }

            world.playSound(null, player.getBlockPos(),
                net.minecraft.sound.SoundEvents.ENTITY_PLAYER_SPLASH_HIGH_SPEED,
                net.minecraft.sound.SoundCategory.HOSTILE, 0.7f, 0.7f);
            sendSync();
        }
    }

    private void primePendingTnt(GridPos tile, String message) {
        primePendingTnt(tile, message, 1);
    }

    /**
     * @param fuseRounds rounds until detonation. 1 = explodes at the next round
     *                   transition (player TNT -they placed it knowing it'd
     *                   blow up "next round"). 2+ = gives the target at least
     *                   one full turn with the physical TNT block visible
     *                   before it detonates (boss TNT -otherwise the warning
     *                   resolves and the round transition fires the explosion
     *                   in the same beat, leaving the player no chance to
     *                   react to the actual block).
     */
    private void primePendingTnt(GridPos tile, String message, int fuseRounds) {
        if (!arena.isInBounds(tile)) return;

        for (PendingTnt existing : pendingTnts) {
            if (existing.tile().equals(tile)) return;
        }

        BlockPos tntBp = arena.gridToBlockPos(tile);
        ServerWorld world = (ServerWorld) player.getEntityWorld();

        // A charge primed where somebody is standing goes off THERE, now. gridToBlockPos is
        // standing height, so the alternative is a solid TNT block written inside a body:
        // vanilla ejects whatever it overlaps, and the shove is what put a player in a void
        // pit with no telegraph that could have warned them which way they were going. A
        // demolition charge planted at your feet detonating is also just the honest reading.
        // The rest of the board is lifted out first so this cannot clip anyone else's fuse.
        if (isTileOccupiedByCombatant(tile)) {
            sendMessage("§c§l  The charge goes off the instant it lands!");
            List<PendingTnt> others = new ArrayList<>(pendingTnts);
            pendingTnts.clear();
            pendingTnts.add(new PendingTnt(tile, tntBp, 1));
            try {
                detonatePendingTnts();
            } finally {
                pendingTnts.addAll(others);
            }
            return;
        }

        world.setBlockState(tntBp, Blocks.TNT.getDefaultState());
        world.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE,
            tntBp.getX() + 0.5, tntBp.getY() + 0.8, tntBp.getZ() + 0.5,
            8, 0.2, 0.3, 0.2, 0.01);
        highlightWarningTile(tile);
        pendingTnts.add(new PendingTnt(tile, tntBp, Math.max(1, fuseRounds)));
        if (message != null && !message.isEmpty()) {
            sendMessage(message);
        }
    }

    /**
     * Register a light zone at the given position with specified radius.
     * Light zones negate darkness effects for the player standing within them.
     */
    private void registerLightZone(GridPos pos, int radius) {
        if (arena.isInBounds(pos)) {
            litZones.put(pos, radius);
        }
    }

    /**
     * Spawn a falling-block anvil visual above the target enemy, queue the
     * actual damage to apply when it lands (~12 ticks). The block is
     * non-damaging on impact -Craftics' base damage applies instead.
     *
     * Vanilla FallingBlockEntity converts itself into a REAL anvil block the
     * tick it lands (well before our discard countdown), so we record the
     * landing floor position up front: tickPendingAnvils clears it on resolve,
     * and endCombat's placed-block restore guarantees it never survives the
     * level even if the timing slips. Otherwise a left-behind anvil sits at
     * floor+1 and gets re-read as a permanent OBSTACLE on the next visit.
     */
    private void spawnAnvilDrop(int targetEntityId, int damage) {
        CombatEntity victim = null;
        for (CombatEntity e : enemies) {
            if (e.getEntityId() == targetEntityId) { victim = e; break; }
        }
        if (victim == null || !victim.isAlive()) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        // The falling anvil settles on the floor the VICTIM stands on. On sunken
        // tiles (water, deep water, lava, low ground, powder snow) the victim -and
        // thus the floor the anvil lands on- sits one block below the flat overlay
        // Y that gridToBlockPos returns. Using gridToBlockPos here made the anvil
        // land lower than the recorded/cleanup position, so on those tiles the real
        // anvil block was never cleared and got re-read as a permanent obstacle.
        // Anchor the landing to the victim's actual standing Y instead.
        BlockPos overlayBp = arena.gridToBlockPos(victim.getGridPos());
        int landY = (int) Math.floor(arena.getEntityY(victim.getGridPos()));
        BlockPos targetBp = new BlockPos(overlayBp.getX(), landY, overlayBp.getZ());
        recordPlacedBlock(targetBp);
        double cx = targetBp.getX() + 0.5;
        double cz = targetBp.getZ() + 0.5;
        // Spawn 6 blocks above the landing floor so the fall is visible but quick.
        double spawnY = targetBp.getY() + 6.0;

        //? if <=1.21.1 {
        net.minecraft.entity.FallingBlockEntity fbe =
            net.minecraft.entity.EntityType.FALLING_BLOCK.create(world);
        //?} else {
        /*net.minecraft.entity.FallingBlockEntity fbe =
            net.minecraft.entity.EntityType.FALLING_BLOCK.create(world, net.minecraft.entity.SpawnReason.TRIGGERED);
        *///?}
        if (fbe == null) return;
        net.minecraft.nbt.NbtCompound nbt = new net.minecraft.nbt.NbtCompound();
        fbe.writeNbt(nbt);
        nbt.put("BlockState",
            net.minecraft.nbt.NbtHelper.fromBlockState(Blocks.ANVIL.getDefaultState()));
        nbt.putBoolean("DropItem", false);
        nbt.putBoolean("HurtEntities", false);
        nbt.putInt("Time", 1);
        fbe.readNbt(nbt);
        fbe.setPosition(cx, spawnY, cz);
        fbe.setVelocity(0, -0.4, 0);
        fbe.timeFalling = 1;
        world.spawnEntity(fbe);

        pendingAnvils.add(new PendingAnvil(targetEntityId, damage, fbe.getUuid(), 14, targetBp.toImmutable()));

        world.playSound(null, targetBp,
            net.minecraft.sound.SoundEvents.BLOCK_ANVIL_FALL,
            net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 0.85f);
    }

    /**
     * Tick pending anvil drops once per combat tick. When the countdown hits
     * 0, discard the visual entity, apply the queued Special damage, and run
     * the death check. Mirrors the pendingTnts tick pattern.
     */
    private void tickPendingAnvils() {
        if (pendingAnvils.isEmpty()) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        java.util.Iterator<PendingAnvil> it = pendingAnvils.iterator();
        while (it.hasNext()) {
            PendingAnvil pa = it.next();
            int next = pa.ticksLeft() - 1;
            if (next > 0) {
                // Replace with a decremented copy (record is immutable).
                int idx = pendingAnvils.indexOf(pa);
                pendingAnvils.set(idx, new PendingAnvil(pa.targetEntityId(), pa.damage(), pa.fbeUuid(), next,
                    pa.landingPos()));
                // Iterator is now stale -we set in place so continue.
                continue;
            }
            it.remove();
            // Discard the visual falling block, and clear the real anvil block if
            // vanilla already converted it on landing (it lands in ~5-7 ticks, well
            // before this 14-tick countdown). Restore the floor we recorded at spawn
            // so the stage shows the anvil fall, then nothing left behind.
            net.minecraft.entity.Entity fbe = world.getEntity(pa.fbeUuid());
            if (fbe != null) fbe.discard();
            // Clear the real anvil block vanilla left when the falling block landed.
            // The exact rest Y can vary by a block depending on what was solid in the
            // column (liquids/offset-Y tiles settle the anvil lower), so scan a small
            // vertical band around the recorded landing position rather than a single
            // cell, restoring whatever was there before (or air).
            if (pa.landingPos() != null) {
                for (int dy = 1; dy >= -2; dy--) {
                    BlockPos check = pa.landingPos().up(dy);
                    if (world.getBlockState(check).isOf(Blocks.ANVIL)) {
                        net.minecraft.block.BlockState original = placedBlockRestores.get(check);
                        world.setBlockState(check,
                            original != null ? original : Blocks.AIR.getDefaultState());
                        break;
                    }
                }
            }

            CombatEntity victim = null;
            for (CombatEntity e : enemies) {
                if (e.getEntityId() == pa.targetEntityId()) { victim = e; break; }
            }
            if (victim == null || !victim.isAlive()) continue;
            // Special, like every other utility item, and like this method's own message has
            // always claimed. It used to call takeDamage directly, which meant an anvil got no
            // Special affinity bonus and ignored mob resistances while telling the player it had
            // dealt "Special damage".
            int dealt = applySpecialUtilityDamage(victim, pa.damage());
            BlockPos vbp = arena.gridToBlockPos(victim.getGridPos());
            world.playSound(null, vbp,
                net.minecraft.sound.SoundEvents.BLOCK_ANVIL_LAND,
                net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 1.0f);
            world.spawnParticles(new net.minecraft.particle.BlockStateParticleEffect(
                    net.minecraft.particle.ParticleTypes.BLOCK,
                    Blocks.ANVIL.getDefaultState()),
                vbp.getX() + 0.5, vbp.getY() + 0.3, vbp.getZ() + 0.5,
                14, 0.4, 0.1, 0.4, 0.05);
            sendMessage("§8Anvil crushes " + victim.getDisplayName()
                + " for " + dealt + " Special damage!");
            checkAndHandleDeath(victim);
            sendSync();
            refreshHighlights();
        }
        // checkAndHandleDeath never ends the fight on its own, so a deferred anvil
        // landing the final blow would soft-lock the level. Re-run the same
        // win-condition check every other damage path uses (see handleAttack /
        // tryHandleInstrument) once all anvils this tick have resolved.
        if (phase != CombatPhase.GAME_OVER && phase != CombatPhase.LEVEL_COMPLETE
                && !anyEnemyBlockingVictory()) {
            handleVictory();
        }
    }

    /**
     * Drop a real block in the world for a placed utility-item tile effect, and
     * mark the tile as OBSTACLE when the block is a full cube so pathing
     * respects the wall. Non-full-cube blocks (campfire, scaffolding, spore
     * blossom, bell) leave the tile walkable.
     */
    private void placeUtilityBlock(String effectType, GridPos effectPos) {
        if (effectPos == null || !arena.isInBounds(effectPos)) return;
        net.minecraft.block.Block block;
        boolean obstacle;
        boolean atFloorLevel; // honey/slime sit IN the floor (trap), not on top of it
        switch (effectType) {
            // Light sources: placed at body level (Y+1), tile stays walkable. These
            // ALSO register a light zone in the caller (torch r2, lantern/campfire r3)
            // to hold back Darkness - but the physical block was never placed, so the
            // AP + item were consumed with nothing to show. Placed now.
            case "torch"         -> { block = Blocks.TORCH;         obstacle = false; atFloorLevel = false; }
            case "lantern"       -> { block = Blocks.LANTERN;       obstacle = false; atFloorLevel = false; }
            case "campfire"      -> { block = Blocks.CAMPFIRE;      obstacle = false; atFloorLevel = false; }
            case "scaffold"      -> { block = Blocks.SCAFFOLDING;   obstacle = false; atFloorLevel = false; }
            case "spore_blossom" -> { block = Blocks.SPORE_BLOSSOM; obstacle = false; atFloorLevel = false; }
            case "bell"          -> { block = Blocks.BELL;          obstacle = false; atFloorLevel = false; }
            case "jukebox"       -> { block = Blocks.JUKEBOX;       obstacle = true;  atFloorLevel = false; }
            case "sponge"        -> { block = Blocks.SPONGE;        obstacle = true;  atFloorLevel = false; }
            // Honey + slime are TRAPS, not walls -they replace the floor block
            // so the enemy walks ONTO them and triggers the effect. Tile stays
            // walkable so pathing AI doesn't route around them.
            case "honey"         -> { block = Blocks.HONEY_BLOCK;   obstacle = false; atFloorLevel = true;  }
            case "slime"         -> { block = Blocks.SLIME_BLOCK;   obstacle = false; atFloorLevel = true;  }
            // Powder snow keeps the existing TileType.POWDER_SNOW behavior
            // (mobs sink into it / freeze) rather than becoming an OBSTACLE.
            // The tile type is set by the caller's setType branch. It sits at floor
            // level (replacing the floor block) like honey/slime -placing it in the
            // Y+1 overlay space left the snow floating one block above the ground.
            case "powder_snow"   -> { block = Blocks.POWDER_SNOW;   obstacle = false; atFloorLevel = true; }
            default -> { return; } // not a utility-block effect
        }
        BlockPos bp = arena.gridToBlockPos(effectPos);
        if (atFloorLevel) bp = bp.down();
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        recordPlacedBlock(bp);
        world.setBlockState(bp, block.getDefaultState(),
            net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);
        GridTile tile = arena.getTile(effectPos);
        if (tile != null) {
            if (obstacle) {
                tile.setType(TileType.OBSTACLE);
                tile.setBlockType(block);
            } else if (!atFloorLevel) {
                // Don't overwrite the floor block type for floor-level traps
                // (honey/slime) -we need the original block ID preserved so
                // the trap can restore the floor on consumption.
                tile.setBlockType(block);
            }
        }
    }

    /**
     * Unregister a light zone at the given position.
     */
    private void unregisterLightZone(GridPos pos) {
        litZones.remove(pos);
    }

    /**
     * Check if a given position is within a lit zone (torch/lantern radius).
     * Returns true if the position is within the radius of any light source -
     * planted, or carried in someone's offhand ({@link #walkingLightRadiusOf}).
     */
    private boolean isPositionLit(GridPos pos) {
        if (pos == null) return false;
        for (java.util.Map.Entry<GridPos, Integer> light : litZones.entrySet()) {
            GridPos lightPos = light.getKey();
            int radius = light.getValue();
            int dist = Math.max(Math.abs(pos.x() - lightPos.x()), Math.abs(pos.z() - lightPos.z()));
            if (dist <= radius) {
                return true;
            }
        }
        // Carried light: a torch or lantern riding in a party member's OFFHAND is a
        // walking light zone centered on them, at the same radius the placed block
        // registers. The tradeoff is built in - that hand isn't holding a shield.
        for (ServerPlayerEntity member : getAllParticipants()) {
            if (member == null || member.isRemoved() || member.isDisconnected()) continue;
            if (deadPartyMembers.contains(member.getUuid())) continue;
            int radius = walkingLightRadiusOf(member);
            if (radius <= 0) continue;
            GridPos mpos = gridPosOf(member);
            if (mpos == null) continue;
            if (Math.max(Math.abs(pos.x() - mpos.x()), Math.abs(pos.z() - mpos.z())) <= radius) {
                return true;
            }
        }
        return false;
    }

    /** Light radius this player carries in their offhand: torch 2, lantern 3, else 0.
     *  Matches the radii the placed blocks register in {@code registerLightZone}. */
    private static int walkingLightRadiusOf(ServerPlayerEntity member) {
        var off = member.getOffHandStack();
        if (off.isOf(Items.TORCH)) return 2;
        if (off.isOf(Items.LANTERN)) return 3;
        return 0;
    }

    /**
     * Walking banner aura: an offhand banner is a carried version of the planted one -
     * anyone (carrier included) within {@link BannerEffects#AURA_RADIUS} of a carrier
     * gets {@link BannerEffects#DEFENSE_BONUS}. Flat base bonus, not the Special-scaled
     * planted value: the scaling is frozen at planting time, and a carried banner never
     * had a planting. Doesn't stack with itself across multiple carriers, but does stack
     * with a planted banner, exactly as the Beacon helmet's aura does.
     */
    private int walkingBannerBonusAt(GridPos pos) {
        if (pos == null || arena == null) return 0;
        for (ServerPlayerEntity member : getAllParticipants()) {
            if (member == null || member.isRemoved() || member.isDisconnected()) continue;
            if (deadPartyMembers.contains(member.getUuid())) continue;
            if (!BannerEffects.isBanner(member.getOffHandStack().getItem())) continue;
            GridPos mpos = gridPosOf(member);
            if (mpos != null && mpos.manhattanDistance(pos) <= BannerEffects.AURA_RADIUS) {
                return BannerEffects.DEFENSE_BONUS;
            }
        }
        return 0;
    }

    /** Tile of the most recently placed bed, or null. Overworld fights only. */
    private GridPos bedRespawnAnchor = null;

    /** Entity id for a player-placed end crystal. */
    public static final String END_CRYSTAL_ID = "craftics:end_crystal";
    /** Blast radius (manhattan) and damage of an end crystal, by distance. */
    private static final int[] CRYSTAL_FLAT = {14, 10, 6, 3};
    private static final double[] CRYSTAL_PCT = {0.35, 0.24, 0.15, 0.08};
    /** Live end-crystal display entities, keyed by their block-object entity id. */
    private final java.util.Map<Integer, net.minecraft.entity.Entity> crystalVisuals = new java.util.HashMap<>();

    /**
     * Give a placed end crystal a real end-crystal entity to look at. The block object
     * is only the grid anchor and HP; this is what the player actually sees and aims at.
     * Mirrors {@link #spawnDecoyVisual}'s split for the armor stand.
     */
    private void spawnEndCrystalVisual(CombatEntity anchor, GridPos pos, ServerWorld world) {
        try {
            BlockPos bp = arena.gridToBlockPos(pos);
            net.minecraft.entity.decoration.EndCrystalEntity vis =
                new net.minecraft.entity.decoration.EndCrystalEntity(world,
                    bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5);
            vis.setShowBottom(false);
            vis.setInvulnerable(true); // it dies with its anchor, never to stray damage
            world.spawnEntity(vis);
            crystalVisuals.put(anchor.getEntityId(), vis);
        } catch (Exception e) {
            CrafticsMod.LOGGER.warn("end crystal visual failed: {}", e.getMessage());
        }
    }

    /** Remove a destroyed crystal's display entity. Safe to call for non-crystals. */
    private void clearEndCrystalVisual(CombatEntity entity) {
        net.minecraft.entity.Entity vis = crystalVisuals.remove(entity.getEntityId());
        if (vis != null) vis.discard();
    }

    /** Crystals that have already gone off, so the two death sinks can't double-blast. */
    private final Set<Integer> detonatedCrystals = new HashSet<>();

    /**
     * Detonate {@code entity} if it is a live end crystal that hasn't gone off yet.
     * Called from BOTH death paths - {@code killEnemy} for direct kills and
     * {@code checkAndHandleDeath} for damage-over-time and splash - because a crystal
     * has to fire no matter which one claims it, and must fire exactly once.
     */
    private void tryDetonateEndCrystal(CombatEntity entity) {
        if (entity == null || !END_CRYSTAL_ID.equals(entity.getEntityTypeId())) return;
        if (!detonatedCrystals.add(entity.getEntityId())) return;
        detonateEndCrystal(entity);
    }

    /**
     * Detonate a destroyed end crystal. Called from the death paths, so it fires no
     * matter what killed it - a player shot, a stray AoE, or an enemy standing on top
     * of it. That is the point: once it is on the board, anything that touches it sets
     * it off, including things the player did not plan for.
     */
    private void detonateEndCrystal(CombatEntity crystal) {
        GridPos center = crystal.getGridPos();
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos bp = arena.gridToBlockPos(center);
        clearEndCrystalVisual(crystal);

        world.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION_EMITTER,
            bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5, 2, 0.8, 0.5, 0.8, 0.0);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD,
            bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5, 40, 1.5, 1.0, 1.5, 0.15);
        world.playSound(null, bp,
            net.minecraft.sound.SoundEvents.ENTITY_GENERIC_EXPLODE.value(),
            net.minecraft.sound.SoundCategory.BLOCKS, 1.8f, 1.2f);
        sendMessage("§d§l✷ THE END CRYSTAL DETONATES! ✷");

        int hit = 0;
        int total = 0;
        for (CombatEntity e : new ArrayList<>(enemies)) {
            if (!e.isAlive() || e.isAlly() || e == crystal) continue;
            int dist = Math.abs(e.getGridPos().x() - center.x())
                     + Math.abs(e.getGridPos().z() - center.z());
            if (dist >= CRYSTAL_FLAT.length) continue;
            total += applySpecialUtilityDamage(e,
                CRYSTAL_FLAT[dist] + e.percentMaxHpDamage(CRYSTAL_PCT[dist]));
            hit++;
            if (!e.isAlive()) checkAndHandleDeath(e);
        }

        // The player is not exempt. Standing next to your own crystal when it goes is
        // the mistake the item is built around.
        GridPos self = arena.getPlayerGridPos();
        if (self != null) {
            int d = Math.abs(self.x() - center.x()) + Math.abs(self.z() - center.z());
            if (d < CRYSTAL_FLAT.length) {
                int dealt = damagePlayer(CRYSTAL_FLAT[d]);
                sendMessage("§cThe blast catches you for " + dealt + "! §7(HP: " + getPlayerHp() + ")");
            }
        }
        if (hit > 0) sendMessage("§6Caught §c" + hit + "§6 enemies for §c" + total + "§6 total.");
        sendSync();
        refreshHighlights();
    }

    /**
     * Lay down ice. All three variants make the same sliding tile; {@code kind} only
     * decides how much of it there is and whether it lasts.
     */
    private void placeIceTile(GridPos target, String kind) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        boolean blue = "blue".equals(kind);
        boolean melts = "plain".equals(kind);
        net.minecraft.block.Block block = blue ? net.minecraft.block.Blocks.BLUE_ICE
            : (melts ? net.minecraft.block.Blocks.ICE : net.minecraft.block.Blocks.PACKED_ICE);

        java.util.List<GridPos> tiles = new java.util.ArrayList<>();
        tiles.add(target);
        if (blue) {
            // Lay the runway pointing AWAY from the player, so it extends the line the
            // player is already looking down rather than doubling back onto them.
            GridPos self = arena.getPlayerGridPos();
            int dx = 1, dz = 0;
            if (self != null && !self.equals(target)) {
                dx = Integer.signum(target.x() - self.x());
                dz = Integer.signum(target.z() - self.z());
                if (dx == 0 && dz == 0) dx = 1;
            }
            GridPos next = target;
            for (int i = 1; i < com.crackedgames.craftics.combat.ItemUseHandler.BLUE_ICE_LENGTH; i++) {
                next = new GridPos(next.x() + dx, next.z() + dz);
                if (!arena.isInBounds(next)) break;
                GridTile t = arena.getTile(next);
                if (t == null || !t.isWalkable()) break;
                tiles.add(next);
            }
        }

        for (GridPos p : tiles) {
            GridTile t = arena.getTile(p);
            if (t == null) continue;
            if (melts) {
                // Melting ice is a temporary terrain change, which reverts on its own.
                t.setTemporaryType(com.crackedgames.craftics.core.TileType.ICE,
                    com.crackedgames.craftics.combat.ItemUseHandler.ICE_MELT_ROUNDS);
            } else {
                t.setType(com.crackedgames.craftics.core.TileType.ICE);
            }
            t.setBlockType(block);
            BlockPos floorBp = arena.gridToBlockPos(p).down();
            world.setBlockState(floorBp, block.getDefaultState());
        }
        world.playSound(null, arena.gridToBlockPos(target),
            net.minecraft.sound.SoundEvents.BLOCK_GLASS_PLACE,
            net.minecraft.sound.SoundCategory.BLOCKS, 0.9f, 1.3f);
    }

    /**
     * Slide whatever just stepped onto ice. Movement continues along {@code (dx,dz)}
     * over every consecutive ice tile and one tile past the end, so ice is free
     * distance in a straight line - and a straight line you do not get to stop in.
     *
     * <p>Routed through {@link #resolveForcedMovement} so a slide that ends in lava,
     * a pit or off the edge resolves exactly like any other shove. That is the whole
     * risk: laying ice next to a hazard is a trap for both sides.
     */
    private void slideOnIce(GridPos from, int dx, int dz) {
        if (dx == 0 && dz == 0) return;
        int run = 0;
        GridPos scan = from;
        // Count the ice ahead, capped so a pathological all-ice arena can't loop long.
        while (run < 16) {
            GridPos next = new GridPos(scan.x() + dx, scan.z() + dz);
            if (!arena.isInBounds(next)) break;
            GridTile t = arena.getTile(next);
            if (t == null || t.getType() != com.crackedgames.craftics.core.TileType.ICE) break;
            scan = next;
            run++;
        }
        // +1 carries you off the far end onto whatever is past the ice.
        int distance = run + 1;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos bp = arena.gridToBlockPos(from);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.SNOWFLAKE,
            bp.getX() + 0.5, bp.getY() + 0.3, bp.getZ() + 0.5, 14, 0.4, 0.1, 0.4, 0.03);
        world.playSound(null, bp, net.minecraft.sound.SoundEvents.BLOCK_GLASS_STEP,
            net.minecraft.sound.SoundCategory.PLAYERS, 0.7f, 0.7f);
        sendMessage("§bYou slide across the ice!");
        resolveForcedMovement(new EnemyAction.ForcedMovement(-1, dx, dz, distance));
    }

    /**
     * Chorus fruit hop: throw the player to a random safe tile. Random on purpose -
     * an ender pearl is the tool you aim, this is the one you gamble on.
     */
    private void chorusHop(int healed) {
        java.util.List<GridPos> candidates = new java.util.ArrayList<>();
        GridPos cur = arena.getPlayerGridPos();
        for (int x = 0; x < arena.getWidth(); x++) {
            for (int z = 0; z < arena.getHeight(); z++) {
                GridPos p = new GridPos(x, z);
                if (p.equals(cur) || arena.isOccupied(p)) continue;
                GridTile t = arena.getTile(p);
                if (t == null || !t.isSafeForSpawn()) continue;
                candidates.add(p);
            }
        }
        if (candidates.isEmpty()) {
            sendMessage("§5You eat the chorus fruit. §7+" + healed
                + " HP, but there's nowhere to be thrown to.");
            return;
        }
        GridPos dest = candidates.get((int) (Math.random() * candidates.size()));
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos fromBp = arena.gridToBlockPos(cur);
        BlockPos toBp = arena.gridToBlockPos(dest);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
            fromBp.getX() + 0.5, fromBp.getY() + 1.0, fromBp.getZ() + 0.5, 30, 0.4, 0.6, 0.4, 0.3);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
            toBp.getX() + 0.5, toBp.getY() + 1.0, toBp.getZ() + 0.5, 30, 0.4, 0.6, 0.4, 0.3);
        world.playSound(null, toBp, net.minecraft.sound.SoundEvents.ITEM_CHORUS_FRUIT_TELEPORT,
            net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 1.0f);
        arena.setPlayerGridPos(dest);
        player.requestTeleport(toBp.getX() + 0.5, toBp.getY(), toBp.getZ() + 0.5);
        sendMessage("§5The chorus fruit throws you across the arena! §7+" + healed + " HP");
        sendSync();
        refreshHighlights();
    }

    /**
     * True when a bed placed here explodes instead of marking a spawn: the Nether and
     * End campaign regions, matching the vanilla rule that a bed you cannot sleep in
     * blows up.
     *
     * <p>Reads the campaign region of the biome rather than the world's dimension key,
     * because every arena physically runs inside an island runtime dimension - the
     * world is never literally {@code minecraft:the_nether}.
     */
    public boolean isExplosiveBedRegion() {
        return isExplosiveSleepItem(false);
    }

    /**
     * True when the arena being fought sits in the Nether campaign region, where poured
     * water flashes to steam instead of forming a pool - the same vanilla rule the bed
     * already follows here.
     *
     * <p>Reads the campaign region rather than the world's dimension key for the same
     * reason {@link #isExplosiveBedRegion()} does: every arena physically runs inside an
     * island runtime dimension, so the world is never literally {@code minecraft:the_nether}.
     * The End is deliberately excluded - water behaves normally there in vanilla.
     */
    public boolean isNetherRegion() {
        return "nether".equals(currentRegionId());
    }

    /**
     * Whether a sleep-item detonates here instead of doing its job. Both items follow
     * the same vanilla rule - each works only in its own home region and explodes
     * everywhere else - so the two differ by one string:
     * <ul>
     *   <li>Bed: home is the Overworld, explodes in the Nether and the End.</li>
     *   <li>Respawn Anchor: home is the Nether, explodes in the Overworld and the End.</li>
     * </ul>
     * An unknown or missing region counts as Overworld, matching the fallback the
     * event roller already uses, so a modded campaign region can't make beds explode.
     */
    public boolean isExplosiveSleepItem(boolean isRespawnAnchor) {
        String home = isRespawnAnchor ? "nether" : "overworld";
        return !home.equals(currentRegionId());
    }

    /** Campaign region id of the biome being fought, defaulting to {@code overworld}. */
    private String currentRegionId() {
        if (!(levelDef instanceof com.crackedgames.craftics.level.GeneratedLevelDefinition gld)) {
            return "overworld";
        }
        BiomeTemplate biome = gld.getBiomeTemplate();
        if (biome == null) return "overworld";
        var region = com.crackedgames.craftics.level.campaign.CampaignManager.regionOf(biome.biomeId);
        return region == null ? "overworld" : region.id();
    }

    /**
     * Place a bed as the party's respawn anchor. The most recent bed wins, so a player
     * can move the anchor by spending another bed.
     */
    private void placeBedAnchor(GridPos tile, net.minecraft.block.Block bedBlock) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        paintBed(world, tile, bedBlock);
        bedRespawnAnchor = tile;
        world.playSound(null, arena.gridToBlockPos(tile),
            net.minecraft.sound.SoundEvents.BLOCK_WOOL_PLACE,
            net.minecraft.sound.SoundCategory.BLOCKS, 1.0f, 0.9f);
        boolean anchor = bedBlock == net.minecraft.block.Blocks.RESPAWN_ANCHOR;
        sendMessage((anchor ? "§b§lRespawn anchor set! " : "§b§lBed placed! ")
            + "§r§7If a totem revives you, you'll come back beside it instead of where you fell.");
    }

    /**
     * Render the bed. Both halves are placed so it reads as a bed rather than a stray
     * half-block, with {@code NOTIFY_LISTENERS} rather than a full update so BedBlock's
     * own neighbour logic never decides the pair is broken and pops it. Falls back to a
     * lone foot when there is no room for the head.
     */
    private void paintBed(ServerWorld world, GridPos tile, net.minecraft.block.Block bedBlock) {
        BlockPos bp = arena.gridToBlockPos(tile);
        net.minecraft.block.BlockState foot = bedBlock.getDefaultState();
        // A respawn anchor is a single ordinary block - only real beds are two-part.
        if (!(bedBlock instanceof net.minecraft.block.BedBlock)) {
            world.setBlockState(bp, foot, net.minecraft.block.Block.NOTIFY_LISTENERS);
            return;
        }
        for (net.minecraft.util.math.Direction dir : net.minecraft.util.math.Direction.Type.HORIZONTAL) {
            BlockPos headPos = bp.offset(dir);
            if (!world.getBlockState(headPos).isAir()) continue;
            try {
                net.minecraft.block.BlockState f = foot
                    .with(net.minecraft.block.HorizontalFacingBlock.FACING, dir)
                    .with(net.minecraft.block.BedBlock.PART,
                        net.minecraft.block.enums.BedPart.FOOT);
                net.minecraft.block.BlockState h = f.with(net.minecraft.block.BedBlock.PART,
                    net.minecraft.block.enums.BedPart.HEAD);
                world.setBlockState(bp, f, net.minecraft.block.Block.NOTIFY_LISTENERS);
                world.setBlockState(headPos, h, net.minecraft.block.Block.NOTIFY_LISTENERS);
                return;
            } catch (Exception ignored) {
                break; // fall through to the single-block placement
            }
        }
        world.setBlockState(bp, foot, net.minecraft.block.Block.NOTIFY_LISTENERS);
    }

    /**
     * Move a just-resurrected player to a tile touching their bed. Called from both
     * totem paths, AFTER the revive has already happened - this never grants a life,
     * it only changes where a life that was already paid for is spent.
     *
     * <p>Silently does nothing when there is no bed or nothing free around it, because
     * a failure here must never interrupt a resurrection.
     */
    private void relocateToBedAnchor() {
        if (bedRespawnAnchor == null || arena == null) return;
        GridPos cur = arena.getPlayerGridPos();
        if (cur == null) return;

        java.util.List<GridPos> candidates = new java.util.ArrayList<>();
        for (int dx = -1; dx <= 1; dx++) {
            for (int dz = -1; dz <= 1; dz++) {
                if (dx == 0 && dz == 0) continue; // the bed's own tile
                GridPos p = new GridPos(bedRespawnAnchor.x() + dx, bedRespawnAnchor.z() + dz);
                if (!arena.isInBounds(p)) continue;
                if (arena.isOccupied(p) && !p.equals(cur)) continue;
                GridTile t = arena.getTile(p);
                if (t == null || !t.isSafeForSpawn()) continue;
                candidates.add(p);
            }
        }
        if (candidates.isEmpty()) {
            sendMessage("§7Your bed is hemmed in - you revive where you fell.");
            return;
        }

        java.util.List<GridPos> enemyPositions = new java.util.ArrayList<>();
        for (CombatEntity e : enemies) {
            if (e.isAlive() && !e.isAlly()) enemyPositions.add(e.getGridPos());
        }
        // Reuse the totem's own safest-tile pick so "beside the bed" still means the
        // side away from whatever killed you.
        GridPos dest = MoreTotemsEffects.safestTile(candidates, enemyPositions);
        if (dest == null) dest = candidates.get(0);
        if (dest.equals(cur)) return;

        arena.setPlayerGridPos(dest);
        BlockPos bp = arena.gridToBlockPos(dest);
        player.requestTeleport(bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5);
        sendMessage("§b§lYou wake beside your bed. §r§7Pulled clear of where you fell.");
    }

    // Bed blast, Nether/End only. Reaches one tile further than TNT and hits far harder,
    // with the percent-of-max-HP terms doing the real work against the region's 150+ HP
    // enemies. Index = manhattan distance from the bed.
    private static final int[] BED_BLAST_FLAT = {12, 8, 5, 3};
    private static final double[] BED_BLAST_PCT = {0.40, 0.28, 0.18, 0.10};
    /** What the blast does to the player, who is always inside it by design. */
    private static final int[] BED_SELF_DAMAGE = {14, 10, 6, 3};

    /**
     * Detonate a bed instantly. Unlike TNT there is no fuse, so nothing gets to walk out
     * of the blast - but the bed has to be placed adjacent to the player (enforced in
     * {@code ItemUseHandler.useBed}), so the player is always standing in it too. That
     * trade is the whole item: guaranteed damage, paid for in your own HP.
     */
    private void detonateBed(GridPos center, net.minecraft.block.Block bedBlock) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos bp = arena.gridToBlockPos(center);

        world.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION_EMITTER,
            bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5, 3, 1.0, 0.5, 1.0, 0.0);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.FLAME,
            bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5, 40, 2.0, 1.2, 2.0, 0.08);
        world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
            bp.getX() + 0.5, bp.getY() + 1.5, bp.getZ() + 0.5, 25, 1.8, 1.2, 1.8, 0.04);
        world.playSound(null, bp,
            net.minecraft.sound.SoundEvents.ENTITY_GENERIC_EXPLODE.value(),
            net.minecraft.sound.SoundCategory.BLOCKS, 2.0f, 0.6f);

        sendMessage("§c§l✸ THE BED EXPLODES! ✸");

        int enemiesHit = 0;
        int totalDamage = 0;
        for (CombatEntity enemy : new ArrayList<>(enemies)) {
            if (!enemy.isAlive() || enemy.isAlly()) continue;
            int dist = Math.abs(enemy.getGridPos().x() - center.x())
                     + Math.abs(enemy.getGridPos().z() - center.z());
            if (dist >= BED_BLAST_FLAT.length) continue;
            int dmg = BED_BLAST_FLAT[dist] + enemy.percentMaxHpDamage(BED_BLAST_PCT[dist]);
            totalDamage += applySpecialUtilityDamage(enemy, dmg);
            enemiesHit++;
            if (!enemy.isAlive()) checkAndHandleDeath(enemy);
        }

        // The player is in their own blast. Routed through damagePlayer so armour and
        // Resistance apply, and so a self-kill resolves like any other death (including
        // letting a totem catch it).
        GridPos self = arena.getPlayerGridPos();
        if (self != null) {
            int selfDist = Math.abs(self.x() - center.x()) + Math.abs(self.z() - center.z());
            if (selfDist < BED_SELF_DAMAGE.length) {
                int selfDealt = damagePlayer(BED_SELF_DAMAGE[selfDist]);
                sendMessage("§cThe blast catches you for " + selfDealt
                    + "! §7(HP: " + getPlayerHp() + ")");
            }
        }

        if (enemiesHit > 0) {
            sendMessage("§6Caught §c" + enemiesHit + "§6 enemies for §c" + totalDamage + "§6 total.");
        } else {
            sendMessage("§7Nothing was close enough to catch the blast.");
        }
        sendSync();
        refreshHighlights();
    }

    /**
     * Detonate all pending TNT blocks. Called at the start of each new round.
     * Deals AoE damage (8/5/3 by manhattan distance), damages the player too if close,
     * removes the TNT block, and spawns a big explosion effect.
     */
    private void detonatePendingTnts() {
        if (pendingTnts.isEmpty()) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();

        // Decrement fuses; only blow up the ones that hit 0 this tick. TNT
        // placed with fuseRounds=2 (boss demolition cache) just had its block
        // appear last round transition; the player needs this round to see
        // the physical TNT and step away before it detonates.
        List<PendingTnt> exploding = new ArrayList<>();
        for (var it = pendingTnts.iterator(); it.hasNext(); ) {
            PendingTnt t = it.next();
            t.fuseRounds--;
            if (t.fuseRounds <= 0) {
                exploding.add(t);
                it.remove();
            }
        }
        if (exploding.isEmpty()) return;

        for (PendingTnt tnt : exploding) {
            GridPos center = tnt.tile();
            BlockPos bp = tnt.blockPos();
            BlockPos floorBp = bp.down();

            // Remove the TNT block -replace with the arena floor
            GridTile floorTile = arena.getTile(center);
            world.setBlockState(bp, Blocks.AIR.getDefaultState());
            if (floorTile != null) {
                world.setBlockState(floorBp, floorTile.getBlockType().getDefaultState());
            }

            // --- Explosion particles ---
            world.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION_EMITTER,
                bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5,
                1, 0.0, 0.0, 0.0, 0.0);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION,
                bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5,
                5, 1.0, 0.8, 1.0, 0.0);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.FLAME,
                bp.getX() + 0.5, bp.getY() + 1.0, bp.getZ() + 0.5,
                25, 1.5, 1.0, 1.5, 0.05);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.LAVA,
                bp.getX() + 0.5, bp.getY() + 0.5, bp.getZ() + 0.5,
                12, 1.0, 0.5, 1.0, 0.0);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                bp.getX() + 0.5, bp.getY() + 1.5, bp.getZ() + 0.5,
                15, 1.2, 1.0, 1.2, 0.03);
            world.spawnParticles(net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE,
                bp.getX() + 0.5, bp.getY() + 2.0, bp.getZ() + 0.5,
                8, 0.8, 0.5, 0.8, 0.01);

            // Explosion sound
            world.playSound(null, bp,
                net.minecraft.sound.SoundEvents.ENTITY_GENERIC_EXPLODE.value(),
                net.minecraft.sound.SoundCategory.BLOCKS, 1.5f, 0.9f);

            sendMessage("§c§lBOOM! §r§7TNT detonates!");

            // --- AoE damage to enemies ---
            int totalDamage = 0;
            int enemiesHit = 0;
            int killCount = 0;
            for (CombatEntity enemy : new ArrayList<>(enemies)) {
                if (!enemy.isAlive()) continue;
                int dist = Math.abs(enemy.getGridPos().x() - center.x())
                         + Math.abs(enemy.getGridPos().z() - center.z());
                if (dist <= 2) {
                    // Flat blast damage plus a percent of max HP by ring (center/adjacent/outer)
                    // so TNT stays lethal against late-game HP pools. Bosses take 1/3 (8/5/3%).
                    double hpPct = dist == 0 ? 0.24 : (dist == 1 ? 0.15 : 0.09);
                    int dmg = (dist == 0 ? 8 : (dist == 1 ? 5 : 3)) + enemy.percentMaxHpDamage(hpPct);
                    int dealt = applySpecialUtilityDamage(enemy, dmg);
                    totalDamage += dealt;
                    enemiesHit++;
                    if (!enemy.isAlive()) {
                        killCount++;
                        checkAndHandleDeath(enemy);
                    }
                }
            }

            // Track TNT kills for achievement
            if (killCount > 0) {
                achievementTracker.recordTntKills(killCount);
            }

            // Self-damage if player is close. Route through damagePlayer so
            // the Craftics combat HP actually drops (and party-aware death
            // detection fires) -the old player.setHealth(max(1, ...)) only
            // touched vanilla health, clamped at 1, and left combat HP
            // untouched. Result: a "fatal" blast that never killed the
            // player's combat state, but later damage processed the queued
            // death only after a turn skip -the softlock the user hit.
            // Self-damage every party member in the 2-tile blast radius, not just
            // the host. With per-victim distance tiers (6/4/2) and the this.player
            // swap so each member's own dodge/armor/effects/death handling applies.
            java.util.List<ServerPlayerEntity> tntVictims = new java.util.ArrayList<>();
            if (partyPlayers.size() > 1) {
                for (ServerPlayerEntity member : partyPlayers) {
                    if (member == null || member.isRemoved() || member.isDisconnected()) continue;
                    if (deadPartyMembers.contains(member.getUuid())) continue;
                    if (center.manhattanDistance(gridPosOf(member)) <= 2) tntVictims.add(member);
                }
            } else {
                GridPos playerPos = arena.getPlayerGridPos();
                if (center.manhattanDistance(playerPos) <= 2) tntVictims.add(player);
            }
            boolean tntHitAnyone = false;
            boolean gameOverFromTnt = false;
            for (ServerPlayerEntity victim : tntVictims) {
                tntHitAnyone = true;
                ServerPlayerEntity savedTntPlayer = this.player;
                boolean tntSwapped = victim != savedTntPlayer;
                if (tntSwapped) { this.player = victim; retargetEffectsToCurrentPlayer(); }
                boolean victimDied = false;
                try {
                    int victimDist = center.manhattanDistance(gridPosOf(victim));
                    int selfDmgRaw = victimDist == 0 ? 6 : (victimDist == 1 ? 4 : 2);
                    int selfDmg = damagePlayer(selfDmgRaw);
                    sendMessage("§c  Blast hit " + enemiesHit + " enemies for " + totalDamage + " total! "
                        + (tntSwapped ? victim.getName().getString() : "You") + " took " + selfDmg + " blast damage!");
                    if (getPlayerHp() <= 0) {
                        victimDied = true;
                        handlePlayerDeathOrGameOver();
                        gameOverFromTnt = (partyPlayers.size() <= 1 || !active);
                    }
                } finally {
                    if (!victimDied) { this.player = savedTntPlayer; retargetEffectsToCurrentPlayer(); }
                }
                if (gameOverFromTnt) { sendSync(); return; }
            }
            if (!tntHitAnyone && enemiesHit > 0) {
                sendMessage("§7  Hit " + enemiesHit + " enemies for " + totalDamage + " total damage!");
            }
        }
        // A deferred TNT landing the final blow would soft-lock the level:
        // checkAndHandleDeath despawns the enemy but never ends the fight. Re-run
        // the win check every other damage path uses, once all TNT this tick has
        // resolved and only if the blast didn't already trigger a player game-over.
        if (phase != CombatPhase.GAME_OVER && phase != CombatPhase.LEVEL_COMPLETE
                && !anyEnemyBlockingVictory()) {
            handleVictory();
            return;
        }
        sendSync();
    }

    // ===== Boss Callback Hooks =====

    /**
     * Called when the player deals damage to a boss enemy.
     * Dispatches to boss-specific reaction callbacks.
     */
    private void notifyBossOfDamage(CombatEntity target, int damageDealt) {
        if (!target.isBoss()) return;
        EnemyAI ai = resolveAi(target);

        // ShulkerArchitect: notify it was damaged (primes Fortify Shell)
        if (ai instanceof ShulkerArchitectAI sa) {
            sa.notifyDamaged();
        }

        // Rockbreaker P2: notify it was damaged (primes the retaliatory slam)
        if (ai instanceof com.crackedgames.craftics.combat.ai.boss.RockbreakerAI rb) {
            rb.notifyDamaged();
        }

        // MoltenKing: at 50% HP, the original boss dies and cleanly splits into 2
        // smaller copies (size 2) that each act as independent bosses. Gen 1 does
        // NOT split further -this fires only for Gen 0.
        if (ai instanceof MoltenKingAI mk && mk.canSplit()
                && !target.hasSplit() && target.isAlive()
                && target.getCurrentHp() <= target.getMaxHp() / 2) {
            target.markSplit();
            String nextGenKey = mk.getNextGenAiKey();
            if (nextGenKey != null) {
                int splitSize = 2; // gen 1 = 2x2 footprint
                int splitHp = Math.max(5, target.getMaxHp() / 2);
                int splitAtk = Math.max(1, target.getAttackPower() - 1);
                int splitDef = Math.max(0, target.getDefense() - 1);

                // The parent occupies a 4x4 area starting at its gridPos. We pick up
                // to 2 non-overlapping 2x2 sub-quadrants of that area to place the
                // split copies -this guarantees they fit inside the footprint the
                // parent just vacated.
                GridPos origin = target.getGridPos();
                int parentSize = target.getMaxSize(); // Molten King is square (4x4 gen 0)
                List<GridPos> quadrantOrigins = new ArrayList<>();
                for (int dx = 0; dx + splitSize <= parentSize; dx += splitSize) {
                    for (int dz = 0; dz + splitSize <= parentSize; dz += splitSize) {
                        quadrantOrigins.add(new GridPos(origin.x() + dx, origin.z() + dz));
                    }
                }
                java.util.Collections.shuffle(quadrantOrigins);

                // Kill the parent FIRST so the sub-quadrants become unoccupied before
                // the split copies are placed. This also prevents the parent's mob
                // entity from lingering as a "ghost" alongside the new copies.
                target.takeDamage(target.getCurrentHp() + 100);
                checkAndHandleDeath(target);

                // Filter to quadrants whose every tile is now walkable and free.
                List<GridPos> splitPositions = new ArrayList<>();
                for (GridPos q : quadrantOrigins) {
                    if (splitPositions.size() >= 2) break;
                    boolean ok = true;
                    for (int dx = 0; dx < splitSize && ok; dx++) {
                        for (int dz = 0; dz < splitSize && ok; dz++) {
                            GridPos tile = new GridPos(q.x() + dx, q.z() + dz);
                            if (!arena.isInBounds(tile) || arena.isOccupied(tile)) { ok = false; break; }
                            GridTile gt = arena.getTile(tile);
                            if (gt == null || !gt.isWalkable()) { ok = false; break; }
                        }
                    }
                    if (ok) splitPositions.add(q);
                }

                if (!splitPositions.isEmpty()) {
                    pendingMoltenSplitKey = nextGenKey;
                    pendingMoltenSplitSize = splitSize;
                    EnemyAction split = new EnemyAction.SummonMinions(
                        "minecraft:magma_cube", splitPositions.size(), splitPositions,
                        splitHp, splitAtk, splitDef);
                    dispatchBossSubAction(split);
                }
            }
        }
    }

    /**
     * Called when the player finishes moving.
     * Notifies Warden boss of player movement for vibration sense.
     */
    private void notifyBossesPlayerMoved(GridPos destination, int tilesMoved) {
        for (CombatEntity e : enemies) {
            if (!e.isAlive() || !e.isBoss()) continue;
            EnemyAI ai = resolveAi(e);
            if (ai instanceof WardenAI warden) {
                warden.onPlayerMove(destination, tilesMoved);
            }
        }
    }

    /**
     * Called at the end of the player's turn.
     * Ticks pending boss warnings (telegraphed attacks).
     */
    private void tickBossWarnings() {
        for (CombatEntity e : enemies) {
            if (!e.isAlive() || !e.isBoss()) continue;
            EnemyAI ai = resolveAi(e);
            if (ai instanceof BossAI boss) {
                boss.tickWarning();
            }
        }
        // Also tick Void Walker rift lifetimes.
        tickVoidRifts();
        // Tick Sandstorm Pharaoh sand-mine lifetimes (arm fresh mines, expire old ones).
        tickSandMines();
        // Tick down the Curse of the Sands.
        if (curseOfSandsTurns > 0) {
            curseOfSandsTurns--;
            if (curseOfSandsTurns == 0) {
                sendMessage("§7The curse of the sands lifts.");
            }
        }
    }

    /**
     * Take {@code enemy} off the grid and out of reach: no attack, AoE, splash, or chain can
     * touch it until {@link #surfaceEnemy} puts it back.
     *
     * <p>Every exit from this state MUST go through surfaceEnemy. The untargetable flag and the
     * missing occupancy tiles are the same fact stored twice, and a boss that keeps the flag is
     * unkillable, so the two calls are a matched pair.
     */
    private void burrowEnemy(CombatEntity enemy) {
        arena.removeEntity(enemy);
        enemy.setUntargetable(true);

        MobEntity mob = enemy.getMobEntity();
        if (mob != null) mob.setInvisible(true);

        if (player != null && player.getEntityWorld() instanceof ServerWorld sw) {
            BlockPos bp = arena.gridToBlockPos(enemy.getGridPos());
            sw.spawnParticles(net.minecraft.particle.ParticleTypes.CAMPFIRE_COSY_SMOKE,
                bp.getX() + 1.0, bp.getY() + 0.2, bp.getZ() + 1.0, 30, 0.8, 0.1, 0.8, 0.02);
            sw.playSound(null, bp, net.minecraft.sound.SoundEvents.BLOCK_ROOTED_DIRT_BREAK,
                net.minecraft.sound.SoundCategory.HOSTILE, 1.4f, 0.5f);
        }
        sendSync();
    }

    /**
     * Put a burrowed {@code enemy} back on the grid at {@code anchor} and make it targetable
     * again. This ALWAYS surfaces: a null or refused anchor falls back to the tile it went under
     * at, and even a refused re-placement still clears the flag. Leaving the boss untargetable
     * because no tile was free would make the fight unwinnable, which is strictly worse than a
     * boss standing on an awkward tile.
     */
    private void surfaceEnemy(CombatEntity enemy, GridPos anchor, String message) {
        GridPos target = anchor != null ? anchor : enemy.getGridPos();
        if (!com.crackedgames.craftics.combat.ai.AIUtils
                .canPlaceFootprintIgnoringSelf(arena, target, enemy)) {
            target = enemy.getGridPos();
        }
        enemy.setGridPos(target);
        // Placement can still be refused (its old tiles may be taken while it was under). The
        // boss surfaces regardless: an entity with no occupancy tile is far less broken than one
        // that is permanently untargetable, and the flag below is what actually gates damage.
        arena.placeEntity(enemy);
        enemy.setUntargetable(false);

        EnemyAI surfaceAi = resolveAi(enemy);
        if (surfaceAi instanceof RevenantAI revenant) revenant.clearBurrowState();

        MobEntity mob = enemy.getMobEntity();
        if (mob != null) {
            mob.setInvisible(false);
            BlockPos bp = arena.gridToBlockPos(target);
            mob.requestTeleport(bp.getX() + 0.5, arena.getEntityY(target), bp.getZ() + 0.5);
        }

        if (message != null) sendMessage(message);
        if (player != null && player.getEntityWorld() instanceof ServerWorld sw) {
            BlockPos bp = arena.gridToBlockPos(target);
            sw.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION,
                bp.getX() + 1.0, bp.getY() + 0.5, bp.getZ() + 1.0, 6, 0.6, 0.2, 0.6, 0.0);
            sw.playSound(null, bp, net.minecraft.sound.SoundEvents.ENTITY_ZOMBIE_INFECT,
                net.minecraft.sound.SoundCategory.HOSTILE, 1.5f, 0.6f);
        }
        sendSync();
    }

    /**
     * Called when a minion/entity in a boss fight dies.
     * Dispatches boss-specific callbacks for minion death.
     */
    private void notifyBossOfMinionDeath(CombatEntity deadEntity) {
        for (CombatEntity e : enemies) {
            if (!e.isAlive() || !e.isBoss()) continue;
            EnemyAI ai = resolveAi(e);

            // ShulkerArchitect: turret destroyed
            if (ai instanceof ShulkerArchitectAI sa) {
                if (deadEntity.getGridPos() != null) {
                    sa.removeTurret(deadEntity.getGridPos());
                }
            }

            // Broodmother: notify the AI that an egg sac was lost so its
            // spawn-cap bookkeeping stays accurate. The actual block + particle
            // cleanup happens unconditionally in checkAndHandleDeath so it
            // still runs if the broodmother died first.
            if (ai instanceof BroodmotherAI bm
                    && "craftics:egg_sac".equals(deadEntity.getEntityTypeId())) {
                bm.onEggSacDestroyed(deadEntity.getGridPos());
                sendMessage("§a✦ Egg sac destroyed! Spawn capacity reduced.");
            }

            // Bastion Brute: the three banners are asymmetric, so the AI reports which one fell
            // and the message names it. Filtered on the type id because this loop sees every
            // death at a tracked tile, not just banners.
            if (ai instanceof BastionBruteAI brute
                    && "craftics:war_banner".equals(deadEntity.getEntityTypeId())) {
                String bannerMessage = brute.onWarBannerDestroyed(deadEntity.getGridPos(), e);
                if (bannerMessage != null) sendMessage(bannerMessage);
            }

            // Revenant: a lost grave narrows the zombie cap permanently. Filtered on the type id
            // because this loop sees every death at a tracked tile, not just graves. The block
            // cleanup itself runs in checkAndHandleDeath so it still happens if the boss died first.
            if (ai instanceof RevenantAI revenant
                    && "craftics:grave".equals(deadEntity.getEntityTypeId())) {
                revenant.onGraveDestroyed(deadEntity.getGridPos());
                sendMessage("§a✦ Grave destroyed! The dead stay down.");

                // Last grave broken while it was under: the escape network is gone, so the
                // retreat fails and it claws out where it dug in. Spending the untouchable turn
                // on the network instead of waiting is the strongest play, and this is the payoff.
                if (revenant.getGraveCount() == 0 && revenant.isBurrowed()) {
                    GridPos forced = revenant.forceSurfaceOnLastGraveLost(e, arena);
                    surfaceEnemy(e, forced, "§6§l✦ The last grave collapses! §e"
                        + e.getDisplayName() + " is dragged back into the light!");
                }
            }
        }
    }

    /**
     * Called after a boss entity is spawned and placed on the arena.
     * Initializes boss-specific fight setup.
     */
    /**
     * The on-screen "it just got worse" beat when a boss crosses into phase two:
     * combat-log line, a subtitle for every party member, a roar, a particle
     * burst on the boss, and a client-side shake/flash via EVENT_BOSS_MOMENT.
     * Server-driven so all co-op clients see the same moment.
     */
    private void announceBossPhaseTwo(CombatEntity boss) {
        sendMessage("§4§l" + boss.getDisplayName() + " enters Phase 2!");

        for (ServerPlayerEntity member : getAllParticipants()) {
            if (member == null || member.isRemoved() || member.isDisconnected()
                    || member.networkHandler == null) continue;
            member.networkHandler.sendPacket(
                new net.minecraft.network.packet.s2c.play.TitleFadeS2CPacket(5, 35, 15));
            member.networkHandler.sendPacket(
                new net.minecraft.network.packet.s2c.play.SubtitleS2CPacket(
                    Text.literal("§4§l" + boss.getDisplayName() + " Phase 2")));
            // Empty title so the subtitle shows even when no title is queued.
            member.networkHandler.sendPacket(
                new net.minecraft.network.packet.s2c.play.TitleS2CPacket(Text.literal("")));
        }

        MobEntity bossMob = boss.getMobEntity();
        if (player != null && player.getEntityWorld() instanceof ServerWorld sw) {
            double bx, by, bz;
            if (bossMob != null) {
                bx = bossMob.getX(); by = bossMob.getY() + 1.0; bz = bossMob.getZ();
            } else {
                BlockPos bp = arena.gridToBlockPos(boss.getGridPos());
                bx = bp.getX() + 0.5; by = bp.getY() + 1.0; bz = bp.getZ() + 0.5;
            }
            sw.spawnParticles(net.minecraft.particle.ParticleTypes.ANGRY_VILLAGER,
                bx, by + 0.5, bz, 12, 0.6, 0.8, 0.6, 0.0);
            sw.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                bx, by, bz, 20, 0.5, 0.7, 0.5, 0.04);
            sw.spawnParticles(net.minecraft.particle.ParticleTypes.FLASH,
                bx, by, bz, 1, 0, 0, 0, 0);
        }
        // ROAR pose: head back, arms wide, plus the ring burst + roar sound
        // that MobAnimations owns for this state.
        if (bossMob != null) {
            com.crackedgames.craftics.combat.animation.MobAnimations.set(bossMob,
                com.crackedgames.craftics.combat.animation.AnimState.ROAR);
        }
        // The arena itself flinches: dragon growl, a shockwave rolling out from
        // the boss that bounces its own minions, blood flash, ENRAGED overhead.
        if (player != null && player.getEntityWorld() instanceof ServerWorld phaseWorld) {
            com.crackedgames.craftics.vfx.boss.BossAttackVfx.phaseTransition(phaseWorld, arena, boss);
        }

        sendToAllParty(new CombatEventPayload(
            CombatEventPayload.EVENT_BOSS_MOMENT, boss.getEntityId(),
            CombatEventPayload.BOSS_MOMENT_PHASE_TWO, 0,
            boss.getGridPos().x(), boss.getGridPos().z()
        ));
    }

    private void initBossSetup(CombatEntity bossEntity) {
        EnemyAI ai = resolveAi(bossEntity);

        if (ai instanceof BroodmotherAI broodmother) {
            List<GridPos> sacPositions = broodmother.initEggSacs(arena);
            ServerWorld world = (ServerWorld) player.getEntityWorld();
            for (GridPos pos : sacPositions) {
                placeEggSacEntity(broodmother, pos, world);
            }
        }

        // Bastion Brute: war banners feed its speed, which feeds Momentum. Only banners the
        // grid actually accepted are registered, or the AI would grant speed for a banner the
        // player has no tile to attack.
        if (ai instanceof BastionBruteAI brute) {
            ServerWorld world = (ServerWorld) player.getEntityWorld();
            for (BastionBruteAI.BannerPlacement bp : brute.initWarBanners(arena)) {
                CombatEntity banner = placeBlockObject("craftics:war_banner", bp.pos(),
                    WAR_BANNER_HP, -(warBannerIdCounter++), warBannerBlock(bp.typeName()), world);
                if (banner != null) brute.registerWarBanner(bp);
            }
        }

        // Revenant: graves are the source of every zombie it raises. Only graves the grid actually
        // accepted are registered, or the AI would raise off a tile the player cannot attack.
        if (ai instanceof RevenantAI revenant) {
            ServerWorld world = (ServerWorld) player.getEntityWorld();
            for (GridPos pos : revenant.initGraves(arena)) {
                CombatEntity grave = placeBlockObject("craftics:grave", pos,
                    GRAVE_HP, -(graveIdCounter++), Blocks.COBBLESTONE_WALL, world);
                if (grave != null) revenant.registerGrave(pos);
            }
        }

        // Ender Dragon: backgroundBoss parked above the arena (same pattern as ghast).
        // The mob entity sits 100 blocks above the arena centre; the PhaseManager is
        // forced to HOVER so it never fights our per-tick position enforcement.
        // The dragon occupies a 3×7 cluster of centre tiles for targeting.
        if (ai instanceof com.crackedgames.craftics.combat.ai.DragonAI) {
            int arenaW = arena.getWidth();
            int arenaH = arena.getHeight();

            arena.removeEntity(bossEntity);
            bossEntity.setBackgroundBoss(true);

            // Set grid position to centre but do NOT place occupancy tiles yet.
            // The dragon starts in ATTACKING state (off-stage, not targetable).
            // tickDragonPositionEnforcer adds occupancy tiles when it transitions
            // to PERCHING state.
            int bw = 3, bh = 7;
            int ox = (arenaW - bw) / 2;
            int oz = (arenaH - bh) / 2;
            bossEntity.setGridPos(new GridPos(ox, oz));
            bossEntity.setSize(1);

            // Clear any enemies from the perch zone so they don't block it later
            for (int dx = 0; dx < bw; dx++) {
                for (int dz = 0; dz < bh; dz++) {
                    GridPos slot = new GridPos(ox + dx, oz + dz);
                    CombatEntity existing = arena.getOccupant(slot);
                    if (existing != null && existing != bossEntity) {
                        GridPos relocated = findNearestValidSpawn(arena,
                            new GridPos(ox + dx, oz + dz + bh), existing.getSizeX(), existing.getSizeZ(), false);
                        if (relocated != null) {
                            arena.moveEntity(existing, relocated);
                            MobEntity eMob = existing.getMobEntity();
                            if (eMob != null) {
                                BlockPos bp = arena.gridToBlockPos(relocated);
                                eMob.refreshPositionAndAngles(
                                    bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5, eMob.getYaw(), eMob.getPitch());
                            }
                        }
                    }
                }
            }

            // Park mob entity 100 blocks above centre -within entity tracking range
            // The per-tick enforcer (tickDragonPositionEnforcer) keeps it there
            // while in ATTACKING state.
            MobEntity dragonMob = bossEntity.getMobEntity();
            if (dragonMob != null) {
                dragonMob.setAiDisabled(true);
                dragonMob.setNoGravity(true);
                dragonMob.noClip = true;
                dragonMob.setInvisible(true);
                // Neutralise the vanilla PhaseManager -HOVER is passive and won't
                // fight our per-tick position enforcement.
                if (dragonMob instanceof net.minecraft.entity.boss.dragon.EnderDragonEntity spawnDragon) {
                    spawnDragon.getPhaseManager().setPhase(
                        net.minecraft.entity.boss.dragon.phase.PhaseType.HOVER);
                }
                double cx = arena.getOrigin().getX() + arenaW / 2.0;
                double cy = arena.getOrigin().getY() + 100;
                double cz = arena.getOrigin().getZ() + arenaH / 2.0;
                forceDragonPosition(dragonMob, cx, cy, cz);
            }
        }

        // Wailing Revenant (Ghast): position OUTSIDE the arena on the low-Z edge.
        // The mob sits beyond the front row, facing +Z (toward the arena).
        // The entire front row (z = 0) is registered as targetable.
        if (ai instanceof WailingRevenantAI) {
            int arenaW = arena.getWidth();
            int arenaH = arena.getHeight();

            // Remove from current grid position
            arena.removeEntity(bossEntity);

            // Mark as background boss -tiles it occupies don't block movement
            bossEntity.setBackgroundBoss(true);

            // Anchor at grid (0, 0) with size 1
            bossEntity.setGridPos(new GridPos(0, 0));
            bossEntity.setSize(1);

            // Register the boss on every tile in the front row (z=0) for targeting.
            // These tiles are still walkable thanks to the backgroundBoss flag.
            // If another enemy already occupies a tile, move it away first.
            for (int x = 0; x < arenaW; x++) {
                GridPos bossSlot = new GridPos(x, 0);
                CombatEntity existing = arena.getOccupant(bossSlot);
                if (existing != null && existing != bossEntity) {
                    // Relocate the existing enemy to the nearest open tile
                    GridPos relocated = findNearestValidSpawn(arena,
                        new GridPos(x, 1), existing.getSizeX(), existing.getSizeZ(), false);
                    if (relocated != null) {
                        arena.moveEntity(existing, relocated);
                        MobEntity eMob = existing.getMobEntity();
                        if (eMob != null) {
                            BlockPos bp = arena.gridToBlockPos(relocated);
                            eMob.refreshPositionAndAngles(
                                bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5, eMob.getYaw(), eMob.getPitch());
                        }
                    }
                }
                arena.getOccupants().put(bossSlot, bossEntity);
            }

            // Place the mob entity OUTSIDE the arena, beyond the front edge.
            MobEntity mob = bossEntity.getMobEntity();
            if (mob != null) {
                double bossX = arena.getOrigin().getX() + (arenaW - 1) / 2.0 + 0.5; // true center of grid
                double bossZ = arena.getOrigin().getZ() - 10.0; // 10 blocks beyond front edge
                double bossY = arena.getOrigin().getY() + 2.0;
                mob.refreshPositionAndAngles(bossX, bossY, bossZ, 0.0f, 0.0f); // yaw 0 = face +Z
                mob.setYaw(0.0f);
                mob.setHeadYaw(0.0f);
                mob.setBodyYaw(0.0f);
            }
        }
    }

    /**
     * Place a single egg sac entity at the given position.
     * Egg sacs are 1HP destructible entities that block all entities except the Broodmother.
     */
    private void placeEggSacEntity(BroodmotherAI broodmother, GridPos pos, ServerWorld world) {
        int fakeEntityId = -(eggSacIdCounter++);
        // attackPower=0 intended (egg sacs don't attack), but CombatEntity clamps to min 1
        CombatEntity eggSac = new CombatEntity(fakeEntityId, "craftics:egg_sac", pos,
            1, 0, 0, 1);
        eggSac.setPassableForBoss(true);
        eggSac.setAiOverrideKey("craftics:egg_sac");
        // Inert but deliberately NOT scenery: egg sacs are must-kill for room-clear, which is why
        // initEggSacs gates on reachability. This only silences the per-turn "waits..." spam.
        eggSac.setInertObject(true);

        enemies.add(eggSac);
        arena.placeEntity(eggSac);

        // Place turtle egg block in the world. gridToBlockPos returns the
        // entity standing block (origin.y + 1) -placing the egg there sits
        // it on top of the arena floor. Using bp.up(1) would float it at
        // head level with an air gap below.
        BlockPos bp = arena.gridToBlockPos(pos);
        world.setBlockState(bp, Blocks.TURTLE_EGG.getDefaultState(),
            net.minecraft.block.Block.NOTIFY_ALL);

        // Spawn placement particles
        world.spawnParticles(net.minecraft.particle.ParticleTypes.ITEM_SLIME,
            bp.getX() + 0.5, bp.getY() + 1.5, bp.getZ() + 0.5,
            8, 0.3, 0.2, 0.3, 0.01);
    }

    /**
     * The world block for each war banner. Distinct colours so the three levers are told apart at
     * a glance, which is the whole point of making them asymmetric: white for the March, red for
     * Fury, black for the Horde. Falls back to red rather than throwing, since an unrecognised
     * banner should still be visible and breakable.
     */
    private static net.minecraft.block.Block warBannerBlock(String typeName) {
        return switch (typeName) {
            case "march" -> Blocks.WHITE_BANNER;
            case "horde" -> Blocks.BLACK_BANNER;
            default -> Blocks.RED_BANNER;
        };
    }

    /**
     * Place a block-backed destructible object on the grid: a real HP combatant with no mob
     * entity, drawn as a world block. Returns null if the grid refused the tile.
     *
     * Immovable is mandatory: knockback would move the grid entry while the world block stayed
     * put, leaving an unhittable ghost. The Creaking heart sets this for the same reason; the
     * egg sac does not, and only gets away with it because nothing shoves it.
     */
    private CombatEntity placeBlockObject(String typeId, GridPos pos, int hp, int fakeEntityId,
                                          net.minecraft.block.Block block, ServerWorld world) {
        // The floor check is here as well as in the callers' tile pickers, because this method
        // is what actually calls setBlockState: a block object on a VOID tile is a solid block
        // sitting in a hole, which reads as ground the player can stand on and is not.
        if (!arena.isPlaceableFloor(pos)) {
            com.crackedgames.craftics.CrafticsMod.LOGGER.warn(
                "Refused to place block object {} at {} - tile has no floor", typeId, pos);
            return null;
        }
        // attackPower=0 intended (these never attack), but CombatEntity clamps to min 1
        CombatEntity obj = new CombatEntity(fakeEntityId, typeId, pos, hp, 0, 0, 1);
        obj.setPassableForBoss(true);
        obj.setAiOverrideKey(typeId);
        obj.setImmovable(true);
        // Graves, hives, war banners and props are optional counterplay: breaking them weakens the
        // fight, but the room must be able to clear with them still standing. The must-kill egg sac
        // is built elsewhere and correctly does not pass through here.
        obj.setScenery(true);
        obj.setInertObject(true);

        // A refused placement would otherwise leave a combatant in `enemies` with no grid
        // tile: unkillable, and the room never clears.
        if (!arena.placeEntity(obj)) {
            return null;
        }
        enemies.add(obj);

        // gridToBlockPos returns the entity standing block (origin.y + 1), so the
        // object sits on the arena floor rather than floating at head level.
        BlockPos bp = arena.gridToBlockPos(pos);
        world.setBlockState(bp, block.getDefaultState(),
            net.minecraft.block.Block.NOTIFY_ALL);
        return obj;
    }

    /**
     * Place cobweb blocks at Y+1 and register web overlays in the arena.
     * Webs apply slowness and last the given number of turns.
     */
    private void placeWebOverlays(List<GridPos> positions, int turns) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        for (GridPos pos : positions) {
            if (!arena.isInBounds(pos)) continue;
            arena.setWebOverlay(pos, turns);
            BlockPos bp = arena.gridToBlockPos(pos);
            world.setBlockState(bp.up(1), net.minecraft.block.Blocks.COBWEB.getDefaultState(),
                net.minecraft.block.Block.NOTIFY_ALL);
            // Placement particles
            world.spawnParticles(net.minecraft.particle.ParticleTypes.ITEM_SLIME,
                bp.getX() + 0.5, bp.getY() + 1.5, bp.getZ() + 0.5,
                5, 0.3, 0.2, 0.3, 0.01);
        }
    }

    /**
     * Remove a web overlay at the given position -clears the cobweb block and arena tracking.
     */
    private void removeWebOverlay(GridPos pos) {
        arena.clearWebOverlay(pos);
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        BlockPos bp = arena.gridToBlockPos(pos);
        world.setBlockState(bp.up(1), net.minecraft.block.Blocks.AIR.getDefaultState(),
            net.minecraft.block.Block.NOTIFY_ALL);
    }

    /**
     * Trigger or reset the ghast scream animation (open mouth texture).
     * Only affects ghast entities.
     */
    private void triggerGhastScream(CombatEntity entity, boolean screaming) {
        MobEntity mob = entity.getMobEntity();
        if (mob instanceof net.minecraft.entity.mob.GhastEntity ghast) {
            ghast.setShooting(screaming);
            if (screaming) {
                // Play ghast scream sound
                ServerWorld world = (ServerWorld) player.getEntityWorld();
                world.playSound(null, mob.getBlockPos(),
                    net.minecraft.sound.SoundEvents.ENTITY_GHAST_SCREAM,
                    net.minecraft.sound.SoundCategory.HOSTILE, 1.5f, 1.0f);
            }
        }
    }

    private static final String ARENA_TEAM_NAME = "craftics_nocollide";

    /**
     * Create a scoreboard team with collision disabled and add all arena mobs + players to it.
     * This prevents vanilla entity pushing during combat.
     */
    private void setupNoCollisionTeam() {
        if (player == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        net.minecraft.scoreboard.Scoreboard scoreboard = world.getScoreboard();

        // Create or get the team
        net.minecraft.scoreboard.Team team = scoreboard.getTeam(ARENA_TEAM_NAME);
        if (team == null) {
            team = scoreboard.addTeam(ARENA_TEAM_NAME);
        }
        team.setCollisionRule(net.minecraft.scoreboard.AbstractTeam.CollisionRule.NEVER);

        // Add all arena mobs
        for (CombatEntity e : enemies) {
            MobEntity mob = e.getMobEntity();
            if (mob != null) {
                scoreboard.addScoreHolderToTeam(mob.getUuidAsString(), team);
            }
        }
        // Add all players
        for (ServerPlayerEntity p : getAllParticipants()) {
            if (p != null) {
                scoreboard.addScoreHolderToTeam(p.getUuidAsString(), team);
            }
        }
    }

    /**
     * Remove the no-collision team on combat end.
     */
    private void cleanupNoCollisionTeam() {
        if (player == null) return;
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        net.minecraft.scoreboard.Scoreboard scoreboard = world.getScoreboard();
        net.minecraft.scoreboard.Team team = scoreboard.getTeam(ARENA_TEAM_NAME);
        if (team != null) {
            scoreboard.removeTeam(team);
        }
    }

    private void startEnemyMove(List<GridPos> path) {
        // Obstacle collision: stop the mob the tile BEFORE a non-walkable
        // tile that appeared after the AI planned its path (eg the player
        // dropped an obstacle on the dash line). FIRE is treated as
        // walkable since some boss charges intentionally leave fire trails.
        for (int i = 0; i < path.size(); i++) {
            var tile = arena.getTile(path.get(i));
            if (tile != null && !tile.isWalkable()
                    && !tile.getType().isFlames()) {
                path = new ArrayList<>(path.subList(0, i));
                sendMessage("§7" + currentEnemy.getDisplayName() + " slams into the obstacle!");
                break;
            }
        }
        // Cobweb trap: truncate path if enemy walks through a web
        for (int i = 0; i < path.size(); i++) {
            if (arena.hasWebOverlay(path.get(i))) {
                path = new ArrayList<>(path.subList(0, i + 1));
                // Break the cobweb
                GridPos webPos = path.get(path.size() - 1);
                arena.clearWebOverlay(webPos);
                BlockPos webBlockPos = new BlockPos(
                    arena.getOrigin().getX() + webPos.x(),
                    arena.getOrigin().getY() + 1,
                    arena.getOrigin().getZ() + webPos.z());
                if (player.getWorld() instanceof ServerWorld sw) {
                    sw.setBlockState(webBlockPos, Blocks.AIR.getDefaultState(),
                        net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);
                }
                sendMessage("§7" + currentEnemy.getDisplayName() + " is caught in cobwebs!");
                break;
            }
        }
        // Footprint-vs-player safety net: never let a sized mob WALK THROUGH the player.
        // A 2x2 mob's anchor can be a tile away from the player yet still overlap them, and
        // size-blind AI planning could route there, so the path is cut at the first overlap.
        //
        // Deliberately still multi-tile only. A 1x1 mob passing over the player's tile is a
        // swoop - the whole point of a diving attack - and cutting the path there would stop
        // phantoms and dragons dead in front of their target instead of through it.
        if (currentEnemy != null && currentEnemy.isMultiTile()) {
            int szX = currentEnemy.getSizeX();
            int szZ = currentEnemy.getSizeZ();
            GridPos pPos = arena.getPlayerGridPos();
            for (int i = 0; i < path.size(); i++) {
                if (CombatEntity.minDistanceFromSizedEntity(path.get(i), szX, szZ, pPos) == 0) {
                    path = new ArrayList<>(path.subList(0, i));
                    break;
                }
            }
        }

        // Where it STOPS is a separate question from what it passed over, and it is the one
        // that has to hold for every mob and every action. The grid cannot represent two
        // combatants on one square, so a move may not END on an occupied tile.
        //
        // This lives here rather than in any single action's handler because a move can be
        // ordered from several of them - a plain Move, a MoveAndAttack, a Swoop, a boss
        // sub-action - and a rule enforced per action is a rule that holds until somebody
        // adds the next one. There are three Swoop dispatch sites alone. Fixing the phantom
        // in one of them fixed the phantom in one of them.
        //
        // Trailing tiles only: cutting at the first occupied tile would forbid flying through
        // anyone, which is exactly what a swoop is for.
        path = trimLandingOntoOccupant(path);

        enemyMovePath = path;
        enemyMovePathIndex = 0;
        enemyMoveTickCounter = 0;
        enemyLerpInitialized = false;
        enemyTurnState = EnemyTurnState.MOVING;
        sendMessage("§7" + currentEnemy.getDisplayName() + " moves...");
        // Announce the mover so the HUD act-order strip can highlight the unit
        // whose turn it is -previously only attacks announced themselves, so
        // movement-only turns never lit up. Also lets the camera follow.
        GridPos moveDest = path.isEmpty() ? currentEnemy.getGridPos() : path.get(path.size() - 1);
        sendToAllParty(new CombatEventPayload(
            CombatEventPayload.EVENT_MOVED, currentEnemy.getEntityId(), 0, 0,
            moveDest.x(), moveDest.z()));
    }

    /**
     * Drop trailing steps until the move ends somewhere the mob can actually stand.
     *
     * <p>"Occupied" is everyone but the mover: the player, every party member, and every other
     * combatant. Its own current tile is not an obstacle to itself, and neither are the squares
     * its own footprint already covers - a 3x3 boss overlaps several tiles of its own route.
     *
     * @return the path to walk, possibly empty when there is nowhere legal to stop
     */
    private List<GridPos> trimLandingOntoOccupant(List<GridPos> path) {
        if (currentEnemy == null || arena == null || path.isEmpty()) return path;
        List<GridPos> out = new ArrayList<>(path);
        while (!out.isEmpty()) {
            GridPos landing = out.get(out.size() - 1);
            if (CombatEntity.minDistanceFromSizedEntity(landing,
                    currentEnemy.getSizeX(), currentEnemy.getSizeZ(),
                    currentEnemy.getGridPos()) <= 0) {
                break;   // its own square - staying put is always legal
            }
            if (!tileTakenByOther(landing)) break;
            out.remove(out.size() - 1);
        }
        return out;
    }

    /**
     * Whether the current enemy, anchored at {@code pos}, would sit on top of anybody else.
     *
     * <p>Counts every other combatant and every player, and deliberately not the mover itself:
     * asking "is this square free" of the mob already standing on it would answer no for the
     * one position that is always legal.
     */
    private boolean tileTakenByOther(GridPos pos) {
        if (currentEnemy == null || arena == null) return false;
        CombatEntity occupant = arena.getOccupant(pos);
        if (occupant != null && occupant != currentEnemy && !occupant.isBackgroundBoss()) {
            return true;
        }
        return landsOnAPlayer(pos);
    }

    /** Whether a mob of the current enemy's size, anchored at {@code pos}, would cover anyone. */
    private boolean landsOnAPlayer(GridPos pos) {
        int szX = currentEnemy.getSizeX();
        int szZ = currentEnemy.getSizeZ();
        if (CombatEntity.minDistanceFromSizedEntity(pos, szX, szZ, arena.getPlayerGridPos()) == 0) {
            return true;
        }
        // Party members stand on their own tiles and are tracked separately from the
        // "current" player, so checking only the latter would let a phantom land on everyone
        // in the party except whoever's turn it happened to be.
        for (GridPos other : arena.getAllPlayerGridPositions()) {
            if (CombatEntity.minDistanceFromSizedEntity(pos, szX, szZ, other) == 0) return true;
        }
        return false;
    }

    private void tickEnemyMoving() {
        if (enemyMovePathIndex >= enemyMovePath.size()) {
            // Movement done
            enemyLerpInitialized = false;

            // Projectile impact after movement completes
            if (pendingAction instanceof EnemyAction.ProjectileMove pm && pm.impacts()) {
                resolveProjectileImpact(currentEnemy, pm.impactPos());
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                return;
            }

            // If MoveAndAttack (any variant), proceed to attack
            if (pendingAction instanceof EnemyAction.MoveAndAttack
                    || pendingAction instanceof EnemyAction.MoveAttackMove
                    || pendingAction instanceof EnemyAction.MoveAndAttackMob
                    || pendingAction instanceof EnemyAction.MoveAndAttackWithKnockback) {
                startAttackAnimation(Math.max(1, CrafticsMod.CONFIG.enemyTurnDelay() / 2));
            } else {
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = Math.max(1, CrafticsMod.CONFIG.enemyTurnDelay() / 2);
            }
            return;
        }

        MobEntity mob = currentEnemy.getMobEntity();
        if (mob == null || !mob.isAlive() || mob.isRemoved()) {
            enemyLerpInitialized = false;
            enemyTurnState = EnemyTurnState.DONE;
            return;
        }

        // Init lerp for this tile
        if (!enemyLerpInitialized) {
            enemyLerpInitialized = true;
            enemyMoveTickCounter = 0;
            enemyLerpStartX = mob.getX();
            enemyLerpStartY = mob.getY();
            enemyLerpStartZ = mob.getZ();

            // Face movement direction
            GridPos next = enemyMovePath.get(enemyMovePathIndex);
            GridPos prev = enemyMovePathIndex == 0 ? currentEnemy.getGridPos() : enemyMovePath.get(enemyMovePathIndex - 1);
            int dx = next.x() - prev.x();
            int dz = next.z() - prev.z();
            float yaw = (float) Math.toDegrees(Math.atan2(-dx, dz));
            if ("minecraft:ghast".equals(currentEnemy.getEntityTypeId())) {
                yaw = snapToCardinalYaw(yaw);
            }
            mob.setYaw(yaw);
            mob.setHeadYaw(yaw);
        }

        enemyMoveTickCounter++;
        GridPos next = enemyMovePath.get(enemyMovePathIndex);
        BlockPos endBlock = arena.gridToBlockPos(next);
        double endX = endBlock.getX() + (currentEnemy != null ? currentEnemy.getSizeX() / 2.0 : 0.5);
        double endY = arena.getEntityY(next, currentEnemy != null && currentEnemy.isFlying());
        double endZ = endBlock.getZ() + (currentEnemy != null ? currentEnemy.getSizeZ() / 2.0 : 0.5);

        // A vault reaches a tile that is not adjacent: the boss cleared the ground between
        // in one bound (see Pathfinding#addVaultEdges). Those in-between tiles are never
        // entries in the path, so the step length is what identifies the leap.
        GridPos lerpFrom = enemyMovePathIndex == 0
            ? currentEnemy.getGridPos() : enemyMovePath.get(enemyMovePathIndex - 1);
        int leapSpan = lerpFrom == null ? 1
            : Math.max(Math.abs(next.x() - lerpFrom.x()), Math.abs(next.z() - lerpFrom.z()));
        boolean vaulting = leapSpan > 1;

        // Takeoff cue, once per leap. Without one the boss simply appears on the far side of
        // the hole, which reads as a teleport rather than a jump.
        if (vaulting && enemyMoveTickCounter == 1 && mob.getWorld() instanceof ServerWorld jumpWorld) {
            jumpWorld.playSound(null, mob.getBlockPos(),
                net.minecraft.sound.SoundEvents.ENTITY_RAVAGER_ROAR,
                net.minecraft.sound.SoundCategory.HOSTILE, 0.7f, 1.6f);
            jumpWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                mob.getX(), mob.getY() + 0.1, mob.getZ(), 14, 0.4, 0.05, 0.4, 0.06);
            sendMessage("§7" + currentEnemy.getDisplayName() + " leaps the gap!");
        }

        int emTicks2 = getMoveTicks();
        // A leap gets more ticks than a step so the arc is legible instead of a blur, and it
        // scales with the span: a 4-tile bound reads as a bigger commitment than a 2-tile one.
        if (vaulting) emTicks2 = Math.max(emTicks2, getMoveTicks() * leapSpan);
        float progress = Math.min(1.0f, (float) enemyMoveTickCounter / emTicks2);
        double x = enemyLerpStartX + (endX - enemyLerpStartX) * progress;
        double y = enemyLerpStartY + (endY - enemyLerpStartY) * progress;
        double z = enemyLerpStartZ + (endZ - enemyLerpStartZ) * progress;
        if (vaulting) {
            // Parabola peaking at the halfway point. Height grows with the span so a wide
            // leap visibly clears more air; 4*p*(1-p) is 1.0 at p=0.5 and 0 at both ends,
            // so the mob still lands exactly on the tile.
            double apex = 1.2 + 0.4 * leapSpan;
            y += apex * 4.0 * progress * (1.0 - progress);
            if (mob.getWorld() instanceof ServerWorld leapWorld) {
                leapWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                    x, y, z, 2, 0.2, 0.1, 0.2, 0.01);
            }
        }
        mob.requestTeleport(x, y, z);

        // Sync visual projectile entity position with the invisible tracking mob
        if (currentEnemy.isProjectile()) {
            syncVisualProjectile(currentEnemy, x, y + 0.5, z);
        }

        // Swoop trail particles -spawned every tick along the lerp path so the
        // dragon's flight is a visible sweep of breath particles across the arena.
        if (pendingAction instanceof EnemyAction.Swoop && mob.getWorld() instanceof ServerWorld sw) {
            boolean isDragon = currentEnemy.getAiKey() != null
                && currentEnemy.getAiKey().contains("dragons_nest");
            if (isDragon) {
                sw.spawnParticles(net.minecraft.particle.ParticleTypes.DRAGON_BREATH,
                    x, y + 1.5, z, 8, 0.6, 0.4, 0.6, 0.04);
                sw.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
                    x, y + 2.0, z, 6, 0.5, 0.3, 0.5, 0.08);
                sw.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                    x, y + 1.0, z, 3, 0.4, 0.3, 0.4, 0.01);
            } else {
                sw.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                    x, y + 1.0, z, 4, 0.3, 0.3, 0.3, 0.02);
                sw.spawnParticles(net.minecraft.particle.ParticleTypes.SMOKE,
                    x, y + 0.5, z, 2, 0.2, 0.2, 0.2, 0.01);
            }
        }

        if (enemyMoveTickCounter >= emTicks2) {
            arena.moveEntity(currentEnemy, next);

            // Landing: the thud is the other half of the leap read.
            if (vaulting && mob.getWorld() instanceof ServerWorld landWorld) {
                landWorld.playSound(null, arena.gridToBlockPos(next),
                    net.minecraft.sound.SoundEvents.BLOCK_ANVIL_LAND,
                    net.minecraft.sound.SoundCategory.HOSTILE, 0.6f, 0.6f);
                BlockPos landBlock = arena.gridToBlockPos(next);
                landWorld.spawnParticles(net.minecraft.particle.ParticleTypes.CLOUD,
                    landBlock.getX() + 0.5, landBlock.getY(), landBlock.getZ() + 0.5,
                    18, 0.5, 0.05, 0.5, 0.08);
            }

            // Void Walker rift: teleport the enemy if they landed on one of the
            // portals. Cancel the remaining path so the lerp doesn't snap back.
            if (handleEnemyVoidRiftEntry(currentEnemy, next)) {
                enemyLerpInitialized = false;
                enemyMovePathIndex = enemyMovePath.size();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                return;
            }

            // Check if enemy walked onto a void/death tile
            if (checkEnemyFallDeath(currentEnemy)) {
                enemyLerpInitialized = false;
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                return;
            }

            // Bow-laid traps fire the moment an enemy steps into them.
            if (triggerTileTrap(next, currentEnemy)) {
                enemyLerpInitialized = false;
                enemyMovePathIndex = enemyMovePath.size();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                return;
            }

            // Check for hex trap tile effect
            if (tileEffects.containsKey(next) && "hex_trap".equals(tileEffects.get(next))) {
                tileEffects.remove(next);
                hexTrapTurnsRemaining = 0;
                int trapDmg = currentEnemy.takeDamage(12);
                currentEnemy.setStunned(true);
                sendMessage("§5\u2620 " + currentEnemy.getDisplayName() + " triggers a Hex Trap! " + trapDmg + " damage + stunned!");
                if (currentEnemy.getMobEntity() != null) {
                    ServerWorld sw = (ServerWorld) player.getEntityWorld();
                    sw.spawnParticles(net.minecraft.particle.ParticleTypes.WITCH,
                        currentEnemy.getMobEntity().getX(), currentEnemy.getMobEntity().getY() + 1.0,
                        currentEnemy.getMobEntity().getZ(), 20, 0.5, 0.5, 0.5, 0.1);
                    player.getWorld().playSound(null, currentEnemy.getMobEntity().getBlockPos(),
                        net.minecraft.sound.SoundEvents.ENTITY_ELDER_GUARDIAN_CURSE,
                        net.minecraft.sound.SoundCategory.HOSTILE, 0.8f, 1.2f);
                }
                checkAndHandleDeath(currentEnemy);
            }

            // Check for honey trap -enemy loses all remaining movement
            if (tileEffects.containsKey(next) && "honey".equals(tileEffects.get(next))) {
                sendMessage("§e" + currentEnemy.getDisplayName() + " is stuck in honey!");
                tileEffects.remove(next);
                enemyLerpInitialized = false;
                // Skip remaining movement -go directly to DONE
                enemyMovePathIndex = enemyMovePath.size();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                // Restore the original floor block under the consumed honey.
                BlockPos honeyBp = arena.gridToBlockPos(next).down();
                ServerWorld honeyWorld = (ServerWorld) player.getEntityWorld();
                GridTile honeyTile = arena.getTile(next);
                net.minecraft.block.Block honeyRestore = honeyTile != null
                    ? honeyTile.getBlockType() : getBiomeFloorBlock();
                honeyWorld.setBlockState(honeyBp, honeyRestore.getDefaultState(),
                    net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);
                return;
            }

            // Check for slime trap -enemy bounces, gets stunned + loses
            // remaining movement. Consume the trap (one bounce per slime block).
            if (tileEffects.containsKey(next) && "slime".equals(tileEffects.get(next))) {
                sendMessage("§a" + currentEnemy.getDisplayName() + " bounces off the slime block!");
                tileEffects.remove(next);
                currentEnemy.setStunned(true);
                enemyLerpInitialized = false;
                enemyMovePathIndex = enemyMovePath.size();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                // Replace the slime block visual with the original floor block.
                BlockPos slimeBp = arena.gridToBlockPos(next).down();
                ServerWorld slimeWorld = (ServerWorld) player.getEntityWorld();
                GridTile slimeTile = arena.getTile(next);
                net.minecraft.block.Block restoreFloor = slimeTile != null
                    ? slimeTile.getBlockType() : getBiomeFloorBlock();
                slimeWorld.setBlockState(slimeBp, restoreFloor.getDefaultState(),
                    net.minecraft.block.Block.NOTIFY_LISTENERS | net.minecraft.block.Block.FORCE_STATE);
                return;
            }

            // Water tile: soak non-immune enemies
            GridTile enemyLandingTile = arena.getTile(next);
            if (enemyLandingTile != null
                    && enemyLandingTile.getType() == com.crackedgames.craftics.core.TileType.WATER
                    && !isWaterImmune(currentEnemy.getEntityTypeId())) {
                currentEnemy.stackSoaked(2, 1);
                sendMessage("§b" + currentEnemy.getDisplayName() + " is soaked from wading through water!");
            }

            // Mud tile: 50% chance to stop the enemy's remaining movement, mirroring
            // the player's mud-truncation rule above (probabilistic cobweb).
            if (enemyLandingTile != null
                    && enemyLandingTile.getType() == com.crackedgames.craftics.core.TileType.MUD
                    && Math.random() < 0.5) {
                sendMessage("§6" + currentEnemy.getDisplayName() + " is stuck in the mud!");
                enemyLerpInitialized = false;
                enemyMovePathIndex = enemyMovePath.size();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                return;
            }

            // Fire tile: walking through the flames sets the enemy alight
            if (enemyLandingTile != null && enemyLandingTile.getType().isFlames()) {
                applyFireTileBurn(currentEnemy, enemyLandingTile.getType());
            }

            // Lava tile: 10 damage when enemy steps on it
            if (enemyLandingTile != null
                    && enemyLandingTile.getType() == com.crackedgames.craftics.core.TileType.LAVA) {
                int eLavaDmg = currentEnemy.takeDamage(10);
                sendMessage("§6" + currentEnemy.getDisplayName() + " steps in lava for " + eLavaDmg + " damage!");
                if (!currentEnemy.isAlive()) {
                    killEnemy(currentEnemy);
                    enemyLerpInitialized = false;
                    enemyTurnState = EnemyTurnState.DONE;
                    enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                    return;
                }
            }


            // Check for cake -enemy heals 2 HP, one use consumed
            if (tileEffects.containsKey(next) && tileEffects.get(next).startsWith("cake")) {
                // cake format: "cake" or "cake:usesRemaining"
                String cakeData = tileEffects.get(next);
                int uses = 3;
                if (cakeData.contains(":")) {
                    try { uses = Integer.parseInt(cakeData.split(":")[1]); } catch (Exception ignored) {}
                }
                // Enemies heal from cake too
                if (currentEnemy.getCurrentHp() < currentEnemy.getMaxHp()) {
                    currentEnemy.heal(2);
                    sendMessage("§d" + currentEnemy.getDisplayName() + " eats cake! +2 HP");
                }
                uses--;
                if (uses <= 0) {
                    tileEffects.remove(next);
                } else {
                    tileEffects.put(next, "cake:" + uses);
                }
            }

            if (pendingAction instanceof EnemyAction.MoveAndAttack
                    && currentEnemy != null
                    && currentEnemy.isEnraged()
                    && currentEnemy.getAiKey() != null
                    && currentEnemy.getAiKey().contains("revenant")) {
                GridTile trailTile = arena.getTile(next);
                if (trailTile != null && trailTile.isWalkable()) {
                    // setTemporaryType, not setType+setTurnsRemaining: the latter records FIRE
                    // as the tile's OWN restore type, so the trail never burned back out.
                    trailTile.setTemporaryType(TileType.FIRE, 3);
                    BlockPos firePos = arena.gridToBlockPos(next);
                    ServerWorld fireWorld = (ServerWorld) player.getEntityWorld();
                    paintTileBlock(fireWorld, next, trailTile);
                    fireWorld.spawnParticles(net.minecraft.particle.ParticleTypes.FLAME,
                        firePos.getX() + 0.5, firePos.getY() + 0.2, firePos.getZ() + 0.5,
                        3, 0.15, 0.05, 0.15, 0.01);
                }
            }

            enemyLerpInitialized = false;
            enemyMovePathIndex++;
        }
    }

    /**
     * Returns the ranged projectile effect name for a mob type, or null if melee.
     * Used to determine animation style (ranged aim vs melee lunge).
     */
    private static String getRangedProjectileType(String entityTypeId) {
        return switch (entityTypeId) {
            case "minecraft:skeleton", "minecraft:bogged" -> "arrow";
            case "minecraft:stray" -> "frost_arrow";
            case "minecraft:pillager" -> "crossbow";
            case "minecraft:blaze" -> "fireball";
            case "minecraft:ghast" -> "fireball";
            case "minecraft:witch" -> "potion";
            case "minecraft:shulker" -> "shulker_bullet";
            case "minecraft:llama", "minecraft:trader_llama" -> "llama_spit";
            case "minecraft:drowned" -> "trident";
            case "minecraft:breeze" -> "wind_charge";
            default -> null;
        };
    }

    /**
     * Mob-vs-mob stealth gate: if the predator's returned action targets a mob
     * that's on a tall-grass/fern tile and the predator isn't adjacent to it,
     * downgrade the action to Idle. The player case is handled pre-decision.
     */
    private EnemyAction gateMobTargetingThroughStealth(CombatEntity predator, EnemyAction action) {
        if (action == null) return action;
        Integer targetId = extractTargetMobId(action);
        if (targetId == null) return action;
        CombatEntity prey = null;
        if (enemies != null) {
            for (CombatEntity e : enemies) {
                if (e != null && e.getMobEntity() != null
                        && e.getMobEntity().getId() == targetId) { prey = e; break; }
            }
        }
        if (prey == null) return action;
        if (StealthTiles.isConcealedFrom(arena, predator.getGridPos(), prey.getGridPos(), player.getEntityWorld())) {
            return new EnemyAction.Idle();
        }
        return action;
    }

    private static Integer extractTargetMobId(EnemyAction a) {
        if (a instanceof EnemyAction.AttackMob am) return am.targetEntityId();
        if (a instanceof EnemyAction.MoveAndAttackMob mam) return mam.targetEntityId();
        return null;
    }

    /** Initialize attack animation and transition to ANIMATING state. */
    private void startAttackAnimation(int delay) {
        attackAnimTick = 0;
        attackAnimSwung = false;
        enemyTurnState = EnemyTurnState.ANIMATING;
        enemyTurnDelay = delay;
        if (currentEnemy != null && currentEnemy.getMobEntity() != null) {
            // Casters channel (arms raised) instead of cocking a melee windup.
            var style = com.crackedgames.craftics.combat.animation.MobAttackAnimations
                .styleFor(currentEnemy.getEntityTypeId(), false);
            com.crackedgames.craftics.combat.animation.MobAnimations.set(
                currentEnemy.getMobEntity(),
                com.crackedgames.craftics.combat.animation.MobAttackAnimations.windupPose(style));
        }
    }

    /**
     * Attack animation phase: mob-type-specific animations before damage is applied.
     * Ranged mobs lean back to aim then snap forward on release.
     * Melee mobs lunge forward then return. Spider crouches before pouncing.
     * On completion, transitions to ATTACKING to apply damage.
     */
    private void tickEnemyAnimating() {
        net.minecraft.entity.mob.MobEntity mob = currentEnemy.getMobEntity();
        if (mob == null || !mob.isAlive() || mob.isRemoved()) {
            enemyTurnState = EnemyTurnState.ATTACKING;
            return;
        }

        attackAnimTick++;

        String entityType = currentEnemy.getEntityTypeId();
        // Ranged mobs use ranged anim even when they MoveAndAttack (move to get LOS, then shoot)
        // Special case: drowned without tridents are pure melee, not ranged
        boolean isRanged = pendingAction instanceof EnemyAction.RangedAttack
            || (pendingAction instanceof EnemyAction.MoveAndAttack && getRangedProjectileType(entityType) != null
                && !"minecraft:drowned".equals(entityType))
            || (pendingAction instanceof EnemyAction.MoveAndAttack && "minecraft:drowned".equals(entityType)
                && currentEnemy.isDrownedWithTrident());

        // Tick 1: Face the player and initialize
        if (!attackAnimSwung) {
            attackAnimSwung = true;
            attackAnimOriginX = mob.getX();
            attackAnimOriginY = mob.getY();
            attackAnimOriginZ = mob.getZ();

            // Face toward the target -allies face their enemy target, enemies face chosen aggro target or player
            double dx, dz;
            if (currentEnemy.isAlly() && pendingAllyAttackTarget != null) {
                net.minecraft.entity.mob.MobEntity tgtMob = pendingAllyAttackTarget.getMobEntity();
                if (tgtMob != null) {
                    dx = tgtMob.getX() - mob.getX();
                    dz = tgtMob.getZ() - mob.getZ();
                } else {
                    net.minecraft.util.math.BlockPos tgtBlock =
                        arena.gridToBlockPos(pendingAllyAttackTarget.getGridPos());
                    dx = tgtBlock.getX() + 0.5 - mob.getX();
                    dz = tgtBlock.getZ() + 0.5 - mob.getZ();
                }
            } else if (currentEnemyPetAggroTarget != null) {
                net.minecraft.entity.mob.MobEntity tgtMob = currentEnemyPetAggroTarget.getMobEntity();
                if (tgtMob != null) {
                    dx = tgtMob.getX() - mob.getX();
                    dz = tgtMob.getZ() - mob.getZ();
                } else {
                    net.minecraft.util.math.BlockPos tgtBlock =
                        arena.gridToBlockPos(currentEnemyPetAggroTarget.getGridPos());
                    dx = tgtBlock.getX() + 0.5 - mob.getX();
                    dz = tgtBlock.getZ() + 0.5 - mob.getZ();
                }
            } else {
                // Face the closest party member, not just `this.player` (the
                // host). Without this, in MP a mob attacking player 2 still
                // pivots to face the host's tile, then plays its swing in the
                // wrong direction relative to who it's actually hitting.
                ServerPlayerEntity faceTarget = findClosestPartyTarget(currentEnemy.getGridPos());
                if (faceTarget == null) faceTarget = player;
                dx = faceTarget.getX() - mob.getX();
                dz = faceTarget.getZ() - mob.getZ();
            }
            float yaw = (float) Math.toDegrees(Math.atan2(-dx, dz));
            // Ghasts must always face a cardinal direction
            if ("minecraft:ghast".equals(entityType)) {
                yaw = snapToCardinalYaw(yaw);
            }
            mob.setYaw(yaw);
            mob.setHeadYaw(yaw);

            double dist = Math.sqrt(dx * dx + dz * dz);
            if (dist > 0.01) {
                attackAnimLungeX = dx / dist;
                attackAnimLungeZ = dz / dist;
            } else {
                attackAnimLungeX = 0;
                attackAnimLungeZ = 1;
            }

            // (The hand swing fires on each style's strike frame below, in sync
            // with the impact -the old code also swung here at windup start.)

            // Send attack anim event to client for mob-specific particles
            int attackType = isRanged ? 2
                : (pendingAction instanceof EnemyAction.AttackWithKnockback
                    || pendingAction instanceof EnemyAction.MoveAndAttackWithKnockback) ? 1 : 0;
            GridPos playerGridPos = arena.getPlayerGridPos();
            ServerPlayNetworking.send(player, new com.crackedgames.craftics.network.CombatEventPayload(
                com.crackedgames.craftics.network.CombatEventPayload.EVENT_MOB_ATTACK_ANIM,
                currentEnemy.getMobEntity().getId(), attackType, 0,
                playerGridPos.x(), playerGridPos.z()
            ));
        }

        // === Style-driven attack animation ===
        // The per-mob-type curves (and the addon registration point) live in
        // MobAttackAnimations -this used to be a ~250-line hardcoded chain of
        // isSpiderLike/isHeavyHitter/... branches that addons couldn't touch.
        var style = com.crackedgames.craftics.combat.animation.MobAttackAnimations
            .styleFor(entityType, isRanged);
        var frame = com.crackedgames.craftics.combat.animation.MobAttackAnimations
            .frameAt(style, attackAnimTick);

        mob.requestTeleport(
            attackAnimOriginX + attackAnimLungeX * frame.forward(),
            attackAnimOriginY + frame.rise(),
            attackAnimOriginZ + attackAnimLungeZ * frame.forward());

        if (frame.strike()) {
            mob.swingHand(net.minecraft.util.Hand.MAIN_HAND);
            // Melee strikes flash the ATTACK pose (biped arm snap + sweep FX);
            // ranged releases and caster lobs keep their own silhouette.
            if (com.crackedgames.craftics.combat.animation.MobAttackAnimations.strikeUsesAttackPose(style)) {
                com.crackedgames.craftics.combat.animation.MobAnimations.set(mob,
                    com.crackedgames.craftics.combat.animation.AnimState.ATTACK);
            }
        }

        if (frame.done()) {
            mob.requestTeleport(attackAnimOriginX, attackAnimOriginY, attackAnimOriginZ);
            // Ease the pose back to neutral instead of freezing mid-swing (the
            // old flow left WINDUP active until the safety tick expired it).
            com.crackedgames.craftics.combat.animation.MobAnimations.set(mob,
                com.crackedgames.craftics.combat.animation.AnimState.RECOIL);
            enemyTurnState = EnemyTurnState.ATTACKING;
            enemyTurnDelay = 0;
        }
    }

    private void tickEnemyAttacking() {
        // Ally pet attack resolution -damage applies after the animation completes
        if (currentEnemy.isAlly() && pendingAction instanceof EnemyAction.MoveAndAttackMob maam) {
            CombatEntity allyTarget = findEnemyById(maam.targetEntityId());
            pendingAllyAttackTarget = null;
            // A missed swing skips the whole block: no damage, no aggro, no on-hit ability,
            // no Fang shock. Landing for zero would still fire every one of those.
            if (allyTarget != null && allyTarget.isAlive()
                    && !attackMisses(currentEnemy, allyTarget)) {
                int dealt = allyTarget.takeDamage(maam.damage());
                allyTarget.setAggroAllyEntityId(currentEnemy.getEntityId());
                // Special on-hit ability (strider burn, soak, slow, ...).
                String abilityMsg = allyTarget.isAlive()
                    ? com.crackedgames.craftics.combat.ai.ally.AllyAbilities.applyOnHit(currentEnemy, allyTarget)
                    : "";
                // Shovel Fang enchantments: the owner's shovel arms every pet they own. Seekers
                // are a spell's payload rather than a pet, so they carry no Fangs (matching how
                // they're excluded from Pet affinity and Honed).
                List<CombatEntity> fangShocked = new ArrayList<>();
                if (allyTarget.isAlive() && !currentEnemy.isSeekerProjectile()) {
                    ServerPlayerEntity fangOwner = resolveAllyOwner(currentEnemy.getOwnerUuid());
                    if (fangOwner != null && fangOwner.getEntityWorld() instanceof ServerWorld fangWorld) {
                        abilityMsg += ShovelEnchantEffects.applyOnAllyHit(
                            currentEnemy, allyTarget, fangOwner, arena, fangWorld, fangShocked);
                    }
                }
                // Rabid: the owner's shovel makes every pet copy ITS OWN debuffs onto what it hits.
                // The pet (currentEnemy) is a CombatEntity with discrete debuff fields, not a
                // CombatEffects map, so each is read off its getters and dispatched by hand. Full
                // remaining duration, no guardrail, mirrors Conductive's balance. Rabid reads the
                // shovel focus inventory-wide (level, not heldLevel). Seekers carry no Rabid, same
                // as they carry no Fangs.
                if (allyTarget.isAlive() && !currentEnemy.isSeekerProjectile()) {
                    ServerPlayerEntity rabidOwner = resolveAllyOwner(currentEnemy.getOwnerUuid());
                    if (rabidOwner != null
                            && CrafticsEnchantments.level(rabidOwner, CrafticsEnchantments.RABID) > 0) {
                        boolean rabidCopied = false;
                        if (currentEnemy.getPoisonTurns() > 0) {
                            allyTarget.stackPoison(currentEnemy.getPoisonTurns(), currentEnemy.getPoisonAmplifier());
                            rabidCopied = true;
                        }
                        if (currentEnemy.getBurningTurns() > 0) {
                            allyTarget.stackBurning(currentEnemy.getBurningTurns(), currentEnemy.getBurningAmplifier());
                            rabidCopied = true;
                        }
                        if (currentEnemy.getWitherTurns() > 0) {
                            allyTarget.stackWither(currentEnemy.getWitherTurns(), currentEnemy.getWitherAmplifier());
                            rabidCopied = true;
                        }
                        if (currentEnemy.getSlownessTurns() > 0) {
                            allyTarget.stackSlowness(currentEnemy.getSlownessTurns(), currentEnemy.getSlownessPenalty());
                            rabidCopied = true;
                        }
                        if (currentEnemy.getBleedStacks() > 0) {
                            allyTarget.stackBleed(currentEnemy.getBleedStacks());
                            rabidCopied = true;
                        }
                        if (currentEnemy.getBlindedTurns() > 0) {
                            allyTarget.stackBlinded(currentEnemy.getBlindedTurns());
                            rabidCopied = true;
                        }
                        if (currentEnemy.getSoakedTurns() > 0) {
                            allyTarget.stackSoaked(currentEnemy.getSoakedTurns(), currentEnemy.getSoakedAmplifier());
                            rabidCopied = true;
                        }
                        if (currentEnemy.getConfusionTurns() > 0) {
                            allyTarget.stackConfusion(currentEnemy.getConfusionTurns(), currentEnemy.getConfusionAmplifier());
                            rabidCopied = true;
                        }
                        if (rabidCopied) {
                            abilityMsg += " §aRabid!";
                        }
                    }
                }
                if (currentEnemy.isLitOneShot() && allyTarget.isAlive()) {
                    allyTarget.stackBurning(3, 0); // Burning I; the 2 here used to be damage/turn
                }
                sendMessage("§a" + currentEnemy.getDisplayName() + " attacks "
                    + allyTarget.getDisplayName() + " for " + dealt + " damage!" + abilityMsg);
                // Addon combat effects: ally attack notification
                final CombatEntity fAlly = currentEnemy;
                final CombatEntity fAllyTarget = allyTarget;
                final int fAllyDealt = dealt;
                fireEffectHook(h -> h.onAllyAttack(effectContext, fAlly, fAllyTarget, fAllyDealt));
                if (!allyTarget.isAlive()) {
                    // Addon combat effects: ally kill notification
                    fireEffectHook(h -> h.onAllyKill(effectContext, fAlly, fAllyTarget));
                    // Route through the full death pipeline (NOT killEnemy) so a
                    // stacked target drops its next layer / rider instead of being
                    // hard-killed outright. killEnemy skips transformStackLayer, so
                    // an ally killing a Zombie Stack would vanish the whole stack
                    // with the baby never dropping. checkAndHandleDeath transforms
                    // the layer when one remains (target stays alive) and runs the
                    // real death side effects only when the last layer falls.
                    // Credit the ally's OWNER (not the current-turn player) for the kill -
                    // correct for party multiplayer loot/kill-streak attribution.
                    if (currentEnemy.getOwnerUuid() != null) {
                        allyTarget.setLastDamagerUuid(currentEnemy.getOwnerUuid());
                    }
                    // Generic on-kill ally hook (e.g. barrel golem bartering bonus loot).
                    // Hooks come from the AllyKillRegistry, populated by compat modules.
                    com.crackedgames.craftics.combat.ai.ally.AllyKillHook killHook =
                        com.crackedgames.craftics.combat.ai.ally.AllyKillRegistry.hookFor(currentEnemy.getEntityTypeId());
                    if (killHook != null) killHook.onKill(currentEnemy, allyTarget);
                    checkAndHandleDeath(allyTarget);
                    // Only credit the kill / check victory if the target actually
                    // died (a stack transform leaves it alive on the next layer).
                    // checkAndHandleDeath doesn't itself do kill-streak or the
                    // victory check, so mirror what killEnemy used to provide here.
                    if (!allyTarget.isAlive()) {
                        // killEnemy only counts non-ally deaths toward the streak;
                        // preserve that guard in case an ally ever targets an ally.
                        if (!allyTarget.isAlly()) {
                            onEnemyKilled(allyTarget);
                        }
                        if (!anyEnemyBlockingVictory()) {
                            handleVictory();
                        }
                    }
                }
                // Thunder Fang's arc can kill things the ally never touched, so those need the
                // same death pipeline the direct victim just went through. Without this a
                // shocked-to-death enemy would stand there at 0 HP until something else nudged it.
                for (CombatEntity zapped : fangShocked) {
                    if (zapped.isAlive()) continue;
                    if (currentEnemy.getOwnerUuid() != null) {
                        zapped.setLastDamagerUuid(currentEnemy.getOwnerUuid());
                    }
                    checkAndHandleDeath(zapped);
                    if (!zapped.isAlive() && !zapped.isAlly()) {
                        onEnemyKilled(zapped);
                    }
                }
                if (!fangShocked.isEmpty()
                        && !anyEnemyBlockingVictory()) {
                    handleVictory();
                }
                // Bee allies pay the same sting recoil as enemy bees do.
                if ("minecraft:bee".equals(currentEnemy.getEntityTypeId())) {
                    applyBeeStingRecoil(currentEnemy);
                }
                // Lit coal golem burns out after its one attack.
                if (currentEnemy.isLitOneShot()) {
                    sendMessage("§7The lit " + currentEnemy.getDisplayName() + " burns out.");
                    currentEnemy.takeDamage(currentEnemy.getCurrentHp() + currentEnemy.getDefense() + 9999);
                    checkAndHandleDeath(currentEnemy);
                }
                // A seeker IS its payload: reaching a target spends it. Detonate here
                // rather than in the AI, since only the manager can pull it off the grid.
                if (currentEnemy.isSeekerProjectile()) {
                    detonateSeeker(currentEnemy);
                }
            }
            sendSync();
            enemyTurnState = EnemyTurnState.DONE;
            enemyTurnDelay = 8;
            return;
        }

        // Handle mob-vs-mob attacks (MoveAndAttackMob)
        if (pendingAction instanceof EnemyAction.MoveAndAttackMob maam) {
            CombatEntity target = findEnemyById(maam.targetEntityId());
            if (target != null && target.isAlive() && !attackMisses(currentEnemy, target)) {
                int bannerBonus = target.isAlly()
                    ? BannerEffects.defenseBonusAt(target.getGridPos(), tileEffects)
                        + walkingBannerBonusAt(target.getGridPos())
                    : 0;
                int dealt = target.takeDamage(maam.damage(), bannerBonus);
                sendMessage("§6" + currentEnemy.getDisplayName() + " attacks " + target.getDisplayName() + " for " + dealt + "!");
                checkAndHandleDeath(target);
            }
            sendSync();
            enemyTurnState = EnemyTurnState.DONE;
            enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            return;
        }

        // Handle ranged attacks -no adjacency required.
        // Some AIs (like Breeze) use MoveAndAttack to reposition and then fire.
        EnemyAction.RangedAttack resolvedRanged = null;
        if (pendingAction instanceof EnemyAction.RangedAttack ra) {
            resolvedRanged = ra;
        } else if (pendingAction instanceof EnemyAction.MoveAndAttack maa) {
            String projectileType = getRangedProjectileType(currentEnemy.getEntityTypeId());
            if (projectileType != null) {
                resolvedRanged = new EnemyAction.RangedAttack(maa.damage(), projectileType);
            }
        }

        if (resolvedRanged != null) {
            // Ranged projectiles cannot fly over obstacles -check line of sight first.
            // MP target resolution: pick the closest live party member (not the
            // stale arena.getPlayerGridPos which only tracks the last-turn
            // player). Without this, a skeleton's arrow targets whoever's tile
            // the arena tracker happens to be on, and on the damage side
            // `this.player` may not match the intended target -so the wrong
            // player took the hit (often producing "skeleton attacked twice in
            // one turn" reports when the death handler then flipped
            // this.player mid-chain).
            // Confused enemy shooting an ally takes priority; else pet-aggro; else player.
            CombatEntity rangedTarget =
                (confusedRangedVictim != null && confusedRangedVictim.isAlive())
                    ? confusedRangedVictim
                    : ((currentEnemyPetAggroTarget != null && currentEnemyPetAggroTarget.isAlive())
                        ? currentEnemyPetAggroTarget : null);
            ServerPlayerEntity rangedTargetPlayer = rangedTarget != null
                ? null : findClosestPartyTarget(currentEnemy.getGridPos());
            GridPos rangedTargetPos = rangedTarget != null ? rangedTarget.getGridPos()
                : (rangedTargetPlayer != null
                    ? gridPosOf(rangedTargetPlayer)
                    : arena.getPlayerGridPos());
            if (!Pathfinding.hasLineOfSight(arena, currentEnemy.getGridPos(), rangedTargetPos)) {
                sendMessage("§7" + currentEnemy.getDisplayName() + "'s ranged attack is blocked by an obstacle.");
                sendSync();
                enemyTurnState = EnemyTurnState.DONE;
                enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
                return;
            }
            // Enemy bow enchantment effects: Power adds damage, Flame ignites, Punch knocks back
            int rangedBaseDmg = resolvedRanged.damage();
            boolean rangedFlame = false;
            int rangedFlameLevel = 0;
            int rangedPunchLevel = 0;
            if (currentEnemy != null && currentEnemy.getMobEntity() != null) {
                ItemStack ew = currentEnemy.getMobEntity().getMainHandStack();
                if (!ew.isEmpty()) {
                    int powerLvl = PlayerCombatStats.getEnchantLevel(ew, "minecraft:power");
                    if (powerLvl > 0) rangedBaseDmg += powerLvl;
                    rangedFlameLevel = PlayerCombatStats.getEnchantLevel(ew, "minecraft:flame");
                    if (rangedFlameLevel > 0) rangedFlame = true;
                    rangedPunchLevel = PlayerCombatStats.getEnchantLevel(ew, "minecraft:punch");
                }
            }
            int raDamage = (int)(rangedBaseDmg * com.crackedgames.craftics.CrafticsMod.CONFIG.enemyDamageMultiplier());
            // Confused-ranged victim (a fellow enemy) takes the CombatEntity damage path,
            // same as a pet-aggro target - so a confused skeleton's arrow lands on its ally.
            CombatEntity petTarget =
                (confusedRangedVictim != null && confusedRangedVictim.isAlive())
                    ? confusedRangedVictim
                    : ((currentEnemyPetAggroTarget != null && currentEnemyPetAggroTarget.isAlive())
                        ? currentEnemyPetAggroTarget : null);
            if (petTarget != null) {
                // Checked inside the pet branch, never on the branch condition: the else
                // below redirects the whole shot onto the player, so a miss folded into
                // the `if` would turn a fumbled shot at a wolf into a hit on its owner.
                if (!attackMisses(currentEnemy, petTarget)) {
                // Addon combat effects: modify ally incoming damage
                int raHookedDmg = fireEffectHookChained(raDamage,
                    (h, d) -> h.onAllyTakeDamage(effectContext, petTarget, currentEnemy, d));
                int raActual = petTarget.takeDamage(raHookedDmg);
                sendMessage("§c" + currentEnemy.getDisplayName() + " hits "
                    + petTarget.getDisplayName() + " for " + raActual + "!");
                if (!petTarget.isAlive()) {
                    fireEffectHook(h -> h.onAllyDeath(effectContext, petTarget));
                }
                checkAndHandleDeath(petTarget);
                } // end pet hit (skipped on a miss)
            } else {
                // Route the entire ranged post-hit chain to the actual target
                // player via the swap pattern (mirrors the melee path). Without
                // this, the first damagePlayer hits whoever this.player is at
                // ranged-attack time and any handler hand-off mid-chain leaks
                // subsequent damage onto the new turn-holder -producing the
                // "skeleton attacked twice in one turn" report where player 2
                // died then player 1 was hit immediately for follow-on damage.
                ServerPlayerEntity savedRangedPlayer = this.player;
                boolean raSwapped = rangedTargetPlayer != null && rangedTargetPlayer != savedRangedPlayer;
                if (raSwapped) {
                    this.player = rangedTargetPlayer;
                    retargetEffectsToCurrentPlayer();
                }
                boolean raTargetDied = false;
                try {
                int raActual = damagePlayer(raDamage, currentEnemy, DamageType.RANGED);

                // Evoker fangs: magic sound + fang particles at player position
                String raEntityType = currentEnemy.getEntityTypeId();
                if ("minecraft:evoker".equals(raEntityType) || "fangs".equals(resolvedRanged.effectName())) {
                    ServerWorld raWorld = (ServerWorld) player.getEntityWorld();
                    player.getWorld().playSound(null, player.getBlockPos(),
                        net.minecraft.sound.SoundEvents.ENTITY_EVOKER_FANGS_ATTACK,
                        net.minecraft.sound.SoundCategory.HOSTILE, 1.0f, 1.0f);
                    // Spawn evoker fang entities at the player's feet for visual effect
                    BlockPos fangPos = player.getBlockPos();
                    for (int fi = 0; fi < 3; fi++) {
                        double fx = fangPos.getX() + 0.5 + (Math.random() - 0.5) * 2;
                        double fz = fangPos.getZ() + 0.5 + (Math.random() - 0.5) * 2;
                        var fangs = new net.minecraft.entity.mob.EvokerFangsEntity(
                            raWorld, fx, fangPos.getY(), fz, 0, fi * 2, null);
                        raWorld.spawnEntity(fangs);
                    }
                    // Casting particles at the evoker
                    if (currentEnemy.getMobEntity() != null) {
                        raWorld.spawnParticles(net.minecraft.particle.ParticleTypes.WITCH,
                            currentEnemy.getMobEntity().getX(),
                            currentEnemy.getMobEntity().getY() + 1.5,
                            currentEnemy.getMobEntity().getZ(),
                            15, 0.3, 0.5, 0.3, 0.05);
                    }
                } else {
                    player.getWorld().playSound(null, player.getBlockPos(),
                        net.minecraft.sound.SoundEvents.ENTITY_ARROW_HIT_PLAYER,
                        net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 1.0f);
                }

                // On-hit effects only land if the shot connected (dodge/block negates them).
                if (!lastHitAvoided) {
                if (isFrostboundBossAttacker()) {
                    applyFrostboundSlownessOnHit();
                }
                // A pure-effect throw (e.g. the witch's poison potion) deals no impact
                // damage -skip the "hits you for 0" line and let the effect speak.
                if (raActual > 0) {
                    sendMessage("§c" + currentEnemy.getDisplayName() + " hits "
                        + (raSwapped ? rangedTargetPlayer.getName().getString() : "you")
                        + " for " + raActual + "!");
                }
                applyEnemyHitEffect(raEntityType);
                // Flame enchant on enemy bow ignites the player
                if (rangedFlame && !combatEffects.hasFireResistance()) {
                    addEffectHooked(CombatEffects.EffectType.BURNING, 2 + rangedFlameLevel, 0);
                    sendMessage("§6  Flaming arrow ignites you! (Burning for "
                        + (2 + rangedFlameLevel) + " turns)");
                }
                // Punch enchant: knock the player back
                if (rangedPunchLevel > 0) {
                    applyPlayerKnockback(currentEnemy.getGridPos(), rangedPunchLevel + 1, currentEnemy);
                    sendMessage("§e  Punch arrow knocks you back!");
                }
                } // end ranged on-hit effects (skipped on a fully avoided shot)
                checkOverwatchCounter(currentEnemy);

                if (getPlayerHp() <= 0) {
                    sendSync();
                    raTargetDied = true;
                    handlePlayerDeathOrGameOver();
                    return;
                }
                } finally {
                    if (!raTargetDied) {
                        this.player = savedRangedPlayer;
                        retargetEffectsToCurrentPlayer();
                    }
                }
            }

            sendSync();

            enemyTurnState = EnemyTurnState.DONE;
            enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            return;
        }

        // Wolf-style hit-and-run: attack, then use retreat path in the same turn.
        if (pendingAction instanceof EnemyAction.MoveAttackMove mam) {
            CombatEntity petTarget = (currentEnemyPetAggroTarget != null && currentEnemyPetAggroTarget.isAlive())
                ? currentEnemyPetAggroTarget : null;
            // Same MP melee-target fix as the main path below -pick the
            // closest party member instead of arena.getPlayerGridPos().
            ServerPlayerEntity mamTargetPlayer = petTarget != null
                ? null : findClosestPartyTarget(currentEnemy.getGridPos());
            GridPos targetPos = petTarget != null ? petTarget.getGridPos()
                : (mamTargetPlayer != null
                    ? gridPosOf(mamTargetPlayer)
                    : arena.getPlayerGridPos());
            int distToTarget = currentEnemy.minDistanceTo(targetPos);
            if (distToTarget <= 1) {
                int damage = (int)(mam.damage() * com.crackedgames.craftics.CrafticsMod.CONFIG.enemyDamageMultiplier());
                if (petTarget != null) {
                    // Checked inside the pet branch - see the ranged path's note.
                    if (!attackMisses(currentEnemy, petTarget)) {
                    // Addon combat effects: modify ally incoming damage
                    final CombatEntity mamPet = petTarget;
                    int mamHookedDmg = fireEffectHookChained(damage,
                        (h, d) -> h.onAllyTakeDamage(effectContext, mamPet, currentEnemy, d));
                    int actual = petTarget.takeDamage(mamHookedDmg);
                    sendMessage("§c" + currentEnemy.getDisplayName() + " hits "
                        + petTarget.getDisplayName() + " for " + actual + "!");
                    if (!petTarget.isAlive()) {
                        fireEffectHook(h -> h.onAllyDeath(effectContext, mamPet));
                    }
                    checkAndHandleDeath(petTarget);
                    } // end pet hit (skipped on a miss)
                } else {
                    ServerPlayerEntity savedMamPlayer = this.player;
                    boolean mamSwapped = mamTargetPlayer != null && mamTargetPlayer != savedMamPlayer;
                    if (mamSwapped) {
                        this.player = mamTargetPlayer;
                        retargetEffectsToCurrentPlayer();
                    }
                    boolean mamTargetDied = false;
                    try {
                        int actual = damagePlayer(damage, currentEnemy);
                        if (!lastHitAvoided) {
                        if (isFrostboundBossAttacker()) {
                            applyFrostboundSlownessOnHit();
                        }
                        player.getWorld().playSound(null, player.getBlockPos(),
                            net.minecraft.sound.SoundEvents.ENTITY_PLAYER_HURT,
                            net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 1.0f);
                        sendMessage("§c" + currentEnemy.getDisplayName() + " hits "
                            + (mamSwapped ? mamTargetPlayer.getName().getString() : "you")
                            + " for " + actual + "!");
                        applyEnemyHitEffect(currentEnemy.getEntityTypeId());
                        } // end on-hit effects (skipped on a fully avoided attack)
                        if (getPlayerHp() <= 0) {
                            sendSync();
                            mamTargetDied = true;
                            handlePlayerDeathOrGameOver();
                            return;
                        }
                    } finally {
                        if (!mamTargetDied) {
                            this.player = savedMamPlayer;
                            retargetEffectsToCurrentPlayer();
                        }
                    }
                }
            }

            // Continue turn with the retreat leg, if present.
            if (mam.retreatPath() != null && !mam.retreatPath().isEmpty()) {
                pendingAction = new EnemyAction.Move(mam.retreatPath());
                sendSync();
                startEnemyMove(mam.retreatPath());
                return;
            }

            sendSync();
            enemyTurnState = EnemyTurnState.DONE;
            enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            return;
        }

        CombatEntity petTarget = (currentEnemyPetAggroTarget != null && currentEnemyPetAggroTarget.isAlive())
            ? currentEnemyPetAggroTarget : null;
        // In MP the mob targeted whichever party member was closest at AI-decision
        // time; if we reuse `arena.getPlayerGridPos()` here it points at the
        // leader and the mob's just-completed walk-up "lands out of range" of the
        // leader-only target, so the attack silently skips and the player sees
        // the wind-up animation but takes no damage. Resolve the actual closest
        // member so the mob hits whoever it walked up to.
        ServerPlayerEntity meleeTargetPlayer = petTarget != null
            ? null : findClosestPartyTarget(currentEnemy.getGridPos());
        GridPos targetPos = petTarget != null ? petTarget.getGridPos()
            : (meleeTargetPlayer != null
                ? gridPosOf(meleeTargetPlayer)
                : arena.getPlayerGridPos());

        // Validate melee range -enemy must be adjacent to its chosen target to hit
        int distToTarget = currentEnemy.minDistanceTo(targetPos);
        if (distToTarget > 1) {
            // Not in range -skip attack
            enemyTurnState = EnemyTurnState.DONE;
            enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
            return;
        }

        // Determine damage and knockback
        int damage = 0;
        int knockbackTiles = 0;
        if (pendingAction instanceof EnemyAction.Attack atk) damage = atk.damage();
        else if (pendingAction instanceof EnemyAction.MoveAndAttack maa) damage = maa.damage();
        else if (pendingAction instanceof EnemyAction.AttackWithKnockback akb) {
            damage = akb.damage();
            knockbackTiles = akb.knockbackTiles();
        } else if (pendingAction instanceof EnemyAction.MoveAndAttackWithKnockback maakb) {
            damage = maakb.damage();
            knockbackTiles = maakb.knockbackTiles();
        }

        // Enemy weapon enchantment effects: read mob's mainhand and apply on-hit effects
        int enemySharp = 0;
        int enemyFireAspect = 0;
        int enemySmite = 0;
        int enemyBane = 0;
        if (currentEnemy != null && currentEnemy.getMobEntity() != null) {
            ItemStack enemyWeapon = currentEnemy.getMobEntity().getMainHandStack();
            if (!enemyWeapon.isEmpty()) {
                enemySharp = PlayerCombatStats.getEnchantLevel(enemyWeapon, "minecraft:sharpness");
                if (enemySharp > 0) damage += enemySharp;
                int enemyKb = PlayerCombatStats.getEnchantLevel(enemyWeapon, "minecraft:knockback");
                if (enemyKb > 0) knockbackTiles += enemyKb;
                enemyFireAspect = PlayerCombatStats.getEnchantLevel(enemyWeapon, "minecraft:fire_aspect");
                enemySmite = PlayerCombatStats.getEnchantLevel(enemyWeapon, "minecraft:smite");
                enemyBane = PlayerCombatStats.getEnchantLevel(enemyWeapon, "minecraft:bane_of_arthropods");
            }
        }
        // Smite/Bane bonus damage applies if the player counts as undead/arthropod (rare, but supported)
        // For PvE these mostly add flat damage instead since the player isn't undead/arthropod
        boolean enemyHasFireAspect = enemyFireAspect > 0;
        boolean enemyHasSharpness = enemySharp > 0;
        boolean enemyHasSmite = enemySmite > 0;
        boolean enemyHasBane = enemyBane > 0;

        damage = (int)(damage * com.crackedgames.craftics.CrafticsMod.CONFIG.enemyDamageMultiplier());
        if (petTarget != null) {
            // Checked inside the pet branch - see the ranged path's note.
            if (!attackMisses(currentEnemy, petTarget)) {
            // Addon combat effects: modify ally incoming damage
            final CombatEntity melPet = petTarget;
            int melHookedDmg = fireEffectHookChained(damage,
                (h, d) -> h.onAllyTakeDamage(effectContext, melPet, currentEnemy, d));
            int actual = petTarget.takeDamage(melHookedDmg);
            sendMessage("§c" + currentEnemy.getDisplayName() + " hits "
                + petTarget.getDisplayName() + " for " + actual + "!");
            if (!petTarget.isAlive()) {
                fireEffectHook(h -> h.onAllyDeath(effectContext, melPet));
            }
            checkAndHandleDeath(petTarget);
            } // end pet hit (skipped on a miss)
        } else {
            // Route the ENTIRE post-hit chain (damage, on-hit bleed/burn/poison
            // effects, smite extra hit, knockback, thorns/counter retaliation,
            // death check) to the actual melee target in MP by swapping
            // `this.player` for the whole block. Every getPlayerHp / armor /
            // shield / setHealth / addEffect call that runs inside reads from
            // the right player. The restore in finally only fires if the
            // target didn't die -handlePlayerDeathOrGameOver already
            // reassigns this.player to the next alive member on death.
            ServerPlayerEntity savedTurnPlayer = this.player;
            boolean swapped = meleeTargetPlayer != null && meleeTargetPlayer != savedTurnPlayer;
            if (swapped) {
                this.player = meleeTargetPlayer;
                retargetEffectsToCurrentPlayer();
            }
            boolean targetDied = false;
            try {
            int actual = damagePlayer(damage, currentEnemy);

            // On-hit side effects only fire if the attack actually connected. A fully
            // avoided hit (AC dodge / Ethereal / shield block / Gilded Guard) applies
            // NO hit sound, damage message, weapon debuffs, knockback, thorns, or
            // counters -the avoid feedback was already shown inside damagePlayer.
            if (!lastHitAvoided) {
            if (isFrostboundBossAttacker()) {
                applyFrostboundSlownessOnHit();
            }
            // Combat sound at the actual target's position
            player.getWorld().playSound(null, player.getBlockPos(),
                net.minecraft.sound.SoundEvents.ENTITY_PLAYER_HURT,
                net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 1.0f);

            sendMessage("§c" + currentEnemy.getDisplayName() + " hits "
                + (swapped ? meleeTargetPlayer.getName().getString() : "you")
                + " for " + actual + "!");
            applyEnemyHitEffect(currentEnemy.getEntityTypeId());

            // Modded mob weapon on-hit debuff: a mob swinging a registered modded weapon
            // applies a short player-facing debuff (katana -> bleed, poison sword ->
            // poison, ...). this.player is already the swapped victim here, and
            // addEffectHooked targets this.player, so the right player gets it.
            if (currentEnemy.getMobEntity() != null) {
                ItemStack mobWeapon = currentEnemy.getMobEntity().getMainHandStack();
                if (!mobWeapon.isEmpty()) {
                    net.minecraft.util.Identifier wid =
                        net.minecraft.registry.Registries.ITEM.getId(mobWeapon.getItem());
                    var debuff = com.crackedgames.craftics.combat.ModdedMobWeapons.onHitDebuff(
                        wid != null ? wid.getPath() : null);
                    if (debuff != null) {
                        boolean skipBurn = debuff.type() == CombatEffects.EffectType.BURNING
                            && combatEffects.hasFireResistance();
                        if (!skipBurn && addEffectHooked(debuff.type(), debuff.turns(), debuff.amplifier())) {
                            sendMessage("§5  " + currentEnemy.getDisplayName() + "'s "
                                + mobWeapon.getName().getString() + " afflicts you!");
                        }
                    }
                }
            }

            // Enemy weapon Sharpness: applies bleed stacks to the player (1 stack per level, 3 turn duration)
            if (enemyHasSharpness) {
                int bleedDuration = 3;
                addEffectHooked(CombatEffects.EffectType.BLEEDING, bleedDuration, enemySharp - 1);
                sendMessage("§4  Sharpened weapon causes Bleeding " + enemySharp + "! (-" + enemySharp + " HP/turn for " + bleedDuration + " turns)");
            }

            // Enemy weapon Fire Aspect: ignite the player AND nearby tiles in a cone
            if (enemyHasFireAspect && !combatEffects.hasFireResistance()) {
                int burnTurns = 2 + enemyFireAspect;
                addEffectHooked(CombatEffects.EffectType.BURNING, burnTurns, enemyFireAspect - 1);
                // Cone of flame: convert tiles in front of the player to fire (in the direction the enemy attacked from).
                // Anchor on the actual victim (this.player after the MP target swap), not the
                // last-acting player's arena tile, so the cone spawns around the player who was hit.
                GridPos pPosFa = gridPosOf(player);
                GridPos ePosFa = currentEnemy.getGridPos();
                int faDx = Integer.signum(pPosFa.x() - ePosFa.x());
                int faDz = Integer.signum(pPosFa.z() - ePosFa.z());
                if (faDx == 0 && faDz == 0) faDx = 1;
                int coneDepth = enemyFireAspect + 1; // Lv1 = 2 deep, Lv2 = 3 deep
                java.util.List<GridPos> coneTiles = new ArrayList<>();
                for (int depth = 1; depth <= coneDepth; depth++) {
                    int halfWidth = depth - 1;
                    for (int w = -halfWidth; w <= halfWidth; w++) {
                        int cx, cz;
                        if (faDz == 0) {
                            cx = pPosFa.x() + faDx * depth;
                            cz = pPosFa.z() + w;
                        } else if (faDx == 0) {
                            cx = pPosFa.x() + w;
                            cz = pPosFa.z() + faDz * depth;
                        } else {
                            cx = pPosFa.x() + faDx * depth;
                            cz = pPosFa.z() + faDz * depth + w;
                        }
                        GridPos cp = new GridPos(cx, cz);
                        if (arena.isInBounds(cp)) coneTiles.add(cp);
                    }
                }
                if (!coneTiles.isEmpty()) {
                    resolveCreateTerrain(new EnemyAction.CreateTerrain(coneTiles, TileType.FIRE, 2));
                }
                sendMessage("§6  Flaming weapon ignites you! Burning " + (enemyFireAspect) + " for " + burnTurns + " turns! Cone of flame erupts!");
            }

            // Enemy weapon Bane of Arthropods: poison + slow (applies regardless of player type)
            if (enemyHasBane) {
                addEffectHooked(CombatEffects.EffectType.POISON, 3, Math.max(0, enemyBane - 1));
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 2, 0);
                sendMessage("§2  Venomous strike! Poisoned and slowed!");
            }

            // Enemy weapon Smite: bonus damage spike (vs the player it's a flat extra hit)
            if (enemyHasSmite) {
                int smiteDmg = enemySmite * 2;
                int smiteActual = damagePlayer(smiteDmg, currentEnemy);
                sendMessage("§e  Holy radiance! Smite deals " + smiteActual + " bonus damage!");
                if (getPlayerHp() <= 0) {
                    sendSync();
                    targetDied = true;
                    handlePlayerDeathOrGameOver();
                    return;
                }
            }

            // Apply knockback to player
            if (knockbackTiles > 0) {
                applyPlayerKnockback(currentEnemy.getGridPos(), knockbackTiles, currentEnemy);
            }

            // Enemy armor Thorns: reflect damage from any armor piece with Thorns
            if (currentEnemy.getMobEntity() != null) {
                int totalEnemyThorns = 0;
                for (net.minecraft.entity.EquipmentSlot slot : new net.minecraft.entity.EquipmentSlot[]{
                        net.minecraft.entity.EquipmentSlot.HEAD, net.minecraft.entity.EquipmentSlot.CHEST,
                        net.minecraft.entity.EquipmentSlot.LEGS, net.minecraft.entity.EquipmentSlot.FEET}) {
                    ItemStack piece = currentEnemy.getMobEntity().getEquippedStack(slot);
                    if (!piece.isEmpty()) {
                        totalEnemyThorns += PlayerCombatStats.getEnchantLevel(piece, "minecraft:thorns");
                    }
                }
                if (totalEnemyThorns > 0 && Math.random() < 0.3) {
                    int thornsRetaliate = damagePlayer(totalEnemyThorns, currentEnemy);
                    sendMessage("§2  Enemy thorns reflects " + thornsRetaliate + " damage!");
                    if (getPlayerHp() <= 0) {
                        sendSync();
                        targetDied = true;
                        handlePlayerDeathOrGameOver();
                        return;
                    }
                }
            }

            // Thorns: reflect damage back to attacker (Luck boosts proc chance)
            int thornsLevel = PlayerCombatStats.getThorns(player);
            if (thornsLevel > 0) {
                int defLuck = PlayerProgression.get((ServerWorld) player.getEntityWorld())
                    .getStats(player).getPoints(PlayerProgression.Stat.LUCK);
                if (Math.random() < (thornsLevel * 0.15) + (defLuck * 0.02)) {
                    int thornsDmg = currentEnemy.takeDamage(thornsLevel);
                    sendMessage("\u00a72Thorns reflects " + thornsDmg + " damage!");
                }
            }

            // Physical affinity: counterattack chance when attacked (Luck boosts proc chance)
            // Triggers based on having PHYSICAL affinity points, regardless of weapon held
            if (currentEnemy.isAlive()) {
                PlayerProgression.PlayerStats pStats = PlayerProgression.get(
                    (ServerWorld) player.getEntityWorld()).getStats(player);
                int physPts = pStats.getAffinityPoints(PlayerProgression.Affinity.PHYSICAL);
                int physLuck = pStats.getPoints(PlayerProgression.Stat.LUCK);
                double counterChance = physPts * 0.03 + physLuck * 0.02; // 3% per affinity + 2% per luck
                if (counterChance > 0 && Math.random() < counterChance) {
                    int counterDmg = performCounterAttack(currentEnemy,
                        computeMeleeAttackDamage(player.getMainHandStack().getItem()));
                    sendMessage("\u00a77\u270A Counter! You strike back for " + counterDmg + " damage!");
                    if (!currentEnemy.isAlive()) {
                        achievementTracker.recordCounterKill();
                        killEnemy(currentEnemy);
                    }
                }
            }

            // Immovable hybrid: reflect a flat amount back at melee attackers.
            if (activeHybridEffect() == HybridEffect.IMMOVABLE && currentEnemy.isAlive()) {
                int reflected = performCounterAttack(currentEnemy, HybridSetEffects.IMMOVABLE_REFLECT);
                sendMessage("\u00a78\u26cf Immovable! " + currentEnemy.getDisplayName()
                    + " takes " + reflected + " reflected damage.");
                if (!currentEnemy.isAlive()) killEnemy(currentEnemy);
            }

            // Counterpuncher hybrid: a chance to immediately strike a melee attacker back.
            if (activeHybridEffect() == HybridEffect.COUNTERPUNCHER && currentEnemy.isAlive()
                    && Math.random() < HybridSetEffects.COUNTERPUNCH_CHANCE) {
                net.minecraft.item.Item counterWeapon = hybridLastWeapon != null
                    ? hybridLastWeapon : player.getMainHandStack().getItem();
                int counterDmg = performCounterAttack(currentEnemy,
                    computeMeleeAttackDamage(counterWeapon));
                sendMessage("\u00a7e\u270A Counterpuncher! You strike back for " + counterDmg + " damage!");
                if (!currentEnemy.isAlive()) {
                    achievementTracker.recordCounterKill();
                    killEnemy(currentEnemy);
                }
            }

            } // end on-hit side effects (skipped entirely on a fully avoided attack)

            if (getPlayerHp() <= 0) {
                sendSync();
                targetDied = true;
                handlePlayerDeathOrGameOver();
                return;
            }
            } finally {
                if (!targetDied) {
                    this.player = savedTurnPlayer;
                    retargetEffectsToCurrentPlayer();
                }
            }
        }

        sendSync();

        enemyTurnState = EnemyTurnState.DONE;
        enemyTurnDelay = CrafticsMod.CONFIG.enemyTurnDelay();
    }

    /**
     * Find a free tile adjacent to the given target for Warp Drive teleportation.
     * Prefers the tile closest to the player's current position so the warp feels
     * like a "leap" rather than a random scatter. Returns null if every adjacent
     * tile is blocked or out of bounds.
     */
    private GridPos findWarpAdjacentTile(CombatEntity target) {
        if (target == null || arena == null) return null;
        GridPos playerPos = arena.getPlayerGridPos();
        // Iterate every tile occupied by the target (handles multi-tile bosses) and
        // collect their 4-neighbour tiles. Score each candidate by manhattan distance
        // from the player, choose the closest valid one.
        java.util.List<GridPos> targetTiles = GridArena.getOccupiedTiles(target);
        GridPos best = null;
        int bestScore = Integer.MAX_VALUE;
        int[][] dirs = { {1,0}, {-1,0}, {0,1}, {0,-1} };
        for (GridPos t : targetTiles) {
            for (int[] d : dirs) {
                GridPos cand = new GridPos(t.x() + d[0], t.z() + d[1]);
                if (!arena.isInBounds(cand)) continue;
                if (arena.isOccupied(cand)) continue;
                GridTile tile = arena.getTile(cand);
                if (tile == null) continue;
                if (tile.getType() == com.crackedgames.craftics.core.TileType.OBSTACLE) continue;
                if (tile.getType() == com.crackedgames.craftics.core.TileType.VOID) continue;
                int score = playerPos.manhattanDistance(cand);
                if (score < bestScore) {
                    bestScore = score;
                    best = cand;
                }
            }
        }
        return best;
    }

    /** Get effective weapon range including trim ATTACK_RANGE bonus. */
    private int getEffectiveWeaponRange() {
        int range = PlayerCombatStats.getWeaponRange(player);
        // Crossbow rook pattern is special (a sentinel, not a literal range) -don't
        // apply flat range bonuses or vision penalties to it.
        if (range != PlayerCombatStats.RANGE_CROSSBOW_ROOK) {
            if (activeTrimScan != null) range += activeTrimScan.get(TrimEffects.Bonus.ATTACK_RANGE);
            // Airtime lofts your shots: +2 range per level, ranged weapons only.
            if (combatEffects.getAirtimeLevel() > 0) {
                Item heldWeapon = player.getMainHandStack().getItem();
                boolean rangedWeapon = PlayerCombatStats.isBowItem(heldWeapon)
                    || heldWeapon == Items.CROSSBOW;
                if (rangedWeapon) range += 2 * combatEffects.getAirtimeLevel();
            }
            // Blindness (-2/level) shrinks attack range, floored to 1. (Darkness
            // is now a client-side fog of war, not a range shave - see CombatState.)
            int visionPenalty = combatEffects.getBlindnessPenalty();
            if (visionPenalty > 0) range = Math.max(1, range - visionPenalty);
        }
        return range;
    }

    /** OVERWATCH set bonus: counter-attack a ranged enemy that hit the player. */
    private void checkOverwatchCounter(CombatEntity attacker) {
        if (attacker == null || !attacker.isAlive()) return;
        if (activeTrimScan == null || activeTrimScan.setBonus() != TrimEffects.SetBonus.OVERWATCH) return;
        int counterDmg = attacker.takeDamage(PlayerCombatStats.getAttackPower(player));
        sendMessage("§c§l✦ Overwatch! §r§cCounter-shot for " + counterDmg + " damage!");
        if (!attacker.isAlive()) {
            checkAndHandleDeath(attacker);
        }
    }

    /** Scaffold range bonus: +1 range if player is standing on a scaffold tile. */
    private int getScaffoldRangeBonus(GridPos pos) {
        String effect = tileEffects.get(pos);
        return "scaffold".equals(effect) ? 1 : 0;
    }

    private void applyPlayerKnockback(GridPos attackerPos, int tiles) {
        applyPlayerKnockback(attackerPos, tiles, null);
    }

    /**
     * Wind Burst recoil: the mace's shockwave throws the swinger around as well as the
     * enemies. Grants Airtime at the enchant's level for one turn and shoves the player a
     * single tile in a random direction.
     *
     * <p>This does NOT reuse {@link #applyPlayerKnockback(GridPos, int)}. That routine is
     * for being hit BY something: it lands the player on hazards and applies their
     * consequences, so a recoil through it could drop you in the void or deep water for a
     * guaranteed kill - dying to your own successful swing on a 1-in-4 roll. Your own
     * shockwave shouldn't be able to kill you, so this shove refuses any tile that isn't
     * plainly safe and simply doesn't move you when every side is blocked.
     *
     * <p>Airtime is raised, never lowered: {@code addEffect} overwrites the amplifier, so
     * re-granting a flat level would downgrade a bigger stack built from wind charges or an
     * Elytra launch.
     */
    private void applyWindBurstRecoil(int windBurstLevel) {
        if (windBurstLevel <= 0 || arena == null || player == null) return;

        // Airtime at the enchant's level (level N -> amplifier N-1), one turn, capped.
        // Never downgrade an existing, higher stack.
        int wantAmp = Math.min(windBurstLevel - 1, CombatEffects.AIRTIME_MAX_AMPLIFIER);
        int haveAmp = Math.max(0, combatEffects.getAirtimeLevel() - 1);
        combatEffects.addEffect(CombatEffects.EffectType.AIRTIME, 1, Math.max(wantAmp, haveAmp));

        // Shove one tile to a random side, skipping anything unsafe. Directions are tried in
        // a random order so a blocked roll still moves you when some other side is open.
        GridPos from = gridPosOf(player);
        java.util.List<int[]> dirs = new java.util.ArrayList<>(java.util.List.of(
            new int[]{1, 0}, new int[]{-1, 0}, new int[]{0, 1}, new int[]{0, -1}));
        java.util.Collections.shuffle(dirs, new java.util.Random(player.getRandom().nextLong()));

        boolean moved = false;
        for (int[] d : dirs) {
            GridPos to = new GridPos(from.x() + d[0], from.z() + d[1]);
            if (!arena.isInBounds(to) || arena.isEnemyOccupied(to)) continue;
            var tile = arena.getTile(to);
            if (tile == null || !isSafeRecoilTile(tile)) continue;
            arena.setPlayerGridPos(to);
            BlockPos bp = arena.gridToBlockPos(to);
            player.requestTeleport(bp.getX() + 0.5, arena.getEntityY(to, false), bp.getZ() + 0.5);
            moved = true;
            break;
        }

        sendMessage("§b✦ Wind Burst recoil! §f" + (moved ? "You're blown a tile" : "You brace against the blast")
            + " and land in §bAirtime " + Math.max(windBurstLevel, combatEffects.getAirtimeLevel())
            + "§f (1 turn).");
    }

    /**
     * A tile the Wind Burst recoil may drop the player on: somewhere they'd walk anyway, that
     * won't hurt them. Excludes water and powder snow, which are walkable but carry their own
     * consequences (Soaked / freezing) that a self-inflicted recoil shouldn't impose.
     */
    private static boolean isSafeRecoilTile(GridTile tile) {
        com.crackedgames.craftics.core.TileType t = tile.getType();
        if (!t.walkable || t.requiresBoat || t.damageOnStep > 0) return false;
        return t != com.crackedgames.craftics.core.TileType.WATER
            && t != com.crackedgames.craftics.core.TileType.POWDER_SNOW;
    }

    /**
     * Shove the player off a tile perpendicular to a dash direction (used by the
     * Artifacts mimic dash). Damages the player and tries to push them 1 tile
     * sideways. If both perpendicular tiles are blocked, falls back to a 1-tile
     * shove backwards along the dash direction.
     */
    private void shovePlayerAside(GridPos onTile, int dirX, int dirZ, int damage, CombatEntity source) {
        int actual = damagePlayer(damage, source);
        sendMessage("§c  " + (source != null ? source.getDisplayName() : "Mimic") + " slams into you for " + actual + " damage!");
        // Compute perpendicular direction(s) -for an X dash, perpendicular is Z and vice versa.
        int[][] sidewaysOptions;
        if (dirX != 0) {
            sidewaysOptions = new int[][] { {0, 1}, {0, -1}, {-dirX, 0} };
        } else {
            sidewaysOptions = new int[][] { {1, 0}, {-1, 0}, {0, -dirZ} };
        }
        for (int[] off : sidewaysOptions) {
            GridPos dest = new GridPos(onTile.x() + off[0], onTile.z() + off[1]);
            if (!arena.isInBounds(dest)) continue;
            if (arena.isOccupied(dest)) continue;
            GridTile t = arena.getTile(dest);
            if (t == null) continue;
            if (t.getType() == com.crackedgames.craftics.core.TileType.OBSTACLE) continue;
            if (t.getType() == com.crackedgames.craftics.core.TileType.VOID) continue;
            arena.setPlayerGridPos(dest);
            BlockPos shoveBlock = arena.gridToBlockPos(dest);
            //? if <=1.21.1 {
            player.teleport((ServerWorld) player.getEntityWorld(),
                shoveBlock.getX() + 0.5, shoveBlock.getY(), shoveBlock.getZ() + 0.5,
                java.util.Collections.emptySet(), player.getYaw(), 0f);
            //?} else {
            /*player.teleport((ServerWorld) player.getEntityWorld(),
                shoveBlock.getX() + 0.5, shoveBlock.getY(), shoveBlock.getZ() + 0.5,
                java.util.Collections.emptySet(), player.getYaw(), 0f, true);
            *///?}
            return;
        }
    }

    /**
     * Shove a non-player entity off a tile (mimic dash collision).
     * Tries perpendicular tiles first, then falls back to backwards.
     */
    private void shoveEntityAside(CombatEntity occupant, GridPos onTile, int dirX, int dirZ, int damage) {
        int dealt = occupant.takeDamage(damage);
        sendMessage("§c  Slams into " + occupant.getDisplayName() + " for " + dealt + " damage!");
        int[][] sidewaysOptions;
        if (dirX != 0) {
            sidewaysOptions = new int[][] { {0, 1}, {0, -1}, {-dirX, 0} };
        } else {
            sidewaysOptions = new int[][] { {1, 0}, {-1, 0}, {0, -dirZ} };
        }
        for (int[] off : sidewaysOptions) {
            GridPos dest = new GridPos(onTile.x() + off[0], onTile.z() + off[1]);
            if (!arena.isInBounds(dest)) continue;
            if (arena.isOccupied(dest)) continue;
            GridTile t = arena.getTile(dest);
            if (t == null) continue;
            if (t.getType() == com.crackedgames.craftics.core.TileType.OBSTACLE) continue;
            arena.moveEntity(occupant, dest);
            MobEntity mob = occupant.getMobEntity();
            if (mob != null) {
                BlockPos shoveBlock = arena.gridToBlockPos(dest);
                mob.requestTeleport(shoveBlock.getX() + 0.5,
                    arena.getEntityY(dest, occupant.isFlying()),
                    shoveBlock.getZ() + 0.5);
            }
            return;
        }
        if (!occupant.isAlive()) checkAndHandleDeath(occupant);
    }

    /**
     * Prismarine armor's guardian beam. At the start of the wearer's turn every live
     * enemy standing within {@link ArmorSetEffects#PRISMARINE_RADIUS} tiles takes Water
     * damage and is Soaked. Mob Water resistances still apply, so a drowned shrugs it
     * off the same way it shrugs off a trident.
     */
    private void applyPrismarineDischarge(ServerPlayerEntity wearer) {
        if (arena == null || wearer == null) return;
        GridPos wearerPos = gridPosOf(wearer);
        if (wearerPos == null) return;

        int zapped = 0;
        for (CombatEntity enemy : new java.util.ArrayList<>(enemies)) {
            if (!enemy.isAlive() || enemy.isAlly()) continue;
            if (enemy.minDistanceTo(wearerPos) > ArmorSetEffects.PRISMARINE_RADIUS) continue;

            int dealt = enemy.takeDamage(MobResistances.applyResistance(
                enemy.getEntityTypeId(), DamageType.WATER, ArmorSetEffects.PRISMARINE_DAMAGE));
            if (dealt <= 0) continue;
            enemy.stackSoaked(ArmorSetEffects.PRISMARINE_SOAK_TURNS, 1);
            zapped++;
            achievementTracker.recordPlayerDealtDamage();

            if (wearer.getEntityWorld() instanceof ServerWorld world) {
                ProjectileSpawner.spawnSpellTrail(world,
                    arena.gridToBlockPos(wearerPos), arena.gridToBlockPos(enemy.getGridPos()),
                    net.minecraft.particle.ParticleTypes.BUBBLE,
                    net.minecraft.particle.ParticleTypes.SPLASH, 12, 0.2);
            }
            sendMessage("§3✦ Prismarine beam hits " + enemy.getDisplayName()
                + " for " + dealt + " and soaks it!");
            checkAndHandleDeath(enemy);
        }
        if (zapped > 0 && wearer.getEntityWorld() instanceof ServerWorld world) {
            world.playSound(null, wearer.getBlockPos(),
                net.minecraft.sound.SoundEvents.ENTITY_GUARDIAN_ATTACK,
                net.minecraft.sound.SoundCategory.PLAYERS, 0.8f, 1.2f);
        }
    }

    /**
     * Wooden and Bone armor are brittle: every worn piece of the set independently
     * risks shattering when its wearer is struck. A piece that shatters is destroyed
     * outright, not merely damaged - the set trades durability for its other perks.
     * Luck steadies the gear, shaving the roll down without ever making it safe.
     */
    private void applyFragileArmorBreak() {
        if (player == null) return;
        double breakChance = ArmorSetEffects.fragileBreakChance(
            PlayerCombatStats.getArmorSet(player), luckPointsOf(player));
        if (breakChance <= 0) return;
        for (net.minecraft.entity.EquipmentSlot slot : new net.minecraft.entity.EquipmentSlot[]{
                net.minecraft.entity.EquipmentSlot.HEAD, net.minecraft.entity.EquipmentSlot.CHEST,
                net.minecraft.entity.EquipmentSlot.LEGS, net.minecraft.entity.EquipmentSlot.FEET}) {
            ItemStack piece = player.getEquippedStack(slot);
            if (piece.isEmpty()) continue;
            if (Math.random() >= breakChance) continue;
            String name = piece.getName().getString();
            player.equipStack(slot, ItemStack.EMPTY);
            sendMessage("§c§l✦ SHATTERED! §r§7Your " + name + " breaks apart.");
            player.getWorld().playSound(null, player.getBlockPos(),
                net.minecraft.sound.SoundEvents.BLOCK_GLASS_BREAK,
                net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 0.8f);
        }
    }

    /** Wither armor: whatever strikes the wearer in melee starts to rot. */
    private void applyWitherRetaliation(CombatEntity attacker) {
        if (player == null || attacker == null || !attacker.isAlive()) return;
        int turns = ArmorSetEffects.witherRetaliationTurns(PlayerCombatStats.getArmorSet(player));
        if (turns <= 0) return;
        // Only a melee attacker touches the armor; an archer across the arena does not.
        if (attacker.minDistanceTo(gridPosOf(player)) > 1) return;
        attacker.stackWither(turns, 0);
        sendMessage("§8✦ Wither armor: §7" + attacker.getDisplayName() + " begins to rot.");
    }

    /** Slime armor: the wearer's own hits bounce their target away. */
    private void applySlimeAttackKnockback(CombatEntity target) {
        if (player == null || target == null || !target.isAlive() || arena == null) return;
        int tiles = ArmorSetEffects.contactKnockbackTiles(PlayerCombatStats.getArmorSet(player));
        if (tiles <= 0) return;
        GridPos pPos = gridPosOf(player);
        GridPos tPos = target.getGridPos();
        int dx = Integer.signum(tPos.x() - pPos.x());
        int dz = Integer.signum(tPos.z() - pPos.z());
        if (dx == 0 && dz == 0) return;
        knockEnemyBack(target, dx, dz, tiles);
        sendMessage("§a✦ Slime armor: §7" + target.getDisplayName() + " bounces away.");
    }

    /** Slime armor: the blow bounces. Both parties are shoved a tile apart. */
    private void applySlimeContactKnockback(CombatEntity attacker) {
        if (player == null || attacker == null || !attacker.isAlive() || arena == null) return;
        int tiles = ArmorSetEffects.contactKnockbackTiles(PlayerCombatStats.getArmorSet(player));
        if (tiles <= 0) return;
        if (attacker.minDistanceTo(gridPosOf(player)) > 1) return; // only contact bounces

        GridPos pPos = gridPosOf(player);
        GridPos aPos = attacker.getGridPos();
        knockEnemyBack(attacker,
            Integer.signum(aPos.x() - pPos.x()), Integer.signum(aPos.z() - pPos.z()), tiles);
        applyPlayerKnockback(aPos, tiles, attacker);
        sendMessage("§a✦ Slime armor: §7the blow bounces you both apart.");
    }

    /**
     * True if the live world has a solid, collidable floor under this tile - an entity placed
     * here would stand, not fall.
     *
     * <p>Used to sanity-check a tile the arena scan typed {@code VOID} before applying an
     * instant-death. A VOID-typed tile with a real block beneath it is a MIS-CLASSIFICATION
     * (the schematic floor sat at a different Y than the sampled level, so the scan saw air and
     * called it a pit), and the player - who sees solid ground - must not be void-killed for
     * standing on it. A genuine pit has air laid at the floor, so this returns false for those
     * and the lethal path still runs.
     */
    /**
     * True when the live world can actually hold someone standing on this tile.
     *
     * <p>Two legal footings: a surface at the arena floor (NORMAL and every hazard type that
     * stands at floor height) or one block down (LOW_GROUND). Fluids count - water and lava tiles
     * are walkable-with-consequences, not holes - and so does anything the tile scan would accept
     * as a standing surface, which keeps this in agreement with
     * {@code WallBlocks#providesStandingSurface} and with the classification in ArenaBuilder.
     */
    private boolean worldSupportsStanding(GridPos pos) {
        if (arena == null || pos == null) return true;   // no arena to check against - allow
        if (!(player.getEntityWorld() instanceof ServerWorld sw)) return true;
        BlockPos floor = arena.gridToBlockPos(pos).down();   // the floor BLOCK, not the feet
        BlockPos below = floor.down();
        return supportsOrFluid(sw, floor) || supportsOrFluid(sw, below);
    }

    private boolean supportsOrFluid(ServerWorld sw, BlockPos pos) {
        net.minecraft.block.BlockState state = sw.getBlockState(pos);
        if (!state.getFluidState().isEmpty()) return true;   // water/lava tiles are their own type
        return WallBlocks.providesStandingSurface(state, sw, pos);
    }

    private boolean hasSolidFloorAt(GridPos pos) {
        if (arena == null || !(player.getEntityWorld() instanceof ServerWorld sw)) return false;
        BlockPos stand = arena.gridToBlockPos(pos); // feet at origin.getY() + 1
        // Scan only the standing block and the floor block below it ([origin.getY(),
        // origin.getY()+1]). The build-time scan types a tile VOID off a single sampled floor
        // level, so it MISSES a walkable surface that sits a step above - the raised temple
        // floor beside a pillar is the classic case; a solid block at foot/floor level here
        // means the entity lands instead of plummeting, so it is not a death pit.
        //
        // Do NOT scan down to origin.getY()-2: every real pit is capped with BLACK_CONCRETE at
        // exactly floorY-2 (see ArenaBuilder.placePitObstacles / digVoidPit), so a -2 window hit
        // that cap on EVERY genuine pit and wrongly suppressed the fall death (regression). A
        // real pit is air at floorY and floorY-1, so this narrower window still returns false
        // for it, keeping it lethal.
        int bottom = arena.getOrigin().getY();
        for (int y = stand.getY(); y >= bottom; y--) {
            BlockPos p = new BlockPos(stand.getX(), y, stand.getZ());
            if (!sw.getBlockState(p).getCollisionShape(sw, p).isEmpty()) return true;
        }
        return false;
    }

    /**
     * Move a player who SURVIVED a void/drown knockback (via a totem) off the hazard tile and
     * onto solid ground.
     *
     * <p>A survivor left standing on a genuine void tile - whose floor is air - falls through
     * and trips the per-tick fall-death check on the very next tick, dying for real with the
     * totem already spent. Mirrors the rescue the movement void-fall path performs.
     */
    /**
     * Ledgegrip boots: once per combat, a knockback that would drop the player into a lethal
     * hazard becomes a caught edge - a small scrape and a scramble back to safe ground
     * instead of the fall. Returns true when the catch fired (the caller skips the lethal
     * branch entirely).
     */
    private boolean tryLedgegrip(String hazardName, CombatEntity source) {
        if (CrafticsEnchantments.wornLevel(player, CrafticsEnchantments.LEDGEGRIP) <= 0) return false;
        if (!ledgegripUsed.add(player.getUuid())) return false;
        damagePlayer(SwordAxeEnchantEffects.LEDGEGRIP_DAMAGE, source);
        sendMessage("§6Ledgegrip! You catch the edge of " + hazardName
            + " and haul yourself back up!");
        if (getPlayerHp() > 0) rescueSurvivorToSafeTile();
        return true;
    }

    private void rescueSurvivorToSafeTile() {
        GridPos safeGrid = getSafeArenaGridPos(arena);
        BlockPos safePos = safeGrid != null
            ? arena.gridToBlockPos(safeGrid) : arena.getPlayerStartBlockPos();
        if (safeGrid != null) arena.setPlayerGridPos(safeGrid);
        if (safePos != null) {
            player.requestTeleport(safePos.getX() + 0.5, safePos.getY(), safePos.getZ() + 0.5);
            broadcastPlayerPositionToOthers(player);
        }
        player.setVelocity(0, 0, 0);
        player.velocityModified = true;
        player.fallDistance = 0;
        refreshHighlights();
        sendSync();
    }

    /**
     * Knock the player back N tiles away from the attacker position.
     */
    private void applyPlayerKnockback(GridPos attackerPos, int tiles, CombatEntity source) {
        // Immovable hybrid: the player cannot be knocked back at all.
        if (activeHybridEffect() == HybridEffect.IMMOVABLE) {
            sendMessage("§8⛏ Immovable -you don't budge.");
            return;
        }
        // Heavy armor: too much plate to shift.
        if (ArmorSetEffects.ignoresKnockback(PlayerCombatStats.getArmorSet(player))) {
            sendMessage("§8⛨ Heavy armor -the blow doesn't move you.");
            return;
        }
        // Slow Falling: the player resists knockback (floats in place).
        if (combatEffects.hasSlowFalling()) {
            sendMessage("§f☁ Slow Falling -you drift, unmoved by the blow.");
            return;
        }
        // Addon combat effects: modify knockback distance
        tiles = fireEffectHookChained(tiles, (h, d) -> h.onKnockback(effectContext, source, d));
        if (tiles <= 0) return;

        // Read THIS.PLAYER's actual position, not arena.getPlayerGridPos(). The
        // arena tracker only ever holds one position -whoever took the last
        // player turn -so in MP a mob knocking back the host would compute
        // the "from" tile as player 2's stale spot and teleport the host
        // across the arena to land near player 2. gridPosOf walks the player's
        // real block pos through the arena origin instead.
        GridPos playerGridPos = gridPosOf(player);
        int dx = Integer.signum(playerGridPos.x() - attackerPos.x());
        int dz = Integer.signum(playerGridPos.z() - attackerPos.z());
        if (dx == 0 && dz == 0) dx = 1; // default direction

        GridPos landingPos = playerGridPos;
        boolean hitHazard = false;
        boolean hitCactus = false;
        for (int i = 1; i <= tiles; i++) {
            GridPos candidate = new GridPos(playerGridPos.x() + dx * i, playerGridPos.z() + dz * i);
            if (!arena.isInBounds(candidate) || arena.isEnemyOccupied(candidate)) break;
            var tile = arena.getTile(candidate);
            if (tile == null) break;

            // Solid obstacles block knockback -check for cactus
            if (tile.getType() == com.crackedgames.craftics.core.TileType.OBSTACLE) {
                if (tile.getBlockType() == Blocks.CACTUS) hitCactus = true;
                break;
            }

            // Hazard tiles: land ON them, then take consequences
            if (tile.getType() == com.crackedgames.craftics.core.TileType.VOID
                || tile.getType() == com.crackedgames.craftics.core.TileType.DEEP_WATER
                || tile.getType() == com.crackedgames.craftics.core.TileType.WATER
                || tile.getType() == com.crackedgames.craftics.core.TileType.LAVA) {
                // A tile typed VOID but with a real floor beneath it in the live world is a
                // mis-classified tile, not a pit: the player sees solid ground and would not
                // fall, so treat it as normal footing rather than an instant-death hazard.
                if (tile.getType() == com.crackedgames.craftics.core.TileType.VOID
                        && hasSolidFloorAt(candidate)) {
                    landingPos = candidate;
                    continue;
                }
                landingPos = candidate;
                hitHazard = true;
                break;
            }

            landingPos = candidate;
        }

        // Cactus collision damage -fires even if player didn't move (adjacent slam)
        if (hitCactus) {
            int cactusDmg = damagePlayerFromTile(2, source);
            sendMessage("§2  Slammed into a cactus for " + cactusDmg + " damage!");
            if (getPlayerHp() <= 0) {
                sendSync();
                handlePlayerDeathOrGameOver();
                return;
            }
        }

        if (!landingPos.equals(playerGridPos)) {
            arena.setPlayerGridPos(landingPos);
            BlockPos bp = arena.gridToBlockPos(landingPos);
            double kbY = (boatOf(player) != null) ? bp.getY() : arena.getEntityY(landingPos);
            player.requestTeleport(bp.getX() + 0.5, kbY, bp.getZ() + 0.5);
            broadcastPlayerPositionToOthers(player);
            sendMessage("§e  Knocked back " + playerGridPos.manhattanDistance(landingPos) + " tiles!");

            if (hitHazard) {
                var hazardTile = arena.getTile(landingPos);
                if (hazardTile != null) {
                    switch (hazardTile.getType()) {
                        case VOID -> {
                            if (tryLedgegrip("the pit", source)) break;
                            damagePlayer((int) player.getHealth() + 10, source);
                            sendMessage("§4  Fell into the void!");
                            // Survived (a totem fired inside damagePlayer): don't leave them
                            // standing on the void tile or they fall through and the per-tick
                            // fall-death check kills them for real next tick, totem already spent.
                            if (getPlayerHp() > 0) rescueSurvivorToSafeTile();
                        }
                        case DEEP_WATER -> {
                            if (playerHasBoat()) {
                                consumeBoat();
                                addEffectHooked(CombatEffects.EffectType.SOAKED, 2, 0);
                                sendMessage("§b  Your boat saves you from drowning! Soaked for 2 turns.");
                            } else if (tryLedgegrip("the deep water", source)) {
                                // caught the edge - nothing more to resolve
                            } else {
                                damagePlayer((int) player.getHealth() + 10, source);
                                sendMessage("§1  Drowned in deep water!");
                                if (getPlayerHp() > 0) rescueSurvivorToSafeTile();
                            }
                        }
                        case LAVA -> {
                            if (!combatEffects.hasFireResistance()) {
                                int lavaDmg = damagePlayerFromTile(10, source);
                                sendMessage("§6  Knocked into lava for " + lavaDmg + " damage!");
                            } else {
                                sendMessage("§6  Knocked into lava, but the heat washes over you!");
                            }
                        }
                        case WATER -> {
                            if (player.getEquippedStack(net.minecraft.entity.EquipmentSlot.HEAD).getItem() != Items.TURTLE_HELMET) {
                                addEffectHooked(CombatEffects.EffectType.SOAKED, 2, 0);
                                sendMessage("§b  Splashed into water! Soaked for 2 turns.");
                            }
                        }
                        default -> {}
                    }
                    if (getPlayerHp() <= 0) {
                        sendSync();
                        handlePlayerDeathOrGameOver();
                    }
                }
            }
        }
    }

    /**
     * Breeze wind charge: punt the player 2 tiles away from the breeze, then
     * blow every entity adjacent to the player's new position 2 tiles further
     * outward. Stops early on walls, obstacles, occupants, or hazards.
     */
    private void applyWindChargeKnockback(CombatEntity breeze) {
        if (breeze == null) return;
        GridPos breezePos = breeze.getGridPos();
        // Read the actual victim's tile, not arena.getPlayerGridPos() -that
        // arena tracker only holds the last-turn-player's pos, so in MP the
        // knockback's "from" tile would point at the wrong player and the
        // landing candidates would compute from there. With gridPosOf the
        // wind charge actually launches the player who got hit by it.
        GridPos playerStart = gridPosOf(player);
        int pdx = Integer.signum(playerStart.x() - breezePos.x());
        int pdz = Integer.signum(playerStart.z() - breezePos.z());
        if (pdx == 0 && pdz == 0) { pdx = 1; }

        GridPos playerLanding = playerStart;
        for (int i = 1; i <= 2; i++) {
            GridPos candidate = new GridPos(playerStart.x() + pdx * i, playerStart.z() + pdz * i);
            if (!arena.isInBounds(candidate) || arena.isOccupied(candidate)) break;
            GridTile tile = arena.getTile(candidate);
            if (tile == null || !tile.isWalkable()) break;
            playerLanding = candidate;
        }
        if (!playerLanding.equals(playerStart)) {
            arena.setPlayerGridPos(playerLanding);
            BlockPos bp = arena.gridToBlockPos(playerLanding);
            player.requestTeleport(bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5);
            broadcastPlayerPositionToOthers(player);
        }

        // Push every entity adjacent to the player's new position 2 tiles
        // outward (away from the player). Diagonals included so the gust
        // radiates in all 8 directions.
        java.util.List<CombatEntity> nearby = new java.util.ArrayList<>();
        for (CombatEntity e : enemies) {
            if (e == null || !e.isAlive() || e == breeze) continue;
            GridPos epos = e.getGridPos();
            int dx = epos.x() - playerLanding.x();
            int dz = epos.z() - playerLanding.z();
            if (Math.abs(dx) <= 1 && Math.abs(dz) <= 1 && !(dx == 0 && dz == 0)) {
                nearby.add(e);
            }
        }
        for (CombatEntity e : nearby) {
            GridPos epos = e.getGridPos();
            int dx = Integer.signum(epos.x() - playerLanding.x());
            int dz = Integer.signum(epos.z() - playerLanding.z());
            if (dx == 0 && dz == 0) continue;
            knockEnemyBack(e, dx, dz, 2);
        }
    }

    /**
     * Knock an enemy back, allowing them to land on hazard tiles (void/lava/water).
     * Returns the final landing position.
     */
    private GridPos knockEnemyBack(CombatEntity enemy, int dx, int dz, int tiles) {
        // Crater enchant: knockback the player causes flies 1 tile further, and slamming into
        // anything hurts and Stuns. Gated on the PLAYER_TURN phase so an enemy-driven push (the
        // breeze's wind gust fires this same routine on its own turn) is never boosted just
        // because a Crater weapon happens to be in the player's hand; within the player's turn
        // the heldLevel check keeps it to pushes made with the blunt weapon actually held.
        boolean crater = phase == CombatPhase.PLAYER_TURN
            && CrafticsEnchantments.heldLevel(player, CrafticsEnchantments.CRATER) > 0;
        if (crater) tiles += SwordAxeEnchantEffects.CRATER_EXTRA_TILES;

        GridPos startPos = enemy.getGridPos();
        int sizeX = enemy.getSizeX();
        int sizeZ = enemy.getSizeZ();
        GridPos landingPos = startPos;
        boolean hitHazard = false;
        boolean hitCactus = false;
        boolean hitWall = false;
        String wallLabel = "wall";

        // Iterate the push 1 tile at a time. For multi-tile entities we have
        // to check the FULL footprint at each candidate -the old single-tile
        // check let a 2x2 spider land on a small mob because only the
        // top-left corner of the destination got validated, sharing the other
        // three footprint tiles with whoever was already there.
        for (int i = 1; i <= tiles; i++) {
            GridPos candidate = new GridPos(startPos.x() + dx * i, startPos.z() + dz * i);

            boolean candidateHazard = false;
            boolean candidateWall = false;
            boolean candidateCactus = false;
            boolean candidateEdgeVoid = false;
            for (int fx = 0; fx < sizeX && !candidateWall && !candidateEdgeVoid; fx++) {
                for (int fz = 0; fz < sizeZ; fz++) {
                    GridPos fp = new GridPos(candidate.x() + fx, candidate.z() + fz);

                    if (!arena.isInBounds(fp)) {
                        // Pushed off the arena edge into the surrounding void. A
                        // non-immune mob falls to its death (there's no tile to
                        // land on out here); a hazard-immune boss just stops at
                        // the wall as before.
                        if (!enemy.isHazardImmune()) {
                            candidateEdgeVoid = true;
                            break;
                        }
                        candidateWall = true;
                        wallLabel = "arena wall";
                        break;
                    }
                    CombatEntity occ = arena.getOccupant(fp);
                    if (occ != null && occ != enemy && !occ.isBackgroundBoss()) {
                        candidateWall = true;
                        wallLabel = "another enemy";
                        break;
                    }
                    if (fp.equals(arena.getPlayerGridPos())) {
                        candidateWall = true;
                        wallLabel = "the player";
                        break;
                    }
                    for (GridPos pp : arena.getAllPlayerGridPositions()) {
                        if (fp.equals(pp)) { candidateWall = true; wallLabel = "the player"; break; }
                    }
                    if (candidateWall) break;
                    var tile = arena.getTile(fp);
                    if (tile == null) { candidateWall = true; break; }

                    if (tile.getType() == com.crackedgames.craftics.core.TileType.OBSTACLE) {
                        if (tile.getBlockType() == Blocks.CACTUS) {
                            candidateCactus = true;
                        } else {
                            candidateWall = true;
                            wallLabel = "obstacle";
                            break;
                        }
                        continue;
                    }

                    // Sink/hazard tiles the mob is shoved INTO (and affected by),
                    // not stopped in front of. Matches GridArena.getEntityY's sink
                    // set so the mob both visually drops AND takes the tile's
                    // effect: VOID (fall to death), DEEP_WATER (drown), WATER
                    // (soak), LAVA (burn), POWDER_SNOW (freeze), LOW_GROUND (a
                    // sunken pit - lands one level down). A hazard-immune mob (a
                    // boss) treats them as a wall and stops at the edge instead.
                    TileType tt = tile.getType();
                    if (tt == com.crackedgames.craftics.core.TileType.VOID
                        || tt == com.crackedgames.craftics.core.TileType.DEEP_WATER
                        || tt == com.crackedgames.craftics.core.TileType.WATER
                        || tt == com.crackedgames.craftics.core.TileType.LAVA
                        || tt == com.crackedgames.craftics.core.TileType.POWDER_SNOW
                        || tt == com.crackedgames.craftics.core.TileType.LOW_GROUND) {
                        if (enemy.isHazardImmune()) {
                            candidateWall = true;
                            wallLabel = "hazard edge";
                            break;
                        }
                        candidateHazard = true;
                        continue;
                    }

                    if (!tile.isWalkable()) {
                        candidateWall = true;
                        wallLabel = "terrain";
                        break;
                    }
                }
            }

            if (candidateEdgeVoid) {
                // Shoved clean off the arena edge. There's no tile out there to
                // move onto, so fling the mob toward the edge visually and kill
                // it outright - a void fall, same fate as an in-arena VOID tile.
                ServerWorld voidWorld = (ServerWorld) player.getEntityWorld();
                if (enemy.getMobEntity() != null) {
                    BlockPos edgeBp = arena.gridToBlockPos(candidate);
                    enemy.getMobEntity().requestTeleport(
                        edgeBp.getX() + 0.5, edgeBp.getY() - 3.0, edgeBp.getZ() + 0.5);
                    voidWorld.spawnParticles(net.minecraft.particle.ParticleTypes.PORTAL,
                        edgeBp.getX() + 0.5, edgeBp.getY(), edgeBp.getZ() + 0.5, 20, 0.4, 0.4, 0.4, 0.3);
                }
                enemy.takeDamage(enemy.getCurrentHp() + 100);
                sendMessage("§4" + enemy.getDisplayName() + " is knocked off the edge into the void!");
                killEnemy(enemy);
                return startPos;
            }

            if (candidateWall) {
                hitWall = true;
                if (candidateCactus) hitCactus = true;
                break;
            }
            if (candidateCactus) hitCactus = true;
            if (candidateHazard) {
                landingPos = candidate;
                hitHazard = true;
                break;
            }
            landingPos = candidate;
        }

        // Cactus collision damage -cactus has its own fixed-damage effect that fires
        // even if the enemy didn't move at all (adjacent slam).
        if (hitCactus) {
            int cactusDmg = enemy.takeDamage(2);
            sendMessage("§2" + enemy.getDisplayName() + " slammed into a cactus for " + cactusDmg + " damage!");
            if (!enemy.isAlive()) {
                killEnemy(enemy);
                return startPos;
            }
        }

        // Generic wall/obstacle slam -scales with the push strength so strong
        // knockbacks that hit a wall hurt more than weak ones. Mirrors the
        // collision handling in VanillaWeapons' Knockback shockwave.
        if (hitWall && !hitHazard) {
            int slamDamage = Math.max(1, tiles * 2);
            int dealt = enemy.takeDamage(slamDamage);
            sendMessage("§6" + enemy.getDisplayName() + " slammed into " + wallLabel
                + " for " + dealt + " collision damage!");
            if (!enemy.isAlive()) {
                killEnemy(enemy);
                return landingPos;
            }
        }

        // Crater: any slam (wall, obstacle, another enemy, cactus) also Stuns and hits harder.
        if (crater && (hitWall || hitCactus) && enemy.isAlive()) {
            int dealt = enemy.takeDamage(SwordAxeEnchantEffects.CRATER_COLLISION_DAMAGE);
            enemy.setStunned(true);
            sendMessage("§6Crater! " + enemy.getDisplayName() + " takes " + dealt
                + " more from the impact and is Stunned!");
            if (!enemy.isAlive()) {
                killEnemy(enemy);
                return landingPos;
            }
        }

        // Midas enchant (blunt): a wall-slam shakes emeralds loose into the slammer's bank,
        // once per enemy per combat so bouncing the same skeleton off a wall isn't a mint.
        if ((hitWall || hitCactus) && phase == CombatPhase.PLAYER_TURN && player != null
                && CrafticsEnchantments.heldLevel(player, CrafticsEnchantments.MIDAS) > 0
                && midasPaidEnemies.add(enemy.getEntityId())) {
            int coins = 1 + combatRng.nextInt(SwordAxeEnchantEffects.MIDAS_MAX_EMERALDS);
            var midasData = com.crackedgames.craftics.world.CrafticsSavedData.get(
                (ServerWorld) player.getEntityWorld());
            midasData.getPlayerData(player.getUuid()).addEmeralds(coins);
            midasData.markDirty();
            sendMessage("§aMidas! " + coins + " emerald" + (coins == 1 ? "" : "s")
                + " shake loose into your bank.");
        }

        if (!landingPos.equals(startPos)) {
            arena.moveEntity(enemy, landingPos);
            if (enemy.getMobEntity() != null) {
                var bp = arena.gridToBlockPos(landingPos);
                enemy.getMobEntity().requestTeleport(bp.getX() + 0.5, arena.getEntityY(landingPos, enemy.isFlying()), bp.getZ() + 0.5);
            }

            if (hitHazard) {
                var hazardTile = arena.getTile(landingPos);
                if (hazardTile != null) {
                    switch (hazardTile.getType()) {
                        case VOID -> {
                            enemy.takeDamage(enemy.getCurrentHp() + 100);
                            sendMessage("§4" + enemy.getDisplayName() + " fell into the void!");
                            killEnemy(enemy);
                        }
                        case DEEP_WATER -> {
                            if (isWaterImmune(enemy.getEntityTypeId())) {
                                // Aquatic mobs survive deep water -just soak them
                                enemy.stackSoaked(2, 1);
                                sendMessage("§b" + enemy.getDisplayName() + " splashes into deep water!");
                            } else {
                                enemy.takeDamage(enemy.getCurrentHp() + 100);
                                sendMessage("§1" + enemy.getDisplayName() + " drowned in deep water!");
                                killEnemy(enemy);
                            }
                        }
                        case LAVA -> {
                            int lavaDmg = enemy.takeDamage(10);
                            sendMessage("§6" + enemy.getDisplayName() + " knocked into lava for " + lavaDmg + " damage!");
                            if (!enemy.isAlive()) {
                                killEnemy(enemy);
                            }
                        }
                        case WATER -> {
                            enemy.stackSoaked(2, 1);
                            sendMessage("§b" + enemy.getDisplayName() + " splashes into water! Soaked!");
                        }
                        case POWDER_SNOW -> {
                            // Shoved into powder snow: freezing damage + Slowness,
                            // matching the tile's freeze hazard for anything that
                            // sinks into it.
                            int freezeDmg = enemy.takeDamage(2);
                            enemy.stackSlowness(2, 1);
                            sendMessage("§b" + enemy.getDisplayName() + " sinks into powder snow for "
                                + freezeDmg + " freezing damage!");
                            if (!enemy.isAlive()) killEnemy(enemy);
                        }
                        case LOW_GROUND -> {
                            // A sunken pit: no innate damage, but the drop staggers
                            // the mob (brief stun) as it tumbles a level down.
                            enemy.setStunned(true);
                            sendMessage("§7" + enemy.getDisplayName() + " tumbles into a sunken pit!");
                        }
                        default -> {}
                    }
                }
            }

            // Ice: a shove that ends on ice doesn't end there. Re-enter the same push
            // with exactly the length of the ice run ahead, so the enemy carries on to
            // the far edge and one tile past it - which is how you feed something into
            // a pit it would never have walked into. Guarded on isAlive so a hazard
            // that just killed it isn't followed by a slide, and the recursion is
            // bounded because each pass consumes the ice it just crossed.
            GridTile landedOn = arena.getTile(landingPos);
            if (enemy.isAlive() && !hitWall && !hitHazard
                    && landedOn != null
                    && landedOn.getType() == com.crackedgames.craftics.core.TileType.ICE) {
                int run = 0;
                GridPos scan = landingPos;
                while (run < 16) {
                    GridPos next = new GridPos(scan.x() + dx, scan.z() + dz);
                    if (!arena.isInBounds(next)) break;
                    GridTile t = arena.getTile(next);
                    if (t == null || t.getType() != com.crackedgames.craftics.core.TileType.ICE) break;
                    scan = next;
                    run++;
                }
                sendMessage("§b" + enemy.getDisplayName() + " skids across the ice!");
                return knockEnemyBack(enemy, dx, dz, run + 1);
            }
        }

        // Hemorrhage enchant (sword): being knocked around detonates the target's Bleed - the
        // stacks convert to one burst and clear. Player-turn gated like Crater, so an enemy
        // shove never triggers it.
        if (phase == CombatPhase.PLAYER_TURN && player != null
                && enemy.isAlive() && enemy.getBleedStacks() > 0
                && CrafticsEnchantments.heldLevel(player, CrafticsEnchantments.HEMORRHAGE) > 0) {
            int stacks = enemy.getBleedStacks();
            enemy.setBleedStacks(0);
            int burst = enemy.takeDamage(stacks * SwordAxeEnchantEffects.HEMORRHAGE_DAMAGE_PER_STACK);
            sendMessage("§4Hemorrhage! " + enemy.getDisplayName() + "'s " + stacks
                + " Bleed stack" + (stacks == 1 ? "" : "s") + " detonate for " + burst + "!");
            if (!enemy.isAlive()) killEnemy(enemy);
        }

        // Trapper: an enemy SHOVED onto a trap springs it immediately.
        springTrapperTraps();
        return landingPos;
    }

    private boolean hasLeatherBoots() {
        if (player == null) return false;
        var boots = player.getEquippedStack(net.minecraft.entity.EquipmentSlot.FEET);
        return boots.getItem() == Items.LEATHER_BOOTS;
    }

    private static boolean isWaterImmune(String entityTypeId) {
        return switch (entityTypeId) {
            case "minecraft:drowned", "minecraft:guardian", "minecraft:elder_guardian",
                 "minecraft:squid", "minecraft:glow_squid", "minecraft:axolotl",
                 "minecraft:turtle", "minecraft:dolphin", "minecraft:cod",
                 "minecraft:salmon", "minecraft:tropical_fish", "minecraft:pufferfish",
                 "minecraft:tadpole", "minecraft:frog" -> true;
            default -> false;
        };
    }

    /** Remove {@code owner}'s water boat (if any) and snap them back onto their
     *  grid tile -vanilla dismount offsets X/Z. */
    private void despawnActiveBoat(ServerPlayerEntity owner) {
        if (owner == null) return;
        net.minecraft.entity.vehicle.BoatEntity boat = activeBoats.remove(owner.getUuid());
        if (boat == null) return;
        owner.stopRiding();
        boat.discard();
        if (arena != null && !owner.isRemoved() && !owner.isDisconnected()) {
            GridPos ownerPos = (player != null && owner.getUuid().equals(player.getUuid()))
                ? arena.getPlayerGridPos() : gridPosOf(owner);
            BlockPos correct = arena.gridToBlockPos(ownerPos);
            double correctY = arena.getEntityY(ownerPos);
            owner.setPosition(correct.getX() + 0.5, correctY, correct.getZ() + 0.5);
            owner.networkHandler.requestTeleport(
                correct.getX() + 0.5, correctY, correct.getZ() + 0.5,
                owner.getYaw(), owner.getPitch());
        }
    }

    /** Combat-end cleanup: remove every player's water boat. */
    private void despawnAllBoats() {
        for (ServerPlayerEntity member : new ArrayList<>(allCombatPlayers())) {
            despawnActiveBoat(member);
        }
        // Boats whose owner already left the roster (disconnects) still need discarding.
        for (var leftover : activeBoats.values()) {
            if (leftover != null) leftover.discard();
        }
        activeBoats.clear();
    }

    /**
     * Apply status effects when certain enemy types hit the player.
     */
    private void applyEnemyHitEffect(String entityTypeId) {
        switch (entityTypeId) {
            case "minecraft:wither_skeleton" -> {
                addEffectHooked(CombatEffects.EffectType.WITHER, 3, 0);
                sendMessage("§8  Withered for 3 turns! (damage ramps up)");
            }
            case "minecraft:wither" -> {
                // The Wither boss applies Wither II on every direct hit -the
                // signature mechanic of the boss. Stronger than its minions.
                addEffectHooked(CombatEffects.EffectType.WITHER, 4, 1);
                sendMessage("§8  Withered II for 4 turns! (damage ramps up)");
            }
            case "minecraft:blaze" -> {
                if (!combatEffects.hasFireResistance()) {
                    addEffectHooked(CombatEffects.EffectType.BURNING, 2, 0);
                    sendMessage("§6  You're burning for 2 turns!");
                }
            }
            case "minecraft:husk" -> {
                addEffectHooked(CombatEffects.EffectType.WEAKNESS, 2, 0);
                sendMessage("§7  Weakness applied! (-2 attack for 2 turns)");
                applyPlayerKnockback(currentEnemy.getGridPos(), 1, currentEnemy);
            }
            case "minecraft:vindicator" -> {
                applyPlayerKnockback(currentEnemy.getGridPos(), 2, currentEnemy);
            }
            case "minecraft:stray" -> {
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 2, 0);
                sendMessage("§b  Slowness applied! (-1 movement for 2 turns)");
            }
            case "minecraft:witch" -> {
                addEffectHooked(CombatEffects.EffectType.POISON, 3, 0);
                sendMessage("§2  Poisoned for 3 turns!");
            }
            case "minecraft:shulker" -> {
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 2, 0);
                sendMessage("§d  Levitation slows you! (-1 movement for 2 turns)");
            }
            case "minecraft:ghast" -> {
                // Ghast fireball splash: also damages nearby enemies? No -just applies burning
                if (!combatEffects.hasFireResistance()) {
                    addEffectHooked(CombatEffects.EffectType.BURNING, 2, 0);
                    sendMessage("§6  Fireball burns you for 2 turns!");
                }
            }
            case "minecraft:breeze" -> {
                addEffectHooked(CombatEffects.EffectType.SLOWNESS, 1, 0);
                sendMessage("§b  Wind blast pushes you off balance! (-1 movement next turn)");
                // Wind charge gust: shove the player 2 tiles away from the
                // breeze. The full knockback handler also radiates adjacent
                // enemies outward from the player's new tile (8-direction).
                // This used to only fire from dispatchBossSubAction, which
                // the breeze's ranged-attack flow doesn't go through -
                // applyEnemyHitEffect is the path both ranged + melee hits
                // share, so calling it here actually moves the player.
                applyWindChargeKnockback(currentEnemy);
            }
            case "minecraft:ender_dragon" -> {
                addEffectHooked(CombatEffects.EffectType.WEAKNESS, 2, 0);
                sendMessage("§5  Dragon breath weakens you! (-2 attack for 2 turns)");
            }
            case "minecraft:bee" -> {
                addEffectHooked(CombatEffects.EffectType.POISON, 3, 0);
                sendMessage("§2  Bee sting! Poisoned for 3 turns!");
            }
            case "minecraft:llama" -> {
                sendMessage("§a  Splat! Llama spit!");
            }
            default -> {} // no special effect
        }
        // Bee post-attack recoil: stinging the player costs the bee 25% of its
        // max HP every time it attacks, just like the vanilla bee dying after
        // a sting.
        if ("minecraft:bee".equals(entityTypeId) && currentEnemy != null) {
            applyBeeStingRecoil(currentEnemy);
        }
    }

    /**
     * Bees lose 25% of their max HP every time they attack (rounded up, min 1).
     * Models the vanilla "bees die after stinging" mechanic without one-shotting
     * them, since arena bees have boosted HP. Kills the bee if recoil drops it.
     */
    /**
     * Count live allies that belong to {@code owner}. Used to gate spawn-egg
     * summons against the player's party cap. Unowned arena tames count as
     * belonging to the local active player.
     */
    private int countOwnedAllies(ServerPlayerEntity owner) {
        if (owner == null) return 0;
        java.util.UUID ownerId = owner.getUuid();
        int n = 0;
        for (CombatEntity e : enemies) {
            if (!e.isAlive() || !e.isAlly()) continue;
            // Seekers are spell payloads, not party members - they must not eat the
            // pet-affinity party slots a player summons real allies with.
            if (e.isSeekerProjectile()) continue;
            java.util.UUID eOwner = e.getOwnerUuid();
            if (eOwner == null && owner == player) { n++; continue; }
            if (eOwner != null && eOwner.equals(ownerId)) n++;
        }
        return n;
    }

    private void applyBeeStingRecoil(CombatEntity bee) {
        if (bee == null || !bee.isAlive()) return;
        if (!"minecraft:bee".equals(bee.getEntityTypeId())) return;
        int recoil = Math.max(1, (bee.getMaxHp() + 3) / 4);
        bee.takeDamage(recoil);
        if (bee.getMobEntity() != null && player != null
                && player.getEntityWorld() instanceof ServerWorld bw) {
            bw.spawnParticles(net.minecraft.particle.ParticleTypes.DAMAGE_INDICATOR,
                bee.getMobEntity().getX(), bee.getMobEntity().getY() + 0.5,
                bee.getMobEntity().getZ(), 4, 0.2, 0.2, 0.2, 0.02);
        }
        sendMessage("§e  " + bee.getDisplayName() + " loses " + recoil
            + " HP from stinging. (" + bee.getCurrentHp() + "/" + bee.getMaxHp() + ")");
        if (!bee.isAlive()) {
            checkAndHandleDeath(bee);
        }
    }

    private void tickEnemyDone() {
        // Broodmother: consume pending web rain (Hunting Dive phase 2)
        if (currentEnemy != null && currentEnemy.isBoss()) {
            EnemyAI bossAi = resolveAi(currentEnemy);
            if (bossAi instanceof BroodmotherAI bm) {
                List<GridPos> webRain = bm.consumeWebRain();
                if (webRain != null && !webRain.isEmpty()) {
                    placeWebOverlays(webRain, 2);
                    sendMessage("§e  The Broodmother rains webs from the ceiling!");
                }
            }
        }

        // INFINITE MODE: bosses past biome 10/20/... act multiple times per enemy
        // phase. Re-enter DECIDING for the same enemy (index unchanged) until its
        // per-turn action budget is spent; the counter self-resets at phase start.
        if (currentEnemy != null && currentEnemy.isAlive() && currentEnemy.isBoss()
                && phase == CombatPhase.ENEMY_TURN) {
            int totalActions = currentEnemy.getAiMemory("inf_actions_per_turn", 1);
            if (totalActions > 1) {
                int used = currentEnemy.getAiMemory("inf_actions_used", 0) + 1;
                if (used < totalActions) {
                    currentEnemy.setAiMemory("inf_actions_used", used);
                    sendMessage("§5  " + currentEnemy.getDisplayName() + " strikes again! ("
                        + (used + 1) + "/" + totalActions + ")");
                    enemyTurnState = EnemyTurnState.DECIDING;
                    enemyTurnDelay = Math.max(1, CrafticsMod.CONFIG.enemyTurnDelay() / 2);
                    pendingAction = null;
                    currentEnemy = null;
                    return;
                }
                currentEnemy.setAiMemory("inf_actions_used", 0);
            }
        }

        enemyTurnIndex++;
        enemyTurnState = EnemyTurnState.DECIDING;
        enemyTurnDelay = Math.max(1, CrafticsMod.CONFIG.enemyTurnDelay() / 2);
        pendingAction = null;
        currentEnemy = null;
    }

    /**
     * Locate a Totem of Undying anywhere on the player. Hand slots are checked
     * first to match vanilla totem priority; the rest of the inventory is
     * scanned afterward so a totem placed in the hotbar/main/armor slots still
     * saves the player. Returns the live stack reference (not a copy) so the
     * caller can decrement it directly. {@code null} if no totem is held.
     */
    private net.minecraft.item.ItemStack findTotemStack() {
        return findTotemStack(player);
    }

    /**
     * The same search, for any party member rather than only the turn holder.
     *
     * <p>Split out because a totem used to be something only the acting player could be
     * saved by: the below-floor sweep for NON-acting members killed them outright, with the
     * totem still in their hand. Everything that decides "does this player die" has to be
     * able to ask this question about the player it is about to kill.
     */
    private net.minecraft.item.ItemStack findTotemStack(ServerPlayerEntity who) {
        if (who == null) return null;
        net.minecraft.item.ItemStack mainHand = who.getMainHandStack();
        if (!mainHand.isEmpty() && isAnyTotem(mainHand.getItem())) {
            return mainHand;
        }
        net.minecraft.item.ItemStack offHand = who.getOffHandStack();
        if (!offHand.isEmpty() && isAnyTotem(offHand.getItem())) {
            return offHand;
        }
        var inv = who.getInventory();
        for (int i = 0; i < inv.size(); i++) {
            net.minecraft.item.ItemStack stack = inv.getStack(i);
            if (!stack.isEmpty() && isAnyTotem(stack.getItem())) {
                return stack;
            }
        }
        // A backpack carrying Backpacked's Immortal augment is the last place to look, which
        // matches the augment's own rule that totems in the hands are spent before stored ones.
        // Callers decrement what they get back, and a backpack does not persist that by itself,
        // so every totem-spending path flushes afterwards.
        return com.crackedgames.craftics.compat.backpacked.BackpackedCompat
            .findTotem(who, stack -> isAnyTotem(stack.getItem()));
    }

    /**
     * Spend a party member's totem to save them from a void death, and report whether one
     * was there to spend.
     *
     * <p>Deliberately simpler than {@link #tryConsumeTotemAndResurrect}, which drives the
     * MoreTotems effects through {@code this.player} and cannot speak for anyone else. This
     * grants the core contract - the totem is consumed, the holder lives - rather than
     * nothing at all, which is what a member got before.
     */
    private boolean tryConsumeTotemForMember(ServerPlayerEntity member) {
        net.minecraft.item.ItemStack totem = findTotemStack(member);
        if (totem == null) return false;
        totem.decrement(1);
        com.crackedgames.craftics.compat.backpacked.BackpackedCompat.flush(member);
        member.setHealth(8.0f); // four hearts, as a vanilla totem leaves you
        member.clearStatusEffects();
        member.setFireTicks(0);
        member.setFrozenTicks(0);
        return true;
    }

    /** Vanilla Totem of Undying or any MoreTotems totem. */
    private static boolean isAnyTotem(net.minecraft.item.Item item) {
        return item == Items.TOTEM_OF_UNDYING
            || com.crackedgames.craftics.compat.moretotems.MoreTotemsCompat.isMoreTotem(item);
    }

    /**
     * Consume a Totem of Undying and resurrect the player. Returns {@code true}
     * if a totem was consumed (death should be skipped), {@code false} if the
     * player has no totem.
     *
     * <p>Order is important: the totem is decremented <em>before</em> any other
     * side effects, so an exception in particle/sound rendering can never
     * leave the player half-resurrected with the totem still in hand. Status
     * effects are cleared first (matches vanilla behavior) so lingering
     * Wither/Poison from the killing blow can't chain-kill the resurrected
     * player on the next tick.
     */
    /**
     * Last-resort totem hook for damage Craftics never metered: a vanilla source (an explosion,
     * fire, fall damage, a boss's real-entity attack) that would kill the player outright.
     *
     * <p>{@code damagePlayer} clamps HP to 1 so the turn-based flow can never kill, and every
     * death route it owns checks the totem. But nothing was watching vanilla damage - so a boss
     * one-shot could take the player from full HP to dead without the totem ever being asked.
     * {@code PlayerDeathTotemMixin} calls this from {@code LivingEntity.damage} just before the
     * blow would land lethally, and cancels the damage when a totem is spent.
     *
     * @param deathBlow the player is about to die from a source Craftics didn't route
     * @return true when a totem was consumed and the death must be cancelled
     */
    /**
     * True while the arena is still settling after combat start. Damage taken in this window is
     * an artifact of the arena not being built yet (the player is falling through air that has
     * no floor under it yet), so it must not kill anyone or spend a totem - the mixin swallows
     * it outright instead.
     */
    public boolean isArenaSettling() {
        // Deliberately the TIMER only, not "is the floor missing?". A boss that destroys terrain
        // can legitimately delete the start tile's floor mid-fight, and keying invulnerability on
        // that would make the whole party immortal for the rest of the fight - far worse than the
        // bug this guards. The floor probe is used to EXTEND the grace window (below), never to
        // re-open it once the fight is genuinely underway.
        return active && fallDeathGraceTicks > 0;
    }

    public boolean tryTotemAgainstLethalDamage(ServerPlayerEntity victim) {
        if (!active || victim == null) return false;
        // Retarget onto the victim: `player` is the current TURN holder, and in a party the
        // one taking a vanilla hit may be someone else entirely. Consuming the turn-holder's
        // totem to save a different player would be a real bug.
        ServerPlayerEntity saved = this.player;
        try {
            this.player = victim;
            return tryConsumeTotemAndResurrect();
        } finally {
            this.player = saved;
        }
    }

    private boolean tryConsumeTotemAndResurrect() {
        net.minecraft.item.ItemStack totem = findTotemStack();
        if (totem == null) return false;

        // A revive can fire from inside the death animation, which set invulnerability to keep
        // the 1-HP clamp honest. Drop it before either revive path runs, or the resurrected
        // player walks away untouchable.
        player.setInvulnerable(false);

        String moddedPath = com.crackedgames.craftics.compat.moretotems.MoreTotemsCompat.totemPath(totem.getItem());
        if (moddedPath != null) {
            return consumeModdedTotem(totem, moddedPath);
        }

        totem.decrement(1);
        com.crackedgames.craftics.compat.backpacked.BackpackedCompat.flush(player);

        // Vanilla parity: clear all status effects, then re-apply totem buffs.
        player.clearStatusEffects();
        player.setAbsorptionAmount(0f);

        float halfMax = Math.max(1.0f, player.getMaxHealth() / 2.0f);
        player.setHealth(halfMax);

        // Combat-only regeneration: the vanilla effect heals in real time, which would let a
        // resurrected player tick their HP back between turns and quietly undo the turn-based
        // damage economy. The combat effect heals a little at the start of each of their turns.
        combatEffects.addEffect(CombatEffects.EffectType.REGENERATION, 5, 1);
        player.addStatusEffect(new net.minecraft.entity.effect.StatusEffectInstance(
            net.minecraft.entity.effect.StatusEffects.ABSORPTION, 100, 1));
        player.addStatusEffect(new net.minecraft.entity.effect.StatusEffectInstance(
            net.minecraft.entity.effect.StatusEffects.FIRE_RESISTANCE, 800, 0));

        // A bed placed this fight redirects where the revive lands. Runs before the
        // particles so the totem burst plays at the destination, not at the corpse.
        relocateToBedAnchor();

        // Visual + audio feedback. Wrapped so a particle/sound failure can't
        // block the resurrection -the player must always be saved if a totem
        // was consumed.
        try {
            ServerWorld world = (ServerWorld) player.getEntityWorld();
            world.spawnParticles(net.minecraft.particle.ParticleTypes.TOTEM_OF_UNDYING,
                player.getX(), player.getY() + 1.0, player.getZ(),
                100, 0.6, 1.0, 0.6, 0.5);
            world.playSound(null, player.getBlockPos(),
                net.minecraft.sound.SoundEvents.ITEM_TOTEM_USE,
                net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 1.0f);
        } catch (Exception ignored) {
        }

        sendMessage("\u00a76\u00a7l\u2726 TOTEM OF UNDYING ACTIVATES! \u2726 \u00a7rResurrected with half health!");
        achievementTracker.recordTotemProc();
        sendSync();
        return true;
    }

    /**
     * Consume a MoreTotems totem and resurrect with a BARE revive (clear effects + 50% HP),
     * then run the totem's unique Craftics effect. Decrement happens first so a render
     * failure can never leave the player un-revived (matches the vanilla method's ordering).
     */
    private boolean consumeModdedTotem(net.minecraft.item.ItemStack totem, String path) {
        totem.decrement(1);
        com.crackedgames.craftics.compat.backpacked.BackpackedCompat.flush(player);

        // Bare revive: clear effects + zero absorption + 50% HP. No vanilla buff baseline.
        player.clearStatusEffects();
        player.setAbsorptionAmount(0f);
        float halfMax = Math.max(1.0f, player.getMaxHealth() / 2.0f);
        player.setHealth(halfMax);

        String label;
        switch (path) {
            case com.crackedgames.craftics.compat.moretotems.MoreTotemsCompat.EXPLOSIVE -> {
                label = "Explosive Totem";
                totemExplosion();
            }
            case com.crackedgames.craftics.compat.moretotems.MoreTotemsCompat.SKELETAL -> {
                label = "Skeletal Totem";
                totemMarkAllEnemies(2);
            }
            case com.crackedgames.craftics.compat.moretotems.MoreTotemsCompat.TELEPORTING -> {
                label = "Teleporting Totem";
                totemTeleportToSafestTile();
            }
            case com.crackedgames.craftics.compat.moretotems.MoreTotemsCompat.GHASTLY -> {
                label = "Ghastly Totem";
                totemBurnAllEnemiesAndFireRes(5);
            }
            case com.crackedgames.craftics.compat.moretotems.MoreTotemsCompat.STINGING -> {
                label = "Stinging Totem";
                totemSummonAllies(net.minecraft.entity.EntityType.BEE, 5);
            }
            case com.crackedgames.craftics.compat.moretotems.MoreTotemsCompat.TENTACLED -> {
                label = "Tentacled Totem";
                totemBlindAllEnemies(2);
            }
            case com.crackedgames.craftics.compat.moretotems.MoreTotemsCompat.ROTTING -> {
                label = "Rotting Totem";
                totemSummonAllies(net.minecraft.entity.EntityType.ZOMBIE, 3);
            }
            default -> label = "Totem";
        }

        // After the totem's own effect, so an explicitly placed bed overrides the
        // Teleporting Totem's safest-tile pick. The bed is a deliberate choice the
        // player spent a turn on; the totem's teleport is a default.
        relocateToBedAnchor();

        try {
            ServerWorld world = (ServerWorld) player.getEntityWorld();
            world.spawnParticles(net.minecraft.particle.ParticleTypes.TOTEM_OF_UNDYING,
                player.getX(), player.getY() + 1.0, player.getZ(),
                100, 0.6, 1.0, 0.6, 0.5);
            world.playSound(null, player.getBlockPos(),
                net.minecraft.sound.SoundEvents.ITEM_TOTEM_USE,
                net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 1.0f);
        } catch (Exception ignored) {
        }

        sendMessage("\u00a76\u00a7l\u2726 " + label.toUpperCase() + " ACTIVATES! \u2726 \u00a7rResurrected with half health!");
        achievementTracker.recordTotemProc();
        sendSync();
        return true;
    }

    // \u2500\u2500 MoreTotems effect helpers \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500

    /** Explosive totem: 4x4 around the player, each enemy takes 50% max HP + biome ordinal. */
    private void totemExplosion() {
        GridPos center = arena.getPlayerGridPos();
        ServerWorld sw = (ServerWorld) player.getEntityWorld();
        try {
            BlockPos bp = arena.gridToBlockPos(center);
            sw.playSound(null, bp, net.minecraft.sound.SoundEvents.ENTITY_GENERIC_EXPLODE.value(),
                net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 1.0f);
        } catch (Exception ignored) {}
        // 4x4 block anchored so the player tile is the inner corner: dx,dz in -1..2.
        outer:
        for (int dx = -1; dx <= 2; dx++) {
            for (int dz = -1; dz <= 2; dz++) {
                GridPos pos = new GridPos(center.x() + dx, center.z() + dz);
                if (!arena.isInBounds(pos)) continue;
                CombatEntity target = arena.getOccupant(pos);
                if (target == null || !target.isAlive() || target.isAlly()) continue;
                int dmg = MoreTotemsEffects.explosionDamage(target.getMaxHp(), currentBiomeOrdinal);
                int actual = target.takeDamage(dmg);
                sendMessage("\u00a7c\u2726 Explosion hits " + target.getDisplayName() + " for " + actual + "!");
                checkAndHandleDeath(target);
                if (!active) break outer; // last enemy died \u2014 combat already ended
            }
        }
        refreshHighlights();
    }

    /** Skeletal totem: mark every living enemy for the given turns. */
    private void totemMarkAllEnemies(int turns) {
        int n = 0;
        for (CombatEntity e : enemies) {
            if (!e.isAlive() || e.isAlly()) continue;
            e.setMarkedTurns(Math.max(e.getMarkedTurns(), turns));
            n++;
        }
        sendMessage("\u00a7e\u2726 " + n + " enemies are Marked for " + turns + " turns!");
    }

    /** Tentacled totem: blind every living enemy for the given turns. */
    private void totemBlindAllEnemies(int turns) {
        int n = 0;
        for (CombatEntity e : enemies) {
            if (!e.isAlive() || e.isAlly()) continue;
            e.stackBlinded(turns);
            n++;
        }
        sendMessage("\u00a79\u2726 " + n + " enemies are Blinded for " + turns + " turns!");
    }

    /** Ghastly totem: set every living enemy on fire, grant the player Fire Resistance. */
    private void totemBurnAllEnemiesAndFireRes(int turns) {
        // Burning I. This was a per-turn damage number before the amplifier slot meant a level.
        int burnAmp = 0;
        int n = 0;
        for (CombatEntity e : enemies) {
            if (!e.isAlive() || e.isAlly()) continue;
            e.stackBurning(turns, burnAmp);
            n++;
        }
        addEffectHooked(CombatEffects.EffectType.FIRE_RESISTANCE, turns, 0);
        sendMessage("\u00a76\u2726 " + n + " enemies set ablaze for " + turns + " turns! You gain Fire Resistance.");
    }

    /** Teleporting totem: move the player to the tile farthest from the nearest enemy. */
    private void totemTeleportToSafestTile() {
        java.util.List<GridPos> candidates = new java.util.ArrayList<>();
        GridPos cur = arena.getPlayerGridPos();
        for (int x = 0; x < arena.getWidth(); x++) {
            for (int z = 0; z < arena.getHeight(); z++) {
                GridPos p = new GridPos(x, z);
                if (arena.isOccupied(p) && !p.equals(cur)) continue;
                GridTile t = arena.getTile(p);
                if (t == null || !t.isSafeForSpawn()) continue;
                candidates.add(p);
            }
        }
        java.util.List<GridPos> enemyPositions = new java.util.ArrayList<>();
        for (CombatEntity e : enemies) {
            if (e.isAlive() && !e.isAlly()) enemyPositions.add(e.getGridPos());
        }
        GridPos dest = MoreTotemsEffects.safestTile(candidates, enemyPositions);
        if (dest == null || dest.equals(cur)) return; // no better tile \u2014 stay put
        arena.setPlayerGridPos(dest);
        BlockPos bp = arena.gridToBlockPos(dest);
        //? if <=1.21.1 {
        player.teleport((ServerWorld) player.getEntityWorld(),
            bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5,
            java.util.Collections.emptySet(), player.getYaw(), 0f);
        //?} else {
        /*player.teleport((ServerWorld) player.getEntityWorld(),
            bp.getX() + 0.5, bp.getY(), bp.getZ() + 0.5,
            java.util.Collections.emptySet(), player.getYaw(), 0f, true);
        *///?}
        sendMessage("\u00a7d\u2726 Teleported to safety!");
    }

    /**
     * Summon {@code count} temporary allied mobs of the given type near the player. Bypasses
     * AP and the party cap (this is a revive bonus, not a player action). Best-effort: any mob
     * that can't be placed is skipped.
     */
    private void totemSummonAllies(net.minecraft.entity.EntityType<?> entityType, int count) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        String typeId = net.minecraft.registry.Registries.ENTITY_TYPE.getId(entityType).toString();
        com.crackedgames.craftics.api.registry.AllyEntry entry =
            com.crackedgames.craftics.api.registry.AllyRegistry.getOrNull(typeId);
        int hp, atk, def, range;
        if (entry != null) {
            hp = entry.hp(); atk = entry.attack(); def = entry.defense(); range = entry.range();
        } else {
            hp = 8; atk = 2; def = 0; range = 1;
        }
        hp += computeAllyPetHpBonus(typeId, player.getUuid());

        java.util.Set<GridPos> reserved = new java.util.HashSet<>();
        for (CombatEntity e : enemies) {
            if (e.isAlive()) reserved.add(e.getGridPos());
        }
        reserved.add(arena.getPlayerGridPos());

        int spawned = 0;
        for (int i = 0; i < count; i++) {
            GridPos tile = findNearestWalkableUnreserved(arena, arena.getPlayerGridPos(), reserved);
            if (tile == null) break;
            reserved.add(tile);

            BlockPos blockPos = arena.gridToBlockPos(tile);
            net.minecraft.entity.Entity rawEntity = entityType.create(world, null, blockPos,
                net.minecraft.entity.SpawnReason.MOB_SUMMONED, false, false);
            if (!(rawEntity instanceof net.minecraft.entity.mob.MobEntity mob)) continue;
            mob.refreshPositionAndAngles(
                blockPos.getX() + 0.5, blockPos.getY(), blockPos.getZ() + 0.5, 0, 0);
            mob.setPersistent();
            mob.setAiDisabled(true);
            mob.setInvulnerable(true);
            mob.setNoGravity(true);
            mob.noClip = true;
            mob.setSilent(true);
            mob.addCommandTag("craftics_arena");
            world.spawnEntity(mob);

            CombatEntity ce = new CombatEntity(mob.getId(), typeId, tile, hp, atk, def, range);
            ce.setAlly(true);
            ce.setTemporaryAlly(true);
            ce.setOwnerUuid(player.getUuid());
            ce.setMobEntity(mob);
            ce.setAllyAi(com.crackedgames.craftics.combat.ai.ally.AllyArchetypes.aiFor(typeId));
            enemies.add(ce);
            arena.placeEntity(ce);
            spawned++;
        }
        sendMessage("\u00a7a\u2726 " + spawned + " allies rise to defend you!");
        refreshHighlights();
    }

    /**
     * Called when the active player's HP reaches 0. In a party, the dead player
     * becomes a spectator and combat continues with the next alive member.
     * Only triggers a full game over when ALL party members are dead (or solo play).
     */
    private void handlePlayerDeathOrGameOver() {
        // Totem of Undying: save the player from downing/death entirely.
        if (tryConsumeTotemAndResurrect()) {
            return;
        }

        // Solo play or no party → start death animation before game over
        if (partyPlayers.size() <= 1) {
            startPlayerDeathAnimation();
            return;
        }

        // Mark current player as dead
        deadPartyMembers.add(player.getUuid());
        player.setHealth(1); // keep at clamp threshold (avoids vanilla death screen)

        // --- Downed animation: distinct from death (shorter, different effects) ---
        // Downed sound: player hurt + anvil thud (not wither sounds like death)
        ServerWorld downedWorld = (ServerWorld) player.getEntityWorld();
        player.getWorld().playSound(null, player.getBlockPos(),
            net.minecraft.sound.SoundEvents.ENTITY_PLAYER_HURT,
            net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 0.7f);
        player.getWorld().playSound(null, player.getBlockPos(),
            net.minecraft.sound.SoundEvents.BLOCK_ANVIL_LAND,
            net.minecraft.sound.SoundCategory.PLAYERS, 0.4f, 0.5f);

        // Downed particles: red dust + damage indicator (NOT soul particles like death)
        downedWorld.spawnParticles(net.minecraft.particle.ParticleTypes.DAMAGE_INDICATOR,
            player.getX(), player.getY() + 1.0, player.getZ(),
            8, 0.3, 0.5, 0.3, 0.02);
        //? if <=1.21.1 {
        downedWorld.spawnParticles(
            new net.minecraft.particle.DustParticleEffect(
                new org.joml.Vector3f(1.0f, 0.2f, 0.2f), 1.5f),
            player.getX(), player.getY() + 0.5, player.getZ(),
            12, 0.4, 0.3, 0.4, 0.01);
        //?} else {
        /*downedWorld.spawnParticles(
            new net.minecraft.particle.DustParticleEffect(0xFF3333, 1.5f),
            player.getX(), player.getY() + 0.5, player.getZ(),
            12, 0.4, 0.3, 0.4, 0.01);
        *///?}

        // Send downed event to client (orange vignette, different from red death vignette)
        sendToAllParty(new CombatEventPayload(
            CombatEventPayload.EVENT_PLAYER_DOWNED, 0, 0, 0, 0, 0));

        player.changeGameMode(net.minecraft.world.GameMode.SPECTATOR);
        sendMessage("§c§l☠ " + player.getName().getString() + " has fallen!");

        // Find next alive party member
        ServerPlayerEntity nextAlive = null;
        for (ServerPlayerEntity member : partyPlayers) {
            if (!deadPartyMembers.contains(member.getUuid())
                    && member != null && !member.isRemoved() && !member.isDisconnected()) {
                nextAlive = member;
                break;
            }
        }

        if (nextAlive == null) {
            // Everyone dead → start death animation before game over
            startPlayerDeathAnimation();
            return;
        }

        // Transfer combat control to next alive member. We deliberately do NOT
        // teleport them to the dying player's spot -they're standing on their
        // own arena tile and the previous "snap to the corpse" behavior was
        // making the survivor jump onto where their teammate just died for no
        // gameplay benefit (it broke positioning in turn-based combat).
        sendMessage("§e" + nextAlive.getName().getString() + " takes over the fight!");
        // Drop the dead player from the positional turn queue so the survivors
        // don't get a free double-turn this round (the queue is rotated by index,
        // and switchToTurnPlayer only skipped removed/disconnected, not dead).
        pruneDeadFromTurnQueue(player.getUuid());
        this.player = nextAlive;
        retargetEffectsToCurrentPlayer();

        // Recalculate stats for the new active player
        PlayerProgression prog = PlayerProgression.get((ServerWorld) player.getEntityWorld());
        PlayerProgression.PlayerStats pStats = prog.getStats(player);
        this.apRemaining = pStats.getEffective(PlayerProgression.Stat.AP)
            + PlayerCombatStats.getSetApBonus(player);
        this.movePointsRemaining = pStats.getEffective(PlayerProgression.Stat.SPEED)
            + PlayerCombatStats.getSetSpeedBonus(player);
        this.activeTrimScan = TrimEffects.scan(player);
        this.activeCombatEffects = activeTrimScan.getCombatEffects();
        if (effectContext != null) effectContext.update(player, arena, combatEffects, activeTrimScan);

        sendSync();
        refreshHighlights();
    }

    /**
     * Begin the player death animation sequence. Freezes combat, plays dramatic
     * effects (sound, particles, camera event) over PLAYER_DEATH_ANIM_TICKS,
     * then transitions to the real handleGameOver().
     */
    private void startPlayerDeathAnimation() {
        phase = CombatPhase.PLAYER_DYING;
        playerDeathAnimTick = 0;

        // Clamp player health so vanilla death screen doesn't trigger
        player.setHealth(1);
        // ...and make that clamp hold. At 1 HP ANY damage landing during the animation kills for
        // real - an enemy's attack resolving the same tick, a poison tick, an evoker's fangs -
        // and the vanilla death screen opens on top of a combat still running its death
        // sequence, which strands the whole fight. Cleared in handleGameOver and on any revive.
        player.setInvulnerable(true);

        // Death sound -deep bass hit
        player.getWorld().playSound(null, player.getBlockPos(),
            net.minecraft.sound.SoundEvents.ENTITY_PLAYER_DEATH,
            net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 0.5f);

        // Send death event to client for screen effects (red vignette, camera drop)
        sendToAllParty(new CombatEventPayload(
            CombatEventPayload.EVENT_COMBAT_LOST, 0, PLAYER_DEATH_ANIM_TICKS, 0, 0, 0));

        sendMessage("§c§l☠ You have fallen...");
    }

    private void tickPlayerDying() {
        playerDeathAnimTick++;

        ServerWorld world = (ServerWorld) player.getEntityWorld();

        // Tick 1-15: rising soul particles from player
        if (playerDeathAnimTick <= 15 && playerDeathAnimTick % 3 == 0) {
            world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL,
                player.getX(), player.getY() + 1.0, player.getZ(),
                5, 0.3, 0.5, 0.3, 0.02);
        }

        // Tick 10: secondary death echo sound
        if (playerDeathAnimTick == 10) {
            player.getWorld().playSound(null, player.getBlockPos(),
                net.minecraft.sound.SoundEvents.ENTITY_WITHER_HURT,
                net.minecraft.sound.SoundCategory.PLAYERS, 0.4f, 0.3f);
        }

        // Tick 20-40: smoke/ash particles (body fading)
        if (playerDeathAnimTick >= 20 && playerDeathAnimTick <= 40 && playerDeathAnimTick % 4 == 0) {
            world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                player.getX(), player.getY() + 0.5, player.getZ(),
                8, 0.4, 0.3, 0.4, 0.01);
        }

        // Tick 45: defeat sting
        if (playerDeathAnimTick == 45) {
            player.getWorld().playSound(null, player.getBlockPos(),
                net.minecraft.sound.SoundEvents.ENTITY_WITHER_DEATH,
                net.minecraft.sound.SoundCategory.PLAYERS, 0.5f, 0.5f);
        }

        // Animation complete → proceed to actual game over logic
        if (playerDeathAnimTick >= PLAYER_DEATH_ANIM_TICKS) {
            handleGameOver();
        }
    }

    /**
     * Pre-roll the death-loss outcome for every losable item this player carries,
     * WITHOUT mutating the inventory. Returns an empty list (caller falls back to
     * the legacy synchronous path) when the player is death-protected or is not in
     * a biome run past level 1, or when there is nothing losable. Exempt items
     * (Move feather, Guide Book) are skipped entirely.
     */
    /** One slot before grouping: its stack, its per-unit loss chance, and how many
     *  of its units rolled "lost". */
    private record RawSlotRoll(int kind, int index, String accContainer, int accKind, int accSlot,
                               ItemStack stack, int lost) {}

    private java.util.List<PendingItemRoll> rollGameOverLoss(ServerPlayerEntity p,
                                                             CrafticsSavedData.PlayerData ld) {
        java.util.List<PendingItemRoll> rolls = new java.util.ArrayList<>();
        // Protected players keep everything - no flip.
        if (DeathProtectionComponent.hasRecoveryCompass(p)
                && DeathProtectionComponent.protectCombatInventory(p)) {
            return rolls;
        }
        // Any biome-run death uses the per-item coin-flip (level 1 included).
        if (!ld.isInBiomeRun()) return rolls;

        double mainLoss = CrafticsMod.CONFIG.deathMainInventoryLossChance();
        double gearLoss = CrafticsMod.CONFIG.deathGearLossChance();
        int luck = PlayerProgression.get((ServerWorld) p.getEntityWorld())
            .getStats(p).getPoints(PlayerProgression.Stat.LUCK);
        double gearEff = Math.max(MIN_LOSS_CHANCE, gearLoss - LUCK_KEEP_PER_POINT * luck);
        double mainEff = Math.max(MIN_LOSS_CHANCE, mainLoss - LUCK_KEEP_PER_POINT * luck);

        // Roll each physical slot at its own rate, per UNIT in the stack.
        java.util.List<RawSlotRoll> raw = new java.util.ArrayList<>();
        // Main + hotbar 36 slots (hotbar < 9 = gear rate, backpack >= 9 = main rate).
        int mainSlots = Math.min(36, p.getInventory().size());
        for (int slot = 0; slot < mainSlots; slot++) {
            ItemStack stack = p.getInventory().getStack(slot);
            if (stack.isEmpty()) continue;
            Item item = stack.getItem();
            if (item == com.crackedgames.craftics.item.ModItems.MOVE_ITEM
                    || item instanceof com.crackedgames.craftics.item.GuideBookItem) continue;
            int lost = rollUnitsLost(stack.getCount(), slot < 9 ? gearEff : mainEff);
            raw.add(new RawSlotRoll(0, slot, null, 0, 0, stack.copy(), lost));
        }
        // Armor (4 slots) at gear rate.
        //? if <=1.21.4 {
        for (int slot = 0; slot < p.getInventory().armor.size(); slot++) {
            ItemStack stack = p.getInventory().armor.get(slot);
            if (stack.isEmpty()) continue;
            raw.add(new RawSlotRoll(1, slot, null, 0, 0, stack.copy(),
                rollUnitsLost(stack.getCount(), gearEff)));
        }
        //?} else {
        /*net.minecraft.entity.EquipmentSlot[] armorSlots = {
                net.minecraft.entity.EquipmentSlot.HEAD, net.minecraft.entity.EquipmentSlot.CHEST,
                net.minecraft.entity.EquipmentSlot.LEGS, net.minecraft.entity.EquipmentSlot.FEET};
        for (int slot = 0; slot < armorSlots.length; slot++) {
            ItemStack stack = p.getEquippedStack(armorSlots[slot]);
            if (stack.isEmpty()) continue;
            raw.add(new RawSlotRoll(1, slot, null, 0, 0, stack.copy(),
                rollUnitsLost(stack.getCount(), gearEff)));
        }
        *///?}
        // Offhand at gear rate.
        ItemStack off = p.getOffHandStack();
        if (!off.isEmpty()) {
            raw.add(new RawSlotRoll(2, 0, null, 0, 0, off.copy(),
                rollUnitsLost(off.getCount(), gearEff)));
        }
        // Accessories (Artifacts trinkets) at gear rate, enumerated per slot.
        for (com.crackedgames.craftics.compat.artifacts.AccessoriesReflect.AccessorySnapshot snap :
                com.crackedgames.craftics.compat.artifacts.AccessoriesReflect.saveAccessories(p)) {
            raw.add(new RawSlotRoll(3, 0, snap.container(), snap.kind(), snap.slot(),
                snap.stack().copy(), rollUnitsLost(snap.stack().getCount(), gearEff)));
        }
        // Backpack contents (Backpacked) at the main-inventory rate - the same rate the vanilla
        // storage rows pay, because that is what a backpack is. They sat outside the flip
        // entirely before, which made a worn backpack a death-proof vault and would have made
        // stuffing one the obviously correct way to survive a run.
        //
        // A pack whose Recall augment is linked to a shelf is left out: Recall's promise is that
        // the backpack comes home when you die, and this screen is where a run's belongings are
        // actually at risk. losableSlots applies that rule per pack.
        for (com.crackedgames.craftics.compat.backpacked.BackpackedCompat.LosableSlot bs :
                com.crackedgames.craftics.compat.backpacked.BackpackedCompat.losableSlots(p)) {
            Item bagItem = bs.stack().getItem();
            if (bagItem == com.crackedgames.craftics.item.ModItems.MOVE_ITEM
                    || bagItem instanceof com.crackedgames.craftics.item.GuideBookItem) continue;
            raw.add(new RawSlotRoll(4, bs.pack(), null, 0, bs.slot(), bs.stack().copy(),
                rollUnitsLost(bs.stack().getCount(), mainEff)));
        }

        // Group identical item-types (same item + components) across all slots into
        // one display entry: total quantity, summed lost quantity, and the per-slot
        // removals to apply. Insertion order preserved for a stable grid.
        for (RawSlotRoll rs : raw) {
            PendingItemRoll group = null;
            for (PendingItemRoll g : rolls) {
                if (ItemStack.areItemsAndComponentsEqual(g.repr(), rs.stack())) { group = g; break; }
            }
            SlotLoss sl = new SlotLoss(rs.kind(), rs.index(), rs.accContainer(), rs.accKind(),
                rs.accSlot(), rs.lost());
            if (group == null) {
                java.util.List<SlotLoss> slots = new java.util.ArrayList<>();
                slots.add(sl);
                ItemStack repr = rs.stack().copy();
                repr.setCount(rs.stack().getCount());
                rolls.add(new PendingItemRoll(repr, rs.stack().getCount(), rs.lost(), slots));
            } else {
                group.slots().add(sl);
                // records are immutable; replace with an updated total/lost. The repr
                // stack carries the merged total purely for the client display.
                int idx = rolls.indexOf(group);
                int newTotal = group.totalQ() + rs.stack().getCount();
                ItemStack repr = group.repr().copy();
                repr.setCount(Math.min(9999, newTotal));
                rolls.set(idx, new PendingItemRoll(repr, newTotal, group.lostQ() + rs.lost(), group.slots()));
            }
        }
        return rolls;
    }

    /** Roll {@code count} independent units at {@code lossChance} each; return how
     *  many were lost. */
    private static int rollUnitsLost(int count, double lossChance) {
        int lost = 0;
        for (int i = 0; i < count; i++) if (Math.random() < lossChance) lost++;
        return lost;
    }

    private void handleGameOver() {
        phase = CombatPhase.GAME_OVER;
        // Defeat ends the run, so the fight that was lost must not be resumable. This is also the
        // half that keeps the feature from becoming a second life: losing costs the run, not a
        // rewind to the turn before the killing blow.
        clearResumeSnapshots();
        lastXpLevelsLost.clear();
        // Release the death-animation invulnerability (see startPlayerDeathAnimation) now that
        // the fight is resolving - leaving it set would follow the player out of the arena.
        if (player != null) player.setInvulnerable(false);
        // Sound: defeat
        if (player != null) {
            player.getWorld().playSound(null, player.getBlockPos(),
                net.minecraft.sound.SoundEvents.ENTITY_WITHER_DEATH,
                net.minecraft.sound.SoundCategory.PLAYERS, 0.5f, 0.5f);
        }
        sendMessage("§c§l*** DEFEATED ***");

        ServerWorld world = (ServerWorld) player.getEntityWorld();
        CrafticsSavedData data = CrafticsSavedData.get(world);
        CrafticsSavedData.PlayerData ld = data.getPlayerData(leaderUuid != null ? leaderUuid : player.getUuid());

        // HARDCORE ISLAND: full-party defeat = total wipe. Takes precedence over
        // the infinite-mode and permadeath flows; no emerald/XP penalties and no
        // coin-flip item screen - everything is gone regardless.
        java.util.UUID hcOwner = leaderUuid != null ? leaderUuid : player.getUuid();
        if (com.crackedgames.craftics.world.HardcoreIslands.isHardcore(world.getServer(), hcOwner)) {
            finishHardcoreTeardown(hcOwner, ld);
            return;
        }

        // DAILY RAID BOSS: the standard defeat screen with no penalties at all. Raiders
        // brought gear in from outside a run, so the item-loss coin flip, the emerald
        // halving and the XP loss below would punish participation far harder than
        // losing a biome run does. The instance owns the return trip and the dimension.
        if (raidBossContext != null) {
            com.crackedgames.craftics.raid.RaidBossInstance raidInstance = raidBossContext;
            java.util.List<ServerPlayerEntity> raidParticipants =
                new java.util.ArrayList<>(getAllParticipants());
            for (ServerPlayerEntity p : raidParticipants) {
                if (p != null && !p.isRemoved() && !p.isDisconnected()) {
                    p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);
                }
            }
            sendMessage("§4§lThe raid has fallen.");
            // Spec 6.2: the STANDARD game-over screen runs, with only the item-loss
            // rolls skipped - not the screen itself. GameOverItemsPayload is what opens
            // that screen client-side, so it must still be sent, just with empty lists
            // and zero losses, or a raid wipe silently shows nothing where every other
            // defeat in the mod shows the coin-flip screen.
            for (ServerPlayerEntity p : raidParticipants) {
                if (p != null && !p.isRemoved() && !p.isDisconnected()) {
                    ServerPlayNetworking.send(p, new com.crackedgames.craftics.network.GameOverItemsPayload(
                        java.util.List.of(), java.util.List.of(), 0, 0));
                }
            }
            sendToAllParty(new ExitCombatPayload(false));
            petsRescued = true;
            endCombat();
            raidInstance.finish(world.getServer());
            return;
        }

        // INFINITE MODE: a wipe just ends the run. No emerald/XP/item death
        // penalties - the run items and the run wallet evaporate with the stash
        // restore (the real balance returns), and the banked best score is kept.
        // Resolve the ACTUAL run host, not the party leader: infiniteActive lives on
        // the HOST's record, and in co-op the host need not be the leader. Checking
        // the leader's record here skipped this branch entirely and dropped a co-op
        // wipe into the death-penalty path below (same bug class the victory flow
        // fixed with resolveActiveHost).
        java.util.UUID infHost = InfiniteRunManager.resolveActiveHost(
            data, leaderUuid != null ? leaderUuid : player.getUuid(), player.getUuid());
        if (infHost != null) {
            finishGameOverTeardown();
            InfiniteRunManager.endRun(world.getServer(), infHost, "the party fell");
            return;
        }

        // Permadeath mode: lose ALL emeralds and reset biome progress
        if (CrafticsMod.CONFIG.permadeathMode()) {
            int allEmeralds = ld.emeralds;
            if (allEmeralds > 0) ld.spendEmeralds(allEmeralds);
            ld.highestBiomeUnlocked = 1;
            sendMessage("§4§lPERMADEATH: All progress lost!");
        }

        // Death penalty: lose 50% emeralds
        int emeraldLoss = CrafticsMod.CONFIG.permadeathMode() ? 0 : ld.emeralds / 2;
        if (emeraldLoss > 0) {
            ld.spendEmeralds(emeraldLoss);
            sendMessage("§cLost " + emeraldLoss + " emeralds!");
        }

        // Death penalty: lose XP levels
        for (ServerPlayerEntity p : getAllParticipants()) {
            int levels = p.experienceLevel;
            if (levels > 0) {
                int lost = Math.max(1, levels / 2);
                p.addExperienceLevels(-lost);
                lastXpLevelsLost.put(p.getUuid(), lost);
                sendMessageTo(p, "§cLost " + lost + " XP level" + (lost != 1 ? "s" : "") + "!");
            }
        }

        // Per-player item loss. Eligible players (biome run past level 1, not
        // death-protected, with losable items) defer to the coin-flip screen; the
        // rest take the legacy synchronous path immediately.
        pendingGameOverLoss.clear();
        gameOverAcks.clear();
        gameOverWaiting.clear();
        boolean anyFlip = false;
        for (ServerPlayerEntity p : getAllParticipants()) {
            java.util.List<PendingItemRoll> rolls = rollGameOverLoss(p, ld);
            if (rolls.isEmpty()) {
                applyLegacyGameOverLoss(p, ld); // protected / level-1 / nothing losable
                continue;
            }
            pendingGameOverLoss.put(p.getUuid(), rolls);
            gameOverWaiting.add(p.getUuid());
            anyFlip = true;
            // Build the parallel lists for the payload: one entry per grouped item,
            // its representative stack (count = total owned) and how many units of
            // it are lost.
            java.util.List<ItemStack> items = new java.util.ArrayList<>();
            java.util.List<Integer> lostCounts = new java.util.ArrayList<>();
            for (PendingItemRoll r : rolls) {
                items.add(r.repr());
                lostCounts.add(r.lostQ());
            }
            int pXpLost = lastXpLevelsLost.getOrDefault(p.getUuid(), 0);
            ServerPlayNetworking.send(p, new com.crackedgames.craftics.network.GameOverItemsPayload(
                items, lostCounts, emeraldLoss, pXpLost));
        }

        if (anyFlip) {
            // Hold here; clients animate, then ack. tickGameOverFlip applies the
            // loss + teardown on all-acked or on timeout.
            phase = CombatPhase.GAME_OVER_FLIP;
            gameOverFlipTimer = GAME_OVER_FLIP_TIMEOUT;
            return;
        }
        // Nobody flips - fall through to the existing heal/teleport/endCombat teardown below.
        finishGameOverTeardown();
    }

    /** The original synchronous death-loss for one player: recovery-compass save,
     *  past-level-1 probabilistic per-slot loss, or level-1 single-item loss.
     *  Used for players who do not get the coin-flip screen. */
    private void applyLegacyGameOverLoss(ServerPlayerEntity p, CrafticsSavedData.PlayerData ld) {
            if (DeathProtectionComponent.hasRecoveryCompass(p)
                && DeathProtectionComponent.protectCombatInventory(p)) {
                // Particles + sound for recovery compass activation
                ServerWorld compassWorld = (ServerWorld) p.getEntityWorld();
                compassWorld.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL,
                    p.getX(), p.getY() + 1.0, p.getZ(),
                    40, 0.5, 0.8, 0.5, 0.02);
                compassWorld.spawnParticles(net.minecraft.particle.ParticleTypes.END_ROD,
                    p.getX(), p.getY() + 1.5, p.getZ(),
                    25, 0.4, 0.6, 0.4, 0.05);
                p.getWorld().playSound(null, p.getBlockPos(),
                    net.minecraft.sound.SoundEvents.BLOCK_RESPAWN_ANCHOR_CHARGE,
                    net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 1.2f);
                sendMessageTo(p, "\u00a76\u00a7l\u2728 Recovery Compass activated! \u00a7rYour inventory was saved.");
                return;
            }
            if (ld.isInBiomeRun() && ld.activeBiomeLevelIndex > 0) {
                // Past level 1: probabilistic loss. Backpack (main inventory) items are very
                // likely to be lost; hotbar, armor, offhand and accessories are far more likely
                // to survive. Both rates are config-tunable.
                double mainLoss = CrafticsMod.CONFIG.deathMainInventoryLossChance();
                double gearLoss = CrafticsMod.CONFIG.deathGearLossChance();
                int itemsLost = 0;
                // Iterate only the 36 main+hotbar slots (0-8 hotbar, 9-35 backpack); armor and
                // offhand are handled separately below so they never get rolled twice.
                int mainSlots = Math.min(36, p.getInventory().size());
                for (int slot = 0; slot < mainSlots; slot++) {
                    ItemStack stack = p.getInventory().getStack(slot);
                    if (stack.isEmpty()) continue;
                    Item item = stack.getItem();
                    if (item == com.crackedgames.craftics.item.ModItems.MOVE_ITEM || item instanceof com.crackedgames.craftics.item.GuideBookItem) continue;
                    double loss = slot < 9 ? gearLoss : mainLoss; // hotbar vs backpack
                    if (Math.random() < loss) {
                        p.getInventory().setStack(slot, ItemStack.EMPTY);
                        itemsLost++;
                    }
                }
                //? if <=1.21.4 {
                for (int slot = 0; slot < p.getInventory().armor.size(); slot++) {
                    if (!p.getInventory().armor.get(slot).isEmpty() && Math.random() < gearLoss) {
                        p.getInventory().armor.set(slot, ItemStack.EMPTY);
                        itemsLost++;
                    }
                }
                //?} else {
                /*for (net.minecraft.entity.EquipmentSlot armorSlot : new net.minecraft.entity.EquipmentSlot[]{
                        net.minecraft.entity.EquipmentSlot.HEAD, net.minecraft.entity.EquipmentSlot.CHEST,
                        net.minecraft.entity.EquipmentSlot.LEGS, net.minecraft.entity.EquipmentSlot.FEET}) {
                    if (!p.getEquippedStack(armorSlot).isEmpty() && Math.random() < gearLoss) {
                        p.equipStack(armorSlot, ItemStack.EMPTY);
                        itemsLost++;
                    }
                }
                *///?}
                if (!p.getOffHandStack().isEmpty() && Math.random() < gearLoss) {
                    p.setStackInHand(net.minecraft.util.Hand.OFF_HAND, ItemStack.EMPTY);
                    itemsLost++;
                }
                // Accessories (Artifacts trinkets, shields in accessory slots, etc.) roll at the gear rate.
                itemsLost += com.crackedgames.craftics.compat.artifacts.AccessoriesReflect
                    .clearAccessoriesChance(p, gearLoss);
                if (itemsLost > 0) {
                    sendMessageTo(p, "§c§lLost " + itemsLost + " item" + (itemsLost != 1 ? "s" : "") + "!");
                }
            } else {
                // First level or no run: remove one non-exempt item.
                // Prefer main hand, but fall back to hotbar/offhand/inventory so
                // holding the Move feather can't bypass the death penalty.
                ItemStack dropped = ItemStack.EMPTY;

                var mainHand = p.getMainHandStack();
                if (!mainHand.isEmpty()
                    && mainHand.getItem() != com.crackedgames.craftics.item.ModItems.MOVE_ITEM
                    && !(mainHand.getItem() instanceof com.crackedgames.craftics.item.GuideBookItem)) {
                    dropped = mainHand.copy();
                    //? if <=1.21.4 {
                    p.getInventory().setStack(p.getInventory().selectedSlot, ItemStack.EMPTY);
                    //?} else
                    /*p.getInventory().setStack(p.getInventory().getSelectedSlot(), ItemStack.EMPTY);*/
                }

                if (dropped.isEmpty()) {
                    for (int slot = 0; slot < 9; slot++) {
                        ItemStack stack = p.getInventory().getStack(slot);
                        if (stack.isEmpty()) continue;
                        Item item = stack.getItem();
                        if (item == com.crackedgames.craftics.item.ModItems.MOVE_ITEM || item instanceof com.crackedgames.craftics.item.GuideBookItem) continue;
                        dropped = stack.copy();
                        p.getInventory().setStack(slot, ItemStack.EMPTY);
                        break;
                    }
                }

                if (dropped.isEmpty()) {
                    ItemStack offhand = p.getOffHandStack();
                    if (!offhand.isEmpty()
                        && offhand.getItem() != com.crackedgames.craftics.item.ModItems.MOVE_ITEM
                        && !(offhand.getItem() instanceof com.crackedgames.craftics.item.GuideBookItem)) {
                        dropped = offhand.copy();
                        p.setStackInHand(net.minecraft.util.Hand.OFF_HAND, ItemStack.EMPTY);
                    }
                }

                if (dropped.isEmpty()) {
                    for (int slot = 9; slot < p.getInventory().size(); slot++) {
                        ItemStack stack = p.getInventory().getStack(slot);
                        if (stack.isEmpty()) continue;
                        Item item = stack.getItem();
                        if (item == com.crackedgames.craftics.item.ModItems.MOVE_ITEM || item instanceof com.crackedgames.craftics.item.GuideBookItem) continue;
                        dropped = stack.copy();
                        p.getInventory().setStack(slot, ItemStack.EMPTY);
                        break;
                    }
                }

                if (!dropped.isEmpty()) {
                    sendMessageTo(p, "§cDropped: " + dropped.getName().getString());
                }
            }
    }

    /** Shared game-over teardown tail: heal/clear participants, end the biome run,
     *  clear lost party mobs, teleport everyone home, and end combat. Runs exactly
     *  once per wipe - from the no-flip fall-through or from applyGameOverLossAndTeardown. */
    private void finishGameOverTeardown() {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        CrafticsSavedData data = CrafticsSavedData.get(world);
        CrafticsSavedData.PlayerData ld = data.getPlayerData(leaderUuid != null ? leaderUuid : player.getUuid());

        // Heal all participants (including dead spectators returning home)
        for (ServerPlayerEntity p : getAllParticipants()) {
            if (CrafticsMod.CONFIG.healBetweenLevels()) {
                p.setHealth(p.getMaxHealth());
            }
            p.clearStatusEffects();
        }

        // Reset biome run. Same two-record split as the Go Home path: the run was started on
        // whoever pressed Start but is ended here on the leader, so a wipe could leave the
        // starter permanently "in a run" - see clearMirroredBiomeRun.
        String endedBiomeId = ld.activeBiomeId;
        ld.endBiomeRun();
        clearMirroredBiomeRun(data, endedBiomeId, player, getAllParticipants(),
            leaderUuid != null ? leaderUuid : player.getUuid());
        ld.inCombat = false;
        data.markDirty();

        sendMessage("§7Returning to hub... Your biome run has ended.");
        // Per-player wallets: every survivor sees their OWN remaining balance, not the
        // leader's.
        for (ServerPlayerEntity p : getAllParticipants()) {
            sendMessageTo(p, "§7Remaining emeralds: "
                + data.getPlayerData(p.getUuid()).emeralds);
        }

        // Death = the run failed; the party mobs (and the mount) brought into it are
        // lost along with the dropped items -they do NOT return to the hub. Mark
        // petsRescued so endCombat()'s safety-net doesn't "rescue" the survivors back
        // home (the reported bug: "when you die in battle, the mounts come home when
        // they shouldn't"). endCombat() then discards the transient combat mobs.
        petsRescued = true;
        // Clear the lost party so the party HUD / next run don't reference ghost mobs.
        // Party-add enforces partyCap (PartyMobs), so the whole party is always brought
        // into the run -every entry here was just lost. (We clear rather than probe
        // world.getEntity(): at death the player is in the arena with the hub chunks
        // unloaded, so a lookup would false-null and is the wrong tool anyway.)
        try {
            java.util.UUID partyOwner = leaderUuid != null ? leaderUuid : player.getUuid();
            CrafticsSavedData.PlayerData ownerPd = data.getPlayerData(partyOwner);
            if (!ownerPd.getPartyMobs().isEmpty()) {
                ownerPd.getPartyMobs().clear();
                data.markDirty();
                ServerPlayerEntity ownerPlayer = world.getServer().getPlayerManager().getPlayer(partyOwner);
                if (ownerPlayer != null) com.crackedgames.craftics.network.PartyMobSync.sync(ownerPlayer);
            }
        } catch (Exception e) {
            CrafticsMod.LOGGER.warn("handleGameOver: party-mob clear failed: {}", e.getMessage());
        }

        // Teleport all party members home, restore daytime
        world.setTimeOfDay(6000);
        for (ServerPlayerEntity p : getAllParticipants()) {
            teleportToHub(p);
        }
        sendToAllParty(new ExitCombatPayload(false));
        endCombat();
    }

    /**
     * Hardcore variant of the game-over teardown: no penalties, no coin flip.
     * Resolves an active infinite run first (its stash restore is wiped anyway),
     * does the normal run-failure bookkeeping, ends combat, then hands off to
     * HardcoreIslands.wipe which empties + deletes the island dimension.
     */
    private void finishHardcoreTeardown(java.util.UUID owner, CrafticsSavedData.PlayerData ld) {
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        net.minecraft.server.MinecraftServer srv = world.getServer();
        CrafticsSavedData data = CrafticsSavedData.get(world);

        sendMessage("§4§l☠ HARDCORE DEFEAT §r§4- the island is lost.");

        // Infinite run on a hardcore island: resolve stash flags before the wipe
        // (restoreParticipant refills inventories, but the wipe below clears them
        // again; offline members are caught by the pending-wipe join hook, which
        // runs AFTER the join-time stash restore).
        // Bare infiniteActive on purpose: the island is being wiped, so a PARKED run must
        // die with it too - this is the one place that means "any run", not "the live one".
        if (ld.infiniteActive) {
            InfiniteRunManager.endRun(srv, owner, "hardcore defeat");
        }

        // Same run-failure bookkeeping as finishGameOverTeardown.
        ld.endBiomeRun();
        ld.inCombat = false;
        data.markDirty();
        // Dead run: pets are lost with it; block endCombat's rescue safety-net
        // (same reasoning as finishGameOverTeardown). The owner record reset in
        // HardcoreIslands.wipe clears the party-mob list itself.
        petsRescued = true;

        // Snapshot participants BEFORE endCombat clears party state.
        java.util.List<ServerPlayerEntity> participants =
            new java.util.ArrayList<>(getAllParticipants());

        // Downed party members sit in SPECTATOR; restore before the lobby move.
        for (ServerPlayerEntity p : participants) {
            if (p != null && !p.isRemoved() && !p.isDisconnected()) {
                p.changeGameMode(net.minecraft.world.GameMode.SURVIVAL);
            }
        }

        world.setTimeOfDay(6000);
        sendToAllParty(new ExitCombatPayload(false));
        endCombat();

        com.crackedgames.craftics.world.HardcoreIslands.wipe(srv, owner, participants);
    }

    /** Apply every pending player's pre-decided losses, then run the shared teardown. */
    private void applyGameOverLossAndTeardown() {
        if (phase != CombatPhase.GAME_OVER_FLIP) return; // already applied (late ack vs timeout race)
        phase = CombatPhase.GAME_OVER;                   // close the window for any further ack/tick
        for (var entry : pendingGameOverLoss.entrySet()) {
            ServerPlayerEntity p = server != null ? server.getPlayerManager().getPlayer(entry.getKey()) : null;
            int lost = 0;
            for (PendingItemRoll r : entry.getValue()) {
                lost += r.lostQ();
                if (p == null) continue; // disconnected - their items still count as lost server-side
                // Remove exactly `lose` units from each slot in this group.
                for (SlotLoss sl : r.slots()) {
                    if (sl.lose() <= 0) continue;
                    removeUnitsFromSlot(p, sl);
                }
            }
            if (p != null && lost > 0) {
                sendMessageTo(p, "§c§lLost " + lost + " item" + (lost != 1 ? "s" : "") + "!");
            }
        }
        pendingGameOverLoss.clear();
        gameOverAcks.clear();
        gameOverWaiting.clear();
        finishGameOverTeardown();
    }

    /** Remove {@code sl.lose()} units from the physical slot {@code sl} refers to.
     *  Armor/offhand/accessory stacks are size 1 so any loss clears them; main slots
     *  decrement by the lost count (clearing the slot if it empties). */
    private void removeUnitsFromSlot(ServerPlayerEntity p, SlotLoss sl) {
        int lose = sl.lose();
        switch (sl.kind()) {
            case 0 -> {
                ItemStack s = p.getInventory().getStack(sl.index());
                if (s.isEmpty()) return;
                if (lose >= s.getCount()) p.getInventory().setStack(sl.index(), ItemStack.EMPTY);
                else s.decrement(lose);
            }
            case 1 -> {
                //? if <=1.21.4 {
                p.getInventory().armor.set(sl.index(), ItemStack.EMPTY);
                //?} else {
                /*net.minecraft.entity.EquipmentSlot[] as = {
                        net.minecraft.entity.EquipmentSlot.HEAD, net.minecraft.entity.EquipmentSlot.CHEST,
                        net.minecraft.entity.EquipmentSlot.LEGS, net.minecraft.entity.EquipmentSlot.FEET};
                if (sl.index() >= 0 && sl.index() < as.length) p.equipStack(as[sl.index()], ItemStack.EMPTY);
                *///?}
            }
            case 2 -> p.setStackInHand(net.minecraft.util.Hand.OFF_HAND, ItemStack.EMPTY);
            case 3 -> com.crackedgames.craftics.compat.artifacts.AccessoriesReflect
                .clearAccessoryAt(p, sl.accContainer(), sl.accKind(), sl.accSlot());
            // Backpack: index is the bay it is worn in, accSlot the slot inside it.
            case 4 -> com.crackedgames.craftics.compat.backpacked.BackpackedCompat
                .removeUnits(p, sl.index(), sl.accSlot(), lose);
        }
    }

    /** Tick the GAME_OVER_FLIP hold; apply outcomes when the client timeout expires. */
    private void tickGameOverFlip() {
        if (gameOverFlipTimer > 0) gameOverFlipTimer--;
        if (gameOverFlipTimer <= 0) {
            applyGameOverLossAndTeardown();
        }
    }

    /** A player's client finished the coin-flip animation. Apply once all ack or on timeout. */
    public void handleGameOverAck(ServerPlayerEntity p) {
        if (phase != CombatPhase.GAME_OVER_FLIP) return;
        gameOverAcks.add(p.getUuid());
        if (gameOverAcks.containsAll(gameOverWaiting)) {
            applyGameOverLossAndTeardown();
        }
    }

    private void killEnemy(CombatEntity enemy) {
        markBurningOnDeath(enemy);
        enemy.takeDamage(9999);
        // A destroyed decoy's armor stand must go with it.
        clearDecoyVisual(enemy);
        // Silk Touch on a wild hive hands over the hive itself, so a forest
        // obstacle becomes a reusable ally-summoning tool.
        dropHiveOnSilkTouch(enemy);
        // Deeper-and-Darker props: infested sculk erupts, the vase either pays out
        // or bursts. Both consult the breaker's Silk Touch, so this must run on the
        // kill path where the weapon is still known.
        breakDeepDarkProp(enemy);
        // A destroyed end crystal goes off, whatever destroyed it.
        tryDetonateEndCrystal(enemy);
        // Roll equipment drops on direct kills too (DOTs are handled by checkAndHandleDeath).
        // Mirror clones (Void Walker decoys) never drop loot -they now have real HP, so a
        // hazard-knockback kill routes through killEnemy instead of the dispel path; mirror
        // checkAndHandleDeath's clone guard here so they grant no loot/XP/streak.
        if (!enemy.isAlly() && !enemy.isMirrorClone() && !enemy.isDeathProcessed()
                && enemy.getMobEntity() != null) {
            rollMobEquipmentDrops(enemy);
        }
        // Weapon Fortune + Silk Touch: the tool enchants are dead weight on an axe/shovel/hoe
        // used as a weapon, so give them a killing-blow effect. Same real-kill guard as loot.
        if (!enemy.isAlly() && !enemy.isMirrorClone() && enemy.getMobEntity() != null && player != null) {
            net.minecraft.item.ItemStack weapon = player.getMainHandStack();
            // Fortune (weapon): 5% per level for a bonus loot roll on this enemy.
            int wFortune = PlayerCombatStats.getEnchantLevel(weapon, "minecraft:fortune");
            if (wFortune > 0 && Math.random() < 0.05 * wFortune) {
                rollMobEquipmentDrops(enemy); // an extra roll of the enemy's own drops
                sendMessage("§6✦ Fortune! Extra loot from " + enemy.getDisplayName() + ".");
            }
            // Silk Touch (weapon): 25% per level (capped 100%) to drop the enemy's head.
            int wSilk = PlayerCombatStats.getEnchantLevel(weapon, "minecraft:silk_touch");
            if (wSilk > 0) {
                double headChance = Math.min(1.0, 0.25 * wSilk);
                net.minecraft.item.Item head = getMobHeadForType(enemy.getEntityTypeId());
                if (head != null && Math.random() < headChance) {
                    net.minecraft.item.ItemStack headStack = new net.minecraft.item.ItemStack(head);
                    LootDelivery.deliver(player, headStack);
                    sendMessage("§7✦ Silk Touch: " + enemy.getDisplayName() + "'s head drops.");
                }
            }
        }
        // Ally died: drop from the persistent battle-party list right now so
        // the cap-aware spawn-egg gate, party HUD, and post-fight pet collector
        // all see the slot freed without waiting for combat to end.
        if (enemy.isAlly() && enemy.getMobEntity() != null && player != null
                && enemy.getMobEntity().getEntityWorld() instanceof ServerWorld dw) {
            java.util.UUID mobUuid = enemy.getMobEntity().getUuid();
            java.util.UUID ownerId = enemy.getOwnerUuid() != null
                ? enemy.getOwnerUuid() : player.getUuid();
            com.crackedgames.craftics.world.CrafticsSavedData savedData =
                com.crackedgames.craftics.world.CrafticsSavedData.get(dw);
            com.crackedgames.craftics.world.CrafticsSavedData.PlayerData pd =
                savedData.getPlayerData(ownerId);
            if (pd.getPartyMobs().remove(mobUuid)) {
                savedData.markDirty();
            }
        }
        // Background bosses occupy many manually-registered tiles -clear them all
        if (enemy.isBackgroundBoss()) {
            arena.getOccupants().values().removeIf(e -> e == enemy);
        } else {
            arena.removeEntity(enemy);
        }
        // Only real enemy kills count toward streaks / rewards. A dying ally
        // (killed by an enemy) routes through here too, but it must not award
        // kill-streak emeralds, Symbiote heals, AP refunds, or loot procs.
        // Mirror clones are excluded for the same reason -they are decoys, not kills.
        //
        // Projectiles are excluded on the same grounds and are the most common case: a
        // boss fireball, wither skull or seeker is a CombatEntity so it can occupy grid
        // tiles and be moved by the AI, and it is retired through killEnemy the instant it
        // lands - on a player, on a wall, on anything. That is the projectile DOING ITS
        // JOB, so every hit the party took was crediting the party with a kill: streak up,
        // bonus emeralds, Symbiote heal, AP refunds, and totalEnemiesKilled inflated.
        if (!enemy.isAlly() && !enemy.isMirrorClone() && !enemy.isProjectile()) {
            onEnemyKilled(enemy); // track kill streak
        }
        // Clean up visual projectile entity
        if (enemy.isProjectile()) {
            killVisualProjectileNear(enemy);
        }
        MobEntity mob = enemy.getMobEntity();
        if (mob == null && player != null) {
            // Non-mob entity (e.g., end crystal) -discard the world entity by ID
            ServerWorld deathWorld = (ServerWorld) player.getEntityWorld();
            net.minecraft.entity.Entity rawEnt = deathWorld.getEntityById(enemy.getEntityId());
            if (rawEnt != null) rawEnt.discard();
        }
        if (mob != null && mob.isAlive()) {
            // Background boss death: big explosion + scream, then discard
            if (enemy.isBackgroundBoss() && mob instanceof net.minecraft.entity.mob.GhastEntity ghast) {
                ghast.setShooting(true); // scream face
                ServerWorld world = (ServerWorld) player.getEntityWorld();
                world.playSound(null, mob.getBlockPos(),
                    net.minecraft.sound.SoundEvents.ENTITY_GHAST_DEATH,
                    net.minecraft.sound.SoundCategory.HOSTILE, 2.0f, 0.8f);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.EXPLOSION_EMITTER,
                    mob.getX(), mob.getY() + 2.0, mob.getZ(), 3, 1.0, 1.0, 1.0, 0.0);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.SOUL,
                    mob.getX(), mob.getY() + 2.0, mob.getZ(), 30, 2.0, 2.0, 2.0, 0.05);
                world.spawnParticles(net.minecraft.particle.ParticleTypes.LARGE_SMOKE,
                    mob.getX(), mob.getY() + 1.0, mob.getZ(), 20, 2.0, 1.5, 2.0, 0.03);
            }
            // Stack passenger cleanup: a force-kill on the base of a stack
            // mob (counterattack, smite, sweep, etc.) bypasses
            // transformStackLayer, so the cosmetic baby zombie / skeleton /
            // slime riding on top would otherwise stay in the world as a
            // ghost mob -visible but not in the combat entity list.
            clearStackPassengers(mob);
            // Death shrink -mob shrinks to 0 then gets discarded after delay
            float scale = startDeathShrink(mob);
            dyingMobs.add(new DyingMob(mob, 20, scale));
        }
        // Check if all enemies are dead or allied
        boolean allDead = !anyEnemyBlockingVictory();
        if (allDead) {
            handleVictory();
        }
    }

    /**
     * Delivers a loot stack to a recipient; any portion that did not fit is
     * recorded in {@code overflow} keyed by the recipient's UUID.
     */
    private static void deliverLoot(ServerPlayerEntity recipient, ItemStack stack,
                                    java.util.Map<java.util.UUID, List<ItemStack>> overflow) {
        ItemStack leftover = LootDelivery.deliver(recipient, stack);
        if (leftover != null && !leftover.isEmpty()) {
            overflow.computeIfAbsent(recipient.getUuid(), k -> new ArrayList<>()).add(leftover);
        }
    }

    /**
     * Opens the post-victory loot screen for one player, pre-filled with their overflow.
     * Returns whether the screen actually opened (false if the player already had a screen open).
     */
    private boolean openLootScreen(ServerPlayerEntity p, List<ItemStack> overflowItems) {
        net.minecraft.inventory.SimpleInventory lootInv = new net.minecraft.inventory.SimpleInventory(
            com.crackedgames.craftics.screen.LootManagementScreenHandler.LOOT_SLOTS);
        int placed = 0;
        for (ItemStack item : overflowItems) {
            if (placed >= com.crackedgames.craftics.screen.LootManagementScreenHandler.LOOT_SLOTS) {
                CrafticsMod.LOGGER.warn(
                    "[Craftics] Loot overflow exceeded {} slots for {} -{} item(s) discarded",
                    com.crackedgames.craftics.screen.LootManagementScreenHandler.LOOT_SLOTS,
                    p.getName().getString(), overflowItems.size() - placed);
                break;
            }
            lootInv.setStack(placed++, item);
        }
        return p.openHandledScreen(new net.minecraft.screen.SimpleNamedScreenHandlerFactory(
            (syncId, playerInv, viewer) ->
                new com.crackedgames.craftics.screen.LootManagementScreenHandler(syncId, playerInv, lootInv),
            net.minecraft.text.Text.literal("Battle Loot"))).isPresent();
    }

    /** Called by the loot screen handler when a player closes their loot screen. */
    public void handleLootScreenClosed(ServerPlayerEntity p) {
        if (lootPendingPlayers.remove(p.getUuid()) && lootPendingPlayers.isEmpty()) {
            if (raidBossContext != null) {
                finishRaidBossVictory();
                return;
            }
            continueVictoryAfterLoot();
        }
    }

    private void handleVictory() {
        // Re-entrancy gate. Twenty-odd call sites all ask "is every enemy dead?" from
        // different places - DOT ticks, death handling, item use, turn end - and several can
        // run in the SAME tick off one killing blow. Each entry minted a fresh pendingVictory,
        // and each pendingVictory bought its own advanceBiomeRun(): two paths meant +2 levels,
        // three meant +3. That is the "Deep Dark level 3 -> 6, landed in Nether Wastes I"
        // report - the run skipped its own boss and walked into the next biome.
        //
        // The downstream consume-once token in continueVictoryAfterLoot() cannot help here:
        // it stops that method being re-entered, but a second handleVictory() just hands it a
        // brand new token. The duplicate has to be rejected at the entry point, and phase is
        // the state that says the level is already won.
        if (phase == CombatPhase.LEVEL_COMPLETE) return;
        // Before anything else: take back the screen. Loot delivery below can open a screen of
        // its own, so this has to happen first or it would close the one it just opened.
        closeForeignScreens();
        // Recorded at the entry point, before anything downstream can reset the fight state:
        // by the time the feat check runs, suddenDeath has to still be true, and the re-entry
        // gate above guarantees this line runs exactly once per win.
        if (suddenDeath) achievementTracker.recordSuddenDeathWin();

        // DAILY RAID BOSS: rewards and teardown are entirely our own. The biome victory
        // path below unlocks biomes, advances the run and offers a next level, none of
        // which mean anything for a raid, so it never runs.
        if (raidBossContext != null) {
            phase = CombatPhase.LEVEL_COMPLETE;
            awardRaidBossRewards();
            return;
        }

        // Miniboss gate: some mechanics hold an extra objective beyond "enemies dead"
        // (e.g. graves still standing). Most mechanics use the default isComplete()==true,
        // so this is a no-op for them - only mechanics with an extra objective hold victory
        // here. The round hook re-checks next round; combat continues in the meantime.
        if (activeMiniboss != null && !activeMiniboss.isComplete(buildMinibossCtx())) {
            return;
        }

        // Bastille gate: same shape as the raid gate below - a cleared field with
        // garrisons left summons the next one instead of winning.
        if (tryAdvanceBastilleWave()) {
            return;
        }

        // Raid gate: clearing the field is NOT winning while waves remain. Reward the
        // early clear by bringing the next wave in immediately (no telegraph wait) rather
        // than making the party stand around for the timer.
        if (raidActive && (raidRemainingPillagers > 0 || !raidFinaleSpawned)) {
            sendMessage("§cNo time to rest - the next wave pours in!");
            spawnRaidWave();
            raidRoundsUntilWave = RAID_WAVE_INTERVAL;
            return;
        }
        if (raidActive) {
            markRaidDefeated();
        }

        // If a thrown trident was lying on the arena when the final blow landed,
        // auto-recover it -otherwise the player loses it permanently on level end.
        if (!droppedTridents.isEmpty()) {
            int recovered = droppedTridents.size();
            returnDroppedTrident();
            sendMessage(recovered == 1
                ? "§3\u21BA Recovered your trident!"
                : "§3\u21BA Recovered " + recovered + " thrown tridents!");
        }

        // Diagnostic: in party combat, this.player is the current turn player
        // (whoever landed the killing blow), NOT the combat leader. Flag the
        // divergence so any downstream code that still uses this.player as a
        // proxy for "the leader" leaves a trail in the log.
        if (isTurnPlayerDivergentFromLeader()) {
            ServerPlayerEntity realLeader = getCombatLeader();
            CrafticsMod.LOGGER.info(
                "handleVictory: turn player '{}' ≠ combat leader '{}' -any leader-specific logic below must use getCombatLeader()",
                player.getName().getString(),
                realLeader != null ? realLeader.getName().getString() : leaderUuid);
        }

        // Sound: victory
        if (player != null) {
            player.getWorld().playSound(null, player.getBlockPos(),
                net.minecraft.sound.SoundEvents.UI_TOAST_CHALLENGE_COMPLETE,
                net.minecraft.sound.SoundCategory.PLAYERS, 1.0f, 1.0f);
        }
        phase = CombatPhase.LEVEL_COMPLETE;
        // The level is over, so its save points are too: leaving them would let a player walk back
        // into a level they already cleared and resume a fight that no longer exists.
        clearResumeSnapshots();
        sendMessage("§a§l*** VICTORY! ***");
        fireEffectHook(h -> h.onCombatEnd(effectContext));

        // Revive fallen party members with 2 hearts (4 HP)
        if (!deadPartyMembers.isEmpty()) {
            for (ServerPlayerEntity p : getAllParticipants()) {
                if (deadPartyMembers.contains(p.getUuid())) {
                    p.setHealth(4); // 2 hearts
                    p.clearStatusEffects();
                    p.changeGameMode(net.minecraft.world.GameMode.ADVENTURE);
                    sendMessageTo(p, "§a§l\u2726 REVIVED! §rYour party won -you're back with 2 hearts!");
                }
            }
            sendMessage("§aFallen allies have been revived!");
            deadPartyMembers.clear();
        }

        // Pillager Camp / Bastille payouts (It Takes a Pillage). Per participant, on top
        // of the ordinary per-mob loot below. The camp's headline is the Bastille Map;
        // the bastille's is the ominous-tier haul - it cost three consecutive fights.
        if (levelDef instanceof PillageEvents.CampLevelDef
                || levelDef instanceof PillageEvents.BastilleLevelDef) {
            boolean bastille = levelDef instanceof PillageEvents.BastilleLevelDef;
            ServerWorld rewardWorld = (ServerWorld) player.getEntityWorld();
            var rewardData = com.crackedgames.craftics.world.CrafticsSavedData.get(rewardWorld);
            java.util.Random rewardRng = new java.util.Random();
            int purse = bastille
                ? PillageEvents.bastilleEmeralds(pendingEventBiomeOrdinal)
                : PillageEvents.campEmeralds(pendingEventBiomeOrdinal);
            for (ServerPlayerEntity member : getAllParticipants()) {
                if (member == null || member.isRemoved() || member.isDisconnected()) continue;
                rewardData.getPlayerData(member.getUuid()).emeralds += purse;
                if (bastille) {
                    PillageEvents.give(member, TrialChamberEvent.rollHeavyGear(rewardWorld, rewardRng));
                    ItemStack artifact = com.crackedgames.craftics.compat.artifacts.ArtifactRoller.rollOne();
                    if (!artifact.isEmpty()) PillageEvents.give(member, artifact);
                    for (ItemStack material : PillageEvents.bastilleMaterials(rewardRng)) {
                        PillageEvents.give(member, material);
                    }
                } else {
                    PillageEvents.give(member, PillageEvents.createBastilleMap());
                }
            }
            rewardData.markDirty();
            sendMessage(bastille
                ? "§6§l⚑ The Bastille falls! §r§6+" + purse
                    + " emeralds, spoils from its armory, and its vault cracked open."
                : "§6§l⚑ The camp is routed! §r§6+" + purse
                    + " emeralds - and a map marking the road to their Bastille.");
        }

        // Per-mob loot now routes to the killer only, not every party member.
        // Arena/level-completion bonuses below still go to everyone -that's
        // the shared "you beat the wave" reward and shouldn't be one-player.
        java.util.Map<java.util.UUID, List<ItemStack>> lootOverflow = new java.util.HashMap<>();
        int luckBonusItems = PlayerProgression.get((ServerWorld) player.getEntityWorld())
            .getStats(player).getPoints(PlayerProgression.Stat.LUCK);
        if (activeMiniboss != null) {
            luckBonusItems += 1; // miniboss bonus: one extra loot roll
        }
        // One merged chat line per distinct item for the whole victory burst.
        // Announcing each stack as it rolled printed "+ 1x Bone" once per
        // skeleton; the burst is delivered in one breath, so it reads as one.
        List<ItemStack> lootChatSummary = new ArrayList<>();
        for (CombatEntity enemy : enemies) {
            // The enemies list also holds the player's allies. A *surviving*
            // ally is not loot (a bee ally that lives must not award honey).
            // A *fallen* ally does drop its mob loot, same as any defeated mob.
            if (enemy.isAlly() && enemy.isAlive()) continue;
            // Skip drops for creepers that self-exploded (rewards killing them properly)
            if (enemy.isSelfExploded()) continue;
            List<ServerPlayerEntity> killerOnly = resolveKillerRecipients(enemy);
            List<ItemStack> displayDrops = null;
            for (ServerPlayerEntity recipient : killerOnly) {
                List<ItemStack> drops = getMobDrops(enemy.getEntityTypeId());
                // Burned to death = already cooked. Applied per roll so the meat that
                // actually lands in the bag is the meat announced in chat.
                if (enemy.wasBurningOnDeath()) drops = cookDropsOverFire(drops);
                // Snapshot copies: deliverLoot consumes the stacks it is handed.
                if (displayDrops == null) {
                    displayDrops = new ArrayList<>();
                    for (ItemStack d : drops) displayDrops.add(d.copy());
                }
                for (ItemStack drop : drops) {
                    if (drop.isEmpty() || drop.getCount() <= 0) continue;
                    if (luckBonusItems > 0 && Math.random() < (luckBonusItems * 0.20)) {
                        drop.setCount(drop.getCount() + 1);
                    }
                    deliverLoot(recipient, drop, lootOverflow);
                }
            }
            // Broadcast a representative message (leader's perspective). Reuses the FIRST
            // recipient's actual roll: rolling a fresh set here announced items nobody was
            // given, and would have advertised raw meat for a kill that handed out cooked.
            if (displayDrops == null) displayDrops = getMobDrops(enemy.getEntityTypeId());
            for (ItemStack drop : displayDrops) {
                if (drop.isEmpty() || drop.getCount() <= 0) continue;
                mergeLootChatLine(lootChatSummary, drop);
            }
            // Rare goat horn drop -per-mob, killer-only.
            if ("minecraft:goat".equals(enemy.getEntityTypeId())) {
                for (ServerPlayerEntity recipient : killerOnly) {
                    if (Math.random() < CrafticsMod.CONFIG.goatHornDropChance() + luckBonusItems * 0.02) {
                        ItemStack horn = GoatHornEffects.createRandomHorn(player.getRegistryManager());
                        if (horn != null) {
                            deliverLoot(recipient, horn, lootOverflow);
                            sendMessageTo(recipient, "§6§l+ Goat Horn! " + horn.getName().getString());
                        }
                    }
                }
            }
        }
        // Shared list used by arena/completion loot below -that stays party-wide.
        List<ServerPlayerEntity> rewardRecipients = getAllParticipants();

        // Give level completion loot to each party participant individually
        if (levelDef != null) {
            ServerWorld lootWorld = (ServerWorld) player.getEntityWorld();
            com.crackedgames.craftics.level.BiomeTemplate lootBiome = null;
            if (levelDef instanceof com.crackedgames.craftics.level.GeneratedLevelDefinition gld) {
                lootBiome = gld.getBiomeTemplate();
            }
            final com.crackedgames.craftics.level.BiomeTemplate finalLootBiome = lootBiome;
            // Each player rolls their own completion loot (Luck boosts item counts)
            for (ServerPlayerEntity recipient : rewardRecipients) {
                java.util.List<ItemStack> lootItems = new java.util.ArrayList<>(levelDef.rollCompletionLoot(lootWorld));
                fireEffectHook(h -> h.onLootRoll(effectContext, lootItems));
                List<ItemStack> loot = new ArrayList<>();
                for (ItemStack stack : lootItems) {
                    loot.add(stack.isOf(Items.ENCHANTED_BOOK) ? randomEnchantedBook(lootWorld, stack.getCount(), finalLootBiome) : stack);
                }
                for (ItemStack item : loot) {
                    if (item.isEmpty() || item.getCount() <= 0) continue; // skip empty/air rolls
                    if (luckBonusItems > 0 && Math.random() < (luckBonusItems * 0.20)) {
                        item.setCount(item.getCount() + 1);
                    }
                    deliverLoot(recipient, item, lootOverflow);
                }
            }
            // Show a representative loot message
            List<ItemStack> displayLoot = levelDef.rollCompletionLoot(lootWorld);
            for (ItemStack item : displayLoot) {
                if (item.isEmpty() || item.getCount() <= 0) continue; // never show "0x Air"
                mergeLootChatLine(lootChatSummary, item);
            }
        }
        for (ItemStack line : lootChatSummary) {
            sendMessage("§e+ " + line.getCount() + "x " + line.getName().getString());
        }

        // Rare pottery sherd drop (Luck boosts chance)
        float sherdChance = CrafticsMod.CONFIG.potterySherdDropChance() + luckBonusItems * 0.01f;
        if (sherdChance > 0 && Math.random() < sherdChance) {
            var sherdList = new ArrayList<>(PotterySherdSpells.POTTERY_SHERDS);
            Item sherdItem = sherdList.get(new java.util.Random().nextInt(sherdList.size()));
            ItemStack sherdStack = new ItemStack(sherdItem);
            for (ServerPlayerEntity recipient : rewardRecipients) {
                deliverLoot(recipient, sherdStack.copy(), lootOverflow);
            }
            sendMessage("§d§l✦ RARE DROP: " + sherdStack.getName().getString() + "!");
        }

        // Rare spawn egg drop (Luck and Pet affinity boost the chance) -summons a temporary
        // ally in combat. The roll is one shared roll for the whole party, so it reads the
        // party's best beastmaster rather than the leader alone: whoever invested in Pet
        // widens the pipeline for everyone standing with them.
        float eggChance = 0.04f + luckBonusItems * 0.01f
            + bestPetAffinity(rewardRecipients) * PET_AFFINITY_EGG_CHANCE_PER_POINT;
        if (eggChance > 0 && Math.random() < eggChance) {
            Item eggItem = SPAWN_EGG_DROP_POOL[new java.util.Random().nextInt(SPAWN_EGG_DROP_POOL.length)];
            ItemStack eggStack = new ItemStack(eggItem);
            for (ServerPlayerEntity recipient : rewardRecipients) {
                deliverLoot(recipient, eggStack.copy(), lootOverflow);
            }
            sendMessage("§e§l✦ RARE DROP: " + eggStack.getName().getString() + "!");
        }

        // Award emeralds (scales with biome progression)
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        CrafticsSavedData data = CrafticsSavedData.get(world);
        java.util.UUID dataOwner = leaderUuid != null ? leaderUuid : player.getUuid();
        CrafticsSavedData.PlayerData ld = data.getPlayerData(dataOwner);
        int biomeIndex = ld.activeBiomeLevelIndex;
        com.crackedgames.craftics.level.BiomeTemplate biomeTemplate = null;
        if (levelDef instanceof com.crackedgames.craftics.level.GeneratedLevelDefinition gld) {
            biomeTemplate = gld.getBiomeTemplate();
        }
        // Fallback: look up biome from active biome run (covers event levels like treasure vault)
        if (biomeTemplate == null && ld.isInBiomeRun()) {
            for (var b : com.crackedgames.craftics.level.BiomeRegistry.getAllBiomes()) {
                if (b.biomeId.equals(ld.activeBiomeId)) { biomeTemplate = b; break; }
            }
        }
        // Use active-campaign order for biome progression (not registry order).
        // INFINITE MODE: reward scaling tracks the run depth (virtualOrdinal), not the
        // rolled biome's campaign position - otherwise the payout for the same run
        // depth swings with whichever biome the roll happened to land on (plains pays
        // ordinal-0 money at depth 50, a late biome pays campaign-endgame money at
        // depth 1). Mirrors the spawn path's ordinal swap.
        ld.initBranchIfNeeded();
        com.crackedgames.craftics.level.InfiniteSpec victoryInfSpec =
            levelDef instanceof com.crackedgames.craftics.level.GeneratedLevelDefinition vgld
                ? vgld.getInfiniteSpec() : null;
        int biomeOrdinal;
        if (victoryInfSpec != null) {
            biomeOrdinal = Math.max(0, victoryInfSpec.virtualOrdinal());
        } else {
            biomeOrdinal = biomeTemplate != null
                ? com.crackedgames.craftics.level.campaign.CampaignManager
                    .ordinalOf(biomeTemplate.biomeId, Math.max(0, ld.branchChoice))
                : 0;
            if (biomeOrdinal < 0) biomeOrdinal = 0;
        }
        // Event fights (trials, raids, ambushes, addon fights) carry synthetic 9000+ level
        // numbers. isBossLevel clamps ">= last level", so a synthetic id would read as "boss
        // of the current biome" and process an EVENT victory as a BIOME COMPLETE: wrong
        // unlock, endBiomeRun, teleport home - while pendingNextLevelDef/lastFightWasTrial
        // stay armed and warp the NEXT run into the old biome (the wrong-biome ping-pong).
        boolean isBoss = biomeTemplate != null
            && arena.getLevelNumber() < com.crackedgames.craftics.level.LevelDefinition.SYNTHETIC_LEVEL_BASE
            && biomeTemplate.isBossLevel(arena.getLevelNumber());
        // Rare MoreTotems totem drop -boss kills only (Luck boosts chance). No-op when the
        // mod is absent (rollOne returns EMPTY).
        if (isBoss) {
            float totemChance = (float) CrafticsMod.CONFIG.totemDropChance() + luckBonusItems * 0.01f;
            if (Math.random() < totemChance) {
                ItemStack totemDrop = com.crackedgames.craftics.compat.moretotems.MoreTotemsLootRoller.rollOne();
                if (!totemDrop.isEmpty()) {
                    for (ServerPlayerEntity recipient : rewardRecipients) {
                        deliverLoot(recipient, totemDrop.copy(), lootOverflow);
                    }
                    sendMessage("§d§l✦ RARE DROP: " + totemDrop.getName().getString() + "!");
                }
            }
        }
        // Rare unique weapon drop -boss kills only (Luck boosts chance). Each recipient
        // rolls independently, preferring uniques they don't already carry. Simply Swords
        // and Simply Bows share ONE drop chance and one coin-flip between them, so having
        // both mods installed widens the pool without doubling how often it pays out.
        // No-op when neither mod is present (each roller returns EMPTY).
        if (isBoss) {
            float uniqueChance = (float) CrafticsMod.CONFIG.uniqueWeaponDropChance() + luckBonusItems * 0.01f;
            if (Math.random() < uniqueChance) {
                for (ServerPlayerEntity recipient : rewardRecipients) {
                    ItemStack uniqueDrop = rollUniqueWeapon(recipient);
                    if (!uniqueDrop.isEmpty()) {
                        deliverLoot(recipient, uniqueDrop.copy(), lootOverflow);
                        sendMessage("§6§l⚔ LEGENDARY DROP: " + uniqueDrop.getName().getString() + "!");
                    }
                }
            }
        }
        // Resourceful stat: +1 emerald per point (uses leader's stat)
        PlayerProgression victoryProg = PlayerProgression.get(world);
        int resourcefulBonus = victoryProg.getStats(player).getPoints(PlayerProgression.Stat.RESOURCEFUL) * PROG_RESOURCEFUL_PER_POINT;
        // The base emerald reward scales with how many enemies this level had, so a few-enemy
        // early level pays less than a full late one. Boss levels keep their flat reward (their
        // small add-crew shouldn't shrink the payout). Resourceful is a flat player bonus on top.
        int baseEmeralds = com.crackedgames.craftics.CrafticsMod.CONFIG.emeraldBaseReward() + biomeOrdinal / 3;
        if (!isBoss && levelDef != null) {
            double emeraldMult = com.crackedgames.craftics.level.BiomeDifficulty.rewardMultiplier(
                levelDef.getEnemySpawns().length);
            baseEmeralds = Math.max(1, (int) Math.round(baseEmeralds * emeraldMult));
        }
        if (activeMiniboss != null) {
            baseEmeralds += 3; // miniboss bonus emeralds
        }
        int emeraldsEarned = baseEmeralds + (isBoss ? 3 : 0) + resourcefulBonus;
        // FORTUNE_PEAK set bonus: double emerald rewards
        if (activeTrimScan != null && activeTrimScan.setBonus() == TrimEffects.SetBonus.FORTUNE_PEAK) {
            emeraldsEarned *= 2;
            sendMessage("§6§l✦ Fortune's Peak! §r§6Emerald rewards doubled!");
        }
        // Addon combat effects: modify emerald gain
        emeraldsEarned = fireEffectHookChained(emeraldsEarned, (h, amt) -> h.onEmeraldGain(effectContext, amt));
        // Award emeralds to all party members via per-player data
        for (ServerPlayerEntity recipient : rewardRecipients) {
            CrafticsSavedData.PlayerData pd = data.getPlayerData(recipient.getUuid());
            pd.addEmeralds(emeraldsEarned);
        }
        data.markDirty();
        sendMessage("§a+ " + emeraldsEarned + " Emeralds");

        // Per-island boss-kill scaling: record this defeat so the NEXT encounter
        // with the same boss on this island spawns with +bossKillHpScale HP.
        // Infinite-run kills are excluded - their bosses are randomized stand-ins
        // and must never inflate the campaign's per-boss HP ramp.
        if (isBoss && biomeTemplate != null && biomeTemplate.biomeId != null
                && currentInfiniteSpec() == null) {
            java.util.UUID owner = worldOwnerUuid;
            if (owner != null) {
                CrafticsSavedData killData = CrafticsSavedData.get((net.minecraft.server.world.ServerWorld) player.getEntityWorld());
                killData.getPlayerData(owner).incrementBossKills(biomeTemplate.biomeId);
                killData.markDirty();
            }
        }

        // Boss trim template drops (semi-rare: ~35% chance, Luck boosts)
        if (isBoss && Math.random() < CrafticsMod.CONFIG.trimDropChance() + luckBonusItems * 0.02) {
            // Determine dimension from the active campaign's region for this biome
            String dimension = "overworld"; // sensible default if region is unknown/null
            if (biomeTemplate != null) {
                com.crackedgames.craftics.level.campaign.CampaignRegion region =
                    com.crackedgames.craftics.level.campaign.CampaignManager.regionOf(biomeTemplate.biomeId);
                if (region != null) dimension = region.id();
            }

            net.minecraft.item.Item[] trimPool = TrimEffects.getBossDropTrims(dimension);
            if (trimPool.length > 0) {
                // Avoid giving the same trim back-to-back
                java.util.List<net.minecraft.item.Item> candidates = new java.util.ArrayList<>();
                for (net.minecraft.item.Item t : trimPool) {
                    if (t != lastDroppedTrim) candidates.add(t);
                }
                if (candidates.isEmpty()) {
                    for (net.minecraft.item.Item t : trimPool) candidates.add(t);
                }
                java.util.Random trimRng = new java.util.Random();
                String lastName = null;
                for (ServerPlayerEntity recipient : rewardRecipients) {
                    net.minecraft.item.Item trimItem =
                        candidates.get(trimRng.nextInt(candidates.size()));
                    lastDroppedTrim = trimItem; // best-effort anti-repeat across drops
                    ItemStack trimStack = new ItemStack(trimItem);
                    deliverLoot(recipient, trimStack.copy(), lootOverflow);
                    lastName = trimStack.getName().getString();
                }
                if (lastName != null) {
                    sendMessage("\u00a7b\u00a7l\u2726 RARE DROP: " + lastName + "!");
                }

                // Unlock "How Trims Work" guide entry for all recipients
                ServerWorld trimWorld = (ServerWorld) player.getEntityWorld();
                CrafticsSavedData trimData = CrafticsSavedData.get(trimWorld);
                for (ServerPlayerEntity recipient : rewardRecipients) {
                    CrafticsSavedData.PlayerData rpd = trimData.getPlayerData(recipient.getUuid());
                    if (rpd.unlockGuideEntry("How Trims Work")) {
                        trimData.markDirty();
                        sendGuideBookSync(recipient, rpd);
                    }
                }
            }
        }

        // Stash the victory context, then route through the loot screen for any
        // player whose rewards overflowed a full inventory. continueVictoryAfterLoot()
        // runs the boss / non-boss branch -immediately, or once every loot screen closes.
        this.pendingVictory = new PendingVictory(isBoss, biomeOrdinal, biomeTemplate, emeraldsEarned);
        if (lootOverflow.isEmpty()) {
            continueVictoryAfterLoot();
        } else {
            lootPendingPlayers.clear();
            lootPendingPlayers.addAll(lootOverflow.keySet());
            for (java.util.Map.Entry<java.util.UUID, List<ItemStack>> entry : lootOverflow.entrySet()) {
                ServerPlayerEntity p = world.getServer().getPlayerManager().getPlayer(entry.getKey());
                if (p == null || !openLootScreen(p, entry.getValue())) {
                    lootPendingPlayers.remove(entry.getKey());
                }
            }
            // Every player with overflow has since disconnected -continue anyway.
            if (lootPendingPlayers.isEmpty()) {
                continueVictoryAfterLoot();
            }
        }
    }

    /**
     * INFINITE MODE boss clear: score +1 (banked immediately, so a crash can't
     * lose it), a guaranteed level-up on the run-scoped stats (alternating stat
     * point / affinity pick via grantLevelUp), then the party is moved to the
     * rest room where the bell continues into a random biome. The campaign's
     * unlock/NG+/boss-kill bookkeeping is deliberately absent here.
     */
    private void handleInfiniteBossVictory(ServerWorld world, CrafticsSavedData data,
                                           java.util.UUID hostUuid,
                                           List<ServerPlayerEntity> rewardRecipients) {
        CrafticsSavedData.PlayerData ld = data.getPlayerData(hostUuid);
        // Capture player turns taken THIS boss fight before endCombat resets it -
        // drives the "fewer turns = more points" boss score.
        int bossTurns = turnNumber;
        savePets();
        sendToAllParty(new ExitCombatPayload(true));
        sendMessage("§5§l*** ∞ BIOME " + (ld.infiniteBiomesCleared + 1) + " CLEARED! ∞ ***");
        ld.inCombat = false;
        data.markDirty();
        world.setTimeOfDay(6000);

        // Surviving pets return to the hub - the rest room is people-only.
        if (!savedPets.isEmpty()) {
            HubPetCollector.restorePetsToHub(world, player, savedPets, data);
            savedPets.clear();
        }
        petsRescued = true;

        List<ServerPlayerEntity> savedParty = new ArrayList<>(rewardRecipients);
        endCombat();

        // Every infinite boss grants a level-up on the run-scoped profile; the
        // reward alternates automatically (even level = stat point, odd level =
        // affinity pick) - same cadence as the campaign, one per boss.
        PlayerProgression progression = PlayerProgression.get(world);
        for (ServerPlayerEntity member : savedParty) {
            PlayerProgression.PlayerStats stats = progression.getStats(member);
            stats.grantLevelUp();
            stats.pendingAffinityChoice = stats.isAffinityLevel();
            progression.saveStats(member);
            StringBuilder statData = new StringBuilder();
            for (PlayerProgression.Stat s : PlayerProgression.Stat.values()) {
                if (statData.length() > 0) statData.append(":");
                statData.append(stats.getPoints(s));
            }
            ServerPlayNetworking.send(member, new com.crackedgames.craftics.network.LevelUpPayload(
                stats.level, stats.unspentPoints, statData.toString()));
            StringBuilder affData = new StringBuilder();
            for (PlayerProgression.Affinity a : PlayerProgression.Affinity.values()) {
                if (affData.length() > 0) affData.append(":");
                affData.append(stats.getAffinityPoints(a));
            }
            CrafticsSavedData.PlayerData memberPd = data.getPlayerData(member.getUuid());
            ServerPlayNetworking.send(member, new com.crackedgames.craftics.network.PlayerStatsSyncPayload(
                stats.level, stats.unspentPoints, statData.toString(),
                memberPd.emeralds, affData.toString()));
        }

        // Bank the score, roll the next realm, rebuild the rest room, move the party.
        InfiniteRunManager.onBossDefeated(world, hostUuid, savedParty, bossTurns);
    }

    /**
     * Pay out a raid win: the boss's bounty in emeralds plus two rolls from its loot
     * table, to every participant who did not forfeit, whether downed or alive. Overflow goes
     * through the same loot screen as a normal victory.
     */
    private void awardRaidBossRewards() {
        com.crackedgames.craftics.raid.RaidBossInstance instance = raidBossContext;
        com.crackedgames.craftics.raid.RaidBossDefinition def = instance.boss();
        ServerWorld world = (ServerWorld) player.getEntityWorld();
        CrafticsSavedData data = CrafticsSavedData.get(world);
        java.util.Map<java.util.UUID, List<ItemStack>> lootOverflow = new java.util.HashMap<>();
        java.util.Random rng = new java.util.Random();
        int luckBonusItems = PlayerProgression.get(world)
            .getStats(player).getPoints(PlayerProgression.Stat.LUCK);
        List<ServerPlayerEntity> rewardedOnline = new ArrayList<>();

        // Spec 6.1: a server-wide broadcast naming the boss and its survivors - not
        // just a message to this instance's own party, which is all sendMessage()
        // reaches. Other instances fighting the same boss (and the rest of the
        // server) never otherwise hear that a raid was won.
        broadcastRaidBossVictory(instance, def);

        // Revive fallen (downed, not forfeited) raiders with 2 hearts, the same as the
        // standard victory path in handleVictory() - which this raid branch returns
        // before reaching, so without this a downed winner went home still clamped at
        // 1 HP from the death handler.
        if (!deadPartyMembers.isEmpty()) {
            for (java.util.UUID recipientId : instance.rewardedPlayers()) {
                if (!deadPartyMembers.contains(recipientId)) continue;
                ServerPlayerEntity revived = server != null
                    ? server.getPlayerManager().getPlayer(recipientId) : null;
                if (revived == null) continue;
                revived.setHealth(4); // 2 hearts
                revived.clearStatusEffects();
                revived.changeGameMode(net.minecraft.world.GameMode.ADVENTURE);
                sendMessageTo(revived, "§a§l✦ REVIVED! §rYour raid won - you're back with 2 hearts!");
            }
            deadPartyMembers.clear();
        }

        for (java.util.UUID recipientId : instance.rewardedPlayers()) {
            ServerPlayerEntity recipient = server != null
                ? server.getPlayerManager().getPlayer(recipientId) : null;
            if (recipient == null) continue;
            rewardedOnline.add(recipient);

            data.getPlayerData(recipientId).addEmeralds(def.bounty());
            sendMessageTo(recipient, "§a+ " + def.bounty() + " Emeralds");

            for (int roll = 0; roll < 2; roll++) {
                ItemStack drop = rollRaidBossLoot(def, rng);
                if (drop.isEmpty()) continue;
                deliverLoot(recipient, drop, lootOverflow);
                sendMessageTo(recipient, "§6§l⚔ " + drop.getCount() + "x "
                    + drop.getName().getString());
            }
        }

        // Include the same boss-only rare extras normal boss fights can award.
        // These rolls are shared at the raid instance level (matching the normal
        // boss path's single roll gate), then distributed to each rewarded player.
        if (!rewardedOnline.isEmpty()) {
            float totemChance = (float) CrafticsMod.CONFIG.totemDropChance() + luckBonusItems * 0.01f;
            if (Math.random() < totemChance) {
                ItemStack totemDrop = com.crackedgames.craftics.compat.moretotems.MoreTotemsLootRoller.rollOne();
                if (!totemDrop.isEmpty()) {
                    for (ServerPlayerEntity recipient : rewardedOnline) {
                        deliverLoot(recipient, totemDrop.copy(), lootOverflow);
                    }
                    sendMessage("§d§l✦ RARE DROP: " + totemDrop.getName().getString() + "!");
                }
            }

            float uniqueChance = (float) CrafticsMod.CONFIG.uniqueWeaponDropChance() + luckBonusItems * 0.01f;
            if (Math.random() < uniqueChance) {
                for (ServerPlayerEntity recipient : rewardedOnline) {
                    ItemStack uniqueDrop = rollUniqueWeapon(recipient);
                    if (!uniqueDrop.isEmpty()) {
                        deliverLoot(recipient, uniqueDrop.copy(), lootOverflow);
                        sendMessageTo(recipient, "§6§l⚔ LEGENDARY DROP: " + uniqueDrop.getName().getString() + "!");
                    }
                }
            }

            if (Math.random() < CrafticsMod.CONFIG.trimDropChance() + luckBonusItems * 0.02) {
                String dimension = raidTrimDimension(def.environmentId());
                net.minecraft.item.Item[] trimPool = TrimEffects.getBossDropTrims(dimension);
                if (trimPool.length > 0) {
                    java.util.List<net.minecraft.item.Item> candidates = new java.util.ArrayList<>();
                    for (net.minecraft.item.Item t : trimPool) {
                        if (t != lastDroppedTrim) candidates.add(t);
                    }
                    if (candidates.isEmpty()) {
                        for (net.minecraft.item.Item t : trimPool) candidates.add(t);
                    }
                    java.util.Random trimRng = new java.util.Random();
                    String lastName = null;
                    for (ServerPlayerEntity recipient : rewardedOnline) {
                        net.minecraft.item.Item trimItem =
                            candidates.get(trimRng.nextInt(candidates.size()));
                        lastDroppedTrim = trimItem;
                        ItemStack trimStack = new ItemStack(trimItem);
                        deliverLoot(recipient, trimStack.copy(), lootOverflow);
                        lastName = trimStack.getName().getString();
                    }
                    if (lastName != null) {
                        sendMessage("§b§l✦ RARE DROP: " + lastName + "!");
                    }
                    unlockTrimGuideEntries(world, rewardedOnline);
                }
            }
        }

        data.markDirty();

        // Hand overflow to the standard loot screen, then tear the instance down once
        // every screen is closed; the raid has no next level to transition into.
        lootPendingPlayers.clear();
        for (var entry : lootOverflow.entrySet()) {
            ServerPlayerEntity p = server != null
                ? server.getPlayerManager().getPlayer(entry.getKey()) : null;
            if (p == null) continue;
            if (openLootScreen(p, entry.getValue())) lootPendingPlayers.add(entry.getKey());
        }
        if (lootPendingPlayers.isEmpty()) {
            finishRaidBossVictory();
        }
    }

    /** Server-wide victory announcement: the boss, and who survived to collect the
     *  reward. Deliberately separate from {@link #sendMessage}, which only reaches
     *  this instance's own party. */
    private void broadcastRaidBossVictory(
            com.crackedgames.craftics.raid.RaidBossInstance instance,
            com.crackedgames.craftics.raid.RaidBossDefinition def) {
        if (server == null) return;
        List<String> survivorNames = new ArrayList<>();
        for (java.util.UUID id : instance.rewardedPlayers()) {
            ServerPlayerEntity p = server.getPlayerManager().getPlayer(id);
            if (p != null) survivorNames.add(p.getName().getString());
        }
        String survivors = survivorNames.isEmpty()
            ? "no one left standing" : String.join(", ", survivorNames);
        Text msg = Text.literal("§6§l✦ " + def.name()
            + " has fallen! §r§7Survivors: " + survivors);
        for (ServerPlayerEntity online : server.getPlayerManager().getPlayerList()) {
            online.sendMessage(msg, false);
        }
    }

    /** Weighted single roll from a raid boss's authored loot table. */
    private static ItemStack rollRaidBossLoot(
            com.crackedgames.craftics.raid.RaidBossDefinition def, java.util.Random rng) {
        int total = 0;
        for (var entry : def.loot()) total += Math.max(1, entry.weight());
        if (total <= 0) return ItemStack.EMPTY;
        int pick = rng.nextInt(total);
        int cumulative = 0;
        for (var entry : def.loot()) {
            cumulative += Math.max(1, entry.weight());
            if (pick >= cumulative) continue;
            // tryParse, not of(): an authored itemId is untrusted JSON text that the
            // parser never validates as a well-formed identifier. of() throws
            // InvalidIdentifierException on anything malformed, which would abort the
            // whole raid reward pass mid-loop. Mirrors BarterJsonLoader's convention.
            net.minecraft.util.Identifier itemId = net.minecraft.util.Identifier.tryParse(entry.itemId());
            if (itemId == null) {
                CrafticsMod.LOGGER.warn("Raid boss '{}' loot id '{}' is not a valid identifier",
                    def.id(), entry.itemId());
                return ItemStack.EMPTY;
            }
            if (!net.minecraft.registry.Registries.ITEM.containsId(itemId)) {
                CrafticsMod.LOGGER.warn("Raid boss '{}' loot item '{}' is not registered",
                    def.id(), entry.itemId());
                return ItemStack.EMPTY;
            }
            int span = Math.max(1, entry.max() - entry.min() + 1);
            int count = entry.min() + rng.nextInt(span);
            return new ItemStack(net.minecraft.registry.Registries.ITEM.get(itemId), count);
        }
        return ItemStack.EMPTY;
    }

    /** Raid environments map onto the same trim-drop dimensions as regular bosses. */
    private static String raidTrimDimension(String environmentId) {
        if (environmentId == null) return "overworld";
        return switch (environmentId) {
            case "nether", "crimson_forest", "warped_forest" -> "nether";
            case "end" -> "end";
            default -> "overworld";
        };
    }

    /** Unlocks the trim guide page after a raid trim drop, same as normal boss wins. */
    private void unlockTrimGuideEntries(ServerWorld world, List<ServerPlayerEntity> recipients) {
        CrafticsSavedData trimData = CrafticsSavedData.get(world);
        for (ServerPlayerEntity recipient : recipients) {
            CrafticsSavedData.PlayerData pd = trimData.getPlayerData(recipient.getUuid());
            if (pd.unlockGuideEntry("How Trims Work")) {
                trimData.markDirty();
                sendGuideBookSync(recipient, pd);
            }
        }
    }

    /** Close out a raid win: end combat and let the instance return everyone home. */
    private void finishRaidBossVictory() {
        com.crackedgames.craftics.raid.RaidBossInstance instance = raidBossContext;
        if (instance == null) return;
        net.minecraft.server.MinecraftServer srv = server;
        sendToAllParty(new ExitCombatPayload(true));
        petsRescued = true;
        endCombat();
        if (srv != null) instance.finish(srv);
    }

    /**
     * Runs the boss / non-boss victory branch -either straight after loot
     * delivery (no overflow) or once every player's loot screen has closed.
     */
    private void continueVictoryAfterLoot() {
        PendingVictory pv = this.pendingVictory;
        this.pendingVictory = null;
        if (pv == null) return;
        boolean isBoss = pv.isBoss();
        int biomeOrdinal = pv.biomeOrdinal();
        com.crackedgames.craftics.level.BiomeTemplate biomeTemplate = pv.biomeTemplate();
        int emeraldsEarned = pv.emeraldsEarned();

        ServerWorld world = (ServerWorld) player.getEntityWorld();
        CrafticsSavedData data = CrafticsSavedData.get(world);
        java.util.UUID dataOwner = leaderUuid != null ? leaderUuid : player.getUuid();
        // Resolve the ACTUAL infinite-run host, not just the party leader. The run's
        // host state lives on the host's own record (infiniteActive), which in co-op
        // is not necessarily the party leader / island owner. resolveActiveHost checks
        // the leader, then this player's infiniteRunHost pointer, and returns whoever's
        // record is actually active - so the boss-victory rest-room flow fires in co-op,
        // not just solo. null when there's no active run (campaign boss).
        java.util.UUID infiniteHostOwner = InfiniteRunManager.resolveActiveHost(
            data, dataOwner, player.getUuid());
        java.util.UUID progressionOwner = InfiniteRunManager.isHostOfActiveRun(data, infiniteHostOwner)
            ? infiniteHostOwner : dataOwner;
        CrafticsSavedData.PlayerData ld = data.getPlayerData(progressionOwner);
        List<ServerPlayerEntity> rewardRecipients = getAllParticipants();

        // ===== begin block moved verbatim from handleVictory =====
        // Check combat feat achievements for ALL victories (boss and non-boss)
        if (!isBoss) {
            for (ServerPlayerEntity recipient : rewardRecipients) {
                AchievementManager.checkCombatFeats(recipient, achievementTracker);
                AchievementManager.checkCollections(recipient, data.getPlayerData(recipient.getUuid()).emeralds);
            }
        }

        if (isBoss) {
            // Network coins for the hub's cosmetic lootboxes -every boss, campaign and
            // infinite alike, so this sits ahead of the mode branch below. Fire-and-forget
            // and a no-op without the CrackedGames lobby mod; the run never waits on it.
            // The occasion tag carries the world tick so replaying a boss pays again,
            // while a retry of THIS award (which only the lobby's journal issues) does not.
            long victoryTick = world.getTime();
            com.crackedgames.craftics.compat.crackedlobby.CrackedLobbyCoins.awardBossDefeat(rewardRecipients,
                Long.toString(victoryTick, 36) + "o" + biomeOrdinal
                    + (InfiniteRunManager.isHostOfActiveRun(data, infiniteHostOwner) ? "i" : "c"));

            // INFINITE MODE: a boss clear banks score and parks the party in the
            // rest room instead of unlocking biomes / going home. No campaign
            // side-effects (unlocks, NG+, boss-kill HP ramp) are touched.
            if (InfiniteRunManager.isHostOfActiveRun(data, infiniteHostOwner)) {
                handleInfiniteBossVictory(world, data, infiniteHostOwner, rewardRecipients);
                return;
            }

            // Boss fights end the run immediately, so capture surviving allied pets now.
            savePets();

            // Boss fights end the biome run immediately.
            sendToAllParty(new ExitCombatPayload(true));

            // Boss defeated -biome complete! Unlock next biome, go home
            sendMessage("§6§l*** BIOME COMPLETE! ***");
            int currentBiomeOrder = biomeOrdinal + 1;
            if (ld.highestBiomeUnlocked <= currentBiomeOrder) {
                ld.highestBiomeUnlocked = currentBiomeOrder + 1;
                data.markDirty();
                com.crackedgames.craftics.CrafticsMod.updateWorldIcon(player.getServer(), ld);
                // Unlock biome for all party members
                for (ServerPlayerEntity recipient : rewardRecipients) {
                    CrafticsSavedData.PlayerData pd = data.getPlayerData(recipient.getUuid());
                    if (pd.highestBiomeUnlocked <= currentBiomeOrder) {
                        pd.highestBiomeUnlocked = currentBiomeOrder + 1;
                    }
                }
                // Region-boundary "unlocked" banner -campaign-driven. Resolve the
                // just-cleared biome id, then announce the NEXT region (if any) when the
                // next biome in flattened campaign order belongs to a different region.
                int branch = Math.max(0, ld.branchChoice);
                java.util.List<String> campaignOrder = com.crackedgames.craftics.level.campaign.CampaignManager
                    .orderedBiomeIds(branch);
                String justClearedBiomeId = biomeTemplate != null ? biomeTemplate.biomeId : ld.activeBiomeId;
                if (justClearedBiomeId == null
                        && biomeOrdinal >= 0 && biomeOrdinal < campaignOrder.size()) {
                    justClearedBiomeId = campaignOrder.get(biomeOrdinal);
                }
                String nextBiomeId = (biomeOrdinal + 1 < campaignOrder.size())
                    ? campaignOrder.get(biomeOrdinal + 1) : null;
                if (nextBiomeId != null) {
                    com.crackedgames.craftics.level.campaign.CampaignRegion clearedRegion =
                        com.crackedgames.craftics.level.campaign.CampaignManager.regionOf(justClearedBiomeId);
                    com.crackedgames.craftics.level.campaign.CampaignRegion nextRegion =
                        com.crackedgames.craftics.level.campaign.CampaignManager.regionOf(nextBiomeId);
                    if (nextRegion != null && nextRegion != clearedRegion) {
                        sendMessage(nextRegion.color() + "§l" + nextRegion.icon() + " "
                            + nextRegion.displayName().toUpperCase() + " HAS BEEN UNLOCKED! "
                            + nextRegion.icon());
                    }
                }
                // Final node of the final region (any campaign, any size) - trigger NG+.
                if (com.crackedgames.craftics.level.campaign.CampaignManager
                        .isFinalBiome(justClearedBiomeId, branch)) {
                    ld.startNewGamePlus();
                    sendMessage("§6§l★ NEW GAME+ " + ld.ngPlusLevel + " UNLOCKED! ★");
                    sendMessage("§eAll biomes reset. Enemies are now stronger. Your stats carry over.");
                }
            }
            ld.endBiomeRun();
            ld.inCombat = false;
            // The run is over - drop any event-interlude leftovers. Orphaned
            // pendingNextLevelDef/lastFightWasTrial survive on this per-leader instance and
            // would hijack the NEXT run's first Continue into the old biome's stale level.
            clearEventInterludeState();
            data.markDirty();
            world.setTimeOfDay(6000);
            // Teleport all party members home
            for (ServerPlayerEntity p : rewardRecipients) {
                teleportToHub(p);
            }

            // Restore surviving pets to the hub for the run owner.
            if (!savedPets.isEmpty()) {
                HubPetCollector.restorePetsToHub(world, player, savedPets, data);
                savedPets.clear();
            }
            // Pets handled -endCombat() must not restore them a second time.
            petsRescued = true;

            // Check achievements before endCombat() clears state
            String achievBiomeId = biomeTemplate != null ? biomeTemplate.biomeId : "";
            String achievArmorSet = PlayerCombatStats.getArmorSet(player);
            CombatAchievementTracker savedTracker = achievementTracker;
            for (ServerPlayerEntity recipient : rewardRecipients) {
                AchievementManager.checkBossVictory(recipient, achievBiomeId, achievArmorSet, savedTracker);
            }
            // Check NG+ achievements
            if (ld.ngPlusLevel > 0) {
                for (ServerPlayerEntity recipient : rewardRecipients) {
                    AchievementManager.checkNewGamePlus(recipient, ld.ngPlusLevel);
                }
            }
            // Check emerald collection achievement
            for (ServerPlayerEntity recipient : rewardRecipients) {
                CrafticsSavedData.PlayerData rpd = data.getPlayerData(recipient.getUuid());
                AchievementManager.checkCollections(recipient, rpd.emeralds);
            }

            // Save party list before endCombat() clears it.
            // savedPlayer must be the stable combat leader (not this.player,
            // which rotates per turn and points at the boss-killer by now).
            List<ServerPlayerEntity> savedParty = new ArrayList<>(rewardRecipients);
            ServerPlayerEntity resolvedLeader = getCombatLeader();
            ServerPlayerEntity savedPlayer = resolvedLeader != null ? resolvedLeader : player;
            endCombat();

            // Grant level-up with diminishing returns per boss
            String bossbiomeId = biomeTemplate != null ? biomeTemplate.biomeId : "unknown";
            PlayerProgression progression = PlayerProgression.get(world);
            for (ServerPlayerEntity member : savedParty) {
                PlayerProgression.PlayerStats stats = progression.getStats(member);
                boolean earned = stats.recordBossKillAndCheckLevelUp(bossbiomeId);
                progression.saveStats(member);
                if (earned) {
                    stats.grantLevelUp();
                    stats.pendingAffinityChoice = stats.isAffinityLevel();
                    progression.saveStats(member);
                    AchievementManager.checkProgression(member);
                } else {
                    int remaining = stats.getKillsUntilNextLevel(bossbiomeId);
                    sendMessageTo(member, "§7Defeat this boss §e" + remaining + "§7 more time" + (remaining != 1 ? "s" : "") + " for a level up.");
                }
                StringBuilder statData = new StringBuilder();
                for (PlayerProgression.Stat s : PlayerProgression.Stat.values()) {
                    if (statData.length() > 0) statData.append(":");
                    statData.append(stats.getPoints(s));
                }
                // Only show level-up screen if this kill earned a level
                if (earned) {
                    ServerPlayNetworking.send(member, new com.crackedgames.craftics.network.LevelUpPayload(
                        stats.level, stats.unspentPoints, statData.toString()
                    ));
                }
                StringBuilder affData = new StringBuilder();
                for (PlayerProgression.Affinity a : PlayerProgression.Affinity.values()) {
                    if (affData.length() > 0) affData.append(":");
                    affData.append(stats.getAffinityPoints(a));
                }
                CrafticsSavedData.PlayerData pd = data.getPlayerData(member.getUuid());
                ServerPlayNetworking.send(member, new com.crackedgames.craftics.network.PlayerStatsSyncPayload(
                    stats.level, stats.unspentPoints, statData.toString(), pd.emeralds, affData.toString()
                ));
            }
        } else {
            // Non-boss: show Go Home / Continue choice
            // Don't advance if this was a trial/ambush -those are bonus fights, not real levels
            if (!lastFightWasTrial) {
                ld.advanceBiomeRun();
                data.markDirty();
                // INFINITE MODE: clearing a normal level banks +5 points minus 1 per
                // 2 player-turns (floored at 1) - rewards finishing levels quickly.
                // Trials/ambushes are excluded (guarded above). Boss levels score via
                // onBossDefeated, not here.
                if (InfiniteRunManager.isHostOfActiveRun(data, infiniteHostOwner)) {
                    int earned = InfiniteRunManager.clearPoints(
                        InfiniteRunManager.LEVEL_POINTS, turnNumber);
                    int total = InfiniteRunManager.awardScore(
                        data, infiniteHostOwner, earned, rewardRecipients);
                    for (ServerPlayerEntity member : rewardRecipients) {
                        sendMessageTo(member, "§5∞ Level cleared! §d+" + earned
                            + " points §7(fewer turns = more). Score: §f" + total);
                    }
                }
            }
            String biomeName = biomeTemplate != null ? biomeTemplate.displayName : "Unknown";
            int displayIndex = ld.activeBiomeLevelIndex;
            // Go Home means opposite things in the two modes, so the button has to know
            // which one it is in: a campaign run resets its biome progress, an infinite run
            // parks at a save point and resumes exactly where it left off. Resolved here
            // (not on the client) because biomeName is the plain biome display name and
            // carries no infinite marker.
            boolean inInfiniteRun = InfiniteRunManager.isHostOfActiveRun(data, infiniteHostOwner);
            // Check if the next level in this biome is a boss fight
            int nextGlobalLevel = levelDef instanceof com.crackedgames.craftics.level.GeneratedLevelDefinition gld2
                ? gld2.getLevelNumber() + 1 : -1;
            boolean nextIsBoss = biomeTemplate != null && nextGlobalLevel >= 0
                && biomeTemplate.isBossLevel(nextGlobalLevel);

            // Send choice screen to the STABLE combat leader (resolved via
            // leaderUuid), not `this.player` -in party combat `this.player`
            // is the current turn player and has likely rotated to whoever
            // killed the last enemy by the time we reach this code.
            ServerPlayerEntity decisionPlayer = getCombatLeader();
            if (decisionPlayer == null) {
                decisionPlayer = partyPlayers.isEmpty() ? player : partyPlayers.get(0);
            }
            if (decisionPlayer == null) {
                CrafticsMod.LOGGER.error("handleVictoryNonBoss: no leader found to send victory screen -aborting");
                return;
            }
            // The emerald total on this screen is the RECIPIENT's own balance, never the
            // progression owner's. Emeralds are earned per player (the award loop credits
            // every recipient's PlayerData) and spent per player, so the two drift apart as
            // soon as anyone buys anything - sending ld.emeralds made each member's HUD
            // adopt the island owner's number until their next purchase resynced it.
            ServerPlayNetworking.send(decisionPlayer, new VictoryChoicePayload(
                emeraldsEarned, data.getPlayerData(decisionPlayer.getUuid()).emeralds,
                false, biomeName, displayIndex, nextIsBoss,
                true, inInfiniteRun, LootRecorder.drain(decisionPlayer.getUuid())
            ));
            // Non-leaders get a persistent "waiting" loading screen. It fades out
            // automatically when their next EnterCombatPayload arrives from the
            // subsequent transitionPartyToArena call.
            String leaderName = decisionPlayer.getName().getString();
            for (ServerPlayerEntity member : getAllParticipants()) {
                if (!member.getUuid().equals(decisionPlayer.getUuid())) {
                    sendMessageTo(member, "§7Waiting for " + leaderName + " to decide...");
                    // Non-leaders see their OWN collected rewards; isLeader=false makes
                    // the screen show a "waiting for the leader" note instead of buttons.
                    ServerPlayNetworking.send(member, new VictoryChoicePayload(
                        emeraldsEarned, data.getPlayerData(member.getUuid()).emeralds,
                        false, biomeName, displayIndex, nextIsBoss,
                        false, inInfiniteRun, LootRecorder.drain(member.getUuid())
                    ));
                }
            }
            {
                java.util.List<java.util.UUID> doneIds = new java.util.ArrayList<>();
                for (ServerPlayerEntity p : getAllParticipants()) doneIds.add(p.getUuid());
                LootRecorder.end(doneIds);
            }
            // Don't endCombat yet -wait for player choice
            // But do clear the arena
            clearHighlights();

            // Pre-build the NEXT level's arena while everyone is parked on the victory
            // screen. A level's first visit otherwise pays its arena build on the way IN -
            // a main-thread hitch right at the transition. The same cost spent NOW lands in
            // a moment nobody is moving. Already-built levels return from cache instantly.
            prefetchNextArena();
        }
        // ===== end moved block =====
    }

    /**
     * Clear the ended biome run off any OTHER participant still carrying it.
     *
     * <p>A biome run is written and erased on two different records. It is started on whoever
     * pressed Start ({@code RunInviteManager.beginRun} writes {@code startBiomeRun} to
     * {@code getPlayerData(starter.getUuid())}), but it is ended on the progression owner -
     * the combat leader, or the infinite host. Those are the same player in the common case
     * and different the moment they are not, and nothing ever reconciled them.
     *
     * <p>The visible symptom is Infinite Mode refusing to start. Its gate reads the
     * STARTER's {@code isInBiomeRun()}, so a starter whose record was never cleared is told
     * "finish your current biome run (or Go Home from it)" forever - and Go Home cannot help,
     * because Go Home is the thing that writes to the other record. There is no in-game way
     * out of it.
     *
     * <p>Deliberately narrow. It only clears a record that is pointing at THIS run - same
     * biome id, same island - so a party member's own paused run back on their own island is
     * left alone rather than being wiped by helping with someone else's. A member hosting a
     * live infinite run is skipped too: their cursor is the run's save point.
     */
    private static void clearMirroredBiomeRun(CrafticsSavedData data, String endedBiomeId,
                                              ServerPlayerEntity leader,
                                              List<ServerPlayerEntity> members,
                                              java.util.UUID alreadyCleared) {
        if (data == null || endedBiomeId == null || endedBiomeId.isEmpty() || leader == null) return;
        java.util.UUID island = data.getEffectiveWorldOwner(leader.getUuid());
        if (island == null) return;
        for (ServerPlayerEntity member : members) {
            if (member == null) continue;
            java.util.UUID uuid = member.getUuid();
            if (uuid.equals(alreadyCleared)) continue;
            CrafticsSavedData.PlayerData md = data.getPlayerData(uuid);
            if (!endedBiomeId.equals(md.activeBiomeId)) continue;      // not this run
            if (!island.equals(data.getEffectiveWorldOwner(uuid))) continue;  // not this island
            if (md.infiniteActive && !md.infiniteSuspended) continue;  // live run's save point
            md.endBiomeRun();
        }
    }

    /**
     * The level an addon event wants to run next, read back after its handler has executed.
     *
     * <p>Turning an event into a fight is the whole point of a campaign addon: a trainer
     * battle is an event that becomes a level. A handler says so by setting a pending level,
     * and there are two objects it could reasonably set it on - the {@link EventManager} it
     * was handed, or the combat manager running the fight. This honours both, in that order,
     * and falls back to the level that was already queued when the handler asked for nothing.
     *
     * <p>Both needed fixing. The forced-event path built its arena from a local captured
     * <em>before</em> the handler ran and nulled the pending level first, so a non-choice
     * event could hand out rewards and nothing else - it could never become a fight. And
     * {@code EventManager.setPendingNextLevel} was read by nothing at all, which is the
     * setter a handler reaches for first, since the EventManager is the object it is given.
     *
     * <p>Consumes what it finds, so a redirect cannot leak into a later event.
     *
     * @param handlerManager the EventManager the handler was passed, may be null
     * @param fallback       the level queued before the handler ran
     */
    private com.crackedgames.craftics.level.LevelDefinition consumeAddonNextLevel(
            EventManager handlerManager,
            com.crackedgames.craftics.level.LevelDefinition fallback) {
        if (handlerManager != null && handlerManager.getPendingNextLevel() != null) {
            var fromManager = handlerManager.getPendingNextLevel();
            handlerManager.setPendingNextLevel(null);
            return fromManager;
        }
        if (pendingNextLevelDef != null) return pendingNextLevelDef;
        return fallback;
    }

    /**
     * Handle the player's choice after winning a non-boss level.
     * goHome = true: teleport home, reset biome run
     * goHome = false: continue to next level (with possible trader encounter)
     */
    public void handlePostLevelChoice(ServerPlayerEntity choicePlayer, boolean goHome) {
        // Reject if combat is mid-fight (not in a post-level state)
        if (active && phase != CombatPhase.LEVEL_COMPLETE) return;

        // Handle addon event choice (accept/decline from VictoryChoicePayload)
        if (pendingAddonEventId != null) {
            String eventId = pendingAddonEventId;
            List<ServerPlayerEntity> members = pendingAddonEventMembers;
            EventManager evtMgr = pendingAddonEventManager;
            pendingAddonEventId = null;
            pendingAddonEventMembers = null;
            pendingAddonEventManager = null;

            if (goHome) {
                // Declined -skip event, continue to pending next level
                for (ServerPlayerEntity p : getOnlinePartyMembers(choicePlayer)) {
                    sendMessageTo(p, "§7You decide to move on...");
                }
                if (pendingNextLevelDef != null) {
                    ServerWorld w = (ServerWorld) choicePlayer.getEntityWorld();
                    spawnSavedPets();
                    GridArena nextArena = buildArena(w, pendingNextLevelDef);
                    transitionPartyToArena(choicePlayer, members, nextArena, pendingNextLevelDef);
                    pendingNextLevelDef = null;
                    pendingBiome = null;
                }
            } else {
                // Accepted -execute the addon event handler
                var addonEvent = com.crackedgames.craftics.api.registry.EventRegistry.getById(eventId);
                if (addonEvent != null && addonEvent.handler() != null) {
                    ServerWorld w = (ServerWorld) choicePlayer.getEntityWorld();
                    try {
                        addonEvent.handler().execute(
                            members != null ? members : getOnlinePartyMembers(choicePlayer),
                            w, evtMgr);
                    } catch (Exception addonEx) {
                        CrafticsMod.LOGGER.error("Addon event '{}' handler threw exception", eventId, addonEx);
                    }
                    // After handler: if no combat was started, auto-continue
                    if (!active && !trialChamberPending && !digSitePending) {
                        var acceptedNext = consumeAddonNextLevel(evtMgr, pendingNextLevelDef);
                        if (acceptedNext != null) {
                            spawnSavedPets();
                            GridArena nextArena = buildArena(w, acceptedNext);
                            transitionPartyToArena(choicePlayer, members, nextArena, acceptedNext);
                            pendingNextLevelDef = null;
                            pendingBiome = null;
                        }
                    }
                }
            }
            return;
        }

        // Trial chamber choice used to live here, but it's now a party-vote
        // dialogue (see offerTrialVote / handleTrialDialogueChoice). The
        // trialChamberPending branch is unreachable from the post-battle screen
        // and has been removed; trial accept/skip transitions happen directly
        // from finalizeTrialEvent.
        if (false) { // dead -trial choice moved to dialogue vote, see offerTrialVote
            trialChamberPending = false;
            lastFightWasTrial = false;
            com.crackedgames.craftics.level.LevelDefinition savedTrialDef = trialChamberLevelDef;
            trialChamberLevelDef = null;
            ServerWorld tcWorld = (ServerWorld) choicePlayer.getEntityWorld();
            if (goHome) {
                // Skip trial -continue to pending next level
                for (ServerPlayerEntity p : getOnlinePartyMembers(choicePlayer)) {
                    sendMessageTo(p, "§7You pass by the trial chamber...");
                }
                if (pendingNextLevelDef != null && pendingBiome != null) {
                    // Restore allies and pets before continuing
                    spawnSavedPets();
                    GridArena nextArena = buildArena(tcWorld, pendingNextLevelDef);
                    transitionPartyToArena(choicePlayer, nextArena, pendingNextLevelDef);
                    pendingNextLevelDef = null;
                    pendingBiome = null;
                    pendingEventBiomeOrdinal = 0;
                }
            } else {
                // Accept trial!
                for (ServerPlayerEntity p : getOnlinePartyMembers(choicePlayer)) {
                    sendMessageTo(p, "§6§l\u2694 Entering the Trial Chamber! \u2694");
                    sendMessageTo(p, "§cWarning: Enemies are stronger here!");
                }
                if (savedTrialDef != null) {
                    // Restore allies and pets before entering trial
                    spawnSavedPets();
                    GridArena trialArena = buildArena(tcWorld, savedTrialDef);
                    transitionPartyToArena(choicePlayer, trialArena, savedTrialDef);
                    lastFightWasTrial = true;
                }
            }
            return;
        }

        // After a trial chamber or ambush victory, go directly to the pending next level (no more events)
        if (lastFightWasTrial && pendingNextLevelDef != null && !goHome) {
            lastFightWasTrial = false;
            ServerWorld world2 = (ServerWorld) choicePlayer.getEntityWorld();
            // Capture allies that survived the trial/ambush (including the player's
            // mount) BEFORE endCombat(). The old code called spawnSavedPets() here,
            // but savedPets was already drained when the trial was entered (see
            // finalizeTrialEvent), so it was a no-op -and because savePets()/
            // petsRescued were never set, endCombat()'s safety-net "rescued" the live
            // trial allies straight back to the hub, making mounts and pets vanish
            // from the run after every trial/ambush ("they never return").
            savePets();
            petsRescued = true;
            endCombat();
            GridArena nextArena = buildArena(world2, pendingNextLevelDef);
            // transitionPartyToArena -> startCombat -> spawnSavedPets re-spawns and
            // re-mounts the carried-over allies in the new arena.
            transitionPartyToArena(choicePlayer, nextArena, pendingNextLevelDef);
            pendingNextLevelDef = null;
            pendingBiome = null;
            pendingEventBiomeOrdinal = 0;
            return;
        }
        // Only accept choice from the party leader.
        // CRITICAL: resolve the leader via getCombatLeader() (by stable
        // leaderUuid), NOT via `this.player` -in party combat this.player is
        // reassigned per turn by switchToTurnPlayer() and at victory points at
        // whoever dealt the killing blow. Before this was fixed,
        // `savedPlayer = player` caused transitionPartyToArena to treat the
        // killer as the "leader" and teleport only them to the next level.
        ServerPlayerEntity leader = getCombatLeader();
        if (leader == null) {
            // Fall back to partyPlayers[0] / this.player for pre-startCombat
            // edge cases where leaderUuid is null.
            leader = partyPlayers.isEmpty() ? player : partyPlayers.get(0);
        }
        if (leader == null || !choicePlayer.getUuid().equals(leader.getUuid())) {
            CrafticsMod.LOGGER.debug(
                "handlePostLevelChoice: rejecting click from {} (combat leader: {})",
                choicePlayer.getName().getString(),
                leader != null ? leader.getName().getString() : "none");
            return;
        }
        // Cleared only AFTER the leader check: a non-leader's spurious choice packet must
        // not strip the post-event routing flag out from under the leader's real click.
        lastFightWasTrial = false;

        // Save references before endCombat() nulls them. snapshotParticipants
        // prefers partyPlayers (still populated here) and falls back through
        // eventManager so downstream code never has to worry about ordering.
        ServerPlayerEntity savedPlayer = leader;
        List<ServerPlayerEntity> savedMembers = snapshotParticipants();
        ServerWorld world = (ServerWorld) savedPlayer.getEntityWorld();
        CrafticsSavedData data = CrafticsSavedData.get(world);
        java.util.UUID dataOwner = leaderUuid != null ? leaderUuid : savedPlayer.getUuid();
        java.util.UUID infiniteHostOwner = InfiniteRunManager.resolveActiveHost(
            data, dataOwner, savedPlayer.getUuid());
        java.util.UUID progressionOwner = InfiniteRunManager.isHostOfActiveRun(data, infiniteHostOwner)
            ? infiniteHostOwner : dataOwner;
        CrafticsSavedData.PlayerData ld = data.getPlayerData(progressionOwner);

        // Snapshot biome state BEFORE endCombat can interfere
        String biomeId = ld.activeBiomeId;
        int levelIndex = ld.activeBiomeLevelIndex;
        int branchChoice = ld.branchChoice;
        int ngPlusLevel = ld.ngPlusLevel;

        // Persist tamed pets so they carry over to the next level (continue) or
        // get restored to the hub just below (go home). Either branch disposes of
        // the survivors explicitly, so endCombat() must not touch them.
        savePets();
        petsRescued = true;

        if (goHome) {
            sendMessage("§7Returning to hub...");
            // Restore surviving pets back into the hub world using their original NBT snapshots.
            if (!savedPets.isEmpty()) {
                HubPetCollector.restorePetsToHub(world, savedPlayer, savedPets, data);
                sendMessage("§aYour surviving pets returned to the hub.");
                savedPets.clear();
            }
            // Read through the live predicate, not the raw flag: a parked run also has
            // infiniteActive set, and for a solo parked host progressionOwner IS that
            // host - so the bare read made Go Home from a normal campaign level skip the
            // biome reset the button explicitly promises, and left every party member's
            // mirrored cursor pointing at a run that had ended.
            boolean wasInfinite = InfiniteRunManager.isInLiveRun(data, progressionOwner);
            // A live infinite run keeps its biome/level cursor - that IS the save point.
            if (!wasInfinite) {
                ld.endBiomeRun();
                clearMirroredBiomeRun(data, biomeId, savedPlayer, savedMembers, progressionOwner);
            }
            // Going home ends the interlude either way - stale pending event state must
            // not leak into the next run (see clearEventInterludeState).
            clearEventInterludeState();
            ld.inCombat = false;
            data.markDirty();
            world.setTimeOfDay(6000);
            // Teleport all party members home
            for (ServerPlayerEntity member : savedMembers) {
                teleportToHub(member);
            }
            sendToAllParty(new ExitCombatPayload(true));
            endCombat();
            // INFINITE MODE: going home parks the run at a save point - the stash comes
            // back now, and Infinite Mode resumes here later. Score stays banked either way.
            if (wasInfinite) {
                InfiniteRunManager.suspendRun(world.getServer(), progressionOwner, "went home");
            }
        } else {
            // Continue to next level
            // Broadcast to all BEFORE endCombat clears party state
            for (ServerPlayerEntity m : savedMembers) {
                sendMessageTo(m, "§aOnward!");
            }
            // Save eventManager before endCombat nulls it -addon event handlers need it
            EventManager savedEventManager = this.eventManager;
            endCombat();

            try {
            // Start next level -use snapshotted biome state (safe from endCombat clobbering)
            com.crackedgames.craftics.level.BiomeTemplate biome = null;
            for (var b : com.crackedgames.craftics.level.BiomeRegistry.getAllBiomes()) {
                if (b.biomeId.equals(biomeId)) { biome = b; break; }
            }
            if (biome != null) {
                int globalLevel = biome.startLevel + levelIndex;
                // Island owner's per-level HP scaling preference. For party fights
                // this is whoever owns the world slot (the leader); for solo it's
                // the player themselves. worldOwnerUuid is set when combat starts.
                java.util.UUID hpScaleOwnerId = worldOwnerUuid != null
                    ? worldOwnerUuid
                    : (leaderUuid != null ? leaderUuid : savedPlayer.getUuid());
                boolean islandHpScale = data.getPlayerData(hpScaleOwnerId).scaleHpPerLevelEnabled;
                // Once the island owner has beaten this biome's boss, every level in the
                // biome spawns the biome's peak enemy count instead of the normal ramp.
                boolean ownerBeatBiomeBoss = PlayerProgression.get(world)
                    .getStats(hpScaleOwnerId).getBossKills(biomeId) >= 1;
                // INFINITE MODE: thread the run spec so the next level scales off
                // the cleared-biome count and a boss level rolls the randomized boss.
                com.crackedgames.craftics.level.InfiniteSpec contInfSpec =
                    InfiniteRunManager.specFor(data, progressionOwner, biome, globalLevel);
                if (contInfSpec != null) {
                    // A chapter must present the same roster to everyone at the same run
                    // depth. This flag is per-island campaign history: it flips enemy
                    // count from the ramp to the biome's peak, and enemy count also sets
                    // the loot quantity range, so leaving it in would vary both the
                    // roster size and the payout between players. RunInviteManager
                    // already hardcodes false when it starts an infinite biome.
                    ownerBeatBiomeBoss = false;
                }
                // The other two per-island values below are still forwarded, and both are
                // inert on the infinite path TODAY. Verify that again before relying on it:
                // the biome roll used to forward branchChoice the same way and it was NOT
                // inert, which silently put half the server on a differently ordered ladder.
                //   branchChoice   read once in LevelGenerator, inside the else of
                //                  `if (infiniteSpec != null)`. Level-to-template mapping
                //                  (BiomeRegistry.getForLevel) takes no branch argument.
                //   islandHpScale  feeds only hpBonus, which infinite never reads: enemy HP
                //                  comes from InfiniteScaling.enemyHp, boss HP from
                //                  InfiniteScaling.bossHp, passives from mob.baseHp().
                // If either ever starts affecting infinite content, it has to be neutralized
                // here the way ownerBeatBiomeBoss is, or determinism breaks without a
                // compile error to warn anyone.
                com.crackedgames.craftics.level.LevelDefinition nextLevelDef =
                    com.crackedgames.craftics.level.LevelRegistry.get(globalLevel, branchChoice,
                        islandHpScale, ownerBeatBiomeBoss, contInfSpec);
                if (nextLevelDef != null) {
                    // INFINITE MODE: WHICH event fires is content presented before the
                    // player acts, so everyone at the same run depth must get the same
                    // one - an ambush is a whole extra fight and a vault is free loot,
                    // both of which feed score. Only the host carries the run cursor,
                    // so resolve it through infiniteRunHost the way the trader stock
                    // does. Outside an infinite run this stays unseeded, as before.
                    java.util.Random eventRng = new java.util.Random();
                    if (contInfSpec != null) {
                        String eventHostRef = data.getPlayerData(savedPlayer.getUuid()).infiniteRunHost;
                        if (eventHostRef != null && !eventHostRef.isEmpty()) {
                            try {
                                var eventHost = data.getPlayerData(java.util.UUID.fromString(eventHostRef));
                                if (eventHost.infiniteActive && !eventHost.infiniteSuspended) {
                                    eventRng = com.crackedgames.craftics.combat.infinite.ChapterRng.random(
                                        com.crackedgames.craftics.combat.infinite.ChapterManager.seedOf(data),
                                        com.crackedgames.craftics.combat.infinite.ChapterRng.SALT_EVENT_PICK,
                                        eventHost.infiniteBiomesCleared, eventHost.activeBiomeLevelIndex);
                                }
                            } catch (IllegalArgumentException ignored) {}
                        }
                    }
                    float eventRoll = eventRng.nextFloat();

                    // Calculate biome position for difficulty scaling (use active-campaign ordinal, not registry index)
                    int biomeOrdinal = contInfSpec != null
                        ? contInfSpec.virtualOrdinal()
                        : com.crackedgames.craftics.level.campaign.CampaignManager
                            .ordinalOf(biome.biomeId, Math.max(0, branchChoice));
                    if (biomeOrdinal < 0) biomeOrdinal = 0;

                    // No events on the very first continue (level index 1 = just beat level 1)
                    // Never have events before a boss fight
                    // Never have events before a biome's SPECIAL level (Graveyard, Blizzard, ...) -
                    // an event interlude here plays instead of the special level and skips it
                    // entirely (the reported "abandoned campsite replaced the Graveyard" bug).
                    // Reduced event chance on early biomes (first 3 biomes)
                    boolean isBossLevel = biome.isBossLevel(globalLevel);
                    boolean nextIsSpecialLevel = com.crackedgames.craftics.level.LevelGenerator
                        .isMinibossLevel(biome, biome.getBiomeLevelIndex(globalLevel), isBossLevel);
                    boolean skipEvents = levelIndex <= 1 || isBossLevel || nextIsSpecialLevel;
                    if (!skipEvents && biomeOrdinal < 3) {
                        // Early biomes: reduced event chance (configurable)
                        skipEvents = eventRoll > CrafticsMod.CONFIG.earlyBiomeEventChance();
                        if (!skipEvents) eventRoll = eventRng.nextFloat(); // re-roll within event pool
                    }

                    // === PITY TIMER: Increase overall event chance based on levels without event ===
                    // Each event-less level ADDS 5% (cap +50%) to every event window.
                    // This used to multiply the thresholds by (1 - pity), which SHRANK
                    // them - the longer the dry streak, the RARER events got, quietly
                    // starving the low-probability tail (e.g. the Artifacts campsite).
                    float pityBonus = 0f;
                    if (!skipEvents && ld.levelsSinceLastEvent > 0) {
                        pityBonus = Math.min(0.50f, ld.levelsSinceLastEvent * 0.05f);
                        if (ld.levelsSinceLastEvent >= 3) {
                            //sendMessageToAllChat("§7§o[Pity Timer: " + ld.levelsSinceLastEvent + " levels without events - event probability +" + (int)(pityBonus * 100) + "%]");
                        }
                    }

                    // Check for forced event from /craftics force_event
                    String forced = forcedNextEvent;
                    if (forced != null) {
                        forcedNextEvent = null;
                        skipEvents = false; // override skip
                    }

                    // Helper: broadcast event messages to all party members
                    // Use savedMembers (captured before endCombat) since party state is already cleared
                    List<ServerPlayerEntity> partyMsg = savedMembers;

                    // Cap the pity boost so the whole cascade (built-ins + addon
                    // events) still fits under 1.0 - otherwise a long dry streak
                    // would push the trader window past 1.0 and make the addon
                    // events at the tail unreachable again.
                    float addonEventTotal = 0f;
                    for (var addonEntry : com.crackedgames.craftics.api.registry.EventRegistry.getAll()) {
                        if (addonEntry.handler() != null && biomeOrdinal >= addonEntry.minBiomeOrdinal()) {
                            addonEventTotal += addonEntry.probability();
                        }
                    }
                    float baseEventTotal = CrafticsMod.CONFIG.ominousTrialChance()
                        + CrafticsMod.CONFIG.trialChamberChance()
                        + CrafticsMod.CONFIG.ambushChance()
                        + CrafticsMod.CONFIG.shrineChance()
                        + CrafticsMod.CONFIG.travelerChance()
                        + CrafticsMod.CONFIG.vaultChance()
                        + CrafticsMod.CONFIG.digSiteChance()
                        + 0.06f // enchanter (hardcoded below)
                        + CrafticsMod.CONFIG.traderSpawnChance()
                        + addonEventTotal;
                    float pityScale = 1f + pityBonus;
                    if (baseEventTotal * pityScale > 0.98f) {
                        pityScale = Math.max(1f, 0.98f / baseEventTotal);
                    }

                    // Build cumulative thresholds from config (with pity boost applied)
                    float cOminous = CrafticsMod.CONFIG.ominousTrialChance() * pityScale;
                    float cTrial = cOminous + CrafticsMod.CONFIG.trialChamberChance() * pityScale;
                    float cAmbush = cTrial + CrafticsMod.CONFIG.ambushChance() * pityScale;
                    float cShrine = cAmbush + CrafticsMod.CONFIG.shrineChance() * pityScale;
                    float cTraveler = cShrine + CrafticsMod.CONFIG.travelerChance() * pityScale;
                    float cVault = cTraveler + CrafticsMod.CONFIG.vaultChance() * pityScale;
                    float cDigSite = cVault + CrafticsMod.CONFIG.digSiteChance() * pityScale;
                    float cEnchanter = cDigSite + 0.06f * pityScale; // 6% enchanter chance
                    float cTrader = cEnchanter + CrafticsMod.CONFIG.traderSpawnChance() * pityScale;

                    boolean isNetherRegion = "nether".equals(
                        java.util.Optional.ofNullable(
                            com.crackedgames.craftics.level.campaign.CampaignManager.regionOf(biome.biomeId))
                        .map(r -> r.id()).orElse("overworld"));

                    // RAID gets first claim on the event slot. A fresh island (raid never
                    // defeated) is under active pillager threat: 75% of rolls are the raid
                    // until the players win one, then it drops to an ordinary event rate.
                    // Rolled as its own draw so the cumulative windows below are untouched
                    // either way. It comes off the same stream as eventRoll, which in an
                    // infinite run is the seeded one, so the raid decision is reproducible
                    // too (the number of draws ahead of it is fixed by conditions that are
                    // themselves identical for everyone at this depth).
                    boolean raidAlreadyDefeated = data.getPlayerData(
                        data.getEffectiveWorldOwner(savedPlayer.getUuid())).raidDefeated;
                    // Infinite mode should not get the fresh-island raid boost. Keep raid odds
                    // there equal to the normal post-raid baseline so it competes fairly with
                    // the rest of the event pool.
                    float raidChance = (contInfSpec != null || raidAlreadyDefeated) ? 0.06f : 0.75f;
                    float raidRoll = eventRng.nextFloat();
                    // Pillager Camp draw - its own roll, like the raid's, so it never
                    // carves a band out of the built-in events' shared cascade. Drawn
                    // unconditionally to keep the eventRng stream identical whether or
                    // not the mod is installed (infinite runs replay this stream).
                    float campRoll = eventRng.nextFloat();

                    if (skipEvents) {
                        // No event -go straight to next level. Boss levels get a
                        // narrator intro first; once all members dismiss it the
                        // transition fires (no leader choice -combat starts either way).
                        ld.levelsSinceLastEvent++; // increment pity timer
                        data.markDirty();
                        final com.crackedgames.craftics.level.LevelDefinition nextDef = nextLevelDef;
                        final ServerPlayerEntity ref = savedPlayer;
                        final List<ServerPlayerEntity> members = savedMembers;
                        final ServerWorld w = world;
                        Runnable transition = () -> {
                            ServerPlayerEntity source = (ref != null && !ref.isRemoved() && !ref.isDisconnected())
                                ? ref : firstOnlinePartyMember();
                            if (source == null) return;
                            GridArena nextArena = buildArena(w, nextDef);
                            transitionPartyToArena(source, members, nextArena, nextDef);
                        };
                        if (isBossLevel && contInfSpec == null) {
                            // Infinite runs skip the authored biome-boss intro - the
                            // randomized boss announces itself at spawn instead.
                            offerBossIntro(members, biome, transition);
                        } else {
                            transition.run();
                        }
                    } else if (forced != null ? forced.equals("raid") : (raidRoll < raidChance)) {
                        // Raid - defend the villagers from pillager waves on a plains field.
                        ld.levelsSinceLastEvent = 0;
                        data.markDirty();
                        pendingNextLevelDef = nextLevelDef;
                        pendingBiome = biome;
                        var raidDef = TrialChamberEvent.generateRaid(
                            Math.max(0, biomeOrdinal), ngPlusLevel);
                        pendingEventBiomeOrdinal = Math.max(0, biomeOrdinal);
                        // lastFightWasTrial is set in finalizeShinyEvent only when the
                        // party actually enters the raid; setting it here leaked the flag
                        // on a decline and suppressed the next real advanceBiomeRun().
                        offerRaid(savedPlayer, savedMembers, raidDef);
                    } else if (forced != null ? forced.equals("ominous_trial") : (eventRoll < cOminous && biomeOrdinal >= 10)) {
                        // Ominous Trial Chamber (late game only). Party-vote dialogue -
                        // tie or majority Accept enters the trial; majority Decline skips
                        // straight to the next level.
                        ld.levelsSinceLastEvent = 0;
                        data.markDirty();
                        pendingNextLevelDef = nextLevelDef;
                        pendingBiome = biome;
                        trialChamberLevelDef = RandomEvents.generateOminousTrial(biomeOrdinal, ngPlusLevel);
                        trialChamberPending = true;
                        offerTrialVote(savedPlayer, partyMsg, true);
                    } else if (forced != null ? forced.equals("trial") : (eventRoll < cTrial)) {
                        // Trial Chamber. Party-vote dialogue -tie or majority Enter takes
                        // the trial; majority Pass skips straight to the next level.
                        ld.levelsSinceLastEvent = 0;
                        data.markDirty();
                        pendingNextLevelDef = nextLevelDef;
                        pendingBiome = biome;
                        trialChamberLevelDef = TrialChamberEvent.generate(biomeOrdinal, ngPlusLevel);
                        trialChamberPending = true;
                        offerTrialVote(savedPlayer, partyMsg, false);
                    } else if (forced != null ? forced.equals(PillageEvents.BASTILLE_KEY)
                            : false) {
                        // The Bastille (It Takes a Pillage). Reached ONLY through a
                        // Bastille Map - it never rolls naturally; the map is the key.
                        ld.levelsSinceLastEvent = 0;
                        data.markDirty();
                        pendingNextLevelDef = nextLevelDef;
                        pendingBiome = biome;
                        pendingEventBiomeOrdinal = Math.max(0, biomeOrdinal);
                        offerAcceptDeclineFight(savedPlayer, savedMembers,
                            PillageEvents.generateBastille(biomeOrdinal, ngPlusLevel),
                            "craftics:bastille_intro");
                    } else if (forced != null ? forced.equals(PillageEvents.CAMP_KEY)
                            : (com.crackedgames.craftics.compat.takesapillage.TakesAPillageCompat
                                    .isLoaded()
                                && campRoll < PillageEvents.CAMP_CHANCE)) {
                        // Pillager Camp (It Takes a Pillage): its own roll, like the raid's,
                        // so it exists only when the mod does and never eats a built-in
                        // event's odds.
                        ld.levelsSinceLastEvent = 0;
                        data.markDirty();
                        pendingNextLevelDef = nextLevelDef;
                        pendingBiome = biome;
                        pendingEventBiomeOrdinal = Math.max(0, biomeOrdinal);
                        offerAcceptDeclineFight(savedPlayer, savedMembers,
                            PillageEvents.generateCamp(biomeOrdinal, ngPlusLevel),
                            "craftics:pillager_camp_intro");
                    } else if (forced != null ? forced.equals("ambush") : (eventRoll < cAmbush)) {
                        // Shiny on the ground. The party votes Take vs Leave; majority Yes
                        // resolves 50/50 into a reward for one Yes voter or this ambush
                        // combat. Majority No walks past safely. Ties trigger the ambush.
                        // (Config name kept as "ambush" so the chance / force_event key
                        // does not break.)
                        ld.levelsSinceLastEvent = 0; // reset pity timer on event
                        data.markDirty();
                        pendingNextLevelDef = nextLevelDef;
                        pendingBiome = biome;
                        var ambushDef = RandomEvents.generateAmbush(biome.biomeId, biomeOrdinal,
                            biome.getBiomeLevelIndex(globalLevel), ngPlusLevel);
                        pendingEventBiomeOrdinal = Math.max(0, biomeOrdinal);
                        // lastFightWasTrial is set in finalizeShinyEvent only when the
                        // ambush combat actually starts; a Leave vote or the reward
                        // outcome must not leave the flag armed.
                        offerShinyChoice(savedPlayer, savedMembers, ambushDef);
                    } else if (forced != null ? forced.equals("shrine") : (eventRoll < cShrine)) {
                        // Shrine of Fortune -interactive room
                        ld.levelsSinceLastEvent = 0; // reset pity timer on event
                        data.markDirty();
                        pendingNextLevelDef = nextLevelDef;
                        pendingBiome = biome;
                        offerShrine(savedPlayer, biomeOrdinal);
                    } else if (forced != null ? forced.equals("traveler") : (eventRoll < cTraveler)) {
                        // Wounded Traveler -interactive room
                        ld.levelsSinceLastEvent = 0; // reset pity timer on event
                        data.markDirty();
                        pendingNextLevelDef = nextLevelDef;
                        pendingBiome = biome;
                        offerTraveler(savedPlayer, biomeOrdinal);
                    } else if (forced != null ? forced.equals("vault") : (eventRoll < cVault)) {
                        // Treasure Vault -interactive room
                        ld.levelsSinceLastEvent = 0; // reset pity timer on event
                        data.markDirty();
                        pendingNextLevelDef = nextLevelDef;
                        pendingBiome = biome;
                        offerVault(savedPlayer, biomeOrdinal);
                    } else if (forced != null ? forced.equals("dig_site") : (eventRoll < cDigSite)) {
                        // Dig Site
                        ld.levelsSinceLastEvent = 0; // reset pity timer on event
                        data.markDirty();
                        pendingNextLevelDef = nextLevelDef;
                        pendingBiome = biome;
                        offerDigSite(savedPlayer, biome);
                    } else if (forced != null ? forced.equals("enchanter") : (eventRoll < cEnchanter)) {
                        // Enchanter -enhance a weapon or armor piece
                        ld.levelsSinceLastEvent = 0; // reset pity timer on event
                        data.markDirty();
                        pendingNextLevelDef = nextLevelDef;
                        pendingBiome = biome;
                        offerEnchanter(savedPlayer);
                    } else if (forced != null ? (forced.equals("trader") || forced.equals("piglin_barter")) : (eventRoll < cTrader)) {
                        // Configurable chance: Wandering Trader (Overworld/End) or Piglin Barter (Nether)
                        ld.levelsSinceLastEvent = 0; // reset pity timer on event
                        data.markDirty();
                        pendingNextLevelDef = nextLevelDef;
                        pendingBiome = biome;
                        if (isNetherRegion) {
                            offerPiglinBarter(savedPlayer, biome, biomeOrdinal);
                        } else {
                            offerTrader(savedPlayer, biome, biomeOrdinal);
                        }
                    } else {
                        // Check addon-registered events from EventRegistry
                        String addonEventId = null;
                        if (forced != null) {
                            // Forced event that didn't match any built-in -check addon registry
                            addonEventId = forced;
                        } else {
                            // Roll against addon event probabilities. Apply the same
                            // pity-timer boost as built-in events so addons scale
                            // proportionally as pity ramps.
                            float addonRoll = eventRoll - cTrader; // remaining probability space
                            if (addonRoll >= 0) {
                                for (var addonEvent : com.crackedgames.craftics.api.registry.EventRegistry.getAll()) {
                                    // Skip built-in events that are also mirrored into the registry
                                    // with a null handler (VanillaContent registers them for listing
                                    // only). They are driven by the inline cascade above, not here;
                                    // counting them would consume the addon probability space and
                                    // starve real addon events (e.g. the Artifacts campsite), which
                                    // sit later in the iteration order and could never be reached.
                                    if (addonEvent.handler() == null) continue;
                                    if (biomeOrdinal >= addonEvent.minBiomeOrdinal()) {
                                        addonRoll -= addonEvent.probability() * pityScale;
                                        if (addonRoll < 0) {
                                            addonEventId = addonEvent.id();
                                            break;
                                        }
                                    }
                                }
                            }
                        }

                        if (addonEventId != null) {
                            var addonEvent = com.crackedgames.craftics.api.registry.EventRegistry.getById(addonEventId);
                            if (addonEvent != null && addonEvent.handler() != null) {
                                ld.levelsSinceLastEvent = 0;
                                data.markDirty();
                                pendingNextLevelDef = nextLevelDef;
                                pendingBiome = biome;

                                if (addonEvent.isChoiceEvent()) {
                                    // Choice event: show accept/decline prompt, execute handler only on accept
                                    pendingAddonEventId = addonEventId;
                                    pendingAddonEventMembers = savedMembers;
                                    pendingAddonEventManager = savedEventManager;
                                    final ServerPlayerEntity addonLeader = savedPlayer;
                                    final int addonLeaderEmeralds =
                                        data.getPlayerData(addonLeader.getUuid()).emeralds;
                                    final String addonLabel = addonEvent.displayName();
                                    Runnable addonPrompt = leaderPromptOrAutoDecline(addonLeader,
                                        // levelIndex -1 marks this an event prompt, which renders
                                        // Accept/Decline rather than the Go Home button, so the
                                        // infinite flag is never read on this path.
                                        new VictoryChoicePayload(0, addonLeaderEmeralds, false,
                                            addonLabel, -1, false, true, false,
                                            new java.util.ArrayList<>()));
                                    if (addonEvent.introLines() != null && !addonEvent.introLines().isEmpty()) {
                                        // Opt-in narrator intro -gate the leader's Accept/Decline
                                        // screen behind an all-dismiss dialogue.
                                        var addonIntro = new com.crackedgames.craftics.combat.dialogue.DialogueDefinition(
                                            "craftics:addon_intro_" + addonEventId.replace(':', '_'),
                                            "", "addon_intro",
                                            addonEvent.introLines(), java.util.List.of());
                                        offerIntroNarrator(savedMembers, addonIntro,
                                            "§e§l✦ " + addonLabel + " ✦", addonPrompt);
                                    } else {
                                        // Legacy: chat preface + immediate leader prompt.
                                        for (ServerPlayerEntity p : partyMsg) {
                                            sendMessageTo(p, "§e§l" + addonLabel + " discovered!");
                                        }
                                        addonPrompt.run();
                                    }
                                } else {
                                    // Non-choice event: execute immediately, then auto-continue
                                    try {
                                        addonEvent.handler().execute(savedMembers, world, savedEventManager);
                                    } catch (Exception addonEx) {
                                        CrafticsMod.LOGGER.error("Addon event '{}' handler threw exception", addonEventId, addonEx);
                                    }
                                    // Auto-continue - into whatever the handler asked for, which
                                    // may be a level of its own rather than the one that was queued.
                                    var forcedNext = consumeAddonNextLevel(savedEventManager, nextLevelDef);
                                    pendingNextLevelDef = null;
                                    pendingBiome = null;
                                    // A handler that started its own fight has already moved the
                                    // party; building a second arena on top of it would tear that
                                    // down and drop everyone into the wrong level.
                                    if (!active) {
                                        spawnSavedPets();
                                        GridArena nextArena = buildArena(world, forcedNext);
                                        transitionPartyToArena(savedPlayer, savedMembers, nextArena, forcedNext);
                                    }
                                }
                            } else {
                                // Unknown addon event ID or no handler -skip to next level
                                ld.levelsSinceLastEvent++;
                                data.markDirty();
                                GridArena nextArena = buildArena(world, nextLevelDef);
                                transitionPartyToArena(savedPlayer, savedMembers, nextArena, nextLevelDef);
                            }
                        } else {
                            // No event -start next level immediately
                            // Increment pity counter since no event occurred
                            ld.levelsSinceLastEvent++;
                            data.markDirty();
                            GridArena nextArena = buildArena(world, nextLevelDef);
                            transitionPartyToArena(savedPlayer, savedMembers, nextArena, nextLevelDef);
                        }
                    }
                }
            }
            } catch (Exception ex) {
                CrafticsMod.LOGGER.error("Failed to start next level, sending player home", ex);
                sendMessageTo(savedPlayer, "§cError loading next level! Returning to hub...");
                ld.endBiomeRun();
                ld.inCombat = false;
                data.markDirty();
                teleportToHub(savedPlayer);
                // Send all party members home on error, not just the leader
                for (ServerPlayerEntity m : savedMembers) {
                    if (!m.getUuid().equals(savedPlayer.getUuid())) {
                        teleportToHub(m);
                    }
                    ServerPlayNetworking.send(m, new ExitCombatPayload(false));
                }
            }
        }
    }

    // ---- Forced event (debug command) ----
    private String forcedNextEvent = null;
    public void setForcedNextEvent(String event) { this.forcedNextEvent = event; }
    public String getForcedNextEvent() { return forcedNextEvent; }

    // ---- Addon event (pending choice) ----
    private String pendingAddonEventId = null;
    private List<ServerPlayerEntity> pendingAddonEventMembers = null;
    private EventManager pendingAddonEventManager = null;

    // ---- Trial Chamber event ----
    private boolean trialChamberPending = false;
    private com.crackedgames.craftics.level.LevelDefinition trialChamberLevelDef;
    private boolean lastFightWasTrial = false;

    /**
     * Drop every event-interlude leftover. Called whenever a run ends (biome complete or
     * go-home): this per-leader CombatManager instance outlives the run, and a stale
     * pendingNextLevelDef + lastFightWasTrial pair would reroute the next run's first
     * Continue into the OLD biome's stashed level - the "wrong biome, then ping-pong" bug.
     */
    /**
     * Drop everything an interlude was holding, including any transition it had queued.
     *
     * <p>The queued transition is the part that used to be missed. {@code eventReturnTicks} is
     * a countdown in {@link #tick()} that ends by pulling the whole party into
     * {@code pendingNextLevelDef}, and it ran outside the active-combat guard on purpose -
     * events live between levels. Nothing cancelled it. Not this method, not
     * {@code endCombat()}, not a boss win, not going home: an armed transition outlived the
     * run that armed it and kept counting.
     *
     * <p>Nulling the level definition alone is not enough, because it is not the only thing
     * that writes one. The victory path sets it for the next level, an addon can set it
     * through {@code setPendingNextLevel}, and starting a fresh run on this same per-leader
     * instance sets it again. Any of those refills the slot the stale timer is about to read,
     * and the party gets moved into a level nobody chose - which is exactly what "we did not
     * press continue" looks like from the floor.
     *
     * <p>So the countdown is cancelled with the state it belongs to.
     */
    private void clearEventInterludeState() {
        pendingNextLevelDef = null;
        pendingBiome = null;
        pendingEventBiomeOrdinal = 0;
        lastFightWasTrial = false;
        trialChamberPending = false;
        trialChamberLevelDef = null;
        eventReturnTicks = 0;
        eventReturnLeader = null;
    }

    // ---- Addon-event public hooks ----
    /**
     * The biome the player is currently progressing through, captured at level
     * transition. Used by addon event handlers (e.g. Artifacts mimic encounter)
     * to read floor blocks, boss stats, etc.
     */
    public com.crackedgames.craftics.level.BiomeTemplate getPendingBiome() { return pendingBiome; }

    /** Position of the current biome in the dimension path (0 = first biome). */
    public int getCurrentBiomeOrdinal() { return currentBiomeOrdinal; }

    /** The level definition that will be loaded next, if any. */
    public com.crackedgames.craftics.level.LevelDefinition getPendingNextLevel() { return pendingNextLevelDef; }
    public void setPendingNextLevel(com.crackedgames.craftics.level.LevelDefinition def) { this.pendingNextLevelDef = def; }
    public void setPendingBiome(com.crackedgames.craftics.level.BiomeTemplate b) { this.pendingBiome = b; }

    /**
     * Build an arena for the given level definition and transition the given leader's
     * party into combat there. Used by addon event handlers that need to launch an
     * encounter outside the normal "next biome level" pipeline.
     * <p>
     * Accepts {@code leader} explicitly because at addon-event-acceptance time
     * {@code this.player} may have been cleared by a prior endCombat call. The
     * leader passed in by the event handler is always the current party leader.
     */
    public void startCustomCombat(ServerPlayerEntity leader, com.crackedgames.craftics.level.LevelDefinition def) {
        if (def == null || leader == null) {
            CrafticsMod.LOGGER.warn("startCustomCombat: ignoring null def or leader (def={}, leader={})",
                def, leader);
            return;
        }
        ServerWorld w = (ServerWorld) leader.getEntityWorld();
        spawnSavedPets();
        GridArena custom = buildArena(w, def);
        if (custom == null) {
            CrafticsMod.LOGGER.error("startCustomCombat: buildArena returned null for level '{}' -aborting",
                def.getName());
            return;
        }
        CrafticsMod.LOGGER.info("startCustomCombat: transitioning party into '{}' at {} ({}x{})",
            def.getName(), custom.getOrigin(), custom.getWidth(), custom.getHeight());
        transitionPartyToArena(leader, custom, def);
        // Clear the pending-next-level so the post-choice auto-continue doesn't also
        // try to load the normal next biome level on top of this custom combat.
        this.pendingNextLevelDef = null;
        this.pendingBiome = null;
    }

    /** @deprecated use {@link #startCustomCombat(ServerPlayerEntity, com.crackedgames.craftics.level.LevelDefinition)} */
    @Deprecated
    public void startCustomCombat(com.crackedgames.craftics.level.LevelDefinition def) {
        startCustomCombat(this.player, def);
    }

